const C: Record<string, string[]> = {"Mishneh Torah, Admission into the Sanctuary 4":["טָמֵא שֶׁעָבַד בַּמִּקְדָּשׁ חִלֵּל עֲבוֹדָתוֹ וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם עַל עֲבוֹדָתוֹ אַף עַל פִּי שֶׁלֹּא שָׁהָה שָׁם שֶׁנֶּאֱמַר (ויקרא כב ב) \"וְיִנָּזְרוּ מִקָּדְשֵׁי בְנֵי יִשְׂרָאֵל וְלֹא יְחַלְּלוּ אֶת שֵׁם קָדְשִׁי\" הֲרֵי זוֹ אַזְהָרָה לְעוֹבֵד בְּטֻמְאָה. וּלְהַלָּן הוּא אוֹמֵר (ויקרא כב ט) \"וּמֵתוּ בוֹ כִּי יְחַלְּלֻהוּ\". מָה חִלּוּל הָאָמוּר [שָׁם] חַיָּב מִיתָה בִּידֵי שָׁמַיִם אַף כָּאן מִיתָה בִּידֵי שָׁמַיִם. וְכָל לָאו שֶׁחַיָּבִין עָלָיו מִיתָה בִּידֵי שָׁמַיִם לוֹקִין עָלָיו:","אַף עַל פִּי שֶׁאִם עָבַד בְּטֻמְאָה אֵינוֹ חַיָּב בְּבֵית דִּין אֶלָּא מַלְקוֹת אֶחָיו הַכֹּהֲנִים לֹא הָיוּ מְבִיאִין אוֹתוֹ לְבֵית דִּין אֶלָּא מוֹצִיאִין אוֹתוֹ לַחוּץ וּפוֹצְעִין אֶת מֹחוֹ וְאֵין מְמַחִין עֲלֵיהֶן בְּכָךְ:","וְהֵיאַךְ אֶפְשָׁר לוֹ לַעֲבֹד וְלֹא יִשְׁהֶה עַד שֶׁלֹּא יִתְחַיֵּב כָּרֵת אֶלָּא מִיתָה בִּידֵי שָׁמַיִם בִּלְבַד. כְּגוֹן שֶׁנִּטְמָא בָּעֲזָרָה וְיָצָא בִּקְצָרָה וּבִיצִיאָתוֹ הָיָה צִנּוֹר בְּיָדוֹ וְהָפַךְ בּוֹ אֵיבָר עַל הָאֵשׁ בַּמִּזְבֵּחַ וְקֵרֵב שְׂרֵפָתוֹ שֶׁכָּל קֵרוּב עֲבוֹדָה הֲרֵי הוּא כַּעֲבוֹדָה:","וְכֵן טָמֵא שֶׁטָּבַל וְעָבַד קֹדֶם שֶׁיַּעֲרִיב שִׁמְשׁוֹ עֲבוֹדָתוֹ פְּסוּלָה וְחַיָּב מִיתָה בִּידֵי שָׁמַיִם שֶׁנֶּאֱמַר (ויקרא כא ו) \"וְלֹא יְחַלְּלוּ שֵׁם אֱלֹהֵיהֶם\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לִטְבוּל יוֹם שֶׁעָבַד שֶׁעֲדַיִן טָמֵא הוּא שֶׁנֶּאֱמַר (ויקרא כב ז) \"וּבָא הַשֶּׁמֶשׁ וְטָהֵר\" מִכְּלַל שֶׁעֲדַיִן לֹא טָהֵר. אֲבָל מְחֻסַּר כִּפּוּרִים שֶׁעָבַד אַף עַל פִּי שֶׁעֲבוֹדָתוֹ פְּסוּלָה וְחִלֵּל הֲרֵי זֶה פָּטוּר:","וּמִנַּיִן שֶׁעֲבוֹדָתוֹ פְּסוּלָה שֶׁנֶּאֱמַר (ויקרא יב ח) \"וְכִפֶּר עָלֶיהָ הַכֹּהֵן וְטָהֵרָה\". מִכְּלַל שֶׁעֲדַיִן לֹא נִגְמְרָה טָהֳרָתָהּ. וְהוּא הַדִּין לְכָל מְחֻסְּרֵי כִּפּוּרִים:","כֹּהֵן שֶׁעָבַד וְאַחַר כָּךְ נוֹדַע שֶׁהָיָה טָמֵא. אִם הִיא טֻמְאָה יְדוּעָה כָּל הַקָּרְבָּנוֹת שֶׁהִקְרִיב פְּסוּלִין שֶׁהֲרֵי עֲבוֹדָתוֹ חֻלִּין. וְאִם הִיא טֻמְאַת הַתְּהוֹם הַצִּיץ מְרַצֶּה. וְכָל הַקָּרְבָּנוֹת שֶׁהִקְרִיב נִרְצוּ. וַאֲפִלּוּ נוֹדַע לוֹ שֶׁהוּא טָמֵא קֹדֶם שֶׁיִּזְרֹק הַדָּם וְזָרַק הֻרְצָה. שֶׁהַצִּיץ מְרַצֶּה עַל טֻמְאַת הַתְּהוֹם אַף עַל פִּי שֶׁהוּא מֵזִיד. וּכְבָר בֵּאַרְנוּ טֻמְאַת הַתְּהוֹם בִּנְזִירוּת:","וְכֵן הַצִּיץ מְרַצֶּה עַל טֻמְאַת דְּבָרִים הַקְּרֵבִין שֶׁנֶּאֱמַר (שמות כח לח) \"וְהָיָה עַל מֵצַח אַהֲרֹן וְנָשָׂא אַהֲרֹן אֶת עֲוֹן הַקֳדָשִׁים\". אֲבָל אֵינוֹ מְרַצֶּה עַל טֻמְאַת הַנֶּאֱכָלִין. וְלֹא עַל טֻמְאַת הָאָדָם שֶׁנִּטְמָא בְּטֻמְאָה יְדוּעָה. אֶלָּא אִם כֵּן הָיְתָה הַטֻּמְאָה הַדְּחוּיָה בַּצִּבּוּר שֶׁהַצִּיץ מְרַצֶּה עָלֶיהָ:","וְאֵין הַצִּיץ מְרַצֶּה אֶלָּא בִּזְמַן שֶׁהוּא עַל מִצְחוֹ שֶׁנֶּאֱמַר (שמות כח לח) \"וְהָיָה עַל מִצְחוֹ תָּמִיד לְרָצוֹן לָהֶם לִפְנֵי ה'\":","כָּל קָרְבָּן שֶׁאֵין קָבוּעַ לוֹ זְמַן אֵינוֹ דּוֹחֶה לֹא אֶת הַשַּׁבָּת וְלֹא אֶת הַטֻּמְאָה. שֶׁאִם לֹא יַקְרִיב הַיּוֹם יִקָּרֵב לְמָחָר וּלְמָחֳרַת מָחָר. וְכָל קָרְבָּן שֶׁקָּבוּעַ לוֹ זְמַן בֵּין קָרְבַּן צִבּוּר בֵּין קָרְבַּן יָחִיד דּוֹחֶה אֶת הַשַּׁבָּת וְדוֹחֶה אֶת הַטֻּמְאָה. וְלֹא כָּל הַטֻּמְאוֹת הוּא דּוֹחֶה אֶלָּא טֻמְאַת הַמֵּת לְבַדָּהּ:","כָּל קָרְבְּנוֹת הַצִּבּוּר קָבוּעַ זְמַנָּם. לְפִיכָךְ כֻּלָּן דּוֹחִין אֶת הַשַּׁבָּת וְאֶת טֻמְאַת הַמֵּת:","וְכָל קָרְבָּן מֵהֶן שֶׁקָּרֵב בְּטֻמְאָה אֵינוֹ נֶאֱכָל. אֶלָּא מַקְטִירִין מִמֶּנּוּ דְּבָרִים הָרְאוּיִין לְהַקְטָרָה וְהַשְּׁאָר הָרָאוּי לַאֲכִילָה נִשְׂרָף כִּשְׁאָר קָדָשִׁים שֶׁנִּטְמְאוּ:","כֵּיצַד דּוֹחֶה אֶת הַטֻּמְאָה. הִגִּיעַ זְמַנּוֹ שֶׁל אוֹתוֹ קָרְבָּן וְהָיוּ רֹב הַקָּהָל שֶׁמַּקְרִיבִין אוֹתוֹ טְמֵאִין לְמֵת. אוֹ שֶׁהָיוּ הַקָּהָל טְהוֹרִים וְהָיוּ הַכֹּהֲנִים הַמַּקְרִיבִין טְמֵאִים לְמֵת. אוֹ שֶׁהָיוּ אֵלּוּ וְאֵלּוּ טְהוֹרִין וְהָיוּ כְּלֵי הַשָּׁרֵת טְמֵאִים לְמֵת. הֲרֵי זֶה יֵעָשֶׂה בְּטֻמְאָה וְיִתְעַסְּקוּ בּוֹ הַטְּמֵאִים וְהַטְּהוֹרִים כְּאֶחָד וְיִכָּנְסוּ כֻּלָּן לָעֲזָרָה. אֲבָל הַטְּמֵאִים בְּטֻמְאָה אַחֶרֶת כְּגוֹן זָבִין וְזָבוֹת וְנִדּוֹת [וְיוֹלְדוֹת] וּטְמֵאֵי שֶׁרֶץ וּנְבֵלָה וְכַיּוֹצֵא בָּהֶן. לֹא יִתְעַסְּקוּ וְלֹא יִכָּנְסוּ לָעֲזָרָה וְאַף עַל פִּי שֶׁנַּעֲשָׂה בְּטֻמְאָה. וְאִם עָבְרוּ וְעָשׂוּ אוֹ נִכְנְסוּ לָעֲזָרָה חַיָּבִין כָּרֵת עַל הַבִּיאָה וּמִיתָה עַל הָעֲבוֹדָה. שֶׁלֹּא נִדְחֵית אֶלָּא טֻמְאַת הַמֵּת בִּלְבַד:","וּפֶסַח שֶׁבָּא בְּטֻמְאָה וְדָחֲקוּ טְמֵאֵי מֵת וְנִכְנְסוּ לַהֵיכָל פְּטוּרִין. אַף עַל פִּי שֶׁלֹּא הֻתְּרוּ אֶלָּא לָעֲזָרָה. הוֹאִיל וְאֵין אֲנִי קוֹרֵא בָּהֶם (במדבר ה ג) \"אֶל מִחוּץ לַמַּחֲנֶה תְּשַׁלְּחוּם\" הֲרֵי אֵלּוּ פְּטוּרִין:","הָיוּ מִקְצָת בֵּית אָב טְמֵאִים וּמִקְצָתָם טְהוֹרִים אַף עַל פִּי שֶׁרֻבָּן טְמֵאֵי מֵת לֹא יַקְרִיבוּ אֶלָּא הַטְּהוֹרִים. הָיָה כָּל בֵּית הָאָב טְמֵאֵי מֵת יָבִיאוּ בֵּית אָב אַחֵר. הָיְתָה כָּל הַמִּשְׁמָרָה טְמֵאֵי מֵת מַחֲזִירִין עַל מִשְׁמָרָה אַחֶרֶת. אִם הָיוּ רֹב הַכֹּהֲנִים הַנִּכְנָסִין שָׁם בִּירוּשָׁלַיִם בַּזְּמַן הַקָּבוּעַ טְמֵאִין יַעֲשׂוּ בְּטֻמְאָה:","וּמִפְּנֵי מָה מַחֲזִירִין עַל הַטָּהוֹר מִבֵּית אָב אַחֵר. מִפְּנֵי שֶׁהַטֻּמְאָה לֹא הֻתְּרָה בַּצִּבּוּר אֶלָּא בְּאִסּוּרָהּ עוֹמֶדֶת וּדְחוּיָה הִיא עַתָּה מִפְּנֵי הַדְּחָק. וְאֵין דּוֹחִין כָּל דָּבָר הַנִּדְחֶה אֶלָּא בְּמָקוֹם שֶׁאִי אֶפְשָׁר. וּמִפְּנֵי זֶה צְרִיכָה צִיץ לְרַצּוֹת עָלֶיהָ:","וּמִנַּיִן שֶׁטֻּמְאַת מֵת דְּחוּיָה בַּצִּבּוּר שֶׁנֶּאֱמַר (במדבר ט ו) \"וַיְהִי אֲנָשִׁים אֲשֶׁר הָיוּ טְמֵאִים לְנֶפֶשׁ אָדָם\". כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה שֶׁאֲנָשִׁים יְחִידִים הֵם שֶׁיִּדָּחוּ לְפֶסַח שֵׁנִי אִם הָיוּ טְמֵאִים. אֲבָל צִבּוּר שֶׁהָיוּ טְמֵאֵי מֵת אֵינָן נִדְחִין אֶלָּא הַטֻּמְאָה תִּדָּחֶה וְיַעֲשׂוּ פֶּסַח בְּטֻמְאָה. וְהוּא הַדִּין לְכָל קָרְבָּן שֶׁקָּבוּעַ לוֹ זְמַן כְּפֶסַח שֶׁהוּא דּוֹחֶה אֶת הַטֻּמְאָה:","וַהֲרֵי הַדָּבָר מְפֹרָשׁ בַּכְּתוּבִים שֶׁנֶּאֱמַר שָׁם (דברי הימים ב ל יז) \"כִּי רַבַּת בַּקָּהָל אֲשֶׁר לֹא הִתְקַדָּשׁוּ וְהַלְוִיִּם עַל שְׁחִיטַת הַפְּסָחִים לְכל לֹא טָהוֹר\" [לְהַקְדִּישׁ לַה'] (דברי הימים ב ל יח) \"כִּי מַרְבִּית הָעָם רַבַּת מֵאֶפְרַיִם וּמְנַשֶּׁה יִשָּׂשכָר וּזְבֻלוּן לֹא הִטֶּהָרוּ\". וּמַהוּ זֶה שֶׁנֶּאֱמַר (דברי הימים ב ל יח) \"כִּי אָכְלוּ אֶת הַפֶּסַח בְּלֹא כַכָּתוּב\" מִפְּנֵי שֶׁעִבְּרוּ אוֹתָהּ הַשָּׁנָה מִפְּנֵי הַטֻּמְאָה שֶׁנֶּאֱמַר (דברי הימים ב ל ב) \"וַיִּוָּעַץ הַמֶּלֶךְ וְשָׂרָיו וְכָל הַקָּהָל בִּירוּשָׁלָםִ לַעֲשׂוֹת הַפֶּסַח בַּחֹדֶשׁ הַשֵּׁנִי\" (דברי הימים ב ל ג) \"כִּי לֹא יָכְלוּ לַעֲשֹׂתוֹ בָּעֵת הַהִיא כִּי הַכֹּהֲנִים לֹא הִתְקַדְּשׁוּ לְמַדַּי\". וּכְבָר בֵּאַרְנוּ בְּקִדּוּשׁ הַחֹדֶשׁ שֶׁאֵין מְעַבְּרִין אֶת הַשָּׁנָה לְכַתְּחִלָּה מִפְּנֵי הַטֻּמְאָה:","וְעוֹד אַחֶרֶת הָיְתָה שָׁם בְּאוֹתָהּ הַשָּׁנָה. שֶׁעִבֵּר חִזְקִיָּה הַמֶּלֶךְ אֶת הַשָּׁנָה בְּיוֹם שְׁלֹשִׁים שֶׁל אֲדָר שֶׁרָאוּי לִהְיוֹת רֹאשׁ חֹדֶשׁ נִיסָן וְעָשָׂה אוֹתוֹ הַחֹדֶשׁ אֲדָר שֵׁנִי וְלֹא הוֹדוּ לוֹ חֲכָמִים שֶׁאֵין מְעַבְּרִין בְּיוֹם זֶה כְּמוֹ שֶׁבֵּאַרְנוּ בְּקִדּוּשׁ הַחֹדֶשׁ. וּמִפְּנֵי דְּבָרִים אֵלּוּ שֶׁעָשָׂה שֶׁלֹּא כַּהֲלָכָה נֶאֱמַר (דברי הימים ב ל יח) \"כִּי אָכְלוּ אֶת הַפֶּסַח בְּלֹא כַכָּתוּב\". וּבִקֵּשׁ רַחֲמִים עַל עַצְמוֹ וְעַל הַחֲכָמִים שֶׁהִסְכִּימוּ עַל מַעֲשָׂיו שֶׁנֶּאֱמַר (דברי הימים ב ל יח) \"כִּי הִתְפַּלֵּל יְחִזְקִיָּהוּ עֲלֵיהֶם לֵאמֹר ה' הַטּוֹב יְכַפֵּר בְּעַד\" וְנֶאֱמַר (דברי הימים ב ל כ) \"וַיִּשְׁמַע ה' אֶל יְחִזְקִיָּהוּ וַיִּרְפָּא אֶת הָעָם\" שֶׁנִּרְצָה קָרְבָּנָם:"],"Mishneh Torah, Agents and Partners 6":["שְׁנַּיִם שֶׁהֵן נוֹשְׂאִין וְנוֹתְנִין בְּמָמוֹן הַשֻּׁתָּפוּת אַף עַל פִּי שֶׁהַמָּמוֹן שֶׁל אֶחָד מֵהֶן הֲרֵי זוֹ נִקְרֵאת שֻׁתָּפוּת וְאִם פָּחֲתוּ אוֹ הוֹתִירוּ הֲרֵי הוּא לָאֶמְצַע. וְיֵשׁ לָהֶם לְהַתְנוֹת בַּשָּׂכָר וּבַהֶפְסֵד כָּל מַה שֶּׁיִּרְצוּ כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אִם הָיָה הָאֶחָד בִּלְבַד הוּא שֶׁנּוֹשֵׂא וְנוֹתֵן בְּמָמוֹן הַשִּׁתּוּף אַף עַל פִּי שֶׁהַמָּמוֹן מִשֶּׁל שְׁנֵיהֶם הֲרֵי זוֹ הַשֻּׁתָּפוּת נִקְרֵאת עֵסֶק וְזֶה הַנּוֹשֵׂא וְנוֹתֵן נִקְרָא מִתְעַסֵּק שֶׁהֲרֵי הוּא לְבַדּוֹ מִתְעַסֵּק בְּמַשָּׂא וּמַתָּן וְשֻׁתָּפוֹ שֶׁאֵינוֹ נוֹשֵׂא וְנוֹתֵן נִקְרָא בַּעַל הַמָּעוֹת:","תִּקְּנוּ חֲכָמִים שֶׁכָּל הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ לְהִתְעַסֵּק בָּהֶן יִהְיֶה חֲצִי הַמָּמוֹן בְּתוֹרַת הַלְוָאָה וַהֲרֵי הַמִּתְעַסֵּק חַיָּב בְּאַחֲרָיוּתוֹ אַף עַל פִּי שֶׁאָבַד בְּאֹנֶס וְהַחֵצִי הָאַחֵר בְּתוֹרַת פִּקָּדוֹן וַהֲרֵי הוּא בְּאַחֲרָיוּת בַּעַל הַמָּעוֹת. וְאִם נִגְנַב אוֹ אָבַד הַחֵצִי שֶׁל פִּקָּדוֹן אֵין הַמִּתְעַסֵּק חַיָּב לְשַׁלֵּם וּלְפִיכָךְ יִהְיֶה שְׂכַר זוֹ הַחֵצִי אִם הִרְוִיחַ שֶׁל בַּעַל הַמָּעוֹת. וּלְפִי תַּקָּנָה זוֹ אִי אֶפְשָׁר שֶׁיִּהְיֶה הַשָּׂכָר אוֹ הַהֶפְסֵד שֶׁל כָּל הַמָּמוֹן לָאֶמְצַע בְּשָׁוֶה שֶׁאִם אַתָּה אוֹמֵר כֵּן נִמְצָא בַּעַל הַמָּמוֹן נוֹטֵל שְׂכַר חֲצִי מְעוֹתָיו שֶׁהֵן פִּקָּדוֹן וְאֵינוֹ עוֹשֶׂה כְּלוּם אֶלָּא זֶה הַמִּתְעַסֵּק טוֹרֵחַ לוֹ בַּחֲצִי שֶׁל פִּקָּדוֹן מִפְּנֵי מְעוֹתָיו שֶׁהִלְוָהוּ וְנִמְצָא בָּאִין לִידֵי אֲבַק רִבִּית. וְהֵיאַךְ יַעֲשׂוּ אִם רוֹצֶה לִהְיוֹת הַשָּׂכָר אוֹ הַהֶפְסֵד לָאֶמְצַע בְּשָׁוֶה יִתֵּן לַמִּתְעַסֵּק שְׂכָרוֹ שֶׁבְּכָל יוֹם וְיוֹם מִימֵי הַשֻּׁתָּפוּת כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה שֶׁבָּטֵל מִמֶּנָּה. וְאִם הָיָה לוֹ עֵסֶק אַחֵר כָּל שֶׁהוּא לְהִתְעַסֵּק בּוֹ עִם מְעוֹתָיו שֶׁל זֶה אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר שֶׁל כָּל יוֹם וְיוֹם אֶלָּא אֲפִלּוּ הֶעֱלָה לוֹ דִּינָר בְּכָל יְמֵי הַשֻּׁתָּפוּת דַּיּוֹ וְאִם פָּחֲתוּ אוֹ הוֹתִירוּ יִהְיֶה לָאֶמְצַע בְּשָׁוֶה. וְכֵן אִם אָמַר לוֹ כָּל הָרֶוַח יִהְיֶה לְךָ שְׁלִישׁוֹ אוֹ עֲשִׂירִיתוֹ בִּשְׂכָרְךָ הוֹאִיל וְיֵשׁ לוֹ עֵסֶק אַחֵר הֲרֵי זֶה מֻתָּר. וְאִם הִפְסִידוּ יַפְסִיד מֶחֱצָה. וְאִם הָיָה זֶה הַמִּתְעַסֵּק אֲרִיסוֹ וְהָיָה לוֹ עֵסֶק אַחֵר אֵינוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר אַחֵר כְּלָל שֶׁהָאָרִיס מְשֻׁעְבָּד הוּא לְבַעַל הַשָּׂדֶה:","וְעוֹד תִּקְּנוּ חֲכָמִים שֶׁכָּל הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ לְהִתְעַסֵּק בָּהֶן וּפָחֲתוּ אוֹ הוֹתִירוּ וְלֹא רָצָה לִתֵּן לוֹ שְׂכַר עֲמָלוֹ בְּכָל יוֹם וְלֹא הִתְנוּ בֵּינֵיהֶן שׁוּם תְּנַאי שֶׁיִּהְיֶה שְׂכַר הַמִּתְעַסֵּק בְּאוֹתוֹ חֲצִי שֶׁל פִּקָּדוֹן שְׁלִישׁ רֶוַח הַפִּקָּדוֹן שֶׁהוּא שְׁתוּת רֶוַח כָּל הַמָּמוֹן. לְפִיכָךְ אִם הִרְוִיחוּ יִטּל הַמִּתְעַסֵּק שְׁנֵי שְׁלִישֵׁי הָרֶוַח חֲצִי הָרֶוַח שֶׁל חֲצִי הַמָּעוֹת שֶׁהֵן מִלְוֶה וּשְׁתוּת הָרֶוַח בְּשָׂכָר שֶׁנִּתְעַסֵּק בַּפִּקָּדוֹן. נִמְצָא הַכּל שְׁנֵי שְׁלִישֵׁי הָרֶוַח. וְיִטּל בַּעַל הַמָּעוֹת שְׁלִישׁ הָרֶוַח. וְאִם פָּחֲתוּ יַפְסִיד הַמִּתְעַסֵּק שְׁלִישׁ הַפְּחָת שֶׁהֲרֵי הוּא חַיָּב בַּחֲצִי הַפְּחָת מִפְּנֵי שֶׁחֲצִי הַמָּעוֹת מִלְוֶה וְיֵשׁ לוֹ שְׁתוּת בִּשְׂכָרוֹ בְּאוֹתוֹ הַחֵצִי שֶׁל פִּקָּדוֹן וְנִמְצָא שֶׁנִּשְׁאַר עָלָיו מִן הַפְּחָת שְׁלִישׁוֹ וּבַעַל הַמָּעוֹת יַפְסִיד שְׁנֵי שְׁלִישֵׁי הַפְּחָת:","יֵשׁ מִי שֶׁטּוֹעֶה וְאוֹמֵר שֶׁהַנּוֹתֵן עֵסֶק סְתָם אִם יִהְיֶה שָׁם שָׂכָר יִטּל הַמִּתְעַסֵּק חֶצְיוֹ וְאִם הָיָה שָׁם הֶפְסֵד יַפְסִיד שְׁלִישׁ. וְאֵין הַדָּבָר כֵּן אֶלָּא אִם כֵּן הִתְנוּ עַל דָּבָר זֶה בְּפֵרוּשׁ. וְכֵן אִם הִתְנוּ שֶׁיַּפְסִיד הַמִּתְעַסֵּק מֶחֱצָה וְאִם יִהְיֶה שָׁם שָׂכָר יִטּל שְׁנֵי שְׁלִישֵׁי הָרֶוַח הֲרֵי זֶה מֻתָּר. וְכֵן אִם הִתְנוּ שֶׁאִם יִהְיֶה שָׁם שָׂכָר יִטּל הַמִּתְעַסֵּק תְּשִׁיעִיתוֹ וְאִם יִהְיֶה שָׁם הֶפְסֵד יַפְסִיד עֲשִׂירִיתוֹ הוֹאִיל וְהִתְנוּ שֶׁיִּהְיֶה רֶוַח הַמִּתְעַסֵּק יוֹתֵר עַל הֶפְסֵדוֹ תְּנָאוֹ קַיָּם וְתוֹסֶפֶת זוֹ כְּנֶגֶד עֲמָלוֹ. וְרַבּוֹתַי הוֹרוּ שֶׁאֵין הַתְּנַאי זֶה מוֹעִיל אֶלָּא אִם כֵּן הָיָה לַמִּתְעַסֵּק עֵסֶק אַחֵר. אֲבָל אִם אֵין לוֹ עֵסֶק אַחֵר צָרִיךְ שֶׁיְּהֵא שְׂכַר הַמִּתְעַסֵּק יֶתֶר עַל הֶפְסֵדוֹ בִּשְׁתוּת כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁזֶּה דָּבָר אָסוּר הוּא וְאֵין הַתְּנַאי מוֹעִיל בּוֹ. וְלֹא יֵרָאֶה לִי זֶה:","הוֹרוּ רַבּוֹתַי שֶׁאִם הִתְנוּ שֶׁיִּטּל הַמִּתְעַסֵּק שְׁלֹשָׁה חֲלָקִים מֵהַשָּׂכָר וּבַעַל הַמָּעוֹת רְבִיעַ הַשָּׂכָר נִמְצָא רְבִיעַ הַמָּעוֹת בִּלְבַד בְּתוֹרַת פִּקָּדוֹן וּשְׁלֹשָׁה רְבִיעִים בְּתוֹרַת הַלְוָאָה. לְפִיכָךְ אִם הָיָה שָׁם הֶפְסֵד יַפְסִיד הַמִּתְעַסֵּק שְׁלֹשָׁה רְבִיעֵי הֶפְסֵד פָּחוֹת שְׁלִישׁ הָרְבִיעַ וְיַפְסִיד בַּעַל הַמָּעוֹת רְבִיעַ וּשְׁלִישׁ רְבִיעַ שֶׁהוּא שְׁלִישׁ כָּל הַהֶפְסֵד. כֵּיצַד. נָתַן לוֹ מֵאָה דִּינָרִים עַל תְּנַאי זֶה וְחָסְרוּ אַרְבָּעָה וְעֶשְׂרִים בַּעַל הַמָּעוֹת מַפְסִיד שְׁמֹנָה וְהַמִּתְעַסֵּק מְשַׁלֵּם שִׁשָּׁה עָשָׂר. וְעַל דֶּרֶךְ זוֹ לְעוֹלָם כָּל חֵלֶק שֶׁיֵּשׁ לְבַעַל הַמָּעוֹת בַּשָּׂכָר אִם יִהְיֶה שָׁם רֶוַח נוֹטֵל כְּמוֹ שֶׁהִתְנוּ וְאִם יִהְיֶה שָׁם הֶפְסֵד יַפְסִיד אוֹתוֹ הַחֵלֶק וְתוֹסֶפֶת שְׁלִישׁוֹ. נִמְצֵאתָ לָמֵד לְפִי מִדָּה זוֹ שֶׁאִם הִתְנוּ שֶׁיִּטּל הַמִּתְעַסֵּק רְבִיעַ הַשָּׂכָר אִם פָּחַת לֹא יְשַׁלֵּם הַמִּתְעַסֵּק כְּלוּם שֶׁהֲרֵי רְבִיעַ הַהֶפְסֵד שֶׁהוּא חַיָּב לְשַׁלֵּם מִפְּנֵי הַמִּלְוֶה יֵשׁ לוֹ כְּנֶגְדּוֹ שְׁלִישׁ מַה שֶּׁיִּטּל בַּעַל הַמָּעוֹת שֶׁהוּא רְבִיעַ וְנִמְצָא זֶה כְּנֶגֶד זֶה. וְכֵן אִם הִתְנוּ עַל הַפְּחָת וְלֹא הִזְכִּירוּ הָרֶוַח אִם פָּחֲתוּ פִּחֵת הַמִּתְעַסֵּק כְּפִי מַה שֶּׁהִתְנוּ וְאִם הוֹסִיפוּ נוֹטֵל הַמִּתְעַסֵּק כְּמוֹ אוֹתוֹ הַחֵלֶק שֶׁהָיָה מַפְסִיד וְתוֹסֶפֶת שְׁלִישׁ מַה שֶּׁנָּטַל בַּעַל הַמָּעוֹת. כֵּיצַד. הִתְנוּ שֶׁאִם הָיָה שָׁם הֶפְסֵד יִפְחֹת הַמִּתְעַסֵּק רְבִיעַ וְהִפְחִיתוּ מְשַׁלֵּם רְבִיעַ הַפְּחָת וְאִם הוֹתִירוּ נוֹטֵל מֶחֱצָה. וְאַף עַל פִּי שֶׁדְּבָרִים אֵלּוּ שֶׁהוֹרוּ דִּבְרֵי טַעַם הֵם אִם תֵּלֵךְ עַל דֶּרֶךְ זוֹ שֶׁמָּא הַמִּתְעַסֵּק אֶפְשָׁר שֶׁיִּפְחֹת וְיִטּל שָׂכָר. כֵּיצַד. כְּגוֹן שֶׁהִתְנָה עִמּוֹ שֶׁיִּטּל הַמִּתְעַסֵּק אֶחָד מִשִּׁבְעָה בַּשָּׂכָר וּפָחֲתוּ נִמְצָא נוֹטֵל הַמִּתְעַסֵּק אֶחָד מִשִּׁבְעָה יָתֵר עַל זֶה הַהֶפְסֵד. כֵּיצַד. כְּגוֹן שֶׁפָּחֲתוּ שִׁבְעָה דִּינָרִים הֲרֵי הַמִּתְעַסֵּק אוֹמֵר לוֹ אֲנִי חַיָּב לְךָ דִּינָר אֶחָד כְּפִי הַתְּנַאי וְאַתָּה חַיָּב לְשַׁלֵּם לִי שְׁנַיִם שֶׁהֵן שְׁלִישׁ חֵלֶק הַפִּקָּדוֹן נִמְצָא בַּעַל הַמָּעוֹת חַיָּב לִתֵּן לוֹ דִּינָר בִּשְׂכָר שֶׁהִפְסִיד שִׁבְעָה וְאִלּוּ הִפְסִיד אַרְבָּעָה עָשָׂר הָיָה חַיָּב בַּעַל הַמָּעוֹת לִתֵּן לוֹ שְׁנֵי דִּינָרִין וְזֶה תֵּימָה גָּדוֹל וְדָבָר שֶׁאֵין הַדַּעַת סוֹבֶלֶת אוֹתוֹ וְאֵין זֶה אֶצְלִי אֶלָּא כְּמוֹ דִּבְרֵי הַחֲלוֹם. אֲבָל הַדֶּרֶךְ וְהַדִּין הָאֱמֶת שֶׁיֵּרָאֶה לִי שֶׁכָּל שֶׁיַּרְוִיחַ הַמִּתְעַסֵּק אִם יִהְיֶה שָׁם הֶפְסֵד יַפְסִיד שְׁנֵי שְׁלִישֵׁי הַחֵלֶק שֶׁהָיָה מַרְוִיחַ וְכֵן אִם הִתְנוּ עַל הַהֶפְסֵד וְהִרְוִיחוּ יִטּל כְּמוֹ אוֹתוֹ הַחֵלֶק שֶׁהָיָה מַפְסִיד וְתוֹסֶפֶת שְׁלִישׁ חֵלֶק חֲבֵרוֹ. נִמְצֵאתָ אַתָּה אוֹמֵר לְפִי מִדָּה זוֹ שֶׁאִם הִתְנוּ שֶׁיִּטּל הַמִּתְעַסֵּק רְבִיעַ הַשָּׂכָר וְהִפְסִיד הֲרֵי זֶה מְשַׁלֵּם שְׁתוּת וְאִם הִתְנוּ שֶׁיַּפְסִיד רְבִיעַ וְהִרְוִיחַ נוֹטֵל מֶחֱצָה. וְעַל דֶּרֶךְ זֶה לֹא תִּמְצָא תֵּימָה וְיֵצֵא הַדִּין בְּקַו הַצֶּדֶק:"],"Mishneh Torah, Blessings 1":["מִצְוַת עֲשֵׂה מִן הַתּוֹרָה לְבָרֵךְ אַחַר אֲכִילַת מָזוֹן שֶׁנֶּאֱמַר (דברים ח י) ״וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ אֶת יְיָ׳‎ אֱלֹהֶיךָ״. וְאֵינוֹ חַיָּב מִן הַתּוֹרָה אֶלָּא אִם כֵּן שָׂבַע שֶׁנֶּאֱמַר וְאָכַלְתָּ וְשָׂבָעְתָּ וּבֵרַכְתָּ. וּמִדִּבְרֵי סוֹפְרִים אָכַל אֲפִלּוּ כְּזַיִת מְבָרֵךְ אַחֲרָיו:","וּמִדִּבְרֵי סוֹפְרִים לְבָרֵךְ עַל כָּל מַאֲכָל תְּחִלָּה וְאַחַר כָּךְ יֵהָנֶה מִמֶּנּוּ. וַאֲפִלּוּ נִתְכַּוֵּן לֶאֱכל אוֹ לִשְׁתּוֹת כָּל שֶׁהוּא מְבָרֵךְ וְאַחַר כָּךְ יֵהָנֶה. וְכֵן אִם הֵרִיחַ רֵיחַ טוֹב מְבָרֵךְ וְאַחַר כָּךְ יֵהָנֶה מִמֶּנּוּ. וְכָל הַנֶּהֱנֶה בְּלֹא בְּרָכָה מָעַל. וְכֵן מִדִּבְרֵי סוֹפְרִים לְבָרֵךְ אַחַר כָּל מַה שֶּׁיֹּאכַל וְכָל מַה שֶּׁיִּשְׁתֶּה. וְהוּא שֶׁיִּשְׁתֶּה רְבִיעִית וְהוּא שֶׁיֹּאכַל כְּזַיִת. וּמַטְעֶמֶת אֵינָהּ צְרִיכָה בְּרָכָה לֹא לְפָנֶיהָ וְלֹא לְאַחֲרֶיהָ עַד רְבִיעִית:","וּכְשֵׁם שֶׁמְּבָרְכִין עַל הַהֲנָיָה כָּךְ מְבָרְכִין עַל כָּל מִצְוָה וּמִצְוָה וְאַחַר כָּךְ יַעֲשֶׂה אוֹתָהּ. וּבְרָכוֹת רַבּוֹת תִּקְּנוּ חֲכָמִים דֶּרֶךְ שֶׁבַח וְהוֹדָיָה וְדֶרֶךְ בַּקָּשָׁה כְּדֵי לִזְכֹּר אֶת הַבּוֹרֵא תָּמִיד אַף עַל פִּי שֶׁלֹּא נֶהֱנָה וְלֹא עָשָׂה מִצְוָה:","נִמְצְאוּ כָּל הַבְּרָכוֹת כֻּלָּן שְׁלֹשָׁה מִינִים. בִּרְכוֹת הֲנָיָה. וּבִרְכוֹת מִצְוֹת. וּבִרְכוֹת הוֹדָאָה שֶׁהֵן דֶּרֶךְ שֶׁבַח וְהוֹדָיָה וּבַקָּשָׁה כְּדֵי לִזְכֹּר אֶת הַבּוֹרֵא תָּמִיד וּלְיִרְאָה מִמֶּנּוּ:","וְנֹסַח כָּל הַבְּרָכוֹת עֶזְרָא וּבֵית דִּינוֹ תִּקְּנוּם. וְאֵין רָאוּי לְשַׁנּוֹתָם וְלֹא לְהוֹסִיף עַל אַחַת מֵהֶם וְלֹא לִגְרֹעַ מִמֶּנָּה. וְכָל הַמְשַׁנֶּה מִמַּטְבֵּעַ שֶׁטָּבְעוּ חֲכָמִים בַּבְּרָכוֹת אֵינוֹ אֶלָּא טוֹעֶה. וְכָל בְּרָכָה שֶׁאֵין בָּהּ הַזְכָּרַת הַשֵּׁם וּמַלְכוּת אֵינָהּ בְּרָכָה אֶלָּא אִם כֵּן הָיְתָה סְמוּכָה לַחֲבֵרְתָהּ:","וְכָל הַבְּרָכוֹת כֻּלָּן נֶאֱמָרִין בְּכָל לָשׁוֹן וְהוּא שֶׁיֹּאמַר כְּעֵין שֶׁתִּקְּנוּ חֲכָמִים. וְאִם שִׁנָּה אֶת הַמַּטְבֵּעַ הוֹאִיל וְהִזְכִּיר אַזְכָּרָה וּמַלְכוּת וְעִנְיַן הַבְּרָכָה אֲפִלּוּ בִּלְשׁוֹן חֹל יָצָא:","כָּל הַבְּרָכוֹת כֻּלָּן צָרִיךְ שֶׁיַּשְׁמִיעַ לְאָזְנוֹ מַה שֶּׁהוּא אוֹמֵר וְאִם לֹא הִשְׁמִיעַ לְאָזְנוֹ יָצָא בֵּין שֶׁהוֹצִיא בִּשְׂפָתָיו בֵּין שֶׁבֵּרֵךְ בְּלִבּוֹ:","כָּל הַבְּרָכוֹת כֻּלָּן לֹא יַפְסִיק בֵּין הַבְּרָכָה וּבֵין הַדָּבָר שֶׁמְּבָרְכִין עָלָיו בִּדְבָרִים אֲחֵרִים וְאִם הִפְסִיק צָרִיךְ לַחֲזֹר וּלְבָרֵךְ שְׁנִיָּה. וְאִם הִפְסִיק בִּדְבָרִים שֶׁהֵן מֵעִנְיַן דְּבָרִים שֶׁמְּבָרְכִין עָלָיו אֵינוֹ צָרִיךְ לְבָרֵךְ שְׁנִיָּה. כֵּיצַד. כְּגוֹן שֶׁבֵּרֵךְ עַל הַפַּת וְקֹדֶם שֶׁיֹּאכַל אָמַר הָבִיאוּ מֶלַח הָבִיאוּ תַּבְשִׁיל תְּנוּ לִפְלוֹנִי לֶאֱכל תְּנוּ מַאֲכָל לַבְּהֵמָה וְכַיּוֹצֵא בָּאֵלּוּ אֵינוֹ צָרִיךְ לְבָרֵךְ שֵׁנִית. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הַבְּרָכוֹת כֻּלָּם מֻתָּר לְטָמֵא לְבָרֵךְ אוֹתָן. בֵּין שֶׁהָיָה טָמֵא טֻמְאָה שֶׁהוּא יָכוֹל לַעֲלוֹת מִמֶּנָּה בּוֹ בַּיּוֹם. בֵּין טֻמְאָה שֶׁאֵינוֹ יָכוֹל לַעֲלוֹת מִמֶּנָּה בּוֹ בַּיּוֹם. וְאָסוּר לַמְבָרֵךְ לְבָרֵךְ כְּשֶׁהוּא עָרֹם עַד שֶׁיְּכַסֶּה עֶרְוָתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִישׁ אֲבָל בְּאִשָּׁה יוֹשֶׁבֶת וּפָנֶיהָ טוּחוֹת בַּקַּרְקַע וּמְבָרֶכֶת:","כָּל הַבְּרָכוֹת כֻּלָּן אַף עַל פִּי שֶׁבֵּרֵךְ וְיָצָא יְדֵי חוֹבָתוֹ מֻתָּר לוֹ לְבָרֵךְ לַאֲחֵרִים שֶׁלֹּא יָצְאוּ יְדֵי חוֹבָתָן כְּדֵי לְהוֹצִיאָן. חוּץ מִבִּרְכַּת הַהֲנָיָה שֶׁאֵין בָּהּ מִצְוָה שֶׁאֵינוֹ מְבָרֵךְ לַאֲחֵרִים אֶלָּא אִם כֵּן נֶהֱנָה עִמָּהֶן. אֲבָל בִּרְכַּת הַהֲנָיָה שֶׁיֵּשׁ בָּהּ מִצְוָה כְּגוֹן אֲכִילַת מַצָּה בְּלֵילֵי הַפְּסָחִים וְקִדּוּשׁ הַיּוֹם הֲרֵי זֶה מְבָרֵךְ לַאֲחֵרִים וְאוֹכְלִין וְשׁוֹתִים אַף עַל פִּי שֶׁאֵינוֹ אוֹכֵל עִמָּהֶן:","כָּל הַשּׁוֹמֵעַ בְּרָכָה מִן הַבְּרָכוֹת מִתְּחִלָּתָהּ וְעַד סוֹפָהּ וְנִתְכַּוֵּן לָצֵאת בָּהּ יְדֵי חוֹבָתוֹ יָצָא וְאַף עַל פִּי שֶׁלֹּא עָנָה אָמֵן. וְכָל הָעוֹנֶה אָמֵן אַחַר הַמְבָרֵךְ הֲרֵי זֶה כִּמְבָרֵךְ וְהוּא שֶׁיִּהְיֶה הַמְבָרֵךְ חַיָּב בְּאוֹתָהּ בְּרָכָה. הָיָה הַמְבָרֵךְ חַיָּב מִדִּבְרֵי סוֹפְרִים וְהָעוֹנֶה חַיָּב מִן הַתּוֹרָה לֹא יָצַא יְדֵי חוֹבָתוֹ עַד שֶׁיַּעֲנֶה אוֹ עַד שֶׁיִּשְׁמַע מִמִּי שֶׁהוּא חַיָּב בָּהּ מִן הַתּוֹרָה כָּמוֹהוּ:","רַבִּים שֶׁנִּתְוַעֲדוּ לֶאֱכל פַּת אוֹ לִשְׁתּוֹת יַיִן וּבֵרֵךְ אֶחָד מֵהֶן וְעָנוּ כֻּלָּם אָמֵן הֲרֵי אֵלּוּ מֻתָּרִין לֶאֱכל וְלִשְׁתּוֹת. אֲבָל אִם לֹא נִתְכַּוְּנוּ לֶאֱכל כְּאֶחָד אֶלָּא זֶה בָּא מֵעַצְמוֹ וְזֶה בָּא מֵעַצְמוֹ אַף עַל פִּי שֶׁהֵן אוֹכְלִין מִכִּכָּר אֶחָד כָּל אֶחָד וְאֶחָד מְבָרֵךְ לְעַצְמוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּפַת וְיַיִן בִּלְבַד אֲבָל שְׁאָר אֳכָלִים וּמַשְׁקִין אֵינָן צְרִיכִין הַסִּבָּה אֶלָּא אִם בֵּרֵךְ אֶחָד מֵהֶן וְעָנוּ כֻּלָּן אָמֵן הֲרֵי אֵלּוּ אוֹכְלִים וְשׁוֹתִין. וְאַף עַל פִּי שֶׁלֹּא נִתְכַּוְּנוּ לְהָסֵב כְּאֶחָד:","כָּל הַשּׁוֹמֵעַ אֶחָד מִיִּשְׂרָאֵל מְבָרֵךְ בְּרָכָה מִכָּל הַבְּרָכוֹת כֻּלָּן אַף עַל פִּי שֶׁלֹּא שָׁמַע הַבְּרָכָה כֻּלָּהּ מִתְּחִלָּתָהּ וְעַד סוֹפָהּ וְאַף עַל פִּי שֶׁאֵינוֹ חַיָּב בְּאוֹתָהּ בְּרָכָה חַיָּב לַעֲנוֹת אָמֵן. וְאִם הָיָה הַמְבָרֵךְ גוי אוֹ אֶפִּיקוֹרוֹס אוֹ כּוּתִי אוֹ תִּינוֹק הַמִּתְלַמֵּד אוֹ שֶׁהָיָה גָּדוֹל וְשִׁנָּה מִמַּטְבֵּעַ הַבְּרָכָה אֵין עוֹנִין אַחֲרֵיהֶן אָמֵן:","כָּל הָעוֹנֶה אָמֵן לֹא יַעֲנֶה לֹא אָמֵן חֲטוּפָה וְלֹא אָמֵן קְטוּפָה וְלֹא אָמֵן קְצָרָה וְלֹא אֲרֻכָּה אֶלָּא אָמֵן בֵּינוֹנִית. וְלֹא יַגְבִּיהַּ קוֹלוֹ יוֹתֵר מִן הַמְבָרֵךְ. וְכָל מִי שֶׁלֹּא שָׁמַע אֶת הַבְּרָכָה שֶׁהוּא חַיָּב בָּהּ לֹא יַעֲנֶה אָמֵן בִּכְלַל הָעוֹנִים:","כָּל הַמְבָרֵךְ בְּרָכָה שֶׁאֵינָהּ צְרִיכָה הֲרֵי זֶה נוֹשֵׂא שֵׁם שָׁמַיִם לַשָּׁוְא וַהֲרֵי הוּא כְּנִשְׁבָּע לַשָּׁוְא וְאָסוּר לַעֲנוֹת אַחֲרָיו אָמֵן. הַתִּינוֹקוֹת מְלַמְּדִין אוֹתָן הַבְּרָכוֹת כְּתִקּוּנָן וְאַף עַל פִּי שֶׁהֵן מְבָרְכִין לְבַטָּלָה בִּשְׁעַת לִמּוּד הֲרֵי זֶה מֻתָּר. וְאֵין עוֹנִין אַחֲרֵיהֶן אָמֵן. וְהָעוֹנֶה אַחֲרֵיהֶן אָמֵן לֹא יָצָא יְדֵי חוֹבָתוֹ:","כָּל הָעוֹנֶה אָמֵן אַחַר בִּרְכוֹתָיו הֲרֵי זֶה מְגֻנֶּה. וְהָעוֹנֶה אַחַר בְּרָכָה שֶׁהִיא סוֹף בְּרָכוֹת אַחֲרוֹנוֹת הֲרֵי זֶה מְשֻׁבָּח. כְּגוֹן אַחַר בּוֹנֵה יְרוּשָׁלַיִם בְּבִרְכַּת הַמָּזוֹן וְאַחַר בְּרָכָה אַחֲרוֹנָה שֶׁל קְרִיאַת שְׁמַע שֶׁל עַרְבִית. וְכֵן בְּסוֹף כָּל בְּרָכָה שֶׁהִיא סוֹף בְּרָכוֹת אַחֲרוֹנוֹת עוֹנֶה בָּהּ אָמֵן אַחַר עַצְמוֹ:","וְלָמָּה יַעֲנֶה אָמֵן אַחַר בּוֹנֵה יְרוּשָׁלָיִם וַהֲרֵי אַחֲרֶיהָ בִּרְכַּת הַטּוֹב וְהַמֵּטִיב. מִפְּנֵי שֶׁבְּרָכָה זוֹ בִּימֵי חַכְמֵי מִשְׁנָה תִּקְּנוּהָ וּכְאִלּוּ הִיא תּוֹסֶפֶת. אֲבָל סוֹף עִקַּר הַבְּרָכוֹת שֶׁל בִּרְכַּת הַמָּזוֹן הִיא בּוֹנֵה יְרוּשָׁלַיִם. וְלָמָּה לֹא יַעֲנֶה אָמֵן אַחַר אַהֲבַת עוֹלָם מִפְּנֵי שֶׁהִיא סוֹף בְּרָכוֹת רִאשׁוֹנוֹת שֶׁל קְרִיאַת שְׁמַע, וְכֵן כָּל כַּיּוֹצֵא בָּהּ מִבְּרָכוֹת שֶׁמְּבָרְכִין אוֹתָן תְּחִלָּה לַדָּבָר, כְּגוֹן בְּרָכוֹת שֶׁמְּבָרְכִין לִפְנֵי קְרִיאַת מְגִלָּה וְהַדְלָקַת נֵר חֲנֻכָּה. לְמַעַן לֹא יַפְסִיק בְּאָמֵן בֵּין בְּרָכָה וּבֵין הַדָּבָר שֶׁבֵּרֵךְ עָלָיו:","וְלָמָּה לֹא יַעֲנֶה אָמֵן אַחַר בִּרְכַּת הַפֵּרוֹת וְכַיּוֹצֵא בָּהּ. מִפְּנֵי שֶׁהִיא בְּרָכָה אַחַת וְאֵין עוֹנִין אָמֵן אֶלָּא אַחַר בְּרָכָה אַחֲרוֹנָה שֶׁקָּדְמָה אוֹתָהּ בְּרָכָה אַחֶרֶת אוֹ בְּרָכוֹת כְּגוֹן בִּרְכוֹת הַמֶּלֶךְ וּבִרְכוֹת כֹּהֵן גָּדוֹל וְכַיּוֹצֵא בָּהֶן, לְהוֹדִיעַ שֶׁכְּבָר הִשְׁלִים כָּל בִּרְכוֹתָיו וּלְפִיכָךְ עוֹנֶה אָמֵן:","כָּל הָאוֹכֵל דָּבָר הָאָסוּר בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה אֵינוֹ מְבָרֵךְ עָלָיו לֹא בַּתְּחִלָּה וְלֹא בַּסּוֹף. כֵּיצַד. הֲרֵי שֶׁאָכַל טֶבֶל שֶׁל דִּבְרֵיהֶם אוֹ שֶׁאָכַל מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלוּ תְּרוּמוֹתָיו אוֹ מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ כְּהִלְכָתָן אֵינוֹ מְבָרֵךְ. וְאֵין צָרִיךְ לוֹמַר אִם אָכַל נְבֵלוֹת וּטְרֵפוֹת אוֹ שָׁתָה יֵין נֶסֶךְ וְכַיּוֹצֵא בּוֹ:","אֲבָל אִם אָכַל דְּמַאי אַף עַל פִּי שֶׁאֵינוֹ רָאוּי אֶלָּא לַעֲנִיִּים אוֹ מַעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְּרוּמָתוֹ אַף עַל פִּי שֶׁלֹּא נִטַּל מִמֶּנּוּ חֶשְׁבּוֹן תְּרוּמָה גְּדוֹלָה וְהוּא שֶׁהִקְדִּימוֹ בְּשִׁבֳּלִין, אוֹ מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁנִּפְדּוּ אַף עַל פִּי שֶׁלֹּא נָתַן אֶת הַחֹמֶשׁ. הֲרֵי זֶה מְבָרֵךְ תְּחִלָּה וָסוֹף. וְכֵן כָּל כְּיוֹצֵא בָּהֶן:"],"Mishneh Torah, Borrowing and Deposit 2":["הַשׁוֹאֵל בַּבְּעָלִים אֲפִלּוּ נִגְנַב אוֹ אָבַד בִּפְשִׁיעָה פָּטוּר שֶׁנֶּאֱמַר (שמות כב יד) \"אִם בְּעָלָיו עִמּוֹ לֹא יְשַׁלֵּם\". וּבִלְבַד שֶׁשָּׁאַל הַבְּעָלִים תְּחִלָּה עִם הַחֵפֶץ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֶחָד הַשּׁוֹאֵל אֶת הַבְּעָלִים אוֹ שֶׁשְּׂכָרָן וְאֶחָד שֶׁשּׁוֹאֵל אֶת הַבְּעָלִים לְאוֹתָהּ הַמְּלָאכָה אוֹ שֶׁשְּׁאָלָן וּשְׂכָרָן לִמְלָאכָה אַחֶרֶת אוֹ לְשׁוּם דָּבָר בָּעוֹלָם. אֲפִלּוּ אָמַר לַחֲבֵרוֹ הַשְׁקֵנִי מַיִם וְשָׁאַל מִמֶּנּוּ בְּהֶמְתּוֹ וְהִשְׁקָהוּ וְנָתַן לוֹ אֶת הַבְּהֵמָה הֲרֵי זוֹ שְׁאֵלָה בִּבְעָלִים וּפָטוּר. מָשַׁךְ אֶת הַבְּהֵמָה בַּתְּחִלָּה וְאַחַר כָּךְ הִשְׁקָהוּ אֵינָהּ שְׁאֵלָה בִּבְעָלִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִשְׁאִיל בְּהֶמְתּוֹ אוֹ הִשְׂכִּירָהּ לְמַשּׂוֹי וְיָצָא עִמָּהּ לְסָעֳדָהּ עִם הַשּׁוֹאֵל אוֹ הַשּׂוֹכֵר וְלִטְעֹן עִמּוֹ בְּמַשָּׂאוֹ הֲרֵי זוֹ שְׁמִירָה בַּבְּעָלִים. וְאִם יָצָא לְבַקֵּר הַמַּשּׂאוֹי בִּלְבַד וְלִרְאוֹת שֶׁלֹּא יִטְעֲנוּ עָלֶיהָ יֶתֶר מִן הָרָאוּי אֵינָהּ שְׁמִירָה בַּבְּעָלִים:","מְלַמֵּד תִּינוֹקוֹת. וְהַנּוֹטֵעַ לִבְנֵי הַמְּדִינָה. וְהַמַּקִּיז לָהֶם אֶת הַדָּם. וְהַסּוֹפֵר שֶׁלָּהֶן. כָּל אֶחָד מֵאֵלּוּ וְכַיּוֹצֵא בָּהֶן בַּיּוֹם שֶׁהוּא יוֹשֵׁב בּוֹ לַעֲסֹק בִּמְלַאכְתָּן אִם הִשְׁאִיל אוֹ הִשְׂכִּיר לְאֶחָד מֵאֵלּוּ שֶׁהוּא עוֹסֵק בִּמְלַאכְתָּם הֲרֵי זוֹ שְׁמִירָה בַּבְּעָלִים וַאֲפִלּוּ פָּשַׁע בָּהּ הַשּׁוֹמֵר פָּטוּר. אֲבָל הוּא שֶׁשָּׁאַל אוֹ שֶׁשָּׂכַר מֵהֶן חַיָּב שֶׁאֵינָן שְׁאוּלִין לוֹ:","הָרַב שֶׁהוּא מַקְרִיא בִּרְצוֹנוֹ לַתַּלְמִידִים בְּכָל עֵת שֶׁיִּרְצֶה וְאֵיזוֹ מַסֶּכְתָּא שֶׁיִּרְצֶה וְהֵם הָיוּ קְבוּעִים לָבוֹא תָּמִיד וְנִשְׁמַט לָהֶן מִמַּסֶּכְתָּא לְמַסֶּכְתָּא הֲרֵי הֵן שְׁאוּלִין אֶצְלוֹ וְאֵין הוּא שָׁאוּל לָהֶם. וּבְיוֹם הַפֶּרֶק שֶׁהַכּל בָּאִין לִשְׁמֹעַ עִנְיַן אוֹתוֹ מוֹעֵד הֲרֵי הוּא שָׁאוּל לָהֶם וְהֵם אֵינָן שְׁאוּלִין לוֹ:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וְהִשָּׁאֵל עִם פָּרָתִי אֵינָהּ שְׁאֵלָה בַּבְּעָלִים שֶׁנֶּאֱמַר (שמות כב יד) \"אִם בְּעָלָיו עִמּוֹ לֹא יְשַׁלֵּם\" הַבְּעָלִים עַצְמָן לֹא שָׁלִיחַ. אָמַר לְעַבְדּוֹ הַכְּנַעֲנִי צֵא וְהִשָּׁאֵל עִם פָּרָתִי הֲרֵי זוֹ שְׁאֵלָה בַּבְּעָלִים שֶׁיַּד הָעֶבֶד כְּיַד רַבּוֹ. נִשְׁאַל הָעֶבֶד עִמָּהּ שֶׁלֹּא מִדַּעַת רַבּוֹ אֵינָהּ שְׁאֵלָה בַּבְּעָלִים:","הַשּׁוֹאֵל מִן הָאִשָּׁה וְנִשְׁאַל לוֹ בַּעְלָהּ אֵינָהּ שְׁאֵלָה בַּבְּעָלִים שֶׁקִּנְיַן פֵּרוֹת אֵינוֹ כְּקִנְיַן הַגּוּף וְאֵין לַבַּעַל אֶלָּא פֵּרוֹת:","הַשּׁוֹאֵל מֵאִשְׁתּוֹ אוֹ שֻׁתָּפִין שֶּׁשָּׁאֲלוּ זֶה מִזֶּה הֲרֵי זוֹ שְׁאֵלָה בַּבְּעָלִים. וְאִם אָמַר הַשֻׁתָּף לַחֲבֵרוֹ הַשְׁאִילֵנִי הַיּוֹם וְאַשְׁאִילְךָ לְמָחָר אֵינָהּ שְׁאֵלָה בַּבְּעָלִים:","שָׁאַל מִן הַשֻּׁתָּפִין וְנִשְׁאַל לוֹ אֶחָד מֵהֶן וְכֵן הַשֻּׁתָּפִין שֶׁשָּׁאֲלוּ וְנִשְׁאַל לְאֶחָד מֵהֶן הֲרֵי זֶה סָפֵק אִם הִיא שְׁאֵלָה בַּבְּעָלִים אִם אֵינָהּ. לְפִיכָךְ אִם מֵתָה אֵינוֹ מְשַׁלֵּם. וְאִם תָּפְסוּ הַבְּעָלִים אֵין מוֹצִיאִין מִיָּדָם. פָּשַׁע בָּהּ הֲרֵי זֶה מְשַׁלֵּם:","הַשּׁוֹאֵל אֶת הַבְּהֵמָה בַּבְּעָלִים לְרָבְעָהּ אוֹ לְהַרְאוֹת בָּהּ אוֹ לַעֲשׂוֹת בָּהּ פָּחוֹת מִשְּׁוֵה פְּרוּטָה אוֹ שֶׁשָּׁאַל שְׁתֵּי פָּרוֹת לַעֲשׂוֹת בָּהֶן שְׁוֵה פְּרוּטָה הֲרֵי כָּל אֵלּוּ סְפֵק שְׁאֵלָה בַּבְּעָלִים:","שְׁאָלָהּ בַּבְּעָלִים וּשְׂכָרָהּ שֶׁלֹּא בַּבְּעָלִים פָּטוּר שֶׁהַשְּׂכִירוּת תָּלוּי בַּשְּׁאֵלָה. אֲבָל אִם שְׂכָרָהּ בַּבְּעָלִים וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בַּבְּעָלִים אוֹ שֶׁשְּׁאָלָה בַּבְּעָלִים וְחָזַר וּשְׂכָרָהּ שֶׁלֹּא בַּבְּעָלִים וְחָזַר וּשְׁאָלָהּ (שֶׁלֹּא) בַּבְּעָלִים אוֹ שֶׁשְּׂכָרָהּ בַּבְּעָלִים וְחָזַר וּשְׁאָלָהּ שֶׁלֹּא בַּבְּעָלִים וְחָזַר וּשְׂכָרָהּ (שֶׁלֹּא) בַּבְּעָלִים כָּל אֵלּוּ סְפֵק שְׁמִירָה בַּבְּעָלִים הוּא:","אִשָּׁה שֶׁשָּׁאֲלָה וְאַחַר כָּךְ נִשֵּׂאת הֲרֵי הַבַּעַל כְּלוֹקֵחַ מִמֶּנָּה וְאֵינוֹ לֹא שׁוֹמֵר שָׂכָר וְלֹא שׁוֹאֵל. לְפִיכָךְ אִם הָיְתָה דְּבַר הַשְּׁאֵלָה בְּהֵמָה וּמֵתָה הַבַּעַל פָּטוּר אַף עַל פִּי שֶׁהוּא מִשְׁתַּמֵּשׁ בָּהּ כָּל יְמֵי שְׁאֵלָתָהּ אֲפִלּוּ פָּשַׁע מִפְּנֵי שֶׁהוּא כְּלוֹקֵחַ וְהָאִשָּׁה חַיֶּבֶת לְשַׁלֵּם כְּשֶׁיִּהְיֶה לָהּ מָמוֹן. וְאִם הוֹדִיעָה אֶת בַּעְלָהּ שֶׁהִיא שְׁאוּלָה הֲרֵי זֶה נִכְנָס תַּחְתֶּיהָ. כָּל שֶׁאָמַרְנוּ שֶׁהִיא שְׁאֵלָה בַּבְּעָלִים כָּךְ אִם הָיָה שׂוֹכֵר אוֹ נוֹשֵׂא שָׂכָר הֲרֵי הִיא שְׂכִירוּת בַּבְּעָלִים וּפָטוּר. וְכָל שֶׁאֵינָהּ שְׁאֵלָה בַּבְּעָלִים כָּךְ אֵינָהּ שְׂכִירוּת בַּבְּעָלִים. וְכָל שֶׁהוּא סָפֵק בִּשְׁאֵלָה כָּךְ הוּא סָפֵק בִּשְׂכִירוּת:"],"Mishneh Torah, Creditor and Debtor 11":["הַמַּלְוֶה אֶת חֲבֵרוֹ בִּפני עֵדִים אוֹ שֶׁאָמַר לְעֵדִים הֱיוּ עָלַי עֵדִים שֶׁאֲנִי חַיָּב לָזֶה מָנֶה אוֹ אַתֶּם עֵדַי שֶׁאֲנִי חַיָּב לָזֶה מָנֶה. זוֹ נִקְרֵאת מִלְוֶה עַל פֶּה וְאֵין צָרִיךְ לְפָרְעוֹ בְּעֵדִים. לְפִיכָךְ אִם טָעַן וְאָמַר אַחַר כָּךְ פָּרַעְתִּי נִשְׁבָּע הֶסֵּת וְנִפְטָר. אֲבָל הַמַּלְוֶה אֶת חֲבֵרוֹ בִּשְׁטָר צָרִיךְ לְפָרְעוֹ בְּעֵדִים לְפִיכָךְ אִם טָעַן וְאָמַר פָּרַעְתִּי שְׁטָר זֶה אֵינוֹ נֶאֱמָן אֶלָּא אוֹמְרִים לוֹ אוֹ הָבֵא עֵדִים אוֹ עֲמֹד וְשַׁלֵּם לוֹ חוֹבוֹ. לְפִיכָךְ הָאוֹמֵר לְעֵדִים הֱיוּ עָלַי עֵדִים שֶׁאֲנִי חַיָּב לָזֶה מָנֶה אֵין כּוֹתְבִין עֵדוּתָן וְנוֹתְנִין לַמַּלְוֶה. שֶׁלֹּא יַחֲזִירוֹ לַמַּלְוֶה עַל פִּי עֵדוּת בִּשְׁטָר עַד שֶׁיֹּאמַר לָהֶן הַלּוֶֹה כִּתְבוּ שְׁטָר וְחִתְמוּ וּתְנוּ לוֹ. אַף עַל פִּי שֶׁאָמַר לָהֶן כָּךְ צְרִיכִין לְהִמָּלֵךְ בּוֹ אַחַר שֶׁחָתְמוּ בַּשְּׁטָר וְאַחַר כָּךְ נוֹתְנִין הַשְּׁטָר בְּיַד הַמַּלְוֶה. קָנוּ מִיָּדוֹ שֶׁהוּא חַיָּב לוֹ מָנֶה הֲרֵי אֵלּוּ כּוֹתְבִין וְנוֹתְנִין אַף עַל פִּי שֶׁלֹּא אָמַר לָהֶן כְּתֹבוּ שֶׁסְּתָם קִנְיָן לִכְתִיבָה עוֹמֵד וְאֵינָן צְרִיכִין לְהִמָּלֵךְ בּוֹ:","לוֶֹה שֶׁכָּתַב שְׁטָר בִּכְתַב יָדוֹ וְהֵעִיד בּוֹ עֵדִים וּנְתָנוֹ לַמַּלְוֶה הֲרֵי זֶה שְׁטָר כָּשֵׁר. וְכֵן אִם כָּתַב שְׁטָר אַף עַל פִּי שֶׁאֵין בּוֹ עֵדִים וּנְתָנוֹ לַמַּלְוֶה בִּפְנֵי עֵדִים הֲרֵי זוֹ מִלְוֶה בִּשְׁטָר. וְהוּא שֶׁיִּהְיֶה כְּתָב שֶׁאֵינוֹ יָכוֹל לְהִזְדַּיֵּף וְיִקְרְאוּ אוֹתוֹ הָעֵדִים שֶׁנִּמְסַר בִּפְנֵיהֶם. וְיֵשׁ מִן הַגְּאוֹנִים שֶׁהוֹרָה שֶׁצָּרִיךְ לוֹמַר לָעֵדִים שֶׁמָּסְרוּ בִּפְנֵיהֶם חִתְמוּ וְהָעִידוּ שֶׁנִּמְסַר בִּפְנֵיכֶם:","הוֹצִיא עָלָיו כְּתַב יָדוֹ שֶׁהוּא חַיָּב לוֹ וְאֵין שָׁם עֵדִים אַף עַל פִּי שֶׁהֻחְזַק כְּתַב יָדוֹ בְּבֵית דִּין הֲרֵי זֶה כְּמִלְוֶה עַל פֶּה לְכָל דָּבָר. וְאִם טָעַן שֶׁפָּרַע נִשְׁבָּע הֶסֵּת וְנִפְטָר וְאֵינוֹ גּוֹבֶה בִּכְתָב זֶה לֹא מִן הַיּוֹרְשִׁין וְלֹא מִן הַלָּקוֹחוֹת:","כָּל מִלְוֶה בִּשְׁטָר גּוֹבֶה אוֹתָהּ מִן הַיּוֹרְשִׁין וּמִן הַלָּקוֹחוֹת כְּמוֹ שֶׁיִּתְבָּאֵר. וּמִלְוֶה עַל פֶּה גּוֹבֶה אוֹתָהּ מִן הַיּוֹרְשִׁין וְאֵינוֹ גּוֹבֶה אוֹתָהּ מִן הַלָּקוֹחוֹת לְפִי שֶׁאֵין לָהּ קוֹל לְפִיכָךְ לֹא יִטְרֹף בָּהּ. אֲבָל מִלְוֶה שֶׁבִּשְׁטָר קוֹל יֵשׁ לָהּ וְהַלּוֹקֵחַ הִפְסִיד עַל עַצְמוֹ שֶׁלֹּא שָׁאַל עַד שֶׁיָּדַע שֶׁנְּכָסָיו שֶׁל זֶה מְשֻׁעְבָּדִין בַּמִּלְוֶה שֶׁעָלָיו. שֶׁכָּל נִכְסֵי הַלּוֶֹה תַּחַת שִׁעְבּוּד הַמַּלְוֶה מִן הַתּוֹרָה:","הַמּוֹכֵר שָׂדֵהוּ בְּעֵדִים וְיָצָאת מִתַּחַת יְדֵי הַלּוֹקֵחַ אַף עַל פִּי שֶׁאֵין שָׁם שְׁטָר בְּיַד הַלּוֹקֵחַ הֲרֵי זֶה חוֹזֵר וְטוֹרֵף מִנְּכָסִים מְשֻׁעְבָּדִים כְּמוֹ שֶׁיִּתְבָּאֵר. שֶׁכָּל הַמּוֹכֵר בְּפַרְהֶסְיָא מוֹכֵר וְקוֹל יֵשׁ לוֹ:","אֵין הַהַלְוָאָה שֶׁעַל פֶּה נִגְבֵּית מִן הַיּוֹרְשִׁין אֶלָּא בְּאֶחָד מִשְּׁלֹשָׁה דְּבָרִים אֵלּוּ. כְּשֶׁחַיָּב מוֹדֶה בָּהּ וְצִוָּה בְּחָלְיוֹ שֶׁיֵּשׁ לִפְלוֹנִי עָלָיו חוֹב עֲדַיִן. אוֹ שֶׁהָיְתָה הַהַלְוָאָה לִזְמַן וְלֹא הִגִּיעַ זְמַן לְפָרְעָהּ וַחֲזָקָה הִיא שֶׁאֵין אָדָם פּוֹרֵעַ בְּתוֹךְ זְמַנּוֹ. אוֹ שֶׁנִּדּוּהוּ עַד שֶׁיִּתֵּן וּמֵת בְּנִדּוּיוֹ. כָּל אֵלּוּ גּוֹבִין מִן הַיּוֹרְשִׁין בְּלֹא שְׁבוּעָה. אֲבָל אִם בָּאוּ עֵדִים שֶׁהָיָה חַיָּב לָזֶה מָנֶה אוֹ בְּפָנֵינוּ הִלְוָהוּ אֵינוֹ גּוֹבֶה מִן הַיּוֹרֵשׁ כְּלוּם שֶׁמָּא פְּרָעוֹ שֶׁהַמַּלְוֶה אֶת חֲבֵרוֹ בְּעֵדִים אֵין צָרִיךְ לְפָרְעוֹ בְּעֵדִים. וְכֵן אִם מוֹצִיא כְּתַב יַד אֲבִיהֶן שֶׁהוּא חַיָּב לוֹ אֵינוֹ גּוֹבֶה בּוֹ כְּלוּם כְּמוֹ שֶׁבֵּאַרְנוּ:","לוֶֹה שֶׁאֵין לוֹ מִטַּלְטְלִין וְיֵשׁ לוֹ קַרְקַע אִם נוֹדַע לְבֵית דִּין שֶׁתּוֹלֶה מְעוֹתָיו בְּיַד אֲחֵרִים כּוֹפִין אוֹתוֹ לִמְכֹּר וְלִתֵּן לְבַעַל חוֹבוֹ. וְאִם לֹא נוֹדַע לָהֶם דָּבָר זֶה מַחְרִימִין עַל מִי שֶׁיֵּדַע לוֹ מִטַּלְטְלִין וְלֹא יְבִיאֵם. וְאַחַר כָּךְ יוֹרְדִין לְבֵינוֹנִית שֶׁבִּנְכָסָיו וּמַגְבִּין לְבַעַל חוֹבוֹ כְּמוֹ שֶׁיִּתְבָּאֵר. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנִּפְרָעִין מִן הַלּוֶֹה עַצְמוֹ. אֲבָל הַבָּא לִפָּרַע מִן הַיּוֹרֵשׁ בֵּין קָטָן בֵּין גָּדוֹל לֹא יִפָּרַע מִן הַמִּטַּלְטְלִין אֲפִלּוּ הָיוּ מֻפְקָדִין אוֹ מִלְוֶה אֵצֶל אֲחֵרִים. שֶׁהַמִּטַּלְטְלִין אֵינָן תַּחַת שִׁעְבּוּד בַּעַל חוֹב מִן הַתּוֹרָה:","מִצְוָה עַל הַיְתוֹמִין לִפְרֹעַ חוֹב אֲבִיהֶן מִן הַמִּטַּלְטְלִין שֶׁהִנִּיחַ. וְאִם לֹא רָצָה הַיּוֹרֵשׁ לִתֵּן אֵין כּוֹפִין אוֹתוֹ. וְאִם תָּפַס בַּעַל חוֹב מֵחַיִּים גּוֹבֶה מֵהֶן. טָעַן שֶׁמֵּחַיִּים תְּפָסָן וְהַיּוֹרֵשׁ טָעַן שֶׁאַחַר מִיתָה תָּפַס עַל הַיּוֹרֵשׁ לְהָבִיא רְאָיָה אוֹ יִשָּׁבַע הַמַּלְוֶה שֶׁכָּךְ וְכָךְ הוּא חַיָּב לוֹ וְיָכוֹל לִטְעֹן עַד כְּדֵי דְּמֵיהֶן וְכוֹלֵל בִּשְׁבוּעָתוֹ שֶׁמֵּחַיִּים תָּפַס. הָיוּ הַדְּבָרִים שֶׁתָּפַס שְׁטָרוֹת וְטָעַן שֶׁהֵן מַשְׁכּוֹן בְּיָדוֹ עַל חוֹבוֹ וְשֶׁמֵּחַיִּים תָּפַס. עַל הַמַּלְוֶה לְהָבִיא רְאָיָה שֶׁמֵּחַיִּים תָּפַס. וְאִם לֹא הֵבִיא רְאָיָה יַחְזִיר לַיּוֹרְשִׁים מִפְּנֵי שֶׁאֵינוֹ טוֹעֵן לִקְנוֹת גּוּפָם אֶלָּא לָרְאָיָה שֶׁבָּהֶן:","יְתוֹמִים שֶׁגָּבוּ קַרְקַע בְּחוֹב שֶׁהָיָה לַאֲבִיהֶן אֵצֶל אֲחֵרִים יֵשׁ לְבַעַל חוֹב שֶׁל אֲבִיהֶם לַחְזֹר וְלִגְבּוֹת אוֹתָהּ מֵהֶן שֶׁהֲרֵי קַרְקַע זוֹ שֶׁל אֲבִיהֶם הִיא:","רְאוּבֵן שֶׁמָּכַר שָׂדֶה לְשִׁמְעוֹן בְּאַחֲרָיוּת וְזָקַף שִׁמְעוֹן דְּמֵי הַשָּׂדֶה עָלָיו מִלְוֶה לִרְאוּבֵן וּמֵת רְאוּבֵן וּבָא בַּעַל חוֹב שֶׁל רְאוּבֵן לִטְרֹף מִשִּׁמְעוֹן הַשָּׂדֶה וּפִיְּסוֹ שִׁמְעוֹן בְּמָעוֹת וְהָלַךְ לוֹ. הַדִּין נוֹתֵן שֶׁיָּבוֹאוּ יוֹרְשֵׁי רְאוּבֵן וְיִתְבְּעוּ שִׁמְעוֹן בַּמִּלְוֶה שֶׁזָּקַף עָלָיו שֶׁהֲרֵי אֵינָהּ מְשֻׁעְבֶּדֶת לְבַעַל חוֹב שֶׁל רְאוּבֵן. לְפִיכָךְ אִם הָיָה שִׁמְעוֹן פִּקֵּחַ נוֹתֵן לָהֶן הַקַּרְקַע שֶׁלָּקַח מֵרְאוּבֵן בַּמִּלְוֶה שֶׁזָּקַף עַל עַצְמוֹ וְחוֹזֵר וְטוֹרֵף אוֹתָהּ מֵהֶן מִפְּנֵי הַמָּעוֹת שֶׁנָּתַן לְבַעַל חוֹב שֶׁל רְאוּבֵן כְּדֵי שֶׁלֹּא יִטְרֹף אוֹתָהּ מִמֶּנּוּ שֶׁהֲרֵי בְּאַחֲרָיוּת לְקָחָהּ מֵרְאוּבֵן:","כְּבָר תִּקְּנוּ גְּאוֹנִים הָאַחֲרוֹנִים כֻּלָּם שֶׁיִּהְיֶה בַּעַל חוֹב גּוֹבֶה מִטַּלְטְלִין מִן הַיּוֹרְשִׁין. וְכֵן דָּנִין יִשְׂרָאֵל בְּכָל בֵּית דִּין שֶׁבָּעוֹלָם. אֲבָל בַּמַּעֲרָב הָיוּ כּוֹתְבִין בְּשִׁטְרֵי חוֹבוֹת שֶׁיֵּשׁ לִגְבּוֹת מִן הַקַּרְקַע וּמִן הַמִּטַּלְטְלִין בֵּין בְּחַיָּיו בֵּין אַחַר מוֹתוֹ וְנִמְצָא גּוֹבֶה עַל תְּנַאי זֶה יוֹתֵר מִן הַתַּקָּנָה. וּסְיָג גָּדוֹל עָשׂוּ בַּדָּבָר שֶׁמָּא לֹא יֵדַע הַלּוֶֹה בְּתַקָּנָה זוֹ וְנִמְצָא מָמוֹן יְתוֹמִים יוֹצֵא שֶׁלֹּא כַּדִּין. שֶׁאֵין כֹּחַ בְּתַקָּנַת אַחֲרוֹנִים לְחַיֵּב בָּהּ יְתוֹמִים:"],"Mishneh Torah, Creditor and Debtor 22":["סֵדֶר גְּבִיַּת הַחוֹב כָּךְ הוּא. כְּשֶׁיָּבִיא הַמַּלְוֶה שְׁטָרוֹ לְבֵית דִּין וְיִתְקַיֵּם אוֹמְרִים לַלּוֶֹה שַׁלֵּם. וְאֵין יוֹרְדִין לִנְכָסָיו תְּחִלָּה עַד שֶׁיִּתְבָּעֶנּוּ. וְאִם טָעָה הַדַּיָּן וְהוֹרִיד הַמַּלְוֶה לְנִכְסֵי לוֶֹה קֹדֶם שֶׁיִּתְבָּעֶנּוּ מְסַלְּקִין אוֹתוֹ. אָמַר הַלּוֶֹה הֲרֵינִי מְשַׁלֵּם קִבְעוּ לִי זְמַן כְּדֵי שֶׁאֶלְוֶה מֵאַחֵר אוֹ אֲמַשְׁכֵּן אוֹ אֶמְכֹּר וְאָבִיא הַמָּעוֹת קוֹבְעִין לוֹ זְמַן שְׁלֹשִׁים יוֹם וְאֵין מְחַיְּבִין אוֹתוֹ לִתֵּן מַשְׁכּוֹן שֶׁאִלּוּ הָיוּ שָׁם מִטַּלְטְלִים מִיָּד הָיוּ בֵּית דִּין גּוֹבִין מֵהֶן. וְאִם רָצָה הַמַּלְוֶה לְהַחֲרִים עַל מִי שֶׁיֵּשׁ לוֹ מָעוֹת אוֹ מִטַּלְטְלִין וּמַפְלִיג אוֹתוֹ בִּדְבָרִים הֲרֵי זֶה מַחֲרִים. וְאֵין מְחַיְּבִין הַלּוֶֹה לְהָבִיא עָרֵב עַד שֶׁיִּתֵּן. שָׁלְמוּ הַשְּׁלֹשִׁים וְלֹא הֵבִיא בֵּית דִּין כּוֹתְבִין אַדְרַכְתָּא. וְכֵן אִם אָמַר בַּתְּחִלָּה כְּשֶׁתְּבָעוֹ אֵינִי מְשַׁלֵּם כּוֹתְבִין אַדְרַכְתָּא עַל נְכָסָיו מִיָּד וְאֵין קוֹבְעִין לוֹ זְמַן. וְכֵן אִם אֵין שָׁם אֶלָּא מִלְוֶה עַל פֶּה אוֹ שֶׁהוֹדָה כּוֹתְבִין אַדְרַכְתָּא עַל נִכְסֵי בְּנֵי חוֹרִין שֶׁיֵּשׁ לוֹ:","טָעַן וְאָמַר שְׁטָר זֶה שֶׁנִּתְקַיֵּם בִּפְנֵיהֶם מְזֻיָּף הוּא אֲנִי אָבִיא רְאָיָה וַאֲבַטְּלֶנּוּ וְעֵדַי בְּמָקוֹם פְּלוֹנִי וְהֵם פְּלוֹנִי וּפְלוֹנִי. אִם נִרְאֶה לַדַּיָּנִין שֶׁיֵּשׁ מַמָּשׁ בִּדְבָרָיו קוֹבְעִין לוֹ זְמַן לְהָבִיא עֵדָיו וְאִם נִרְאֶה לָהֶם שֶׁאֵינוֹ בָּא אֶלָּא בַּעֲלִילוֹת דְּבָרִים וּבִטְעָנוֹת שֶׁל דֹּפִי אוֹמְרִים לוֹ שַׁלֵּם וְאַחַר כָּךְ אִם יֵשׁ לוֹ רְאָיָה יַחְזֹר. וְאִם הָיָה הַמַּלְוֶה אַלָּם וְשֶׁמָּא אֵינוֹ יָכוֹל לְהוֹצִיאוֹ מִיָּדוֹ מַנִּיחִין עַל יְדֵי שָׁלִישׁ:","קָבְעוּ לוֹ זְמַן לְהָבִיא רְאָיָה וּלְבַטֵּל הַשְּׁטָר וְהִגִּיעַ הַזְּמַן וְלֹא בָּא מַמְתִּינִין לוֹ שֵׁנִי וַחֲמִישִׁי וְשֵׁנִי. לֹא בָּא כּוֹתְבִין עָלָיו פְּתִיחָא וּמְשַׁמְּתִין אוֹתוֹ וּמַמְתִּינִין לוֹ וְהוּא בְּנִדּוּיוֹ תִּשְׁעִים יוֹם. שְׁלֹשִׁים רִאשׁוֹנִים שֶׁמָּא טוֹרֵחַ לִלְווֹת. אֶמְצָעִים שֶׁמָּא הוּא טוֹרֵחַ לִמְכֹּר. אַחֲרוֹנִים שֶׁמָּא הַלּוֹקֵחַ מִמֶּנּוּ טוֹרֵחַ לְהָבִיא מָעוֹת. שָׁלְמוּ תִּשְׁעִים יוֹם וְלֹא בָּא בֵּית דִּין כּוֹתְבִין לוֹ אַדְרַכְתָּא עַל נְכָסָיו וּמַתִּירִין לוֹ נִדּוּיוֹ:","אֵין כּוֹתְבִין אַדְרַכְתָּא עַד שֶׁשּׁוֹלְחִין וּמוֹדִיעִין לוֹ. וְהוּא שֶׁיִּהְיֶה קָרוֹב בְּבֵית דִּין מַהֲלַךְ שְׁנֵי יָמִים אוֹ פָּחוֹת. יֶתֶר עַל זֶה אֵין צְרִיכִין לְהוֹדִיעוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה כָּל הַתִּשְׁעִים יוֹם נִשְׁמָט וְאוֹמֵר עַתָּה אָבִיא רְאָיָה וַאֲבַטֵּל הַשְּׁטָר. אֲבָל אָמַר אֵינִי בָּא לְבֵית דִּין מִיָּד כּוֹתְבִין אַדְרַכְתָּא עַל נְכָסָיו בֵּין עַל הַקַּרְקָעוֹת בֵּין עַל הַמִּטַּלְטְלִין. וְכֵן אִם הָיָה הַשְּׁטָר עַל הַפִּקָּדוֹן אֵין מַמְתִּינִין לוֹ תִּשְׁעִים יוֹם אֶלָּא כּוֹתְבִין אַדְרַכְתָּא עַל נְכָסָיו מִיָּד:","זֶה שֶׁאָמַרְנוּ שֶׁאִם לֹא בָּא בְּסוֹף הַתִּשְׁעִים כּוֹתְבִין אַדְרַכְתָּא עַל הַקַּרְקָעוֹת. אֲבָל עַל הַמִּטַּלְטְלִין אֲפִלּוּ אַחַר תִּשְׁעִים יוֹם כָּל זְמַן שֶׁהוּא אוֹמֵר עַתָּה אָבִיא רְאָיָה וַאֲבַטֵּל הַשְּׁטָר אֵין מוֹרִידִין הַמַּלְוֶה לַמִּטַּלְטְלִין שֶׁמָּא יֹאכַל אוֹתָם וְיָבִיא זֶה רְאָיָה וִיבַטֵּל הַשְּׁטָר וְלֹא יִמְצָא מַה יִּטּל. וַאֲפִלּוּ הָיָה לַמַּלְוֶה קַרְקַע שֶׁמָּא תַּכְסִיף אוֹ תִּשְׁתַּדֵּף:","כֵּיצַד כּוֹתְבִין הָאַדְרַכְתָּא. אִם לִנְכָסִים בְּנֵי חוֹרִין הוֹרִידוּהוּ אוֹמְרִים אִישׁ פְּלוֹנִי נִתְחַיֵּב לִפְלוֹנִי בַּדִּין כָּךְ וְכָךְ וְלֹא נָתַן לוֹ מֵעַצְמוֹ וְכָתַבְנוּ לוֹ אַדְרַכְתָּא זוֹ עַל שָׂדֶה פְּלוֹנִית שֶׁלּוֹ. וְאַחַר כָּךְ שָׁמִין לוֹ שְׁלֹשָׁה מֵאוֹתָהּ שָׂדֶה כְּנֶגֶד חוֹבוֹ וּמַכְרִיזִין עָלֶיהָ כְּפִי מַה שֶּׁיִּרְאוּ עַד שֶׁיִּפְסְקוּ הַמּוֹסִיפִין. וּמוֹרִידִין אוֹתוֹ בְּחוֹבוֹ לַחֵלֶק שֶׁשָּׁמוּ אוֹתוֹ וְקוֹרְעִין שְׁטַר הַחוֹב אִם הָיָה שָׁם שְׁטָר. וְאִם לֹא הָיוּ לוֹ נְכָסִים בְּנֵי חוֹרִין כּוֹתְבִין הָאַדְרַכְתָּא כָּךְ אִישׁ פְּלוֹנִי נִתְחַיֵּב לִפְלוֹנִי כָּךְ בִּשְׁטָר חוֹב שֶׁיֵּשׁ בְּיָדוֹ וְלֹא נָתַן לוֹ חוֹבוֹ וְלֹא מָצָאנוּ לוֹ נְכָסִים בְּנֵי חוֹרִין. וּכְבָר קָרַעְנוּ לַשְּׁטָר שֶׁהָיָה לוֹ עָלָיו וְנָתַנְנוּ לִפְלוֹנִי רְשׁוּת לִדְרשׁ וְלַחְקֹר וְלִהְיוֹת יָדוֹ נְטוּיָה עַל כָּל הַנְּכָסִים שֶׁיִּמָצְאוּ לוֹ וְכָל קַרְקָעוֹת שֶׁמָּכַר מִזְּמַן פְּלוֹנִי וָהָלְאָה יֵשׁ לוֹ לְהִפָּרַע לִגְבּוֹת חוֹבוֹ מִן הַכּל:","וְאַחַר שֶׁכּוֹתְבִין אַדְרַכְתָּא זוֹ הוֹלֵךְ הַמַּלְוֶה וּמְחַפֵּשׂ. אִם מָצָא לוֹ נְכָסִים בְּנֵי חוֹרִין שָׁמִין לוֹ מֵהֶן. מָצָא לוֹ נְכָסִים מְשֻׁעְבָּדִין מֵאַחַר זְמַן שְׁטָרוֹ טוֹרֵף מֵהֶן וְקוֹרְעִין שְׁטַר הָאַדְרַכְתָּא וְכוֹתְבִין לוֹ שְׁטַר הַטִּירְפָא:","כֵּיצַד כּוֹתְבִין. אִישׁ פְּלוֹנִי בֶּן פְּלוֹנִי זָכָה בַּדִּין לִטְרֹף בְּחוֹב שֶׁפְּלוֹנִי חַיָּב לוֹ שֶׁהוּא כָּךְ וְכָךְ מִשָּׂדֶה פְּלוֹנִית שֶׁלָּקַח פְּלוֹנִי בְּכָךְ וְכָךְ מִזְּמַן פְּלוֹנִי. וּכְבָר קָרַעְנוּ הָאַדְרַכְתָּא שֶׁהָיְתָה בְּיָדוֹ וְהִרְשִׁינוּהוּ לִטְרֹף מִזֶּה בְּכָךְ וְכָךְ:","וְאַחַר שֶׁכּוֹתְבִין הַטִּירְפָא לִטְרֹף מוֹרִידִין שְׁלֹשָׁה בְּקִיאִין לְאוֹתָהּ שָׂדֶה וְשָׁמִין לוֹ מִמֶּנָּה כְּשִׁעוּר חוֹבוֹ כְּפִי מַה שֶּׁרָאוּי לוֹ מִן הַקֶּרֶן וַחֲצִי הַשֶּׁבַח כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַכְרִיזִין עָלֶיהָ שְׁלֹשִׁים יוֹם כְּדֶרֶךְ שֶׁמַּכְרִיזִין עַל נִכְסֵי יְתוֹמִים:","וְאַחַר כָּךְ מַשְׁבִּיעִין אֶת הַלּוֶֹה שֶׁאֵין לוֹ כְּלוּם כְּתַקָּנַת הַגְּאוֹנִים אִם הָיָה הַלּוֶֹה עִמָּנוּ בַּמְּדִינָה. וּמַשְׁבִּיעִין אֶת הַטּוֹרֵף בִּנְקִיטַת חֵפֶץ שֶׁלֹּא נִפְרַע חוֹב זֶה וְלֹא מְחָלוֹ וְלֹא מְכָרוֹ לְאַחֵר. וְאַחַר כָּךְ מוֹרִידִין אוֹתוֹ לְנִכְסֵי הַלּוֹקֵחַ בְּשׁוּמָא שֶׁלּוֹ וְכוֹתְבִין הוֹרָדָה:","וְכֵיצַד כּוֹתְבִין. אַחַר שֶׁשַּׁמְנוּ לִפְלוֹנִי בְּשׁוּמָא שֶׁהָיְתָה בְּיָדוֹ וְהִכְרַזְנוּ שְׁלֹשִׁים יוֹם כָּרָאוּי וְהִשְׁבַּעְנוּ אֶת זֶה הַטּוֹרֵף וְאֶת בַּעַל חוֹב הוֹרַדְנוּהוּ לְשָׂדֶה פְּלוֹנִית לִהְיוֹת מִשְׁתַּמֵּשׁ בָּהּ כְּדֶרֶךְ שֶׁמִּשְׁתַּמֵּשׁ אָדָם בְּקִנְיָנוֹ:","וּמֵאֵימָתַי אוֹכֵל הַטּוֹרֵף פֵּרוֹת שָׂדֶה זוֹ מִשֶּׁיִּפְסְקוּ יְמֵי הַהַכְרָזָה:","כָּל אַדְרַכְתָּא שֶׁאֵין כָּתוּב בָּהּ קְרַעְנוּהוּ לִשְׁטַר הַהַלְוָאָה אֵינָהּ אַדְרַכְתָּא. וְכָל טִירְפָא שֶׁאֵין כָּתוּב בָּהּ קְרַעְנוּהָ לָאַדְרַכְתָּא אֵינָהּ טִירְפָא. וְכָל שׁוּמָא דְּלָא כָּתוּב בָּהּ קְרַעְנוּהָ לַטִּירְפָא אֵינָהּ שׁוּמָא:","שְׁלֹשָׁה שֶׁיָּרְדוּ לָשׁוּם. אֶחָד אוֹמֵר בְּמָנֶה וּשְׁנַיִם אוֹמְרִים בְּמָאתַיִם אוֹ אֶחָד אוֹמֵר בְּמָאתַיִם וּשְׁנַיִם אוֹמְרִים בְּמָנֶה. בָּטֵל יָחִיד בְּמִעוּטוֹ. אֶחָד אוֹמֵר בְּמָנֶה וְאֶחָד אוֹמֵר בִּשְׁמוֹנִים וְאֶחָד אוֹמֵר בְּמֵאָה וְעֶשְׂרִים נִדּוֹן בְּמֵאָה. אֶחָד אוֹמֵר בְּמֵאָה וְאֶחָד אוֹמֵר תִּשְׁעִים וְאֶחָד אוֹמֵר מֵאָה וּשְׁלֹשִׁים נִדּוֹן בְּמֵאָה וַעֲשָׂרָה. וְעַל דֶּרֶךְ זוֹ שָׁמִין בֵּינֵיהֶן:","בֵּית דִּין שֶׁשָּׁמוּ לַטּוֹרֵף בְּנִכְסֵי לוֹקֵחַ וְטָעוּ בְּכָל שֶׁהוּא מִכְרָן בָּטֵל שֶׁהֲרֵי הֵן כְּשָׁלִיחַ לַטּוֹרֵף וְלַלּוֹקֵחַ וְיֵשׁ לָהֶן רְשׁוּת לְתַקֵּן אֲבָל לֹא לְעַוֵּת כְּשָׁלִיחַ. וְכָל הַמּוֹרִים כָּזֶה הוֹרוּ:","בֵּית דִּין שֶׁשָּׁמוּ לְבַעַל חוֹב בֵּין בְּנִכְסֵי לוֶֹה בֵּין בִּמְשֻׁעְבָּדִין שֶׁבְּיַד הַלּוֹקֵחַ וּלְאַחַר זְמַן הִשִּׂיגָה יָדוֹ שֶׁל לוֶֹה אוֹ שֶׁל נִטְרָף אוֹ שֶׁל יוֹרְשֵׁיהֶן וְהֵבִיאוּ לְבַעַל חוֹב אֶת מְעוֹתָיו מְסַלְּקִין אוֹתוֹ מֵאוֹתָהּ קַרְקַע. שֶׁהַשּׁוּמָא חוֹזֶרֶת לַבְּעָלִים לְעוֹלָם. מִשּׁוּם שֶׁנֶּאֱמַר (דברים ו יח) \"וְעָשִׂיתָ הַיָּשָׁר וְהַטּוֹב\":","קַרְקַע שֶׁשָּׁמוּ אוֹתָהּ לְבַעַל חוֹב וְאַחַר כָּךְ שָׁמוּהָ בֵּית דִּין לְבַעַל חוֹב שֶׁל זֶה הַמַּלְוֶה הֲרֵי זוֹ חוֹזֶרֶת. לֹא יְהֵא כֹּחוֹ גָּדוֹל מִכֹּחַ בַּעַל חוֹב הָרִאשׁוֹן. מְכָרָהּ בַּעַל חוֹב אוֹ נְתָנָהּ בְּמַתָּנָה אוֹ שֶׁשָּׁמָהּ לְבַעַל חוֹב מִדַּעְתּוֹ אוֹ שֶׁמֵּת וְהוֹרִישָׁהּ אֵינָהּ חוֹזֶרֶת. שָׁמוּ קַרְקַע לְאִשָּׁה וְנִשֵּׂאת אוֹ שֶׁשָּׁמוּ מִמֶּנָּה וְנִשֵּׂאת בַּעַל בְּנִכְסֵי אִשְׁתּוֹ כְּלוֹקֵחַ הוּא וְלֹא מַחְזִיר וְלֹא מַחֲזִירִין לוֹ:"],"Mishneh Torah, Creditor and Debtor 9":["אֵין פּוֹסְקִין עַל הַפֵּרוֹת עַד שֶׁיֵּצֵא הַשַּׁעַר. יָצָא הַשַּׁעַר פּוֹסְקִין. אַף עַל פִּי שֶׁאֵין לָזֶה יֵשׁ לָזֶה. כֵּיצַד. הָיָה הַשַּׁעַר לַחִטִּים קָבוּעַ לַשּׁוּק אַרְבַּע סְאִין בְּסֶלַע הֲרֵי זֶה פּוֹסֵק עִמּוֹ עַל מֵאָה סְאִין וְנוֹתֵן לוֹ חָמֵשׁ וְעֶשְׂרִים סְלָעִים. וְאִם יִתֵּן לוֹ מֵאָה סְאָה שֶׁל חִטִּים אַחַר זְמַן בְּעֵת שֶׁיִּהְיוּ הַחִטִּים סְאָה בְּסֶלַע אֵין בָּזֶה רִבִּית כְּלָל אַף עַל פִּי שֶׁלֹּא הָיָה לַמּוֹכֵר חִטִּים כְּלָל בְּעֵת שֶׁפָּסַק. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה לוֹ כְּלוּם מֵאוֹתוֹ הַמִּין בְּעֵת שֶׁפָּסַק עָלָיו. אֲבָל אִם הָיָה לַמּוֹכֵר מֵאוֹתוֹ הַמִּין כְּלוּם אַף עַל פִּי שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתּוֹ הֲרֵי זֶה מֻתָּר לִפְסֹק עָלָיו אַף עַל פִּי שֶׁעֲדַיִן לֹא יָצָא הַשַּׁעַר. כֵּיצַד. הָיָה הוּא תְּחִלָּה לַקּוֹצְרִים הֲרֵי זֶה פּוֹסֵק עַל הַחִטִּים אַף עַל פִּי שֶׁעֲדַיִן הֵן גָּדִישׁ. וּפוֹסֵק עַל הַיַּיִן מִשֶּׁיִּבְצֹר הָעֲנָבִים וְיִתְּנֵם בְּעָבִיט וְעַל הַשֶּׁמֶן מִשֶּׁנָּתַן זֵיתִים בַּמַּעֲטָן וְעַל הַסִּיד מִשֶּׁיְּשַׁקְּעֶנָּה בַּכִּבְשָׁן. וְכֵן פּוֹסֵק עַל כְּלֵי חֶרֶשׂ מִשֶּׁיַּעֲשֶׂה הַיּוֹצֵר בֵּיצִים שֶׁלָּהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה עֲפָרָן לָבָן אֲבָל עֲפָרָן שָׁחוֹר פּוֹסֵק עַל הַכֵּלִים הַנַּעֲשִׂין מִמֶּנּוּ אַף עַל פִּי שֶׁלֹּא נַעֲשׂוּ מִפְּנֵי שֶׁהוּא מָצוּי לַכּל וְאַף עַל פִּי שֶׁאֵין לָזֶה יֵשׁ לָזֶה. וְכֵן פּוֹסֵק עִמּוֹ עַל הַזֶּבֶל כָּל יְמוֹת הַשָּׁנָה אַף עַל פִּי שֶׁאֵין לוֹ זֶבֶל מִפְּנֵי שֶׁהוּא מָצוּי תָּמִיד:","כָּל דָּבָר שֶׁהוּא מְחֻסַּר מְלָאכָה אַחַת אוֹ שְׁתַּיִם פּוֹסֵק עִמּוֹ עָלָיו. הָיָה מְחֻסַּר שָׁלֹשׁ מְלָאכוֹת אֵינוֹ פּוֹסֵק אֶלָּא אִם כֵּן יָצָא הַשַּׁעַר שֶׁכֵּיוָן שֶׁהוּא מְחֻסַּר שָׁלֹשׁ מְלָאכוֹת הֲרֵי זֶה כְּמִי שֶׁאֵין לוֹ מֵאוֹתוֹ הַמִּין כְּלוּם וּכְמוֹ לֹא בָּא לָעוֹלָם עֲדַיִן. כֵּיצַד. גָּדִישׁ שֶׁהָיָה מְחֻסַּר הַנָּחָה בַּשֶּׁמֶשׁ שֶׁיִּבַשׁ וְדִישָׁה וּזְרִיָּה אֵינוֹ פּוֹסֵק עָלָיו אֶלָּא אִם כֵּן יָצָא הַשַּׁעַר. הָיָה יָבֵשׁ וְאֵינוֹ מְחֻסָּר אֶלָּא דִּישָׁה וּזְרִיָּה פּוֹסֵק עָלָיו. בֵּיצִים שֶׁל יוֹצֵר שֶׁהָיוּ מְחֻסָּרִין לְפִיפָה וְיִבּוּשׁ וְהוֹלָכָה לַכִּבְשָׁן וּשְׂרֵפָה וְהוֹצָאָה אֵינוֹ פּוֹסֵק עֲלֵיהֶן. הָיוּ יְבֵשִׁין וְאֵינָן מְחֻסָּרִין אֶלָּא הוֹלָכָה לַכִּבְשָׁן וּשְׂרֵפָה פּוֹסֵק עֲלֵיהֶן. וְהוּא שֶׁיִּהְיֶה דֶּרֶךְ הַלּוֹקֵחַ לְהוֹצִיא אוֹתוֹ מִן הַכִּבְשָׁן. אֲבָל אִם הָיָה הַמּוֹכֵר הוּא שֶׁמּוֹצִיא הֲרֵי אֵלּוּ מְחֻסָּרִין שָׁלֹשׁ וְאֵינוֹ פּוֹסֵק עֲלֵיהֶן עַד שֶׁיֵּצֵא הַשַּׁעַר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַהוֹלֵךְ לַחֲלֹב אֶת עִזָּיו וְלִגְזֹז אֶת רְחֵלָיו וְלִרְדּוֹת אֶת כַּוַּרְתּוֹ וּמְצָאוֹ חֲבֵרוֹ וְאָמַר לוֹ מַה שֶּׁעִזַּי חוֹלְבוֹת מָכוּר לְךָ מַה שֶּׁרְחֵלַי גּוֹזְזוֹת מָכוּר לְךָ מַה שֶּׁכַּוַּרְתִּי רוֹדָה מָכוּר לְךָ הֲרֵי זֶה מֻתָּר. אֲבָל אָמַר לוֹ מַה שֶּׁעִזַּי חוֹלְבוֹת כָּךְ וְכָךְ מָכוּר לְךָ בְּכָךְ וְכָךְ. מַה שֶּׁרְחֵלַי גּוֹזְזוֹת כָּךְ וְכָךְ מָכוּר לְךָ בְּכָךְ וְכָךְ. מַה שֶּׁכַּוַּרְתִּי רוֹדָה כָּךְ וְכָךְ מָכוּר לְךָ בְּכָךְ וְכָךְ אָסוּר אֶלָּא אִם כֵּן פָּסַק עִמּוֹ כַּשַּׁעַר שֶׁבַּשּׁוּק. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין פּוֹסְקִין עַל שַׁעַר שֶׁל עֲיָרוֹת מִפְּנֵי שֶׁאֵין הַשַּׁעַר קָבוּעַ אֶלָּא עַל שַׁעַר שֶׁבַּמְּדִינָה. הָיוּ הַחִטִּים הַחֲדָשׁוֹת בַּמְּדִינָה אַרְבַּע סְאִין בְּסֶלַע וִישָׁנוֹת שָׁלֹשׁ בְּסֶלַע אֵין פּוֹסְקִין עַד שֶׁיֵּצֵא הַשַּׁעַר לֶחָדָשׁ וְלַיָּשָׁן. הָיוּ חִטִּין שֶׁל לְקוּטוֹת אַרְבַּע סְאִין בְּסֶלַע וְשֶׁל בַּעַל הַבַּיִת שָׁלֹשׁ פּוֹסֵק לַלְּקוּטוֹת כְּשַׁעַר לְקוּטוֹת וְלֹא יִפְסֹק לְבַעַל הַבַּיִת עַד שֶׁיִּקְבַּע הַשַּׁעַר לְבַעַל הַבַּיִת:","כֵּיוָן שֶׁנִּקְבַּע הַשַּׁעַר מֻתָּר לִפְסֹק עַל הַשַּׁעַר הַגָּבוֹהַּ. כֵּיצַד. הָיוּ הַחִטִּים נִמְכָּרוֹת אַרְבַּע סְאִין בְּסֶלַע וּפָסַק עִמּוֹ שֶׁיִּתֵּן לוֹ הַחִטִּים כַּשַּׁעַר הַזּוֹל אִם עָמְדוּ אַחַר כֵּן עֶשֶׂר סְאִין בְּסֶלַע נוֹתֵן לוֹ עֶשֶׂר סְאִין כַּשַּׁעַר שֶׁהָיָה בַּשּׁוּק שֶׁהֲרֵי פָּסַק עִמּוֹ בְּשַׁעַר גָּבוֹהַּ. נָתַן לוֹ הַמָּעוֹת סְתָם וְלֹא פָּסַק עִמּוֹ בַּשַּׁעַר הַגָּבוֹהַּ וְהוּזְלוּ נוֹתֵן כַּשַּׁעַר שֶׁהָיוּ שָׁוִין כְּשֶׁנָּתַן לוֹ הַמָּעוֹת. וּמִי שֶׁחָזַר מְקַבֵּל מִי שֶׁפָּרַע. בַּמֶּה דְּבָרִים אֲמוּרִים בְּפוֹסֵק עַל דַּעַת עַצְמוֹ. אֲבָל אִם הָיָה שָׁלִיחַ לַאֲחֵרִים בֵּין הַמּוֹכֵר בֵּין הַלּוֹקֵחַ אֵינוֹ נוֹטֵל אֶלָּא כַּשַּׁעַר הַזּוֹל אוֹ מַחְזִיר אֶת הַדָּמִים וְאֵינוֹ מְקַבֵּל מִי שֶׁפָּרַע בְּשָׁלִיחַ שֶׁהֲרֵי הַמְשַׁלֵּחַ אוֹמֵר לְתַקֵּן שְׁלַחְתִּיךָ וְלֹא לְעַוֵּת כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיוּ הַחִטִּים נִמְכָּרוֹת אַרְבַּע סְאִין בְּסֶלַע וְנָטַל אֶת הַדָּמִים וְנָתַן לוֹ חָמֵשׁ בְּסֶלַע אִם יֵשׁ לוֹ חִטִּים מֻתָּר. הָיוּ לוֹ חִטִּים חוֹב אֵצֶל אֲחֵרִים וְנָטַל הַמָּעוֹת עַד שֶׁיִּגְבֶּה חִטָּיו וְיִתֵּן לוֹ אָסוּר שֶׁהֲרֵי הֵן מְחֻסָּרִין גְּבִיָּה וּכְאִלּוּ אֵינָם וַהֲרֵי זֶה כְּקוֹבֵעַ לוֹ זְמַן וְהוֹזִיל לוֹ מִפְּנֵי שֶׁמַּקִּיפוֹ:","הָיוּ הַחִטִּים בַּמְּדִינָה אַרְבַּע סְאִין בְּסֶלַע וּבַכְּפָרִים שֵׁשׁ בַּסֶּלַע הֲרֵי זֶה מֻתָּר לִתֵּן סֶלַע לְתַגָּר כְּדֵי שֶׁיָּבִיא שֵׁשׁ סְאִין מִן הַכְּפָר. וְהוּא שֶׁיִּהְיוּ בִּרְשׁוּת הַלּוֹקֵחַ. אִם אָבְדוּ בַּדֶּרֶךְ אוֹ נִגְנְבוּ אָבְדוּ לוֹ. וְאָדָם חָשׁוּב אָסוּר לַעֲשׂוֹת זֶה. ובְּמִינֵי סְחוֹרָה אָסוּר לְכָל אָדָם לְפִי שֶׁאֵין מִינֵי סְחוֹרָה מְצוּיִין כְּפֵרוֹת:","הַחַמָּרִין שֶׁנִּכְנְסוּ לָעִיר וַהֲרֵי הַחִטִּים אַרְבַּע סְאִין בְּסֶלַע. הוֹזִילוּ וּמָכְרוּ לְמַכִּירֵיהֶן אוֹ לְסַפְסָרֵיהֶן חָמֵשׁ בְּסֶלַע בַּמָּעוֹת שֶׁנָּתְנוּ לָהֶן תְּחִלָּה כְּשֶׁיִּכָּנְסוּ לָעִיר עַד שֶׁיִּפְתְּחוּ שַׂקֵּיהֶן וְיִמְכְּרוּ לְכָל אָדָם הֲרֵי זֶה מֻתָּר שֶׁאֵין אֵלּוּ מוֹכְרִין לָהֶם בְּזוֹל מִפְּנֵי שֶׁנָּתְנוּ מָעוֹת עַתָּה וְלֹא יִקְחוּ אֶלָּא לְאַחַר זְמַן אֶלָּא מִפְּנֵי שֶׁמּוֹדִיעִין לָהֶם אֶת הַשַּׁעַר וּמְסַעֲדִין אוֹתָם:","הַמּוֹלִיךְ פֵּרוֹתָיו מִמָּקוֹם לְמָקוֹם מְצָאוֹ חֲבֵרוֹ וְאָמַר לוֹ תְּנֵם לִי וַאֲנִי אַעֲלֶה לְךָ פֵּרוֹת שֶׁיֵּשׁ לִי (בְּמָקוֹם פְּלוֹנִי) בְּאוֹתוֹ מָקוֹם. אִם יֵשׁ לוֹ שָׁם מֻתָּר וְאִם לָאו אָסוּר. הָיָה מוֹלִיךְ סְחוֹרָה מִמָּקוֹם לְמָקוֹם אָמַר לוֹ תְּנֵם לִי וַאֲנִי אַעֲלֶה לְךָ דָּמֶיהָ כְּמוֹ שֶׁשָּׁוֶה בְּאוֹתוֹ מָקוֹם אִם הָיְתָה בִּרְשׁוּת הַמּוֹכֵר עַד שֶׁהִגִּיעַ לְשָׁם מֻתָּר וְאִם הָיְתָה בִּרְשׁוּת לוֹקֵחַ אָסוּר:","הַנּוֹתֵן לְבַעַל הַגִּנָּה דְּמֵי עֲשָׂרָה קִשּׁוּאִין אֵלּוּ דְּמֵי עֲשָׂרָה אֲבַטִּיחִים אֵלּוּ וַהֲרֵי הֵן קְטַנִּים וְהִתְנָה עִמּוֹ שֶׁיִּתְּנֵם לוֹ לִכְשֶׁיַּגְדִּילוּ הֲרֵי זֶה מֻתָּר שֶׁהֲרֵי הוּא מַנִּיחָן וְהֵם גְּדֵלִים מֵאֲלֵיהֶן וְאִלּוּ קִצְּצָן עַתָּה כְּשֶׁהֵן קְטַנִּים לֹא הָיוּ בָּאִים אֲחֵרִים תַּחְתֵּיהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִדָּבָר שֶׁאֵין בּוֹ הֶפְסֵד וְלֹא חִסָּרוֹן עַל הַמּוֹכֵר:"],"Mishneh Torah, Damages to Property 10":["שׁוֹר שֶׁהֵמִית אֶת הָאָדָם בְּכָל מָקוֹם בֵּין גָּדוֹל בֵּין קָטָן בֵּין עֶבֶד בֵּין בֶּן חוֹרִין אֶחָד תָּם וְאֶחָד מוּעָד הֲרֵי זֶה נִסְקָל. וְאִם הֵמִית אֶת הָעַכּוּ\"ם פָּטוּר כְּדִינֵיהֶם:","אֶחָד שׁוֹר וְאֶחָד שְׁאָר בְּהֵמָה חַיָּה וְעוֹף שֶׁהֵמִיתוּ הֲרֵי אֵלּוּ נִסְקָלִין. מַה בֵּין תָּם שֶׁהָרַג אֶת הָאָדָם לְמוּעָד שֶׁהָרַג אֶת הָאָדָם. שֶׁהַתָּם פָּטוּר מִן הַכֹּפֶר וְהַמּוּעָד חַיָּב בְּכֹפֶר וּבִלְבַד שֶׁיִּהְיֶה מוּעָד לַהֲרֹג:","וְהוֹאִיל וְכָל בְּהֵמָה חַיָּה וְעוֹף שֶׁהָרְגוּ אֶת הָאָדָם נִסְקָלִין הֵיאַךְ יִמָּצֵא מוּעָד לַהֲרֹג עַד שֶׁיְּשַׁלְּמוּ בְּעָלָיו אֶת הַכֹּפֶר. כְּגוֹן שֶׁהָרַג שְׁלֹשָׁה עוֹבְדֵי כּוֹכָבִים וְאַחַר כָּךְ הָרַג יִשְׂרָאֵל שֶׁהַמּוּעָד לְעַכּוּ\"ם הֲרֵי זֶה מוּעָד לְיִשְׂרָאֵל. אוֹ שֶׁהָרַג שְׁלֹשָׁה יִשְׂרָאֵל טְרֵפָה וְאַחַר כָּךְ הָרַג שָׁלֵם. אוֹ שֶׁהָרַג וּבָרַח וּבָרְבִיעִי נִתְפַּס. שֶׁאֵין הַבְּעָלִים חַיָּבִין בְּכֹפֶר עַד שֶׁיִּסָּקֵל הַשּׁוֹר. וְכֵן אִם סִכֵּן שְׁלֹשָׁה בְּנֵי אָדָם כְּאֶחָד אוֹ שֶׁהָרַג שָׁלֹשׁ בְּהֵמוֹת הֲרֵי זֶה מוּעָד לַהֲרִיגָה וּבְעָלִים מְשַׁלְּמִין אֶת הַכֹּפֶר. וְכֵן אִם הִכִּירוּ עֵדִים אֶת בַּעַל הַשּׁוֹר וְלֹא הִכִּירוּ אֶת הַשּׁוֹר בְּפַעַם רִאשׁוֹנָה וּשְׁנִיָּה וּשְׁלִישִׁית וּבָרְבִיעִית רָאוּ שׁוֹרוֹ שֶׁהָרַג וְלֹא הָיוּ יוֹדְעִין אִם זֶה הוּא הַשּׁוֹר שֶׁהָרַג בְּשָׁלֹשׁ פְּעָמִים הָרִאשׁוֹנוֹת אוֹ אַחֵר הָיָה. הוֹאִיל וְהוּעֲדוּ הַבְּעָלִים שֶׁיֵּשׁ לָהֶם בִּבְקָרָם שׁוֹר שֶׁהָרַג שָׁלֹשׁ פְּעָמִים הָיָה לָהֶם לִשְׁמֹר כָּל בְּהֶמְתָּם וּמֵאַחַר שֶׁלֹּא שָׁמְרוּ מְשַׁלְּמִין אֶת הַכֹּפֶר:","זֶה שֶׁכָּתוּב בַּתּוֹרָה (שמות כא כט) \"וְגַם בְּעָלָיו יוּמָת\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁחִיּוּב מִיתָה זוֹ בִּידֵי שָׁמַיִם וְאִם נָתַן כֹּפֶר הַנֶּהֱרָג מִתְכַּפֵּר לוֹ. וְאַף עַל פִּי שֶׁהַכֹּפֶר כַּפָּרָה מְמַשְׁכְּנִין מִי שֶׁנִּתְחַיֵּב בְּכֹפֶר בְּעַל כָּרְחוֹ:","שׁוֹר שֶׁל שְׁנֵי שֻׁתָּפִין שֶׁהָרַג. כָּל אֶחָד מֵהֶם מְשַׁלֵּם כֹּפֶר שָׁלֵם שֶׁהֲרֵי כָּל אֶחָד מֵהֶן צָרִיךְ כַּפָּרָה גְּמוּרָה:","אֵין גּוֹמְרִין דִּינוֹ שֶׁל שׁוֹר אֶלָּא בִּפְנֵי בְּעָלָיו אִם הָיוּ לוֹ בְּעָלִים. אֲבָל אִם לֹא הָיוּ לוֹ בְּעָלִים כְּגוֹן שׁוֹר הַמִּדְבָּר וְשׁוֹר שֶׁל הֶקְדֵּשׁ וְשׁוֹר שֶׁל גֵּר שֶׁמֵּת וְאֵין לוֹ יוֹרְשִׁין אִם הֵמִית הֲרֵי זֶה נִסְקָל וְגוֹמְרִין דִּינוֹ אַף עַל פִּי שֶׁאֵין לוֹ בְּעָלִים. וְכֵן שׁוֹר הָאִשָּׁה וְשׁוֹר הַיְתוֹמִים וְשׁוֹר הָאַפּוֹטְרוֹפְּסִים שֶׁהֵמִיתוּ נִסְקָלִין. וְאֵין הָאַפּוֹטְרוֹפְּסִים מְשַׁלְּמִין אֶת הַכֹּפֶר שֶׁהַכֹּפֶר כַּפָּרָה הוּא וְאֵין הַקְּטַנִּים וְהַחֵרְשִׁים וְהַשּׁוֹטִים בְּנֵי חִיּוּב כְּדֵי שֶׁיִּהְיוּ צְרִיכִין כַּפָּרָה:","שׁוֹר שֶׁהוּא טְרֵפָה שֶׁהָרַג אֶת הַנֶּפֶשׁ אוֹ שֶׁהָיָה הַשּׁוֹר שֶׁל אָדָם טְרֵפָה אֵינוֹ נִסְקָל שֶׁנֶּאֱמַר (שמות כא כט) \"וְגַם בְּעָלָיו יוּמָת\" כְּמִיתַת הַבְּעָלִים כָּךְ מִיתַת הַשּׁוֹר. וְכֵיוָן שֶׁבְּעָלָיו כְּמֵת הֵם חֲשׁוּבִים וְאֵינָן צְרִיכִין מִיתָה הֲרֵי זֶה פָּטוּר:","הַמְשַׁסֶּה כֶּלֶב בַּחֲבֵרוֹ וַהֲרָגוֹ אֵין הַכֶּלֶב נִסְקָל. וְכֵן אִם גֵּרָה בּוֹ בְּהֵמָה אוֹ חַיָּה וַהֲרָגוּהוּ. אֲבָל אִם שִׁסָּה בּוֹ נָחָשׁ וַאֲפִלּוּ הִשִּׁיכוֹ בּוֹ וַהֲרָגוֹ הַנָּחָשׁ נִסְקָל. שֶׁאֶרֶס הַנָּחָשׁ שֶׁמֵּמִית מֵעַצְמוֹ מְקִיאוֹ לְפִיכָךְ זֶה הָאָדָם שֶׁהִשִּׁיךְ בּוֹ נָחָשׁ פָּטוּר מִמִּיתַת בֵּית דִּין:","אֵין הַבְּהֵמָה נִסְקֶלֶת אִם הֵמִיתָה עַד שֶׁנִּתְכַּוְּנָה לְהַזִּיק לְמִי שֶׁהִיא חַיֶּבֶת עָלָיו סְקִילָה. אֲבָל שׁוֹר שֶׁהָיָה מִתְכַּוֵּן לַהֲרֹג אֶת הַבְּהֵמָה וְהָרַג אֶת הָאָדָם. נִתְכַּוִּן לְעַכּוּ\"ם וְהָרַג לְיִשְׂרָאֵל. נִתְכַּוֵּן לִנְפָלִים וְהָרַג בֶּן קַיָּמָא. פָּטוּר מִן הַמִּיתָה. וְאִם הָיָה מוּעָד הַבְּעָלִים חַיָּבִין בְּכֹפֶר. אוֹ בִּקְנָס אִם הֵמִית עֶבֶד. וְאַף עַל פִּי שֶׁהָרַג בְּלֹא כַּוָּנָה הוֹאִיל וְהוּא מוּעָד לָזֶה:","הָיָה מוּעָד לִפּל עַל בְּנֵי הָאָדָם בְּבוֹרוֹת וְרָאָה יָרָק בַּבּוֹר וְנָפַל לַבּוֹר בִּשְׁבִיל הַיָּרָק וְהָיָה שָׁם אָדָם וּמֵת. אוֹ שֶׁהָיָה מוּעָד לְהִתְחַכֵּךְ בַּכְּתָלִים וּלְהַפִּיל עַל בְּנֵי אָדָם וְנִתְחַכֵּךְ בַּכֹּתֶל לַהֲנָאָתוֹ וְנָפַל עַל אָדָם וּמֵת מֵחֲמַת חִכּוּכוֹ. הַשּׁוֹר פָּטוּר מִמִּיתָה לְפִי שֶׁלֹּא נִתְכַּוֵּן לְהָמִית וְהַבְּעָלִים חַיָּבִין בְּכֹפֶר שֶׁהֲרֵי זֶה מוּעָד לִפּל בְּבוֹרוֹת עַל בְּנֵי אָדָם אוֹ לְהַפִּיל עֲלֵיהֶם הַכְּתָלִים. וְהֵיאַךְ יוֹדֵעַ שֶׁנִּתְחַכֵּךְ לַהֲנָאָתוֹ. כְּשֶׁנִּתְחַכֵּךְ לְאַחַר שֶׁהִפִּיל וְהֵמִית:","אֵין הַבְּעָלִים מְשַׁלְּמִין אֶת הַכֹּפֶר עַד שֶׁתָּמִית בְּהֶמְתָּן חוּץ מֵרְשׁוּתָן. אֲבָל אִם הֵמִית בִּרְשׁוּת הַמַּזִּיק אַף עַל פִּי שֶׁהוּא בִּסְקִילָה הַבְּעָלִים פְּטוּרִין מִן הַכֹּפֶר. כֵּיצַד. הַנִּכְנָס לַחֲצַר בַּעַל הַבַּיִת שֶׁלֹּא בִּרְשׁוּתוֹ וַאֲפִלּוּ נִכְנַס לִתְבֹּעַ שְׂכָרוֹ אוֹ חוֹבוֹ מִמֶּנּוּ וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת וּמֵת. הַשּׁוֹר בִּסְקִילָה וְהַבְּעָלִים פְּטוּרִין מִן הַכֹּפֶר. שֶׁהֲרֵי אֵין לוֹ רְשׁוּת לִכָּנֵס לִרְשׁוּתוֹ שֶׁל זֶה שֶׁלֹּא מִדַּעְתּוֹ:","עָמַד בַּפֶּתַח וְקָרָא לְבַעַל הַבַּיִת וְאָמַר לוֹ הֵן. וְנִכְנַס וּנְגָחוֹ שׁוֹרוֹ שֶׁל בַּעַל הַבַּיִת הֲרֵי הַבְּעָלִים פְּטוּרִין. שֶׁאֵין מַשְׁמַע הֵן אֶלָּא עֲמֹד בִּמְקוֹמְךָ עַד שֶׁאֲדַבֵּר עִמְּךָ:","בְּהֵמָה שֶׁנִּכְנְסָה לַחֲצַר הַנִּזָּק וְדָרְסָה עַל גַּבֵּי תִּינוֹק דֶּרֶךְ הִלּוּכָהּ וַהֲרָגַתְהוּ הַבְּעָלִים מְשַׁלְּמִין אֶת הַכֹּפֶר שֶׁהָרֶגֶל מוּעֶדֶת לְהַזִּיק בְּדֶרֶךְ הִלּוּכָהּ וּבִרְשׁוּת הַנִּזָּק חַיָּב אַף עַל הַשֵּׁן וְעַל הָרֶגֶל כְּמוֹ שֶׁבֵּאַרְנוּ. נִמְצֵאתָ לָמֵד שֶׁהַמּוּעָד שֶׁהֵמִית בְּכַוָּנָה נִסְקָל וְהַבְּעָלִים חַיָּבִין בְּכֹפֶר וְאִם הֵמִית שֶׁלֹּא בְּכַוָּנָה פָּטוּר מִן הַמִּיתָה וְהַבְּעָלִים חַיָּבִין בְּכֹפֶר. וְתָם שֶׁהֵמִית שֶׁלֹּא בְּכַוָּנָה פָּטוּר מִן הַמִּיתָה וּמִן הַכֹּפֶר. וְאִם נִתְכַּוֵּן לְהָמִית נִסְקָל וְהַבְּעָלִים פְּטוּרִין מִן הַכֹּפֶר וְכֵן מִקְּנָס שֶׁל עֶבֶד:","נִרְאֶה לִי שֶׁאַף עַל פִּי שֶׁהַתָּם שֶׁהֵמִית בְּכַוָּנָה עֶבֶד אוֹ שִׁפְחָה פָּטוּר מִן הַקְּנָס שֶׁהוּא שְׁלֹשִׁים סֶלַע הַכָּתוּב בַּתּוֹרָה. אִם הֵמִית שֶׁלֹּא בְּכַוָּנָה מְשַׁלֵּם חֲצִי דְּמֵי הָעֶבֶד אוֹ חֲצִי דְּמֵי הַשִּׁפְחָה מִגּוּפוֹ כְּאִלּוּ הֵמִית שׁוֹר חֲבֵרוֹ אוֹ חֲמוֹרוֹ:"],"Mishneh Torah, Damages to Property 9":["בְּהֵמָה מְעֻבֶּרֶת שֶׁהִזִּיקָה גּוֹבֶה חֲצִי נֵזֶק מִמֶּנָּה וּמִוְּלָדָהּ מִפְּנֵי שֶׁהוּא מִגּוּפָהּ. אֲבָל תַּרְנְגלֶת שֶׁהִזִּיקָה אֵינוֹ גּוֹבֶה מִבֵּיצָתָהּ מִפְּנֵי שֶׁהַבֵּיצָה אֵינָהּ מִגּוּפָהּ אֲבָל מֻבְדֶּלֶת וּמֻפְרֶשֶׁת מִמֶּנָּה:","מְעֻבֶּרֶת שֶׁנָּגְחָה וְנִמְצָא וְלָדָהּ בְּצִדָּהּ וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נָגְחָה יָלְדָה אוֹ אַחַר שֶׁנָּגְחָה יָלְדָה. מְשַׁלֵּם חֲצִי נֵזֶק מִן הַפָּרָה וְאֵינוֹ גּוֹבֶה מִן הַוָּלָד כְּלוּם עַד שֶׁיָּבִיא רְאָיָה שֶׁבְּשָׁעָה שֶׁנָּגְחָה הָיְתָה מְעֻבֶּרֶת. שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו לְהָבִיא הָרְאָיָה:","שׁוֹר שֶׁנָּגַח פָּרָה מְעֻבֶּרֶת וְנִמְצָא עֻבָּרָהּ נוֹפֵל בְּצִדָּהּ וְאֵין יָדוּעַ אִם עַד שֶׁלֹּא נְגָחָהּ הִפִּילָה אוֹ מֵחֲמַת נְגִיחָה הִפִּילָה. מְשַׁלֵּם נֵזֶק הַפָּרָה וְאֵינוֹ מְשַׁלֵּם נֵזֶק הַוָּלָד. שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","נָגַח פָּרָה מְעֻבֶּרֶת וְהִפִּילָה. אֵין שָׁמִין פְּחַת פָּרָה בִּפְנֵי עַצְמָהּ וּפְחַת הַוָּלָד בִּפְנֵי עַצְמוֹ. אֶלָּא שָׁמִין כַּמָּה הָיְתָה הַפָּרָה שָׁוָה כְּשֶׁהָיְתָה מְעֻבֶּרֶת וּבְרִיאָה וְכַמָּה הִיא שָׁוָה עַכְשָׁו הִיא וְהַנֵּפֶל שֶׁלָּהּ וּמְשַׁלֵּם הַפְּחָת אוֹ חֶצְיוֹ אִם הָיָה תָּם:","הָיְתָה הַפָּרָה לְאֶחָד וְהַוָּלָד לְאֶחָד הֲרֵי פְּחַת הַשֻּׁמָּן שֶׁפָּחַת גּוּף הַפָּרָה לְבַעַל הַפָּרָה. וּפְחַת הַנֶּפַח חוֹלְקִין אוֹתוֹ בַּעַל הַפָּרָה עִם בַּעַל הַוָּלָד. וְהַנֵּפֶל שֶׁל בַּעַל הַוָּלָד:","שׁוֹר שֶׁהָיָה רוֹדֵף אַחַר שׁוֹר אַחֵר וְהֻזַּק. הַנִּזָּק אוֹמֵר שׁוֹרְךָ הִזִּיק וְזֶה אוֹמֵר אֵינִי יוֹדֵעַ שֶׁמָּא בְּסֶלַע לָקָה. הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְאַף עַל פִּי שֶׁהַנִּזָק אוֹמֵר אֵינִי יוֹדֵעַ בְּוַדַּאי וְזֶה אוֹמֵר אֵינִי יוֹדֵעַ. טָעַן הַנִּזָּק וְאָמַר וַדַּאי אַתָּה יוֹדֵעַ שֶׁשּׁוֹרְךָ הִזִּיק הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁאֵינוֹ יוֹדֵעַ אִם הָיָה מוּעָד. אֲבָל אִם הָיָה תָּם פָּטוּר אַף מִשְּׁבוּעַת הֶסֵּת שֶׁאֲפִלּוּ הוֹדָה מֵעַצְמוֹ פָּטוּר שֶׁחֲצִי נֵזֶק קְנָס הוּא וּמוֹדֶה בִּקְנָס פָּטוּר הוּא:","הָיוּ שְׁנַיִם רוֹדְפִין אַחַר אֶחָד וַהֲרֵי עֵדִים שֶׁאֶחָד מֵהֶן הִזִּיק וְאֵין הָעֵדִים יוֹדְעִים אֵיזֶהוּ מִשְּׁנֵיהֶם. זֶה אוֹמֵר שׁוֹרְךָ הִזִּיק וְזֶה אוֹמֵר שׁוֹרְךָ הִזִּיק שְׁנֵיהֶם פְּטוּרִין. וְאִם הָיוּ שְׁנֵיהֶם שֶׁל אִישׁ אֶחָד חַיָּב לְשַׁלֵּם מִגּוּף הַפָּחוּת שֶׁבִּשְׁנֵיהֶם. וְאִם הָיוּ מוּעָדִין מְשַׁלֵּם נֵזֶק שָׁלֵם מִנְּכָסָיו:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשְּׁנֵי הַשְּׁוָרִים עוֹמְדִין. אֲבָל אִם מֵת אֶחָד מֵהֶן אוֹ אָבַד וְהָיָה אֶחָד מֵהֶן תָּם אַף עַל פִּי שֶׁהֵן שֶׁל אִישׁ אֶחָד פָּטוּר. שֶׁהֲרֵי אוֹמֵר לוֹ הָבֵא רְאָיָה שֶׁזֶּה הָעוֹמֵד הוּא שֶׁהִזִּיק וַאֲשַׁלֵּם לְךָ:","הָיוּ שְׁנֵי הַשְּׁוָרִים הָרוֹדְפִין אֶחָד גָּדוֹל וְאֶחָד קָטָן. הַנִּזָּק אוֹמֵר גָּדוֹל הִזִּיק וְהַמַּזִּיק אוֹמֵר קָטָן הִזִּיק. הָיָה אֶחָד תָּם וְאֶחָד מוּעָד הַנִּזָּק אוֹמֵר מוּעָד הִזִּיק וְהַמַּזִּיק אוֹמֵר תָּם הִזִּיק. הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","לֹא הָיְתָה שָׁם רְאָיָה בְּרוּרָה שֶׁזֶּה הִזִּיק אֶלָּא עֵדִים מְעִידִים שֶׁאֶחָד מִשְּׁנֵי אֵלּוּ הִזִּיק מְשַׁלֵּם הַמַּזִּיק כְּמוֹ שֶׁאוֹמֵר. וְאִם טָעַן הַנִּזָּק שֶׁאַתָּה יוֹדֵעַ וַדַּאי שֶׁזֶּה הִזִּיק בְּפָנֶיךָ הֲרֵי הַמַּזִּיק נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה וּמְשַׁלֵּם כְּמוֹ שֶׁהוֹדָה שֶׁהֲרֵי הוֹדָה בְּמִקְצָת:","הָיוּ הַנִּזָּקִין שְׁנַיִם אֶחָד גָּדוֹל וְאֶחָד קָטָן וְהַמַּזִּיקִין אֶחָד גָּדוֹל וְאֶחָד קָטָן. הַנִּזָּק אוֹמֵר גָּדוֹל הִזִּיק אֶת הַגָּדוֹל וְהַקָּטָן אֶת הַקָּטָן וְהַמַּזִּיק אוֹמֵר לֹא כִּי אֶלָּא קָטָן הִזִּיק אֶת הַגָּדוֹל וְגָדוֹל אֶת הַקָּטָן. אוֹ שֶׁהָיָה אֶחָד תָּם וְאֶחָד מוּעָד הַנִּזָּק אוֹמֵר הַמּוּעָד הִזִּיק אֶת הַגָּדוֹל וְתָם הִזִּיק אֶת הַקָּטָן וְהַמַּזִּיק אוֹמֵר תָּם הִזִּיק אֶת הַגָּדוֹל וְהַמּוּעָד הִזִּיק אֶת הַקָּטָן. הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. לֹא הָיְתָה שָׁם רְאָיָה בְּרוּרָה הַמַּזִּיק פָּטוּר. לְמָה זֶה דּוֹמֶה לְזֶה טוֹעֵן אֶת חֲבֵרוֹ חִטִּים וְהוֹדָה לוֹ בִּשְׂעוֹרִים שֶׁהוּא נִשְׁבַּע שְׁבוּעַת הֶסֵּת וּפָטוּר אַף מִדְּמֵי שְׂעוֹרִים כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת טוֹעֵן. וְאִם תָּפַס הַנִּזָּק הֲרֵי זֶה מְשַׁלֵּם לַקָּטָן מִן הַגָּדוֹל וְלַגָּדוֹל מִן הַקָּטָן כְּמוֹ שֶׁהוֹדָה הַמַּזִּיק. אֲבָל אִם לֹא תָּפַס אֵין מוֹצִיאִין מִן הַמַּזִּיק כְּלוּם:","שׁוֹר שֶׁנָּגַח וְחָזַר וְנָגַח שׁוֹר אַחֵר הֲרֵי הַנִּזָּק הָרִאשׁוֹן וְהַבְּעָלִים שֻׁתָּפִין בּוֹ. כֵּיצַד. שׁוֹר שָׁוֶה מָאתַיִם שֶׁנָּגַח שׁוֹר שָׁוֶה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם הַנִּזָּק נוֹטֵל מֵאָה וּבַעַל הַשּׁוֹר מֵאָה. חָזַר וְנָגַח שׁוֹר אַחֵר שָׁוֶה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם הָאַחֲרוֹן נוֹטֵל מֵאָה וְהַנִּזָּק שֶׁלְּפָנָיו עִם הַבְּעָלִים נוֹטְלִין חֲמִשִּׁים חֲמִשִּׁים זוּז. חָזַר וְנָגַח שׁוֹר אַחֵר שָׁוֶה מָאתַיִם וְאֵין הַנְּבֵלָה יָפָה כְּלוּם הָאַחֲרוֹן נוֹטֵל מֵאָה וְנִזָּק שֶׁלְּפָנָיו חֲמִשִּׁים וְהַנִּזָּק הָרִאשׁוֹן עִם הַבְּעָלִים עֶשְׂרִים וַחֲמִשָּׁה עֶשְׂרִים וַחֲמִשָּׁה. וְכֵן עַל דֶּרֶךְ זוֹ חוֹלְקִין וְהוֹלְכִים:","נִזָּק שֶׁתָּפַס בְּהֵמָה שֶׁהִזִּיקָה לִגְבּוֹת חֲצִי נִזְקוֹ מִגּוּפָהּ נַעֲשָׂה עָלֶיהָ שׁוֹמֵר שָׂכָר לִנְזָקִין וְאִם יָצְתָה וְהִזִּיקָה הַנִּזָּק הָרִאשׁוֹן חַיָּב בִּנְזָקֶיהָ וְהַבְּעָלִים פְּטוּרִין. כֵּיצַד. שׁוֹר שָׁוֶה מָאתַיִם שֶׁנָּגַח וְהִפְסִיד מָאתַיִם וּתְפָסוֹ הַנִּזָּק לִגְבּוֹת מִמֶּנּוּ מֵאָה וְחָזַר וְנָגַח וְהִפְסִיד בְּמֵאָה וְאַרְבָּעִים הֲרֵי הַנִּזָּק הָאַחֲרוֹן מִשְׁתַּלֵּם שִׁבְעִים וְהַנִּזָּק הָרִאשׁוֹן שֶׁתְּפָסוֹ מִשְׁתַּלֵּם מוֹתַר נִזְקוֹ וְהוּא שְׁלֹשִׁים וְהַבְּעָלִים מֵאָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","שְׁנֵי שְׁוָרִים תַּמִּים שֶׁחָבְלוּ זֶה בָּזֶה מְשַׁלְּמִין בַּמּוֹתָר חֲצִי נֵזֶק. שְׁנֵיהֶם מוּעָדִין (אוֹ מוּעָד וְאָדָם) שֶׁחָבְלוּ זֶה בָּזֶה מְשַׁלְּמִין בַּמּוֹתָר נֵזֶק שָׁלֵם. אֶחָד תָּם וְאֶחָד מוּעָד. מוּעָד בְּתָם מְשַׁלֵּם בַּמּוֹתָר נֵזֶק שָׁלֵם תָּם בְּמוּעָד מְשַׁלֵּם בַּמּוֹתָר חֲצִי נֵזֶק. כֵּיצַד. שׁוֹר תָּם שֶׁהִפְסִיד בְּשׁוֹר תָּם אַחֵר שְׁוֵה מָנֶה וְחָזַר זֶה הָאַחֲרוֹן וְהִפְסִיד בָּרִאשׁוֹן שְׁוֵה אַרְבָּעִים הֲרֵי בַּעַל הָרִאשׁוֹן מְשַׁלֵּם לַבַּעַל הָאַחֲרוֹן שְׁלֹשִׁים. הָיוּ שְׁנֵיהֶם מוּעָדִין בַּעַל הָרִאשׁוֹן מְשַׁלֵּם שִׁשִּׁים. הָרִאשׁוֹן מוּעָד וְאַחֲרוֹן תָּם בַּעַל הָרִאשׁוֹן מְשַׁלֵּם שְׁמוֹנִים. הָרִאשׁוֹן תָּם וְהָאַחֲרוֹן מוּעָד בַּעַל הָרִאשׁוֹן מְשַׁלֵּם עֲשָׂרָה:"],"Mishneh Torah, Defilement by Leprosy 5":["מִי שֶׁהָיְתָה לוֹ מַכָּה בְּעוֹר בְּשָׂרוֹ וְנִפְשַׁט הָעוֹר מֵחֲמַת הַמַּכָּה. אִם הָיְתָה הַמַּכָּה מֵחֲמַת הָאֵשׁ כְּגוֹן שֶׁנִּכְוָה בְּגַחֶלֶת אוֹ בְּרֶמֶץ אוֹ בְּבַרְזֶל אוֹ בְּאֶבֶן שֶׁלִּבְּנוֹ בָּאֵשׁ וְכַיּוֹצֵא בָּהֶן הֲרֵי זוֹ נִקְרֵאת מִכְוָה. וְאִם הָיְתָה הַמִּכְוָה שֶׁלֹּא מֵחֲמַת הָאֵשׁ. בֵּין שֶׁלָּקָה בְּאֶבֶן אוֹ בְּעֵץ וְכַיּוֹצֵא בָּהֶן בֵּין שֶׁהָיְתָה הַמִּכְוָה מֵחֲמַת חֳלִי הַגּוּף כְּגוֹן גָּרָב אוֹ חֲזָזִית שֶׁהִפְסִיד הָעוֹר אוֹ שַׁחֶפֶת אוֹ קַדַּחַת וְדַלֶּקֶת וְכַיּוֹצֵא בָּהֶן שֶׁהִשְׁחִיתוּ הָעוֹר הֲרֵי זֶה נִקְרָא שְׁחִין:","לִבֵּן שִׁפּוּד וְהִכָּה בּוֹ אִם הָיָה רֹאשׁוֹ (מְבוֹרָז) [כַּדּוּר] הֲרֵי זוֹ מִכְוָה. וְאִם הָיָה רֹאשׁוֹ חַד הֲרֵי זוֹ סָפֵק אִם הִיא מִכְוָה אוֹ שְׁחִין. לָקָה בְּמֵי טְבֶרְיָא אוֹ בְּגֶפֶת וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה שְׁחִין:","הַשְּׁחִין וְהַמִּכְוָה כָּל זְמַן שֶׁהֵן מַכּוֹת טְרִיּוֹת הֵן נִקְרָאִין מוֹרְדִין וְאֵינָן מִטַמְּאִין בִּנְגָעִים כְּלָל. חָיוּ הַשְּׁחִין וְהַמִּכְוָה וְנִתְרַפְּאוּ רִפּוּי גָּמוּר אַף עַל פִּי שֶׁהַמָּקוֹם צַלֶּקֶת וְאֵינָהּ דּוֹמָה לִשְׁאָר הָעוֹר הֲרֵי הֵן כְּעוֹר הַבָּשָׂר לְכָל דָּבָר וּמִתְטַמְּאִין בִּשְׁלֹשָׁה סִימָנִין וְיֵשׁ בָּהֶן הֶסְגֵּר שְׁנֵי שָׁבוּעוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:","הִתְחִילוּ הַשְּׁחִין וְהַמִּכְוָה לִחְיוֹת וּלְהִתְרַפְּאוֹת וְנַעֲשֵׂית עֲלֵיהֶן קְלִפָּה כִּקְלִפַּת הַשּׁוּם. זוֹ הִיא (ויקרא יג כג) \"צָרֶבֶת הַשְּׁחִין\" הָאֲמוּרָה בַּתּוֹרָה (ויקרא יג כד) \"וּמִחְיַת הַמִּכְוָה\" הָאֲמוּרָה שָׁם. וּמְטַמְּאוֹת בִּשְׁנֵי סִימָנִין בְּשֵׂעָר לָבָן אוֹ בְּפִשְׂיוֹן וְאֵין בָּהֶן הֶסְגֵּר אֶלָּא שָׁבוּעַ אֶחָד. כֵּיצַד. בַּהֶרֶת שֶׁהָיְתָה בְּצָרֶבֶת הַשְּׁחִין אוֹ בְּמִחְיַת הַמִּכְוָה אִם הָיָה בָּהּ שֵׂעָר לָבָן יַחְלִיט. לֹא הָיָה בָּהּ שֵׂעָר לָבָן יַסְגִּיר שָׁבוּעַ אֶחָד וְיֵרָאֶה בְּסוֹף הַשָּׁבוּעַ אִם נוֹלַד בָּהּ שֵׂעָר אוֹ פָּשְׂתָה יַחְלִיט וְאִם לֹא נוֹלַד בָּהּ כְּלוּם יִפְטֹר. פָּשְׂתָה לְאַחַר הַפִּטּוּר אוֹ נוֹלַד בָּהּ שֵׂעָר לָבָן יַחְלִיט:","הַשְּׁחִין וְהַמִּכְוָה אֵין מִצְטָרְפִין זֶה עִם זֶה לְפִיכָךְ חִלְּקָן הַכָּתוּב לוֹמַר שֶׁאֵין מִצְטָרְפִין זֶה עִם זֶה וְאֵין פּוֹשִׂין זֶה לָזֶה וְאֵין פּוֹשִׂין לְעוֹר הַבָּשָׂר וְלֹא בַּהֶרֶת עוֹר הַבָּשָׂר פּוֹשָׂה לְתוֹכָן. כֵּיצַד. הָיָה שְׁחִין בְּצַד הַמִּכְוָה וּבַהֶרֶת כִּגְרִיס בִּשְׁתֵּיהֶן הֲרֵי זֶה טָהוֹר. הָיְתָה בְּאַחַת מֵהֶן וּפָשְׂתָה לַשְּׁנִיָּה אוֹ שֶׁפָּשְׂתָה לְעוֹר הַבָּשָׂר טָהוֹר. הָיְתָה בַּהֶרֶת בְּעוֹר הַבָּשָׂר וּפָשְׂתָה לְאַחַת מֵהֶן אֵינוֹ פִּשְׂיוֹן. הָיָה בְּתוֹךְ כַּפּוֹ צָרֶבֶת שְׁחִין כִּגְרִיס וּבָהּ בַּהֶרֶת כִּגְרִיס יַסְגִּיר שֶׁאַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לְשֵׂעָר לָבָן וְלֹא לְפִשְׂיוֹן שֶׁמָּא יִוָּלֵד לוֹ שְׁחִין אַחֵר בְּצִדָּהּ וְתִפְשֶׂה לְתוֹכוֹ:","שְׁחִין שֶׁנַּעֲשָׂה מִכְוָה בִּטְּלָה מִכְוָה אֶת הַשְּׁחִין. וּמִכְוָה שֶׁנַּעֲשֵׂית שְׁחִין בִּטֵּל שְׁחִין הַמִּכְוָה. אִם אֵין יָדוּעַ אִם שְׁחִין הָיָה אִם מִכְוָה אֵין בְּכָךְ כְּלוּם שֶׁשְּׁנֵיהֶם סִימָן אֶחָד וְטֻמְאָה אַחַת וְלֹא חִלְּקָן הַכָּתוּב אֶלָּא לוֹמַר שֶׁאֵין מִצְטָרְפִין:","הִסְגִּירוֹ בְּבַהֶרֶת שֶׁבַּשְּׁחִין וּבְסוֹף הַשָּׁבוּעַ נַעֲשָׂה עוֹר הַבָּשָׂר. אוֹ שֶׁהִסְגִּירוֹ בְּעוֹר הַבָּשָׂר וּבְסוֹף הַשָּׁבוּעַ נַעֲשֵׂית שְׁחִין יֵרָאֶה בַּתְּחִלָּה:","מִי שֶׁנָּשַׁר כָּל שְׂעַר רֹאשׁוֹ בֵּין מֵחֲמַת חלִי בֵּין מֵחֲמַת מַכָּה שֶׁאֵינָהּ רְאוּיָה לְגַדֵּל שֵׂעָר בֵּין שֶׁאָכַל דְּבָרִים הַמַּשִּׁירִין אֶת הַשֵּׂעָר אוֹ סָךְ דְּבָרִים שֶׁהִשִּׁירוּ שְׂעָרוֹ אַף עַל פִּי שֶׁרָאוּי לְגַדֵּל לְאַחַר זְמַן הוֹאִיל וְאָבַד כָּל שְׂעַר רֹאשׁוֹ עַתָּה הֲרֵי זֶה נִקְרָא קֵרֵחַ אוֹ גִּבֵּחַ. אִם נָשַׁר שְׂעָרוֹ מִן הַקָּדְקֹד וּלְמַטָּה שׁוֹפֵעַ לְאָחוֹר וְעַד פִּיקָה שֶׁל צַוָּאר נִקְרָא קֵרֵחַ. וְאִם נָשַׁר מִן הַקָּדְקֹד וּלְמַטָּה שׁוֹפֵעַ לְפָנָיו עַד כְּנֶגֶד פַּדַּחְתּוֹ נִקְרָא גִּבֵּחַ:","הַקָּרַחַת וְהַגַּבַּחַת מְטַמְּאוֹת בִּשְׁנֵי סִימָנִין בְּמִחְיָה וּבְפִשְׂיוֹן. וְיֵשׁ בָּהֶן הֶסְגֵּר שְׁנֵי שָׁבוּעוֹת שֶׁנֶּאֱמַר בָּהֶן (ויקרא יג מג) \"כְּמַרְאֵה צָרַעַת עוֹר בָּשָׂר\". וּלְפִי שֶׁאֵין בָּהֶן שֵׂעָר אֵין הַשֵּׂעָר הַלָּבָן סִימַן טֻמְאָה בָּהֶן. וְכֵיצַד מְטַמְּאִין בִּשְׁנֵי סִימָנִין וּבִשְׁתֵּי שָׁבוּעוֹת. שֶׁאִם הָיְתָה בַּהֶרֶת בְּקָרַחְתּוֹ אוֹ בְּגַבַּחְתּוֹ וְהָיְתָה בָּהּ מִחְיָה יַחְלִיט. לֹא הָיְתָה בָּהּ מִחְיָה יַסְגִּיר וְיִרְאֶה בְּסוֹף הַשָּׁבוּעַ אִם נוֹלְדָה בָּהּ מִחְיָה אוֹ פִּשְׂיוֹן יַחְלִיט. לֹא נוֹלַד בָּהּ כְּלוּם יַסְגִּיר שָׁבוּעַ שֵׁנִי. פָּשָׂת אוֹ שֶׁנּוֹלַד בָּהּ מִחְיָה יַחְלִיט לֹא נוֹלַד בָּהּ כְּלוּם יִפְטֹר. וְאִם פָּשָׂת אוֹ נוֹלַד בָּהּ מִחְיָה לְאַחַר הַפִּטּוּר יַחְלִיט:","הַקָּרַחַת וְהַגַּבַּחַת אֵינָן מִצְטָרְפוֹת זוֹ עִם זוֹ שֶׁנֶּאֱמַר (ויקרא יג מב) \"בְּקָרַחְתּוֹ אוֹ בְּגַבַּחְתּוֹ\" מְלַמֵּד שֶׁהֵן שְׁתַּיִם וְאֵין פּוֹשׂוֹת מִזּוֹ לְזוֹ וְלֹא לִשְׁאָר עוֹר הַבָּשָׂר וְלֹא בַּהֶרֶת עוֹר הַבָּשָׂר פּוֹשָׂה לְתוֹכָן:","הַקָּרַחַת אוֹ הַגַּבַּחַת אוֹ הַזָּקָן שֶׁנִּקְרַח וְנַעֲשָׂה בָּהֶן שְׁחִין אוֹ מִכְוָה מְטַמְּאִין כִּשְׁחִין וּכְמִכְוָה שֶׁבְּעוֹר הַבָּשָׂר. שֶׁהָרֹאשׁ אוֹ הַזָּקָן שֶׁנִּקְרְחוּ כְּעוֹר הַבָּשָׂר לְכָל דָּבָר אֶלָּא שֶׁאֵין מִטַּמְּאִין בְּשֵׂעָר לָבָן. הָרֹאשׁ וְהַזָּקָן קֹדֶם שֶׁיִּצְמַח בָּהֶן הַשֵּׂעָר וַעֲדַיִן לֹא הֶעֱלוּ שֵׂעָר מֵעוֹלָם וְכֵן הַדִּלְדּוּלִין שֶׁבָּרֹאשׁ וְשֶׁבַּזָּקָן הֲרֵי הֵן כְּעוֹר הַבָּשָׂר וּמִתְטַמְּאִין בִּשְׁלֹשָׁה סִימָנִין וּשְׁנֵי שָׁבוּעוֹת. וְכֵן זְקַן הָאִשָּׁה וְהַסָּרִיס עַד שֶׁלֹּא הֶעֱלוּ שֵׂעָר הֲרֵי הֵן כְּעוֹר הַבָּשָׂר. וְאִם הֶעֱלוּ שֵׂעָר הֲרֵי הֵן כִּזְקַן הָאִישׁ שֶׁמִּתְטַמֵּא בִּנְתָקִין כְּמוֹ שֶׁיִּתְבָּאֵר וְאֵינוֹ מִתְטַמֵּא בְּבַהֶרֶת:"],"Mishneh Torah, Defilement by a Corpse 16":["אֲרֻבָּה שֶׁהִיא בְּאֶמְצַע תִּקְרַת הַבַּיִת בֵּין שֶׁיֵּשׁ בָּהּ פּוֹתֵחַ טֶפַח בֵּין שֶׁאֵין בָּהּ פּוֹתֵחַ טֶפַח וְהָיְתָה טֻמְאָה תַּחַת תִּקְרַת הַבַּיִת כְּנֶגֶד אֲרֻבָּה טָהוֹר שֶׁהֲרֵי הוּא גָּלוּי לָאֲוִיר וּשְׁאָר הַבַּיִת טָמֵא. הָיְתָה טֻמְאָה כְּנֶגֶד אֲרֻבָּה בִּלְבַד כָּל הַבַּיִת טָהוֹר. הָיְתָה מִקְצָת הַטֻּמְאָה תַּחַת הַתִּקְרָה וּמִקְצָתָהּ תַּחַת אֲרֻבָּה אִם הָיָה בָּאֲרֻבָּה פּוֹתֵחַ טֶפַח הַבַּיִת כֻּלּוֹ טָמֵא וּכְנֶגֶד כָּל הָאֲרֻבָּה טָמֵא. אֵין בָּהּ פּוֹתֵחַ טֶפַח אִם יֵשׁ בַּטֻּמְאָה כְּדֵי שֶׁתִּתְחַלֵּק וְיִמָּצֵא כַּשִּׁעוּר תַּחַת הַתִּקְרָה וְכַשִּׁעוּר תַּחַת הָאֲרֻבָּה הַכּל טָמֵא. וְאִם לָאו הַבַּיִת טָמֵא וּכְנֶגֶד הָאֲרֻבָּה טָהוֹר. הָיָה בָּאֲרֻבָּה פּוֹתֵחַ טֶפַח וְנָתַן אָדָם רַגְלוֹ מִלְּמַעְלָה עַל הָאֲרֻבָּה נַעֲשֶׂה הַכּל אֹהֶל אֶחָד. וּבֵין שֶׁהָיְתָה הַטֻּמְאָה תַּחַת הַתִּקְרָה בִּלְבַד אוֹ תַּחַת הָאֲרֻבָּה בִּלְבַד הַכּל טָמֵא הַבַּיִת וּמַה שֶּׁכְּנֶגֶד אֲרֻבָּה. וְהָאָדָם שֶׁעֵרֵב אֶת הַטֻּמְאָה טָמֵא מִפְּנֵי שֶׁנַּעֲשָׂה אֹהֶל עַל הַטֻּמְאָה. אֵין בָּאֲרֻבָּה פּוֹתֵחַ טֶפַח וְהָיְתָה הַטֻּמְאָה תַּחַת הַתִּקְרָה זֶה שֶׁנָּתַן רַגְלוֹ מִלְּמַעְלָה טָהוֹר שֶׁאֵין טֻמְאָה יוֹצֵאת לוֹ בְּפָחוֹת מִטֶּפַח. הָיְתָה הַטֻּמְאָה תַּחַת הָאֲרֻבָּה אִם טֻמְאָה קָדְמָה אֶת רַגְלוֹ טָמֵא שֶׁהֲרֵי הֶאֱהִיל עַל הַטֻּמְאָה. אִם רַגְלוֹ קָדְמָה אֶת הַטֻּמְאָה טָהוֹר שֶׁהֲרֵי רַגְלוֹ מִקְצָת הָאֹהֶל וְאֵין טֻמְאָה יוֹצֵאת לוֹ:","הָיָה כְּזַיִת מִן הַמֵּת בְּפִי הָעוֹרֵב וְהֶאֱהִיל עַל גַּבֵּי אֲרֻבָּה עַד שֶׁנִּמְצָא כְּזַיִת בַּאֲוִיר אֲרֻבָּה אַף עַל פִּי שֶׁאֵין בָּהּ פּוֹתֵחַ טֶפַח הַבַּיִת טָמֵא:","בַּיִת וַאֲרֻבָּה בְּאֶמְצַע תִּקְרַת הַבַּיִת וַעֲלִיָּה עַל גַּבָּיו. וַאֲרֻבָּה אַחֶרֶת יֵשׁ בְּאֶמְצַע תִּקְרַת הָעֲלִיָּה וְהָאֲרֻבּוֹת מְכֻוָּנוֹת זוֹ לְמַעְלָה מִזּוֹ. בֵּין שֶׁיֵּשׁ בָּאֲרֻבּוֹת פּוֹתֵחַ טֶפַח בֵּין שֶׁאֵין בָּהֶן פּוֹתֵחַ טֶפַח. וְטֻמְאָה בַּבַּיִת. כְּנֶגֶד הָאֲרֻבּוֹת טָהוֹר וְהַשְּׁאָר טָמֵא. הָיְתָה טֻמְאָה כְּנֶגֶד אֲרֻבּוֹת הֲרֵי הַבַּיִת כֻּלּוֹ טָהוֹר. הָיוּ בָּאֲרֻבּוֹת פּוֹתֵחַ טֶפַח וְהַטֻּמְאָה בֵּין תַּחַת תִּקְרַת הַבַּיִת בֵּין כְּנֶגֶד אֲרֻבּוֹת וְנָתַן דָּבָר שֶׁהוּא מְקַבֵּל טֻמְאָה בֵּין לְמַעְלָה מֵאֲרֻבַּת הַבַּיִת בֵּין לְמַעְלָה מֵאֲרֻבַּת הָעֲלִיָּה הַכּל טָמֵא שֶׁאֵין דָּבָר טָמֵא חוֹצֵץ. נָתַן דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה עַל אֲרֻבַּת הַבַּיִת הַבַּיִת טָמֵא וְהָעֲלִיָּה טְהוֹרָה. נְתָנוֹ עַל אֲרֻבַּת הָעֲלִיָּה הַבַּיִת וְהָעֲלִיָּה טְמֵאִים וּכְנֶגְדוֹ מִלְּמַעְלָה וְלַשָּׁמַיִם טָהוֹר. אֵין בָּאֲרֻבּוֹת פּוֹתֵחַ טֶפַח וְהַטֻּמְאָה תַּחַת תִּקְרַת הַבַּיִת וְנָתַן בֵּין דָּבָר הַמְקַבֵּל טֻמְאָה וּבֵין דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה בֵּין עַל אֲרֻבַּת הַבַּיִת בֵּין עַל אֲרֻבַּת הָעֲלִיָּה אֵין טָמֵא אֶלָּא הַבַּיִת שֶׁאֵין טֻמְאָה יוֹצֵאת לָעֲלִיָּה בְּפָחוֹת מִטֶּפַח. הָיְתָה הַטֻּמְאָה כְּנֶגֶד אֲרֻבּוֹת וְנָתַן דָּבָר שֶׁהוּא מְקַבֵּל טֻמְאָה בֵּין לְמַעְלָן בֵּין לְמַטָּן הַבַּיִת וְהָעֲלִיָּה טְמֵאִין שֶׁהֲרֵי עֵרֵב אֶת הַטֻּמְאָה. נָתַן דָּבָר שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה בֵּין לְמַעְלָן בֵּין לְמַטָּן אֵינוֹ טָמֵא אֶלָּא הַבַּיִת. וְכָל אֵלּוּ הַדִּינִין בְּעוֹשֶׂה אֲרֻבָּה אֲבָל תִּקְרָה שֶׁנִּפְחֲתָה מֵאֵלֶיהָ שִׁעוּרָהּ מְלֹא אֶגְרוֹף כְּמוֹ שֶׁבֵּאַרְנוּ:","הַפּוֹחֵת אֶת הַמַּעֲזִיבָה עַד שֶׁעָשָׂה אֲרֻבָּה בְּתוֹךְ תִּקְרַת הַבַּיִת כְּדֵי שֶׁתִּכָּנֵס בָּהּ רֶגֶל הָעֶרֶשׂ וְהָיְתָה רֶגֶל הָעֶרֶשׂ סוֹתֶמֶת אֶת הָאֲרֻבָּה. אִם יֵשׁ בָּהּ פּוֹתֵחַ טֶפַח וְטֻמְאָה בַּבַּיִת אַף הָעֲלִיָּה טְמֵאָה. שֶׁאֵין כְּלִי הַמְקַבֵּל טֻמְאָה חוֹצֵץ. וְאִם אֵין בָּהּ פּוֹתֵחַ טֶפַח הָעֲלִיָּה טְהוֹרָה וְהָרֶגֶל שֶׁלְּמַטָּה טְמֵאָה כְּכֵלִים הַמַּאֲהִילִים. נִפְחֲתָה הַמַּעֲזִיבָה מֵאֵלֶיהָ שִׁעוּרָהּ מְלֹא אֶגְרוֹף כְּמוֹ שֶׁבֵּאַרְנוּ:","אֲרֻבָּה שֶׁבְּתוֹךְ תִּקְרַת הַבַּיִת וּקְדֵרָה מֻנַּחַת עַל הָאָרֶץ וּמְכֻוֶּנֶת כְּנֶגֶד אֲרֻבָּה שֶׁאִם תַּעֲלֶה תֵּצֵא בְּצִמְצוּם מִן הָאֲרֻבָּה וְהָיְתָה טֻמְאָה תַּחַת הַקְּדֵרָה רְצוּצָה בֵּינָהּ וּבֵין הָאָרֶץ אוֹ שֶׁהָיְתָה הַטֻּמְאָה בְּתוֹךְ הַקְּדֵרָה אוֹ עַל גַּבָּהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת וְאֵין טָמֵא אֶלָּא כְּנֶגְדָּהּ וְהַבַּיִת כֻּלּוֹ טָהוֹר. הָיְתָה הַקְּדֵרָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ תַּחַת תִּקְרַת הַבַּיִת הַבַּיִת כֻּלּוֹ טָמֵא וְתַחַת הַקְּדֵרָה טָמֵא שֶׁהֲרֵי הוּא אֹהֶל אֲבָל תּוֹךְ הַקְּדֵרָה וְגַבָּהּ טָהוֹר שֶׁאֵין כְּלִי חֶרֶשׂ מִטַּמֵּא מִגַּבּוֹ וַהֲרֵי אֲוִיר הַקְּדֵרָה גָּלוּי לַאֲוִירוֹ. אִם הָיָה כְּלִי בְּתוֹכָהּ אוֹ לְמַעְלָה עַל גַּבָּהּ טָהוֹר. הָיְתָה טֻמְאָה בְּתוֹכָהּ אוֹ עַל גַּבָּהּ הַבַּיִת כֻּלּוֹ טָהוֹר שֶׁהֲרֵי הַטֻּמְאָה כְּנֶגֶד אֲרֻבָּה בִּלְבַד. הָיְתָה הַקְּדֵרָה תַּחַת הָאֲרֻבָּה וְהָאֲרֻבָּה גְּדוֹלָה מִן הַקְּדֵרָה שֶׁאִם תַּעֲלֶה הַקְּדֵרָה וְתֵצֵא מִן הָאֲרֻבָּה נִמְצָא בֵּינָהּ וּבֵין שִׂפְתֵי הָאֲרֻבָּה פּוֹתֵחַ טֶפַח. אַף עַל פִּי שֶׁהַקְּדֵרָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה בְּתוֹכָהּ אוֹ עַל גַּבָּהּ אוֹ תַּחְתֶּיהָ הַבַּיִת טָהוֹר. הָיְתָה הַקְּדֵרָה מֻנַּחַת בְּצַד אַסְקֻפַּת הַבַּיִת שֶׁאִם תַּעֲלֶה נִמְצָא מִמֶּנָּה פּוֹתֵחַ טֶפַח לְפָנִים מִן הַמַּשְׁקוֹף. וְהָיְתָה טֻמְאָה רְצוּצָה תַּחְתֶּיהָ אוֹ בְּתוֹכָהּ אוֹ עַל גַּבָּהּ טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. הָיְתָה גְּבוֹהָה מִן הָאָרֶץ טֶפַח וְטֻמְאָה תַּחְתֶּיהָ אוֹ בַּבַּיִת. תַּחְתֶּיהָ וְהַבַּיִת טָמֵא שֶׁהַכּל אֹהֶל אֶחָד וְתוֹכָהּ וְגַבָּהּ טָהוֹר. הָיְתָה הַטֻּמְאָה בְּתוֹכָהּ אוֹ עַל גַּבָּהּ הַבַּיִת טָמֵא מִפְּנֵי שֶׁהִיא נוֹגַעַת בַּמַּשְׁקוֹף טֶפַח וְכֵן תַּחְתֶּיהָ טָמֵא מִפְּנֵי שֶׁהַטֻּמְאָה יוֹצְאָה לְתַחְתֶּיהָ מִן הַבַּיִת שֶׁהַכּל אֹהֶל אֶחָד. לְפִיכָךְ אִם לֹא הָיְתָה נוֹגַעַת בַּמַּשְׁקוֹף בְּפוֹתֵחַ טֶפַח אוֹ שֶׁהָיְתָה בְּצַד הַמַּשְׁקוֹף וְטֻמְאָה תַּחְתֶּיהָ אֵין טָמֵא אֶלָּא תַּחְתֶּיהָ אֲבָל הַבַּיִת טָהוֹר:","קוֹרוֹת הַבַּיִת וְהָעֲלִיָּה שֶׁאֵין עֲלֵיהֶם מַעֲזִיבָה וְהֵן מְכֻוָּנוֹת קוֹרָה כְּנֶגֶד קוֹרָה וַאֲוִיר כְּנֶגֶד אֲוִיר וּבְכָל קוֹרָה מֵהֶן פּוֹתֵחַ טֶפַח וּבֵינֵיהֶן אֲוִיר פּוֹתֵחַ טֶפַח וְטֻמְאָה תַּחַת אַחַת מֵהֶן. תַּחְתֶּיהָ בִּלְבַד טָמֵא. הָיְתָה הַטֻּמְאָה בֵּין הַתַּחְתּוֹנָה לָעֶלְיוֹנָה בֵּין שְׁתֵּיהֶן בִּלְבַד טָמֵא. הָיְתָה הַטֻּמְאָה עַל גַּבֵּי הָעֶלְיוֹנָה כְּנֶגְדּוֹ עַד לָרָקִיעַ טָמֵא. הָיוּ הַקּוֹרוֹת הָעֶלְיוֹנוֹת מְכֻוָּנוֹת כְּנֶגֶד הָאֲוִיר שֶׁבֵּין הַקּוֹרוֹת הַתַּחְתּוֹנוֹת וְטֻמְאָה תַּחַת אַחַת מֵהֶן תַּחַת כֻּלָּם טְמֵאָה. הָיְתָה הַטֻּמְאָה עַל גַּבֵּי קוֹרָה הָעֶלְיוֹנָה כְּנֶגֶד הַטֻּמְאָה עַד לָרָקִיעַ טָמֵא. אֵין בַּקּוֹרוֹת פּוֹתֵחַ טֶפַח בֵּין שֶׁהָיוּ מְכֻוָּנוֹת זֶה עַל גַּבֵּי זוֹ וּבֵין שֶׁהָיוּ הָעֶלְיוֹנוֹת כְּנֶגֶד אֲוִיר הַתַּחְתּוֹנוֹת וְהָיְתָה הַטֻּמְאָה תַּחְתֵּיהֶן אוֹ בֵּינֵיהֶן אוֹ עַל גַּבֵּיהֶן טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת וְאֵינָהּ מְטַמְּאָה אֶלָּא כְּנֶגְדָּהּ בִּלְבַד לְפִי שֶׁכָּל טֻמְאָה שֶׁאֵינָהּ תַּחַת פּוֹתֵחַ טֶפַח בְּרוּם טֶפַח הֲרֵי הִיא כִּרְצוּצָה. בַּיִת שֶׁנִּסְדַּק גַּגּוֹ וּכְתָלָיו וְנַעֲשָׂה שְׁנֵי חֲלָקִים וְהָיְתָה הַטֻּמְאָה בְּחֶצְיוֹ הַחִיצוֹן שֶׁהַפֶּתַח בּוֹ הַכֵּלִים שֶׁבְּחֶצְיוֹ הַפְּנִימִי כֻּלָּם טְהוֹרִין. הָיְתָה טֻמְאָה בְּחֶצְיוֹ הַפְּנִימִי אִם הָיָה רֹחַב הַסֶּדֶק כְּחוּט הַמִּשְׁקלֶת כֵּלִים שֶׁבְּחֶצְיוֹ הַחִיצוֹן טְהוֹרִין. וְאִם הָיָה פָּחוֹת מִכָּאן הֲרֵי הֵן טְמֵאִין:","אַכְסַדְרָה שֶׁנִּסְדְּקָה וְטֻמְאָה בְּצַד אֶחָד הַכֵּלִים שֶׁבַּצַּד הַשֵּׁנִי טְהוֹרִין שֶׁהֲרֵי הִיא שְׁנֵי אֹהָלִים זֶה בְּצַד זֶה וַאֲוִיר בֵּינֵיהֶן שֶׁהֲרֵי הַסֶּדֶק בְּכָל הַתִּקְרָה. נָתַן רַגְלוֹ אוֹ קָנֶה מִלְּמַעְלָה עַל הַסֶּדֶק עֵרֵב אֶת הַטֻּמְאָה. נָתַן אֶת הַקָּנֶה בָּאָרֶץ כְּנֶגֶד הַסֶּדֶק וַאֲפִלּוּ כְּלִי גָּדוֹל אֵינוֹ מְעָרֵב אֶת הַטֻּמְאָה עַד שֶׁיִּהְיֶה גָּבוֹהַּ טֶפַח תַּחַת הַסֶּדֶק. הָיָה אָדָם מֻטָּל עַל הָאָרֶץ תַּחַת הַסֶּדֶק מְעָרֵב אֶת הַטֻּמְאָה שֶׁאָדָם חָלוּל הוּא וְהַצַּד הָעֶלְיוֹן הֲרֵי הוּא כְּאֹהֶל שֶׁיֵּשׁ בּוֹ גֹּבַהּ טֶפַח. וְכֵן אִם הָיוּ תַּחַת הַסֶּדֶק כֵּלִים מְקֻפָּלִין מֻנָּחִין עַל הָאָרֶץ זֶה עַל גַּב זֶה וְהָיָה הָעֶלְיוֹן גָּבוֹהַּ מֵעַל הָאָרֶץ טֶפַח עֵרֵב אֶת הַטֻּמְאָה וְכָל הַכֵּלִים שֶׁלְּמַטָּה מִמֶּנּוּ הֲרֵי הֵן כְּכֵלִים שֶׁתַּחַת הָאֹהֶל:"],"Mishneh Torah, Defilement by a Corpse 4":["רְבִיעִית דָּם הַבָּאָה מִשְּׁנֵי מֵתִים טְהוֹרָה עַד שֶׁתִּהְיֶה כָּל הָרְבִיעִית מִמֵּת אֶחָד. שִׁדְרָה שֶׁנִּגְמְרָה מִשְּׁנֵי מֵתִים כְּגוֹן שֶׁהָיוּ מִקְצָת הַחֻלְיוֹת מֵאֶחָד וְתַשְׁלוּמָן מִמֵּת אַחֵר וְכֵן הַגֻּלְגּלֶת שֶׁל שְׁנֵי מֵתִים וְרֹבַע עֲצָמוֹת מִשְּׁנֵי מֵתִים וְאֵיבָר מִן הַמֵּת מִשְּׁנֵי מֵתִים כָּל אֵלּוּ אֵינָן מְטַמְּאִין בְּאֹהֶל אֶלָּא בְּמַגָּע וּבְמַשָּׂא כִּשְׁאָר כָּל עֲצָמוֹת:","אֵיבָר מִן הַחַי מִשְּׁנֵי אֲנָשִׁים טָהוֹר אֲפִלּוּ מֵאִישׁ אֶחָד אִם נֶחְלַק לִשְׁנַיִם טָהוֹר:","כְּזַיִת בָּשָׂר מִשְּׁנֵי מֵתִים וּכְזַיִת נֶצֶל מִשְּׁנֵי מֵתִים וּמְלֹא חָפְנַיִם רֶקֶב מִשְּׁנֵי מֵתִים שֶׁכָּל אֶחָד מֵהֶן יֵשׁ לוֹ רֶקֶב הֲרֵי אֵלּוּ מִצְטָרְפִין זֶה עִם זֶה. וְכֵן כַּחֲצִי זַיִת בָּשָׂר וְכַחֲצִי זַיִת נֶצֶל מִצְטָרְפִין זֶה עִם זֶה. וּשְׁאָר כָּל הַטֻּמְאוֹת שֶׁבַּמֵּת אֵין מִצְטָרְפִין זֶה עִם זֶה מִפְּנֵי שֶׁלֹּא שָׁווּ בְּשִׁעוּרֵיהֶן:","עֶצֶם כִּשְׂעוֹרָה שֶׁנֶּחְלָק לִשְׁנַיִם מְטַמֵּא בְּמַשָּׂא. וְכֵן רֹבַע עַצְמוֹת מֵת אֶחָד שֶׁנִּדַּקְדְּקוּ וְאֵין בְּכָל אֶחָד מֵהֶם עֶצֶם כִּשְׂעוֹרָה מְטַמְּאִין בְּאֹהֶל כְּאִלּוּ לֹא נִדַּקְדְּקוּ:","כְּזַיִת מִן הַמֵּת שֶׁחֲתָכוֹ לַחֲלָקִים וְרִדְּדוֹ וְדִבְּקוֹ מְטַמֵּא בְּאֹהֶל וּבְמַשָּׂא וְאֵינוֹ מְטַמֵּא בְּמַגָּע קְצָתוֹ אַף עַל פִּי שֶׁחִבְּרוֹ שֶׁאֵין חִבּוּרֵי אָדָם חִבּוּר:","כְּזַיִת חֵלֶב שָׁלֵם שֶׁהִתִּיכוֹ טָמֵא. הָיָה מְפֹרָד וְהִתִּיכוֹ טָהוֹר:","שִׁדְרָה שֶׁנִּגְרְרוּ מִמֶּנָּה רֹב חֻלְיוֹת שֶׁלָּהּ אַף עַל פִּי שֶׁשִּׁלְדָּהּ קַיֶּמֶת אֵינָהּ מְטַמְּאָה בְּאֹהֶל. וּבַזְּמַן שֶׁהִיא בְּתוֹךְ הַקֶּבֶר אֲפִלּוּ מְשֻׁבֶּרֶת אֲפִלּוּ מְכֻתֶּתֶת מְטַמְּאָה בְּאֹהֶל מִפְּנֵי שֶׁהַקֶּבֶר מְצָרְפָהּ:","כָּל הַמְטַמְּאִין בְּאֹהֶל שֶׁנֶּחְלְקוּ וְהִכְנִיסָן בְּתוֹךְ הַבַּיִת הָאֹהֶל מְצָרְפָן וּמְטַמְּאִין בְּאֹהֶל:","עֶצֶם שֶׁיֵּשׁ עָלָיו כְּזַיִת בָּשָׂר בִּידֵי שָׁמַיִם וְהִכְנִיס מִקְצָתוֹ לְפָנִים מִן הַבַּיִת נִטְמָא הַבַּיִת. שְׁנֵי עֲצָמוֹת וַעֲלֵיהֶם כִּשְׁנֵי חֲצָיֵי זֵיתִים בָּשָׂר וְהִכְנִיס מִקְצָתָן לִפְנִים הַבַּיִת טָמֵא. וְאִם הָיָה הַבָּשָׂר תָּחוּב בָּעֲצָמוֹת בִּידֵי אָדָם הַבַּיִת טָהוֹר שֶׁאֵין חִבּוּרֵי אָדָם חִבּוּר:","מְלֹא חָפְנַיִם רֶקֶב שֶׁנִּתְפַּזֵּר בְּתוֹךְ הַבַּיִת הַבַּיִת טָמֵא:","רְבִיעִית דָּם שֶׁנִּבְלְעָה בְּתוֹךְ הַבַּיִת הַבַּיִת טָהוֹר לְהַבָּא וְכָל שֶׁהָיָה בּוֹ בְּעֵת שֶׁנִּבְלְעָה הָרְבִיעִית בָּאָרֶץ טָמֵא:","כְּזַיִת מִן הַמֵּת שֶׁאָבַד בְּתוֹךְ הַבַּיִת וּבִקֵּשׁ וְלֹא נִמְצָא, הַבַּיִת טָהוֹר. וְלִכְשֶׁיִּמָּצֵא הַבַּיִת טָמֵא לְמַפְרֵעַ מֵעֵת שֶׁאָבַד עַד שֶׁנִּמְצָא:","רְבִיעִית דָּם שֶׁנִּשְׁפַּךְ בָּאֲוִיר אִם קָרַשׁ אוֹ שֶׁהָיָה בִּמְקוֹם אַשְׁבֹּרֶן וְהוּא הַמָּקוֹם הַנָּמוּךְ כְּמוֹ גֻּמָּא וְהֶאֱהִיל הַמַּאֲהִיל עַל מִקְצָתוֹ נִטְמָא. נִשְׁפַּךְ עַל הָאַסְקֻפָּה בַּמּוֹרָד בֵּין לְפָנִים בֵּין לַחוּץ הַבַּיִת טָהוֹר. שֶׁהֲרֵי לֹא נָח הַדָּם עַל הָאַסְקֻפָּה. וְאִם הָיְתָה הָאַסְקֻפָּה אַשְׁבֹּרֶן אוֹ שֶׁקָּרַשׁ הַדָּם עָלֶיהָ הַבַּיִת טָמֵא. רְבִיעִית דָּם שֶׁנִּבְלְעָה בִּכְסוּת אִם מִתְכַּבֶּסֶת וְיוֹצְאָה מִמֶּנּוּ רְבִיעִית דָּם הֲרֵי זוֹ הַכְּסוּת מִתְטַמְּאָה בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל וְאִם לָאו אֵינָהּ מִתְטַמְּאָה בְּאֹהֶל וַהֲרֵי הִיא כִּכְסוּת שֶׁנָּגְעָה בְּמֵת שֶׁכָּל הַבָּלוּעַ שֶׁאֵינוֹ יָכוֹל לָצֵאת טָהוֹר. כֵּיצַד מְשַׁעֲרִין אוֹתָהּ. מְכַבְּסִין אוֹתָהּ בְּמַיִם וּמֵבִיא מַיִם כְּמִדָּתָן וְנוֹתֵן לְתוֹכָן רְבִיעִית דָּם אִם הָיָה מַרְאֵיהֶן שָׁוֶה אוֹ שֶׁהָיָה מֵי הַכִּבּוּס אָדֹם יוֹתֵר מִמֵּי הַמֶּזֶג בְּיָדוּעַ שֶׁיָּצָא מִמֶּנָּה רְבִיעִית:","הַמַּשָּׂא וְהַמַּגָּע וְהָאֹהֶל שְׁלֹשָׁה שֵׁמוֹת הֵם. וְכָל שֶׁהוּא מִשֵּׁם אֶחָד מִצְטָרֵף וּמְטַמֵּא. וּמִשְּׁנֵי שֵׁמוֹת אֵינוֹ מִצְטָרֵף וְטָהוֹר. כֵּיצַד. הַנּוֹגֵעַ בְּכִשְׁנֵי חֲצָאֵי זֵיתִים אוֹ שֶׁנָּשָׂא שְׁנֵי חֲצָאֵי זֵיתִים בְּבַת אַחַת. אוֹ שֶׁהֶאֱהִיל עַל כִּשְׁנֵי חֲצָאֵי זֵיתִים. אוֹ שֶׁהֶאֱהִיל עַל חֲצִי זַיִת וַחֲצִי זַיִת אַחֵר מַאֲהִיל עָלָיו. אוֹ שֶׁהָיָה הוּא וַחֲצִי זַיִת תַּחַת הָאֹהֶל וְהֶאֱהִיל בְּמִקְצָת גּוּפוֹ עַל חֲצִי זַיִת אַחֵר. אוֹ הֶאֱהִיל חֲצִי זַיִת עַל מִקְצָתוֹ. הַכּל טְמֵאִים מִפְּנֵי שֶׁהוּא שֵׁם אֶחָד. אֲבָל הַנּוֹגֵעַ בַּחֲצִי זַיִת אוֹ הַנּוֹשֵׂא חֲצִי זַיִת וְדָבָר אַחֵר מַאֲהִיל עָלָיו וְעַל כַּחֲצִי זַיִת. אוֹ שֶׁהֶאֱהִיל עָלָיו חֲצִי זַיִת אַחֵר. אוֹ שֶׁהֶאֱהִיל הוּא עַל חֲצִי זַיִת אַחֵר. וְכֵן הַנּוֹשֵׂא כַּחֲצִי זַיִת וְנָגַע בַּחֲצִי זַיִת אַחֵר. הַכּל טְהוֹרִים. שֶׁאֵין הַמַּגָּע מִצְטָרֵף עִם הַמַּשָּׂא לֹא בְּמֵת וְלֹא בִּשְׁאָר טֻמְאוֹת. וְלֹא הַמַּגָּע מִצְטָרֵף עִם הָאֹהֶל וְלֹא הָאֹהֶל מִצְטָרֵף עִם הַמַּשָּׂא [לְפִי שֶׁאֵינוֹ שֵׁם אֶחָד]:"],"Mishneh Torah, Defilement of Foods 15":["מַיִם שֶׁבַּכֵּלִים מִתְטַמְּאִין בִּין לְרָצוֹן בֵּין שֶׁלֹּא לְרָצוֹן וּמְטַמְּאִין אֳכָלִים וְכֵלִים בֵּין שֶׁנָּפַל עֲלֵיהֶן בְּרָצוֹן בֵּין שֶׁלֹּא נָפַל עֲלֵיהֶן בְּרָצוֹן. אֲבָל מַיִם שֶׁבַּקַּרְקָעוֹת כְּגוֹן מֵי בּוֹרוֹת שִׁיחִין וּמְעָרוֹת וּמֵי גְּבָאִים שֶׁאֵין בָּהֶם אַרְבָּעִים סְאָה אֵין מִתְטַמְּאִין אֶלָּא לְרָצוֹן וְאֵין מְטַמְּאִין אֶלָּא בְּרָצוֹן. כֵּיצַד. מַיִם שֶׁבַּקַּרְקַע שֶׁאֵין בָּהֶן אַרְבָּעִים סְאָה בֵּין שֶׁהָיוּ שְׁאוּבִין בֵּין שֶׁאֵינָן שְׁאוּבִין שֶׁנָּפַל לְתוֹכָן הַמֵּת אוֹ שֶׁהָלַךְ בָּהֶן הַטָּמֵא הֲרֵי אֵלּוּ טְהוֹרִין. אֲבָל אִם שָׁתָה מֵהֶן אָדָם טָמֵא אוֹ שֶׁמִּלֵּא בָּהֶן בִּכְלִי טָמֵא אוֹ שֶׁנָּפְלוּ לְתוֹכָן מַשְׁקִין טְמֵאִין בְּרָצוֹן הֲרֵי אֵלּוּ טְמֵאִין וְאַף עַל פִּי שֶׁהֵן בַּקַּרְקַע. שָׁתָה מֵהֶן הַטָּהוֹר אַחַר שֶׁנִּטְמְאוּ בַּקַּרְקַע אוֹ שֶׁמִּלֵּא בָּהֶן בִּכְלִי טָהוֹר נִטְמָא הַשּׁוֹתֶה וְנִטְמָא הַכְּלִי שֶׁהֲרֵי בְּרָצוֹן שָׁתָה אוֹ מִלֵּא. נָפַל לְתוֹכָן כִּכָּר שֶׁל תְּרוּמָה הֲרֵי הוּא טָהוֹר כְּשֶׁהָיָה שֶׁאֵין מִתְטַמְּאִין אֶלָּא לְרָצוֹן. לְפִיכָךְ אִם הֵדִיחַ יָדוֹ וְהוֹצִיא הַכִּכָּר נִטְמָא הַכִּכָּר בַּמַּיִם שֶׁבְּיָדָיו שֶׁהֲרֵי הֵן בְּרָצוֹן:","מֵי גְּבָאִים וְכַיּוֹצֵא בָּהֶן מִמַּיִם שֶׁבַּקַּרְקָעוֹת כְּגוֹן מֵי בּוֹרוֹת שִׁיחִין וּמְעָרוֹת וּמֵי תַּמְצִית שֶׁפָּסְקוּ וּמִקְוָאוֹת שֶׁאֵין בָּהֶן אַרְבָּעִים סְאָה שֶׁנִּטְמְאוּ וְיָרְדוּ לָהֶם גְּשָׁמִים וְרַבּוּ מֵי גְּשָׁמִים עֲלֵיהֶם אַף עַל פִּי שֶׁלֹּא שָׁטְפוּ הֲרֵי הֵן טְהוֹרִין לְפִיכָךְ כָּל הַמַּיִם שֶׁבַּקַּרְקָעוֹת כְּגוֹן מֵי גְּבָאִים וְכַיּוֹצֵא בָּהֶן בִּשְׁעַת הַגְּשָׁמִים הַכּל בְּחֶזְקַת טָהֳרָה:","פָּסְקוּ הַגְּשָׁמִים הַקְּרוֹבִים לָעִיר אוֹ לַדֶּרֶךְ טְמֵאִין שֶׁהֵן בְּחֶזְקַת שֶׁשָּׁתָה מֵהֶן הַטָּמֵא וְשֶׁמִּלְּאוּ מֵהֶן בְּכֵלִים טְמֵאִין. וְהָרְחוֹקִים טְהוֹרִים עַד שֶׁיְּהַלְּכוּ רֹב הָאָדָם. הָלְכוּ הַכּל בְּחֶזְקַת טֻמְאָה שֶׁהַהוֹלְכִים בַּשַּׁיָּרוֹת מְמַלְּאִין וְשׁוֹתִין מֵהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּגֶבֶא שֶׁאֶפְשָׁר לִשְׁתּוֹת מִמֶּנָּה. אֲבָל בְּגֶבֶא שֶׁאִי אֶפְשָׁר לִשְׁתּוֹת מִמֶּנָּה אֶלָּא בְּדֹחַק גָּדוֹל הֲרֵי זוֹ בְּחֶזְקַת טָהֳרָה (שֶׁהֵן בְּחֶזְקַת טְהוֹרִין) עַד שֶׁיִּמְצָא מְקוֹם פַּרְסוֹת רַגְלֵי אָדָם אוֹ פַּרְסוֹת רַגְלֵי בְּהֵמָה גַּסָּה נִכֶּרֶת בּוֹ אֲבָל מָצָא פַּרְסוֹת רַגְלֵי בְּהֵמָה דַּקָּה הֲרֵי זֶה טָהוֹר שֶׁאֶפְשָׁר שֶׁיָּרְדָה וְשָׁתַת:","חֶזְקַת טִיט וּגְמוּמִיּוֹת שֶׁבְּפִתְחֵי חֲנֻיּוֹת בִּרְשׁוּת הָרַבִּים בִּשְׁעַת הַגְּשָׁמִים שֶׁהֵן טְהוֹרִין. פָּסְקוּ הַגְּשָׁמִים הֲרֵי הֵן כְּמֵי שְׁפִיכוֹת. וְשֶׁבַּשְּׁוָקִין הוֹלְכִין בָּהֶן אַחַר הָרֹב. גֶּבֶא שֶׁנָּפַל לְתוֹכוֹ יַיִן אוֹ חָלָב אוֹ דְּבַשׁ הוֹלְכִין בּוֹ אַחַר הָרֹב. נָפַל לְתוֹכוֹ שֶׁמֶן אַף עַל פִּי שֶׁהִקְפִּיאָהוּ הֲרֵי זֶה מִתְטַמֵּא וּמְטַמֵּא שֶׁלֹּא בְּרָצוֹן לְפִי שֶׁאִי אֶפְשָׁר לוֹ לָצֵאת יְדֵי צַחְצָחִית:","שֶׁמֶן וּשְׁאָר הַמַּשְׁקִין חוּץ מִן הַמַּיִם הֲרֵי הֵן בַּקַּרְקַע כְּמוֹת שֶׁהֵן בְּכֵלִים דִּין אֶחָד הוּא:","מֵי תַּמְצִית שֶׁלֹּא פָּסְקוּ אַף עַל פִּי שֶׁאֵין בָּהֶן אַרְבָּעִים סְאָה הוֹאִיל וְהֵן בַּקַּרְקַע וַהֲרֵי הַמַּיִם נִמְשָׁכִין וּבָאִין לָהֶן אֵינָן מְקַבְּלִין טֻמְאָה. וְאַף עַל פִּי שֶׁשָּׁתָה מֵהֶן הַטָּמֵא וּמִלֵּא מֵהֶן בִּכְלִי טָמֵא אוֹ נָתַן לְתוֹכָן מַיִם טְמֵאִים הֲרֵי הֵן טְהוֹרִין לְכָל דָּבָר:","מִי שֶׁהָיָה אוֹכֵל תְּרוּמָה בְּיָדַיִם טְמֵאוֹת כְּגוֹן דְּבֵלָה שֶׁלֹּא הֻכְשְׁרָה וְהִכְנִיס יָדוֹ לְתוֹךְ פִּיו לִטּל צְרוֹר אִם הָפַךְ נִטְמֵאת הַדְּבֵלָה בְּרִירוֹ שֶׁהֲרֵי נִטְמָא בַּיָּד מִפְּנֵי שֶׁעֲקָרוֹ. וְאִם לֹא הָפַךְ טְהוֹרָה שֶׁהַמַּשְׁקֶה שֶׁבְּפִיו קֹדֶם שֶׁיְּהַפְּכֶנּוּ אוֹ יְמוֹצְצֶנּוּ לְהוֹצִיאוֹ דּוֹמֶה לְמַיִם שֶׁלֹּא נִתְלְשׁוּ אֶלָּא הֵן עֲדַיִן בַּקַּרְקַע שֶׁאֵין מִתְטַמְּאִין וְאֵין מְטַמְּאִין אֶלָּא בְּרָצוֹן כְּמוֹ שֶׁבֵּאַרְנוּ. וְזֶה אֵין רְצוֹנוֹ אֶלָּא לִטּל הַצְּרוֹר. הָיָה פּוּנְדְיוֹן לְתוֹךְ פִּיו וּפָשַׁט יָדוֹ לִטְּלוֹ וְהַדְּבֵלָה בְּתוֹךְ פִּיו אִם הִנִּיחוֹ לִצְמָאוֹ הֲרֵי זֶה הָרֹק כְּעָקוּר וְנִטְמֵאת הַדְּבֵלָה מֵחֲמַת מַשְׁקֵה פִּיו שֶׁנִּטְמָא מֵחֲמַת יָדָיו:","הָאִשָּׁה שֶׁהָיְתָה אוֹכֶלֶת אֳכָלִין שֶׁל תְּרוּמָה שֶׁאֵינָן מֻכְשָׁרִין וְהָיְתָה גּוֹרֶפֶת אֶת הַתַּנּוּר הַטָּמֵא וְהִכָּה הַקּוֹץ וְיָצָא מִמֶּנָּה דָּם וּמָצְצָה אֶצְבָּעָהּ מִפְּנֵי הַדָּם אוֹ שֶׁנִּכְוֵית וְנָתְנָה אֶצְבָּעָהּ בְּפִיהָ נִטְמֵאת הַתְּרוּמָה שֶׁבְּפִיהָ. שֶׁהֲרֵי רְצוֹנָהּ לְהוֹצִיא הַמַּשְׁקֶה מִפִּיהָ וּלְעָקְרוֹ בִּמְצִיצַת אֶצְבַּע:"],"Mishneh Torah, Diverse Species 2":["זֶרַע שֶׁנִּתְעָרֵב בּוֹ זֶרַע אַחֵר אִם הָיוּ אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה כְּגוֹן סְאָה שֶׁל חִטִּים שֶׁנִּתְעָרְבָה בְּעֶשְׂרִים וְשָׁלֹשׁ סְאָה שֶׁל שְׂעוֹרִים הֲרֵי זֶה אָסוּר לִזְרֹעַ אֶת הַמְעֹרָב עַד שֶׁיְּמַעֵט אֶת הַחִטִּין אוֹ יוֹסִיף עַל הַשְּׂעוֹרִים וְאִם זָרַע לוֹקֶה:","וְכָל שֶׁהוּא כִּלְאַיִם עִם הַזֶּרַע מִצְטָרֵף לְאֶחָד מֵעֶשְׂרִים וְאַרְבַּע. כֵּיצַד. עֶשְׂרִים וְשָׁלֹשׁ סְאָה שֶׁל חִטִּים שֶׁנִּתְעָרֵב בָּהּ שְׁנֵי קַבִּין שְׂעוֹרִים וּשְׁנֵי קַבִּין עֲדָשִׁים וּשְׁנֵי קַבִּין פּוֹלִים הֲרֵי זֶה לֹא יִזְרַע הַכּל עַד שֶׁיְּמַעֵט סְאָה שֶׁל תַּעֲרֹבֶת וְיָבֹר מִקְצָתָהּ אוֹ יוֹסִיף עַל הַחִטִּים. שֶׁהַשְּׂעוֹרִים וְהָעֲדָשִׁים וְהַפּוֹל כֻּלָּם כִּלְאַיִם עִם הַחִטִּים:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁנִּתְעָרְבוּ מִינֵי תְּבוּאָה זֶה בָּזֶה אוֹ מִינֵי קִטְנִיּוֹת זֶה בָּזֶה אוֹ שֶׁנִּתְעָרְבָה תְּבוּאָה בְּקִטְנִיּוֹת אוֹ קִטְנִיּוֹת בִּתְבוּאָה. אֲבָל זֵרְעוֹנֵי גִּנָּה שֶׁנִּתְעָרֵב אֶחָד מֵהֶן בִּתְבוּאָה אוֹ בְּקִטְנִיּוֹת שִׁעוּרָן אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה מִמַּה שֶּׁזּוֹרְעִין בְּבֵית סְאָה מֵאוֹתוֹ הַמִּין אִם נִתְעָרֵב בִּסְאָה שֶׁל תְּבוּאָה אוֹ קִטְנִית לֹא יִזְרַע עַד שֶׁיְּמַעֵט אוֹ יוֹסִיף עַל הַתְּבוּאָה:","כֵּיצַד. חַרְדָּל שֶׁנִּתְעָרֵב בִּתְבוּאָה וַהֲרֵי הַחַרְדָּל זוֹרְעִין מִמֶּנּוּ קַב בְּכָל בֵּית סְאָה אִם נִתְעָרֵב מִמֶּנּוּ אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה מִן הַקַּב בִּסְאָה שֶׁל תְּבוּאָה אוֹ שֶׁל קִטְנִית חַיָּב לְמַעֵט. וְכֵן אִם הָיָה מִין זֶה מִזֵּרְעוֹנֵי גִּנָּה זוֹרְעִין מִמֶּנּוּ סָאתַיִם בְּכָל בֵּית סְאָה אִם נִתְעָרֵב מִמֶּנּוּ חֲצִי קַב בְּכָל סְאָה שֶׁל תְּבוּאָה אוֹ שֶׁל קִטְנִית יְמַעֵט:","לְפִיכָךְ תְּבוּאָה שֶׁנִּתְעָרֵב בָּהּ זֶרַע פִּשְׁתָּן אִם הָיָה שְׁלֹשֶׁת רְבִיעִים בְּכָל סְאָה הֲרֵי זֶה יְמַעֵט. וְאִם לָאו אֵינוֹ צָרִיךְ לְמַעֵט. לְפִי שֶׁבֵּית סְאָה זוֹרְעִין בּוֹ שָׁלֹשׁ סְאִים זֶרַע פִּשְׁתָּן. וְעַל דֶּרֶךְ זֶה מְשַׁעֲרִים בְּכָל הַזְּרָעִים הָאֲחֵרִים:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא נִתְכַּוֵּן לְעָרֵב וּבְשֶׁלֹּא נִתְכַּוֵּן לִזְרֹעַ הַשְּׁנֵי מִינִין שֶׁנִּתְעָרְבוּ. אֲבָל אִם נִתְכַּוֵּן לְעָרֵב זֶרַע בְּזֶרַע אַחֵר אוֹ לִזְרֹעַ הַשְּׁנֵי מִינִין אֲפִלּוּ הָיְתָה חִטָּה אַחַת בְּתוֹךְ כְּרִי שֶׁל שְׂעוֹרִים אֲסוּרָה לְזָרְעָהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַזּוֹרֵעַ שָׂדֵהוּ מִין מִן הַמִּינִין וּכְשֶׁיִּצְמַח רָאָה בּוֹ כִּלְאַיִם. אִם הָיָה הַמִּין הָאֶחָד אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה בַּשָּׂדֶה הֲרֵי זֶה יִלְקֹט עַד שֶׁיְּמַעֲטֶנּוּ מִפְּנֵי מַרְאִית הָעַיִן. שֶׁמָּא יֹאמְרוּ כִּלְאַיִם זָרַע בְּכַוָּנָה. בֵּין שֶׁהָיָה הַמִּין הָאֶחָד שֶׁצָּמַח תְּבוּאָה וְקִטְנִית בִּתְבוּאָה וְקִטְנִית. אוֹ זֵרְעוֹנֵי גִּנָּה בִּתְבוּאָה וְקִטְנִית וּבְזֵרְעוֹנֵי גִּנָּה. וְאִם הָיָה הַצּוֹמֵחַ פָּחוֹת מִיכַּן אֵינוֹ צָרִיךְ לְמַעֲטוֹ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁיֵּשׁ מָקוֹם לַחֲשָׁד. אֲבָל בִּזְמַן שֶׁהַדְּבָרִים מַרְאִין שֶׁאֵין זֶה מִדַּעְתּוֹ שֶׁל בַּעַל הַשָּׂדֶה אֶלָּא מֵאֲלֵיהֶן עָלוּ אֵין מְחַיְּבִין אוֹתוֹ לְמַעֵט:","כֵּיצַד. כְּגוֹן תְּבוּאָה שֶׁעָלוּ בָּהּ סְפִיחֵי אִסְטִיס וְתִלְתָּן שֶׁזְּרָעָהּ לְמַאֲכַל אָדָם שֶׁעָלוּ בָּהּ מִינֵי עֲשָׂבִים שֶׁזֶּה מַפְסִיד הוּא. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּבְמַה יִּוָּדַע שֶׁהַתִּלְתָּן זְרוּעָה לְמַאֲכַל אָדָם. כְּשֶׁהָיְתָה זְרוּעָה עֲרוּגוֹת עֲרוּגוֹת וְלָהּ גְּבוּל סָבִיב. וְכֵן מְקוֹם הַגֳּרָנוֹת שֶׁעָלוּ בָּהּ מִינִין הַרְבֵּה אֵין מְחַיְּבִין אוֹתוֹ לַעֲקֹר. שֶׁהֲרֵי הַדָּבָר יָדוּעַ שֶׁאֵינוֹ רוֹצֶה שֶּׁיִּצְמַח צֶמַח בִּמְקוֹם הַגֳּרָנוֹת. וְאִם הֵסִיר מִקְצָתָן אוֹמְרִין לוֹ עֲקֹר הַכּל חוּץ מִמִּין אֶחָד שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁרוֹצֶה בְּקִיּוּם הַשְּׁאָר:","אֵין נוֹטְעִין יְרָקוֹת בְּתוֹךְ סַדָּן שֶׁל שִׁקְמָה וְכַיּוֹצֵא בָּהּ. הַטּוֹמֵן אֲגֻדַּת לֶפֶת וּצְנוֹן וְכַיּוֹצֵא בָּהּ תַּחַת הָאִילָן אֲפִלּוּ תַּחַת הַגֶּפֶן. אִם הָיוּ מִקְצָת הֶעָלִין מְגֻלִּין אֵינוֹ חוֹשֵׁשׁ שֶׁהֲרֵי אֵינוֹ רוֹצֶה בְּהַשְׁרָשָׁתָן וְאִם אֵינָן אֲגֻדָּה אוֹ שֶׁלֹּא הָיוּ הֶעָלִין מְגֻלִּין חוֹשֵׁשׁ מִשּׁוּם כִּלְאַיִם:","שָׂדֶה שֶׁהָיְתָה זְרוּעָה וְקָצַר הַזֶּרַע וְנִשְׁאֲרוּ הָעִקָּרִין בָּאָרֶץ אַף עַל פִּי שֶׁאֵין מוֹצִיאִין צֶמַח אֶלָּא אַחַר כַּמָּה שָׁנִים לֹא יִהְיֶה זוֹרֵעַ בְּאוֹתָהּ שָׂדֶה מִין אַחֵר עַד שֶׁיַּעֲקֹר הָעִקָּרִין:","הָיְתָה שָׂדֵהוּ זְרוּעָה חִטִּים וְנִמְלַךְ לְזָרְעָהּ שְׂעוֹרִים קֹדֶם שֶׁיִּצְמְחוּ הַחִטִּים. יַמְתִּין לָהּ עַד שֶׁיִּפָּסְדוּ הַחִטִּים וְיַתְלִיעוּ בָּאָרֶץ כְּמוֹ שְׁלֹשָׁה יָמִים אִם הָיְתָה שָׂדֵהוּ רָוָה וְאַחַר כָּךְ יְהַפְּכֶהָ בְּמַחְרֵשָׁה וְיִזְרַע הַמִּין הָאַחֵר. וְאֵינוֹ צָרִיךְ לְהַפֵּךְ אֶת כֻּלָּהּ עַד שֶׁלֹּא תִּשָּׁאֵר חִטָּה שֶׁלֹּא נֶעֶקְרָה אֶלָּא חוֹרֵשׁ אֶת הַשָּׂדֶה כְּדֶרֶךְ שֶׁחוֹרְשִׁין אוֹתָהּ קֹדֶם הַמָּטָר כְּדֵי שֶׁתִּרְוֶה:","צָמְחוּ הַחִטִּים וְאַחַר כָּךְ נִמְלַךְ לְזָרְעָהּ שְׂעוֹרִים יַהֲפֹךְ וְאַחַר כָּךְ יִזְרַע. וְאִם הוֹרִיד בְּהֶמְתּוֹ לְתוֹכָהּ וְקִרְסְמָה אֶת הַצֶּמַח הֲרֵי זֶה מֻתָּר לִזְרֹעַ שָׁם מִין אַחֵר:","בְּאֶחָד בַּאֲדָר מַשְׁמִיעִין עַל הַכִּלְאַיִם. וְכָל אָדָם יוֹצֵא לְגִנָּתוֹ וּלְשָׂדֵהוּ וּמְנַקִּין אוֹתוֹ מִן הַכִּלְאַיִם. וּבַחֲמִשָּׁה עָשָׂר בּוֹ יוֹצְאִים שְׁלוּחֵי בֵּית דִּין וּמְסַבְּבִים לִבְדֹּק:","בָּרִאשׁוֹנָה הָיוּ עוֹקְרִין וּמַשְׁלִיכִין וְהָיוּ בַּעֲלֵי בָּתִּים שְׂמֵחִים שֶׁמְּנַקִּין לָהֶן שְׂדוֹתֵיהֶן. הִתְקִינוּ שֶׁיִּהְיוּ מַפְקִירִין אֶת כָּל הַשָּׂדֶה שֶׁיִּמְצְאוּ בּוֹ כִּלְאַיִם. וְהוּא שֶׁיִּמְצְאוּ בָּהּ מִין אַחֵר אֶחָד מֵאַרְבָּעָה וְעֶשְׂרִים אֲבָל פָּחוֹת מִיכַּן לֹא יִגְּעוּ בָּהּ:","וְחוֹזְרִין שְׁלוּחֵי בֵּית דִּין בְּחֻלּוֹ שֶׁל מוֹעֵד הַפֶּסַח לִרְאוֹת הָאֲפִיל שֶׁיָּצָא. וְכִלְאַיִם שֶׁהֵנֵצּוּ אֵין מַמְתִּינִים לָהֶן אֶלָּא יוֹצְאִין עֲלֵיהֶן מִיָּד וּמַפְקִירִין אֶת כָּל הַשָּׂדֶה אִם יֵשׁ בָּהּ אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה:"],"Mishneh Torah, Divorce 13":["הָאִשָּׁה שֶׁאָמְרָה לְבַעְלָהּ גֵּרַשְׁתַּנִי בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי וּבָאוּ אוֹתָן הָעֵדִים וְהִכְחִישׁוּהָ וְאַחַר כָּךְ הָלְכָה הִיא וּבַעְלָהּ וְשָׁלוֹם בָּעוֹלָם וּבָאָה וְאָמְרָה מֵת בַּעְלִי אֵינָהּ נֶאֱמֶנֶת. שֶׁזּוֹ הֻחְזְקָה שַׁקְרָנִית וְרוֹצָה לְהִשָּׁמֵט מִתַּחַת בַּעְלָהּ. בָּא עֵד אֶחָד וְהֵעִיד לָהּ שֶׁמֵּת בַּעְלָהּ לֹא תִּנָּשֵׂא שֶׁמָּא הִיא שָׂכְרָה אוֹתוֹ. וְאִם נִשֵּׂאת לֹא תֵּצֵא שֶׁהֲרֵי יֵשׁ לָהּ עֵד:","וְכֵן אִם הָיְתָה מִלְחָמָה בָּעוֹלָם וּבָאָה וְאָמְרָה מֵת בַּעְלִי בַּמִּלְחָמָה אֵינָהּ נֶאֱמֶנֶת וְאַף עַל פִּי שֶׁהָיָה שָׁלוֹם בֵּינוֹ לְבֵינָהּ (שֶׁמָּא) תִּסְמֹךְ דַּעְתָּהּ עַל דְּבָרִים שֶׁרֻבָּן לְמִיתָה וְתֹאמַר מֵת כְּגוֹן שֶׁנֶּהֶרְגוּ הָרִאשׁוֹנִים וְהָאַחֲרוֹנִים שֶׁהָיָה בַּעְלָהּ בְּאֶמְצָעָן שֶׁהֲרֵי הִיא אוֹמֶרֶת מֵאַחַר שֶׁנֶּהֶרְגוּ אֵלּוּ וְאֵלּוּ נֶהֱרַג הוּא בִּכְלָלָן. לְפִיכָךְ אֵינָהּ נֶאֱמֶנֶת וַאֲפִלּוּ אָמְרָה מֵת בַּמִּלְחָמָה וּקְבַרְתִּיו. אֲבָל אִם אָמְרָה מֵת עַל מִטָּתוֹ נֶאֱמֶנֶת:","לֹא הֻחְזְקָה מִלְחָמָה בָּעוֹלָם וּבָאָה וְאָמְרָה מִלְחָמָה הָיְתָה בְּמָקוֹם פְּלוֹנִי וּמֵת בַּמִּלְחָמָה לֹא תִּנָּשֵׂא לְכַתְּחִלָּה. וְאִם נִשֵּׂאת לֹא תֵּצֵא:","וְכֵן הָאִשָּׁה שֶׁאָמְרָה מֵת בַּעְלִי תַּחַת הַמַּפּלֶת אֵינָהּ נֶאֱמֶנֶת. וְכֵן אִם הָיָה שִׁלּוּחַ נְחָשִׁים וְעַקְרַבִּים וְאָמְרָה נְשָׁכוֹ נָחָשׁ אוֹ עַקְרָב וָמֵת אֵינָהּ נֶאֱמֶנֶת. שֶׁמָּא תִּסְמֹךְ דַּעְתָּהּ עַל רֹב אֲנָשִׁים שֶׁמֵּתוּ כָּךְ בִּנְשִׁיכָה:","אָמְרָה עִשְּׁנוּ עָלֵינוּ בַּיִת אוֹ מְעָרָה הוּא מֵת וַאֲנִי נִצַּלְתִּי אֵינָהּ נֶאֱמֶנֶת. כְּשֵׁם שֶׁנַּעֲשָׂה לָהּ נֵס כָּךְ נַעֲשָׂה לוֹ. הָיְתָה שְׁנַת רְעָבוֹן וְאָמְרָה מֵת בַּעְלִי אֵינָהּ נֶאֱמֶנֶת. מֵת וּקְבַרְתִּיו נֶאֱמֶנֶת:","אָמְרָה נָפְלוּ עָלֵינוּ עַכּוּ״‎ם אוֹ לִסְטִים הוּא נֶהֱרַג וַאֲנִי נִצַּלְתִּי נֶאֱמֶנֶת. שֶׁאֵין דַּרְכָּן לַהֲרֹג אֶת הַנָּשִׁים כְּדֵי שֶׁנֹּאמַר כְּשֵׁם שֶׁנִּצְּלָה הִיא כָּךְ נִצַּל הוּא:","הָיָה דֶּבֶר בָּעוֹלָם וְאָמְרָה מֵת בַּעְלִי נֶאֱמֶנֶת שֶׁדָּבָר פָּשׁוּט בְּפִי כָּל אָדָם שֶׁבִּשְׁנַת הַדֶּבֶר זֶה חַי וְזֶה מֵת. וְאֶפְשָׁר שֶׁיָּמוּתוּ בַּדֶּבֶר נְעָרִים חֲזָקִים וְיִנָּצְלוּ הַזְּקֵנִים הַחוֹלִים. וּלְפִי זֶה אֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא סָמְכָה דַּעְתָּהּ עַל רֹב הַמֵּתִים:","כְּבָר אָמַרְנוּ שֶׁעֵד מִפִּי עֵד כָּשֵׁר לְעֵדוּת אִשָּׁה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁשָּׁמַע מִפִּי בֶּן דַּעַת שֶׁמֵּת פְּלוֹנִי כְּגוֹן עֶבֶד אוֹ שִׁפְחָה. אֲבָל אִם שָׁמַע מִפִּי שׁוֹטֶה אוֹ מִפִּי קָטָן אֵינוֹ מֵעִיד וְאֵין סוֹמְכִין עַל דִּבְרֵיהֶם:","שָׁמַע מִן הַתִּינוֹקוֹת שֶׁהֵן אוֹמְרִין עַכְשָׁו בָּאנוּ מֵהֶסְפֵּד פְּלוֹנִי כָּךְ וְכָךְ סַפְדָּנִין הָיוּ שָׁם וּפְלוֹנִי הֶחָכָם וּפְלוֹנִי עָלָה אַחַר מִטָּתוֹ כָּךְ וְכָךְ עָשׂוּ בְּמִטָּתוֹ הֲרֵי זֶה מֵעִיד מִפִּיהֶן עַל פִּי הַדְּבָרִים הָאֵלּוּ וְכַיּוֹצֵא בָּהֶן וּמַשִּׂיאִין אֶת אִשְׁתּוֹ:","יִשְׂרָאֵל שֶׁאָמַר הָרַגְתִּי אֶת פְּלוֹנִי הֲרֵי זוֹ תִּנָּשֵׂא עַל פִּיו שֶׁאֵין אָדָם מֵשִׂים עַצְמוֹ רָשָׁע וַהֲרֵי הֵעִיד שֶׁמֵּת:","כְּבָר אָמַרְנוּ שֶׁהָעַכּוּ״‎ם שֶׁהֵסִיחַ לְפִי תֻּמּוֹ מַשִּׂיאִין עַל פִּיו. כֵּיצַד. הָיָה עַכּוּ״‎ם מֵסִיחַ וְאָמַר אוֹי לִפְלוֹנִי שֶׁמֵּת כַּמָּה הָיָה נָאֶה וְכַמָּה טוֹבָה עָשָׂה עִמִּי. אוֹ שֶׁהָיָה מֵסִיחַ וְאוֹמֵר כְּשֶׁהָיִיתִי בָּא בַּדֶּרֶךְ נָפַל פְּלוֹנִי שֶׁהָיָה מְהַלֵּךְ עִמָּנוּ וָמֵת וּתְמֵהַנִי לְדָבָר זֶה כֵּיצַד מֵת פִּתְאֹם וְכַיּוֹצֵא בִּדְבָרִים הָאֵלּוּ שֶׁהֵן מַרְאִין שֶׁאֵין כַּוָּנָתוֹ לְהָעִיד הֲרֵי זֶה נֶאֱמָן:","יִשְׂרָאֵל שֶׁשָּׁמַע מֵעַכּוּ״‎ם הַמֵּסִיחַ לְפִי תֻּמּוֹ מֵעִיד שֶׁשָּׁמַע מִמֶּנּוּ וְתִנָּשֵׂא עַל פִּיו. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא הָיְתָה שָׁם אֲמַתְלָא. אֲבָל אִם הָיְתָה שָׁם אֲמַתְלָא בְּשִׂיחַת הָעַכּוּ״‎ם שֶׁמָּא לֹא יִתְכַּוִּן אֶלָּא לְדָבָר אַחֵר. כְּמוֹ שֶׁאָמַר לְאֶחָד עֲשֵׂה לִי כָּךְ וְכָךְ שֶׁלֹּא אֶהֱרֹג אוֹתְךָ כְּדֶרֶךְ שֶׁהָרַגְתִּי פְּלוֹנִי. אֵין זֶה מֵסִיחַ לְפִי תֻּמּוֹ שֶׁכַּוָּנָתוֹ לְהַטִּיל אֵימָה עַל זֶה:","וְכֵן אִם שָׁמַע מֵעֶרְכָּאוֹת שֶׁל עַכּוּ״‎ם שֶׁאָמְרוּ הָרַגְנוּ פְּלוֹנִי אֵינָם נֶאֱמָנִין. שֶׁהֵן מַחֲזִיקִין יְדֵי עַצְמָן בְּכָזָב כְּדֵי לְהַטִּיל אֵימָה. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ:","עַכּוּ״‎ם שֶׁהֵסִיחַ לְפִי תֻּמּוֹ תְּחִלָּה אַף עַל פִּי שֶׁשָּׁאֲלוּ אוֹתוֹ אַחַר כָּךְ וּבְדָקוּהוּ עַד שֶׁיְּפָרֵשׁ כָּל הַמְאֹרָע הֲרֵי זֶה נֶאֱמָן וּמַשִּׂיאִין עַל פִּיו:","כְּבָר הוֹדַעְנוּ שֶׁהָעֵד שֶׁאָמַר שָׁמַעְתִּי שֶׁמֵּת פְּלוֹנִי אֲפִלּוּ שָׁמַע מֵאִשָּׁה שֶׁשָּׁמְעָה מֵעֶבֶד הֲרֵי זֶה כָּשֵׁר לְעֵדוּת אִשָּׁה וּמַשִּׂיאִין עַל פִּיו. אֲבָל אִם אָמַר הָעֵד אוֹ הָאִשָּׁה אוֹ הָעֶבֶד מֵת פְּלוֹנִי וַאֲנִי רְאִיתִיו שֶׁמֵּת. שׁוֹאֲלִין אוֹתוֹ הֵיאַךְ רָאִיתָ וּבְמַה יָּדַעְתָּ שֶׁמֵּת. אִם הֵעִיד בְּדָבָר בָּרוּר נֶאֱמָן וְאִם הֵעִיד בִּדְבָרִים שֶׁרֻבָּן לְמִיתָה אֵין מַשִּׂיאִין אֶת אִשְׁתּוֹ שֶׁאֵין מְעִידִין עַל הָאָדָם שֶׁמֵּת אֶלָּא כְּשֶׁרָאוּהוּ שֶׁמֵּת וַדַּאי וְאֵין בּוֹ סָפֵק:","כֵּיצַד. רָאוּהוּ שֶׁנָּפַל לַיָּם אֲפִלּוּ טָבַע בַּיָּם הַגָּדוֹל אֵין מְעִידִין עָלָיו שֶׁמֵּת שֶׁמָּא יָצָא בְּמָקוֹם אַחֵר. וְאִם נָפַל לְמַיִם מְקֻבָּצִים כְּגוֹן בּוֹר אוֹ מְעָרָה שֶׁעוֹמֵד וְרוֹאֶה כָּל סְבִיבָיו וְשָׁהָה כְּדֵי שֶׁתֵּצֵא נַפְשׁוֹ וְלֹא עָלָה מְעִידִין עָלָיו שֶׁמֵּת וּמַשִּׂיאִין אֶת אִשְׁתּוֹ. וְכֵן אִם הִשְׁלִיכוּהוּ בַּיָּם וְהִשְׁלִיכוּ מְצוּדָה אַחֲרָיו וְהֶעֱלוּ מִמֶּנּוּ אֵיבָר שֶׁאִי אֶפְשָׁר שֶׁיִּנָּטֵל מִן הַחַי וְיִחְיֶה הֲרֵי זֶה מְעִידִין עָלָיו שֶׁמֵּת וּמַשִּׂיאִין אֶת אִשְׁתּוֹ:","רָאוּהוּ שֶׁנָּפַל לְגֹב אֲרָיוֹת וּנְמֵרִים וְכַיּוֹצֵא בָּהֶן אֵין מְעִידִין עָלָיו. אֶפְשָׁר שֶׁלֹּא יֹאכְלוּהוּ. נָפַל לַחֲפִירַת נְחָשִׁים וְעַקְרַבִּים אוֹ לְתוֹךְ כִּבְשַׁן הָאֵשׁ אוֹ לְתוֹךְ יוֹרָה רוֹתַחַת מְלֵאָה יַיִן אוֹ שֶׁמֶן אוֹ שֶׁשָּׁחֲטוּ בּוֹ שְׁנֵי סִימָנִין אוֹ רֻבָּן אֲפִלּוּ עָמַד וּבָרַח מְעִידִין עָלָיו שֶׁמֵּת. שֶׁוַּדַּאי סוֹפוֹ לָמוּת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִדְּבָרִים שֶׁאִי אֶפְשָׁר שֶׁיִּחְיֶה אֶלָּא יָמוּת מִיָּד בִּזְמַן קָרוֹב הֲרֵי אֵלּוּ מְעִידִין עָלָיו:","רָאוּהוּ צָלוּב וְהָעוֹף אוֹכֵל בּוֹ אַף עַל פִּי שֶׁדְּקָרוּהוּ אוֹ יָרוּ בּוֹ חִצִּים אֵינוֹ מֵעִיד עָלָיו שֶׁמֵּת. וְאִם רָאוּ הָעוֹף אוֹכֵל בְּמָקוֹם שֶׁהַנֶּפֶשׁ יוֹצְאָה בִּנְטִילָתוֹ כְּגוֹן מֹחוֹ אוֹ לִבּוֹ אוֹ בְּנֵי מֵעָיו הֲרֵי זֶה מֵעִיד עָלָיו שֶׁמֵּת:","עֵד אֶחָד אוֹמֵר רְאִיתִיו שֶׁמֵּת בַּמִּלְחָמָה אוֹ בְּמַפּלֶת אוֹ שֶׁטָּבַע בַּיָּם הַגָּדוֹל וָמֵת וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ שֶׁרֻבָּן לְמִיתָה אִם אָמַר קְבַרְתִּיו נֶאֱמָן וְתִנָּשֵׂא עַל פִּיו. וְאִם לֹא אָמַר קְבַרְתִּיו לֹא תִּנָּשֵׂא. וְאִם נִשֵּׂאת לֹא תֵּצֵא:","וְכֵן הָאִשָּׁה שֶׁהֵעִיד לָהּ עֵד אֶחָד שֶׁטָּבַע בַּעְלָהּ בַּיָּם אוֹ בְּמַיִם שֶׁאֵין לָהֶם סוֹף וְלֹא עָלָה וְאָבַד זִכְרוֹ וְנִשְׁתַּכַּח שְׁמוֹ הֲרֵי זוֹ לֹא תִּנָּשֵׂא עַל עֵדוּת זוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם נִשֵּׂאת לֹא תֵּצֵא. וַאֲפִלּוּ הָיָה הָעַכּוּ״‎ם שֶׁהֵסִיחַ לְפִי תֻּמּוֹ וְאָמַר טָבַע פְּלוֹנִי בַּיָּם וְנִשֵּׂאת עַל פִּיו הֲרֵי זוֹ לֹא תֵּצֵא. וְחָכָם שֶׁהוֹרָה לְהַשִּׂיאָהּ לְכַתְּחִלָּה מְנַדִּין אוֹתוֹ:","מְצָאוּהוּ הָרוּג אוֹ מֵת. אִם פַּדַּחְתּוֹ וְחָטְמוֹ וּפַרְצוּף פָּנָיו קַיָּמִין וְהִכִּירוּהוּ בָּהֶן שֶׁהוּא פְּלוֹנִי מְעִידִין עָלָיו. וְאִם נִטַּל אֶחָד מֵאֵלּוּ אַף עַל פִּי שֶׁיֵּשׁ לָהֶם סִימָנִין בְּגוּפוֹ וּבְכֵלָיו וַאֲפִלּוּ שׁוּמָא אֵין מְעִידִין עָלָיו שֶׁמָּא אַחֵר הוּא. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁרָאוּהוּ בְּתוֹךְ שְׁלֹשָׁה יָמִים אַחַר הֲרִיגָתוֹ אוֹ אַחַר מִיתָתוֹ. אֲבָל אַחַר שְׁלֹשָׁה אֵין מְעִידִין עָלָיו מִפְּנֵי שֶׁפַּרְצוּף פָּנָיו מִשְׁתַּנֶּה:","טָבַע בַּיָּם וְהִשְׁלִיכוֹ הַיָּם לַיַּבָּשָׁה אֲפִלּוּ אַחַר כַּמָּה יָמִים. אִם הִכִּירוּ פָּנָיו וְחָטְמוֹ מְעִידִין עָלָיו, שֶׁאֵינוֹ מִשְׁתַּנֶּה בַּמַּיִם אֶלָּא לְאַחַר זְמַן מְרֻבֶּה. וְאִם שָׁהָה בַּיַּבָּשָׁה אַחַר שֶׁהֻשְׁלַךְ מִן הַיָּם י״‎ב שָׁעוֹת וְנִתְפַּח אֵין מְעִידִין עָלָיו שֶׁהֲרֵי נִשְׁתַּנָּה. כְּשֶׁמִּסְתַּכְּלִין בְּצוּרָתוֹ כְּדֵי לְהַכִּירוֹ לְהָעִיד עָלָיו בּוֹדְקִין אוֹתוֹ וְרוֹאִין אוֹתוֹ אֲפִלּוּ בַּלַּיְלָה לְאוֹר הַנֵּר אוֹ לְאוֹר הַלְּבָנָה:","רָאוּ אֶחָד עוֹמֵד מֵרָחוֹק וְאוֹמֵר שֶׁהוּא פְּלוֹנִי בֶּן פְּלוֹנִי אוֹ פְּלוֹנִי מִמָּקוֹם פְּלוֹנִי וַהֲרֵי נְשָׁכוֹ נָחָשׁ וַהֲרֵי הוּא מֵת וְהָלְכוּ וּמְצָאוּהוּ שֶׁנִּשְׁתַּנָּה וְלֹא הִכִּירוּהוּ הֲרֵי אֵלּוּ מַשִּׂיאִין אֶת אִשְׁתּוֹ:","בָּא אֶחָד וְאָמַר אָמְרוּ לִי בֵּית דִּין אוֹ אֲנָשִׁים כְּשֶׁתֵּלֵךְ לְמָקוֹם פְּלוֹנִי אֱמֹר לָהֶם שֶׁמֵּת יִצְחָק בֶּן מִיכָאֵל. וּבָא הַשָּׁלִיחַ וְאָמַר לָנוּ. וְהַשָּׁלִיחַ אֵינוֹ יוֹדֵעַ מִי הוּא זֶה. הוֹאִיל וְאָנוּ יוֹדְעִים פְּלוֹנִי הַיָּדוּעַ בְּשֵׁם זֶה הֲרֵי אִשְׁתּוֹ מֻתֶּרֶת וְאֵין אוֹמְרִין שֶׁמָּא יִצְחָק בֶּן מִיכָאֵל אַחֵר הוּא שֶׁמֵּת:","יָצָא עַכּוּ״‎ם וְיִשְׂרָאֵל מֵעִמָּנוּ לְמָקוֹם אַחֵר. וּבָא הָעַכּוּ״‎ם וְהֵסִיחַ לְפִי תֻּמּוֹ וְאָמַר אִישׁ שֶׁיָּצָא עִמִּי מִכָּאן מֵת. מַשִּׂיאִין אֶת אִשְׁתּוֹ וְאַף עַל פִּי שֶׁאֵין הָעַכּוּ״‎ם יוֹדֵעַ אוֹתוֹ הָאִישׁ. וְהוּא שֶׁיֹּאמַר קְבַרְתִּיו:","וְכֵן אִם יָצְאוּ עֲשָׂרָה בְּנֵי אָדָם כְּאֶחָד מִמָּקוֹם לְמָקוֹם וְהֵן אֲסוּרִין בְּקוֹלָר אוֹ נוֹשְׂאִים גְּמַלִּים וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. וְהֵסִיחַ הָעַכּוּ״‎ם לְפִי תֻּמּוֹ וְאָמַר שֶׁעֲשָׂרָה אֲנָשִׁים שֶׁהָלְכוּ מִמָּקוֹם פְּלוֹנִי לְמָקוֹם פְּלוֹנִי וְהֵם נוֹשְׂאִים כָּךְ וְכָךְ מֵתוּ כֻּלָּם וּקְבַרְנוּם מַשִּׂיאִין אֶת נְשׁוֹתֵיהֶן:","יִשְׂרָאֵל שֶׁאָמַר מֵת אִישׁ יְהוּדִי עִמָּנוּ בְּמָקוֹם פְּלוֹנִי כָּךְ וְכָךְ צוּרָתוֹ וְכָךְ הָיוּ סִימָנָיו. אֵין אוֹמְרִים בְּאֹמֶד הַדַּעַת פְּלוֹנִי הוּא עַד שֶׁיָּעִיד הָעֵד שֶׁהוּא פְּלוֹנִי וְיַזְכִּיר שְׁמוֹ וְשֵׁם עִירוֹ. אֲבָל אִם אָמַר אֶחָד יָצָא עִמָּנוּ מֵעִיר פְּלוֹנִית וּמֵת. מְחַפְּשִׂין בְּאוֹתָהּ הָעִיר אִם לֹא יָצָא מִשָּׁם אֶלָּא הוּא תִּנָּשֵׂא אִשְׁתּוֹ:","מָצְאוּ כָּתוּב בִּשְׁטָר מֵת אִישׁ פְּלוֹנִי בֶּן פְּלוֹנִי אוֹ נֶהֱרַג פְּלוֹנִי בֶּן פְּלוֹנִי וְנוֹדַע שֶׁזֶּה כָּתַב יִשְׂרָאֵל הֲרֵי זֶה תִּנָּשֵׂא אִשְׁתּוֹ. וְכֵן מִי שֶׁנִּשְׁתַּתֵּק וּבָדְקוּ אוֹתוֹ כְּדֶרֶךְ שֶׁבּוֹדְקִין לְגִטִּין וְנִמְצֵאת דַּעְתּוֹ מְכֻוֶּנֶת וְכָתַב שֶׁמֵּת פְּלוֹנִי בֶּן פְּלוֹנִי סוֹמְכִין עַל כְּתִיבָתוֹ וְתִנָּשֵׂא. וְאֵין בּוֹדְקִין עֵדֵי אִשָּׁה בִּדְרִישָׁה וַחֲקִירָה שֶׁלֹּא אָמְרוּ חֲכָמִים בַּדָּבָר לְהַחֲמִיר אֶלָּא לְהָקֵל מִשּׁוּם הַתָּרַת עֲגוּנָה:","אַל יִקְשֶׁה בְּעֵינֶיךָ שֶׁהִתִּירוּ חֲכָמִים הָעֶרְוָה הַחֲמוּרָה בְּעֵדוּת אִשָּׁה אוֹ עֶבֶד אוֹ שִׁפְחָה אוֹ עַכּוּ״‎ם הַמֵּסִיחַ לְפִי תֻּמּוֹ וְעֵד מִפִּי עֵד וּמִפִּי הַכְּתָב וּבְלֹא דְּרִישָׁה וַחֲקִירָה כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁלֹּא הִקְפִּידָה תּוֹרָה עַל הֲעָדַת שְׁנֵי עֵדִים וּשְׁאָר מִשְׁפְּטֵי הָעֵדוּת אֶלָּא בְּדָבָר שֶׁאֵין אַתָּה יָכוֹל לַעֲמֹד עַל בֻּרְיוֹ אֶלָּא מִפִּי הָעֵדִים וּבְעֵדוּתָן כְּגוֹן שֶׁהֵעִידוּ שֶׁזֶּה הָרַג אֶת זֶה אוֹ הִלְוָה אֶת זֶה. אֲבָל דָּבָר שֶׁאֶפְשָׁר לַעֲמֹד עַל בֻּרְיוֹ שֶׁלֹּא מִפִּי הָעֵד הַזֶּה וְאֵין הָעֵד יָכוֹל לְהִשָּׁמֵט אִם אֵין הַדָּבָר אֱמֶת. כְּגוֹן זֶה שֶׁהֵעִיד שֶׁמֵּת פְּלוֹנִי. לֹא הִקְפִּידָה תּוֹרָה עָלָיו. שֶׁדָּבָר רָחוֹק הוּא שֶׁיָּעִיד בּוֹ הָעֵד בְּשֶׁקֶר. לְפִיכָךְ הֵקֵלּוּ חֲכָמִים בְּדָבָר זֶה וְהֶאֱמִינוּ בּוֹ עֵד אֶחָד מִפִּי שִׁפְחָה וּמִן הַכְּתָב וּבְלֹא דְּרִישָׁה וַחֲקִירָה כְּדֵי שֶׁלֹּא תִּשָּׁאַרְנָה בְּנוֹת יִשְׂרָאֵל עֲגוּנוֹת: סְלִיקוּ לְהוּ הִלְכוֹת גֵּרוּשִׁין בְּסִיַּעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Eruvin 4":["אַנְּשֵׁי חָצֵר שֶׁהָיוּ כֻּלָּם אוֹכְלִין עַל שֻׁלְחָן אֶחָד אַף עַל פִּי שֶׁכָּל אֶחָד וְאֶחָד יֵשׁ לוֹ בַּיִת בִּפְנֵי עַצְמוֹ אֵין צְרִיכִין עֵרוּב מִפְּנֵי שֶׁהֵן כְּאַנְשֵׁי בַּיִת אֶחָד. וּכְשֵׁם שֶׁאֵין אִשְׁתּוֹ שֶׁל אָדָם וּבְנֵי בֵּיתוֹ וַעֲבָדָיו אוֹסְרִין עָלָיו וְאֵינוֹ צָרִיךְ לְעָרֵב עִמָּהֶן כָּךְ אֵלּוּ כְּאַנְשֵׁי בַּיִת אֶחָד הֵן מִפְּנֵי שֶׁהֵן כֻּלָּן סוֹמְכִין עַל שֻׁלְחָן אֶחָד:","וְכֵן אִם הֻצְרְכוּ לַעֲשׂוֹת עֵרוּב עִם אַנְשֵׁי חָצֵר אַחֶרֶת עֵרוּב אֶחָד לְכֻלָּן וּפַת אַחַת בִּלְבַד מוֹלִיכִין לְאוֹתוֹ מָקוֹם שֶׁמְּעָרְבִין עִמּוֹ. וְאִם הָיָה הָעֵרוּב בָּא אֶצְלָן אֵינָן צְרִיכִין לְעָרֵב כְּמוֹ הַבַּיִת שֶׁמַּנִּיחִין בּוֹ הָעֵרוּב שֶׁאֵינוֹ צָרִיךְ לִתֵּן אֶת הַפַּת שֶׁכָּל אֵלּוּ הַבָּתִּים כְּבַיִת אֶחָד הֵן חֲשׁוּבִין:","וְכֵן אַנְשֵׁי חָצֵר שֶׁעֵרְבוּ נַעֲשׂוּ כֻּלָּן כְּבַיִת אֶחָד. וְאִם הֻצְרְכוּ לְעָרֵב עִם חָצֵר שְׁנִיָּה כִּכָּר אֶחָד בִּלְבַד הוּא שֶׁמּוֹלִיכִין עַל יְדֵי כֻּלָּן לַמָּקוֹם שֶׁמְּעָרְבִין בּוֹ. וְאִם הָיָה הָעֵרוּב בָּא אֶצְלָן אֵינָן צְרִיכִין לִתֵּן פַּת:","חֲמִשָּׁה שֶׁגָּבוּ אֶת הָעֵרוּב לְהוֹלִיכוֹ לְמָקוֹם שֶׁמַּנִּיחִין בּוֹ הָעֵרוּב כְּשֶׁהֵם מוֹלִיכִין אֵינָן צְרִיכִין לְהוֹלִיךְ עַל יְדֵי חֲמִשְּׁתָּן אֶלָּא כִּכָּר אַחַת שֶׁכֵּיוָן שֶׁגָּבוּ כֻּלָּן נַעֲשׂוּ כְּאַנְשֵׁי בַּיִת אֶחָד:","הָאָב וּבְנוֹ וְהָרַב וְתַלְמִידוֹ שֶׁהֵן שְׁרוּיִין בְּחָצֵר אֵינָן צְרִיכִין לְעָרֵב מִפְּנֵי שֶׁהֵן כְּבַיִת אֶחָד. וְאַף עַל פִּי שֶׁפְּעָמִים אוֹכְלִין עַל שֻׁלְחָן אֶחָד וּפְעָמִים אֵינָן אוֹכְלִין הֲרֵי הֵן כְּבַיִת אֶחָד:","הָאַחִים שֶׁכָּל אֶחָד מֵהֶם לוֹ בַּיִת בִּפְנֵי עַצְמוֹ וְאֵינָן סוֹמְכִין עַל שֻׁלְחַן אֲבִיהֶן. וְכֵן הַנָּשִׁים אוֹ הָעֲבָדִים שֶׁאֵינָן סוֹמְכִין עַל שֻׁלְחַן בַּעֲלֵיהֶן אוֹ רַבָּן תָּמִיד אֲבָל אוֹכְלִין הֵם עַל שֻׁלְחָנוֹ בִּשְׂכַר מְלָאכָה שֶׁעוֹשִׂין לוֹ אוֹ בְּטוֹבָה יָמִים יְדוּעִין כְּמִי שֶׁסּוֹעֵד אֵצֶל חֲבֵרוֹ שָׁבוּעַ אוֹ חֹדֶשׁ. אִם אֵין עִמָּהֶן דִּיּוּרִין אֲחֵרִים בֶּחָצֵר אֵינָן צְרִיכִין לְעָרֵב. וְאִם עֵרְבוּ עִם חָצֵר אַחֶרֶת עֵרוּב אֶחָד לְכֻלָּן. וְאִם בָּא הָעֵרוּב אֶצְלָן אֵין נוֹתְנִין פַּת. וְאִם הָיוּ דִּיּוּרִין עִמָּהֶן בֶּחָצֵר צְרִיכִין פַּת לְכָל אֶחָד וְאֶחָד כִּשְׁאָר אַנְשֵׁי הֶחָצֵר מִפְּנֵי שֶׁאֵינָן סוֹמְכִין עַל שֻׁלְחָן אֶחָד תָּמִיד:","חָמֵשׁ חֲבוּרוֹת שֶׁשָּׁבְתוּ בִּטְרַקְלִין אֶחָד. אִם הָיָה מַפְסִיק בֵּין כָּל חֲבוּרָה וַחֲבוּרָה מְחִצָּה הַמַּגַּעַת לַתִּקְרָה הֲרֵי כָּל חֲבוּרָה מֵהֶן כְּאִלּוּ הִיא בְּחֶדֶר בִּפְנֵי עַצְמוֹ אוֹ בַּעֲלִיָּה בִּפְנֵי עַצְמָהּ לְפִיכָךְ צְרִיכִין פַּת מִכָּל חֲבוּרָה. וְאִם אֵין הַמְּחִצּוֹת מַגִּיעוֹת לַתִּקְרָה כִּכָּר אֶחָד לְכֻלָּן שֶׁכֻּלָּן כְּאַנְשֵׁי בַּיִת אֶחָד חֲשׁוּבִין:","מִי שֶׁיֵּשׁ לוֹ בַּחֲצַר חֲבֵרוֹ בֵּית שַׁעַר שֶׁרַבִּים דּוֹרְסִין בּוֹ אוֹ אַכְסַדְרָה אוֹ מִרְפֶּסֶת אוֹ בֵּית הַבָּקָר אוֹ בֵּית הַתֶּבֶן אוֹ בֵּית הָעֵצִים אוֹ אוֹצָר הֲרֵי זֶה אֵינוֹ אוֹסֵר עָלָיו עַד שֶׁיִּהְיֶה לוֹ עִמּוֹ בֶּחָצֵר מְקוֹם דִּירָה שֶׁהוּא סוֹמֵךְ עָלָיו לֶאֱכל בּוֹ פִּתּוֹ וְאַחַר כָּךְ יִהְיֶה אוֹסֵר עָלָיו עַד שֶׁיְּעָרֵב עִמּוֹ. אֲבָל מְקוֹם לִינָה אֵינוֹ אוֹסֵר. לְפִיכָךְ אִם קָבַע לוֹ מָקוֹם לֶאֱכל בּוֹ בְּבֵית שַׁעַר אוֹ בְּאַכְסַדְרָה וּמִרְפֶּסֶת אֵינוֹ אוֹסֵר עָלָיו לְפִי שֶׁאֵינוֹ מְקוֹם דִּירָה:","עֲשָׂרָה בָּתִּים זֶה לִפְנִים מִזֶּה הַבַּיִת הַפְּנִימִי וְהַשֵּׁנִי לוֹ הֵם שֶׁנּוֹתְנִין אֶת הָעֵרוּב וְהַשְּׁמוֹנָה בָּתִּים הַחִיצוֹנִים אֵינָן נוֹתְנִין אֶת הָעֵרוּב הוֹאִיל וְרַבִּים דּוֹרְסִין בָּהֶן הֲרֵי הֵן כְּבֵית שַׁעַר וְהַדָּר בְּבֵית שַׁעַר אֵינוֹ אוֹסֵר. אֲבָל הַתְּשִׁיעִי אֵין דּוֹרְסִין בּוֹ רַבִּים אֶלָּא יָחִיד לְפִיכָךְ אוֹסֵר עַד שֶׁיִּתֵּן עֵרוּבוֹ:","שְׁתֵּי חֲצֵרוֹת וּבֵינֵיהֶן שְׁלֹשָׁה בָּתִּים פְּתוּחִים זֶה לָזֶה וּפְתוּחִים לַחֲצֵרוֹת וְהֵבִיאוּ בְּנֵי חָצֵר זוֹ עֵרוּבָן דֶּרֶךְ הַבַּיִת הַפָּתוּחַ לָהֶן וְהִנִּיחוּהוּ בְּבַיִת אֶמְצָעִי. וְכֵן הֵבִיאוּ בְּנֵי הֶחָצֵר הָאַחֵר עֵרוּבָן דֶּרֶךְ הַפָּתוּחַ לָהֶן וְהִנִּיחוּהוּ בַּבַּיִת הָאֶמְצָעִי. אוֹתָן הַשְּׁלֹשָׁה בָּתִּים אֵינָן צְרִיכִין לִתֵּן אֶת הַפַּת. הָאֶמְצָעִי מִפְּנֵי שֶׁהִנִּיחוּ בּוֹ הָעֵרוּב וְהַשְּׁנַיִם שֶׁמִּצְּדָדָיו מִפְּנֵי שֶׁכָּל אֶחָד מֵהֶן בֵּית שַׁעַר לְאַנְשֵׁי חָצֵר:","שְׁתֵּי חֲצֵרוֹת וּשְׁנֵי בָּתִּים פְּתוּחִין זֶה לָזֶה בֵּינֵיהֶן וְהֵבִיאוּ אֵלּוּ עֵרוּבָן דֶּרֶךְ הַבַּיִת הַפָּתוּחַ לָהֶן וְהִנִּיחוּהוּ בַּבַּיִת הַשֵּׁנִי הַסָּמוּךְ לֶחָצֵר הָאַחֶרֶת וְהֵבִיאוּ אֵלּוּ עֵרוּבָן דֶּרֶךְ הַפֶּתַח הַסָּמוּךְ לָהֶן וְהִנִּיחוּהוּ בַּבַּיִת הָאַחֵר. שְׁתֵּיהֶן לֹא קָנוּ עֵרוּב. שֶׁכָּל אֶחָד מֵהֶן הִנִּיחַ עֵרוּבוֹ בְּבֵית שַׁעַר שֶׁל חָצֵר אַחֶרֶת:","אֶחָד מִבְּנֵי הֶחָצֵר שֶׁהָיָה גּוֹסֵס אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לִחְיוֹת בּוֹ בַּיּוֹם הֲרֵי זֶה אוֹסֵר עַל בְּנֵי הֶחָצֵר עַד שֶׁיְּזַכּוּ לוֹ בְּפַת וִיעָרְבוּ עָלָיו. וְכֵן קָטָן אַף עַל פִּי שֶׁאֵינוֹ יָכוֹל לֶאֱכל כַּזַּיִת הֲרֵי זֶה אוֹסֵר עַד שֶׁיְּעָרְבוּ עָלָיו. אֲבָל הָאוֹרֵחַ אֵינוֹ אוֹסֵר לְעוֹלָם כְּמוֹ שֶׁבֵּאַרְנוּ:","אֶחָד מִבְּנֵי חָצֵר שֶׁהִנִּיחַ בֵּיתוֹ וְהָלַךְ וְשָׁבַת בְּחָצֵר אַחֶרֶת אֲפִלּוּ הָיְתָה סְמוּכָה לַחֲצֵרוֹ. אִם הִסִּיעַ מִלִּבּוֹ וְאֵין דַּעְתּוֹ לַחֲזֹר לְבֵיתוֹ בְּשַׁבָּת הֲרֵי זֶה אֵינוֹ אוֹסֵר עֲלֵיהֶן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּיִשְׂרָאֵל. אֲבָל עוֹבֵד כּוֹכָבִים אֲפִלּוּ הָלַךְ לִשְׁבֹּת בְּעִיר אַחֶרֶת אוֹסֵר עֲלֵיהֶן עַד שֶׁיִּשְׂכְּרוּ מִמֶּנּוּ מְקוֹמוֹ שֶׁהֲרֵי אֶפְשָׁר שֶׁיָּבוֹא בְּשַׁבָּת:","בַּעַל הֶחָצֵר שֶׁהִשְׂכִּיר מִבָּתֵּי חֲצֵרוֹ לַאֲחֵרִים וְהִנִּיחַ לוֹ כֵּלִים אוֹ מִינֵי סְחוֹרָה בְּכָל בַּיִת וּבַיִת מֵהֶן אֵינָן אוֹסְרִין עָלָיו הוֹאִיל וְיֵשׁ לוֹ תְּפִיסַת יָד בְּכָל בַּיִת מֵהֶן נַעֲשׂוּ הַכּל כְּאוֹרְחִין אֶצְלוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהִנִּיחַ שָׁם דָּבָר שֶׁאָסוּר לְטַלְטְלוֹ בְּשַׁבָּת כְּגוֹן טֶבֶל וַעֲשָׁשִׁיּוֹת. אֲבָל אִם נִשְׁאַר לוֹ בְּכָל בַּיִת מֵהֶן כֵּלִים שֶׁמֻּתָּר לְטַלְטְלָן הוֹאִיל וְאֶפְשָׁר שֶׁיּוֹצִיאֵם הַיּוֹם וְלֹא יִשָּׁאֵר לוֹ שָׁם תְּפִיסַת יָד הֲרֵי אֵלּוּ אוֹסְרִין עָלָיו עַד שֶׁיְּעָרְבוּ:","אַנְשֵׁי הֶחָצֵר שֶׁשָּׁכְחוּ וְלֹא עֵרְבוּ אֵין מוֹצִיאִים מִבָּתִּים לְחָצֵר וְלֹא מֵחָצֵר לְבָתִּים אֲבָל מְטַלְטְלִין הֵן כֵּלִים שֶׁשָּׁבְתוּ בֶּחָצֵר בְּכָל הֶחָצֵר וּבְכָל הַנֶּחְשָׁב עִם הֶחָצֵר. וְאִם הָיְתָה שָׁם מִרְפֶּסֶת אוֹ עֲלִיָּה וְעֵרְבוּ אַנְשֵׁי הֶחָצֵר לְעַצְמָן וְאַנְשֵׁי הַמִּרְפֶּסֶת לְעַצְמָן. אַנְשֵׁי הַמִּרְפֶּסֶת אוֹ אַנְשֵׁי הָעֲלִיָּה מְטַלְטְלִין כֵּלִים שֶׁשָּׁבְתוּ בְּבָתֵּיהֶן בְּכָל הַמִּרְפֶּסֶת וּבְכָל הַנֶּחְשָׁב עִמָּהּ אוֹ בְּכָל רֹחַב הָעֲלִיָּה וּבְכָל הַנֶּחְשָׁב עִמָּהּ. וְאַנְשֵׁי הֶחָצֵר מְטַלְטְלִין בְּכָל הֶחָצֵר וּבְכָל הַנֶּחְשָׁב עִמָּהּ. וְכֵן אִם הָיָה יָחִיד דָּר בְּחָצֵר וְיָחִיד דָּר בַּעֲלִיָּה וְשָׁכְחוּ וְלֹא עֵרְבוּ. זֶה מְטַלְטֵל בְּכָל הָעֲלִיָּה וְהַנֶּחְשָׁב עִמָּהּ וְזֶה מְטַלְטֵל בְּכָל הֶחָצֵר וְהַנֶּחְשָׁב עִמָּהּ:","כֵּיצַד. הַסֶּלַע אוֹ תֵּל וְכַיּוֹצֵא בּוֹ שֶׁבְּתוֹךְ הֶחָצֵר אִם אֵינָן גְּבוֹהִין עֲשָׂרָה טְפָחִים הֲרֵי אֵלּוּ נֶחְשָׁבִין בֵּין הֶחָצֵר וּבֵין הַמִּרְפֶּסֶת וּשְׁנֵיהֶן אֲסוּרִין לְהוֹצִיא שָׁם כֵּלִים שֶׁבַּבָּתִּים. וְאִם גְּבוֹהִין עֲשָׂרָה וְהָיָה בֵּינֵיהֶן וּבֵין הַמִּרְפֶּסֶת פָּחוֹת מֵאַרְבָּעָה טְפָחִים הֲרֵי אֵלּוּ נֶחְשָׁבִין עִם הַמִּרְפֶּסֶת שֶׁהֲרֵי הֵן שָׁוִין לָהּ וּבְנֵי מִרְפֶּסֶת מֻתָּרִין בָּהֶם. וְאִם הָיוּ רְחוֹקִין מִן הַמִּרְפֶּסֶת אַרְבָּעָה טְפָחִים אוֹ יֶתֶר עַל כֵּן אַף עַל פִּי שֶׁגְּבוֹהִין עֲשָׂרָה הֲרֵי אֵלּוּ בִּכְלַל הֶחָצֵר וְהַמִּרְפֶּסֶת לְפִי שֶּׁשְּׁנֵיהֶן אֶפְשָׁר לְהִשְׁתַּמֵּשׁ בָּהֶן עַל יְדֵי זְרִיקָה. לְפִיכָךְ שְׁנֵיהֶן אֲסוּרִין לְהוֹצִיא לְשָׁם כְּלֵי הַבָּתִּים עַד שֶׁיְּעָרְבוּ. הָיְתָה מַצֵּבָה רְחָבָה אַרְבָּעָה טְפָחִים לִפְנֵי הַמִּרְפֶּסֶת אֵין הַמִּרְפֶּסֶת אוֹסֶרֶת עַל בְּנֵי הֶחָצֵר שֶׁהֲרֵי נֶחְלְקָה מֵהֶן:","זִיזִין הַיּוֹצְאִין מִן הַכְּתָלִים. כָּל שֶׁהוּא לְמַטָּה מֵעֲשָׂרָה טְפָחִים הֲרֵי זֶה נֶחְשָׁב מִן הֶחָצֵר וּבְנֵי הֶחָצֵר מִשְׁתַּמְּשִׁין בּוֹ. וְכָל שֶׁהוּא בְּתוֹךְ עֲשָׂרָה טְפָחִים הָעֶלְיוֹנִים הַסְּמוּכִין לַעֲלִיָּה. אַנְשֵׁי עֲלִיָּה מִשְׁתַּמְּשִׁין בּוֹ וְהַנִּשְׁאָר בֵּין עֲשָׂרָה הַתַּחְתּוֹנִים עַד תְּחִלַּת עֲשָׂרָה הָעֶלְיוֹנִים מִן הַזִּיזִין הַיּוֹצְאִין שָׁם שְׁנֵיהֶן אֲסוּרִין בּוֹ וְאֵין מִשְׁתַּמְּשִׁין בָּהֶן בַּכֵּלִים שֶׁבַּבָּתִּים אֶלָּא אִם כֵּן עֵרְבוּ:","בּוֹר שֶׁבֶּחָצֵר אִם הָיָה מָלֵא פֵּרוֹת טְבָלִים שֶׁאָסוּר לְטַלְטְלָן בְּשַׁבָּת וְכַיּוֹצֵא בָּהֶן הֲרֵי הוּא וְחֻלְיָתוֹ כְּסֶלַע אוֹ תֵּל שֶׁבֶּחָצֵר. אִם הָיָה גָּבוֹהַּ עֲשָׂרָה וְהָיָה סָמוּךְ לַמִּרְפֶּסֶת הֲרֵי הוּא נֶחְשָׁב עִם הַמִּרְפֶּסֶת. אֲבָל אִם הָיָה מָלֵא מַיִם אֵין בְּנֵי חָצֵר וְלֹא בְּנֵי מִרְפֶּסֶת מַכְנִיסִין מִמֶּנּוּ לַבָּתִּים עַד שֶׁיְּעָרְבוּ:","שְׁתֵּי חֲצֵרוֹת זוֹ לִפְנִים מִזּוֹ וְאַנְשֵׁי הַפְּנִימִית יוֹצְאִין וְנִכְנָסִין וְעוֹבְרִין עַל הַחִיצוֹנָה. עֵרְבָה הַפְּנִימִית וְלֹא עֵרְבָה הַחִיצוֹנָה הַפְּנִימִית מֻתֶּרֶת וְהַחִיצוֹנָה אֲסוּרָה. עֵרְבָה הַחִיצוֹנָה וְלֹא עֵרְבָה הַפְּנִימִית שְׁתֵּיהֶן אֲסוּרוֹת. הַפְּנִימִית מִפְּנֵי שֶׁלֹּא עֵרְבָה וְהַחִיצוֹנָה מִפְּנֵי אֵלּוּ שֶׁלֹּא עֵרְבוּ שֶׁעוֹבְרִין עֲלֵיהֶן. עֵרְבוּ זוֹ לְעַצְמָהּ וְזוֹ לְעַצְמָהּ זוֹ מֻתֶּרֶת בִּפְנֵי עַצְמָהּ וְזוֹ מֻתֶּרֶת בִּפְנֵי עַצְמָהּ אֲבָל אֵין מְטַלְטְלִין מִזּוֹ לָזוֹ:","שָׁכַח אֶחָד מִן הַחִיצוֹנָה וְלֹא עֵרֵב הַפְּנִימִית בְּהֶתֵּרָהּ עוֹמֶדֶת. שָׁכַח אֶחָד מִן בְּנֵי הַפְּנִימִית וְלֹא עֵרֵב עִמָּהֶן אַף הַחִיצוֹנָה אֲסוּרָה מִפְּנֵי אֵלּוּ בְּנֵי הַפְּנִימִית שֶׁלֹּא עָלָה לָהֶן עֵרוּב שֶׁהֵן עוֹבְרִין עֲלֵיהֶן:","עָשׂוּ שְׁתֵּיהֶן עֵרוּב אֶחָד אִם הִנִּיחוּהוּ בַּחִיצוֹנָה וְשָׁכַח אֶחָד מֵהֶן וְלֹא עֵרֵב בֵּין שֶׁהָיָה מִבְּנֵי הַחִיצוֹנָה בֵּין מִבְּנֵי הַפְּנִימִית שְׁתֵּיהֶן אֲסוּרוֹת עַד שֶׁיְּבַטֵּל לָהֶן שֶׁהֲרֵי בֵּאַרְנוּ שֶׁמְּבַטְּלִין מֵחָצֵר לֶחָצֵר. וְאִם הִנִּיחוּ עֵרוּבָן בַּפְּנִימִית וְשָׁכַח אֶחָד מִבְּנֵי הַחִיצוֹנָה וְלֹא עֵרֵב הַחִיצוֹנָה אֲסוּרָה וּפְנִימִית מֻתֶּרֶת בִּמְקוֹמָהּ. שָׁכַח אֶחָד מִבְּנֵי הַפְּנִימִית וְלֹא עֵרֵב שְׁתֵּיהֶן אֲסוּרוֹת עַד שֶׁיְּבַטֵּל לָהֶן:","הָיָה אֶחָד דָּר בֶּחָצֵר זוֹ וְאֶחָד דָּר בֶּחָצֵר זוֹ אֵינָן צְרִיכִין לְעָרֵב אֶלָּא כָּל אֶחָד מֵהֶן מִשְׁתַּמֵּשׁ בְּכָל חֲצֵרוֹ. וְאִם הָיָה עוֹבֵד כּוֹכָבִים וּמַזָּלוֹת בַּפְּנִימִית אַף עַל פִּי שֶׁהוּא אֶחָד הֲרֵי הוּא כְּרַבִּים וְאוֹסֵר עַל הַחִיצוֹנָה עַד שֶׁיִּשְׂכְּרוּ מְקוֹמוֹ:","שָׁלֹשׁ חֲצֵרוֹת הַפְּתוּחוֹת זוֹ לָזוֹ וְרַבִּים בְּכָל חָצֵר מֵהֶן. עֵרְבוּ שְׁתַּיִם הַחִיצוֹנוֹת עִם הָאֶמְצָעִית הִיא מֻתֶּרֶת עִמָּהֶן וְהֵן מֻתָּרוֹת עִמָּהּ וּשְׁתַּיִם הַחִיצוֹנוֹת אֲסוּרוֹת זוֹ עִם זוֹ עַד שֶׁיַּעֲשׂוּ שְׁלָשְׁתָּן עֵרוּב אֶחָד. הָיָה בְּכָל חָצֵר מֵהֶן אֶחָד אַף עַל פִּי שֶׁרַבִּים דּוֹרְסִין בַּחִיצוֹנָה אֵינָן צְרִיכִין לְעָרֵב שֶׁכָּל אֶחָד מֵהֶן מֻתָּר בִּמְקוֹמוֹ. הָיוּ שְׁנַיִם בַּפְּנִימִית הוֹאִיל וְהֵן אֲסוּרִין בִּמְקוֹמָן עַד שֶׁיְּעָרְבוּ הֲרֵי הֵן אוֹסְרִין עַל הַיְחִידִים שֶׁבָּאֶמְצָעִית וְשֶׁבַּחִיצוֹנָה עַד שֶׁיְּעָרְבוּ שְׁנַיִם שֶׁבַּפְּנִימִית. זֶה הַכְּלָל רֶגֶל הָאֲסוּרָה בִּמְקוֹמָהּ אוֹסֶרֶת שֶׁלֹּא בִּמְקוֹמָהּ וְרֶגֶל הַמֻּתֶּרֶת בִּמְקוֹמָהּ אֵינָהּ אוֹסֶרֶת שֶׁלֹּא בִּמְקוֹמָהּ מִפְּנֵי שֶׁעוֹבֶרֶת עֲלֵיהֶן:","שְׁתֵּי כְּצוֹצְטְרִיּוֹת זוֹ לְמַעְלָה מִזּוֹ שֶׁהֵן לְמַעְלָה מִן הַמַּיִם אַף עַל פִּי שֶׁעָשְׂתָה כָּל אַחַת מֵהֶן מְחִצָּה גְּבוֹהָה עֲשָׂרָה טְפָחִים יוֹרֶדֶת מִכָּל אַחַת וְאַחַת. אִם הָיוּ שְׁתֵּי הַכְּצוֹצְטְרִיּוֹת בְּתוֹךְ עֲשָׂרָה טְפָחִים הֲרֵי אֵלּוּ אֲסוּרִין לְמַלְּאוֹת עַד שֶׁיְּעָרְבוּ שְׁתֵּיהֶן עֵרוּב אֶחָד מִפְּנֵי שֶׁהֵן כִּכְצוֹצְטְרָא אַחַת. וְאִם הָיָה בֵּין הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה יוֹתֵר עַל עֲשָׂרָה טְפָחִים וְעֵרְבָה זוֹ לְעַצְמָהּ וְזוֹ לְעַצְמָהּ שְׁתֵּיהֶן מֻתָּרוֹת לְמַלְּאוֹת:","לֹא עָשְׂתָה הָעֶלְיוֹנָה מְחִצָּה וְעָשְׂתָה הַתַּחְתּוֹנָה אַף הַתַּחְתּוֹנָה אֲסוּרָה לְמַלְּאוֹת מִפְּנֵי דְּלִי שֶׁל בְּנֵי הָעֶלְיוֹנָה שֶׁהֵן אֲסוּרִין שֶׁעוֹבֵר עָלֶיהָ. עָשְׂתָה הָעֶלְיוֹנָה מְחִצָּה וְלֹא עָשְׂתָה הַתַּחְתּוֹנָה הָעֶלְיוֹנָה מֻתֶּרֶת לְמַלְּאוֹת וְהַתַּחְתּוֹנָה אֲסוּרָה. וְאִם נִשְׁתַּתְּפוּ בְּנֵי הַתַּחְתּוֹנָה עִם בְּנֵי הָעֶלְיוֹנָה בַּמְּחִצָּה שֶׁעָשׂוּ שְׁתֵּיהֶן אֲסוּרוֹת לְמַלְּאוֹת עַד שֶׁיְּעָרְבוּ עֵרוּב אֶחָד:","שָׁלֹשׁ דִּיאֲטוֹת זוֹ לְמַעְלָה מִזּוֹ עֶלְיוֹנָה וְתַחְתּוֹנָה שֶׁל אֶחָד וְאֶמְצָעִית שֶׁל אֶחָד לֹא יְשַׁלְשֵׁל מִן הָעֶלְיוֹנָה לַתַּחְתּוֹנָה דֶּרֶךְ אֶמְצָעִית שֶׁאֵין מְשַׁלְשְׁלִין מֵרְשׁוּת לִרְשׁוּת דֶּרֶךְ רְשׁוּת אַחֵר. אֲבָל מְשַׁלְשֵׁל הוּא מִן הָעֶלְיוֹנָה לְהַתַּחְתּוֹנָה שֶׁלֹּא דֶּרֶךְ אֶמְצָעִית:","שְׁתֵּי דִּיאֲטוֹת זוֹ כְּנֶגֶד זוֹ וְחָצֵר אַחַת תַּחְתֵּיהֶן שֶׁשּׁוֹפְכִין לְתוֹכָהּ הַמַּיִם לֹא יִשְׁפְּכוּ לְתוֹכָהּ עַד שֶׁיְּעָרְבוּ שְׁתֵּיהֶן עֵרוּב אֶחָד. עָשׂוּ מִקְצָתָן עוּקָה בֶּחָצֵר לִשְׁפֹּךְ בָּהּ הַמַּיִם וּמִקְצָתָן לֹא עָשׂוּ. אֵלּוּ שֶׁעָשׂוּ שׁוֹפְכִים לָעוּקָה שֶׁלָּהֶן וְאֵלּוּ שֶׁלֹּא עָשׂוּ לֹא יִשְׁפְּכוּ לַחֲצֵר עַד שֶׁיְּעָרְבוּ. וְאִם עָשׂוּ אֵלּוּ עוּקָה וְאֵלּוּ עוּקָה כָּל אַחַת מִשְּׁתֵּיהֶן שׁוֹפֶכֶת לָעוּקָה שֶׁלָּהֶן אַף עַל פִּי שֶׁלֹּא עֵרְבוּ:"],"Mishneh Torah, Festival Offering 3":["מִצְוַת עֲשֵׂה לְהַקְהִיל כָּל יִשְׂרָאֵל אֲנָשִׁים וְנָשִׁים וְטַף בְּכָל מוֹצָאֵי שְׁמִטָּה בַּעֲלוֹתָם לָרֶגֶל וְלִקְרוֹת בְּאָזְנֵיהֶם מִן הַתּוֹרָה פָּרָשִׁיּוֹת שֶׁהֵן מְזָרְזוֹת אוֹתָן בְּמִצְוֹת וּמְחַזְּקוֹת יְדֵיהֶם בְּדַת הָאֱמֶת. שֶׁנֶּאֱמַר (דברים לא י) \"מִקֵּץ שֶׁבַע שָׁנִים בְּמֹעֵד שְׁנַת הַשְּׁמִטָּה בְּחַג הַסֻּכּוֹת\" (דברים לא יא) \"בְּבוֹא כָל יִשְׂרָאֵל לֵרָאוֹת\" וְגוֹ' (דברים לא יב) \"הַקְהֵל אֶת הָעָם הָאֲנָשִׁים וְהַנָּשִׁים וְהַטַּף וְגֵרְךָ אֲשֶׁר בִּשְׁעָרֶיךָ\" וְגוֹ':","כָּל הַפָּטוּר מִן הָרְאִיָּה פָּטוּר מִמִּצְוַת הַקְהֵל חוּץ מִן הַנָּשִׁים וְהַטַּף וְהֵעָרֵל. אֲבָל הַטָּמֵא פָּטוּר מִמִּצְוַת הַקְהֵל שֶׁנֶּאֱמַר (דברים לא יא) \"בְּבוֹא כָל יִשְׂרָאֵל\" וְזֶה אֵינוֹ רָאוּי לְבִיאָה. וְהַדָּבָר בָּרוּר שֶׁהַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס חַיָּבִין שֶׁהֲרֵי הַנָּשִׁים חַיָּבוֹת:","אֵימָתַי הָיוּ קוֹרִין. בְּמוֹצָאֵי יוֹם טוֹב הָרִאשׁוֹן שֶׁל חַג הַסֻּכּוֹת שֶׁהוּא תְּחִלַּת יְמֵי חֻלּוֹ שֶׁל מוֹעֵד שֶׁל שָׁנָה שְׁמִינִית. וְהַמֶּלֶךְ הוּא שֶׁיִּקְרָא בְּאָזְנֵיהֶם. וּבְעֶזְרַת הַנָּשִׁים הָיוּ קוֹרִין. וְקוֹרֵא כְּשֶׁהוּא יוֹשֵׁב וְאִם קָרָא מְעֻמָּד הֲרֵי זֶה מְשֻׁבָּח. מֵהֵיכָן הוּא קוֹרֵא מִתְּחִלַּת חֻמַּשׁ אֵלֶּה הַדְּבָרִים עַד סוֹף פָּרָשַׁת שְׁמַע וּמְדַלֵּג לִ(דברים יא יג) \"וְהָיָה אִם שָׁמוֹעַ\" וְגוֹ' וּמְדַלֵּג לְעַשֵּׂר תְּעַשֵּׂר וְקוֹרֵא מֵ (דברים יד כב) \"עַשֵּׂר תְּעַשֵּׂר\" עַל הַסֵּדֶר עַד סוֹף בְּרָכוֹת וּקְלָלוֹת עַד (דברים כח סט) \"מִלְּבַד הַבְּרִית אֲשֶׁר כָּרַת אִתָּם בְּחֹרֵב\" וּפוֹסֵק:","כֵּיצַד הוּא קוֹרֵא. תּוֹקְעִין בַּחֲצוֹצְרוֹת בְּכָל יְרוּשָׁלַיִם כְּדֵי לְהַקְהִיל אֶת הָעָם. וּמְבִיאִין בִּימָה גְּדוֹלָה וְשֶׁל עֵץ הָיְתָה וּמַעֲמִידִין אוֹתָהּ בְּאֶמְצַע עֶזְרַת נָשִׁים וְהַמֶּלֶךְ עוֹלֶה וְיוֹשֵׁב עָלֶיהָ כְּדֵי שֶׁיִּשְׁמְעוּ קְרִיאָתוֹ וְכָל יִשְׂרָאֵל הָעוֹלִים לָחֹג מִתְקַבְּצִין סְבִיבָיו. וְחַזַּן הַכְּנֶסֶת נוֹטֵל סֵפֶר תּוֹרָה וְנוֹתְנוֹ לְרֹאשׁ הַכְּנֶסֶת וְרֹאשׁ הַכְּנֶסֶת נוֹתְנוֹ לַסְּגָן וּסְגָן לְכֹהֵן גָּדוֹל וְכֹהֵן גָּדוֹל לַמֶּלֶךְ כְּדֵי לְהַדְּרוֹ בְּרֹב בְּנֵי אָדָם. וְהַמֶּלֶךְ מְקַבְּלוֹ כְּשֶׁהוּא עוֹמֵד וְאִם רָצָה יֵשֵׁב וּפוֹתֵחַ וְרוֹאֶה וּמְבָרֵךְ כְּדֶרֶךְ שֶׁמְּבָרֵךְ כָּל קוֹרֵא בַּתּוֹרָה בְּבֵית הַכְּנֶסֶת. וְקוֹרֵא הַפָּרָשִׁיּוֹת שֶׁאָמַרְנוּ עַד שֶׁהוּא גּוֹמֵר וְגוֹלֵל וּמְבָרֵךְ לְאַחֲרֶיהָ כְּדֶרֶךְ שֶׁמְּבָרְכִין בְּבָתֵּי כְּנֵסִיּוֹת וּמוֹסִיף שֶׁבַע בְּרָכוֹת וְאֵלּוּ הֵן. רְצֵה ה' אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל וְכוּ'. מוֹדִים אֲנַחְנוּ לָךְ וְכוּ'. אַתָּה בְּחַרְתָּנוּ מִכָּל הָעַמִּים וְכוּ' עַד מְקַדֵּשׁ יִשְׂרָאֵל וְהַזְּמַנִּים כְּדֶרֶךְ שֶׁמְּבָרְכִין בַּתְּפִלָּה. הֲרֵי שָׁלֹשׁ בְּרָכוֹת כְּמַטְבְּעָן. רְבִיעִית מִתְפַּלֵּל עַל הַמִּקְדָּשׁ שֶׁיַּעֲמֹד וְחוֹתֵם בָּהּ בָּרוּךְ אַתָּה ה' הַשּׁוֹכֵן בְּצִיּוֹן. חֲמִישִׁית מִתְפַּלֵּל עַל יִשְׂרָאֵל שֶׁתַּעֲמֹד מַלְכוּתָם וְחוֹתֵם בָּהּ הַבּוֹחֵר בְּיִשְׂרָאֵל. שִׁשִּׁית מִתְפַּלֵּל עַל הַכֹּהֲנִים שֶׁיִּרְצֶה הָאֵל עֲבוֹדָתָם וְחוֹתֵם בָּהּ בָּרוּךְ אַתָּה ה' מְקַדֵּשׁ הַכֹּהֲנִים. שְׁבִיעִית מִתְחַנֵּן וּמִתְפַּלֵּל בָּהּ כְּפִי מַה שֶּׁהוּא יָכוֹל וְחוֹתֵם בָּהּ הוֹשַׁע ה' אֶת עַמְּךָ יִשְׂרָאֵל שֶׁעַמְּךָ צְרִיכִין לְהִוָּשַׁע בָּרוּךְ אַתָּה ה' שׁוֹמֵעַ תְּפִלָּה:","הַקְּרִיאָה וְהַבְּרָכוֹת בִּלְשׁוֹן הַקֹּדֶשׁ. שֶׁנֶּאֱמַר (דברים לא יא) \"תִּקְרָא אֶת הַתּוֹרָה הַזֹּאת\" בִּלְשׁוֹנָהּ אַף עַל פִּי שֶׁיֵּשׁ שָׁם לוֹעֲזוֹת:","וְגֵרִים שֶׁאֵינָן מַכִּירִין חַיָּבִין לְהָכִין לִבָּם וּלְהַקְשִׁיב אָזְנָם לִשְׁמֹעַ בְּאֵימָה וְיִרְאָה וְגִילָה בִּרְעָדָה כְּיוֹם שֶׁנִּתְּנָה בּוֹ בְּסִינַי. אֲפִלּוּ חֲכָמִים גְּדוֹלִים שֶׁיּוֹדְעִים כָּל הַתּוֹרָה כֻּלָּהּ חַיָּבִין לִשְׁמֹעַ בְּכַוָּנָה גְּדוֹלָה יְתֵרָה. וּמִי שֶׁאֵינוֹ יָכוֹל לִשְׁמֹעַ מְכַוֵּן לִבּוֹ לִקְרִיאָה זוֹ שֶׁלֹּא קְבָעָהּ הַכָּתוּב אֶלָּא לְחַזֵּק דַּת הָאֱמֶת וְיִרְאֶה עַצְמוֹ כְּאִלּוּ עַתָּה נִצְטַוָּה בָּהּ וּמִפִּי הַגְּבוּרָה שׁוֹמְעָהּ. שֶׁהַמֶּלֶךְ שָׁלִיחַ הוּא לְהַשְׁמִיעַ דִּבְרֵי הָאֵל:","יוֹם הַקְהֵל שֶׁחָל לִהְיוֹת בְּשַׁבָּת מְאַחֲרִין אוֹתוֹ לְאַחַר הַשַּׁבָּת. מִפְּנֵי תְּקִיעַת הַחֲצוֹצְרוֹת וְהַתְּחִנּוֹת שֶׁאֵינָן דּוֹחִין אֶת הַשַּׁבָּת:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 9":["מִצְוַת עֲשֵׂה לִתֵּן כָּל זוֹבֵחַ בְּהֵמָה טְהוֹרָה לַכֹּהֵן הַזְּרוֹעַ וְהַלְּחָיַיִם וְהַקֵּבָה. שֶׁנֶּאֱמַר (דברים יח ג) \"וְזֶה יִהְיֶה מִשְׁפַּט הַכֹּהֲנִים\". וְאֵלּוּ הֵם הַנִּקְרָאִים בְּכָל מָקוֹם מַתָּנוֹת. וּמִצְוָה זוֹ נוֹהֶגֶת תָּמִיד בֵּין בִּפְנֵי הַבַּיִת בֵּין שֶׁלֹּא בִּפְנֵי הַבַּיִת. וּבְכָל מָקוֹם בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּבְחֻלִּין אֲבָל לֹא בְּמֻקְדָּשִׁין:","כָּל הַקָּדָשִׁים שֶׁקָּדַם מוּם קָבוּעַ לְהֶקְדֵּשָׁן וְנִפְדּוּ חַיָּבִין בְּמַתָּנוֹת. וְאִם קָדַם מוּם עוֹבֵר לְהֶקְדֵּשָׁן אוֹ שֶׁהִקְדִּישָׁן תְּמִימִים וְאַחַר כָּךְ נוֹלַד בָּהֶם מוּם וְנִפְדּוּ הֲרֵי אֵלּוּ פְּטוּרִין מִן הַמַּתָּנוֹת:","סְפֵק בְּכוֹר חַיָּב בְּמַתָּנוֹת מִכָּל צַד. שֶׁאִם בְּכוֹר הוּא כֻּלּוֹ לַכֹּהֵן וְאִם אֵינוֹ בְּכוֹר מַתְּנוֹתָיו לַכֹּהֵן. וְאִם נִסְתַּפֵּק בִּשְׁנַיִם וְלָקַח הַכֹּהֵן הָאֶחָד מִסָּפֵק הֲרֵי הַשֵּׁנִי פָּטוּר מִן הַמַּתָּנוֹת. עֲשָׂאוּהוּ כְּמִי שֶׁזָּכָה בּוֹ הַכֹּהֵן וּנְתָנוֹ בְּמוּמוֹ לִבְעָלָיו. אֲבָל סְפֵק מַעֲשֵׂר פָּטוּר מִכָּל מָקוֹם שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","בֶּהֱמַת קָדָשִׁים שֶׁנִּפְסְלָה בְּמוּמָהּ וְאֵינָהּ חַיֶּבֶת בְּמַתָּנוֹת שֶׁנִּתְעָרְבָה בִּבְהֵמוֹת אֲחֵרוֹת אֲפִלּוּ אַחַת בְּמֵאָה בִּזְמַן שֶׁכָּל בְּהֵמָה מֵהֶן לְאַחֵר כֻּלָּן פְּטוּרִין. שֶׁכָּל אֶחָד וְאֶחָד סָפֵק וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. הָיָה אֶחָד הוּא הַשּׁוֹחֵט אֶת כֻּלָּם פּוֹטֵר מַתְּנוֹת אַחַת מֵהֶן בִּלְבַד:","אֵין חַיָּב בְּמַתָּנוֹת אֶלָּא בְּהֵמָה טְהוֹרָה בִּלְבַד שֶׁנֶּאֱמַר (דברים יח ג) \"אִם שׁוֹר אִם שֶׂה\". כִּלְאַיִם הַבָּא מִכֶּבֶשׂ וְעֵז חַיָּב בְּמַתָּנוֹת. וְהַכְּוִי אַף עַל פִּי שֶׁהוּא סָפֵק מַפְרִישִׁין מִמֶּנּוּ כָּל הַמַּתָּנוֹת. צְבִי הַבָּא עַל הָעֵז וְיָלְדָה הַוָּלָד חַיָּב בַּחֲצִי מַתָּנוֹת שֶׁנֶּאֱמַר אִם שֶׂה אֲפִלּוּ מִקְצָת שֶׂה. תַּיִשׁ הַבָּא עַל הַצְּבִיָּה הַוָּלָד פָּטוּר מִן הַמַּתָּנוֹת:","אֶחָד הַשּׁוֹחֵט לַאֲכִילַת עַכּוּ\"ם אוֹ לַאֲכִילַת כְּלָבִים אוֹ לִרְפוּאָה חַיָּב בְּמַתָּנוֹת:","בֶּהֱמַת שֻׁתָּפִין חַיֶּבֶת שֶׁנֶּאֱמַר (דברים יח ג) \"זֹבְחֵי הַזֶּבַח\":","הַלּוֹקֵחַ בְּהֵמָה מִפֵּרוֹת שְׁבִיעִית חַיָּב בְּמַתָּנוֹת. כֹּהֲנִים וּלְוִיִּים פְּטוּרִים מִן הַמַּתָּנוֹת שֶׁנֶּאֱמַר (דברים יח ג) \"מֵאֵת הָעָם\" וְסָפֵק הֵם הַלְוִיִּים אִם הֵם בִּכְלַל הָעָם אוֹ לֹא. לְפִיכָךְ אֵין נוֹטְלִין מֵהֶם וְאִם נָטַל הַכֹּהֵן לֹא יַחְזִיר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשׁוֹחֵט לְעַצְמוֹ. אֲבָל כֹּהֵן טַבָּח שֶׁשּׁוֹחֵט וּמוֹכֵר בַּשּׁוּק מַמְתִּינִין לוֹ שְׁתַּיִם וְשָׁלֹשׁ שַׁבָּתוֹת. מִיכַּן וְאֵילָךְ מוֹצִיאִין מִמֶּנּוּ מַתָּנוֹת וְנוֹתְנִין אוֹתָם לְכֹהֲנִים אֲחֵרִים. וְאִם קָבַע בֵּית מִטְבָּחַיִם לִמְכֹּר אֵין מַמְתִּינִין לוֹ אֶלָּא מוֹצִיאִין מִמֶּנּוּ מִיָּד. וְאִם נִמְנַע מִלִּתֵּן מְנַדִּין אוֹתוֹ עַד שֶׁיִּתֵּן:","הַשּׁוֹחֵט לְעַכּוּ\"ם וּלְכֹהֵן פָּטוּר מִן הַמַּתָּנוֹת. וְהַמִּשְׁתַּתֵּף עִם הַכֹּהֵן צָרִיךְ שֶׁיִּרְשֹׁם חֶלְקוֹ כְּדֵי שֶׁיַּנִּיחַ הַמַּתָּנוֹת בְּחֵלֶק הַכֹּהֵן. שֶׁאִם לֹא צִיֵּן חֶלְקוֹ חַיָּב בְּמַתָּנוֹת מִפְּנֵי שֶׁאֵין הַכּל יוֹדְעִין שֶׁהַכֹּהֵן שֻׁתָּף לוֹ. לְפִיכָךְ אִם הָיָה הַכֹּהֵן עוֹמֵד עִמּוֹ בַּמִּטְבָּחַיִם וְנוֹשֵׂא וְנוֹתֵן עִמּוֹ אֵינוֹ צָרִיךְ לִרְשֹׁם. וְהַמִּשְׁתַּתֵּף עִם הָעַכּוּ\"ם אֵינוֹ צָרִיךְ לִרְשֹׁם שֶׁסְּתָם עַכּוּ\"ם מַרְבֶּה דְּבָרִים וּמוֹדִיעַ לַכּל שֶׁהוּא שֻׁתָּף וְאַף עַל פִּי שֶׁאֵינוֹ עִמּוֹ בִּשְׁעַת מְכִירָה:","הִתְנָה הַכֹּהֵן עִמּוֹ שֶׁהוּא שֻׁתָּף חוּץ מִן הַמַּתָּנוֹת הֲרֵי הַמַּתָּנוֹת לַכֹּהֵן. כֵּיוָן שֶׁאָמַר לוֹ חוּץ הֲרֵי שִׁיֵּר לוֹ הַכֹּהֵן חֵלֶק בַּמַּתָּנוֹת וּלְפִיכָךְ הֵם שֶׁלּוֹ. אֲבָל אִם אָמַר לוֹ הַכֹּהֵן עַל מְנָת שֶׁהַמַּתָּנוֹת שֶׁלִּי הֲרֵי הַמַּתָּנוֹת שֶׁל יִשְׂרָאֵל זֶה וְנוֹתְנָן לְכָל כֹּהֵן שֶׁיִּרְצֶה. אַף עַל פִּי שֶׁהִתְנָה עִמּוֹ שֶׁהֵן שֶׁלּוֹ לֹא נִפְטַר מִן הַמַּתָּנוֹת. שֶׁהָאוֹמֵר עַל מְנָת לֹא שִׁיֵּר לוֹ בְּעַצְמָן שֶׁל מַתָּנוֹת כְּלוּם הוֹאִיל וְלֹא שִׁיֵּר לוֹ בָּהֶן שֻׁתָּפוּת לֹא קְנָאָן בִּתְנַאי זֶה:","הָיָה הַכֹּהֵן שֻׁתָּף בָּרֹאשׁ פָּטוּר מִן הַלְּחִי. שֻׁתָּף בַּיָּד פָּטוּר מִן הַזְּרוֹעַ. שֻׁתָּף בִּבְנֵי מֵעַיִם פָּטוּר מִן הַקֵּבָה. אָמַר לוֹ הַכֹּהֵן הֲרֵי הַבְּהֵמָה כֻּלָּהּ שֶׁלִּי וְהָרֹאשׁ שֶׁלְּךָ חַיָּב בִּלְחִי. שֶׁהַדָּבָר הַחַיָּב הֲרֵי הוּא שֶׁל יִשְׂרָאֵל:","גֵּר שֶׁנִּתְגַּיֵּר וְהָיְתָה לוֹ בְּהֵמָה שְׁחוּטָה. אִם נִשְׁחֲטָה עַד שֶׁלֹּא נִתְגַּיֵּר פָּטוּר. וְאִם אַחַר שֶׁנִּתְגַּיֵּר חַיָּב. וְאִם סָפֵק פָּטוּר וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","בְּהֵמָה שֶׁלֹּא הוּרְמוּ מַתְּנוֹתֶיהָ מֻתָּר לֶאֱכוֹל מִמֶּנָּה שֶׁאֵינָהּ דּוֹמָה לְטֶבֶל שֶׁהֲרֵי מַתְּנוֹת כְּהֻנָּה מֻבְדָּלִין וְהַמַּתָּנוֹת עַצְמָן אָסוּר לְיִשְׂרָאֵל לְאָכְלָן אֶלָּא בִּרְשׁוּת כֹּהֵן. עָבַר וַאֲכָלָן אוֹ הִזִּיקָן אוֹ מְכָרָן אֵינוֹ חַיָּב לְשַׁלֵּם. מִפְּנֵי שֶׁהוּא מָמוֹן שֶׁאֵין לוֹ תּוֹבֵעַ יָדוּעַ. וְהַקּוֹנֶה אוֹתָם אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי הֲרֵי זֶה מֻתָּר לְאָכְלָן מִפְּנֵי שֶׁמַּתְּנוֹת כְּהֻנָּה נִגְזָלוֹת:","אָמַר לַטַּבָּח מְכֹר לִי בְּנֵי מֵעֶיהָ שֶׁל פָּרָה וְהָיוּ בָּהּ מַתָּנוֹת נוֹתְנָן לַכֹּהֵן וְאֵינוֹ מְנַכֶּה לוֹ מִן הַדָּמִים. לְקָחָם מִמֶּנּוּ בְּמִשְׁקָל נוֹתְנָם לַכֹּהֵן וּמְנַכֶּה לַטַּבָּח מִן הַדָּמִים:","הַמְשַׁלֵּחַ בָּשָׂר לַחֲבֵרוֹ וְהָיוּ בָּהּ מַתָּנוֹת אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא עָבַר זֶה וּגְזָלָן. מָקוֹם שֶׁאֵין בּוֹ כֹּהֵן מַעֲלֶה הַמַּתָּנוֹת בְּדָמִים וְאוֹכְלָן מִפְּנֵי הֶפְסֵד כֹּהֵן וְיִתֵּן הַדָּמִים לְכָל כֹּהֵן שֶׁיִּרְצֶה:","הָרוֹצֶה לִתֵּן הַמַּתָּנוֹת לְכֹהֵן אֶחָד נוֹתֵן. וְאִם רָצָה לַחְלֹק אוֹתָן לֹא יִתֵּן חֲצִי קֵבָה לָאֶחָד אוֹ חֲצִי זְרוֹעַ אֶלָּא זְרוֹעַ לָאֶחָד וְקֵבָה לָאֶחָד וּלְחָיַיִם לִשְׁנַיִם שֶׁנֶּאֱמַר (דברים יח ד) \"תִּתֶּן לּוֹ\" שֶׁיִּהְיֶה בָּהּ כְּדֵי מַתָּנָה. וְאִם הָיוּ שֶׁל שׁוֹר חוֹלֵק אוֹתָן חֲתִיכוֹת וְהוּא שֶׁיִּהְיֶה בְּכָל חֲתִיכָה כְּדֵי מַתָּנָה:","אֵי זֶהוּ הַזְּרוֹעַ. זְרוֹעַ שֶׁל יָמִין מִן הַפֶּרֶק שֶׁל אַרְכֻּבָּה עַד כַּף שֶׁל יָדוֹ שֶׁהֵן שְׁנֵי אֵיבָרִים זֶה מְעֹרֶה בָּזֶה. וְהַלְּחָיַיִם מִן הַפֶּרֶק שֶׁל לְחִי וְעַד פִּיקָה שֶׁל גַּרְגֶּרֶת טַבַּעַת גְּדוֹלָה עִם הַלָּשׁוֹן שֶׁבֵּינֵיהֶן הַכּל לַכֹּהֵן:","אֵין מוֹלְגִין אוֹתָן וְאֵין מַפְשִׁיטִין אוֹתָן אֶלָּא יִתְּנוּ לוֹ בְּעוֹרָן וּבְצִמְרָן. וְהַקֵּבָה בַּחֵלֶב שֶׁעָלֶיהָ וּבַחֵלֶב שֶׁבְּתוֹכָהּ. וּכְבָר נָהֲגוּ הַכֹּהֲנִים לְהַנִּיחַ חֵלֶב הַקֵּבָה לַבְּעָלִים:","הַכֹּהֶנֶת אוֹכֶלֶת הַמַּתָּנוֹת אַף עַל פִּי שֶׁהִיא נְשׂוּאָה לְיִשְׂרָאֵל מִפְּנֵי שֶׁאֵין בָּהֶן קְדֻשָּׁה. וְלֹא עוֹד אֶלָּא הַבַּעַל אוֹכֵל מַתָּנוֹת בִּגְלַל אִשְׁתּוֹ. אֲבָל חֲלָלָה אֵינָהּ אוֹכֶלֶת. שֶׁאֵין חֲלָלִים בִּכְלַל כֹּהֲנִים. וְאִם רָצָה הַכֹּהֵן לִמְכֹּר הַמַּתָּנוֹת אוֹ לִתְּנָן בְּמַתָּנָה אֲפִלּוּ לְעַכּוּ\"ם אוֹ לְהַאֲכִילָם לִכְלָבִים מַאֲכִילָם שֶׁאֵין בָּהֶן קְדֻשָּׁה כְּלָל:","כֹּהֵן שֶׁהָיוּ לוֹ חֲבֵרִים שֶׁנּוֹתְנִים לוֹ הַמַּתָּנוֹת אִם רָצָה לְזַכּוֹת בָּהֶן לְיִשְׂרָאֵל חֲבֵרוֹ הֲרֵי זֶה מְזַכֶּה לוֹ. וְאַף עַל פִּי שֶׁלֹּא בָּאוּ לְיָדוֹ. וְיִהְיוּ אוֹתָם הַחֲבֵרִים זוֹבְחִים וְנוֹתְנִין הַמַּתָּנוֹת לְזֶה הַיִּשְׂרָאֵל שֶׁזָּכָה בָּהֶן. וְהוּא שֶׁיִּהְיֶה הַיִּשְׂרָאֵל זֶה בְּדֹחַק וְאֵין לוֹ לִקְנוֹת בָּשָׂר. וְיִהְיֶה הַכֹּהֵן שֶׁזָּכָה לוֹ חֲבֵרוֹ. אֲבָל אִם הָיָה הַכֹּהֵן שַׁמָּשׁוֹ שֶׁל יִשְׂרָאֵל זֶה אוֹ שְׂכִירוֹ אוֹ לְקִיטוֹ אֵינוֹ מְזַכֶּה לוֹ עַד שֶׁיָּבוֹאוּ לְיָדוֹ שֶׁמָּא יְזַכֶּה בְּעַל כָּרְחוֹ:","לֹא יַחְטֹף הַכֹּהֵן הַמַּתָּנוֹת וְלֹא יִשְׁאַל בְּפִיו אֶלָּא אִם כֵּן נוֹתְנִין לוֹ בְּכָבוֹד נוֹטֵל. וּבִזְמַן שֶׁהֵם רַבִּים בְּבֵית הַמִּטְבָּחַיִם הַצְּנוּעִים מוֹשְׁכִין יְדֵיהֶם וְהַגַּרְגְּרָנִים נוֹטְלִין. וְאִם הָיָה כֹּהֵן צָנוּעַ וְאֵין מַכִּירִין אוֹתוֹ שֶׁהוּא כֹּהֵן הֲרֵי זֶה נוֹטֵל כְּדֵי שֶׁיִּוָּדַע לַכּל שֶׁהוּא כֹּהֵן. וְאֵין הַכֹּהֲנִים אוֹכְלִין הַמַּתָּנוֹת אֶלָּא צָלִי בְּחַרְדָּל שֶׁנֶּאֱמַר (שמות כט כט) \"לְמָשְׁחָה\" כְּדֶרֶךְ שֶׁאוֹכְלִים הַמְּלָכִים:"],"Mishneh Torah, Forbidden Foods 12":["כֵּיצַד הִיא הַנְּגִיעָה שִׁאוֹסֵר בָּהּ הָעַכּוּ\"ם הַיַּיִן. הוּא שֶׁיִּגַּע בַּיַּיִן עַצְמוֹ בֵּין בְּיָדוֹ בֵּין בִּשְׁאָר אֵיבָרָיו שֶׁדַּרְכָּן לְנַסֵּךְ בָּהֶן וִישַׁכְשֵׁךְ. אֲבָל אִם פָּשַׁט יָדוֹ לְחָבִית וְתָפְסוּ אֶת יָדוֹ קֹדֶם שֶׁיּוֹצִיאָהּ וְלֹא יְנִידָהּ וּפָתְחוּ הֶחָבִית מִלְּמַטָּה עַד שֶׁיָּצָא הַיַּיִן וְיָרַד לְמַטָּה מִיָּדוֹ לֹא נֶאֱסַר הַיַּיִן. וְכֵן אִם אָחַז כְּלִי פָּתוּחַ שֶׁל יַיִן וְשִׁכְשְׁכוֹ אַף עַל פִּי שֶׁלֹּא הִגְבִּיהַּ הַכְּלִי וְלֹא נָגַע בַּיַּיִן נֶאֱסַר הַיַּיִן:","נָטַל כְּלִי שֶׁל יַיִן וְהִגְבִּיהוֹ וְיָצַק הַיַּיִן אַף עַל פִּי שֶׁלֹּא שִׁכְשֵׁךְ נֶאֱסַר שֶׁהֲרֵי בָּא הַיַּיִן מִכֹּחוֹ. הִגְבִּיהַּ וְלֹא שִׁכְשֵׁךְ וְלֹא נָגַע מֻתָּר:","עַכּוּ\"ם שֶׁהָיָה אוֹחֵז הַכְּלִי בַּקַּרְקַע וְיִשְׂרָאֵל יָצַק לְתוֹכוֹ יַיִן הַיַּיִן מֻתָּר. וְאִם נִדְנֵד הָעַכּוּ\"ם הַכְּלִי נֶאֱסַר הַיַּיִן:","כְּלִי סָתוּם מֻתָּר לְטַלְטְלוֹ הָעַכּוּ\"ם מִמָּקוֹם לְמָקוֹם וְאַף עַל פִּי שֶׁהַיַּיִן מִתְנַדְנֵד שֶׁאֵין זֶה דֶּרֶךְ הַנִּסּוּךְ. הֶעֱבִיר נוֹד שֶׁל יַיִן מִמָּקוֹם לְמָקוֹם וְהוּא אוֹחֵז פִּי הַנּוֹד בְּיָדוֹ. בֵּין שֶׁהָיָה הַנּוֹד מָלֵא אוֹ חָסֵר מֻתָּר. וְאַף עַל פִּי שֶׁהַיַּיִן מִתְנַדְנֵד. הֶעֱבִיר כְּלִי חֶרֶס פָּתוּחַ מָלֵא יַיִן אָסוּר שֶׁמָּא נָגַע בּוֹ. וְאִם הָיָה חָסֵר מֻתָּר אֶלָּא אִם כֵּן שִׁכְשְׁכוֹ:","עַכּוּ\"ם שֶׁנָּגַע בְּיַיִן וְלֹא נִתְכַּוֵּן לָזֶה הֲרֵי הַיַּיִן מֻתָּר בַּהֲנָיָה בִּלְבַד. כֵּיצַד. כְּגוֹן שֶׁנָּפַל עַל נוֹד שֶׁל יַיִן אוֹ שֶׁהוֹשִׁיט יָדוֹ לְחָבִית עַל מְנָת שֶׁהִיא שֶׁמֶן וְנִמְצֵאת יַיִן:","בָּא הַיַּיִן מִכֹּחוֹ שֶׁל עַכּוּ\"ם בְּלֹא כַּוָּנָה הוֹאִיל וְלֹא נָגַע בַּיַּיִן הֲרֵי זֶה מֻתָּר בִּשְׁתִיָּה. כֵּיצַד. כְּגוֹן שֶׁהִגְבִּיהַּ כְּלִי שֶׁל יַיִן וְיָצַק לִכְלִי אַחֵר וְהוּא מְדַמֶּה שֶׁהוּא שֵׁכָר אוֹ שֶׁמֶן הֲרֵי זֶה מֻתָּר:","נִכְנַס הָעַכּוּ\"ם לְבַיִת אוֹ לַחֲנוּת לְבַקֵּשׁ יַיִן וּפָשַׁט יָדוֹ כְּשֶׁהוּא מְחַפֵּשׂ וְנָגַע בַּיַּיִן אָסוּר שֶׁהֲרֵי לְיַיִן נִתְכַּוֵּן וְאֵין זֶה נוֹגֵעַ בְּלֹא כַּוָּנָה:","חָבִית שֶׁנִּסְדְּקָה לְאָרְכָּהּ וְקָדַם הָעַכּוּ\"ם וְחִבְּקָה כְּדֵי שֶׁלֹּא יִתְפָּרְדוּ הַחֲרָסִים הֲרֵי זֶה מֻתָּר בַּהֲנָיָה. אֲבָל אִם נִסְדְּקָה לְרָחְבָּהּ וְתָפַס בַּסֶּדֶק הָעֶלְיוֹן כְּדֵי שֶׁלֹּא יִפּל הֲרֵי זֶה מֻתָּר בִּשְׁתִיָּה שֶׁהֲרֵי אֵין הַיַּיִן עַל כֹּחוֹ שֶׁל עַכּוּ\"ם:","עַכּוּ\"ם שֶׁנָּפַל לְבוֹר שֶׁל יַיִן וְהֶעֱלוּהוּ מִשָּׁם מֵת. אוֹ שֶׁמָּדַד הַבּוֹר שֶׁיֵּשׁ בּוֹ הַיַּיִן בְּקָנֶה. אוֹ שֶׁהִתִּיז אֶת הַזְּבוּב וְהַצִּרְעָה מֵעָלָיו בְּקָנֶה. אוֹ שֶׁהָיָה מְטַפֵּחַ עַל פִּי הֶחָבִית הָרוֹתַחַת כְּדֵי שֶׁתָּנוּחַ הָרְתִיחָה. אוֹ שֶׁנָּטַל חָבִית וּזְרָקָהּ בַּחֲמָתוֹ לַבּוֹר. הֲרֵי זֶה מֻתָּר בַּהֲנָיָה בִּלְבַד. וְאִם עָלָה הָעַכּוּ\"ם חַי הַיַּיִן אָסוּר בַּהֲנָיָה:","חָבִית שֶׁהָיָה נֶקֶב בְּצִדָּהּ וְנִשְׁמַט הַפְּקָק מִן הַנֶּקֶב וְהִנִּיחַ הָעַכּוּ\"ם אֶצְבָּעוֹ בִּמְקוֹם הַנֶּקֶב כְּדֵי שֶׁלֹּא יֵצֵא הַיַּיִן כָּל הַיַּיִן שֶׁמֵּרֹאשׁ הֶחָבִית עַד הַנֶּקֶב אָסוּר. וְשֶׁתַּחַת הַנֶּקֶב מֻתָּר בִּשְׁתִיָּה:","מֵינֶקֶת כְּפוּפָה שֶׁעוֹשִׂין אוֹתָהּ מִמַּתֶּכֶת אוֹ מִזְּכוּכִית וְכַיּוֹצֵא בָּהֶם. שֶׁהִנִּיחַ רֹאשָׁהּ לְתוֹךְ הַיַּיִן שֶׁבֶּחָבִית וְהָרֹאשׁ הָאַחֵר חוּץ לֶחָבִית וּמָצַץ הַיַּיִן וְהִתְחִיל הַיַּיִן לֵירֵד כְּדֶרֶךְ שֶׁעוֹשִׂין תָּמִיד. וּבָא הָעַכּוּ\"ם וְהִנִּיחַ אֶצְבָּעוֹ עַל פִּי הַמֵּינֶקֶת וּמָנַע הַיַּיִן מִלֵּירֵד נֶאֱסַר כָּל הַיַּיִן שֶׁבֶּחָבִית. שֶׁהַכּל הָיָה יוֹצֵא וְנִגְרָר לוּלֵי יָדוֹ וְנִמְצָא הַכּל כְּבָא מִכֹּחוֹ:","הַמְעָרֶה יַיִן לְתוֹךְ כְּלִי שֶׁיֵּשׁ בּוֹ יֵין עַכּוּ\"ם נֶאֱסַר כָּל הַיַּיִן שֶׁבַּכְּלִי הָעֶלְיוֹן. שֶׁהֲרֵי הָעַמּוּד הַנִּצֹּק מְחַבֵּר בֵּין הַיַּיִן שֶׁבַּכְּלִי הָעֶלְיוֹן וּבֵין הַיַּיִן שֶׁבַּכְּלִי הַתַּחְתּוֹן. לְפִיכָךְ הַמּוֹדֵד לְעַכּוּ\"ם לְתוֹךְ כְּלִי שֶׁבְּיָדוֹ יְנַפֵּץ נְפִיצָה אוֹ יִזְרֹק זְרִיקָה כְּדֵי שֶׁלֹּא יִהְיֶה נִצֹּק חִבּוּר וְיֶאֱסֹר עָלָיו מַה שֶּׁיִּשָּׁאֵר בַּכְּלִי הָעֶלְיוֹן:","מַשְׁפֵּךְ שֶׁמָּדַד בּוֹ לְעַכּוּ\"ם אִם יֵשׁ בִּקְצֵה הַמַּשְׁפֵּךְ עֲכָּבַת יַיִן לֹא יִמְדֹּד בּוֹ לְיִשְׂרָאֵל עַד שֶׁיְּדִיחֶנּוּ וִינַגֵּב. וְאִם לֹא הֵדִיחַ הֲרֵי זֶה אָסוּר:","כְּלִי שֶׁיֵּשׁ לוֹ כְּמִין שְׁנֵי חֳטָמִין יוֹצְאִין מִמֶּנּוּ כְּמוֹ הַכֵּלִים שֶׁנּוֹטְלִין בָּהֶם לַיָּדַיִם שֶׁהָיָה מָלֵא יַיִן בְּיַד יִשְׂרָאֵל וְהָיָה יִשְׂרָאֵל מוֹצֵץ וְשׁוֹתֶה מֵחֹטֶם זֶה וְהָעַכּוּ\"ם מוֹצֵץ וְשׁוֹתֶה מִן הַחֹטֶם הַשֵּׁנִי הֲרֵי זֶה מֻתָּר. וְהוּא שֶׁיַּקְדִּים הַיִּשְׂרְאֵלִי וְיִפְסֹק וַעֲדַיִן הָעַכּוּ\"ם שׁוֹתֶה. שֶׁמִּשֶּׁיִּפְסֹק הָעַכּוּ\"ם יַחֲזֹר הַיַּיִן שֶׁיִּשָּׁאֵר בַּחֹטֶם לַכְּלִי וְיֶאֱסֹר כָּל מַה שֶּׁיִּשָּׁאֵר בּוֹ שֶׁהֲרֵי בָּא הַיַּיִן מִכֹּחוֹ:","עַכּוּ\"ם שֶׁמָּצַץ הַיַּיִן מִן הֶחָבִית בְּמֵינֶקֶת אָסַר כָּל הַיַּיִן שֶׁבָּהּ. שֶׁכְּשֶׁיִּפָּסֵק יַחֲזֹר הַיַּיִן שֶׁעָלָה בַּמֵּינֶקֶת בִּמְצִיצָתוֹ וְיִפּל לֶחָבִית וְיֶאֱסֹר הַכּל:","עַכּוּ\"ם שֶׁהָיָה מַעֲבִיר עִם יִשְׂרָאֵל כַּדֵּי יַיִן מִמָּקוֹם לְמָקוֹם וְהוּא הוֹלֵךְ אַחֲרֵיהֶן לְשָׁמְרָן אֲפִלּוּ הִפְלִיגוּ מִמֶּנּוּ כְּדֵי מִיל הֲרֵי אֵלּוּ מֻתָּרוֹת. שֶׁאֵימָתוֹ עֲלֵיהֶן וְאוֹמֵר עַתָּה יֵצֵא לְפָנֵינוּ וְיִרְאֶה אוֹתָנוּ. וְאִם אָמַר לָהֶם לְכוּ וַאֲנִי אָבוֹא אַחֲרֵיכֶם אִם נִתְעַלְּמוּ מֵעֵינָיו כְּדֵי שֶׁיִּפְתְּחוּ פִּי הַכַּד וְיַחְזְרוּ וְיָגִיפוּ אוֹתָהּ וְתִיגוֹב הֲרֵי הַיַּיִן כֻּלּוֹ אָסוּר בִּשְׁתִיָּה. אִם פָּחוֹת מִכֵּן מֻתָּר:","וְכֵן הַמֵּנִיחַ עַכּוּ\"ם בַּחֲנוּתוֹ אַף עַל פִּי שֶׁהוּא יוֹצֵא וְנִכְנַס כָּל הַיּוֹם כֻּלּוֹ הַיַּיִן מֻתָּר. וְאִם מוֹדִיעוֹ שֶׁהוּא מַפְלִיג וְשָׁהָה כְּדֵי שֶׁיִּפְתַּח וְיִגֹּף וְתִיגוֹב הַיַּיִן אָסוּר בִּשְׁתִיָּה. וְכֵן הַמֵּנִיחַ יֵינוֹ בְּקָרוֹן אוֹ בִּסְפִינָה עִם הָעַכּוּ\"ם וְנִכְנַס לָעִיר לַעֲשׂוֹת צְרָכָיו הַיַּיִן מֻתָּר. וְאִם הוֹדִיעָן שֶׁהוּא מַפְלִיג וְשָׁהָה כְּדֵי שֶׁיִּפְתַּח וְיִגֹּף וְתִיגוֹב הַיַּיִן אָסוּר בִּשְׁתִיָּה. וְכָל הַדְּבָרִים הָאֵלּוּ בְּחָבִיּוֹת סְתוּמוֹת. אֲבָל בִּפְתוּחוֹת אֲפִלּוּ לֹא שָׁהָה מֵאַחַר שֶׁהוֹדִיעָן שֶׁהוּא מַפְלִיג הַיַּיִן אָסוּר:","יִשְׂרָאֵל שֶׁהָיָה אוֹכֵל עִם הָעַכּוּ\"ם וְהִנִּיחַ יַיִן פָּתוּחַ עַל הַשֻּׁלְחָן וְיַיִן פָּתוּחַ עַל הַדֻּלְפְּקִי וְיָצָא. שֶׁעַל הַשֻּׁלְחָן אָסוּר וְשֶׁעַל הַדֻּלְפְּקִי מֻתָּר. וְאִם אָמַר לוֹ מְזֹג וּשְׁתֵה כָּל הַיַּיִן הַפָּתוּחַ שֶׁבַּבַּיִת אָסוּר:","הָיָה שׁוֹתֶה עִם הָעַכּוּ\"ם וְשָׁמַע קוֹל תְּפִלָּה בְּבֵית הַכְּנֶסֶת וְיָצָא אַף הַיַּיִן הַפָּתוּחַ מֻתָּר. שֶׁהַנָּכְרִי אוֹמֵר עַתָּה יִזְכֹּר הַיַּיִן וְיָבוֹא בִּמְהֵרָה וְיִמְצָא אוֹתִי נוֹגֵעַ בְּיֵינוֹ וּלְפִי זֶה אֵינוֹ זָז מִמְּקוֹמוֹ וְאֵין נֶאֱסַר אֶלָּא מַה שֶּׁלְּפָנָיו בִּלְבַד:","עַכּוּ\"ם וְיִשְׂרָאֵל שֶׁהָיוּ דָּרִין בֶּחָצֵר אַחַת וְיָצְאוּ שְׁנֵיהֶם בְּבֶהָלָה לִרְאוֹת חָתָן אוֹ הֶסְפֵּד. וְחָזַר הָעַכּוּ\"ם וְסָגַר הַפֶּתַח וְאַחַר כָּךְ יִשְׂרָאֵל הֲרֵי הַיַּיִן הַפָּתוּחַ שֶׁבְּבֵית יִשְׂרָאֵל בְּהֶתֵּרוֹ. שֶׁלֹּא סָגַר הָעַכּוּ\"ם אֶלָּא עַל דַּעַת שֶׁכְּבָר נִכְנַס הַיִּשְׂרְאֵלִי לְבֵיתוֹ וְלֹא נִשְׁאַר אָדָם בַּחוּץ וְכִמְדֻמֶּה לוֹ שֶׁהוּא קְדָמוֹ:","יַיִן שֶׁל יִשְׂרָאֵל וְשֶׁל עַכּוּ\"ם בְּבַיִת אֶחָד וְהָיוּ חָבִיּוֹת פְּתוּחוֹת וְנִכְנַס הָעַכּוּ\"ם לַבַּיִת וְנָעַל הַדֶּלֶת בַּעֲדוֹ נֶאֱסַר כָּל הַיַּיִן. וְאִם יֵשׁ חַלּוֹן בַּדֶּלֶת שֶׁמִּסְתַּכֵּל מִמֶּנּוּ הָעוֹמֵד אֲחוֹרֵי הַפֶּתַח וְרוֹאֶה כְּנֶגְדּוֹ כָּל הֶחָבִיּוֹת שֶׁכְּנֶגֶד הַחַלּוֹן מֻתָּרוֹת. וְשֶׁמִּן הַצְּדָדִין אֲסוּרוֹת שֶׁהֲרֵי מְפַחֵד מִן הָרוֹאֶה אוֹתוֹ:","וְכֵן אִם שָׁאַג אֲרִי וְכַיּוֹצֵא בּוֹ וּבָרַח הָעַכּוּ\"ם וְנֶחְבָּא בֵּין הֶחָבִיּוֹת הַפְּתוּחוֹת הַיַּיִן מֻתָּר שֶׁהוּא אוֹמֵר שֶׁמָּא יִשְׂרָאֵל אַחֵר נֶחְבָּא כָּאן וְהוּא רוֹאֶה אוֹתִי כְּשֶׁאֶגַּע:","אוֹצָר שֶׁל יַיִן שֶׁהָיוּ חָבִיּוֹתָיו פְּתוּחוֹת וְיֵשׁ לְעַכּוּ\"ם חָבִיּוֹת אֲחֵרוֹת בְּאוֹתוֹ הַפֻּנְדָּק. וְנִמְצָא הָעַכּוּ\"ם עוֹמֵד בֵּין חָבִיּוֹת יִשְׂרָאֵל הַפְּתוּחוֹת. אִם נִבְהַל כְּשֶׁנִּמְצָא וְנִתְפַּשׂ עָלָיו כְּגַנָּב הַיַּיִן מֻתָּר בִּשְׁתִיָּה שֶׁמִּפַּחְדּוֹ וְיִרְאָתוֹ אֵין לוֹ פְּנַאי לְנַסֵּךְ. וְאִם לֹא נִתְפַּשׂ כְּגַנָּב אֶלָּא הֲרֵי הוּא בּוֹטֵחַ שָׁם הַיַּיִן אָסוּר. וְתִינוֹק הַנִּמְצָא בֵּין הֶחָבִיּוֹת בֵּין כָּךְ וּבֵין כָּךְ כָּל הַיַּיִן מֻתָּר:","גְּדוּד שֶׁנִּכְנַס לַמְּדִינָה דֶּרֶךְ שָׁלוֹם כָּל הֶחָבִיּוֹת הַפְּתוּחוֹת שֶׁבַּחֲנוּיוֹת אֲסוּרוֹת וּסְתוּמוֹת מֻתָּרוֹת. וּבִשְׁעַת מִלְחָמָה אִם פָּשַׁט הַגְּדוּד בַּמְּדִינָה וְעָבַר אֵלּוּ וְאֵלּוּ מֻתָּרוֹת שֶׁאֵין פְּנַאי לְנַסֵּךְ:","עַכּוּ\"ם שֶׁנִּמְצָא עוֹמֵד בְּצַד הַבּוֹר שֶׁל יַיִן אִם יֵשׁ לוֹ מִלְוֶה עַל אוֹתוֹ הַיַּיִן הֲרֵי זֶה אָסוּר מִפְּנֵי שֶׁלִּבּוֹ גַּס בּוֹ שׁוֹלֵחַ יָדוֹ וּמְנַסֵּךְ. וְאִם אֵין לוֹ עָלָיו מִלְוֶה הַיַּיִן מֻתָּר בִּשְׁתִיָּה:","זוֹנָה עַכּוּ\"ם בִּמְסִבָּה שֶׁל יִשְׂרָאֵל הַיַּיִן מֻתָּר שֶׁאֵימָתָן עָלֶיהָ וְלֹא תִּגַּע. אֲבָל זוֹנָה יִשְׂרְאֵלִית בִּמְסִבַּת עַכּוּ\"ם יֵינָהּ שֶׁלְּפָנֶיהָ בְּכֵלֶיהָ אָסוּר מִפְּנֵי שֶׁהֵן נוֹגְעִין בּוֹ שֶׁלֹּא מִדַּעְתָּהּ:","עַכּוּ\"ם הַנִּמְצָא בְּבֵית הַגַּת אִם יֵשׁ שָׁם לַחְלוּחִית יַיִן כְּדֵי לִבְלל הַכַּף עַד שֶׁתִּבְלל הַכַּף לְכַף שְׁנִיָּה צָרִיךְ לְהָדִיחַ כָּל בֵּית הַגַּת וִינַגֵּב. וְאִם לָאו מֵדִיחַ בִּלְבַד וְזוֹ הַרְחָקָה יְתֵרָה:","חָבִית שֶׁצָּפָה בַּנָּהָר אִם נִמְצֵאת כְּנֶגֶד עִיר שֶׁרֻבָּהּ יִשְׂרָאֵל מֻתֶּרֶת בַּהֲנָיָה. כְּנֶגֶד עִיר שֶׁרֻבָּהּ עַכּוּ\"ם אֲסוּרָה:","מָקוֹם שֶׁהָיוּ רֹב מוֹכְרֵי הַיַּיִן בּוֹ יִשְׂרְאֵלִים וְנִמְצְאוּ בּוֹ כֵּלִים גְּדוֹלִים מְלֵאִים יַיִן וְהֵם כֵּלִים שֶׁדֶּרֶךְ הַמּוֹכְרִין לְבַדָּם לִכְנֹס בָּהֶם הַיַּיִן הֲרֵי אֵלּוּ מֻתָּרִין בַּהֲנָיָה. חָבִית שֶׁפְּתָחוּהָ גַּנָּבִים אִם רֹב גַּנָּבֵי הָעִיר יִשְׂרָאֵל הַיַּיִן מֻתָּר בִּשְׁתִיָּה וְאִם לָאו אָסוּר:"],"Mishneh Torah, Forbidden Foods 8":["גִּיד הַנָּשֶׁה נוֹהֵג בִּבְהֵמָה וְחַיָּה הַטְּהוֹרִין וַאֲפִלּוּ בִּנְבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶן. וְנוֹהֵג בְּשָׁלִיל וּבְמֻקְדָּשִׁין בֵּין קָדָשִׁים הַנֶּאֱכָלִים בֵּין קָדָשִׁים שֶׁאֵינָן נֶאֱכָלִין. וְנוֹהֵג בְּיָרֵךְ שֶׁל יָמִין וּבְיָרֵךְ שֶׁל שְׂמֹאל. וְאֵין אָסוּר מִן הַתּוֹרָה אֶלָּא שֶׁעַל כַּף הַיָּרֵךְ בִּלְבַד שֶׁנֶּאֱמַר (בראשית לב לג) \"אֲשֶׁר עַל כַּף הַיָּרֵךְ\". אֲבָל שְׁאָר הַגִּיד שֶׁלְּמַעְלָה מִן הַכַּף וְשֶׁלְּמַטָּה עַד סוֹפוֹ וְכֵן חֵלֶב שֶׁעַל הַגִּיד אֵינוֹ אָסוּר אֶלָּא מִדִּבְרֵי סוֹפְרִים. וּשְׁנֵי גִּידִין הֵן. הַפְּנִימִי הַסָּמוּךְ לָעֶצֶם אָסוּר מִן הַתּוֹרָה. וְהָעֶלְיוֹן כֻּלּוֹ אָסוּר מִדִּבְרֵיהֶם:","הָאוֹכֵל מִגִּיד הַנָּשֶׁה הַפְּנִימִי מִמָּקוֹם שֶׁעַל הַכַּף לוֹקֶה. וְאִם אָכַל מֵחֶלְבּוֹ אוֹ מִשְּׁאָר הַגִּיד הַפְּנִימִי אוֹ מִכָּל הַחִיצוֹן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכַמָּה שִׁעוּר אֲכִילָה. כְּזַיִת. וְאִם אָכַל הַגִּיד שֶׁעַל הַכַּף כֻּלּוֹ אַף עַל פִּי שֶׁאֵין בּוֹ כְּזַיִת לוֹקֶה מִפְּנֵי שֶׁהוּא כִּבְרִיָּה בִּפְנֵי עַצְמָהּ:","אָכַל כְּזַיִת מִגִּיד שֶׁל יָמִין וּכְזַיִת מִגִּיד שֶׁל שְׂמֹאל. אוֹ שֶׁאָכַל שְׁנֵי גִּידִים כֻּלָּן. אַף עַל פִּי שֶׁאֵין בָּהֶן כְּזַיִת לוֹקֶה שְׁמוֹנִים. (וְכֵן הוּא לוֹקֶה עַל כָּל גִּיד וְגִיד):","הָעוֹף אֵין בּוֹ מִשּׁוּם גִּיד הַנָּשֶׁה מִפְּנֵי שֶׁאֵין לוֹ כַּף יָרֵךְ אֶלָּא יְרֵכוֹ אָרֹךְ. וְאִם נִמְצָא עוֹף שֶׁיְּרֵכוֹ כְּיֶרֶךְ הַבְּהֵמָה שֶׁיֵּשׁ לוֹ כַּף גִּיד הַנָּשֶׁה שֶׁלּוֹ אָסוּר וְאֵין לוֹקִין עָלָיו. וְכֵן בְּהֵמָה שֶׁכַּף יְרֵכָהּ אָרֹךְ כְּשֶׁל עוֹף גִּיד הַנָּשֶׁה שֶׁלָּהּ אָסוּר וְאֵין לוֹקִין עָלָיו:","הָאוֹכֵל גִּיד הַנָּשֶׁה מִבְּהֵמָה וְחַיָּה הַטְּמֵאִים פָּטוּר לְפִי שֶׁאֵינוֹ נוֹהֵג בִּטְמֵאָה אֶלָּא בִּבְהֵמָה שֶׁכֻּלָּהּ מֻתֶּרֶת. וְאֵינוֹ כְּאוֹכֵל מִשְּׁאָר גּוּפָהּ שֶׁאֵין הַגִּידִים מִכְּלַל הַבָּשָׂר כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם אָכַל מֵחֵלֶב שֶׁעַל הַגִּיד הֲרֵי זֶה כְּאוֹכֵל מִבְּשָׂרָהּ:","הָאוֹכֵל גִּיד הַנָּשֶׁה שֶׁל נְבֵלָה אוֹ שֶׁל טְרֵפָה אוֹ שֶׁל עוֹלָה חַיָּב שְׁתַּיִם. מִתּוֹךְ שֶׁנִּכְלָל בְּאִסּוּר שְׁאָר גּוּפָהּ שֶׁהָיָה מֻתָּר נִכְלָל גַּם הַגִּיד וְנוֹסָף עָלָיו אִסּוּר אַחֵר:","הַנּוֹטֵל גִּיד הַנָּשֶׁה צָרִיךְ לְחַטֵּט אַחֲרָיו עַד שֶׁלֹּא יַשְׁאִיר מִמֶּנּוּ כְּלוּם. וְנֶאֱמָן הַטַּבָּח עַל גִּיד הַנָּשֶׁה כְּשֵׁם שֶׁנֶּאֱמָן עַל הַחֵלֶב. וְאֵין לוֹקְחִין בָּשָׂר מִכָּל טַבָּח אֶלָּא אִם הָיָה אָדָם כָּשֵׁר וּמֻחְזָק בְּכַשְׁרוּת הוּא שֶׁשּׁוֹחֵט לְעַצְמוֹ וּמוֹכֵר וְנֶאֱמָן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּחוּצָה לָאָרֶץ. אֲבָל בְּאֶרֶץ יִשְׂרָאֵל בִּזְמַן שֶׁכֻּלָּהּ לְיִשְׂרָאֵל לוֹקְחִין מִכָּל אָדָם:","טַבָּח הַנֶּאֱמָן לִמְכֹּר בָּשָׂר וְנִמְצָא בְּשַׂר נְבֵלָה אוֹ בְּשַׂר טְרֵפָה יוֹצֵא מִתַּחַת יָדוֹ. מַחֲזִיר אֶת הַדָּמִים לַבְּעָלִים ומְשַׁמְּתִין אוֹתוֹ וּמַעֲבִירִין אוֹתוֹ. וְאֵין לוֹ תַּקָּנָה לְעוֹלָם לִקַּח מִמֶּנּוּ בָּשָׂר עַד שֶׁיֵּלֵךְ לְמָקוֹם שֶׁאֵין מַכִּירִין אוֹתוֹ וְיַחֲזִיר אֲבֵדָה בְּדָבָר חָשׁוּב אוֹ יִשְׁחֹט לְעַצְמוֹ וְיוֹצִיא טְרֵפָה לְעַצְמוֹ בְּמָמוֹן חָשׁוּב שֶׁוַּדַּאי עָשָׂה תְּשׁוּבָה בְּלֹא הַעֲרָמָה:","הַלּוֹקֵחַ בָּשָׂר וּשְׁלָחוֹ בְּיַד אֶחָד מֵעַמֵּי הָאָרֶץ הֲרֵי זֶה נֶאֱמָן עָלָיו. וְאַף עַל פִּי שֶׁאֵינוֹ מֻחְזָק בְּכַשְׁרוּת אֵין חוֹשְׁשִׁין לוֹ שֶׁמָּא יַחֲלִיף. וַאֲפִלּוּ עַבְדֵי יִשְׂרָאֵל וְאַמְהוֹתֵיהֶן נֶאֱמָנִין בְּדָבָר זֶה. אֲבָל לֹא עַכּוּ\"ם שֶׁמָּא יַחֲלִיף:","עֶשֶׂר חֲנֻיּוֹת תֵּשַׁע מוֹכְרוֹת בְּשַׂר שְׁחוּטָה וְאַחַת מוֹכֶרֶת נְבֵלוֹת וְלָקַח בָּשָׂר מֵאַחַת מֵהֶן וְאֵינוֹ יוֹדֵעַ מֵאֵיזֶה מֵהֶן לָקַח הֲרֵי זֶה אָסוּר שֶׁכָּל קָבוּעַ כְּמֶחֱצָה עַל מֶחֱצָה דָּמִי. אֲבָל בָּשָׂר הַנִּמְצָא מֻשְׁלָךְ בַּשּׁוּק הַלֵּךְ אַחַר הָרֹב דְּכָל דְּפָרִישׁ מֵרֻבָּא פָּרִישׁ. אִם הָיוּ רֹב הַמּוֹכְרִים עַכּוּ\"ם אָסוּר. וְאִם הָיוּ רֹב הַמּוֹכְרִים יִשְׂרָאֵל מֻתָּר:","וְכֵן בָּשָׂר הַנִּמְצָא בְּיַד עַכּוּ\"ם וְאֵינוֹ יָדוּעַ מִמִּי לָקַח אִם הָיוּ מוֹכְרֵי הַבָּשָׂר יִשְׂרָאֵל מֻתָּר. זֶה הוּא דִּין תּוֹרָה. וּכְבָר אָסְרוּ חֲכָמִים כָּל הַבָּשָׂר הַנִּמְצָא בֵּין בַּשּׁוּק בֵּין בְּיַד עַכּוּ\"ם אַף עַל פִּי שֶׁכָּל הַשּׁוֹחֲטִין וְכָל הַמּוֹכְרִין יִשְׂרָאֵל. וְלֹא עוֹד אֶלָּא הַלּוֹקֵחַ בָּשָׂר וְהִנִּיחוֹ בְּבֵיתוֹ וְנֶעֱלַם מִן הָעַיִן אָסוּר אֶלָּא אִם כֵּן הָיָה לוֹ בּוֹ סִימָן אוֹ שֶׁהָיָה לוֹ בּוֹ טְבִיעַת עַיִן וְהוּא מַכִּירוֹ וַדַּאי שֶׁהוּא זֶה אוֹ שֶׁהָיָה צָרוּר וְחָתוּם:","תָּלָה כְּלִי מָלֵא חֲתִיכוֹת בָּשָׂר וְנִשְׁבַּר הַכְּלִי וְנָפְלוּ הַחֲתִיכוֹת לָאָרֶץ וּבָא וּמָצָא חֲתִיכוֹת וְאֵין לוֹ בָּהֶן סִימָן וְלֹא טְבִיעַת עַיִן הֲרֵי זֶה אָסוּר שֶׁיֵּשׁ לוֹמַר אוֹתוֹ בָּשָׂר שֶׁהָיָה בַּכְּלִי גְּרָרַתּוּ חַיָּה אוֹ שֶׁרֶץ וְזֶה בָּשָׂר אַחֵר הוּא:","גִּיד הַנָּשֶׁה מֻתָּר בַּהֲנָאָה. לְפִיכָךְ מֻתָּר לְאָדָם לִשְׁלֹחַ לְעַכּוּ\"ם יָרֵךְ שֶׁגִּיד הַנָּשֶׁה בְּתוֹכָהּ. וְנוֹתֵן לוֹ הַיָּרֵךְ שְׁלֵמָה בִּפְנֵי יִשְׂרָאֵל. וְאֵין חוֹשְׁשִׁין שֶׁמָּא יֹאכַל מִמֶּנָּה יִשְׂרָאֵל זֶה קֹדֶם שֶׁיִּנָּטֵל הַגִּיד שֶׁהֲרֵי מְקוֹמוֹ נִכָּר. לְפִיכָךְ אִם הָיְתָה הַיָּרֵךְ חֲתוּכָה לֹא יִתְּנֶנָּה לְעַכּוּ\"ם בִּפְנֵי יִשְׂרָאֵל עַד שֶׁיִּטּל הַגִּיד שֶׁמָּא יֹאכַל מִמֶּנָּה יִשְׂרָאֵל:","כָּל מָקוֹם שֶׁנֶּאֱמַר בַּתּוֹרָה לֹא תֹאכַל לֹא תֹאכְלוּ לֹא יֹאכְלוּ לֹא יֵאָכֵל אֶחָד אִסּוּר אֲכִילָה וְאֶחָד אִסּוּר הֲנָאָה בְּמַשְׁמָע עַד שֶׁיִּפְרֹט לְךָ הַכָּתוּב כְּדֶרֶךְ שֶׁפֵּרֵט לְךָ בִּנְבֵלָה שֶׁנֶּאֱמַר (דברים יד כא) \"לַגֵּר אֲשֶׁר בִּשְׁעָרֶיךָ תִּתְּנֶנָּה וַאֲכָלָהּ\" וְכַחֵלֶב שֶׁנֶּאֱמַר בּוֹ (ויקרא ז כד) \"יֵעָשֶׂה לְכָל מְלָאכָה\". אוֹ עַד שֶׁיִּתְפָּרֵשׁ בַּתּוֹרָה שֶׁבְּעַל פֶּה שֶׁהוּא מֻתָּר בַּהֲנָאָה. כְּגוֹן שְׁקָצִים וּרְמָשִׂים וְדָם וְאֵיבָר מִן הַחַי וְגִיד הַנָּשֶׁה. שֶׁכָּל אֵלּוּ מֻתָּרִין בַּהֲנָאָה מִפִּי הַקַּבָּלָה אַף עַל פִּי שֶׁהֵן אֲסוּרִין בַּאֲכִילָה:","כָּל מַאֲכָל שֶׁהוּא אָסוּר בַּהֲנָאָה אִם נֶהֱנָה וְלֹא אָכַל כְּגוֹן שֶׁמָּכַר אוֹ נָתַן לְעַכּוּ\"ם אוֹ לִכְלָבִים אֵינוֹ לוֹקֶה. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת וְהַדָּמִים מֻתָּרִין. וְכָל דָּבָר שֶׁאָסוּר בַּאֲכִילָה וּמֻתָּר בַּהֲנָאָה אַף עַל פִּי שֶׁהוּא מֻתָּר בַּהֲנָאָה אָסוּר לַעֲשׂוֹת בּוֹ סְחוֹרָה וּלְכַוֵּן מְלַאכְתּוֹ בִּדְבָרִים אֲסוּרִים חוּץ מִן הַחֵלֶב שֶׁהֲרֵי נֶאֱמַר בּוֹ (ויקרא ז כד) \"יֵעָשֶׂה לְכָל מְלָאכָה\". לְפִיכָךְ אֵין עוֹשִׂין סְחוֹרָה לֹא בִּנְבֵלוֹת וְלֹא בִּטְרֵפוֹת וְלֹא בִּשְׁקָצִים וְלֹא בִּרְמָשִׂים:","הַצַּיָּד שֶׁנִּזְדַּמְּנוּ לוֹ חַיָּה אוֹ עוֹף וְדָג טְמֵאִים וְצָדָן אוֹ שֶׁנִּצּוֹדוּ לוֹ טְמֵאִים וּטְהוֹרִים מֻתָּר לְמָכְרָן. אֲבָל לֹא יְכַוֵּן מְלַאכְתּוֹ לִטְמֵאִים. וּמֻתָּר לַעֲשׂוֹת סְחוֹרָה בְּחָלָב שֶׁחֲלָבוֹ עַכּוּ\"ם וְאֵין יִשְׂרָאֵל רוֹאֵהוּ וּבִגְבִינוֹת הָעַכּוּ\"ם וְכַיּוֹצֵא בָּהֶן:","זֶה הַכְּלָל כָּל שֶׁאִסּוּרוֹ מִן הַתּוֹרָה אָסוּר לַעֲשׂוֹת בּוֹ סְחוֹרָה וְכָל שֶׁאִסּוּרוֹ מִדִּבְרֵיהֶם מֻתָּר לַעֲשׂוֹת בּוֹ סְחוֹרָה בֵּין בִּסְפֵקוֹ בֵּין בְּוַדָּאוֹ:"],"Mishneh Torah, Forbidden Intercourse 19":["אֵי זוֹ הִיא חֲלָלָה זוֹ שֶׁנּוֹלִדָה מֵאִסּוּר כְּהֻנָּה. וְכֵן אַחַת מִן הַנָּשִׁים הָאֲסוּרוֹת לִכְהֻנָּה שֶׁנִּבְעֲלָה לְכֹהֵן נִתְחַלְּלָה. אֲבָל הַכֹּהֵן עַצְמוֹ שֶׁעָבַר הָעֲבֵרָה לֹא נִתְחַלֵּל:","וּבֵין שֶׁנִּבְעֲלָה בְּאֹנֶס אוֹ בִּשְׁגָגָה [בֵּין כְּדַרְכָּהּ בֵּין שֶׁלֹּא כְּדַרְכָּהּ] מִשֶּׁהֶעֱרָה בָּהּ נִתְחַלְּלָה. וְהוּא שֶׁיִּהְיֶה כֹּהֵן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וָמַעְלָה וְתִהְיֶה זוֹ הָאֲסוּרָה לוֹ בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד וָמַעְלָה:","כֵּיצַד. כֹּהֵן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד שֶׁבָּא עַל הַגְּרוּשָׁה אוֹ עַל הַזּוֹנָה. וְכֹהֵן גָּדוֹל שֶׁבָּא עֲלֵיהֶן אוֹ עַל הָאַלְמָנָה אוֹ שֶׁנָּשָׂא בְּעוּלָה וּבָא עָלֶיהָ הֲרֵי אֵלּוּ נִתְחַלְּלוּ לְעוֹלָם. וְאִם הוֹלִיד מִמֶּנָּה בֶּן בֵּין זֶה שֶׁחִלְּלָהּ בֵּין כֹּהֵן אַחַר הַוָּלָד חָלָל. אֲבָל כֹּהֵן שֶׁקִּדֵּשׁ אִשָּׁה מֵאִסּוּרֵי כְּהֻנָּה וְנִתְאַלְמְנָה אוֹ נִתְגָּרְשָׁה מִן הָאֵרוּסִין לֹא נִתְחַלְּלָה. וְאִם נִשֵּׂאת אַף עַל פִּי שֶׁלֹּא נִבְעֲלָה נִתְחַלְּלָה שֶׁכָּל נְשׂוּאָה בְּחֶזְקַת בְּעוּלָה הִיא אַף עַל פִּי שֶׁנִּמְצֵאת בְּתוּלָה:","כֹּהֵן גָּדוֹל שֶׁנָּשָׂא בּוֹגֶרֶת אוֹ מֻכַּת עֵץ לֹא חִלְּלָהּ. וְכֵן אִם בַּעַל בְּעוּלָה בְּלֹא נִשּׂוּאִין לֹא חִלְּלָהּ:","כֹּהֵן הַבָּא עַל עֶרְוָה מִן הָעֲרָיוֹת חוּץ מִנִּדָּה אוֹ עַל אַחַת מֵחַיָּבֵי לָאוִין הַשָּׁוִין בַּכֹּל עָשָׂה אוֹתָהּ זוֹנָה כְּמוֹ שֶׁבֵּאַרְנוּ. חָזַר וּבָא עָלֶיהָ בִּיאָה שְׁנִיָּה בֵּין הוּא בֵּין כֹּהֵן אַחֵר נַעֲשֵׂית חֲלָלָה וְזַרְעוֹ מִמֶּנָּה חֲלָלִים. לְפִיכָךְ כֹּהֵן שֶׁבָּא עַל זְקוּקָה לְיָבָם וְנִתְעַבְּרָה מִבִּיאָה רִאשׁוֹנָה הַוָּלָד כָּשֵׁר לְפִי שֶׁאֵינָהּ מֵאִסּוּרֵי כְּהֻנָּה וְנַעֲשֵׂית זוֹנָה. חָזַר וּבָא עָלֶיהָ בִּיאָה שְׁנִיָּה וְנִתְעַבְּרָה וְיָלְדָה הִיא חֲלָלָה וּוְלָדָהּ חָלָל לְפִי שֶׁהוּא מֵאִסּוּרֵי כְּהֻנָּה:","וְכֵן כֹּהֵן הַבָּא עַל הַגִּיֹּרֶת וְהַמְשֻׁחְרֶרֶת חִלְּלָהּ וְזַרְעוֹ מִמֶּנָּה חֲלָלִים. כֹּהֵן הַבָּא עַל הַנִּדָּה הַוָּלָד כָּשֵׁר וְאֵינוֹ חָלָל שֶׁאֵין אִסּוּר הַנִּדָּה מְיֻחָד בְּכֹהֲנִים אֶלָּא שָׁוֶה בַּכּל:","כֹּהֵן שֶׁנָּשָׂא גְּרוּשָׁה מְעֻבֶּרֶת בֵּין מִמֶּנּוּ בֵּין מֵאַחֵר וְיָלְדָה כְּשֶׁהִיא חֲלָלָה הַוָּלָד כָּשֵׁר שֶׁהֲרֵי לֹא בָּא מִטִּפַּת עֲבֵרָה:","כְּבָר בֵּאַרְנוּ שֶׁהַחֲלוּצָה אֲסוּרָה לְכֹהֵן מִדִּבְרֵיהֶם. לְפִיכָךְ כֹּהֵן שֶׁבָּא עַל הַחֲלוּצָה הֲרֵי זוֹ חֲלָלָה וְזַרְעָהּ מִכֹּהֵן חֲלָלִים וְהַכּל מִדִּבְרֵיהֶן. אֲבָל כֹּהֵן שֶׁבָּא עַל אַחַת מֵהַשְּׁנִיּוֹת הִיא כְּשֵׁרָה וְזַרְעוֹ מִמֶּנָּה כְּשֵׁרִים. שֶׁאִסּוּר הַשְּׁנִיּוֹת אִסּוּר הַשָּׁוֶה בַּכּל הוּא וְאֵינוֹ מְיֻחָד בְּכֹהֲנִים:","כֹּהֵן שֶׁבָּא עַל סְפֵק זוֹנָה כְּגוֹן סְפֵק גִּיֹּרֶת אוֹ מְשֻׁחְרֶרֶת. אוֹ שֶׁבָּא עַל סְפֵק גְּרוּשָׁה. וְכֵן כֹּהֵן גָּדוֹל שֶׁבָּא עַל סְפֵק אַלְמָנָה הֲרֵי זוֹ סְפֵק חֲלָלָה וּוְלָדָהּ סְפֵק חָלָל:","נִמְצְאוּ הַחֲלָלִים שְׁלֹשָׁה. חָלָל מִן הַתּוֹרָה. וְחָלָל מִדִּבְרֵיהֶם. וּסְפֵק חָלָל. וְכָל סְפֵק חָלָל נוֹתְנִין עָלָיו חֻמְרֵי כֹּהֲנִים וְחֻמְרֵי יִשְׂרָאֵל. אֵינוֹ אוֹכֵל בִּתְרוּמָה וְלֹא מִטַּמֵּא לַמֵּתִים וְנוֹשֵׂא אִשָּׁה הָרְאוּיָה לְכֹהֵן. וְאִם אָכַל אוֹ נִטְמָא אוֹ נָשָׂא גְּרוּשָׁה מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְהוּא הַדִּין בְּחָלָל שֶׁל דִּבְרֵיהֶם. אֲבָל חָלָל שֶׁל תּוֹרָה הַוַּדַּאי הֲרֵי הוּא כְּזָר וְנוֹשֵׂא גְּרוּשָׁה וּמִטַּמֵּא לַמֵּתִים שֶׁנֶּאֱמַר (ויקרא כא א) \"אֱמֹר אֶל הַכֹּהֲנִים בְּנֵי אַהֲרֹן\". אַף עַל פִּי שֶׁהֵם בְּנֵי אַהֲרֹן עַד שֶׁיִּהְיוּ בְּכִהוּנָם:","כֹּהֵן זָכָר שֶׁהוּא אָסוּר לִשָּׂא זוֹנָה וַחֲלָלָה אָסוּר בְּגִיֹּרֶת וּמְשֻׁחְרֶרֶת שֶׁהִיא כְּזוֹנָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַכֹּהֶנֶת מֻתֶּרֶת לְהִנָּשֵׂא לְחָלָל וּלְגֵר וְלִמְשֻׁחְרָר שֶׁלֹּא הֻזְהֲרוּ כְּשֵׁרוֹת לְהִנָּשֵׂא לִפְסוּלִין שֶׁנֶּאֱמַר (ויקרא כא א) \"בְּנֵי אַהֲרֹן\" וְלֹא בְּנוֹת אַהֲרֹן. נִמְצָא הַגֵּר מֻתָּר לִשָּׂא מַמְזֶרֶת וְלִשָּׂא כֹּהֶנֶת:","גֵּרִים וּמְשֻׁחְרָרִים שֶׁנָּשְׂאוּ אֵלּוּ מֵאֵלּוּ וְהוֹלִידוּ בַּת אֲפִלּוּ לְאַחַר כַּמָּה דּוֹרוֹת הוֹאִיל וְלֹא נִתְעָרֵב בָּהֶן זֶרַע יִשְׂרָאֵל הֲרֵי אוֹתָהּ הַבַּת אֲסוּרָה לְכֹהֵן. וְאִם נִשֵּׂאת לֹא תֵּצֵא הוֹאִיל וְהוֹרָתָהּ וְלֵדָתָהּ בִּקְדֻשָּׁה. אֲבָל גֵּר אוֹ מְשֻׁחְרָר שֶׁנָּשָׂא בַּת יִשְׂרָאֵל אוֹ יִשְׂרָאֵל שֶׁנָּשָׂא גִּיֹּרֶת אוֹ מְשֻׁחְרֶרֶת בִּתּוֹ כְּשֵׁרָה לִכְהֻנָּה לְכַתְּחִלָּה:","גֵּר עַמּוֹנִי שֶׁנָּשָׂא בַּת יִשְׂרָאֵל וְכֵן מִצְרִי שֵׁנִי שֶׁנָּשָׂא בַּת יִשְׂרָאֵל אַף עַל פִּי שֶׁבִּיאָתָם בַּעֲבֵרָה וַהֲרֵי נְשׁוֹתֵיהֶן זוֹנוֹת כְּמוֹ שֶׁבֵּאַרְנוּ בְּנוֹתֵיהֶם כְּשֵׁרוֹת לִכְהֻנָּה לְכַתְּחִלָּה:","חָלָל שֶׁנָּשָׂא כְּשֵׁרָה זַרְעוֹ מִמֶּנָּה חֲלָלִים. וְכֵן בֶּן בֶּן בְּנוֹ וַאֲפִלּוּ אַחַר אֶלֶף דּוֹר. שֶׁבֶּן הֶחָלָל הַזָּכָר הוּא חָלָל לְעוֹלָם. וְאִם הָיְתָה בַּת אֲסוּרָה הִיא לִכְהֻנָּה שֶׁהֲרֵי הִיא חֲלָלָה. אֲבָל יִשְׂרָאֵל שֶׁנָּשָׂא חֲלָלָה הַוָּלָד כָּשֵׁר. לְפִיכָךְ אִם הָיְתָה בַּת הֲרֵי זוֹ תִּנָּשֵׂא לִכְהֻנָּה לְכַתְּחִלָּה:","כֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים מֻתָּרִין לָבוֹא זֶה בָּזֶה. וְהַוָּלָד הוֹלֵךְ אַחַר הַזָּכָר. (לְוִיִּים וְיִשְׂרְאֵלִים וַחֲלָלִים מֻתָּרִים לָבוֹא זֶה בָּזֶה וְהַוָּלָד הוֹלֵךְ אַחַר הַזָּכָר). שֶׁנֶּאֱמַר (במדבר א יח) \"וַיִּתְיַלְדוּ עַל מִשְׁפְּחֹתָם לְבֵית אֲבֹתָם\". בֵּית אָבִיו הִיא מִשְׁפַּחְתּוֹ וְאֵין בֵּית אִמּוֹ מִשְׁפַּחְתּוֹ:","לְוִיִּים וְיִשְׂרְאֵלִים וַחֲלָלִים גֵּרִים וַעֲבָדִים מְשֻׁחְרָרִים מֻתָּרִים לָבוֹא זֶה בָּזֶה. וְהַגֵּר וְהַמְשֻׁחְרָר שֶׁנָּשָׂא לְוִיָּה אוֹ יִשְׂרְאֵלִית אוֹ חֲלָלָה הֲרֵי הַבֵּן יִשְׂרְאֵלִי. וְיִשְׂרְאֵלִי אוֹ לֵוִי אוֹ חָלָל שֶׁנָּשְׂאוּ גִּיֹּרֶת אוֹ מְשֻׁחְרֶרֶת הַוָּלָד הוֹלֵךְ אַחַר הַזָּכָר:","כָּל מִשְׁפָּחוֹת בְּחֶזְקַת כְּשֵׁרוֹת וּמֻתָּר לִשָּׂא מֵהֶן לְכַתְּחִלָּה. וְאַף עַל פִּי כֵן אִם רָאִיתָ שְׁתֵּי מִשְׁפָּחוֹת שֶׁמִּתְגָּרוֹת זוֹ בָּזוֹ תָּמִיד אוֹ רָאִיתָ מִשְׁפָּחָה שֶׁהִיא בַּעֲלַת מַצָּה וּמְרִיבָה תָּמִיד. אוֹ רָאִיתָ אִישׁ שֶׁהוּא מַרְבֶּה מְרִיבָה עִם הַכּל וְעַז פָּנִים בְּיוֹתֵר. חוֹשְׁשִׁין לָהֶן וְרָאוּי לְהִתְרַחֵק מֵהֶן שֶׁאֵלּוּ סִימָנֵי פַּסְלוּת הֵם. וְכֵן הַפּוֹסֵל אֶת אֲחֵרִים תָּמִיד. כְּגוֹן שֶׁנּוֹתֵן שֶׁמֶץ בְּמִשְׁפָּחוֹת אוֹ בִּיחִידִים וְאוֹמֵר עֲלֵיהֶן שֶׁהֵן מַמְזֵרִים. חוֹשְׁשִׁין לוֹ שֶׁמָּא מַמְזֵר הוּא. וְאִם אָמַר לָהֶן שֶׁהֵם עֲבָדִים חוֹשְׁשִׁין לוֹ שֶׁמָּא עֶבֶד הוּא. שֶׁכָּל הַפּוֹסֵל בְּמוּמוֹ פּוֹסֵל. וְכֵן כָּל מִי שֶׁיֵּשׁ בּוֹ עַזּוּת פָּנִים אוֹ אַכְזָרִיּוּת וְשׂוֹנֵא אֶת הַבְּרִיּוֹת וְאֵינוֹ גּוֹמֵל לָהֶם חֶסֶד חוֹשְׁשִׁין לוֹ בְּיוֹתֵר שֶׁמָּא גִּבְעוֹנִי הוּא. שֶׁסִּימָנֵי יִשְׂרָאֵל הָאֻמָּה הַקְּדוֹשָׁה בַּיְשָׁנִין רַחֲמָנִים וְגוֹמְלֵי חֲסָדִים. וּבַגִּבְעוֹנִים הוּא אוֹמֵר (שמואל ב כא ב) \"וְהַגִּבְעֹנִים לֹא מִבְּנֵי יִשְׂרָאֵל הֵמָּה\" לְפִי שֶׁהֵעֵזּוּ פְּנֵיהֶם וְלֹא נִתְפַּיְּסוּ וְלֹא רִחֲמוּ עַל בְּנֵי שָׁאוּל וְלֹא גָּמְלוּ לְיִשְׂרָאֵל חֶסֶד לִמְחל לִבְנֵי מַלְכָּם וְהֵם עָשׂוּ עִמָּהֶם חֶסֶד וְהֶחֱיוּם בַּתְּחִלָּה:","מִשְׁפָּחָה שֶׁקָּרָא עָלֶיהָ עַרְעַר וְהוּא שֶׁיָּעִידוּ שְׁנַיִם שֶׁנִּתְעָרֵב בָּהֶן מַמְזֵר אוֹ חָלָל אוֹ שֶׁיֵּשׁ בָּהֶן עַבְדוּת הֲרֵי זֶה סָפֵק. וְאִם מִשְׁפַּחַת כֹּהֲנִים הִיא לֹא יִשָּׂא מִמֶּנָּה אִשָּׁה עַד שֶׁיִּבְדֹּק עָלֶיהָ אַרְבַּע אִמָּהוֹת שֶׁהֵן שְׁמוֹנֶה. אִמָּהּ. וְאֵם אִמָּהּ. וְאֵם אֲבִי אִמָּהּ. וְאֵם אֵם אֲבִי אִמָּהּ. וְכֵן הוּא בּוֹדֵק עַל אֵם אָבִיהָ. וְאֵם אֵם אָבִיהָ. וְאֵם אֲבִי אָבִיהָ. וְאֵם אֵם אֲבִי אָבִיהָ:","וְאִם הָיְתָה מִשְׁפָּחָה זוֹ שֶׁקָּרָא עָלֶיהָ עַרְעַר לְוִיִּם אוֹ יִשְׂרְאֵלִים. מוֹסִיף לִבְדֹּק לָהֶם זוּג אֶחָד. וְנִמְצָא בּוֹדֵק עֶשֶׂר אִמָּהוֹת. שֶׁהָעֵרוּב בַּלְוִיִּם וְיִשְׂרְאֵלִים יֶתֶר מִן הַכֹּהֲנִים:","וְלָמָּה בּוֹדֵק בַּנָּשִׁים בִּלְבַד. מִפְּנֵי שֶׁהָאֲנָשִׁים כָּל עֵת שֶׁיָּרִיבוּ זֶה עִם זֶה יְחָרֵף אֶת חֲבֵרוֹ בִּפְסוּל שֶׁיֵּשׁ בְּיִחוּסוֹ. וְאִלּוּ הָיָה שָׁם פָּסוּל הָיָה נִשְׁמָע. אֲבָל הַנָּשִׁים אֵין מְחָרְפוֹת בְּיוּחֲסִין:","וְלָמָּה יִבְדֹּק הָאִישׁ כְּשֶׁיִּרְצֶה לִשָּׂא מִמִּשְׁפָּחָה זוֹ שֶׁהֻרְעָה חֶזְקָתָהּ וְלֹא תִּבְדֹּק אִשָּׁה שֶׁתִּנָּשֵׂא לָהֶן. מִפְּנֵי שֶׁלֹּא הֻזְהֲרוּ כְּשֵׁרוֹת לְהִנָּשֵׂא לִפְסוּלִין:","כָּל שֶׁקּוֹרִין לוֹ מַמְזֵר וְשׁוֹתֵק. אוֹ נָתִין וְשׁוֹתֵק. אוֹ חָלָל וְשׁוֹתֵק. אוֹ עֶבֶד וְשׁוֹתֵק. חוֹשְׁשִׁין לוֹ וּלְמִשְׁפַּחְתּוֹ וְאֵין נוֹשְׂאִין מֵהֶן אֶלָּא אִם כֵּן בּוֹדְקִין כְּמוֹ שֶׁבֵּאַרְנוּ:","מִשְׁפָּחָה שֶׁנִּתְעָרֵב בָּהּ סְפֵק חָלָל כָּל אַלְמָנָה מֵאוֹתָהּ מִשְׁפָּחָה אֲסוּרָה לְכֹהֵן לְכַתְּחִלָּה. וְאִם נִשֵּׂאת לֹא תֵּצֵא מִפְּנֵי שֶׁהֵן שְׁתֵּי סְפֵקוֹת. שֶׁמָּא זוֹ אַלְמְנַת אוֹתוֹ חָלָל שֶׁמָּא אֵינָהּ אַלְמְנָתוֹ. וְאִם נֹאמַר שֶׁהִיא אַלְמְנָתוֹ שֶׁמָּא חָלָל הוּא שֶׁמָּא אֵינוֹ חָלָל. אֲבָל אִם נִתְעָרֵב בָּהּ חָלָל וַדַּאי כָּל אִשָּׁה מֵהֶן אֲסוּרָה לְכֹהֵן עַד שֶׁיִּבְדֹּק. וְאִם נִשֵּׂאת תֵּצֵא. וְהוּא הַדִּין אִם נִתְעָרֵב בָּהּ סְפֵק מַמְזֵר אוֹ מַמְזֵר וַדַּאי. שֶׁאֵשֶׁת מַמְזֵר וְאֵשֶׁת חָלָל לִכְהֻנָּה אִסּוּר אֶחָד הוּא כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 1":["בִימֵי אֱנוֹשׁ טָעוּ בְּנֵי הָאָדָם טָעוּת גָּדוֹל וְנִבְעֲרָה עֲצַת חַכְמֵי אוֹתוֹ הַדּוֹר וֶאֱנוֹשׁ עַצְמוֹ מִן הַטּוֹעִים הָיָה. וְזוֹ הָיְתָה טָעוּתָם. אָמְרוּ הוֹאִיל וְהָאֱלֹהִים בָּרָא כּוֹכָבִים אֵלּוּ וְגַלְגַּלִּים לְהַנְהִיג אֶת הָעוֹלָם וּנְתָנָם בַּמָּרוֹם וְחָלַק לָהֶם כָּבוֹד וְהֵם שַׁמָּשִׁים הַמְשַׁמְּשִׁים לְפָנָיו רְאוּיִין הֵם לְשַׁבְּחָם וּלְפָאֲרָם וְלַחֲלֹק לָהֶם כָּבוֹד. וְזֶהוּ רְצוֹן הָאֵל בָּרוּךְ הוּא לְגַדֵּל וּלְכַבֵּד מִי שֶׁגִּדְּלוֹ וְכִבְּדוֹ. כְּמוֹ שֶׁהַמֶּלֶךְ רוֹצֶה לְכַבֵּד הָעוֹמְדִים לְפָנָיו וְזֶהוּ כְּבוֹדוֹ שֶׁל מֶלֶךְ. כֵּיוָן שֶׁעָלָה דָּבָר זֶה עַל לִבָּם הִתְחִילוּ לִבְנוֹת לַכּוֹכָבִים הֵיכָלוֹת וּלְהַקְרִיב לָהֶן קָרְבָּנוֹת וּלְשַׁבְּחָם וּלְפָאֲרָם בִּדְבָרִים וּלְהִשְׁתַּחֲווֹת לְמוּלָם כְּדֵי לְהַשִּׂיג רְצוֹן הַבּוֹרֵא בְּדַעְתָּם הָרָעָה. וְזֶה הָיָה עִקַּר עֲבוֹדַת כּוֹכָבִים. וְכָךְ הָיוּ אוֹמְרִים עוֹבְדֶיהָ הַיּוֹדְעִים עִקָּרָהּ. לֹא שֶׁהֵן אוֹמְרִים שֶׁאֵין שָׁם אֱלוֹהַּ אֶלָּא כּוֹכָב זֶה. הוּא שֶׁיִּרְמְיָהוּ אוֹמֵר מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה כִּי בְכָל חַכְמֵי הַגּוֹיִם וּבְכָל מַלְכוּתָם מֵאֵין כָּמוֹךָ וּבְאַחַת יִבְעֲרוּ וְיִכְסָלוּ מוּסַר הֲבָלִים עֵץ הוּא. כְּלוֹמַר הַכּל יוֹדְעִים שֶׁאַתָּה הוּא לְבַדְּךָ אֲבָל טָעוּתָם וּכְסִילוּתָם שֶׁמְּדַמִּים שֶׁזֶּה הַהֶבֶל רְצוֹנְךָ הוּא:","וְאַחַר שֶׁאָרְכוּ הַיָּמִים עָמְדוּ בִּבְנֵי הָאָדָם נְבִיאֵי שֶׁקֶר וְאָמְרוּ שֶׁהָאֵל צִוָּה וְאָמַר לָהֶם עִבְדוּ כּוֹכָב פְּלוֹנִי אוֹ כָּל הַכּוֹכָבִים וְהַקְרִיבוּ לוֹ וְנַסְּכוּ לוֹ כָּךְ וְכָךְ וּבְנוּ לוֹ הֵיכָל וַעֲשׂוּ צוּרָתוֹ כְּדֵי לְהִשְׁתַּחֲווֹת לוֹ כָּל הָעָם הַנָּשִׁים וְהַקְּטַנִּים וּשְׁאָר עַמֵּי הָאָרֶץ. וּמוֹדִיעַ לָהֶם צוּרָה שֶׁבָּדָה מִלִּבּוֹ וְאוֹמֵר זוֹ הִיא צוּרַת הַכּוֹכָב פְּלוֹנִי שֶׁהוֹדִיעוּהוּ בִּנְבוּאָתוֹ. וְהִתְחִילוּ עַל דֶּרֶךְ זוֹ לַעֲשׂוֹת צוּרוֹת בַּהֵיכָלוֹת וְתַחַת הָאִילָנוֹת וּבְרָאשֵׁי הֶהָרִים וְעַל הַגְּבָעוֹת וּמִתְקַבְּצִין וּמִשְׁתַּחֲוִים לָהֶם וְאוֹמְרִים לְכָל הָעָם שֶׁזּוֹ הַצּוּרָה מֵיטִיבָה וּמְרֵעָה וְרָאוּי לְעָבְדָהּ וּלְיִרְאָה מִמֶּנָּה. וְכֹהֲנֵיהֶם אוֹמְרִים לָהֶם שֶׁבַּעֲבוֹדָה זוֹ תִּרְבּוּ וְתַצְלִיחוּ וַעֲשׂוּ כָּךְ וְכָךְ וְאַל תַּעֲשׂוּ כָּךְ וְכָךְ. וְהִתְחִילוּ כּוֹזְבִים אֲחֵרִים לַעֲמֹד וְלוֹמַר שֶׁהַכּוֹכָב עַצְמוֹ אוֹ הַגַּלְגַּל אוֹ הַמַּלְאָךְ דִּבֵּר עִמָּהֶם וְאָמַר לָהֶם עִבְדוּנִי בְּכָךְ וְכָךְ וְהוֹדִיעַ לָהֶם דֶּרֶךְ עֲבוֹדָתוֹ וַעֲשׂוּ כָּךְ וְאַל תַּעֲשׂוּ כָּךְ. וּפָשַׁט דָּבָר זֶה בְּכָל הָעוֹלָם לַעֲבֹד אֶת הַצּוּרוֹת בַּעֲבוֹדוֹת מְשֻׁנּוֹת זוֹ מִזּוֹ וּלְהַקְרִיב לָהֶם וּלְהִשְׁתַּחֲווֹת. וְכֵיוָן שֶׁאָרְכוּ הַיָּמִים נִשְׁתַּכַּח הַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא מִפִּי כָּל הַיְקוּם וּמִדַּעְתָּם וְלֹא הִכִּירוּהוּ וְנִמְצְאוּ כָּל עַם הָאָרֶץ הַנָּשִׁים וְהַקְּטַנִּים אֵינָם יוֹדְעִים אֶלָּא הַצּוּרָה שֶׁל עֵץ וְשֶׁל אֶבֶן וְהַהֵיכָל שֶׁל אֲבָנִים שֶׁנִּתְחַנְּכוּ מִקַּטְנוּתָם לְהִשְׁתַּחֲווֹת לָהּ וּלְעָבְדָהּ וּלְהִשָּׁבַע בִּשְׁמָהּ. וְהַחֲכָמִים שֶׁהָיוּ בָּהֶם כְּגוֹן כֹּהֲנֵיהֶם וְכַיּוֹצֵא בָּהֶן מְדַמִּין שֶׁאֵין שָׁם אֱלוֹהַּ אֶלָּא הַכּוֹכָבִים וְהַגַּלְגַּלִּים שֶׁנַּעֲשׂוּ הַצּוּרוֹת הָאֵלּוּ בִּגְלָלָם וּלְדַמּוֹתָן. אֲבָל צוּר הָעוֹלָמִים לֹא הָיָה שׁוּם אָדָם שֶׁהָיָה מַכִּירוֹ וְלֹא יוֹדְעוֹ אֶלָּא יְחִידִים בָּעוֹלָם כְּגוֹן חֲנוֹךְ וּמְתוּשֶׁלַח נֹחַ שֵׁם וְעֵבֶר. וְעַל דֶּרֶךְ זֶה הָיָה הָעוֹלָם הוֹלֵךְ וּמִתְגַּלְגֵּל עַד שֶׁנּוֹלַד עַמּוּדוֹ שֶׁל עוֹלָם וְהוּא אַבְרָהָם אָבִינוּ:","כֵּיוָן שֶׁנִּגְמַל אֵיתָן זֶה הִתְחִיל לְשׁוֹטֵט בְּדַעְתּוֹ וְהוּא קָטָן וְהִתְחִיל לַחֲשֹׁב בַּיּוֹם וּבַלַּיְלָה וְהָיָה תָּמֵהַּ הֵיאַךְ אֶפְשָׁר שֶׁיִּהְיֶה הַגַּלְגַּל הַזֶּה נוֹהֵג תָּמִיד וְלֹא יִהְיֶה לוֹ מַנְהִיג וּמִי יְסַבֵּב אוֹתוֹ. כִּי אִי אֶפְשָׁר שֶׁיְּסַבֵּב אֶת עַצְמוֹ. וְלֹא הָיָה לוֹ מְלַמֵּד וְלֹא מוֹדִיעַ דָּבָר אֶלָּא מֻשְׁקָע בְּאוּר כַּשְׂדִּים בֵּין עוֹבְדֵי כּוֹכָבִים הַטִּפְּשִׁים וְאָבִיו וְאִמּוֹ וְכָל הָעָם עוֹבְדֵי כּוֹכָבִים וְהוּא עוֹבֵד עִמָּהֶם וְלִבּוֹ מְשׁוֹטֵט וּמֵבִין עַד שֶׁהִשִּׂיג דֶּרֶךְ הָאֱמֶת וְהֵבִין קַו הַצֶּדֶק מִתְּבוּנָתוֹ הַנְּכוֹנָה. וְיָדַע שֶׁיֵּשׁ שָׁם אֱלוֹהַּ אֶחָד וְהוּא מַנְהִיג הַגַּלְגַּל וְהוּא בָּרָא הַכּל וְאֵין בְּכָל הַנִּמְצָא אֱלוֹהַּ חוּץ מִמֶּנּוּ. וְיָדַע שֶׁכָּל הָעוֹלָם טוֹעִים וְדָבָר שֶׁגָּרַם לָהֶם לִטְעוֹת זֶה שֶׁעוֹבְדִים אֶת הַכּוֹכָבִים וְאֶת הַצּוּרוֹת עַד שֶׁאָבַד הָאֱמֶת מִדַּעְתָּם. וּבֶן אַרְבָּעִים שָׁנָה הִכִּיר אַבְרָהָם אֶת בּוֹרְאוֹ. כֵּיוָן שֶׁהִכִּיר וְיָדַע הִתְחִיל לְהָשִׁיב תְּשׁוּבוֹת עַל בְּנֵי אוּר כַּשְׂדִּים וְלַעֲרֹךְ דִּין עִמָּהֶם וְלוֹמַר שֶׁאֵין זוֹ דֶּרֶךְ הָאֱמֶת שֶׁאַתֶּם הוֹלְכִים בָּהּ וְשִׁבֵּר הַצְּלָמִים וְהִתְחִיל לְהוֹדִיעַ לָעָם שֶׁאֵין רָאוּי לַעֲבֹד אֶלָּא לֶאֱלוֹהַּ הָעוֹלָם וְלוֹ רָאוּי לְהִשְׁתַּחֲווֹת וּלְהַקְרִיב וּלְנַסֵּךְ כְּדֵי שֶׁיַּכִּירוּהוּ כָּל הַבְּרוּאִים הַבָּאִים. וְרָאוּי לְאַבֵּד וּלְשַׁבֵּר כָּל הַצּוּרוֹת כְּדֵי שֶׁלֹּא יִטְעוּ בָּהֶן כָּל הָעָם כְּמוֹ אֵלּוּ שֶׁהֵם מְדַמִּים שֶׁאֵין שָׁם אֱלוֹהַּ אֶלָּא אֵלּוּ. כֵּיוָן שֶׁגָּבַר עֲלֵיהֶם בִּרְאָיוֹתָיו בִּקֵּשׁ הַמֶּלֶךְ לְהָרְגוֹ וְנַעֲשָׂה לוֹ נֵס וְיָצָא לְחָרָן. וְהִתְחִיל לַעֲמֹד וְלִקְרֹא בְּקוֹל גָּדוֹל לְכָל הָעוֹלָם וּלְהוֹדִיעָם שֶׁיֵּשׁ שָׁם אֱלוֹהַּ אֶחָד לְכָל הָעוֹלָם וְלוֹ רָאוּי לַעֲבֹד. וְהָיָה מְהַלֵּךְ וְקוֹרֵא וּמְקַבֵּץ הָעָם מֵעִיר לְעִיר וּמִמַּמְלָכָה לְמַמְלָכָה עַד שֶׁהִגִּיעַ לְאֶרֶץ כְּנַעַן וְהוּא קוֹרֵא שֶׁנֶּאֱמַר (בראשית כא לג) \"וַיִּקְרָא שָׁם בְּשֵׁם ה' אֵל עוֹלָם\". וְכֵיוָן שֶׁהָיוּ הָעָם מִתְקַבְּצִין אֵלָיו וְשׁוֹאֲלִין לוֹ עַל דְּבָרָיו הָיָה מוֹדִיעַ לְכָל אֶחָד וְאֶחָד כְּפִי דַּעְתּוֹ עַד שֶׁיַּחְזִירֵהוּ לְדֶרֶךְ הָאֱמֶת עַד שֶׁנִּתְקַבְּצוּ אֵלָיו אֲלָפִים וּרְבָבוֹת וְהֵם אַנְשֵׁי בֵּית אַבְרָהָם וְשָׁתַל בְּלִבָּם הָעִקָּר הַגָּדוֹל הַזֶּה וְחִבֵּר בּוֹ סְפָרִים וְהוֹדִיעוֹ לְיִצְחָק בְּנוֹ. וְיָשַׁב יִצְחָק מְלַמֵּד וּמַזְהִיר. וְיִצְחָק הוֹדִיעַ לְיַעֲקֹב וּמִנָּהוּ לְלַמֵּד וְיָשַׁב מְלַמֵּד וּמַחֲזִיק כָּל הַנִּלְוִים אֵלָיו. וְיַעֲקֹב אָבִינוּ לִמֵּד בָּנָיו כֻּלָּם וְהִבְדִּיל לֵוִי וּמִנָּהוּ רֹאשׁ וְהוֹשִׁיבוֹ בִּישִׁיבָה לְלַמֵּד דֶּרֶךְ הַשֵּׁם וְלִשְׁמֹר מִצְוַת אַבְרָהָם. וְצִוָּה אֶת בָּנָיו שֶׁלֹּא יַפְסִיקוּ מִבְּנֵי לֵוִי מְמֻנֶּה אַחַר מְמֻנֶּה כְּדֵי שֶׁלֹּא תִשָּׁכַח הַלִּמּוּד. וְהָיָה הַדָּבָר הוֹלֵךְ וּמִתְגַּבֵּר בִּבְנֵי יַעֲקֹב וּבַנִּלְוִים עֲלֵיהֶם וְנַעֲשֵׂית בָּעוֹלָם אֻמָּה שֶׁהִיא יוֹדַעַת אֶת ה'. עַד שֶׁאָרְכוּ הַיָּמִים לְיִשְׂרָאֵל בְּמִצְרַיִם וְחָזְרוּ לִלְמֹד מַעֲשֵׂיהֶן וְלַעֲבֹד כּוֹכָבִים כְּמוֹתָן חוּץ מִשֵּׁבֶט לֵוִי שֶׁעָמַד בְּמִצְוַת אָבוֹת. וּמֵעוֹלָם לֹא עָבַד שֵׁבֶט לֵוִי עֲבוֹדַת כּוֹכָבִים. וְכִמְעַט קָט הָיָה הָעִקָּר שֶׁשָּׁתַל אַבְרָהָם נֶעֱקָר וְחוֹזְרִין בְּנֵי יַעֲקֹב לְטָעוּת הָעוֹלָם וּתְעִיּוֹתָן. וּמֵאַהֲבַת ה' אוֹתָנוּ וּמִשָּׁמְרוֹ אֶת הַשְּׁבוּעָה לְאַבְרָהָם אָבִינוּ עָשָׂה משֶׁה רַבֵּנוּ רַבָּן שֶׁל כָּל הַנְּבִיאִים וּשְׁלָחוֹ. כֵּיוָן שֶׁנִּתְנַבֵּא משֶׁה רַבֵּנוּ וּבָחַר ה' יִשְׂרָאֵל לְנַחֲלָה הִכְתִּירָן בְּמִצְוֹת וְהוֹדִיעָם דֶּרֶךְ עֲבוֹדָתוֹ וּמַה יִּהְיֶה מִשְׁפַּט עֲבוֹדַת כּוֹכָבִים וְכָל הַטּוֹעִים אַחֲרֶיהָ:"],"Mishneh Torah, Foundations of the Torah 1":["יְסוֹד הַיְסוֹדוֹת וְעַמּוּד הַחָכְמוֹת לֵידַע שֶׁיֵּשׁ שָׁם מָצוּי רִאשׁוֹן. וְהוּא מַמְצִיא כָּל נִמְצָא. וְכָל הַנִּמְצָאִים מִשָּׁמַיִם וָאָרֶץ וּמַה שֶּׁבֵּינֵיהֶם לֹא נִמְצְאוּ אֶלָּא מֵאֲמִתַּת הִמָּצְאוֹ:","וְאִם יַעֲלֶה עַל הַדַּעַת שֶׁהוּא אֵינוֹ מָצוּי אֵין דָּבָר אַחֵר יָכוֹל לְהִמָּצְאוֹת:","וְאִם יַעֲלֶה עַל הַדַּעַת שֶׁאֵין כָּל הַנִּמְצָאִים מִלְּבַדּוֹ מְצוּיִים הוּא לְבַדּוֹ יִהְיֶה מָצוּי. וְלֹא יִבָּטֵל הוּא לְבִטּוּלָם. שֶׁכָּל הַנִּמְצָאִים צְרִיכִין לוֹ וְהוּא בָּרוּךְ הוּא אֵינוֹ צָרִיךְ לָהֶם וְלֹא לְאֶחָד מֵהֶם. לְפִיכָךְ אֵין אֲמִתָּתוֹ כַּאֲמִתַּת אֶחָד מֵהֶם:","הוּא שֶׁהַנָּבִיא אוֹמֵר (ירמיה י י) \"וַה' אֱלֹהִים אֱמֶת\". הוּא לְבַדּוֹ הָאֱמֶת וְאֵין לְאַחֵר אֱמֶת כַּאֲמִתָּתוֹ. וְהוּא שֶׁהַתּוֹרָה אוֹמֶרֶת (דברים ד לה) \"אֵין עוֹד מִלְּבַדּוֹ\". כְּלוֹמַר אֵין שָׁם מָצוּי אֱמֶת מִלְּבַדּוֹ כְּמוֹתוֹ:","הַמָּצוּי הַזֶּה הוּא אֱלֹהֵי הָעוֹלָם אֲדוֹן כָּל הָאָרֶץ. וְהוּא הַמַּנְהִיג הַגַּלְגַּל בְּכֹחַ שֶׁאֵין לוֹ קֵץ וְתַכְלִית. בְּכֹחַ שֶׁאֵין לוֹ הֶפְסֵק. שֶׁהַגַּלְגַּל סוֹבֵב תָּמִיד וְאִי אֶפְשָׁר שֶׁיִּסֹּב בְּלֹא מְסַבֵּב. וְהוּא בָּרוּךְ הוּא הַמְסַבֵּב אוֹתוֹ בְּלֹא יָד וּבְלֹא גּוּף:","וִידִיעַת דָּבָר זֶה מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (שמות כ ב) \"אָנֹכִי ה' אֱלֹהֶיךָ\". וְכָל הַמַּעֲלֶה עַל דַּעְתּוֹ שֶׁיֵּשׁ שָׁם אֱלוֹהַּ אַחֵר חוּץ מִזֶּה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (שמות כ ג) \"לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים עַל פָּנָי\". וְכוֹפֵר בָּעִקָּר שֶׁזֶּהוּ הָעִקָּר הַגָּדוֹל שֶׁהַכּל תָּלוּי בּוֹ:","אֱלוֹהַּ זֶה אֶחָד הוּא וְאֵינוֹ שְׁנַיִם וְלֹא יֶתֶר עַל שְׁנַיִם. אֶלָּא אֶחָד. שֶׁאֵין כְּיִחוּדוֹ אֶחָד מִן הָאֲחָדִים הַנִּמְצָאִים בָּעוֹלָם. לֹא אֶחָד כְּמִין שֶׁהוּא כּוֹלֵל אֲחָדִים הַרְבֵּה. וְלֹא אֶחָד כְּגוּף שֶׁהוּא נֶחְלָק לְמַחְלָקוֹת וְלִקְצָווֹת. אֶלָּא יִחוּד שֶׁאֵין יִחוּד אַחֵר כְּמוֹתוֹ בָּעוֹלָם. אִלּוּ הָיוּ אֱלֹהוּת הַרְבֵּה הָיוּ גּוּפִין וּגְוִיּוֹת. מִפְּנֵי שֶׁאֵין הַנִּמְנִים הַשָּׁוִין בִּמְצִיאוּתָן נִפְרָדִין זֶה מִזֶּה אֶלָּא בִּמְאֹרָעִין שֶׁיֶּאֶרְעוּ בַּגּוּפוֹת וְהַגְּוִיּוֹת. וְאִלּוּ הָיָה הַיּוֹצֵר גּוּף וּגְוִיָּה הָיָה לוֹ קֵץ וְתַכְלִית שֶׁאִי אֶפְשָׁר לִהְיוֹת גּוּף שֶׁאֵין לוֹ קֵץ. וְכָל שֶׁיֵּשׁ לְגוּפוֹ קֵץ וְתַכְלִית יֵשׁ לְכֹחוֹ קֵץ וָסוֹף. וֵאלֹהֵינוּ בָּרוּךְ שְׁמוֹ הוֹאִיל וְכֹחוֹ אֵין לוֹ קֵץ וְאֵינוֹ פּוֹסֵק שֶׁהֲרֵי הַגַּלְגַּל סוֹבֵב תָּמִיד. אֵין כֹּחוֹ כֹּחַ גּוּף. וְהוֹאִיל וְאֵינוֹ גּוּף לֹא יֶאֶרְעוּ לוֹ מְאֹרְעוֹת הַגּוּפוֹת כְּדֵי שֶׁיְּהֵא נֶחְלָק וְנִפְרָד מֵאַחֵר. לְפִיכָךְ אִי אֶפְשָׁר שֶׁיִּהְיֶה אֶלָּא אֶחָד. וִידִיעַת דָּבָר זֶה מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (דברים ו ד) \"ה' אֱלֹהֵינוּ ה' אֶחָד\":","הֲרֵי מְפֹרָשׁ בַּתּוֹרָה וּבַנְּבִיאִים שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא גּוּף וּגְוִיָּה שֶׁנֶּאֱמַר (יהושע ב יא) \"כִּי ה' אֱלֹהֵיכֶם הוּא אֱלֹהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת\". וְהַגּוּף לֹא יִהְיֶה בִּשְׁנֵי מְקוֹמוֹת. וְנֶאֱמַר (דברים ד טו) \"כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה\". וְנֶאֱמַר (ישעיה מ כה) \"וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה\". וְאִלּוּ הָיָה גּוּף הָיָה דּוֹמֶה לִשְׁאָר גּוּפִים:","אִם כֵּן מַהוּ זֶה שֶׁכָּתוּב בַּתּוֹרָה \"וְתַחַת רַגְלָיו\". (שמות לא יח) \"כְּתוּבִים בְּאֶצְבַּע אֱלֹהִים\". \"יַד ה'\". \"עֵינֵי ה'\". \"אָזְנֵי ה'\". וְכַיּוֹצֵא בִּדְבָרִים הָאֵלּוּ. הַכּל לְפִי דַּעְתָּן שֶׁל בְּנֵי אָדָם הוּא שֶׁאֵינָן מַכִּירִין אֶלָּא (הַנּוֹפוֹת) [הַגּוּפוֹת] וְדִבְּרָה תּוֹרָה כִּלְשׁוֹן בְּנֵי אָדָם. וְהַכֹּל כִּנּוּיִים הֵן. שֶׁנֶּאֱמַר (דברים לב מא) \"אִם שַׁנּוֹתִי בְּרַק חַרְבִּי\". וְכִי חֶרֶב יֵשׁ לוֹ וּבְחֶרֶב הוּא הוֹרֵג אֶלָּא מָשָׁל וְהַכֹּל מָשָׁל. רְאָיָה לַדָּבָר שֶׁנָּבִיא אֶחָד אוֹמֵר שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא (דניאל ז ט) \"לְבוּשֵׁיִהּ כִּתְלַג חִוֵּר\". וְאֶחָד רָאָהוּ (ישעיה סג א) \"חֲמוּץ בְּגָדִים מִבָּצְרָה\". משֶׁה רַבֵּנוּ עַצְמוֹ רָאָהוּ עַל הַיָּם כְּגִבּוֹר עוֹשֶׂה מִלְחָמָה. וּבְסִינַי כִּשְׁלִיחַ צִבּוּר עָטוּף. לוֹמַר שֶׁאֵין לוֹ דְּמוּת וְצוּרָה אֶלָּא הַכּל בְּמַרְאֵה הַנְּבוּאָה וּבְמַחֲזֶה. וַאֲמִתַּת הַדָּבָר אֵין דַּעְתּוֹ שֶׁל אָדָם מֵבִין וְלֹא יְכוֹלָה לְהַשִּׂיגוֹ וּלְחָקְרוֹ. וְזֶה שֶׁאָמַר הַכָּתוּב (איוב יא ז) \"הַחֵקֶר אֱלוֹהַּ תִּמְצָא אִם עַד תַּכְלִית שַׁדַּי תִּמְצָא\":","מַהוּ זֶה שֶׁבִּקֵּשׁ משֶׁה רַבֵּנוּ לְהַשִּׂיג כְּשֶׁאָמַר (שמות לג יח) \"הַרְאֵנִי נָא אֶת כְּבֹדֶךָ\". בִּקֵּשׁ לֵידַע אֲמִתַּת הִמָּצְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁיִּהְיֶה יָדוּעַ בְּלִבּוֹ כְּמוֹ יְדִיעַת אֶחָד מִן הָאֲנָשִׁים שֶׁרָאָה פָּנָיו וְנֶחְקְקָה צוּרָתוֹ בְּלִבּוֹ שֶׁנִּמְצָא אוֹתוֹ הָאִישׁ נִפְרָד בְּדַעְתּוֹ מִשְּׁאָר הָאֲנָשִׁים. כָּךְ בִּקֵּשׁ משֶׁה רַבֵּנוּ לִהְיוֹת מְצִיאוּת הַקָּדוֹשׁ בָּרוּךְ הוּא נִפְרֶדֶת בְּלִבּוֹ מִשְּׁאָר הַנִּמְצָאִים עַד שֶׁיֵּדַע אֲמִתַּת הִמָּצְאוֹ כַּאֲשֶׁר הִיא. וֶהֱשִׁיבוֹ בָּרוּךְ הוּא שֶׁאֵין כֹּחַ בְּדַעַת הָאָדָם הַחַי שֶׁהוּא מְחֻבָּר מִגּוּף וְנֶפֶשׁ לְהַשִּׂיג אֲמִתַּת דָּבָר זֶה עַל בֻּרְיוֹ. וְהוֹדִיעוֹ בָּרוּךְ הוּא מַה שֶּׁלֹּא יָדַע אָדָם לְפָנָיו וְלֹא יֵדַע לְאַחֲרָיו. עַד שֶׁהִשִּׂיג מֵאֲמִתַּת הִמָּצְאוֹ דָּבָר שֶׁנִּפְרָד הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדַעְתּוֹ מִשְּׁאָר הַנִּמְצָאִים. כְּמוֹ שֶׁיִּפָּרֵד אֶחָד מִן הָאֲנָשִׁים שֶׁרָאָה אֲחוֹרָיו וְהִשִּׂיג כָּל גּוּפוֹ וּמַלְבּוּשׁוֹ בְּדַעְתּוֹ מִשְּׁאָר גּוּפֵי הָאֲנָשִׁים. וְעַל דָּבָר זֶה רָמַז הַכָּתוּב וְאָמַר (שמות לג כג) \"וְרָאִיתָ אֶת אֲחֹרָי וּפָנַי לֹא יֵרָאוּ\":","וְכֵיוָן שֶׁנִּתְבָּרֵר שֶׁאֵינוֹ גּוּף וּגְוִיָּה יִתְבָּרֵר שֶׁלֹּא יֶאֱרַע לוֹ אֶחָד מִמְּאֹרְעוֹת הַגּוּפוֹת. לֹא חִבּוּר וְלֹא פֵּרוּד. לֹא מָקוֹם וְלֹא מִדָּה. לֹא עֲלִיָּה וְלֹא יְרִידָה. וְלֹא יָמִין וְלֹא שְׂמֹאל. וְלֹא פָּנִים וְלֹא אָחוֹר. וְלֹא יְשִׁיבָה וְלֹא עֲמִידָה. וְאֵינוֹ מָצוּי בִּזְמַן עַד שֶׁיִּהְיֶה לוֹ רֵאשִׁית וְאַחֲרִית וּמִנְיַן שָׁנִים. וְאֵינוֹ מִשְׁתַּנֶּה שֶׁאֵין לוֹ דָּבָר שֶׁיִּגְרֹם לוֹ שִׁנּוּי. וְאֵין לוֹ לֹא מָוֶת וְלֹא חַיִּים כְּחַיֵּי הַגּוּף הַחַי. וְלֹא סִכְלוּת וְלֹא חָכְמָה כְּחָכְמַת הָאִישׁ הֶחָכָם. לֹא שֵׁנָה וְלֹא הֲקִיצָה. וְלֹא כַּעַס וְלֹא שְׂחוֹק וְלֹא שִׂמְחָה וְלֹא עַצְבוּת. וְלֹא שְׁתִיקָה וְלֹא דִּבּוּר כְּדִבּוּר בְּנֵי אָדָם. וְכָךְ אָמְרוּ חֲכָמִים אֵין לְמַעְלָה לֹא יְשִׁיבָה וְלֹא עֲמִידָה וְלֹא עֹרֶף וְלֹא עִפּוּי:","וְהוֹאִיל וְהַדָּבָר כֵּן הוּא. כָּל הַדְּבָרִים הַלָּלוּ וְכַיּוֹצֵא בָּהֶן שֶׁנֶּאֶמְרוּ בַּתּוֹרָה וּבְדִבְרֵי נְבִיאִים הַכּל מָשָׁל וּמְלִיצָה הֵן. כְּמוֹ שֶׁנֶּאֱמַר (תהילים ב ד) \"יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק\". (דברים לב כא) \"כִּעֲסוּנִי בְּהַבְלֵיהֶם\". (דברים כח סג) \"כַּאֲשֶׁר שָׂשׂ ה'\" וְכַיּוֹצֵא בָּהֶן. עַל הַכּל אָמְרוּ חֲכָמִים דִּבְּרָה תּוֹרָה כִּלְשׁוֹן בְּנֵי אָדָם. וְכֵן הוּא אוֹמֵר (ירמיה ז יט) \"הַאֹתִי הֵם מַכְעִסִים\". הֲרֵי הוּא אוֹמֵר (מלאכי ג ו) \"אֲנִי ה' לֹא שָׁנִיתִי\". וְאִלּוּ הָיָה פְּעָמִים כּוֹעֵס וּפְעָמִים שָׂמֵחַ הָיָה מִשְׁתַּנֶּה. וְכָל הַדְּבָרִים הָאֵלּוּ אֵינָן מְצוּיִין אֶלָּא לַגּוּפִים הָאֲפֵלִים הַשְּׁפָלִים שׁוֹכְנֵי בָּתֵּי חֹמֶר אֲשֶׁר בֶּעָפָר יְסוֹדָם אֲבָל הוּא בָּרוּךְ הוּא יִתְבָּרַךְ וְיִתְרוֹמַם עַל כָּל זֶה:"],"Mishneh Torah, Fringes 3":["כְּסוּת שֶׁחַיָּב אָדָם לַעֲשׂוֹת בָּהּ צִיצִית מִן הַתּוֹרָה הִיא כְּסוּת שֶׁיֵּשׁ לָהּ אַרְבַּע כְּנָפַיִם אוֹ יוֹתֵר עַל אַרְבַּע. וְתִהְיֶה מִדָּתָהּ כְּדֵי שֶׁיִּתְכַּסֶּה בָּהּ רֹאשׁוֹ וְרֻבּוֹ שֶׁל קָטָן הַמִּתְהַלֵּךְ לְבַדּוֹ בַּשּׁוּק וְאֵינוֹ צָרִיךְ אַחֵר לְשָׁמְרוֹ וְלֵילֵךְ עִמּוֹ. וְתִהְיֶה הַכְּסוּת שֶׁל צֶמֶר אוֹ שֶׁל פִּשְׁתָּן בִּלְבַד:","אֲבָל טַלִּית שֶׁל שְׁאָר מִינִין כְּגוֹן בִּגְדֵי מֶשִׁי וּבִגְדֵי צֶמֶר גֶּפֶן וּבִגְדֵי צֶמֶר גְּמַלִּים וְצֶמֶר אַרְנָבִים וְנוֹצָה שֶׁל עִזִּים וְכַיּוֹצֵא בָּהֶן אֵין חַיָּבִין בְּמִצְוַת צִיצִית אֶלָּא מִדִּבְרֵי חֲכָמִים כְּדֵי לְהִזָּהֵר בְּמִצְוַת צִיצִית. וְהוּא שֶׁתִּהְיֶה מְרֻבַּעַת אוֹ יוֹתֵר עַל אַרְבַּע וְיִהְיֶה שִׁעוּרָהּ כַּשִּׁעוּר שֶׁאָמַרְנוּ. שֶׁכָּל הַבְּגָדִים הָאֲמוּרִים בַּתּוֹרָה סְתָם אֵינָם אֶלָּא צֶמֶר וּפִשְׁתִּים בִּלְבַד:","(דברים כב יב) ״עַל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ״ בַּעֲלַת אַרְבַּע וְלֹא בַּעֲלַת שָׁלֹשׁ. אִם כֵּן בַּעֲלַת אַרְבַּע וְלֹא בַּעֲלַת חָמֵשׁ. תַּלְמוּד לוֹמַר (דברים כב יב) ״אֲשֶׁר תְּכַסֶּה בָּהּ״ אֲפִלּוּ בַּעֲלַת חָמֵשׁ אוֹ יוֹתֵר עַל זֶה. וְלָמָּה אֲנִי מְחַיֵּב בַּעֲלַת חָמֵשׁ וּפוֹטֵר בַּעֲלַת שָׁלֹשׁ וּשְׁתֵּיהֶן אֵינָן בַּעֲלֵי אַרְבַּע כְּנָפוֹת. מִפְּנֵי שֶׁיֵּשׁ בִּכְלַל הֶחָמֵשׁ אַרְבַּע. לְפִיכָךְ כְּשֶׁהוּא עוֹשֶׂה צִיצִית לְבַעֲלַת חָמֵשׁ אוֹ שֵׁשׁ אֵינוֹ עוֹשֶׂה אֶלָּא לְאַרְבַּע כְּנָפַיִם הַמְרֻחָקוֹת זוֹ מִזּוֹ מֵאוֹתָן הֶחָמֵשׁ אוֹ הַשֵּׁשׁ בִּלְבַד. שֶׁנֶּאֱמַר עַל אַרְבַּע כַּנְפוֹת כְּסוּתְךָ:","כְּסוּת שֶׁל בֶּגֶד וּכְנָפֶיהָ שֶׁל עוֹר חַיֶּבֶת. הִיא שֶׁל עוֹר וּכְנָפֶיהָ שֶׁל בֶּגֶד פְּטוּרָה שֶׁאֵין הוֹלְכִין אֶלָּא אַחַר עִקַּר הַכְּסוּת. כְּסוּת שֶׁל שְׁנֵי שֻׁתָּפִין חַיֶּבֶת שֶׁנֶּאֱמַר (במדבר טו לח) ״עַל כַּנְפֵי בִגְדֵיהֶם״. לֹא נֶאֱמַר (דברים כב יב) ״כְּסוּתְךָ״ אֶלָּא לְמַעֵט שְׁאוּלָה שֶׁהַטַּלִּית הַשְּׁאוּלָה פְּטוּרָה מִן הַצִּיצִית שְׁלֹשִׁים יוֹם מִכָּאן וְאֵילָךְ חַיֶּבֶת:","כְּסוּת שֶׁל צֶמֶר עוֹשִׂין לָבָן שֶׁלָּהּ חוּטֵי צֶמֶר. וּכְסוּת שֶׁל פִּשְׁתָּן עוֹשִׂין לָבָן שֶׁלָּהּ חוּטֵי פִּשְׁתָּן מִמֶּנָּה. וּשְׁאָר בְּגָדִים עוֹשִׂין לָבָן שֶׁל כָּל מִין וָמִין מִמִּינוֹ כְּגוֹן חוּטֵי מֶשִׁי לִכְסוּת מֶשִׁי וְחוּטֵי נוֹצָה לִכְסוּת נוֹצָה. וְאִם רָצָה לַעֲשׂוֹת לָבָן לְכָל שְׁאָר מִינִים מִצֶּמֶר אוֹ מִפִּשְׁתִּים עוֹשֶׂה. מִפְּנֵי שֶׁהַצֶּמֶר וְהַפִּשְׁתָּן פּוֹטְרִין בֵּין בְּמִינָן בֵּין שֶׁלֹּא בְּמִינָן וּשְׁאָר מִינִין בְּמִינָן פּוֹטְרִין שֶׁלֹּא בְּמִינָן אֵין פּוֹטְרִין:","וּמַה הוּא לַעֲשׂוֹת חוּטֵי צֶמֶר בִּכְסוּת שֶׁל פִּשְׁתָּן אוֹ חוּטֵי פִּשְׁתָּן בִּכְסוּת שֶׁל צֶמֶר אַף עַל פִּי שֶׁהוּא לָבָן לְבַדּוֹ בְּלֹא תְּכֵלֶת. בְּדִין הוּא שֶׁיְּהֵא מֻתָּר שֶׁהַשַּׁעַטְנֵז מֻתָּר לְעִנְיַן צִיצִית. שֶׁהֲרֵי הַתְּכֵלֶת צֶמֶר הוּא וּמַטִּילִין אוֹתָהּ לְפִשְׁתָּן. וּמִפְּנֵי מָה אֵין עוֹשִׂין כֵּן. מִפְּנֵי שֶׁאֶפְשָׁר לַעֲשׂוֹת הַלָּבָן שֶׁלָּהּ מִמִּינָהּ. וְכָל מָקוֹם שֶׁאַתָּה מוֹצֵא עֲשֵׂה וְלֹא תַּעֲשֶׂה אִם יָכוֹל אַתָּה לְקַיֵּם אֶת שְׁתֵּיהֶן הֲרֵי מוּטָב. וְאִם לָאו יָבוֹא עֲשֵׂה וְיִדְחֶה אֶת לֹא תַּעֲשֶׂה. וְכָאן אֶפְשָׁר לְקַיֵּם אֶת שְׁתֵּיהֶן:","כְּסוּת שֶׁל פִּשְׁתָּן אֵין מַטִּילִין בָּהּ תְּכֵלֶת אֶלָּא עוֹשִׂין הַלָּבָן בִּלְבַד שֶׁל חוּטֵי פִּשְׁתָּן. לֹא מִפְּנֵי שֶׁהַצִּיצִית נִדְחֵית מִפְּנֵי הַשַּׁעַטְנֵז אֶלָּא גְּזֵרָה מִדִּבְרֵיהֶם שֶׁמָּא יִתְכַּסֶּה בָּהּ בַּלַּיְלָה שֶׁאֵינָהּ זְמַן חִיּוּב צִיצִית וְנִמְצָא עוֹבֵר עַל לֹא תַּעֲשֶׂה בְּעֵת שֶׁאֵין שָׁם מִצְוַת עֲשֵׂה. שֶׁחוֹבַת הַצִּיצִית בַּיּוֹם וְלֹא בַּלַּיְלָה שֶׁנֶּאֱמַר (במדבר טו לט) ״וּרְאִיתֶם אֹתוֹ״, בִּשְׁעַת רְאִיָּה. וְסוּמָא חַיָּב בְּצִיצִית, אַף עַל פִּי שֶׁאֵינוֹ רוֹאֶה אֲחֵרִים רוֹאִין אוֹתוֹ:","מֻתָּר לָאָדָם לִלְבּשׁ צִיצִית בַּלַּיְלָה בֵּין בְּחל בֵּין בְּשַׁבָּת וְאַף עַל פִּי שֶׁאֵינוֹ זְמַנָּהּ וּבִלְבַד שֶׁלֹּא יְבָרֵךְ. וּמֵאֵימָתַי יְבָרֵךְ עַל הַצִּיצִית בַּשַּׁחַר. מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת שֶׁבָּהּ לַלָּבָן שֶׁבָּהּ. וְכֵיצַד מְבָרֵךְ עָלֶיהָ. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהִתְעַטֵּף בְּצִיצִית. וְכָל זְמַן שֶׁמִּתְעַטֵּף בָּהּ בַּיּוֹם מְבָרֵךְ עָלֶיהָ קֹדֶם שֶׁיִּתְעַטֵּף. וְאֵינוֹ מְבָרֵךְ עַל הַצִּיצִית בִּשְׁעַת עֲשִׂיָּתָהּ מִפְּנֵי שֶׁסּוֹף הַמִּצְוָה הוּא שֶׁיִּתְעַטֵּף בָּהּ:","וּמֻתָּר לְהִכָּנֵס בְּצִיצִית לְבֵית הַכִּסֵּא וּלְבֵית הַמֶּרְחָץ. נִפְסְקוּ לוֹ חוּטֵי לָבָן אוֹ תְּכֵלֶת זוֹרְקוֹ בָּאַשְׁפָּה מִפְּנֵי שֶׁהִיא מִצְוָה שֶׁאֵין בְּגוּפָהּ קְדֻשָּׁה. וְאָסוּר לִמְכֹּר טַלִּית מְצֻיֶּצֶת לְגוֹי עַד שֶׁיַּתִּיר צִיצִיּוֹתֶיהָ. לֹא מִפְּנֵי שֶׁיֵּשׁ בְּגוּפָהּ קְדֻשָּׁה אֶלָּא שֶׁמָּא יִתְעַטֵּף בָּהּ וְיִתְלַוֶּה עִמּוֹ יִשְׂרָאֵל וִידַמֶּה שֶׁהוּא יִשְׂרָאֵל וְיַהַרְגֶּנּוּ. נָשִׁים וַעֲבָדִים וּקְטַנִּים פְּטוּרִין מִן הַצִּיצִית מִן הַתּוֹרָה. וּמִדִּבְרֵי סוֹפְרִים שֶׁכָּל קָטָן שֶׁיּוֹדֵעַ לְהִתְעַטֵּף חַיָּב בְּצִיצִית כְּדֵי לְחַנְּכוֹ בְּמִצְוֹת. וְנָשִׁים וַעֲבָדִים שֶׁרָצוּ לְהִתְעַטֵּף בְּצִיצִית מִתְעַטְּפִים בְּלֹא בְּרָכָה. וְכֵן שְׁאָר מִצְוֹת עֲשֵׂה שֶׁהַנָּשִׁים פְּטוּרוֹת מֵהֶן אִם רָצוּ לַעֲשׂוֹת אוֹתָן בְּלֹא בְּרָכָה אֵין מְמַחִין בְּיָדָן. טֻמְטוּם וְאַנְדְּרוֹגִינוּס חַיָּבִין בְּכֻלָּן מִסָּפֵק לְפִיכָךְ אֵין מְבָרְכִין אֶלָּא עוֹשִׂין בְּלֹא בְּרָכָה:","הֵיאַךְ חִיּוּב מִצְוַת הַצִּיצִית. כָּל אָדָם שֶׁחַיָּב לַעֲשׂוֹת מִצְוָה זוֹ אִם יִתְכַּסֶּה בִּכְסוּת הָרָאוּי לְצִיצִית יַטִּיל לָהּ צִיצִית וְאַחַר כָּךְ יִתְכַּסֶּה בָּהּ. וְאִם נִתְכַּסָּה בָּהּ בְּלֹא צִיצִית הֲרֵי בִּטֵּל מִצְוַת עֲשֵׂה. אֲבָל בְּגָדִים הָרְאוּיִים לְצִיצִית כָּל זְמַן שֶׁלֹּא יִתְכַּסֶּה בָּהֶן אָדָם אֶלָּא מְקֻפָּלִים וּמֻנָּחִים פְּטוּרִין מִן הַצִּיצִית שֶׁאֵינָהּ חוֹבַת הַטַּלִּית אֶלָּא חוֹבַת הָאִישׁ שֶׁיֵּשׁ לוֹ טַלִּית:","אַף עַל פִּי שֶׁאֵין אָדָם מְחֻיָּב לִקְנוֹת לוֹ טַלִּית וּלְהִתְעַטֵּף בָּהּ כְּדֵי שֶׁיַּעֲשֶׂה בָּהּ צִיצִית אֵין רָאוּי לְאָדָם חָסִיד שֶׁיִּפְטֹר עַצְמוֹ מִמִּצְוָה זוֹ. אֶלָּא לְעוֹלָם יִשְׁתַּדֵּל לִהְיוֹת עָטוּף בִּכְסוּת הַמְחֻיֶּבֶת בַּצִּיצִית כְּדֵי שֶׁיְּקַיֵּם מִצְוָה זוֹ. וּבִשְׁעַת הַתְּפִלָּה צָרִיךְ לְהִזָּהֵר בְּיוֹתֵר. גְּנַאי גָּדוֹל הוּא לְתַלְמִידֵי חֲכָמִים שֶׁיִּתְפַּלְּלוּ וְהֵם אֵינָם עֲטוּפִים:","לְעוֹלָם יְהֵא אָדָם זָהִיר בְּמִצְוַת צִיצִית שֶׁהֲרֵי הַכָּתוּב שְׁקָלָהּ וְתָלָה בָּהּ כָּל הַמִּצְוֹת כֻּלָּן שֶׁנֶּאֱמַר (במדבר טו לט) ״וּרְאִיתֶם אֹתוֹ וּזְכַרְתֶּם אֶת כָּל מִצְוֹת יְיָ׳‎״:סָלִיק הִלְכוֹת צִיצִית"],"Mishneh Torah, Heave Offerings 10":["זָר שֶׁאָכַל תְּרוּמָה בִּשְׁגָגָה מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ. אַף עַל פִּי שֶׁיּוֹדֵעַ שֶׁהִיא תְּרוּמָה וְשֶׁהוּא מֻזְהָר עָלֶיהָ אֲבָל לֹא יָדַע אִם חַיָּב עָלֶיהָ מִיתָה אִם לָאו הֲרֵי זוֹ שְׁגָגָה וּמְשַׁלֵּם קֶרֶן וְחֹמֶשׁ:","אֶחָד הָאוֹכֵל דָּבָר שֶׁדַּרְכּוֹ לֶאֱכל וְאֶחָד הַשּׁוֹתֶה דָּבָר שֶׁדַּרְכּוֹ לִשְׁתּוֹת וְאֶחָד הַסָּךְ דָּבָר שֶׁדַּרְכּוֹ לָסוּךְ שֶׁנֶּאֱמַר (ויקרא כב טו) \"וְלֹא יְחַלְּלוּ אֶת קָדְשֵׁי בְּנֵי יִשְׂרָאֵל\" לְרַבּוֹת אֶת הַסָּךְ. וְאֶחָד הָאוֹכֵל תְּרוּמָה טְהוֹרָה אוֹ טְמֵאָה בִּשְׁגָגָה מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ. וְאֵינוֹ חַיָּב בְּחֹמֶשׁ עַד שֶׁיֹּאכַל כְּזַיִת שֶׁנֶּאֱמַר (ויקרא כב יד) \"כִּי יֹאכַל קֹדֶשׁ בִּשְׁגָגָה\" וְאֵין אֲכִילָה פְּחוּתָה מִכְּזַיִת. וּכְשֵׁם שֶׁאֲכִילַת תְּרוּמָה בִּכְזַיִת כָּךְ שְׁתִיָּה בִּכְזַיִת:","אָכַל וְחָזַר וְאָכַל. שָׁתָה וְחָזַר וְשָׁתָה. אִם יֵשׁ מִתְּחִלַּת אֲכִילָה רִאשׁוֹנָה עַד סוֹף אֲכִילָה אַחֲרוֹנָה כְּדֵי אֲכִילַת פְּרָס וּמִתְּחִלַּת שְׁתִיָּה רִאשׁוֹנָה עַד סוֹף שְׁתִיָּה אַחֲרוֹנָה כְּדֵי שְׁתִיַּת רְבִיעִית הֲרֵי אֵלּוּ מִצְטָרְפִין לִכְזַיִת:","הַתְּרוּמָה וּתְרוּמַת מַעֲשֵׂר בֵּין שֶׁל דְּמַאי בֵּין שֶׁל וַדַּאי וְהַחַלָּה וְהַבִּכּוּרִים כֻּלָּן מִצְטָרְפִין לִכְזַיִת לְחַיֵּב עֲלֵיהֶן מִיתָה וְחֹמֶשׁ שֶׁכֻּלָּן נִקְרְאוּ תְּרוּמָה. וּמִן הַדִּין הָיָה שֶׁאֵין חַיָּבִין חֹמֶשׁ עַל תְּרוּמַת מַעֲשֵׂר שֶׁל דְּמַאי כְּמוֹ שֶׁאֵין חַיָּבִין עַל מַעֲשֵׂר [שֵׁנִי] שֶׁלּוֹ כְּמוֹ שֶׁיִּתְבָּאֵר. אֲבָל אָמְרוּ חֲכָמִים אִם לֹא יִתְחַיֵּב עָלֶיהָ חֹמֶשׁ יְזַלְזְלוּ בָּהּ:","אָכַל תְּרוּמָה בְּמֵזִיד [וְהִתְרוּ בּוֹ לוֹקֶה וְאֵינוֹ מְשַׁלֵּם. לֹא הִתְרוּ בּוֹ] אִם הָיְתָה טְהוֹרָה מְשַׁלֵּם הַקֶּרֶן וְאֵינוֹ מְשַׁלֵּם אֶת הַחֹמֶשׁ. וְאִם הָיְתָה טְמֵאָה מְשַׁלֵּם דְּמֵי עֵצִים מִפְּנֵי שֶׁאֵינָהּ רְאוּיָה אֶלָּא לְהַסָּקָה. לְפִיכָךְ אִם אָכַל תְּרוּמַת תּוּתִים וְרִמּוֹנִים וְכַיּוֹצֵא בָּהֶם שֶׁנִּטְמְאוּ פָּטוּר מִן הַתַּשְׁלוּמִין שֶׁהֲרֵי אֵינָם רְאוּיִין לְהַסָּקָה:","הָאוֹכֵל תְּרוּמַת חָמֵץ בְּפֶסַח בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה בֵּין טְמֵאָה בֵּין טְהוֹרָה פָּטוּר מִן הַתַּשְׁלוּמִין. אֲפִלּוּ הִפְרִישָׁהּ מַצָּה וְהֶחְמִיצָה פָּטוּר. וַאֲפִלּוּ דְּמֵי עֵצִים אֵינוֹ מְשַׁלֵּם שֶׁהֲרֵי אֵינָהּ רְאוּיָה לְהַסָּקָה מִפְּנֵי שֶׁהִיא אֲסוּרָה בַּהֲנָאָה אֵין לָהּ דָּמִים:","אֲבָל הַשּׁוֹגֵג שֶׁאָכַל תְּרוּמָה בְּיוֹם הַכִּפּוּרִים אוֹ שֶׁאָכַל תְּרוּמָה נְקוּרָה. וְהַשּׁוֹתֶה יֵין תְּרוּמָה שֶׁנִּתְגַּלָּה. וְהַסָּךְ יַיִן וְשֶׁמֶן כְּאֶחָד אוֹ שֶׁשָּׁתָה שֶׁמֶן וְחֹמֶץ כְּאֶחָד אוֹ שֶׁכָּסַס אֶת הַחִטִּים אוֹ גָּמַע אֶת הַחֹמֶץ הֲרֵי זֶה מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ:","הָיָה שָׂבֵעַ וְקָץ בִּמְזוֹנוֹ וְהוֹסִיף עַל שָׂבְעוֹ בַּאֲכִילַת תְּרוּמָה אֵינוֹ מְשַׁלֵּם אֶת הַחֹמֶשׁ שֶׁנֶּאֱמַר (ויקרא כב יד) \"כִּי יֹאכַל\" לֹא שֶׁיַּזִּיק אֶת עַצְמוֹ. וְכֵן הַכּוֹסֵס אֶת הַשְּׂעוֹרִים פָּטוּר מִן הַחֹמֶשׁ מִפְּנֵי שֶׁהִזִּיק עַצְמוֹ:","זָר שֶׁבָּלַע שֵׁזָפִין שֶׁל תְּרוּמָה וֶהֱקִיאָן וּבָא אַחֵר וַאֲכָלָן גַּם הוּא בִּשְׁגָגָה הָרִאשׁוֹן מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ וְהַשֵּׁנִי מְשַׁלֵּם דְּמֵי עֵצִים לָרִאשׁוֹן:","הַמַּאֲכִיל הַפּוֹעֲלִים וְאֶת הָאוֹרְחִים תְּרוּמָה הֵם מְשַׁלְּמִין קֶרֶן וְחֹמֶשׁ מִפְּנֵי שֶׁהֵן כְּשׁוֹגְגִין. וְהוּא מְשַׁלֵּם לָהֶם דְּמֵי סְעֻדָּתָן שֶׁדְּמֵי הַחֻלִּין יְתֵרִין מִדְּמֵי תְּרוּמָה שֶׁאָכְלוּ שֶׁדָּבָר הָאָסוּר נַפְשׁוֹ שֶׁל אָדָם חוֹתָה מִמֶּנּוּ:","הַמַּאֲכִיל אֶת בָּנָיו הַקְּטַנִּים וְאֶת עֲבָדָיו בֵּין גְּדוֹלִים בֵּין קְטַנִּים. וְהָאוֹכֵל תְּרוּמַת חוּצָה לָאָרֶץ. וְהָאוֹכֵל אוֹ הַשּׁוֹתֶה פָּחוֹת מִכְּזַיִת. וְנָזִיר שֶׁשָּׁגַג וְשָׁתָה יַיִן שֶׁל תְּרוּמָה. וְהַשּׁוֹתֶה שֶׁמֶן וְהַסָּךְ אֶת הַיַּיִן. כָּל אֵלּוּ מְשַׁלְּמִים אֶת הַקֶּרֶן וְלֹא אֶת הַחֹמֶשׁ:","בַּת כֹּהֵן שֶׁהָיְתָה נְשׂוּאָה לְיִשְׂרָאֵל אוֹ שֶׁנִּפְסְלָה וְאַחַר כָּךְ אָכְלָה תְּרוּמָה מְשַׁלֶּמֶת אֶת הַקֶּרֶן וְלֹא אֶת הַחֹמֶשׁ. הָאִשָּׁה שֶׁהָיְתָה אוֹכֶלֶת בִּתְרוּמָה וְאָמְרוּ לָהּ מֵת בַּעְלִיךְ אוֹ גֵּרְשֵׁךְ. וְכֵן הָעֶבֶד שֶׁהָיָה אוֹכֵל וְאָמְרוּ לוֹ מֵת רַבְּךָ וְהִנִּיחַ יוֹרֵשׁ שֶׁאֵינוֹ מַאֲכִיל אוֹ שֶׁמְּכָרְךָ לְיִשְׂרָאֵל אוֹ נְתָנְךָ לוֹ אוֹ שִׁחְרֶרְךָ. וְכֵן כֹּהֵן שֶׁהָיָה אוֹכֵל וְנוֹדַע לוֹ שֶׁהוּא בֶּן גְּרוּשָׁה אוֹ בֶּן חֲלוּצָה. הֲרֵי אֵלּוּ מְשַׁלְּמִין הַקֶּרֶן בִּלְבַד. וְאִם הָיְתָה תְּרוּמַת חָמֵץ וְהָיָה עֶרֶב הַפֶּסַח הֲרֵי אֵלּוּ פְּטוּרִין מִלְּשַׁלֵּם מִפְּנֵי שֶׁזְּמַנָּהּ בָּהוּל נֶחְפְּזוּ לֶאֱכל וְלֹא בָּדְקוּ. וְכֻלָּן שֶׁהָיְתָה לָהֶן תְּרוּמָה בְּתוֹךְ פִּיהֶן כְּשֶׁיָּדְעוּ שֶׁהֵן אֲסוּרִין לֶאֱכל הֲרֵי אֵלּוּ יִפְלֹטוּ:","הָיָה אוֹכֵל וְאָמְרוּ לוֹ נִטְמֵאתָ. אוֹ נִטְמֵאת הַתְּרוּמָה. טָמֵא הָיִיתָ. אוֹ טְמֵאָה הָיְתָה הַתְּרוּמָה. אוֹ נוֹדַע שֶׁהוּא טֶבֶל אוֹ מַעֲשֵׂר רִאשׁוֹן שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ. אוֹ מַעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁלֹּא נִפְדּוּ. אוֹ שֶׁטָּעַם טַעַם פִּשְׁפֵּשׁ לְתוֹךְ פִּיו. הֲרֵי אֵלּוּ יִפְלֹטוּ:","שְׁתֵּי קֻפּוֹת אַחַת שֶׁל תְּרוּמָה וְאַחַת שֶׁל חֻלִּין וְנָפְלָה תְּרוּמָה לְתוֹךְ אַחַת מֵהֶן וְאֵין יָדוּעַ לְאֵי זוֹ נָפְלָה הֲרֵינִי אוֹמֵר לְתוֹךְ שֶׁל תְּרוּמָה נָפְלָה. אֵין יָדוּעַ אֵי זוֹ הִיא שֶׁל תְּרוּמָה אָכַל זָר אַחַת מֵהֶן הֲרֵי זֶה פָּטוּר מִן הַתַּשְׁלוּמִין שֶׁהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. וְהַשְּׁנִיָּה נוֹהֵג בָּהּ כִּתְרוּמָה. אָכַל אַחֵר אֶת הַשְּׁנִיָּה אַף הוּא פָּטוּר. אָכַל אֶחָד אֶת שְׁתֵּיהֶן מְשַׁלֵּם כַּקְּטַנָּה שֶׁבִּשְׁתֵּיהֶן. אִם מֵזִיד קֶרֶן. וְאִם שׁוֹגֵג קֶרֶן וְחֹמֶשׁ:","הָאוֹכֵל אֶת הַחֹמֶשׁ בִּשְׁגָגָה הֲרֵי זֶה מוֹסִיף עָלָיו חֻמְשׁוֹ. שֶׁהַחֹמֶשׁ כְּקֶרֶן לְכָל דָּבָר. וְכֵן מוֹסִיף חֹמֶשׁ עַל חֹמֶשׁ לְעוֹלָם. כָּל הַמְשַׁלֵּם קֶרֶן וְחֹמֶשׁ הֲרֵי הַתַּשְׁלוּמִין כִּתְרוּמָה לְכָל דָּבָר. אֶלָּא שֶׁאִם נִזְרְעוּ גִּדּוּלֵיהֶן חֻלִּין. וְאִם רָצָה הַכֹּהֵן לִמְחל אֵינוֹ מוֹחֵל. וְכָל הַמְשַׁלֵּם אֶת הַקֶּרֶן בִּלְבַד הֲרֵי הַתַּשְׁלוּמִין חֻלִּין וְאִם רָצָה הַכֹּהֵן לִמְחל מוֹחֵל:","בַּת יִשְׂרָאֵל שֶׁאָכְלָה תְּרוּמָה וְאַחַר כָּךְ נִשֵּׂאת לְכֹהֵן. אִם תְּרוּמָה שֶׁלֹּא זָכָה בָּהּ כֹּהֵן אָכְלָה מְשַׁלֶּמֶת קֶרֶן וְחֹמֶשׁ לְעַצְמָהּ. וְאִם תְּרוּמָה שֶׁזָּכָה בָּהּ כֹּהֵן אָכְלָה מְשַׁלֶּמֶת קֶרֶן לַבְּעָלִים וְחֹמֶשׁ לְעַצְמָהּ. שֶׁכָּל הַמְשַׁלֵּם קֶרֶן וְחֹמֶשׁ מְשַׁלֵּם הַקֶּרֶן לַבְּעָלִים וְהַחֹמֶשׁ לְכָל כֹּהֵן שֶׁיִּרְצֶה:","לֹא הִסְפִּיקָה לְשַׁלֵּם עַד שֶׁנִּתְגָּרְשָׁה בֵּין כָּךְ וּבֵין כָּךְ אֵינָהּ מְשַׁלֶּמֶת לְעַצְמָהּ וַהֲרֵי הִיא כְּמִי שֶׁלֹּא נִשֵּׂאת לְכֹהֵן מֵעוֹלָם:","כָּל הָאוֹכֵל תְּרוּמָה בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד אֵינוֹ מְשַׁלֵּם אֶלָּא מִן הַחֻלִּין הַמְתֻקָּנִים שֶׁהוֹצִיאוּ מֵהֶן תְּרוּמוֹת וּמַעַשְׂרוֹת. וּמְשַׁלְּמִין מִן הַלֶּקֶט וּמִן הַשִּׁכְחָה וּמִן הַפֵּאָה וּמִן הַהֶפְקֵר וּמִמַּעֲשֵׂר רִאשׁוֹן שֶׁנִּטְּלָה תְּרוּמָתוֹ אַף עַל פִּי שֶׁעֲדַיִן לֹא נִטְּלָה תְּרוּמָה גְּדוֹלָה שֶׁיֵּשׁ בּוֹ אִם הִקְדִּים הַמַּעֲשֵׂר לַתְּרוּמָה. וּמְשַׁלְּמִין מִמַּעֲשֵׂר שֵׁנִי וְהֶקְדֵּשׁ שֶׁנִּפְדּוּ וְאַף עַל פִּי שֶׁנִּפְדּוּ שֶׁלֹּא כַּהֲלָכָה. וּמִן הֶחָדָשׁ עַל הַיָּשָׁן אֲבָל לֹא מִמִּין עַל שֶׁאֵינוֹ מִינוֹ שֶׁנֶּאֱמַר (ויקרא כב יד) \"וְנָתַן לַכֹּהֵן אֶת הַקֹּדֶשׁ\". כַּקֹּדֶשׁ שֶׁאָכַל:","הָאוֹכֵל קִשּׁוּאִין שֶׁל עֶרֶב שְׁבִיעִית יַמְתִּין לַקִּשּׁוּאִין שֶׁל מוֹצָאֵי שְׁבִיעִית וִישַׁלֵּם מֵהֶן. שֶׁאֵינוֹ יָכוֹל לְשַׁלֵּם חוֹבוֹ מִפֵּרוֹת שְׁבִיעִית כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","אָכַל תְּרוּמָה טְמֵאָה מְשַׁלֵּם חֻלִּין בֵּין טְמֵאִין בֵּין טְהוֹרִין. אָכַל תְּרוּמָה טְהוֹרָה מְשַׁלֵּם חֻלִּין טְהוֹרִין וְאִם שִׁלֵּם חֻלִּין טְמֵאִין בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד תַּשְׁלוּמָיו תַּשְׁלוּמִין וְיַחֲזֹר וִישַׁלֵּם מִן הַטְּהוֹרִין:","אָכַל תְּרוּמַת חָבֵר מְשַׁלֵּם לוֹ. אָכַל תְּרוּמַת עַם הָאָרֶץ מְשַׁלֵּם לֶחָבֵר וְנוֹטֵל דָּמֶיהָ מִמֶּנּוּ וְנוֹתֵן לְעַם הָאָרֶץ שֶׁאָכַל תְּרוּמָתוֹ שֶׁאֵין מוֹסְרִין טָהֳרוֹת לְעַם הָאָרֶץ:","גָּזַל תְּרוּמָה מֵאֲבִי אִמּוֹ כֹּהֵן וַאֲכָלָהּ וְאַחַר כָּךְ מֵת אֲבִי אִמּוֹ אֵינוֹ מְשַׁלֵּם לְעַצְמוֹ אֶלָּא לְיוֹרֵשׁ אַחֵר מִשְּׁאָר הַשֵּׁבֶט. וְכֵן אִם נָפְלָה לוֹ תְּרוּמָה מֵאֲבִי אִמּוֹ וַאֲכָלָהּ. וּבַעַל חוֹב שֶׁגָּבָה תְּרוּמָה בְּחוֹבוֹ וְהָאִשָּׁה בִּכְתֻבָּתָהּ וַאֲכָלוּהָ מְשַׁלְּמִין קֶרֶן וְחֹמֶשׁ לְכֹהֵן חָבֵר וְהֶחָבֵר נוֹתֵן לָהֶם דָּמִים שֶׁהָיוּ מוֹכְרִין בָּהּ אוֹתָהּ הַתְּרוּמָה כְּמוֹ שֶׁאָכְלוּ:","הַגּוֹנֵב תְּרוּמָה וְלֹא אֲכָלָהּ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל לַבְּעָלִים. וְיֵשׁ לוֹ לְשַׁלֵּם מִדְּמֵי תְּרוּמָה. גְּנָבָהּ וַאֲכָלָהּ מְשַׁלֵּם שְׁנֵי קְרָנִין וְחֹמֶשׁ. קֶרֶן וְחֹמֶשׁ מִן הַחֻלִּין. וְקֶרֶן אֲפִלּוּ מִדְּמֵי תְּרוּמָה:","הָיְתָה הַתְּרוּמָה הֶקְדֵּשׁ לְבֶדֶק הַבַּיִת וּגְנָבָהּ וַאֲכָלָהּ אֵינוֹ מְשַׁלֵּם תַּשְׁלוּמֵי כֶּפֶל. שֶׁאֵין תַּשְׁלוּמֵי כֶּפֶל בְּהֶקְדֵּשׁ כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. אֲבָל מְשַׁלֵּם קֶרֶן וּשְׁנֵי חֳמָשִׁים. חֹמֶשׁ מִשּׁוּם אוֹכֵל תְּרוּמָה. וְחֹמֶשׁ מִשּׁוּם שֶׁנֶּהֱנָה מִן הַהֶקְדֵּשׁ. וּלְמִי מְשַׁלֵּם. אִם הָיָה בָּהּ כְּזַיִת וְאֵין בָּהּ שְׁוֵה פְּרוּטָה מְשַׁלֵּם לַכֹּהֲנִים. וְאִם יֵשׁ בָּהּ שְׁוֵה פְּרוּטָה בֵּין שֶׁיֵּשׁ בָּהּ כְּזַיִת בֵּין שֶׁאֵין בָּהּ כְּזַיִת מְשַׁלֵּם לַהֶקְדֵּשׁ:","וּמִפְּנֵי מָה חָל אִסּוּר הֶקְדֵּשׁ עַל אִסּוּר הַתְּרוּמָה מִפְּנֵי שֶׁהַתְּרוּמָה אֲסוּרָה לְזָר וּמֻתֶּרֶת לַכֹּהֵן. הִקְדִּישָׁהּ נֶאֶסְרָה עַל הַכֹּהֵן. לְפִיכָךְ נוֹסָף בָּהּ אִסּוּר אַף עַל יִשְׂרָאֵל עַל דֶּרֶךְ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בִּיאוֹת אֲסוּרוֹת וְאִסּוּרֵי מַאֲכָלוֹת:","הַגּוֹזֵל תְּרוּמָה וַאֲכָלָהּ מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ אֶחָד. שֶׁהַחֹמֶשׁ שֶׁחַיָּב בּוֹ מִשּׁוּם תְּרוּמָה יָצָא בּוֹ יְדֵי גְּזֵלוֹ שֶׁנֶּאֱמַר (ויקרא כב יד) \"וְנָתַן לַכֹּהֵן אֶת הַקֹּדֶשׁ\" אֵינוֹ חַיָּב אֶלָּא בְּחֹמֶשׁ שֶׁל קֹדֶשׁ בִּלְבַד. גְּזָלָהּ וְהֶאֱכִילָהּ לְאַחֵר. הָאוֹכֵל מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ. כָּל מָקוֹם שֶׁאָמַרְנוּ מְשַׁלֵּם קֶרֶן וְחֹמֶשׁ אִם אָכַל שְׁוֵה אַרְבָּעָה מְשַׁלֵּם שְׁוֵה חֲמִשָּׁה מִמִּין שֶׁאָכַל. וְכָל מָקוֹם שֶׁאָמַרְנוּ מְשַׁלֵּם קֶרֶן וּשְׁנֵי חֳמָשִׁין אָכַל שְׁוֵה אַרְבָּעָה מְשַׁלֵּם שִׁשָּׁה. וְכָל מָקוֹם שֶׁאָמַרְנוּ מְשַׁלֵּם שְׁנֵי קְרָנִין וְחֹמֶשׁ אֶחָד אָכַל שְׁוֵה אַרְבָּעָה מְשַׁלֵּם דְּמֵי תִּשְׁעָה. וּלְעוֹלָם אֵינוֹ מְשַׁלֵּם אֶלָּא לְפִי דָּמִים שֶׁהָיְתָה שָׁוָה בִּשְׁעַת אֲכִילָה בֵּין שֶׁהוּזְלָה בִּשְׁעַת תַּשְׁלוּמִין בֵּין שֶׁהוּקְרָה:"],"Mishneh Torah, Heave Offerings 8":["הָעֻבָּר וְהַיָּבָם וְהָאֵרוּסִין וְהַחֵרֵשׁ וּבֶן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד פּוֹסְלִין וְלֹא מַאֲכִילִין:","הָעֻבָּר כֵּיצַד. בַּת יִשְׂרָאֵל הַמְעֻבֶּרֶת מִכֹּהֵן לֹא תֹּאכַל בִּשְׁבִיל הָעֻבָּר. וּבַת כֹּהֵן הַמְעֻבֶּרֶת מִיִּשְׂרָאֵל אֲסוּרָה לֶאֱכל מִפְּנֵי הָעֻבָּר. שֶׁנֶּאֱמַר (ויקרא כב יג) \"וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ\" פְּרָט לִמְעֻבֶּרֶת:","בַּת כֹּהֵן שֶׁבָּא עָלֶיהָ יִשְׂרָאֵל אֵין חוֹשְׁשִׁין שֶׁמָּא נִתְעַבְּרָה אֶלָּא טוֹבֶלֶת וְאוֹכֶלֶת לָעֶרֶב. הָיְתָה נְשׂוּאָה לְיִשְׂרָאֵל וּמֵת בַּעְלָהּ טוֹבֶלֶת וְאוֹכֶלֶת בִּתְרוּמָה לָעֶרֶב עַד אַרְבָּעִים יוֹם. וְאִם הֻכַּר עֻבָּרָהּ הֲרֵי זוֹ מְקֻלְקֶלֶת לְמַפְרֵעַ עַד אַרְבָּעִים יוֹם. שֶׁכָּל הָאַרְבָּעִים יוֹם אֵינוֹ עֻבָּר אֶלָּא מַיִם בָּעוֹלָם הוּא חָשׁוּב:","בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן וּמֵת וְהִנִּיחָהּ מְעֻבֶּרֶת לֹא יֹאכְלוּ עֲבָדֶיהָ בִּתְרוּמָה בִּשְׁבִיל הָעֻבָּר. שֶׁהַיְלוּד הוּא שֶׁמַּאֲכִיל שֶׁאֵינוֹ יְלוּד אֵינוֹ מַאֲכִיל. לְפִיכָךְ אִם הָיָה הָעֻבָּר חָלָל אֵינוֹ פּוֹסֵל הָעֲבָדִים אֶלָּא אוֹכְלִין בִּגְלַל אֶחָיו הַכְּשֵׁרִים עַד שֶׁיִּוָּלֵד זֶה הֶחָלָל וְיֵאָסְרוּ הָעֲבָדִים מִלֶּאֱכֹל:","הַיָּבָם כֵּיצַד. בַּת יִשְׂרָאֵל הַזְּקוּקָה לְיָבָם כֹּהֵן לֹא תֹּאכַל שֶׁנֶּאֱמַר (ויקרא כב יא) \"וְכֹהֵן כִּי יִקְנֶה נֶפֶשׁ\" וְזֶה עֲדַיִן לֹא קְנָאָהּ. וּבַת כֹּהֵן הַזְּקוּקָה לְיִשְׂרָאֵל אֲסוּרָה מִפְּנֵי יְבָמָהּ שֶׁנֶּאֱמַר (ויקרא כב יג) \"וְשָׁבָה אֶל בֵּית אָבִיהָ כִּנְעוּרֶיהָ\" פְּרָט לְשׁוֹמֶרֶת יָבָם:","יָבָם כֹּהֵן שֶׁבָּא עַל יְבִמְתּוֹ בְּאֹנֶס אוֹ בִּשְׁגָגָה אוֹ שֶׁהֶעֱרָה בָּהּ וְלֹא גָּמַר אַף עַל פִּי שֶׁקְּנָאָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת יִבּוּם אֵינוֹ מַאֲכִילָהּ בִּתְרוּמָה עַד שֶׁיִּבְעל בְּעִילָה גְּמוּרָה בְּרָצוֹן. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁנִּתְאַלְמְנָה מִן הָאֵרוּסִין. אֲבָל מִן הַנִּשּׂוּאִין הוֹאִיל וְהָיְתָה אוֹכֶלֶת תֹּאכַל בְּבִיאָה זוֹ:","הָאֵרוּסִין כֵּיצַד. בַּת כֹּהֵן שֶׁנִּתְאָרְסָה לְיִשְׂרָאֵל אֲסוּרָה לֶאֱכל שֶׁהֲרֵי יֵשׁ לוֹ בָּהּ קִנְיָן. וּבַת יִשְׂרָאֵל שֶׁנִּתְאָרְסָה לְכֹהֵן לֹא תֹּאכַל עַד שֶׁתִּכָּנֵס לַחֻפָּה שֶׁמָּא תַּאֲכִיל לִבְנֵי בֵּית אָבִיהָ כְּמוֹ שֶׁבֵּאַרְנוּ:","יִשְׂרָאֵל שֶׁאָמַר לְכֹהֶנֶת הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי אַחַר שְׁלֹשִׁים יוֹם הֲרֵי זוֹ אוֹכֶלֶת בִּתְרוּמָה כָּל הַשְּׁלֹשִׁים שֶׁעֲדַיִן לֹא נִתְאָרְסָה. וְאִם אָמַר לָהּ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי מֵעַכְשָׁו וּלְאַחַר שְׁלֹשִׁים יוֹם הֲרֵי זוֹ אֲסוּרָה לֶאֱכל מִיָּד וְכֵן שְׁאָר הַתְּנָאִים כַּיּוֹצֵא בָּזֶה:","הַחֵרֵשׁ כֵּיצַד. כֹּהֶנֶת שֶׁנִּשֵּׂאת לְיִשְׂרָאֵל חֵרֵשׁ לֹא תֹּאכַל שֶׁהֲרֵי קוֹנֶה בְּתַקָּנַת חֲכָמִים שֶׁתִּקְּנוּ לוֹ נִשּׂוּאִין. וּבַת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן חֵרֵשׁ לֹא תֹּאכַל שֶׁאֵינוֹ קוֹנֶה מִן הַתּוֹרָה שֶׁאֵינוֹ בֶּן דַּעַת:","נִתְאָרְסָה לְכֹהֵן פִּקֵּחַ וְלֹא הִסְפִּיק לְכָנְסָהּ עַד שֶׁנִּתְחָרֵשׁ אֵינָהּ אוֹכֶלֶת. מֵת וְנָפְלָה לִפְנֵי יָבָם חֵרֵשׁ וְיִבְּמָהּ אֵינָהּ אוֹכֶלֶת. אֲבָל אִם נְשָׂאָהּ כְּשֶׁהוּא פִּקֵּחַ וְנִתְחָרֵשׁ הֲרֵי זוֹ אוֹכֶלֶת. מֵת וְנָפְלָה לִפְנֵי יָבָם חֵרֵשׁ וְיִבְּמָהּ הֲרֵי זוֹ אוֹכֶלֶת הוֹאִיל וְהָיְתָה אוֹכֶלֶת בַּתְּחִלָּה. וְאֵשֶׁת חֵרֵשׁ שֶׁיָּלְדָה מִמֶּנּוּ הֲרֵי זוֹ אוֹכֶלֶת בִּשְׁבִיל בְּנָהּ:","בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד כֵּיצַד. מִי שֶׁנִּבְעֲלָה לְאָסוּר לָהּ וְהוּא בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד הוֹאִיל וּבִיאָתוֹ בִּיאָה נִפְסְלָה מִן הַכְּהֻנָּה וַאֲסוּרָה מִלֶּאֱכל בִּתְרוּמָה מִפְּנֵי שֶׁנַּעֲשֵׂית זוֹנָה אוֹ חֲלָלָה כְּמוֹ שֶׁבֵּאַרְנוּ. אֲפִלּוּ הָיָה שָׁחוּף. וּבַת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד אַף עַל פִּי שֶׁבִּיאָתוֹ בִּיאָה אֵינָהּ אוֹכֶלֶת בִּשְׁבִיל הַקָּטָן לְפִי שֶׁאֵינוֹ קוֹנֶה עַד שֶׁיַּגְדִּיל. סָפֵק שֶׁהוּא בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד סָפֵק שֶׁאֵינוֹ. נִשֵּׂאת לְבֶן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד סָפֵק שֶׁהֵבִיא שְׁתֵּי שְׂעָרוֹת סָפֵק שֶׁלֹּא הֵבִיא. הֲרֵי זוֹ אֲסוּרָה לֶאֱכל:","כָּל אֵלּוּ כְּשֵׁם שֶׁאֵין מַאֲכִילִין בִּתְרוּמָה שֶׁל תּוֹרָה כָּךְ אֵין מַאֲכִילִין בִּתְרוּמָה שֶׁל דִּבְרֵיהֶם גְּזֵרָה שֶׁמָּא יַאֲכִילוּ בְּשֶׁל תּוֹרָה:","וְאֵלּוּ לֹא פּוֹסְלִין וְלֹא מַאֲכִילִין. הָאוֹנֵס. וְהַמְפַתֶּה. וְהַשּׁוֹטֶה שֶׁנָּשָׂא אִשָּׁה. אֶלָּא אִם כֵּן הָיְתָה אֲסוּרָה לָהֶן שֶׁהֵן פּוֹסְלִין אוֹתָהּ בְּבִיאָתָם מִפְּנֵי שֶׁנַּעֲשֵׂית זוֹנָה וַחֲלָלָה כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁנִּשֵּׂאת לְכֹהֵן שׁוֹטֶה אוֹ שֶׁאָנַס אוֹתָהּ אוֹ שֶׁפִּתָּה אוֹתָהּ כֹּהֵן וְיָלְדָה אוֹכֶלֶת בִּשְׁבִיל בְּנָהּ. וְאַף עַל פִּי שֶׁהַדָּבָר סָפֵק הוֹאִיל וּבְלֹא קִדּוּשִׁין הִיא שֶׁמָּא מֵאַחֵר נִתְעַבְּרָה הֲרֵי הַוָּלָד בְּחֶזְקַת זֶה שֶׁבָּא עָלֶיהָ. וְהוּא שֶׁלֹּא יָצָא עָלֶיהָ קוֹל עִם אַחֵר אֶלָּא הַכּל מְרַנְּנִין אַחֲרֶיהָ בְּזֶה הַכֹּהֵן. וְכֵן כֹּהֶנֶת שֶׁבָּא עָלֶיהָ יִשְׂרָאֵל שׁוֹטֶה אוֹ שֶׁאֲנָסָהּ אוֹ פִּתָּה אוֹתָהּ וְנִתְעַבְּרָה אֵינָהּ אוֹכֶלֶת מִפְּנֵי הָעֻבָּר. נִתְחַתֵּךְ הָעֻבָּר הֲרֵי זוֹ תֹּאכַל:","אֵשֶׁת אִישׁ שֶׁבָּאוּ עָלֶיהָ עֵדֵי קִנּוּי וְעֵדֵי סְתִירָה הֲרֵי זוֹ אֲסוּרָה לֶאֱכל בִּתְרוּמָה עַד שֶׁתִּשְׁתֶּה מֵי הַמָּרִים מִפְּנֵי שֶׁהִיא סְפֵק זוֹנָה. מֵת בַּעְלָהּ קֹדֶם שֶׁיַּשְׁקֶנָּה. אוֹ שֶׁהָיְתָה מִן הַנָּשִׁים שֶׁאֵינָן שׁוֹתוֹת וְלֹא נוֹטְלוֹת כְּתֻבָּה. הֲרֵי זוֹ אֲסוּרָה לֶאֱכל בִּתְרוּמָה לְעוֹלָם. וְכָל אֵשֶׁת כֹּהֵן שֶׁאָמְרָה טְמֵאָה אֲנִי הֲרֵי זוֹ אֲסוּרָה לֶאֱכל בִּתְרוּמָה:","קְטַנָּה בַּת יִשְׂרָאֵל שֶׁנִּשֵּׂאת לְכֹהֵן שֶׁלֹּא מִדַּעַת אָבִיהָ בֵּין בִּפְנֵי אָבִיהָ בֵּין שֶׁלֹּא בְּפָנָיו אַף עַל פִּי שֶׁקִּדְּשָׁהּ אָבִיהָ אֵינָהּ אוֹכֶלֶת בִּתְרוּמָה. שֶׁאִם מִחָה תֵּעָשֶׂה זָרָה לְמַפְרֵעַ. וְזֶה שֶׁרוֹאֶה וְשׁוֹתֵק כּוֹעֵס הוּא לְפִי שֶׁנִּשֵּׂאת שֶׁלֹּא לְדַעְתּוֹ:"],"Mishneh Torah, Hiring 7":["כְּשֵׁם שֶׁמַּתְנֶה אָדָם כָּל תְּנַאי שֶׁיִּרְצֶה בְּמִקָּח וּמִמְכָּר כָּךְ מַתְנֶה בִּשְׂכִירוּת שֶׁהַשְּׂכִירוּת מְכִירָה לִזְמַן קָצוּב הִיא וְכָל שֶׁמִּמְכָּרוֹ בִּנְכָסָיו מִמְכָּר שׂוֹכֵר שְׂכִירוּתוֹ שְׂכִירוּת. וְכָל שֶׁאֵין לוֹ לִמְכֹּר כָּךְ אֵין לוֹ לִשְׂכֹּר אֶלָּא אִם כֵּן יֵשׁ לוֹ פֵּרוֹת בִּלְבַד בְּאוֹתָהּ הַקַּרְקַע הֲרֵי זֶה שׂוֹכֵר וְאֵינוֹ מוֹכֵר:","הַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ לְשָׁנָה וְנִתְעַבְּרָה הַשָּׁנָה נִתְעַבְּרָה לַשּׂוֹכֵר. הִשְׂכִּיר לֶחֳדָשִׁים נִתְעַבְּרָה לַמַּשְׂכִּיר. הִזְכִּיר לוֹ חֳדָשִׁים וְשָׁנָה בֵּין שֶׁאָמַר לוֹ דִּינָר לְחֹדֶשׁ שְׁנֵים עָשָׂר דִּינָר בְּשָׁנָה. בֵּין שֶׁאָמַר לוֹ שְׁנֵים עָשָׂר דִּינָר לְשָׁנָה דִּינָר בְּכָל חֹדֶשׁ. הֲרֵי חֹדֶשׁ הָעִבּוּר שֶׁל מַשְׂכִּיר שֶׁהַקַּרְקַע בְּחֶזְקַת בְּעָלִים וְאֵין מוֹצִיאִין דָּבָר מִיַּד בַּעַל הַקַּרְקַע אֶלָּא בִּרְאָיָה בְּרוּרָה. וְכֵן בַּעַל הַבַּיִת שֶׁאָמַר לִזְמַן זֶה הִשְׂכַּרְתִּי לְךָ וְהַשּׂוֹכֵר אוֹמֵר לֹא שָׂכַרְתִּי אֶלָּא סְתָם אוֹ לִזְמַן אָרֹךְ עַל הַשּׂוֹכֵר לְהָבִיא רְאָיָה וְאִם לֹא הֵבִיא בַּעַל הַבַּיִת נִשְׁבָּע הֶסֵּת וּמוֹצִיאוֹ מִן הַבַּיִת:","הַשּׂוֹכֵר שֶׁאָמַר נָתַתִּי שְׂכַר הַבַּיִת שֶׁנִּתְחַיַּבְתִּי בּוֹ וְהַמַּשְׂכִּיר אוֹמֵר עֲדַיִן לֹא נָטַלְתִּי בֵּין שֶׁהָיְתָה בִּשְׁטָר בֵּין שֶׁהָיְתָה בְּעֵדִים. אִם תְּבָעוֹ בְּתוֹךְ שְׁלֹשִׁים יוֹם עַל הַשּׂוֹכֵר לְהָבִיא רְאָיָה אוֹ יִתֵּן וְיַחֲרִים עַל מִי שֶׁלָּקַח מִמֶּנּוּ אוֹ יִטְעֹן עָלָיו בְּדָמִים שֶׁנָּתַן תְּחִלָּה טַעֲנָה בִּפְנֵי עַצְמָהּ וְיַשְׁבִּיעֵהוּ הֶסֵּת. תְּבָעוֹ הַמַּשְׂכִּיר לְאַחַר שְׁלֹשִׁים יוֹם וַאֲפִלּוּ בַּיּוֹם הַשְּׁלֹשִׁים עַל הַמַּשְׂכִּיר לְהָבִיא רְאָיָה אוֹ יִשָּׁבַע הַשּׂוֹכֵר שֶׁכְּבָר נָתַן לוֹ שְׂכָרוֹ וְיִפָּטֵר. וְכֵן אִם שָׂכַר מִמֶּנּוּ וּפֵרֵשׁ שֶׁיִּתֵּן לוֹ הַשָּׂכָר שָׁנָה בְּשָׁנָה וּתְבָעוֹ בְּתוֹךְ הַשָּׁנָה עַל הַשּׂוֹכֵר לְהָבִיא רְאָיָה. תְּבָעוֹ לְאַחַר הַשָּׁנָה וַאֲפִלּוּ בְּיוֹם תִּשְׁעָה וְעֶשְׂרִים בֶּאֱלוּל עַל הַמַּשְׂכִּיר לְהָבִיא רְאָיָה:","הַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ בִּשְׁטָר לְעֶשֶׂר שָׁנִים וְאֵין בּוֹ זְמַן הַשּׂוֹכֵר אוֹמֵר עֲדַיִן לֹא עָבַר מִזְּמַן הַשְּׁטָר אֶלָּא שָׁנָה וְהַמַּשְׂכִּיר אוֹמֵר כְּבָר עָבְרוּ וְשָׁלְמוּ שְׁנֵי הַשְּׂכִירוּת וְשָׁכַנְתָּ עֶשֶׂר שָׁנִים. עַל הַשּׂוֹכֵר לְהָבִיא רְאָיָה וְאִם לֹא הֵבִיא רְאָיָה יִשָּׁבַע הַמַּשְׂכִּיר הֶסֵּת וְיוֹצִיאוֹ:","הַשּׂוֹכֵר פַּרְדֵּס אוֹ שֶׁהָיָה מַשְׁכּוֹן בְּיָדוֹ לְעֶשֶׂר שָׁנִים וְיָבֵשׁ הַפַּרְדֵּס בְּתוֹךְ הַזְּמַן יִמָּכְרוּ עֵצָיו וְיִלָּקַח בָּהֶן קַרְקַע וְיֹאכַל פֵּרוֹתָיו עַד סוֹף זְמַן שְׂכִירוּתוֹ אוֹ זְמַן הַמַּשְׁכּוֹן. וְגוּף הָאִילָנוֹת שֶׁיָּבְשׁוּ אוֹ נִקְצְצוּ שְׁנֵיהֶן אֲסוּרִין בָּהֶן מִשּׁוּם רִבִּית הַמַּלְוֶה וְהַלּוֶֹה:","שְׁטַר הַשְּׂכִירוּת אוֹ שְׁטַר הַמַּשְׁכּוֹן שֶׁכָּתוּב בָּהּ שָׁנִים סְתָם. בַּעַל הַפֵּרוֹת אוֹמֵר שָׁלֹשׁ וּבַעַל הַקַּרְקַע אוֹמֵר שְׁתַּיִם וְקָדַם זֶה הַשּׂוֹכֵר אוֹ הַמַּלְוֶה וְאָכַל הַפֵּרוֹת הֲרֵי הַפֵּרוֹת בְּחֶזְקַת אוֹכְלֵיהֶן עַד שֶׁיָּבִיא בַּעַל הַקַּרְקַע רְאָיָה. אֲכָלָהּ הַשּׂוֹכֵר אוֹ הַמְמַשְׁכֵּן שָׁלֹשׁ שָׁנִים וְכָבַשׁ הַשְּׁטָר וְאָמַר לְחָמֵשׁ שָׁנִים יֵשׁ לִי פֵּרוֹת וּבַעַל הַקַּרְקַע אוֹמֵר שָׁלֹשׁ אָמְרוּ לוֹ הָבֵא שְׁטָרְךָ וְאָמַר אָבַד הַשּׂוֹכֵר נֶאֱמָן שֶׁאִלּוּ רָצָה אָמַר לְקוּחָה הִיא בְּיָדִי שֶׁהֲרֵי אֲכָלָהּ שָׁלֹשׁ שָׁנִים:","מִי שֶׁהִכְנִיס פֵּרוֹתָיו לְבֵית חֲבֵרוֹ שֶׁלֹּא מִדַּעְתּוֹ אוֹ שֶׁהִטְעוּהוּ עַד שֶׁהִכְנִיס פֵּרוֹתָיו וְהִנִּיחָם וְהָלַךְ יֵשׁ לְבַעַל הַבַּיִת לִמְכֹּר לוֹ מֵאוֹתָן הַפֵּרוֹת כְּדֵי לִתֵּן שְׂכַר הַפּוֹעֲלִים שֶׁמּוֹצִיאִין אוֹתָן וּמַשְׁלִיכִין אוֹתָם לַשּׁוּק. וּמִדַּת חֲסִידוּת הוּא שֶׁיּוֹדִיעַ לְבֵית דִּין וְיַשְׂכִּירוּ מִמִּקְצָת דְּמֵיהֶן מָקוֹם מִשּׁוּם הֶשֵּׁב אֲבֵדָה לַבְּעָלִים אַף עַל פִּי שֶׁלֹּא עָשָׂה כַּהֹגֶן:","הַשּׂוֹכֵר רֵחַיִם מֵחֲבֵרוֹ שֶׁיִּטְחֹן לוֹ עֶשְׂרִים סְאָה בְּכָל חֹדֶשׁ בִּשְׂכָרוֹ וְהֶעֱשִׁיר בַּעַל הָרֵחַיִם וַהֲרֵי אֵינוֹ צָרִיךְ לִטְחֹן שָׁם אִם יֵשׁ לַשּׂוֹכֵר חִטִּים שֶׁצָּרִיךְ לִטְחֹן לְעַצְמוֹ אוֹ לַאֲחֵרִים כּוֹפִין אוֹתוֹ לִתֵּן דְּמֵי טְחִינַת עֶשְׂרִים סְאָה שֶׁזּוֹ מִדַּת סְדוֹם הִיא. וְאִם אֵין לוֹ יָכוֹל לוֹמַר אֵין לִי דָּמִים וַהֲרֵינִי טוֹחֵן לְךָ כְּמוֹ שֶׁשָּׂכַרְתִּי וְאִם אֵין אַתָּה צָרִיךְ מְכֹר לַאֲחֵרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Immersion Pools 11":["כְּבָר בֵּאַרְנוּ שֶׁנְּטִילַת יָדַיִם וּטְבִילָתָן מִדִּבְרֵי סוֹפְרִים. וְיָדַיִם שֶׁצְּרִיכוֹת טְבִילָה אֵין מַטְבִּילִין אוֹתָן אֶלָּא בְּמִקְוֶה כָּשֵׁר שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה. שֶׁבְּמָקוֹם שֶׁהָאָדָם טוֹבֵל בּוֹ כֵּלִים יָדַיִם טוֹבְלִין. אֲבָל יָדַיִם שֶׁאֵין צְרִיכוֹת אֶלָּא נְטִילָה בִּלְבַד אִם הִטְבִּילָן בְּמֵי מִקְוֶה טְהוֹרִין. וְאִם הִטְבִּילָן בְּמַיִם שְׁאוּבִין בֵּין בְּכֵלִים בֵּין בְּקַרְקָעוֹת לֹא טָהֲרוּ יָדָיו עַד שֶׁיִּפְּלוּ הַמַּיִם הַשְּׁאוּבִים מִן הַכְּלִי עַל יָדָיו. שֶׁאֵין נוֹטְלִין לַיָּדַיִם אֶלָּא מִן הַכֵּלִים וּמִכֹּחַ נוֹתֵן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת בְּרָכוֹת:","כָּל הַחוֹצֵץ בִּטְבִילָה חוֹצֵץ בַּיָּדַיִם בֵּין בִּטְבִילָתָן בֵּין בִּנְטִילָתָן. וְכָל הָעוֹלֶה לְמִדַּת הַמִּקְוֶה כְּטִיט הַנֵּרוֹק עוֹלֶה לְשִׁעוּר הָרְבִיעִית שֶׁנּוֹטְלִין בָּהֶן הַיָּדָיִם. וְכָל הַנּוֹטֵל יָדָיו צָרִיךְ לְשַׁפְשֵׁף:","הַנּוֹטֵל שְׁתֵּי יָדָיו לִתְרוּמָה צָרִיךְ לַחְזֹר וְלִטּל פַּעַם שְׁנִיָּה בְּמַיִם שְׁנִיִּים כְּדֵי לְהָסִיר הַמַּיִם שֶׁעַל גַּב יָדָיו שֶׁהֲרֵי הַמַּיִם שֶׁנָּטַל בָּהֶן תְּחִלָּה וְהֵן הַנִּקְרָאִין מַיִם רִאשׁוֹנִים נִטְמְאוּ בְּיָדָיו. לְפִיכָךְ אִם נָפַל כִּכָּר שֶׁל תְּרוּמָה לְתוֹךְ הַמַּיִם שֶׁנָּטַל בָּהֶן יָדָיו תְּחִלָּה נִטְמָא וְאִם נָפַל לְתוֹךְ הַמַּיִם הַשְּׁנִיִּים לֹא נִטְמָא. וְאִם נָטַל רִאשׁוֹנִים וּשְׁנִיִּים לְמָקוֹם אֶחָד וְנָפַל שָׁם כִּכָּר שֶׁל תְּרוּמָה נִטְמָא. נָטַל אֶת הָרִאשׁוֹנִים וְנִמְצָא עַל יָדָיו דָּבָר חוֹצֵץ וֶהֱסִירוֹ וְנָטַל אֶת הַשְּׁנִיִּים הֲרֵי יָדָיו טְמֵאוֹת כְּשֶׁהָיוּ שֶׁאֵין הַמַּיִם הַשְּׁנִיִּים מְטַהֲרִין אֶלָּא הַנִּשְׁאָר מִן הַמַּיִם הָרִאשׁוֹנִים עַל גַּבֵּי יָדָיו:","הַיָּדָיִם מִתְטַמְּאוֹת וּמִתְטַהֲרוֹת עַד הַפֶּרֶק. כֵּיצַד. נָטַל אֶת הָרִאשׁוֹנִים עַד הַפֶּרֶק וְנָטַל הַמַּיִם הַשְּׁנִיִּים חוּץ לַפֶּרֶק וְחָזְרוּ מִחוּץ לַפֶּרֶק לְיָדָיו הֲרֵי יָדָיו טְהוֹרוֹת שֶׁהַמַּיִם הַשְּׁנִיִּים טְהוֹרִין הֵן. נָטַל אֶת הָרִאשׁוֹנִים וְהַשְּׁנִיִּים חוּץ לַפֶּרֶק וְחָזְרוּ לְיָדוֹ נִטְמֵאת יָדוֹ שֶׁהַמַּיִם הָרִאשׁוֹנִים שֶׁחוּץ לַפֶּרֶק נִטְמְאוּ מֵחֲמַת יָדָיו וְאֵין הַמַּיִם הַשְּׁנִיִּים מְטַהֲרִים בַּמַּיִם שֶׁחוּץ לַפֶּרֶק. וּלְפִי שֶׁחָזְרוּ הַמַּיִם שֶׁחוּץ לַפֶּרֶק לְיָדוֹ טִמְּאוּהָ:","נָטַל אֶת הָרִאשׁוֹנִים לְיָדוֹ אַחַת וְנִמְלַךְ וְנָטַל אֶת הַשְּׁנִיִּים לִשְׁתֵּי יָדָיו טְמֵאוֹת שֶׁהַשְּׁנִיִּים מִתְטַמְּאִין מֵחֲמַת הַיָּד שֶׁלֹּא נִטְּלָה בְּמַיִם רִאשׁוֹנִים וְחוֹזְרִין וּמְטַמְּאִין אֶת הַיָּד הַשְּׁנִיָּה. נָטַל אֶת הָרִאשׁוֹנִים לִשְׁתֵּי יָדָיו וְנָטַל אֶת הַשְּׁנִיִּים לְיָדוֹ אַחַת הָאַחַת טְהוֹרָה. נָטַל יָדוֹ אַחַת וְשִׁפְשְׁפָהּ בַּחֲבֶרְתָּהּ נִטְמְאוּ הַמַּיִם שֶׁעָלֶיהָ מֵחֲמַת חֲבֶרְתָּהּ שֶׁלֹּא נִטְּלָה וְחוֹזְרִין וּמְטַמְּאִין אֶת הַיָּד שֶׁנִּטְּלָה. שִׁפְשְׁפָהּ בְּרֹאשׁוֹ אוֹ בַּכֹּתֶל הֲרֵי זוֹ טְהוֹרָה:","נָטַל שְׁתֵּי יָדָיו מִשְּׁטִיפָה אַחַת הֲרֵי אֵלּוּ טְהוֹרִין וְאֵין אוֹמְרִין הֲרֵי זֶה כְּנוֹטֵל יָדוֹ אַחַת בַּמַּיִם שֶׁיָּרְדוּ מֵעַל יָדוֹ הַשְּׁנִיָּה. אֲפִלּוּ אַרְבָּעָה אוֹ חֲמִשָּׁה זֶה בְּצַד זֶה אוֹ זֶה עַל גַּב זֶה. וּבִלְבַד שֶׁיַּרְפּוּ שֶׁיָּבוֹאוּ בָּהֶן הַמַּיִם:","נָטַל מִקְצָת יָדוֹ וְחָזַר וְהוֹסִיף וְנָטַל הַנִּשְׁאָר מִן יָדוֹ הֲרֵי יָדוֹ טְמֵאָה כְּשֶׁהָיְתָה. וְאִם עֲדַיִן יֵשׁ עַל מִקְצָת שֶׁנָּטַל בַּתְּחִלָּה טוֹפֵחַ עַל מְנָת לְהַטְפִּיחַ הֲרֵי זוֹ טְהוֹרָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמַיִם רִאשׁוֹנִים. אֲבָל בִּשְׁנִיִּים נוֹטֵל מִקְצָת יָדָיו וְחוֹזֵר וּמוֹסִיף עַל מִקְצָתָן:","שִׁעוּר הַמַּיִם שֶׁנּוֹטְלִין בָּהֶן תְּחִלָּה רְבִיעִית לְכָל אָדָם וְאָדָם לִשְׁתֵּי הַיָדַיִם אֵין פָּחוֹת מִשִּׁעוּר זֶה כְּמוֹ שֶׁבֵּאַרְנוּ בִּנְטִילַת יָדַיִם לְפַת. אֲבָל מַיִם שְׁנִיִּים יֵשׁ לִשְׁנַיִם לִטּל יְדֵיהֶן מֵרְבִיעִית. וּמֵחֲצִי לוֹג נוֹתְנִין לִשְׁלֹשָׁה וּלְאַרְבָּעָה. וּמִלּוֹג נוֹתְנִין אֲפִלּוּ לְמֵאָה שֶׁאֵין הַמַּיִם הַשְּׁנִיִּים לְטַהֵר אֶלָּא לְהַעֲבִיר הַמַּיִם הָרִאשׁוֹנִים:","כְּלִי שֶׁהָיָה בּוֹ רְבִיעִית מַיִם כְּשֵׁרִים לִנְטִילַת יָדַיִם וְנָתַן לְתוֹכוֹ מְעַט מַיִם פְּסוּלִין לִנְטִילַת יָדַיִם הֲרֵי אֵלּוּ כְּשֵׁרִין. נָטַל מִן הַכְּלִי כַּשִּׁעוּר שֶׁנָּתַן וְנִשְׁאֲרָה רְבִיעִית בִּלְבַד כְּשֶׁהָיְתָה הֲרֵי זוֹ פְּסוּלָה מִפְּנֵי שֶׁהַמַּיִם הַפְּסוּלִין הִשְׁלִימוּ שִׁעוּר הָרְבִיעִית:","כָּל הַמַּיִם הַפְּסוּלִין לִנְטִילָה בְּמַיִם רִאשׁוֹנִים כָּךְ הֵן פְּסוּלִין בְּמַיִם שְׁנִיִּים. וְכָל כְּלִי שֶׁאֵין נוֹטְלִין מִמֶּנּוּ בְּמַיִם רִאשׁוֹנִים כָּךְ אֵין נוֹטְלִין מִמֶּנּוּ מַיִם שְׁנִיִּים. וּכְשֵׁם שֶׁצָּרִיךְ לִהְיוֹת הַמַּיִם הָרִאשׁוֹנִים מִכֹּחַ אָדָם כָּךְ הַמַּיִם הַשְּׁנִיִּים:","כְּבָר בֵּאַרְנוּ בְּפֶרֶק שִׁשִּׁי מֵהִלְכוֹת בְּרָכוֹת כָּל מִינֵי הַמַּיִם הַפְּסוּלִין לִנְטִילַת יָדַיִם וְהֶכְשֵׁרָן. וְכָל הַכֵּלִים שֶׁנּוֹטְלִין בָּהֶן לַיָּדַיִם וְשֶׁאֵין נוֹטְלִין. וְאֵי זוֹ נְתִינָה הִיא מִכֹּחַ נוֹתֵן וּכְשֵׁרָה וְאֵי זוֹ נְתִינָה אֵינָהּ מִכֹּחַ נוֹתֵן וּפְסוּלָה. וְכָל אוֹתָן הַדְּבָרִים שֶׁבֵּאַרְנוּ שָׁם בִּנְטִילַת יָדַיִם לְפַת חֻלִּין כָּךְ הֵן לִתְרוּמָה. וּכְשֵׁם שֶׁכָּל סְפֵק יָדַיִם טְהוֹרוֹת לְחֻלִּין כְּמוֹ שֶׁבֵּאַרְנוּ שָׁם. כָּךְ הֵן לִתְרוּמָה כָּל סְפֵק יָדַיִם טָהוֹר:","דָּבָר בָּרוּר וְגָלוּי שֶׁהַטֻּמְאוֹת וְהַטָּהֳרוֹת גְּזֵרוֹת הַכָּתוּב הֵן. וְאֵינָן מִדְּבָרִים שֶׁדַּעְתּוֹ שֶׁל אָדָם מַכְרָעָתוֹ. וַהֲרֵי הֵן מִכְּלַל הַחֻקִּים. וְכֵן הַטְּבִילָה מִן הַטֻּמְאוֹת מִכְּלַל הַחֻקִּים הוּא שֶׁאֵין הַטֻּמְאָה טִיט אוֹ צוֹאָה שֶׁתַּעֲבֹר בְּמַיִם אֶלָּא גְּזֵרַת הַכָּתוּב הִיא וְהַדָּבָר תָּלוּי בְּכַוָּנַת הַלֵּב. וּלְפִיכָךְ אָמְרוּ חֲכָמִים טָבַל וְלֹא הֻחְזַק כְּאִלּוּ לֹא טָבַל. וְאַף עַל פִּי כֵן רֶמֶז יֵשׁ בַּדָּבָר כְּשֵׁם שֶׁהַמְכַוֵּן לִבּוֹ לְטַהֵר כֵּיוָן שֶׁטָּבַל טָהוֹר וְאַף עַל פִּי שֶׁלֹּא נִתְחַדֵּשׁ בְּגוּפוֹ דָּבָר כָּךְ הַמְכַוֵּן לִבּוֹ לְטַהֵר נַפְשׁוֹ מִטֻּמְאוֹת הַנְּפָשׁוֹת שֶׁהֵן מַחְשְׁבוֹת הָאָוֶן וְדֵעוֹת הָרָעוֹת. כֵּיוָן שֶׁהִסְכִּים בְּלִבּוֹ לִפְרשׁ מֵאוֹתָן הָעֵצוֹת וְהֵבִיא נַפְשׁוֹ בְּמֵי הַדַּעַת טָהוֹר. הֲרֵי הוּא אוֹמֵר (יחזקאל לו כה) \"וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם\". הַשֵּׁם בְּרַחֲמָיו הָרַבִּים מִכָּל חֵטְא עָוֹן וְאַשְׁמָה יְטַהֲרֵנוּ אָמֵן:"],"Mishneh Torah, Inheritances 2":["הַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם בְּנִכְסֵי אָבִיו שֶׁנֶּאֱמַר (דברים כא יז) \"לָתֶת לוֹ פִּי שְׁנַיִם\". כֵּיצַד. הִנִּיחַ חֲמִשָּׁה בָּנִים וְאֶחָד מֵהֶן בְּכוֹר הַבְּכוֹר נוֹטֵל שְׁלִישׁ הַמָּמוֹן וְכָל אֶחָד מֵהָאַרְבָּעָה פְּשׁוּטִים נוֹטֵל שְׁתוּת. הִנִּיחַ תִּשְׁעָה בָּנִים הֲרֵי (הָאֶחָד) הַבְּכוֹר נוֹטֵל חֲמִישִׁית וְכָל אֶחָד מִן הַשְּׁמוֹנָה פְּשׁוּטִים נוֹטֵל עֲשִׂירִית וְכֵן עַל הַחֲלוּקָה הַזֹּאת חוֹלְקִין לְעוֹלָם:","בְּכוֹר שֶׁנּוֹלַד אַחַר מִיתַת אָבִיו אֵינוֹ נוֹטֵל פִּי שְׁנַיִם. שֶׁנֶּאֱמַר (דברים כא טז) \"וְהָיָה בְּיוֹם הַנְחִילוֹ אֶת בָּנָיו\" וְגוֹ' (דברים כא יז) \"כִּי אֶת הַבְּכֹר בֶּן הַשְּׂנוּאָה יַכִּיר\". וְאִם יָצָאת פַּדַּחְתּוֹ בְּחַיֵּי אָבִיו אַף עַל פִּי שֶׁלֹּא יָצָא כָּל רֹאשׁוֹ לַאֲוִיר הָעוֹלָם אֶלָּא לְאַחַר מִיתַת אָבִיו הֲרֵי זֶה נוֹטֵל פִּי שְׁנַיִם:","בְּכוֹר שֶׁנִּקְרַע וְנִמְצָא זָכָר אֵינוֹ נוֹטֵל פִּי שְׁנַיִם וּפָשׁוּט שֶׁנִּקְרַע וְנִמְצָא זָכָר אֵינוֹ מְמַעֵט בְּחֵלֶק בְּכוֹרָהּ שֶׁנֶּאֱמַר (דברים כא טו) \"וְיָלְדוּ לוֹ בָנִים\" עַד שֶׁיִּהְיֶה בֵּן מִשְּׁעַת לֵדָה:","כֵּיצַד אֵינוֹ מְמַעֵט בְּחֵלֶק בְּכוֹרָה. הֲרֵי שֶׁהָיָה לוֹ בֵּן בְּכוֹר וּשְׁנֵי פְּשׁוּטִים וְזֶה הַטֻּמְטוּם שֶׁנִּקְרַע וְנִמְצָא זָכָר. הַבְּכוֹר נוֹטֵל רְבִיעַ הַמָּמוֹן בְּחֵלֶק הַבְּכוֹרָה וּכְאִלּוּ אֵין עִמּוֹ אֶלָּא שְׁנֵי הַפְּשׁוּטִים בִּלְבַד. וַחֲצִי וּרְבִיעַ הַנִּשְׁאָר חוֹלְקִין אוֹתוֹ שְׁנֵי הַפְּשׁוּטִין עִם הַנִּקְרָע וְעִם הַבְּכוֹר בְּשָׁוֶה:","קָטָן בֶּן יוֹם אֶחָד מְמַעֵט בְּחֵלֶק בְּכוֹרָה אֲבָל לֹא הָעֻבָּר. וּבֵן שֶׁנּוֹלַד אַחַר מִיתַת אָבִיו אֵינוֹ מְמַעֵט בְּחֵלֶק בְּכוֹרָה:","בֵּן שֶׁנִּסְתַּפֵּק לָנוּ אִם הוּא בְּכוֹר אוֹ פָּשׁוּט כְּגוֹן שֶׁנִּתְעָרֵב עִם אַחֵר אֵינוֹ נוֹטֵל פִּי שְׁנַיִם. וְכֵיצַד עוֹשִׂין. אִם הֻכְּרוּ וּלְבַסּוֹף נִתְעָרְבוּ כּוֹתְבִין הַרְשָׁאָה זֶה לָזֶה וְנוֹטְלִין חֵלֶק בְּכוֹרָה עִם אֲחֵיהֶם. וְאִם לֹא הֻכְּרוּ כְּגוֹן שֶׁיְּלָדוֹ בְּמַחֲבוֹאָה אַחַת אֵין כּוֹתְבִין הַרְשָׁאָה וְאֵין כָּאן חֵלֶק בְּכוֹרָה:","מִי שֶׁהָיוּ לוֹ שְׁנֵי בָּנִים בְּכוֹר וּפָשׁוּט וּמֵתוּ שְׁנֵיהֶם בְּחַיָּיו וְהִנִּיחוּ בָּנִים. הַבְּכוֹר הֵנִיחַ בַּת וְהַפָּשׁוּט הִנִּיחַ בֵּן. הֲרֵי בֶּן הַפָּשׁוּט יוֹרֵשׁ בְּנִכְסֵי הַזָּקֵן שְׁלִישׁ שֶׁהוּא חֵלֶק אָבִיו. וּבַת הַבְּכוֹר יוֹרֶשֶׁת שְׁנֵי שְׁלִישִׁים שֶׁהוּא חֵלֶק אָבִיהָ. וְכֵן הַדִּין בִּבְנֵי הָאַחִין וּבְנֵי אֲחֵי הָאָב וּבְכָל הַיּוֹרְשִׁין אִם הָיָה אֲבִי אֶחָד מִן הַיּוֹרְשִׁים בְּכוֹר נוֹטֵל חֵלֶק בְּכוֹרָה שֶׁלּוֹ זֶה הַיּוֹרֵשׁ מֵחֲמָתוֹ:","אֵין הַבְּכוֹר נוֹטֵל פִּי שְׁנַיִם בְּנִכְסֵי הָאֵם. כֵּיצַד. בְּכוֹר וּפָשׁוּט שֶׁיָּרְשׁוּ אִמָּן חוֹלְקִין בְּשָׁוֶה בֵּין שֶׁהָיָה בְּכוֹר לְנַחֲלָה בֵּין שֶׁהָיָה פֶּטֶר רֶחֶם:","בְּכוֹר לְנַחֲלָה הוּא הַנּוֹלָד לָאָב רִאשׁוֹן שֶׁנֶּאֱמַר (דברים כא יז) \"כִּי הוּא רֵאשִׁית אֹנוֹ\". וְאֵין מַשְׁגִּיחִין עַל הָאֵם אֲפִלּוּ יָלְדָה כַּמָּה בָּנִים הוֹאִיל וְזֶה רִאשׁוֹן לְאָבִיו יוֹרֵשׁ פִּי שְׁנַיִם:","הַבָּא אַחַר נְפָלִים אַף עַל פִּי שֶׁיָּצָא רֹאשׁ הַנֵּפֶל כְּשֶׁהוּא חַי הַבָּא אַחֲרָיו בְּכוֹר לְנַחֲלָה. וְכֵן בֶּן תִּשְׁעָה שֶׁיָּצָא רֹאשׁוֹ מֵת הַבָּא אַחֲרָיו בְּכוֹר לְנַחֲלָה שֶׁזֶּה שֶׁנֶּאֱמַר (דברים כא יז) \"רֵאשִׁית אֹנוֹ\" הוּא שֶׁלֹּא נוֹלַד לוֹ קֹדֶם לָזֶה וָלָד שֶׁיָּצָא חַי לַאֲוִיר הָעוֹלָם. לְפִיכָךְ בֶּן תִּשְׁעָה שֶׁהוֹצִיא רֹב רֹאשׁוֹ חַי הַבָּא אַחֲרָיו אֵינוֹ בְּכוֹר:","יוֹצֵא דֹּפֶן וְהַבָּא אַחֲרָיו שְׁנֵיהֶן אֵינָן בְּכוֹרִים. הָרִאשׁוֹן לְפִי שֶׁלֹּא נוֹלַד וְנֶאֱמַר (דברים כא טו) \"וְיָלְדוּ לוֹ בָנִים\". וְהַשֵּׁנִי שֶׁהֲרֵי קְדָמוֹ אַחֵר:","הָיוּ לוֹ בָּנִים כְּשֶׁהָיָה עַכּוּ\"ם וְנִתְגַּיֵּר אֵין לוֹ בְּכוֹר לְנַחֲלָה. אֲבָל יִשְׂרָאֵל שֶׁהָיָה לוֹ בֵּן מִן הַשִּׁפְחָה וּמִן הָעַכּוּ\"ם הוֹאִיל וְאֵינוֹ קָרוּי בְּנוֹ הַבָּא לוֹ אַחֲרָיו מִן הַיִּשְׂרְאֵלִית בְּכוֹר לְנַחֲלָה וְנוֹטֵל פִּי שְׁנַיִם:","הָיָה הַבְּכוֹר מַמְזֵר נוֹטֵל פִּי שְׁנַיִם שֶׁנֶּאֱמַר (דברים כא יז) \"כִּי אֶת הַבְּכֹר בֶּן הַשְּׂנוּאָה יַכִּיר\" זוֹ שֶׁשְּׂנוּאָה בְּנִשּׂוּאֶיהָ. וְאֵין צָרִיךְ לוֹמַר אִם הָיָה בֶּן גְּרוּשָׁה אוֹ בֶּן חֲלוּצָה:","שְׁלֹשָׁה נֶאֱמָנִין עַל הַבְּכוֹר. חַיָּה וְאִמּוֹ וְאָבִיו. חַיָּה מִיָּד שֶׁאִם אָמְרָה זֶה יָצָא רִאשׁוֹן נֶאֱמֶנֶת. אִמּוֹ כָּל שִׁבְעַת יְמֵי הַלֵּידָה נֶאֱמֶנֶת לוֹמַר זֶהוּ הַבְּכוֹר. אָבִיו לְעוֹלָם אֲפִלּוּ אָמַר הָאָב עַל מִי שֶׁלֹּא הֻחְזַק בְּנוֹ כְּלָל הוּא בְּנִי וּבְכוֹרִי הוּא נֶאֱמָן. וְכֵן אִם אָמַר עַל הַמֻּחְזָק לָנוּ שֶׁהוּא בְּכוֹרוֹ אֵינוֹ בְּכוֹר נֶאֱמָן:","הָאָב שֶׁנִּשְׁתַּתֵּק בּוֹדְקִין אוֹתוֹ כְּדֶרֶךְ שֶׁבּוֹדְקִין לְגִטִּין. אִם רָמַז אוֹ כָּתַב שֶׁזֶּה בְּנוֹ בְּכוֹרוֹ הֲרֵי זֶה נוֹטֵל פִּי שְׁנַיִם:","הֵעִידוּ עֵדִים שֶׁהֵן שָׁמְעוּ אָבִיו שֶׁל זֶה אוֹמֵר דְּבָרִים כָּךְ וְכָךְ שֶׁהֲרֵי אוֹתָן הַדְּבָרִים יוֹדֵעַ מִכְּלָלָן שֶׁזֶּה בְּנוֹ בְּכוֹרוֹ. הֲרֵי זֶה נוֹטֵל פִּי שְׁנַיִם אַף עַל פִּי שֶׁלֹּא אָמַר הָאָב בְּפֵרוּשׁ זֶה בְּנִי בְּכוֹרִי:","שָׁמְעוּ מִן הָאָב שֶׁאָמַר זֶה בְּנִי בְּכוֹר אֵינוֹ נוֹטֵל פִּי שְׁנַיִם בְּעֵדוּת זוֹ שֶׁמָּא בְּכוֹר לְאִמּוֹ הוּא וְלָזֶה נִתְכַּוֵּן הָאָב עַד שֶׁיֹּאמַר בְּנִי בְּכוֹרִי:"],"Mishneh Torah, Kings and Wars 2":["כָּבוֹד גָּדוֹל נוֹהֲגִין בַּמֶּלֶךְ. וּמְשִׂימִין לוֹ אֵימָה וְיִרְאָה בְּלֵב כָּל אָדָם. שֶׁנֶּאֱמַר (דברים יז טו) \"שׂוֹם תָּשִׂים\" שֶׁתְּהֵא אֵימָתוֹ עָלֶיךָ. אֵין רוֹכְבִין עַל סוּסוֹ. וְאֵין יוֹשְׁבִין עַל כִּסְאוֹ. וְאֵין מִשְׁתַּמְּשִׁין בְּשַׁרְבִיטוֹ. וְלֹא בְּכִתְרוֹ. וְלֹא בְּאֶחָד מִכָּל כְּלֵי תַּשְׁמִישָׁיו. וּכְשֶׁהוּא מֵת כֻּלָּן נִשְׂרָפִין לְפָנָיו. וְכֵן לֹא יִשְׁתַּמֵּשׁ בַּעֲבָדָיו וְשִׁפְחוֹתָיו וְשַׁמָּשָׁיו אֶלָּא מֶלֶךְ אַחֵר. לְפִיכָךְ אֲבִישַׁג הָיְתָה מֻתֶּרֶת לִשְׁלֹמֹה וַאֲסוּרָה לַאֲדוֹנִיָּה:","אֲבָל אִשְׁתּוֹ שֶׁל מֶלֶךְ אֵינָהּ נִבְעֶלֶת לְאַחֵר לְעוֹלָם. אֲפִלּוּ הַמֶּלֶךְ אֵינוֹ נוֹשֵׂא אַלְמָנָתוֹ אוֹ גְּרוּשָׁתוֹ שֶׁל מֶלֶךְ אַחֵר:","וְאָסוּר לִרְאוֹתוֹ כְּשֶׁהוּא עֵרוֹם וְלֹא כְּשֶׁהוּא מִסְתַּפֵּר. וְלֹא כְּשֶׁהוּא בְּבֵית הַמֶּרְחָץ. וְלֹא כְּשֶׁהוּא מִסְתַּפֵּג. וְאֵינוֹ חוֹלֵץ שֶׁנֶּאֱמַר (דברים כה ט) \"וְיָרְקָה בְּפָנָיו\" וְזֶה בִּזָּיוֹן. וַאֲפִלּוּ רָצָה אֵין שׁוֹמְעִין לוֹ. שֶׁהַמֶּלֶךְ שֶׁמָּחַל עַל כְּבוֹדוֹ אֵין כְּבוֹדוֹ מָחוּל. וְהוֹאִיל וְאֵינוֹ חוֹלֵץ אֵינוֹ מְיַבֵּם. וְכֵן [אִם מֵת הוּא] כֵּיוָן שֶׁאִי אֶפְשָׁר לְיַבֵּם אֶת אִשְׁתּוֹ כָּךְ אֵין חוֹלְצִין לָהּ אֶלָּא תֵּשֵׁב לְעוֹלָם בְּזִקָּתָהּ:","מֵת לוֹ מֵת אֵינוֹ יוֹצֵא מִפֶּתַח פַּלְטֵרִין שֶׁלּוֹ. וּכְשֶׁמַּבְרִין אוֹתוֹ כָּל הָעָם מְסֻבִּין עַל הָאָרֶץ וְהוּא מֵסֵב עַל הַדַּרְגָּשׁ. וְאִם נִכְנַס לָעֲזָרָה וְהָיָה מִזֶּרַע דָּוִד יֵשֵׁב. שֶׁאֵין יְשִׁיבָה בָּעֲזָרָה אֶלָּא לְמַלְכֵי בֵּית דָּוִד בִּלְבַד. שֶׁנֶּאֱמַר (שמואל ב ז יח) \"וַיָּבֹא הַמֶּלֶךְ דָּוִד וַיֵּשֶׁב לִפְנֵי ה'\":","הַמֶּלֶךְ מִסְתַּפֵּר בְּכָל יוֹם. וּמְתַקֵּן עַצְמוֹ וּמִתְנָאֶה בְּמַלְבּוּשִׁין נָאִים וּמְפֹאָרִים. שֶׁנֶּאֱמַר (ישעיה לג יז) \"מֶלֶךְ בְּיָפְיוֹ תֶּחֱזֶינָה עֵינֶיךָ\". וְיוֹשֵׁב עַל כִּסֵּא מַלְכוּתוֹ בַּפַּלְטֵרִין שֶׁלּוֹ. וּמֵשִׂים כֶּתֶר בְּרֹאשׁוֹ. וְכָל הָעָם בָּאִין אֵלָיו בְּעֵת שֶׁיִּרְצֶה. וְעוֹמְדִין לְפָנָיו וּמִשְׁתַּחֲוִים אַרְצָה. אֲפִלּוּ נָבִיא עוֹמֵד לִפְנֵי הַמֶּלֶךְ מִשְׁתַּחֲוֶה אַרְצָה. שֶׁנֶּאֱמַר (מלכים א א כג) \"הִנֵּה נָתָן הַנָּבִיא וַיָּבֹא לִפְנֵי הַמֶּלֶךְ וַיִּשְׁתַּחוּ לַמֶּלֶךְ\". אֲבָל כֹּהֵן גָּדוֹל אֵינוֹ בָּא לִפְנֵי הַמֶּלֶךְ אֶלָּא אִם רָצָה. וְאֵינוֹ עוֹמֵד לְפָנָיו אֶלָּא הַמֶּלֶךְ עוֹמֵד לִפְנֵי כֹּהֵן גָּדוֹל. שֶׁנֶּאֱמַר (במדבר כז כא) \"וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן יַעֲמֹד\". אַף עַל פִּי כֵן מִצְוָה עַל כֹּהֵן גָּדוֹל לְכַבֵּד אֶת הַמֶּלֶךְ וּלְהוֹשִׁיבוֹ וְלַעֲמֹד מִפָּנָיו כְּשֶׁיָּבוֹא לוֹ. וְלֹא יַעֲמֹד הַמֶּלֶךְ לְפָנָיו אֶלָּא כְּשֶׁיִּשְׁאַל לוֹ בְּמִשְׁפַּט הָאוּרִים. וְכֵן מִצְוָה עַל הַמֶּלֶךְ לְכַבֵּד לוֹמְדֵי הַתּוֹרָה. וּכְשֶׁיִּכָּנְסוּ לְפָנָיו סַנְהֶדְרִין וְחַכְמֵי יִשְׂרָאֵל יַעֲמֹד לִפְנֵיהֶם וְיוֹשִׁיבֵם בְּצִדּוֹ. וְכֵן הָיָה יְהוֹשָׁפָט מֶלֶךְ יְהוּדָה עוֹשֶׂה אֲפִלּוּ לְתַלְמִיד חָכָם הָיָה עוֹמֵד מִכִּסְאוֹ וּמְנַשְּׁקוֹ וְקוֹרֵא לוֹ רַבִּי וּמוֹרִי. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁיִּהְיֶה הַמֶּלֶךְ בְּבֵיתוֹ לְבַדּוֹ הוּא וַעֲבָדָיו יַעֲשֶׂה זֶה בְּצִנְעָה. אֲבָל בְּפַרְהֶסְיָא בִּפְנֵי הָעָם לֹא יַעֲשֶׂה. וְלֹא יַעֲמֹד מִפְּנֵי אָדָם. וְלֹא יְדַבֵּר רַכּוֹת. וְלֹא יִקְרָא לְאָדָם אֶלָּא בִּשְׁמוֹ כְּדֵי שֶׁתְּהֵא יִרְאָתוֹ בְּלֵב הַכּל:","כְּדֶרֶךְ שֶׁחָלַק לוֹ הַכָּתוּב הַכָּבוֹד הַגָּדוֹל. וְחִיֵּב הַכּל בִּכְבוֹדוֹ. כָּךְ צִוָּהוּ לִהְיוֹת לִבּוֹ בְּקִרְבּוֹ שָׁפָל וְחָלָל שֶׁנֶּאֱמַר (תהילים קט כב) \"וְלִבִּי חָלַל בְּקִרְבִּי\". וְלֹא יִנְהַג גַּסּוּת לֵב בְּיִשְׂרָאֵל יֶתֶר מִדַּאי שֶׁנֶּאֱמַר (דברים יז כ) \"לְבִלְתִּי רוּם לְבָבוֹ מֵאֶחָיו\". וְיִהְיֶה חוֹנֵן וּמְרַחֵם לִקְטַנִּים וּגְדוֹלִים. וְיֵצֵא וְיָבוֹא בְּחֶפְצֵיהֶם וּבְטוֹבָתָם. וְיָחוּס עַל כְּבוֹד קָטָן שֶׁבַּקְּטַנִּים. וּכְשֶׁמְּדַבֵּר אֶל כָּל הַקָּהָל בִּלְשׁוֹן רַבִּים יְדַבֵּר רַכּוֹת. שֶׁנֶּאֱמַר (דברי הימים א כח ב) \"שְׁמָעוּנִי אַחַי וְעַמִּי\". וְאוֹמֵר (מלכים א יב ז) \"אִם הַיּוֹם תִּהְיֶה עֶבֶד לָעָם הַזֶּה\" וְגוֹ'. לְעוֹלָם יִתְנַהֵג בַּעֲנָוָה יְתֵרָה. אֵין לָנוּ גָּדוֹל מִמּשֶׁה רַבֵּנוּ וְהוּא אוֹמֵר (שמות טז ח) \"וְנַחְנוּ מָה לֹא עָלֵינוּ תְלֻנֹּתֵיכֶם\". וְיִסְבּל טָרְחָם וּמַשָּׂאָם וּתְלוּנוֹתָם וְקִצְפָּם כַּאֲשֶׁר יִשָּׂא הָאוֹמֵן אֶת הַיּוֹנֵק. רוֹעֶה קְרָאוֹ הַכָּתוּב. לִרְעוֹת בְּיַעֲקֹב עַמּוֹ. וְדַרְכּוֹ שֶׁל רוֹעֶה מְפֹרָשׁ בְּקַבָּלָה כְּרֹעֶה עֶדְרוֹ יִרְעֶה בִּזְרֹעוֹ יְקַבֵּץ טְלָאִים וּבְחֵיקוֹ יִשָּׂא וְגוֹ':"],"Mishneh Torah, Leavened and Unleavened Bread 5":["אֵין אָסוּר מִשּׁוּם חָמֵץ בְּפֶסַח אֶלָּא חֲמֵשֶׁת מִינֵי דָּגָן בִּלְבַד. וְהֵם שְׁנֵי מִינֵי חִטִּים שֶׁהֵן הַחִטָּה וְהַכֻּסֶּמֶת. וּשְׁלֹשָׁה מִינֵי הַשְּׂעוֹרִים שֶׁהֵן הַשְּׂעוֹרָה וְשִׁבּלֶת שׁוּעָל וְהַשִּׁפּוֹן. אֲבָל קִטְנִיּוֹת כְּגוֹן אֹרֶז וְדֹחַן וּפוֹלִים וַעֲדָשִׁים וְכַיּוֹצֵא בָּהֶן אֵין בָּהֶן מִשּׁוּם חָמֵץ אֶלָּא אֲפִלּוּ לָשׁ קֶמַח אֹרֶז וְכַיּוֹצֵא בּוֹ בְּרוֹתְחִין וְכִסָּהוּ בִּבְגָדִים עַד שֶׁנִּתְפַּח כְּמוֹ בָּצֵק שֶׁהֶחֱמִיץ הֲרֵי זֶה מֻתָּר בַּאֲכִילָה שֶׁאֵין זֶה חִמּוּץ אֶלָּא סֵרָחוֹן:","חֲמֵשֶׁת מִינֵי דָּגָן אֵלּוּ אִם לָשָׁן בְּמֵי פֵּרוֹת בִּלְבַד בְּלֹא שׁוּם מַיִם לְעוֹלָם אֵין בָּאִין לִידֵי חִמּוּץ אֶלָּא אֲפִלּוּ הִנִּיחָן כָּל הַיּוֹם עַד שֶׁנִּתְפַּח הַבָּצֵק מֻתָּר בַּאֲכִילָה [ג.] שֶׁאֵין מֵי פֵּרוֹת מַחְמִיצִין אֶלָּא מַסְרִיחִין. וּמֵי פֵּרוֹת הֵן כְּגוֹן יַיִן וְחָלָב וּדְבַשׁ וְשֶׁמֶן זַיִת וּמֵי תַּפּוּחִים וּמֵי רִמּוֹנִים וְכָל כַּיּוֹצֵא בָּהֶן מִשְּׁאָר יֵינוֹת וּשְׁמָנִים וּמַשְׁקִין. וְהוּא שֶׁלֹּא יִתְעָרֵב בָּהֶן שׁוּם מַיִם בָּעוֹלָם. וְאִם נִתְעָרֵב בָּהֶן מַיִם כָּל שֶׁהוּא הֲרֵי אֵלּוּ מַחְמִיצִין:","אֵין מְבַשְּׁלִין חִטִּים בְּמַיִם כְּגוֹן רִיפוֹת וְלֹא קֶמַח כְּגוֹן לְבִיבוֹת. וְאִם בִּשֵּׁל הֲרֵי זֶה חָמֵץ גָּמוּר וְהוּא שֶׁיִּתְבַּקְּעוּ בַּתַּבְשִׁיל. אֵין קוֹלִין אֶת הַבָּצֵק בְּשֶׁמֶן עַל הַמַּחֲבַת. אֲבָל מְבַשְּׁלִין אֶת הַפַּת וְאֶת הַקֶּמַח הַקָּלוּי. וְאִם הִרְתִּיחַ הַמַּיִם הַרְבֵּה וְאַחַר כָּךְ הִשְׁלִיךְ לְתוֹכָן הַקֶּמַח הֲרֵי זֶה מֻתָּר מִפְּנֵי שֶׁהוּא מִתְבַּשֵּׁל מִיָּד קֹדֶם שֶׁיַּחְמִיץ. וּכְבָר נָהֲגוּ בְּשִׁנְעָר וּבִסְפָרַד וּבְכָל הַמַּעֲרָב לֶאֱסֹר דָּבָר זֶה גְּזֵרָה שֶׁמָּא לֹא יַרְתִּיחַ הַמַּיִם יָפֶה יָפֶה:","מֻתָּר לְבַשֵּׁל הַדָּגָן אוֹ הַקֶּמַח בְּמֵי פֵּרוֹת. וְכֵן בָּצֵק שֶׁלָּשׁוֹ בְּמֵי פֵּרוֹת אִם בִּשְּׁלוֹ בְּמֵי פֵּרוֹת אוֹ קָלָהוּ עַל הַמַּחֲבַת בְּשֶׁמֶן הֲרֵי זֶה מֻתָּר שֶׁמֵּי פֵּרוֹת אֵינָן מַחְמִיצִין:","כַּרְמֶל שֶׁמְּהַבְהֲבִין אוֹתוֹ בָּאוּר וְטוֹחֲנִין אוֹתוֹ אֵין מְבַשְּׁלִין אֶת הַקֶּמַח שֶׁלּוֹ בְּמַיִם שֶׁמָּא לֹא נִקְלָה בָּאוּר יָפֶה וְנִמְצָא מַחֲמִיץ כְּשֶׁמְּבַשְּׁלִין אוֹתוֹ. וְכֵן כְּשֶׁמּוֹלְלִין הַקְּדֵרוֹת הַחֲדָשׁוֹת אֵין מְבַשְּׁלִין בָּהֶן אֶלָּא מַצָּה אֲפוּיָה שֶׁחָזְרוּ וְטָחֲנוּ אוֹתָהּ אֲבָל קֶמַח קָלִי אָסוּר שֶׁמָּא לֹא קָלָהוּ יָפֶה וְיָבוֹא לִידֵי חִמּוּץ:","אֵין בּוֹלְלִין אֶת הַשְּׂעוֹרִין בְּמַיִם בְּפֶסַח מִפְּנֵי שֶׁהֵן רָפִין וּמַחְמִיצִין בִּמְהֵרָה. וְאִם בָּלַל אִם רָפוּ כְּדֵי שֶׁאִם הִנִּיחָן עַל פִּי הַבִּיב שֶׁאוֹפִין עָלָיו הַחַלּוֹת יִתְבַּקְּעוּ הֲרֵי אֵלּוּ אֲסוּרִין. וְאִם לֹא הִגִּיעוּ לְרִפְיוֹן זֶה הֲרֵי אֵלּוּ מֻתָּרִין:","הַחִטִּים מֻתָּר לִבְלל אוֹתָן בְּמַיִם כְּדֵי לְהָסִיר סֻבָּן וְטוֹחֲנִין אוֹתָן מִיָּד כְּדֶרֶךְ שֶׁטּוֹחֲנִין הַסּלֶת. וּכְבָר נָהֲגוּ כָּל יִשְׂרָאֵל בְּשִׁנְעָר וּבְאֶרֶץ הַצְּבִי וּבִסְפָרַד וּבְעָרֵי הַמַּעֲרָב שֶׁלֹּא יִבְלְלוּ הַחִטִּים בְּמַיִם גְּזֵרָה שֶׁמָּא יִשְׁהוּ וְיַחֲמִיצוּ:","תַּבְשִׁיל שֶׁנִתְבַּשֵּׁל וְנִמְצְאוּ בּוֹ שְׂעוֹרִים אוֹ חִטִּים אִם נִתְבַּקְּעוּ הֲרֵי כָּל הַתַּבְשִׁיל אָסוּר שֶׁהֲרֵי נִתְעָרֵב בּוֹ הֶחָמֵץ. וְאִם לֹא נִתְבַּקְּעוּ מוֹצִיאִין אוֹתָן וְשׂוֹרְפָן וְאוֹכְלִין שְׁאָר הַתַּבְשִׁיל. שֶׁאֵין הַדָּגָן שֶׁנִּבְלַל וְלֹא נִתְבַּקֵּעַ חָמֵץ גָּמוּר שֶׁל תּוֹרָה. וְאֵינוֹ אֶלָּא מִדִּבְרֵי סוֹפְרִים:","מִשּׁוּם שֶׁנֶּאֱמַר (שמות יב יז) \"וּשְׁמַרְתֶּם אֶת הַמַּצּוֹת\" כְּלוֹמַר הִזָּהֲרוּ בַּמַּצָּה וְשִׁמְרוּ אוֹתָהּ מִכָּל צַד חִמּוּץ. לְפִיכָךְ אָמְרוּ חֲכָמִים צָרִיךְ אָדָם לִזָּהֵר בְּדָגָן שֶׁאוֹכֵל מִמֶּנּוּ בַּפֶּסַח שֶׁלֹּא יָבוֹא עָלָיו מַיִם אַחַר שֶׁנִּקְצַר עַד שֶׁלֹּא יִהְיֶה בּוֹ שׁוּם חִמּוּץ. דָּגָן שֶׁנִּטְבַּע בַּנָּהָר אוֹ שֶׁנָּפַל עָלָיו מַיִם כְּשֵׁם שֶׁאָסוּר לְאָכְלוֹ כָּךְ אָסוּר לְקַיְּמוֹ אֶלָּא מוֹכְרוֹ לְיִשְׂרָאֵל וּמוֹדִיעוֹ כְּדֵי שֶׁיֹּאכְלֶנּוּ קֹדֶם הַפֶּסַח. וְאִם מְכָרוֹ לְנָכְרִי קֹדֶם הַפֶּסַח מוֹכֵר מְעַט לְכָל אֶחָד וְאֶחָד כְּדֵי שֶׁיִּכְלֶה קֹדֶם הַפֶּסַח שֶׁמָּא יַחֲזֹר הַנָּכְרִי וְיִמְכְּרֶנּוּ לְיִשְׂרָאֵל:","דָּגָן שֶׁנָּפַל עָלָיו דֶּלֶף כָּל זְמַן שֶׁהוּא טוֹרֵד טִפָּה אַחַר טִפָּה אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ אֵינוֹ בָּא לִידֵי חִמּוּץ. אֲבָל כְּשֶׁיִּפָּסֵק אִם נִשְׁתַּהָה כַּשִּׁעוּר הֲרֵי זֶה אָסוּר:","אֵין לָשִׁין בְּפֶסַח עִסָּה גְּדוֹלָה שֶׁמָּא תַּחֲמִיץ אֶלָּא כְּשִׁעוּר חַלָּה בִּלְבַד. וְאֵין לָשִׁין לֹא בְּחַמִּין וְלֹא בְּחַמֵּי חַמָּה. וְלֹא בְּמַיִם שֶׁנִּשְׁאֲבוּ בּוֹ בַּיּוֹם אֶלָּא בְּמַיִם שֶׁלָּנוּ. וְאִם עָבַר וְלָשׁ בְּאֶחָד מִכָּל אֵלּוּ הֲרֵי הַפַּת אֲסוּרָה:","לֹא תֵּשֵׁב אִשָּׁה תַּחַת הַשֶּׁמֶשׁ וְתָלוּשׁ. וְלֹא תַּחַת הָרָקִיעַ בְּיוֹם הֶעָבִים אֲפִלּוּ בְּמָקוֹם שֶׁאֵין הַשֶּׁמֶשׁ זוֹרַחַת בּוֹ. וְלֹא תָּנִיחַ אֶת הָעִסָּה וְתִתְעַסֵּק בְּדָבָר אַחֵר. וְאִם הָיְתָה לָשָׁה וְאוֹפָה צְרִיכָה שְׁנֵי כֵּלִים שֶׁל מַיִם. אֶחָד שֶׁמְּקַטֶּפֶת בּוֹ וְאֶחָד שֶׁמְּצַנֶּנֶת בּוֹ יָדֶיהָ. וְאִם עָבְרָה וְלָשָׁה תַּחַת הַשֶּׁמֶשׁ אוֹ שֶׁלֹּא צִנְּנָה יָדֶיהָ אוֹ שֶׁעָשְׂתָה עִסָּה יֶתֶר מִשִּׁעוּר חַלָּה הַפַּת מֻתֶּרֶת. וְכַמָּה שִׁעוּר חַלָּה כְּמוֹ שָׁלֹשׁ וְאַרְבָּעִים בֵּיצִים וְחֹמֶשׁ בֵּיצָה כְּגוּף הַבֵּיצָה הַבֵּינוֹנִית לֹא כְּמִשְׁקָלָהּ:","כָּל זְמַן שֶׁאָדָם עוֹסֵק בַּבָּצֵק אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ אֵינוֹ בָּא לִידֵי חִמּוּץ. וְאִם הִגְבִּיהַּ יָדוֹ וֶהֱנִיחוֹ וְשָׁהָה הַבָּצֵק עַד שֶׁהִגִּיעַ לְהַשְׁמִיעַ הַקּוֹל בִּזְמַן שֶׁאָדָם מַכֶּה בְּיָדוֹ עָלָיו כְּבָר הֶחְמִיץ וְיִשָּׂרֵף מִיָּד. וְאִם אֵין קוֹלוֹ נִשְׁמָע אִם שָׁהָה כְּדֵי שֶׁיְּהַלֵּךְ אָדָם מִיל כְּבָר הֶחְמִיץ וְיִשָּׂרֵף מִיָּד. וְכֵן אִם הִכְסִיפוּ פָּנָיו כְּאָדָם שֶׁעָמְדוּ שַׂעֲרוֹתָיו הֲרֵי זֶה אָסוּר לְאָכְלוֹ וְאֵין חַיָּבִין עָלָיו כָּרֵת:","הָיוּ שְׁתֵּי עִסּוֹת שֶׁהִגְבִּיהוּ הַיָּד מֵהֶן נִלּוֹשׁוֹת בְּעֵת אַחַת וְנִשְׁתַּהוּ. הָאַחַת מֵהֶן יֵשׁ לָהּ קוֹל וְהָאַחֶרֶת אֵין לָהּ קוֹל. שְׁתֵּיהֶן יִשָּׂרְפוּ וַהֲרֵי הֵן חָמֵץ גָּמוּר:","אֵין עוֹשִׂין סְרִיקִין הַמְצֻיָּרִין בְּפֶסַח מִפְּנֵי שֶׁהָאִשָּׁה שׁוֹהָה עֲלֵיהֶן וּמִתְחַמְּצִין בְּעֵת עֲשִׂיָּתָן. לְפִיכָךְ הַנַּחְתּוֹמִין מֻתָּרִין לַעֲשׂוֹתָם מִפְּנֵי שֶׁהֵן בְּקִיאִין בְּאֻמָּנוּתָן וּמְמַהֲרִים לַעֲשׂוֹתָם. אֲבָל בַּעֲלֵי בָּתִּים אֲסוּרִים וַאֲפִלּוּ צָרוּ אוֹתָן בִּדְפוּס. שֶׁמָּא יָבוֹאוּ אֲחֵרִים לַעֲשׂוֹתוֹ שֶׁלֹּא בִּדְפוּס וְיִשְׁהוּ בַּעֲשִׂיָּתָן וְיַחֲמִיצוּ:","מַיִם שֶׁרוֹחֲצִין בָּהֶן הַיָּדַיִם וְהָעֲרֵבָה אַחַר שֶׁלָּשִׁין וְכֵן מַיִם שֶׁמִּשְׁתַּמְּשִׁין בָּהֶן בִּשְׁעַת לִישָׁה הֲרֵי זֶה יִשְׁפֹּךְ אוֹתָן בִּמְקוֹם מִדְרוֹן כְּדֵי שֶׁלֹּא יִתְקַבְּצוּ בְּמָקוֹם אֶחָד וְיַחְמִיץ:","אֵין שׁוֹרִין אֶת הַמֻּרְסָן וּמַנִּיחִין לִפְנֵי הַתַּרְנְגוֹלִין שֶׁמָּא יַחְמִיץ. אֲבָל חוֹלְטִין לָהֶן הַמֻּרְסָן בְּרוֹתְחִין וּמַנִּיחִין לִפְנֵיהֶן. וּכְבָר נָהֲגוּ רֹב הָעוֹלָם שֶׁלֹּא לַחֲלֹט גְּזֵרָה שֶׁמָּא לֹא יַרְתִּיחַ הַמַּיִם יָפֶה:","וּמֻתָּר לָלוּשׁ לְתַרְנְגוֹלִין מֻרְסָן אוֹ קֶמַח וּמַאֲכִילָן מִיָּד אוֹ נוֹתֵן לִפְנֵיהֶן וְהוּא עוֹמֵד עֲלֵיהֶן עַד שֶׁלֹּא יַשְׁהֶה לִפְנֵיהֶן כְּדֵי הִלּוּךְ מִיל. וְכָל זְמַן שֶׁהֵן מְנַקְּרִין בּוֹ אוֹ שֶׁהוּא מְהַפֵּךְ בְּיָדוֹ אֵינוֹ מַחֲמִיץ. וּכְשֶׁיִּפְסְקוּ מִלֶּאֱכל יִשְׁטֹף הַכְּלִי בְּמַיִם וְיִשְׁפֹּךְ בִּמְקוֹם מִדְרוֹן:","לֹא תִּשְׁרֶה אִשָּׁה מֻרְסָן שֶׁתּוֹלִיךְ בְּיָדָהּ לַמֶּרְחָץ. אֲבָל שָׁפָה עַל בְּשָׂרָהּ יָבֵשׁ. וְלֹא יִלְעֹס אָדָם חִטִּין וְיִתֵּן עַל מַכָּתוֹ מִפְּנֵי שֶׁהֵן מַחֲמִיצוֹת. אֵין נוֹתְנִין אֶת הַקֶּמַח לְתוֹךְ הַחֲרֹסֶת וְאִם נָתַן יִשָּׁפֵךְ מִיָּד מִפְּנֵי שֶׁהוּא מְמַהֵר לְהַחֲמִיץ. וְאֵין נוֹתְנִין אֶת הַקֶּמַח לְתוֹךְ הַחַרְדָּל וְאִם נָתַן יֹאכַל מִיָּד:","מֻתָּר לִתֵּן הַתַּבְלִין וְהַשֻּׁמְשְׁמִין וְהָקֶצַּח וְכַיּוֹצֵא בָּהֶן לְתוֹךְ הַבָּצֵק. וְכֵן מֻתָּר לָלוּשׁ הָעִסָּה בְּמַיִם וְשֶׁמֶן אוֹ דְּבַשׁ וְחָלָב אוֹ לְקַטֵּף בָּהֶן. וּבַיּוֹם הָרִאשׁוֹן אָסוּר לָלוּשׁ וּלְקַטֵּף אֶלָּא בְּמַיִם בִּלְבַד. לֹא מִשּׁוּם חָמֵץ אֶלָּא כְּדֵי שֶׁיִּהְיֶה (דברים טז ג) \"לֶחֶם עֹנִי\". וּבַיּוֹם הָרִאשׁוֹן בִּלְבַד הוּא שֶׁצָּרִיךְ לִהְיוֹת זִכְרוֹן לֶחֶם עֹנִי:","כָּל כְּלִי חֶרֶס שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן חָמֵץ בְּצוֹנֵן מֻתָּר לְהִשְׁתַּמֵּשׁ בָּהֶן מַצָּה בְּצוֹנֵן. חוּץ מִכְּלִי שֶׁמַּנִּיחִין בּוֹ אֶת הַשְּׂאוֹר וּכְלִי שֶׁמַּנִּיחִין בּוֹ חֲרֹסֶת מִפְּנֵי שֶׁחִמּוּצוֹ קָשֶׁה. וְכֵן עֲרֵבוֹת שֶׁלָּשִׁין בָּהֶן הֶחָמֵץ וּמַנִּיחִין אוֹתוֹ שָׁם עַד שֶׁיַּחְמִיץ הֲרֵי הֵן כְּבֵית שְׂאוֹר וְאֵין מִשְׁתַּמְּשִׁין בָּהֶן בְּפֶסַח:","בִּיב שֶׁל חֶרֶס שֶׁאוֹפִין עָלָיו חַלּוֹת חָמֵץ כָּל הַשָּׁנָה כֻּלָּהּ אֵין אוֹפִין עָלָיו מַצָּה בְּפֶסַח. וְאִם מִלְּאוֹ גֶּחָלִים וְהִסִּיק מָקוֹם שֶׁהָיָה מְבַשֵּׁל בּוֹ הֶחָמֵץ מֻתָּר לְבַשֵּׁל עָלָיו מַצָּה:","כְּלֵי מַתָּכוֹת וּכְלֵי אֲבָנִים שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן חָמֵץ בְּרוֹתְחִין בִּכְלִי רִאשׁוֹן כְּגוֹן קְדֵרוֹת וְאִלְפָּסִין. נוֹתֵן אוֹתָן לְתוֹךְ כְּלִי גָּדוֹל שֶׁל מַיִם וּמְמַלֵּא עֲלֵיהֶן מַיִם וּמַרְתִּיחָן בְּתוֹכוֹ עַד שֶׁיִּפְלְטוּ וְאַחַר כָּךְ שׁוֹטֵף אוֹתָן בְּצוֹנֵן וּמִשְׁתַּמֵּשׁ בָּהֶן בְּמַצָּה. וְכֵן הַסַּכִּינִין מַרְתִּיחַ אֶת הַלַּהַב וְאֶת הַנִּצָּב בִּכְלִי רִאשׁוֹן וְאַחַר כָּךְ מִשְׁתַּמֵּשׁ בָּהֶן בְּמַצָּה:","כְּלֵי מַתָּכוֹת וַאֲבָנִים וּכְלֵי עֵצִים שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן חָמֵץ בִּכְלִי שֵׁנִי כְּגוֹן קְעָרוֹת וְכוֹסוֹת נוֹתֵן אוֹתָן לְתוֹךְ כְּלִי גָּדוֹל וְנוֹתֵן עֲלֵיהֶן מַיִם רוֹתְחִין וּמַנִּיחָן בְּתוֹכוֹ עַד שֶׁיִּפְלוֹטוּ וְאַחַר כָּךְ שׁוֹטְפָן וּמִשְׁתַּמֵּשׁ בָּהֶן בְּמַצָּה:","כָּל כְּלִי חֶרֶשׂ שֶׁנִּשְׁתַּמֵּשׁ בָּהֶן חָמֵץ בְּחַמִּין בֵּין כְּלִי רִאשׁוֹן כְּגוֹן קְדֵרוֹת. בֵּין כְּלִי שֵׁנִי כְּגוֹן קְעָרוֹת. בֵּין שֶׁהָיוּ מְשׁוּחִין וְשׁוּעִין בַּאֲבַר שֶׁעוֹשִׂין אוֹתָן כְּעֵין זְכוּכִית. בֵּין שֶׁהָיוּ חֶרֶס כְּמַה שֶּׁהֵן. אֵין מִשְׁתַּמְּשִׁין בָּהֶן בְּמַצָּה אֶלָּא מַנִּיחָן לְאַחַר הַפֶּסַח וּמְבַשֵּׁל בָּהֶן:","כְּלִי רִאשׁוֹן שֶׁרָצָה לְהַרְתִּיחוֹ וְלֹא מָצָא כְּלִי אַחֵר גָּדוֹל מִמֶּנּוּ כְּדֵי לְהַרְתִּיחוֹ בְּתוֹכוֹ הֲרֵי זֶה מַקִּיף לוֹ שָׂפָה שֶׁל טִיט עַל שְׂפָתוֹ מִבַּחוּץ וּמְמַלְּאֵהוּ מַיִם עַד שֶׁיִּגְבְּרוּ הַמַּיִם עַל שְׂפָתוֹ וּמַרְתִּיחַ הַמַּיִם בְּתוֹכוֹ וְדַיּוֹ וְאַחַר כָּךְ שׁוֹטֵף אוֹתוֹ וּמִשְׁתַּמֵּשׁ בּוֹ בְּמַצָּה:"],"Mishneh Torah, Levirate Marriage and Release 8":["מִי שֶׁקִּדֵּשׁ אַחַת מִשְּׁתֵּי אֲחָיוֹת וְאֵין יָדוּעַ אֵי זֶה מֵהֶן קִדֵּשׁ וּמֵת וְלוֹ אָח. אֶחָד חוֹלֵץ לִשְׁתֵּיהֶן כְּדֵי לְהַתִּירָן לַאֲחֵרִים. הָיוּ לוֹ שְׁנֵי אַחִין אֶחָד חוֹלֵץ לְאַחַת מֵהֶן בַּתְּחִלָּה וְהַשֵּׁנִי מְיַבֵּם לַשְּׁנִיָּה עַל כָּל פָּנִים. אִם זוֹ הִיא שֶׁקִּדֵּשׁ אָחִיו הֲרֵי יִבֵּם אוֹתָהּ. וְאִם אֵינָהּ אֵשֶׁת אָחִיו הֲרֵי נָשָׂא אִשָּׁה מִשְּׁאָר הַנָּשִׁים וַאֲחוֹתָהּ שֶׁהָיְתָה אֵשֶׁת אָחִיו כְּבָר נֶחְלְצָה. אֲבָל לֹא יְיַבֵּם הָאַחַת תְּחִלָּה שֶׁמָּא הָאַחֶרֶת הִיא אֵשֶׁת אָחִיו וְנִמְצָא שֶׁנָּשָׂא קְרוֹבַת זְקוּקָתוֹ. קָדְמוּ שְׁנֵי הָאַחִים וְכָנְסוּ שְׁתֵּי הַיְבָמוֹת אֵין מוֹצִיאִין אוֹתָן מִיָּדָן:","שְׁנַיִם שֶׁקִּדְּשׁוּ שְׁתֵּי אֲחָיוֹת. זֶה אֵינוֹ יוֹדֵעַ אֵי זוֹ קִדֵּשׁ וְזֶה אֵינוֹ יוֹדֵעַ אֵי זוֹ קִדֵּשׁ. וּמֵתוּ שְׁנֵיהֶן. לָזֶה אָח וְלָזֶה אָח. זֶה חוֹלֵץ לִשְׁתֵּיהֶן וְזֶה חוֹלֵץ לִשְׁתֵּיהֶן. לָזֶה אָח אֶחָד וְלָזֶה שְׁנַיִם. הַיְחִידִי חוֹלֵץ לִשְׁתֵּיהֶן בַּתְּחִלָּה וְהַשְּׁנַיִם אֶחָד חוֹלֵץ רִאשׁוֹנָה וְהַשֵּׁנִי מְיַבֵּם. וְאִם קָדְמוּ וְכָנְסוּ אֵין מוֹצִיאִין מִיָּדָן. וַאֲפִלּוּ הָיוּ כֹּהֲנִים שֶׁהַחֲלִיצָה שֶׁחָלַץ הַיְחִידִי מִסָּפֵק חָלַץ וְהַחֲלוּצָה אֲסוּרָה לְכֹהֵן מִדִּבְרֵי סוֹפְרִים וּבִסְפֵק חֲלוּצָה לֹא גָּזְרוּ:","הָיוּ לָזֶה שְׁנֵי אַחִין וְלָזֶה שְׁנֵי אַחִין. אָחִיו שֶׁל זֶה חוֹלֵץ לְאַחַת וְאָחִיו שֶׁל זֶה חוֹלֵץ לָאַחֶרֶת. וְאַחַר כָּךְ הָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה. וְהָאָח הַשֵּׁנִי שֶׁל זֶה מְיַבֵּם חֲלוּצָתוֹ שֶׁל זֶה. קָדְמוּ שְׁנֵיהֶן וְחָלְצוּ לִשְׁתֵּיהֶן לֹא יְיַבְּמוּ שְׁנֵי הָאַחִין הָאֲחֵרִים. אֶלָּא אֶחָד חוֹלֵץ בַּתְּחִלָּה וְאָחִיו מְיַבֵּם לַשְּׁנִיָּה. וְאִם קָדְמוּ וְכָנְסוּ אֵין מוֹצִיאִין מִיָּדָן:","הָאִשָּׁה שֶׁהָיוּ לָהּ בָּנִים וְהָיוּ לְכַלָּתָהּ בָּנִים וְנִתְעַבְּרָה הָאִשָּׁה וְנִתְעַבְּרָה כַּלָּתָהּ וְיָלְדוּ שְׁתֵּיהֶן בְּמַחֲבוֹאָה אַחַת וְנִתְעָרְבוּ שְׁנֵי הַיְלָדִים וְהִגְדִּילוּ הַתַּעֲרוֹבוֹת וְנָשְׂאוּ נָשִׁים וּמֵתוּ. כֵּיצַד הֵן נִתָּרוֹת. בְּנֵי הַכַּלָּה חוֹלְצִין לִשְׁתֵּיהֶן תְּחִלָּה וְלֹא מְיַבְּמִין שֶׁכָּל אַחַת מֵהֶן סָפֵק שֶׁהִיא אֵשֶׁת אָחִיו וְתִהְיֶה מֻתֶּרֶת לוֹ, סָפֵק שֶׁהִיא אֵשֶׁת אֲחִי אָבִיו וְהִיא עֶרְוָה עָלָיו. אֲבָל בְּנֵי הַזְּקֵנָה אוֹ חוֹלְצִין אוֹ מְיַבְּמִין. שֶׁאִם הִיא זוֹ אֵשֶׁת אָחִיו הֲרֵי יִבְּמָהּ. וְאִם הִיא אֵשֶׁת בֶּן אָחִיו מֻתֶּרֶת לְהִנָּשֵׂא לוֹ שֶׁכְּבָר נֶחְלְצָה:","מֵתוּ הַבָּנִים הַיְדוּעִים שֶׁל זְקֵנָה וְשֶׁל כַּלָּתָהּ וַהֲרֵי בְּנֵי הַתַּעֲרוֹבוֹת קַיָּמִין. בְּנֵי הַתַּעֲרוֹבוֹת לִנְשֵׁי בְּנֵי הַזְּקֵנָה חוֹלְצִין וְלֹא מְיַבְּמִין שֶׁהִיא סְפֵק אֵשֶׁת אֲחִי אָבִיו שֶׁהִיא עֶרְוָה עָלָיו, סְפֵק אֵשֶׁת אָחִיו שֶׁהִיא מֻתֶּרֶת לְיַבְּמָהּ. וְלִנְשֵׁי בְּנֵי הַכַּלָּה אֶחָד חוֹלֵץ בַּתְּחִלָּה וְאֶחָד מְיַבֵּם עַל כָּל פָּנִים. אִם בֶּן הַכַּלָּה הוּא שֶׁחָלַץ תְּחִלָּה הֲרֵי חָלַץ אֵשֶׁת אָחִיו וְהַשֵּׁנִי מִן הַתַּעֲרוֹבוֹת הוּא בֶּן הַזְּקֵנָה וּמֻתָּר לוֹ לִשָּׂא אֵשֶׁת בֶּן אָחִיו אַחַר שֶׁנֶּחְלְצָה מִיבָמָהּ. וְאִם זֶה שֶׁחָלַץ תְּחִלָּה הוּא בֶּן הַזְּקֵנָה הֲרֵי חָלַץ לְאֵשֶׁת בֶּן אָחִיו וְלֹא עָשָׂה כְּלוּם וְהַשֵּׁנִי מִן הַתַּעֲרוֹבוֹת הוּא בֶּן הַכַּלָּה וַהֲרֵי יִבֵּם אֵשֶׁת אָחִיו:","מִי שֶׁלֹּא שָׁהֲתָה אַחַר מִיתַת בַּעְלָהּ שְׁלֹשָׁה חֳדָשִׁים וְנִשֵּׂאת וְיָלְדָה וְאֵין יָדוּעַ אִם בֶּן תִּשְׁעָה לָרִאשׁוֹן אִם בֶּן שִׁבְעָה לָאַחֲרוֹן. וְהָיוּ לָהּ בָּנִים מִן הָרִאשׁוֹן וּמִן הַשֵּׁנִי. אִם מֵת זֶה הַבֵּן הַסָּפֵק. בְּנֵי הָרִאשׁוֹן וּבְנֵי הַשֵּׁנִי חוֹלְצִין לְאִשְׁתּוֹ וְלֹא מְיַבְּמִין. שֶׁכָּל אֶחָד מֵהֶן שֶׁיָּבוֹא לְיַבֵּם שֶׁמָּא אֵינוֹ אָחִיו מֵאָבִיו וַהֲרֵי הוּא אָחִיו מֵאִמּוֹ בְּוַדַּאי וְאֵשֶׁת אָחִיו מֵאִמּוֹ אֲסוּרָה עָלָיו לְעוֹלָם מִשּׁוּם עֶרְוָה. וְכֵן זֶה הַבֵּן הַסָּפֵק חוֹלֵץ לִנְשׁוֹתֵיהֶן וְלֹא מְיַבֵּם:","הָיָה בֵּן לָרִאשׁוֹן וּבֵן לַשֵּׁנִי שֶׁלֹּא מֵאִשָּׁה זוֹ שֶׁנִּשֵּׂאת בְּתוֹךְ זְמַן וּמֵת אֶחָד מֵהֶן. הֲרֵי הַבֵּן הַסָּפֵק חוֹלֵץ לְאֵשֶׁת זֶה שֶׁמֵּת אוֹ מְיַבֵּם. שֶׁאִם אָחִיו מֵאָבִיו הוּא הֲרֵי יִבֵּם אֶת אִשְׁתּוֹ וְאִם אֵינוֹ אָחִיו מֵאָבִיו הֲרֵי אֵין בֵּינֵיהֶן אַחֲוָה כְּלָל לְפִיכָךְ מֻתָּר לוֹ לִשָּׂא אֶת אִשְׁתּוֹ:","מֵת הַבֵּן הַסָּפֵק אֶחָד מִשְּׁנֵי הַבָּנִים הַוַּדָּאִין חוֹלֵץ לְאִשְׁתּוֹ תְּחִלָּה וְהַשֵּׁנִי מְיַבֵּם עַל כָּל פָּנִים. אִם אָחִיו הוּא הֲרֵי יִבֵּם אֶת אִשְׁתּוֹ. וְאִם אֵינוֹ אָחִיו וְהוּא בֶּן הָאָב הָאַחֵר הֲרֵי נֶחְלְצָה מֵאֲחִי בַּעְלָהּ:","מִי שֶׁהָלַךְ בַּעְלָהּ לִמְדִינָה אַחֶרֶת וְשָׁמְעָה שֶׁמֵּת וְנִשֵּׂאת וְאַחַר כָּךְ בָּא הַבַּעַל הָרִאשׁוֹן וּמֵתוּ שְׁנֵיהֶן וְלָזֶה אַחִין וְלָזֶה אַחִין. אֶחָיו שֶׁל זֶה וְאֶחָיו שֶׁל זֶה חוֹלְצִין וְלֹא מְיַבְּמִין:","חָמֵשׁ נָשִׁים שֶׁהָיָה לְכָל אַחַת מֵהֶן בֵּן יָדוּעַ וְנִתְעַבְּרוּ חֲמִשְׁתָּן וְיָלְדוּ כְּאֶחָד בְּמַחֲבוֹאָה אַחַת חֲמִשָּׁה בָּנִים אֲחֵרִים וְנִתְעָרְבוּ הַיְלָדִים וְהִגְדִּילוּ הַתַּעֲרוֹבוֹת וְנָשְׂאוּ נָשִׁים וּמֵתוּ חֲמִשָּׁה הָאֲנָשִׁים וְנָפְלוּ חָמֵשׁ הַנָּשִׁים לִפְנֵי חֲמִשָּׁה הַבָּנִים הַוַּדָּאִין שֶׁאֵין אֶחָד מֵהֶן יוֹדֵעַ אֵי זוֹ הִיא אֵשֶׁת אָחִיו כֵּיצַד תַּקָּנָתָן. אַרְבַּע מֵהֶן חוֹלְצִין לְאַחַת תְּחִלָּה וְהַחֲמִישִׁי יִשָּׂא זוֹ שֶׁנֶּחְלְצָה אַרְבַּע חֲלִיצוֹת עַל כָּל פָּנִים:","כֵּיצַד. אִם אֵשֶׁת אָחִיו הִיא הֲרֵי יִבֵּם אוֹתָהּ. וְאִם אֵינָהּ אֵשֶׁת אָחִיו הֲרֵי הִיא אֵשֶׁת אָח אֶחָד מֵאַרְבָּעָה וַהֲרֵי חָלְצוּ לָהּ אַרְבַּעְתָּן תְּחִלָּה. וְכֵן הַשְּׁנִיָּה חוֹלְצִין לָהּ אַרְבָּעָה וְהָאֶחָד מִן הָאַרְבָּעָה יִהְיֶה זֶה שֶׁנָּשָׂא הָרִאשׁוֹנָה וְהַחֲמִישִׁי יִשָּׂאֶנָּה. עַד שֶׁנִּמְצְאוּ הַבָּנִים הַחֲמִשָּׁה נָשְׂאוּ הֶחָמֵשׁ נָשִׁים אַחַר שֶׁנֶּחְלְצָה כָּל אַחַת מֵהֶן אַרְבַּע חֲלִיצוֹת:","וּלְעוֹלָם הִזָּהֵר בְּכָל הַסְּפֵקוֹת הַלָּלוּ בְּעִקָּרִים אֵלּוּ. שֶׁכָּל מִי שֶׁנִּסְתַּפֵּק לְךָ שֶׁמָּא בַּת חֲלִיצָה הִיא לְאִישׁ זֶה אוֹ אֵינָהּ צְרִיכָה לַחֲלִיצָה מִמֶּנּוּ. אֵינָהּ נִתֶּרֶת לְהִנָּשֵׂא לְזָר עַד שֶׁיַּחֲלֹץ לָהּ אוֹתוֹ הָאִישׁ. וְכָל מִי שֶׁיִּסְתַּפֵּק לְךָ שֶׁמָּא בִּיאָתָהּ אֲסוּרָה עַל אִישׁ זֶה בֵּין מִדִּבְרֵי תּוֹרָה בֵּין מִדִּבְרֵי סוֹפְרִים אֵינָהּ מִתְיַבֶּמֶת לוֹ. וְכָל שֶׁנֶּחְלְצָה חֲלִיצָה מְעֻלָּה אוֹ נִבְעֲלָה בְּעִילָה כְּשֵׁרָה הֻתְּרָה צָרָתָהּ לְזָר:","וְעַל דֶּרֶךְ זוֹ תָּבִין וְתוֹרֶה בְּכָל הַסְּפֵקוֹת שֶׁיֶּאֶרְעוּ לְעִנְיַן יִבּוּם וַחֲלִיצָה שֶׁהֲרֵי בֵּאַרְנוּ כָּל הָעִקָּרִין שֶׁעֲלֵיהֶן תִּסְמֹךְ וְתֵדַע מִי הוּא שֶׁחוֹלֵץ וּמִי הוּא שֶׁמְּיַבֵּם וּמִי הִיא הַפְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם וּמִי הִיא הָרְאוּיָה לְיַבֵּם: סְלִיקוּ לְהוּ הִלְכוֹת יִבּוּם וַחֲלִיצָה בְּסִיַּעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Marriage 2":["הַבַּת מִיּוֹם לֵדָתָהּ עַד שֶׁתִּהְיֶה בַּת י\"ב שָׁנָה גְּמוּרוֹת הִיא הַנִּקְרֵאת קְטַנָּה וְנִקְרֵאת תִּינֹקֶת. וַאֲפִלּוּ הֵבִיאָה כַּמָּה שְׂעָרוֹת בְּתוֹךְ הַזְּמַן הַזֶּה אֵינָם אֶלָּא כְּשׁוּמָא. אֲבָל אִם הֵבִיאָה שְׁתֵּי שְׂעָרוֹת לְמַטָּה בַּגּוּף בַּמְּקוֹמוֹת הַיְדוּעוֹת לַהֲבָאַת שֵׂעָר וְהִיא מִבַּת י\"ב שָׁנָה וְיוֹם אֶחָד וָמַעְלָה נִקְרֵאת נַעֲרָה:","וַהֲבָאַת שְׁתֵּי שְׂעָרוֹת בַּזְּמַן הַזֶּה נִקְרָא סִימָן הַתַּחְתּוֹן. וּמֵאַחַר שֶׁתָּבִיא סִימָן הַתַּחְתּוֹן תִּקָּרֵא נַעֲרָה עַד שִׁשָּׁה חֳדָשִׁים גְּמוּרִים. וּמִתְּחִלַּת יוֹם תַּשְׁלוּם הַשִּׁשָּׁה חֳדָשִׁים וָמַעְלָה תִּקָּרֵא בּוֹגֶרֶת. וְאֵין בֵּין נַעֲרוּת לְבַגְרוּת אֶלָּא שִׁשָּׁה חֳדָשִׁים בִּלְבַד:","הִגִּיעָה לְי\"ב שָׁנָה וְיוֹם אֶחָד וְלֹא הֵבִיאָה שְׁתֵּי שְׂעָרוֹת אַף עַל פִּי שֶׁנִּרְאוּ בָּהּ סִימָנֵי אַיְלוֹנִית עֲדַיִן קְטַנָּה הִיא עַד עֶשְׂרִים שָׁנָה. וּכְשֶׁתָּבִיא שְׁתֵּי שְׂעָרוֹת אֲפִלּוּ בִּשְׁנַת עֶשְׂרִים תִּהְיֶה נַעֲרָה שִׁשָּׁה חֳדָשִׁים וְאַחַר כָּךְ תִּקָּרֵא בּוֹגֶרֶת:","הָיְתָה בַּת עֶשְׂרִים שָׁנָה פָּחוֹת שְׁלֹשִׁים יוֹם וְלֹא הֵבִיאָה שְׁתֵּי שְׂעָרוֹת וְנִרְאוּ בָּהּ (כָּל) סִימָנֵי אַיְלוֹנִית הֲרֵי הִיא אַיְלוֹנִית. וְאִם לֹא נִרְאוּ בָּהּ (כָּל) סִימָנֵי אַיְלוֹנִית עֲדַיִן קְטַנָּה הִיא עַד שֶׁתָּבִיא שְׁתֵּי שְׂעָרוֹת אוֹ עַד שֶׁתִּהְיֶה בַּת ל\"ה שָׁנָה וְיוֹם אֶחָד:","הִגִּיעָה לַזְּמַן הַזֶּה וְלֹא הֵבִיאָה שְׁתֵּי שְׂעָרוֹת הֲרֵי זוֹ נִקְרֵאת אַיְלוֹנִית אַף עַל פִּי שֶׁלֹּא נִרְאֶה בָּהּ סִימָן מִסִּימָנֵי אַיְלוֹנִית. נִמְצֵאתָ אַתָּה לָמֵד שֶׁהָאַיְלוֹנִית אֵין לָהּ יְמֵי נַעֲרוּת אֶלָּא מִקַּטְנוּתָהּ תֵּצֵא לְבַגְרוּת:","וְאֵלּוּ הֵן סִימָנֵי אַיְלוֹנִית. כָּל שֶׁאֵין לָהּ דָּדִין. וּמִתְקַשָּׁה בִּשְׁעַת תַּשְׁמִישׁ. וְאֵין לָהּ שִׁפּוּלֵי מֵעַיִם כְּנָשִׁים. וְקוֹלָהּ עָבֶה וְאֵינָהּ נִכֶּרֶת בֵּין אִישׁ לְאִשָּׁה. וְהַנַּעֲרָה וְהַבּוֹגֶרֶת וְהָאַיְלוֹנִית כָּל אַחַת מִשְּׁלָשְׁתָּן נִקְרֵאת גְּדוֹלָה:","וְיֵשׁ בְּבַת סִימָנִין מִלְּמַעְלָה וְהֵן הַנִּקְרָאִין סִימָן הָעֶלְיוֹן. וְאֵלּוּ הֵן. מִשֶּׁתַּחֲזִיר יָדֶיהָ לְאָחוֹרָהּ וְיֵעָשֶׂה קֶמֶט (בִּמְקוֹם הַדָּדִין). וּמִשֶּׁיַּשְׁחִיר רֹאשׁ הַדָּד. וּמִשֶּׁיִּתֵּן אָדָם יָדוֹ עַל עֹקֶץ הַדָּד וְהוּא שׁוֹקֵעַ וְשׁוֹהֶה לַחֲזֹר. וּמִשֶּׁיִּפָּצֵל רֹאשׁ חֹטֶם הַדָּד וְיֵעָשֶׂה בְּרֹאשׁוֹ כַּדּוּר קָטָן. וְרַבּוֹתַי פֵּרְשׁוּ מִשֶּׁיִּפָּצֵל הַחֹטֶם עַצְמוֹ. וְכֵן מִשֶּׁיִּטּוּ הַדָּדִין. וּמִשֶּׁיִּתְקַשְׁקְשׁוּ הַדָּדִין. וּמִשֶּׁתַּקִּיף הָעֲטָרָה שֶׁהוּא מְקוֹם הַבָּשָׂר הַתָּפוּחַ שֶׁלְּמַעְלָה מִן הָעֶרְוָה לְעֵמַּת הַבֶּטֶן. וּמִשֶּׁיִּתְמַעֵךְ הַבָּשָׂר הַזֶּה וְלֹא יִהְיֶה קָשֶׁה:","כָּל אֵלּוּ הַסִּימָנִין שְׁמוֹנָה. נִרְאֶה בַּבַּת סִימָן אֶחָד מִכָּל אֵלּוּ אוֹ כֻּלָּן וְהִיא בַּת י\"ב שָׁנָה אוֹ פָּחוֹת אֵין מַשְׁגִּיחִין בּוֹ וַהֲרֵי הִיא קְטַנָּה. נַעֲשֵׂית בַּת י\"ב שָׁנָה וְיוֹם אֶחָד וְנִרְאֶה בָּהּ סִימָן הַתַּחְתּוֹן אֵין מַשְׁגִּיחִין בְּאֶחָד מִכָּל אֵלּוּ. וְאִם לֹא נִרְאֶה הַתַּחְתּוֹן וְנִרְאֶה בָּהּ אֶחָד מִכָּל אֵלּוּ הֲרֵי הִיא סָפֵק בֵּין נַעֲרָה לִקְטַנָּה וְדָנִים בָּהּ לְהַחֲמִיר. וְאִם נִרְאוּ כֻּלָּן [וְלֹא נִרְאֶה סִימָן הַתַּחְתּוֹן] הֲרֵי זוֹ גְּדוֹלָה וַדָּאִית. שֶׁאִי אֶפְשָׁר שֶׁיָּבוֹאוּ כֻּלָּן אֶלָּא כְּבָר בָּא סִימָן הַתַּחְתּוֹן וְנָשַׁר:","הַבַּת שֶׁיָּלְדָה אַחַר שְׁתֵּים עֶשְׂרֵה שָׁנָה אַף עַל פִּי שֶׁלֹּא הֵבִיאָה סִימָנִים לֹא תַּחְתּוֹן וְלֹא עֶלְיוֹן הֲרֵי זוֹ גְּדוֹלָה. בָּנִים הֲרֵי הֵם כְּסִימָנִין:","הַבֵּן מִשֶּׁיִּוָּלֵד עַד שֶׁיִּהְיֶה בֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה נִקְרָא קָטָן וְנִקְרָא תִּינוֹק וַאֲפִלּוּ הֵבִיא כַּמָּה שְׂעָרוֹת בְּתוֹךְ הַזְּמַן הַזֶּה אֵינוֹ סִימָן אֶלָּא שׁוּמָא. הֵבִיא שְׁתֵּי שְׂעָרוֹת לְמַטָּה בַּמְּקוֹמוֹת הַיְדוּעוֹת לְשֵׂעָר. וְהוּא מִבֶּן שְׁלֹשׁ עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד וָמַעְלָה נִקְרָא גָּדוֹל וְנִקְרָא אִישׁ:","הִגִּיעַ לַזְּמַן הַזֶּה וְלֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת אַף עַל פִּי שֶׁנִּרְאוּ בּוֹ סִימָנֵי סָרִיס הֲרֵי הוּא קָטָן עַד שֶׁיִּהְיֶה בֶּן עֶשְׂרִים שָׁנָה פָּחוֹת שְׁלֹשִׁים יוֹם. הִגִּיעַ לַזְּמַן הַזֶּה וְלֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת לְמַטָּה וְלֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת בַּזָּקָן. אִם נִרְאֶה בּוֹ אֶחָד מִסִּימָנֵי סָרִיס הֲרֵי הוּא סָרִיס וְדִינוֹ דִּין הַגָּדוֹל לְכָל דָּבָר. וְאִם לֹא נִרְאֶה בּוֹ סִימָן מִסִּימָנֵי סָרִיס עֲדַיִן קָטָן הוּא עַד שֶׁיָּבִיא שְׁתֵּי שְׂעָרוֹת לְמַטָּה בַּמָּקוֹם הָרָאוּי לָהֶן אוֹ עַד שֶׁיִּהְיֶה בֶּן ל\"ה שָׁנָה וְיוֹם אֶחָד:","הִגִּיעַ לַזְּמַן הַזֶּה וְלֹא הֵבִיא הֲרֵי זֶה סָרִיס אַף עַל פִּי שֶׁלֹּא נִרְאֶה בּוֹ אֶחָד מִסִּימָנֵי סָרִיס. הִגִּיעַ לִשְׁנַת עֶשְׂרִים פָּחוֹת שְׁלֹשִׁים יוֹם וְלֹא הֵבִיא שְׁתֵּי שְׂעָרוֹת לְמַטָּה וְהֵבִיא שְׁתֵּי שְׂעָרוֹת בַּזָּקָן אַף עַל פִּי שֶׁנּוֹלַד לוֹ אֶחָד מִסִּימָנֵי סָרִיס אֵינוֹ סָרִיס. אֶלָּא הֲרֵי הוּא בְּקַטְנוּתוֹ עַד שֶׁיִּוָּלְדוּ לוֹ כָּל סִימָנֵי סָרִיס אוֹ עַד שֶׁיִּהְיֶה בֶּן ל\"ה שָׁנָה וְיוֹם אֶחָד:","וְאֵלּוּ הֵן סִימָנֵי סָרִיס. כָּל שֶׁאֵין לוֹ זָקָן. וּשְׂעָרוֹ לָקוּי. וּבְשָׂרוֹ מַחֲלִיק. וְאֵין מֵימֵי רַגְלָיו מַעֲלִים רְתִיחָה. וּכְשֶׁמֵּטִיל מַיִם אֵינוֹ עוֹשֶׂה כִּפָּה. וְשִׁכְבַת זַרְעוֹ דִּיהָה. וְאֵין מֵימֵי רַגְלָיו מַחְמִיצִין. וְרוֹחֵץ בִּימוֹת הַגְּשָׁמִים וְאֵינוֹ מַעֲלֶה בְּשָׂרוֹ הֶבֶל. וְקוֹלוֹ לָקוּי וְאֵינוֹ נִכָּר בֵּין אִישׁ לְאִשָּׁה:","וְסָרִיס זֶה הוּא הַנִּקְרָא סְרִיס חַמָּה בְּכָל מָקוֹם. אֲבָל הַבֵּן שֶׁחָתְכוּ אוֹ נִתְּקוּ אוֹ מִעֲכוּ גִּידָיו אוֹ בֵּיצָיו כְּמוֹ שֶׁהָעַכּוּ\"ם עוֹשִׂין הוּא הַנִּקְרָא סְרִיס אָדָם. וּכְשֶׁיִּהְיֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד נִקְרָא גָּדוֹל שֶׁאֵין זֶה מֵבִיא סִימָן לְעוֹלָם:","בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד שֶׁלֹּא הֵבִיא סִימָן שֶׁלְּמַטָּה וְנִרְאוּ בּוֹ כָּל הַסִּימָנִין שֶׁל מַעְלָה הֲרֵי זֶה סָפֵק בֵּין גָּדוֹל לְקָטָן. וְאִם לֹא נִבְדַּק מִלְּמַטָּה כֵּיוָן שֶׁנִּרְאֶה בּוֹ סִימָנֵי בַּגְרוּת מִלְּמַעְלָה הֲרֵי זֶה בְּחֶזְקַת גָּדוֹל:","שְׁתֵּי שְׂעָרוֹת הָאֲמוּרוֹת בְּבֵן וּבְבַת בְּכָל מָקוֹם שִׁעוּרָן כְּדֵי לָכֹף רֹאשָׁן לְעִקָּרָן. וּמִשֶּׁיִּצְמְחוּ וְיִהְיוּ יְכוֹלוֹת לְהִנָּטֵל בְּפִי הַזּוּג עַד שֶׁיַּגִּיעוּ לָכֹף רֹאשָׁן לְעִקָּרָן דָּנִין בָּהֶן לְהַחֲמִיר בְּכָל מָקוֹם. לְפִיכָךְ בְּבֵן וּבְבַת נַחְשֹׁב אוֹתָם גְּדוֹלִים לְהַחֲמִיר הוֹאִיל וְצָמְחוּ כְּדֵי לְהִנָּטֵל בְּפִי הַזּוּג. וְנַחְשֹׁב אוֹתָם קְטַנִּים לְהַחֲמִיר הוֹאִיל וְלֹא הִגִּיעוּ לָכֹף רֹאשָׁן לְעִקָּרָן:","שְׁתֵּי שְׂעָרוֹת אֵלּוּ צְרִיכוֹת שֶׁיִּהְיוּ בִּמְקוֹם הָעֶרְוָה. וּבֵית הָעֶרְוָה כֻּלּוֹ מְקוֹם סִימָנִין בֵּין לְמַעְלָה בֵּין לְמַטָּה בֵּין עַל אֵיבְרֵי הַזֶּרַע עַצְמָן. וּצְרִיכוֹת לִהְיוֹת בְּמָקוֹם אֶחָד. וְשֶׁיִּהְיֶה בְּעִקָּרָן גֻּמּוֹת. וַאֲפִלּוּ שְׁתֵּיהֶן בְּגֻמָּה אַחַת הֲרֵי אֵלּוּ סִימָן. נִמְצְאוּ שְׁתֵּי גֻּמּוֹת זוֹ בְּצַד זוֹ וְאֵין בָּהֶן שֵׂעָר הֲרֵי אֵלּוּ סִימָן. חֲזָקָה אֵין גֻּמָּא בְּלֹא שֵׂעָר וּשְׂעָרוֹת הָיוּ בָּהֶן וְנָשְׁרוּ:","הַבַּת שֶׁהֵבִיאָה שְׁתֵּי שְׂעָרוֹת בְּתוֹךְ י\"ב שָׁנָה וְהַבֵּן שֶׁהֵבִיא בְּתוֹךְ י\"ג שְׁנֵיהֶם שׁוּמָא כְּמוֹ שֶׁבֵּאַרְנוּ. אַף עַל פִּי שֶׁאוֹתָן שְׂעָרוֹת בִּמְקוֹמָן הֵם עוֹמְדוֹת אַחַר י\"ג לְזָכָר וְאַחַר י\"ב לִנְקֵבָה אֵינָן סִימָן:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁנִּבְדְּקוּ בְּתוֹךְ הַזְּמַן וְנוֹדַע שֶׁהֵן שׁוּמָא. אֲבָל אִם לֹא נִבְדְּקוּ אֶלָּא אַחַר זְמַן וְנִמְצְאוּ שָׁם שְׁתֵּי שְׂעָרוֹת הֲרֵי הֵן בְּחֶזְקַת סִימָנִין. וְאֵין אוֹמְרִין שֶׁמָּא קֹדֶם זְמַן צָמְחוּ כְּדֵי שֶׁיִּהְיוּ שׁוּמָא:","כְּשֶׁבּוֹדְקִין הַבַּת בֵּין בְּתוֹךְ הַזְּמַן שֶׁהוּא כָּל שְׁנַת י\"ב בֵּין קֹדֶם זְמַן זֶה בֵּין לְאַחַר הַזְּמַן בּוֹדְקִין עַל פִּי נָשִׁים כְּשֵׁרוֹת וְנֶאֱמָנוֹת. וַאֲפִלּוּ אִשָּׁה אַחַת בּוֹדֶקֶת וְשׁוֹמְעִין לָהּ אִם הֵבִיאָה וְאִם לֹא הֵבִיאָה:","כָּל הַשָּׁנִים הָאֲמוּרוֹת בְּבֵן וּבְבַת וּבְעֶרְכִין וּבְכָל מָקוֹם אֵינָן לֹא שְׁנֵי הַלְּבָנָה וְלֹא שְׁנֵי הַחַמָּה אֶלָּא שָׁנִים שֶׁל סֵדֶר הָעִבּוּר שֶׁהֵן פְּשׁוּטוֹת וּמְעֵבָּרוֹת עַל פִּי בֵּית דִּין כְּמוֹ שֶׁהֵם קוֹבְעִין אוֹתָן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת קִדּוּשׁ הַחֹדֶשׁ. וּבְאוֹתָן הַשָּׁנִים מוֹנִין לְכָל דִּבְרֵי הַדָּת:","אֵין סוֹמְכִין עַל הַנָּשִׁים בְּמִנְיַן הַשָּׁנִים וְלֹא עַל הַקְּרוֹבִים אֶלָּא עַל פִּי שְׁנַיִם אֲנָשִׁים כְּשֵׁרִים לְהָעִיד:","הָאָב שֶׁאָמַר בְּנִי זֶה בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד. בִּתִּי זוֹ בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד נֶאֱמָן לְקָרְבָּן אֲבָל לֹא לְמַכּוֹת וְלֹא לָעֳנָשִׁים. בְּנִי זֶה בֶּן י\"ג שָׁנָה וְיוֹם אֶחָד בִּתִּי זוֹ בַּת י\"ב שָׁנָה וְיוֹם אֶחָד נֶאֱמָן לִנְדָרִים וּלְעֶרְכִין וְלַחֲרָמוֹת וּלְהֶקְדֵּשׁוֹת אֲבָל לֹא לְמַכּוֹת וְלֹא לָעֳנָשִׁים:","מִי שֶׁיֵּשׁ לוֹ אֵיבַר זִכְרוּת וְאֵיבַר נְקֵבוּת הוּא הַנִּקְרָא אַנְדְּרוֹגִינוּס וְהוּא סָפֵק אִם זָכָר סָפֵק אִם נְקֵבָה. וְאֵין לוֹ סִימָן שֶׁיִּוָּדַע בּוֹ אִם הוּא זָכָר וַדַּאי אִם הִיא נְקֵבָה וַדָּאִית לְעוֹלָם:","וְכָל מִי שֶׁאֵין לוֹ לֹא זִכְרוּת וְלֹא נְקֵבוּת אֶלָּא אָטוּם הוּא הַנִּקְרָא טֻמְטוּם וְגַם הוּא סָפֵק. וְאִם נִקְרַע הַטֻּמְטוּם וְנִמְצָא זָכָר הֲרֵי הוּא כְּזָכָר וַדַּאי. וְאִם נִמְצָא נְקֵבָה הֲרֵי הוּא נְקֵבָה. וְטֻמְטוּם וְאַנְדְּרוֹגִינוּס שֶׁהָיוּ בֶּן שְׁתֵּים עֶשְׂרֵה שָׁנָה וְיוֹם אֶחָד הֲרֵי הֵן בְּחֶזְקַת גְּדוֹלִים וְהֵם שֶׁנְּדַבֵּר בָּהֶן בְּכָל מָקוֹם:","חֵרֵשׁ וְחֵרֶשֶׁת הָאֲמוּרִים בְּכָל מָקוֹם הֵן הָאִלְּמִים שֶׁאֵין שׁוֹמְעִין וְלֹא מְדַבְּרִים. אֲבָל מִי שֶׁמְּדַבֵּר וְאֵינוֹ שׁוֹמֵעַ אוֹ שׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר הֲרֵי הוּא כְּכָל אָדָם. וְאִישׁ וְאִשָּׁה שֶׁהֵן שְׁלֵמִים בְּדַעְתָּן וְאֵינָן לֹא חֵרְשִׁים וְלֹא שׁוֹטִים נִקְרָאִין פִּקֵּחַ וּפִקַּחַת:","נִמְצְאוּ כָּל הַשֵּׁמוֹת שֶׁבֵּאַרְנוּ עִנְיָנָם בִּשְׁנֵי פְּרָקִים אֵלּוּ עֶשְׂרִים שֵׁמוֹת. וְאִלּוּ הֵן. קִדּוּשִׁין. עֶרְוָה. שְׁנִיָּה. אִסּוּרֵי לָאוִין. אִסּוּרֵי עֲשֵׂה. קְטַנָּה. נַעֲרָה. בּוֹגֶרֶת. אַיְלוֹנִית. גְּדוֹלָה. סִימָן הַתַּחְתּוֹן. סִימָן הָעֶלְיוֹן. קָטָן. סְרִיס חַמָּה. סְרִיס אָדָם. גָּדוֹל. אַנְדְּרוֹגִינוּס. טֻמְטוּם. חֵרְשִׁים. פִּקְחִים. שִׂים כָּל הַשֵּׁמוֹת הָאֵלּוּ לְעֻמָּתְךָ תָּמִיד וְאַל יָלוֹזוּ מֵעֵינֶיךָ כָּל עִנְיְנֵיהֶם כְּדֵי שֶׁלֹּא נִהְיֶה צְרִיכִין לְבָאֵר כָּל שֵׁם מֵהֶן בְּכָל מָקוֹם שֶׁנַּזְכִּיר אוֹתוֹ:"],"Mishneh Torah, Marriage 8":["הָאוֹמֵר לְאִשָּׁה הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בְּכוֹס זֶה שֶׁל יַיִן וְנִמְצָא שֶׁל דְּבַשׁ. שֶׁל דְּבַשׁ וְנִמְצָא שֶׁל יַיִן. בְּדִינָר זֶה שֶׁל כֶּסֶף וְנִמְצָא שֶׁל זָהָב. שֶׁל זָהָב וְנִמְצָא שֶׁל כֶּסֶף. עַל מְנָת שֶׁאֲנִי כֹּהֵן וְנִמְצָא לֵוִי. לֵוִי וְנִמְצָא כֹּהֵן. נָתִין וְנִמְצָא מַמְזֵר. מַמְזֵר וְנִמְצָא נָתִין. בֶּן עִיר וְנִמְצָא בֶּן כְּרַךְ. בֶּן כְּרַךְ וְנִמְצָא בֶּן עִיר. עַל מְנָת שֶׁאֲנִי עָנִי וְנִמְצָא עָשִׁיר. עָשִׁיר וְנִמְצָא עָנִי. עַל מְנָת שֶׁבֵּיתִי קָרוֹב לַמֶּרְחָץ וְנִמְצָא רָחוֹק. רָחוֹק וְנִמְצָא קָרוֹב. עַל מְנָת שֶׁיֵּשׁ לִי שִׁפְחָה אוֹ בַּת גּוֹדֶלֶת אוֹ אוֹפָה וְאֵין לוֹ. עַל מְנָת שֶׁאֵין לוֹ וְיֵשׁ לוֹ. עַל מְנָת שֶׁיֵּשׁ לִי אִשָּׁה וּבָנִים וְאֵין לוֹ. עַל מְנָת שֶׁאֵין לִי וְיֵשׁ לוֹ. בְּכָל אֵלּוּ וְכָל הַדּוֹמֶה לָהֶן אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן הִיא שֶׁהִטְעַתּוּ:","וּבְכֻלָּם אַף עַל פִּי שֶׁאָמְרָה בְּלִבִּי הָיָה לְהִתְקַדֵּשׁ לוֹ אַף עַל פִּי שֶׁהִטְעַנִי וְאֵין הַדָּבָר כְּמוֹ שֶׁאָמַר. וְכֵן אִם אָמַר הוּא בְּלִבִּי הָיָה לְקַדְּשָׁהּ אַף עַל פִּי שֶׁהִטְעַתְנִי אֵינָהּ מְקֻדֶּשֶׁת לְפִי שֶׁהַדְּבָרִים שֶׁבַּלֵּב אֵינָם דְּבָרִים:","הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי עַל מְנָת שֶׁאֲנִי בַּסָּם וְנִמְצָא בַּסָּם וּבוּרְסַי. עַל מְנָת שֶׁאֲנִי בֶּן עִיר וְנִמְצָא בֶּן עִיר וּבֶן כְּרַךְ. עַל מְנָת שֶׁשְּׁמִי יוֹסֵף וְנִמְצָא שְׁמוֹ יוֹסֵף וְשִׁמְעוֹן הֲרֵי זוֹ מְקֻדֶּשֶׁת. אֲבָל אִם אָמַר לָהּ עַל מְנָת שֶׁאֵין שְׁמִי אֶלָּא יוֹסֵף וְנִמְצָא שְׁמוֹ יוֹסֵף וְשִׁמְעוֹן. שֶׁאֵינִי אֶלָּא בַּסָּם וְנִמְצָא בַּסָּם וּבוּרְסַי. שֶׁאֵינִי אֶלָּא בֶּן עִיר וְנִמְצָא בֶּן כְּרַךְ וּבֶן עִיר אֵינָהּ מְקֻדֶּשֶׁת:","הָאוֹמֵר לְאִשָּׁה הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי עַל מְנָת שֶׁאֲנִי יוֹדֵעַ לִקְרוֹת. צָרִיךְ שֶׁיִּקְרָא הַתּוֹרָה וִיתַרְגֵּם אוֹתָהּ תַּרְגּוּם אֻנְקְלוּס הַגֵּר. וְאִם אָמַר לָהּ עַל מְנָת שֶׁאֲנִי קוֹרֵא צָרִיךְ לִהְיוֹת יוֹדֵעַ לִקְרוֹת תּוֹרָה נְבִיאִים וּכְתוּבִים בְּדִקְדּוּק יָפֶה. עַל מְנָת שֶׁאֲנִי יוֹדֵעַ לִשְׁנוֹת צָרִיךְ לִהְיוֹת יוֹדֵעַ לִקְרוֹת הַמִּשְׁנָה. וְאִם אָמַר עַל מְנָת שֶׁאֲנִי תַּנָּאָה צָרִיךְ לִהְיוֹת יוֹדֵעַ לִקְרוֹת הַמִּשְׁנָה וְסַפְרָא וְסִפְרִי וְתוֹסֶפְתָּא שֶׁל רַבִּי חִיָּא:","עַל מְנָת שֶׁאֲנִי תַּלְמִיד אֵין אוֹמְרִין כְּבֶן עֲזַאי וּבֶן זוֹמָא אֶלָּא כָּל שֶׁשּׁוֹאֲלִין אוֹתוֹ דָּבָר אֶחָד בְּתַלְמוּדוֹ וְאוֹמְרוֹ וַאֲפִלּוּ בְּהִלְכוֹת הֶחָג שֶׁמְּלַמְּדִין אוֹתָן בָּרַבִּים מִדְּבָרִים הַקַּלִּים סָמוּךְ לֶחָג כְּדֵי שֶׁיִּהְיוּ כָּל הָעָם בְּקִיאִין בָּהֶן. עַל מְנָת שֶׁאֲנִי חָכָם אֵין אוֹמְרִין כְּרַבִּי עֲקִיבָא וַחֲבֵרָיו אֶלָּא כָּל שֶׁשּׁוֹאֲלִין אוֹתוֹ בְּכָל מָקוֹם דְּבַר חָכְמָה וְאוֹמֵר. עַל מְנָת שֶׁאֲנִי גִּבּוֹר אֵין אוֹמְרִין כְּאַבְנֵר בֶּן נֵר וּכְיוֹאָב אֶלָּא כָּל שֶׁחֲבֵרָיו מִתְיָרְאִים מִמֶּנּוּ מִפְּנֵי גְּבוּרָתוֹ. עַל מְנָת שֶׁאֲנִי עָשִׁיר אֵין אוֹמְרִין [כְּרַבִּי אֶלְעָזָר בֶּן חַרְסוֹם] וּכְרַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אֶלָּא כָּל שֶׁבְּנֵי עִירוֹ מְכַבְּדִין אוֹתוֹ מִפְּנֵי עָשְׁרוֹ. עַל מְנָת שֶׁאֲנִי צַדִּיק אֲפִלּוּ רָשָׁע גָּמוּר הֲרֵי זוֹ מְקֻדֶּשֶׁת מִסָּפֵק שֶׁמָּא הִרְהֵר תְּשׁוּבָה בְּלִבּוֹ. עַל מְנָת שֶׁאֲנִי רָשָׁע אֲפִלּוּ צַדִּיק גָּמוּר הֲרֵי זוֹ מְקֻדֶּשֶׁת מִסָּפֵק שֶׁמָּא הִרְהֵר בְּעַכּוּ\"ם בְּלִבּוֹ שֶׁעֲוֹן עַכּוּ\"ם גָּדוֹל הוּא וּמִשֶּׁיְּהַרְהֵר לַעֲבֹד בְּלִבּוֹ נַעֲשֶׂה רָשָׁע שֶׁנֶּאֱמַר (דברים יא טז) \"פֶּן יִפְתֶּה לְבַבְכֶם\". וְכָתוּב (יחזקאל יד ה) \"לְמַעַן תְּפשֹׁ אֶת בֵּית יִשְׂרָאֵל בְּלִבָּם\":","הַמְקַדֵּשׁ אֶת הָאִשָּׁה וְאָמַר הָיִיתִי סָבוּר שֶׁהִיא כֹּהֶנֶת וַהֲרֵי הִיא לְוִיָּה. לְוִיָּה וַהֲרֵי הִיא כֹּהֶנֶת. עֲנִיָּה וַהֲרֵי הִיא עֲשִׁירָה. עֲשִׁירָה וַהֲרֵי הִיא עֲנִיָּה. הֲרֵי זוֹ מְקֻדֶּשֶׁת מִפְּנֵי שֶׁלֹּא הִטְעַתּוּ. וְכֵן הִיא שֶׁאָמְרָה סְבוּרָה הָיִיתִי שֶׁהוּא כֹּהֵן וַהֲרֵי הוּא לֵוִי. לֵוִי וַהֲרֵי הוּא כֹּהֵן. עָשִׁיר וַהֲרֵי הוּא עָנִי. עָנִי וַהֲרֵי הוּא עָשִׁיר. הֲרֵי זוֹ מְקֻדֶּשֶׁת מִפְּנֵי שֶׁלֹּא הִטְעָה אוֹתָהּ:"],"Mishneh Torah, Mourning 6":["מִדִבְרֵי סוֹפְרִים שֶׁיִּהְיֶה הָאָבֵל נוֹהֵג בְּמִקְצָת דִּבְרֵי אֲבֵלוּת כָּל שְׁלֹשִׁים יוֹם. וּמִנַּיִן סָמְכוּ חֲכָמִים לִשְׁלֹשִׁים יוֹם. שֶׁנֶּאֱמַר (דברים כא יג) \"וּבָכְתָה אֶת אָבִיהָ וְאֶת אִמָּהּ יֶרַח יָמִים\". מִכְלַל שֶׁהָאָבֵל מִצְטַעֵר כָּל שְׁלֹשִׁים יוֹם:","וְאֵלּוּ דְּבָרִים שֶׁהָאָבֵל אָסוּר בָּהֶן כָּל שְׁלֹשִׁים יוֹם. אָסוּר בְּתִסְפֹּרֶת. וּבְגִהוּץ. וּבְנִשּׂוּאִין. וּבְשִׂמְחַת מֵרֵעוּת. וְלֵילֵךְ בִּסְחוֹרָה מִמְּדִינָה לִמְדִינָה. הַכּל חֲמִשָּׁה דְּבָרִים:","בְּתִסְפֹּרֶת כֵּיצַד. כְּשֵׁם שֶׁאָסוּר לְסַפֵּר כָּל שְׂעַר גּוּפוֹ. אוֹ לְגַלֵּחַ שְׂפָמוֹ. אוֹ לָקֹץ צִפָּרְנָיו בִּכְלִי כָּל שִׁבְעָה. כָּךְ אָסוּר כָּל שְׁלֹשִׁים יוֹם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִישׁ. אֲבָל בְּאִשָּׁה מֻתֶּרֶת בִּנְטִילַת שֵׂעָר לְאַחַר שִׁבְעָה וְהָאִישׁ עַד שְׁלֹשִׁים יוֹם. וְעַל אָבִיו וְעַל אִמּוֹ חַיָּב לְגַדֵּל שְׂעָרוֹ עַד שֶׁיִּשְׁלַח פֶּרַע אוֹ עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו:","וְכֵן אָסוּר לִלְבּשׁ כֵּלִים לְבָנִים חֲדָשִׁים וּמְגֹהָצִין כָּל שְׁלֹשִׁים יוֹם. אֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה. הָיוּ צְבוּעִין וּמְגֹהָצִין מֻתָּרִין. וְכֵן אִם לֹא הָיוּ חֲדָשִׁים אַף עַל פִּי שֶׁהֵן לְבָנִים וּמְגֹהָצִין מֻתָּרִין. וּכְלֵי פִּשְׁתָּן אֵין בָּהֶן מִשּׁוּם גִּהוּץ. וּלְאַחַר שְׁלֹשִׁים יוֹם מֻתָּר בְּגִהוּץ אֲפִלּוּ עַל אָבִיו וְעַל אִמּוֹ:","בְּנִשּׂוּאִין כֵּיצַד. אָסוּר לִשָּׂא אִשָּׁה כָּל שְׁלֹשִׁים יוֹם. וּמֻתָּר לְאָרְשָׂהּ אֲפִלּוּ בְּיוֹם הַמִּיתָה. וּמִי שֶׁמֵּתָה אִשְׁתּוֹ אִם כְּבָר קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה וְיֵשׁ לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ וְאֵין לוֹ בָּנִים קְטַנִּים הֲרֵי זֶה אָסוּר לִשָּׂא אִשָּׁה אַחֶרֶת עַד שֶׁיַּעַבְרוּ עָלָיו שְׁלֹשָׁה רְגָלִים. אֲבָל מִי שֶׁלֹּא קִיֵּם מִצְוַת פְּרִיָּה וּרְבִיָּה אוֹ שֶׁקִּיֵּם וְיֵשׁ לוֹ בָּנִים קְטַנִּים אוֹ שֶׁאֵין לוֹ מִי שֶׁיְּשַׁמְּשֶׁנּוּ הֲרֵי זֶה מֻתָּר לְאָרְשָׂהּ וְלִכְנֹס מִיָּד. וְאָסוּר לוֹ לָבוֹא עָלֶיהָ עַד שְׁלֹשִׁים יוֹם. וְכֵן הָאִשָּׁה שֶׁהָיְתָה אֲבֵלָה לֹא תִּבָּעֵל עַד שְׁלֹשִׁים יוֹם:","שִׂמְחַת מֵרֵעוּת שֶׁהָיָה חַיָּב לִפְרֹעַ אוֹתָהּ מִיָּד. מֻתָּר לַעֲשׂוֹתָהּ מִיָּד לְאַחַר שִׁבְעָה. אֲבָל אִם אֵינוֹ חַיָּב לְפָרְעָהּ אָסוּר לְהִכָּנֵס לָהּ עַד שְׁלֹשִׁים יוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר כָּל מֵתִים. אֲבָל עַל אָבִיו וְעַל אִמּוֹ בֵּין כָּךְ וּבֵין כָּךְ לֹא יִכָּנֵס לְשִׂמְחַת מֵרֵעוּת עַד י\"ב חֹדֶשׁ:","עַל כָּל הַמֵּתִים כֻּלָּן מֻתָּר לֵילֵךְ בִּסְחוֹרָה לְאַחַר שְׁלֹשִׁים. עַל אָבִיו וְעַל אִמּוֹ עַד שֶׁיִּגְעֲרוּ בּוֹ חֲבֵרָיו וְיֹאמְרוּ לוֹ לֵךְ עִמָּנוּ:","עַל כָּל הַמֵּתִים כֻּלָּן רָצָה מְמַעֵט בְּעִסְקוֹ רָצָה אֵינוֹ מְמַעֵט. עַל אָבִיו וְעַל אִמּוֹ מְמַעֵט בְּעִסְקוֹ:","הַהוֹלֵךְ מִמָּקוֹם לְמָקוֹם אִם יָכוֹל לְמַעֵט בְּעִסְקוֹ יְמַעֵט וְאִם לָאו יִקְנֶה צָרְכֵי הַדֶּרֶךְ וּדְבָרִים שֶׁיֵּשׁ בָּהֶן חַיֵּי נֶפֶשׁ:","מִי שֶׁהָיָה בַּעְלָהּ צָלוּב בָּעִיר אוֹ אִשְׁתּוֹ צְלוּבָה אוֹ אָבִיו וְאִמּוֹ. אָסוּר לוֹ לִשְׁכֹּן בְּאוֹתָהּ הָעִיר עַד שֶׁיִּכְלֶה הַבָּשָׂר. וְאִם הָיְתָה עִיר גְּדוֹלָה כְּאַנְטוֹכְיָא יֵשׁ לוֹ לִשְׁכֹּן בַּצַּד הָאַחֵר שֶׁאֵינָן צְלוּבִין בּוֹ:","יוֹם שְׁבִיעִי מִקְצָתוֹ כְּכֻלּוֹ וְהוּא עוֹלֶה לְכָאן וּלְכָאן. וּלְפִיכָךְ מֻתָּר לְכַבֵּס וְלִרְחֹץ וְלַעֲשׂוֹת שְׁאָר הַדְּבָרִים בְּיוֹם שְׁבִיעִי. וְכֵן יוֹם שְׁלֹשִׁים מִקְצָתוֹ כְּכֻלּוֹ וּמֻתָּר לְסַפֵּר וּלְגַהֵץ בְּיוֹם שְׁלֹשִׁים:","מִי שֶׁתְּכָפוּהוּ אֲבָלָיו וְהִכְבִּיד שְׂעָרוֹ מֵקֵל בְּתַעַר לֹא בְּמִסְפָּרַיִם. וּמְכַבֵּס כְּסוּתוֹ בְּמַיִם אֲבָל לֹא בְּנֶתֶר וְלֹא בְּחוֹל. וְרוֹחֵץ כָּל גּוּפוֹ בְּצוֹנֵן אֲבָל לֹא בְּחַמִּין. וְכֵן מִי שֶׁתְּכָפוּהוּ אֲבָלָיו וּבָא מִמְּדִינַת הַיָּם וּמִבֵּית הַשִּׁבְיָה. אוֹ שֶׁיָּצָא מִבֵּית הָאֲסוּרִים. אוֹ שֶׁהָיָה מְנֻדֶּה וְהֻתַּר. אוֹ שֶׁהָיָה מֻדָּר וְנִשְׁאַל עַל נִדְרוֹ וְהֻתַּר. וְכָל הַיּוֹצֵא מִטֻּמְאָה לְטָהֳרָה. הֲרֵי אֵלּוּ מְגַלְּחִין בִּימֵי אֶבְלָם הוֹאִיל וּתְכָפָם אֵבֶל אַחַר אֵבֶל וְלֹא מָצְאוּ פְּנַאי:"],"Mishneh Torah, Murderer and the Preservation of Life 5":["כָּל הַהוֹרֵג בִּשְׁגָגָה גּוֹלֶה מִמְּדִינָה שֶׁהָרַג בָּהּ לְעָרֵי מִקְלָט וּמִצְוַת עֲשֵׂה לְהַגְלוֹתוֹ שֶׁנֶּאֱמַר (במדבר לה כה) \"וְיָשַׁב בָּהּ עַד מוֹת הַכֹּהֵן הַגָּדל\". וְהֻזְהֲרוּ בֵּית דִּין שֶׁלֹּא יִקְחוּ כֹּפֶר מִן הָרוֹצֵחַ בִּשְׁגָגָה כְּדֵי לֵישֵׁב בְּעִירוֹ שֶׁנֶּאֱמַר (במדבר לה לב) \"וְלֹא תִקְחוּ כֹפֶר לָנוּס אֶל עִיר מִקְלָטוֹ\":","אֵין הָרוֹצֵחַ בִּשְׁגָגָה גּוֹלֶה אֶלָּא אִם כֵּן מֵת הַנֶּהֱרָג מִיָּד. אֲבָל אִם חָבַל בּוֹ בִּשְׁגָגָה אַף עַל פִּי שֶׁאֲמָדוּהוּ לְמִיתָה וְחָלָה וּמֵת אֵינוֹ גּוֹלֶה שֶׁמָּא הוּא קֵרֵב אֶת מִיתַת עַצְמוֹ אוֹ הָרוּחַ נִכְנְסָה בַּחֲבּוּרָה וַהֲרָגָתְהוּ. אֲפִלּוּ שָׁחַט בּוֹ כָּל שְׁנֵי הַסִּימָנִים וְעָמַד מְעַט אֵינוֹ גּוֹלֶה עַל יָדוֹ. לְפִיכָךְ אִם לֹא פִּרְכֵּס כְּלָל אוֹ שֶׁשְּׁחָטוֹ בְּמָקוֹם שֶׁאֵין הָרוּחַ מְנַשֶּׁבֶת בּוֹ כְּגוֹן בַּיִת סָתוּם שֶׁל שַׁיִשׁ הֲרֵי זֶה גּוֹלֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יִשְׂרָאֵל שֶׁהָרַג בִּשְׁגָגָה אֶת הָעֶבֶד (אוֹ אֶת גֵּר תּוֹשָׁב) גּוֹלֶה. וְכֵן הָעֶבֶד שֶׁהָרַג בִּשְׁגָגָה אֶת יִשְׂרָאֵל אוֹ אֶת גֵּר תּוֹשָׁב וְכֵן גֵּר תּוֹשָׁב שֶׁהָרַג אֶת גֵּר תּוֹשָׁב אוֹ אֶת הָעֶבֶד בִּשְׁגָגָה גּוֹלֶה שֶׁנֶּאֱמַר (במדבר לה טו) \"לִבְנֵי יִשְׂרָאֵל וְלַגֵּר וְלַתּוֹשָׁב בְּתוֹכָם\":","גֵּר תּוֹשָׁב שֶׁהָרַג אֶת יִשְׂרָאֵל בִּשְׁגָגָה אַף עַל פִּי שֶׁהוּא שָׁגַג הֲרֵי זֶה נֶהֱרָג. אָדָם מוּעָד לְעוֹלָם. וְכֵן גֵּר תּוֹשָׁב שֶׁהָרַג גֵּר תּוֹשָׁב מִפְּנֵי שֶׁעָלָה עַל דַּעְתּוֹ שֶׁמֻּתָּר לְהָרְגוֹ הֲרֵי זֶה קָרוֹב לְמֵזִיד וְנֶהֱרָג עָלָיו הוֹאִיל וְנִתְכַּוֵּן לְהָרְגוֹ. וְעַכּוּ\"ם שֶׁהָרַג אֶת הָעַכּוּ\"ם בִּשְׁגָגָה אֵין עָרֵי מִקְלָט קוֹלְטוֹת אוֹתוֹ שֶׁנֶּאֱמַר (במדבר לה טו) \"לִבְנֵי יִשְׂרָאֵל\":","הַבֵּן שֶׁהָרַג אֶת אָבִיו בִּשְׁגָגָה גּוֹלֶה וְכֵן הָאָב שֶׁהָרַג אֶת בְּנוֹ גּוֹלֶה עַל יָדוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהֲרָגוֹ שֶׁלֹּא בִּשְׁעַת לִמּוּד. אוֹ שֶׁהָיָה מְלַמְּדוֹ אֻמָּנוּת אַחֶרֶת שֶׁאֵינוֹ צָרִיךְ לָהּ. אֲבָל אִם יִסֵּר בְּנוֹ כְּדֵי לְלַמְּדוֹ תּוֹרָה אוֹ חָכְמָה אוֹ אֻמָּנוּת וּמֵת פָּטוּר:","וְכֵן הָרַב הַמַּכֶּה אֶת תַּלְמִידוֹ אוֹ שְׁלִיחַ בֵּית דִּין שֶׁהִכָּה אֶת בַּעַל דִּין הַנִּמְנָע מִלָּבוֹא לַדִּין וֶהֱמִיתוֹ בִּשְׁגָגָה פָּטוּר מִן הַגָּלוּת שֶׁנֶּאֱמַר (דברים יט ה) \"לַחְטֹב עֵצִים\". לְדִבְרֵי הָרְשׁוּת. יָצָא הָאָב הַמַּכֶּה אֶת בְּנוֹ וְהָרַב הָרוֹדֶה אֶת תַּלְמִידוֹ וּשְׁלִיחַ בֵּית דִּין שֶׁהֲרֵי שָׁגְגוּ וְהָרְגוּ בִּשְׁעַת עֲשׂוֹת הַמִּצְוֹת:","בַּתְּחִלָּה אֶחָד שׁוֹגֵג וְאֶחָד מֵזִיד מַקְדִּימִין לְעָרֵי מִקְלָט וּבֵית דִּין שֶׁל אוֹתָהּ הָעִיר שֶׁהָרַג בָּהּ שׁוֹלְחִין וּמְבִיאִין אוֹתוֹ מִשָּׁם וְדָנִין שֶׁנֶּאֱמַר (דברים יט יב) \"וְשָׁלְחוּ זִקְנֵי עִירוֹ וְלָקְחוּ אֹתוֹ מִשָּׁם\". מִי שֶׁנִּתְחַיֵּב מִיתָה מְמִיתִין אוֹתוֹ שֶׁנֶּאֱמַר (דברים יט יב) \"וְנָתְנוּ אֹתוֹ בְּיַד גֹּאֵל הַדָּם\". מִי שֶׁנִּפְטַר פּוֹטְרִים אוֹתוֹ שֶׁנֶּאֱמַר (במדבר לה כה) \"וְהִצִּילוּ הָעֵדָה אֶת הָרֹצֵחַ מִיַּד גֹּאֵל הַדָּם\". מִי שֶׁנִּתְחַיֵּב גָּלוּת מַחֲזִירִין אוֹתוֹ לִמְקוֹמוֹ שֶׁנֶּאֱמַר (במדבר לה כה) \"וְהֵשִׁיבוּ אֹתוֹ הָעֵדָה אֶל עִיר מִקְלָטוֹ\":","כְּשֶׁמְּשִׁיבִין אוֹתוֹ מוֹסְרִין לוֹ שְׁנֵי תַּלְמִידֵי חֲכָמִים שֶׁמָּא יַהַרְגֵנוּ גּוֹאֵל הַדָּם בַּדֶּרֶךְ. וְאוֹמֵר לָהֶם אַל תִּנְהֲגוּ בּוֹ מִנְהַג שׁוֹפְכֵי דָּמִים, בְּשׁוֹגֵג בָּא מַעֲשֶׂה לְיָדוֹ:","רוֹצֵחַ בִּשְׁגָגָה שֶׁהֲרָגוֹ גּוֹאֵל הַדָּם חוּץ לִתְחוּם עִיר מִקְלָטוֹ פָּטוּר שֶׁנֶּאֱמַר (דברים יט ו) \"וְלוֹ אֵין מִשְׁפַּט מָוֶת\":","אֶחָד הַהוֹרְגוֹ בַּדֶּרֶךְ קֹדֶם שֶׁיִּכָּנֵס לְעִיר מִקְלָט אוֹ שֶׁהֲרָגוֹ בַּחֲזִירָתוֹ עִם הַשְּׁנַיִם שֶׁשּׁוֹמְרִין אוֹתוֹ. נִכְנַס לְעִיר מִקְלָטוֹ וְיָצָא חוּץ לִתְחוּמָהּ בְּזָדוֹן הֲרֵי זֶה הִתִּיר עַצְמוֹ לְמִיתָה וּרְשׁוּת לְגוֹאֵל הַדָּם לְהָרְגוֹ. וְאִם הֲרָגוֹ כָּל אָדָם אֵין חַיָּבִין עָלָיו שֶׁנֶּאֱמַר (במדבר לה כז) \"אֵין לוֹ דָּם\":","יָצָא חוּץ לִתְחוּם עִיר מִקְלָטוֹ בִּשְׁגָגָה כָּל הַהוֹרְגוֹ בֵּין גּוֹאֵל הַדָּם בֵּין שְׁאָר אָדָם גּוֹלֶה עַל יָדוֹ. הֲרָגוֹ בְּתוֹךְ תְּחוּם עִיר מִקְלָטוֹ אֲפִלּוּ גּוֹאֵל הַדָּם הֲרֵי זֶה נֶהֱרָג עָלָיו:","הַמִּזְבֵּחַ קוֹלֵט שֶׁנֶּאֱמַר בְּהוֹרֵג בְּזָדוֹן (שמות כא יד) \"מֵעִם מִזְבְּחִי תִּקָּחֶנּוּ לָמוּת\" מִכְּלָל שֶׁהַהוֹרֵג בִּשְׁגָגָה אֵינוֹ נֶהֱרָג בַּמִּזְבֵּחַ לְפִיכָךְ הַהוֹרֵג בִּשְׁגָגָה וּקְלָטוֹ מִזְבֵּחַ וַהֲרָגוֹ שָׁם גּוֹאֵל הַדָּם הֲרֵי זֶה נֶהֱרָג עָלָיו כְּמִי שֶׁהֲרָגוֹ בְּתוֹךְ עִיר מִקְלָט:","אֵין קוֹלֵט אֶלָּא גַּגּוֹ שֶׁל מִזְבֵּחַ בֵּית הָעוֹלָמִים בִּלְבַד וְאֵין קוֹלֵט אֶלָּא כֹּהֵן וַעֲבוֹדָה בְּיָדוֹ. אֲבָל זָר אוֹ כֹּהֵן שֶׁאֵינוֹ עוֹבֵד בְּשָׁעָה שֶׁנֶּהֱרָג אוֹ שֶׁהָיָה עוֹבֵד וְלֹא הָיָה עַל גַּגּוֹ שֶׁל מִזְבֵּחַ אֶלָּא סָמוּךְ לוֹ אוֹ אוֹחֵז בְּקַרְנוֹתָיו אֵינוֹ נִקְלָט:","וְכֵן מִי שֶׁקְּלָטוֹ הַמִּזְבֵּחַ אֵין מַנִּיחִין אוֹתוֹ שָׁם אֶלָּא מוֹסְרִין [לוֹ] שׁוֹמְרִין וּמַגְלִין אוֹתוֹ לְעִיר מִקְלָטוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְחֻיַּב גָּלוּת. אֲבָל מִי שֶׁפָּחַד מִן הַמֶּלֶךְ שֶׁלֹּא יַהַרְגֶנּוּ בְּדִין הַמַּלְכוּת אוֹ מִבֵּית דִּין שֶׁלֹּא יַהַרְגוּהוּ בְּהוֹרָאַת שָׁעָה וּבָרַח לַמִּזְבֵּחַ וְנִסְמַךְ לוֹ וַאֲפִלּוּ הָיָה זָר הֲרֵי זֶה נִצָּל וְאֵין לוֹקְחִין אוֹתוֹ מֵעִם הַמִּזְבֵּחַ לָמוּת לְעוֹלָם. אֶלָּא אִם כֵּן נִתְחַיֵּב מִיתַת בֵּית דִּין בְּעֵדוּת גְּמוּרָה וְהַתְרָאָה כִּשְׁאָר כָּל הֲרוּגֵי בֵּית דִּין תָּמִיד:"],"Mishneh Torah, Nazariteship 7":["יֵשׁ טֻמְאוֹת מִן הַמֵּת שֶׁאֵין הַנָּזִיר מְגַלֵּחַ עֲלֵיהֶן וְלֹא סוֹתֵר אֶת הַקּוֹדְמִין וְאַף עַל פִּי שֶׁנִּטְמָא בָּהֶן טֻמְאַת שִׁבְעָה. לְפִי שֶׁלֹּא נֶאֱמַר בּוֹ וְכִי יִטַּמָּא לְנֶפֶשׁ אֶלָּא (במדבר ו ט) \"וְכִי יָמוּת מֵת עָלָיו\" עַד שֶׁיִּטָּמֵא מִטֻּמְאוֹת שֶׁהֵן מֵעַצְמוֹ שֶׁל מֵת וְאַחַר כָּךְ יָבִיא קָרְבְּנוֹת טֻמְאָה וִיגַלֵּחַ תִּגְלַחַת טֻמְאָה וְיִפְּלוּ כָּל הַיָּמִים הָרִאשׁוֹנִים:","וְאֵלּוּ טֻמְאוֹת מִן הַמֵּת שֶׁהַנָּזִיר מְגַלֵּחַ עֲלֵיהֶן. עַל הַנֵּפֶל וַאֲפִלּוּ לֹא נִתְקַשְּׁרוּ אֵיבָרָיו בְּגִידִין. וְעַל כְּזַיִת מִבְּשַׂר הַמֵּת. וְעַל כְּזַיִת נֶצֶל. וְעַל עֲצָמוֹת שֶׁהֵן רֹב מִנְיַן הָעֲצָמוֹת אַף עַל פִּי שֶׁאֵין בָּהֶן רֹבַע הַקַּב. וְעַל עֲצָמוֹת שֶׁהֵן רֹב בִּנְיָנוֹ שֶׁל מֵת וְאַף עַל פִּי שֶׁאֵין בָּהֶן רֹבַע הַקַּב. וְעַל חֲצִי קַב עֲצָמוֹת אַף עַל פִּי שֶׁאֵין בָּהֶן לֹא רֹב בִּנְיָנוֹ וְלֹא רֹב מִנְיָנוֹ. וְכָל הָעֲצָמוֹת יִהְיוּ מִשֶּׁל מֵת אֶחָד וְלֹא מִשְּׁנֵי מֵתִים. וְעַל הַשִּׁדְרָה הַבָּאָה מִמֵּת אֶחָד. וְעַל הַגֻּלְגּלֶת שֶׁל מֵת אֶחָד. וְעַל אֵיבָר מִן הַמֵּת הַבָּא מִמֵּת אֶחָד. וְעַל אֵיבָר מִן הַחַי מֵאָדָם אֶחָד. שֶׁיֵּשׁ עֲלֵיהֶן בָּשָׂר שֶׁרָאוּי לַעֲלוֹת בּוֹ אֲרוּכָה בְּחַי. וְעַל חֲצִי לוֹג דָּם הַבָּא מִמֵּת אֶחָד. וְעַל מְלֹא חָפְנַיִם רֶקֶב הַמֵּת. אֵי זֶהוּ נֶצֶל זֶה בְּשַׂר הַמֵּת שֶׁנִּמּוֹחַ וְנַעֲשָׂה לֵחָה סְרוּחָה:","וְאֵין רֶקֶב הַמֵּת מְטַמֵּא עַד שֶׁיִּקָּבֵר עֵרוֹם בְּאָרוֹן שֶׁל שַׁיִשׁ וְיִהְיֶה כֻּלּוֹ שָׁלֵם. חָסֵר מִמֶּנּוּ אֵיבָר אוֹ שֶׁנִּקְבַּר בִּכְסוּתוֹ אוֹ בְּאָרוֹן שֶׁל עֵץ אוֹ בְּשֶׁל מַתֶּכֶת אֵין לוֹ רֶקֶב. וְלֹא אָמְרוּ רֶקֶב אֶלָּא לְמֵת בִּלְבַד לְהוֹצִיא הָרוּג שֶׁהֲרֵי חָסֵר דָּמוֹ:","קָבְרוּ שְׁנֵי מֵתִים כְּאֶחָד. אוֹ שֶׁגָּזְזוּ שְׂעָרוֹ אוֹ צִפָּרְנָיו וּקְבָרוּם עִמּוֹ. אוֹ אִשָּׁה עֻבָּרָה שֶׁמֵּתָה וְנִקְבְּרָה וְעֻבָּרָהּ בְּמֵעֶיהָ אֵין הָרֶקֶב שֶׁלָּהֶם מְטַמֵּא. וְכֵן אִם טָחַן הַמֵּת עַד שֶׁנַּעֲשָׂה רֶקֶב אֵינוֹ מְטַמֵּא עַד שֶׁיַּרְקִיב מֵאֵלָיו. טָחַן אֶת הַמֵּת וְהִנִּיחַ עֲפָרוֹ עַד שֶׁהִרְקִיב כֻּלּוֹ. אוֹ [שֶׁהִרְקִיב] מִקְצָתוֹ כְּשֶׁהוּא חַי וּמֵת וְהִרְקִיב הַכּל הֲרֵי זֶה סָפֵק וְאִם נִטְמָא לְרֶקֶב זֶה הֲרֵי זֶה סְפֵק טָמֵא. וְכֵן אִם נִטְמָא בְּרֹבַע עֲצָמוֹת הַבָּאִין מֵהַשִּׁדְרָה אוֹ מִן הַגֻּלְגּלֶת בְּאָהֳלָן הֲרֵי זֶה סְפֵק טָמֵא:","כָּל אֵלּוּ הַשְּׁתֵּים עֶשְׂרֵה טֻמְאוֹת שֶׁמָּנִינוּ אִם נָגַע נָזִיר בְּאַחַת מֵהֶן אוֹ נְשָׂאָהּ אוֹ הֶאֱהִיל הַנָּזִיר עָלֶיהָ אוֹ הֶאֱהִיל הַטֻּמְאָה עַל הַנָּזִיר אוֹ הָיָה הַנָּזִיר וְאַחַת מִטֻּמְאוֹת אֵלּוּ בְּאֹהֶל אֶחָד הֲרֵי זֶה מְגַלֵּחַ תִּגְלַחַת טֻמְאָה וּמֵבִיא קָרְבַּן טֻמְאָה וְסוֹתֵר אֶת הַכּל. חוּץ מִן הָרֶקֶב שֶׁאֵינוֹ מְטַמֵּא בְּמַגָּע שֶׁאִי אֶפְשָׁר שֶׁיִּגַּע בְּכֻלּוֹ שֶׁהֲרֵי אֵינוֹ גּוּף אֶחָד. אֲבָל אִם נְשָׂאוֹ אוֹ נִטְמָא בְּאָהֳלוֹ מְגַלֵּחַ:","וְכֵן נָזִיר שֶׁנָּגַע בְּעֶצֶם הַמֵּת אֲפִלּוּ עֶצֶם כִּשְׂעוֹרָה אוֹ נְשָׂאוֹ הֲרֵי זֶה מְגַלֵּחַ עָלָיו וּמֵבִיא קָרְבְּנוֹת טֻמְאָה וְסוֹתֵר אֶת הַקּוֹדְמִים. וְאֵין עֶצֶם כִּשְׂעוֹרָה מְטַמֵּא בְּאֹהֶל. אֲבָל נִטְמָא בְּאַחַת מִשְּׁנֵים עָשָׂר דְּבָרִים הַלָּלוּ. בְּגוּשׁ אֶרֶץ הָעַכּוּ\"ם אוֹ בְּשָׂדֶה שֶׁנֶּחְרַשׁ קֶבֶר בְּתוֹכָהּ שֶׁהֵן מְטַמְּאִין בְּמַגָּע וּבְמַשָּׂא. אוֹ שֶׁהֶאֱהִיל עָלָיו וְעַל הַשָּׂרִיגִים הַיּוֹצְאִים מִן הָאִילָנוֹת אוֹ הַפְּרָעוֹת הַיּוֹצְאוֹת מִן הַגָּדֵר אוֹ מִטָּה אוֹ גָּמָל וְכַיּוֹצֵא בּוֹ. אוֹ שֶׁנִּטְמָא בְּאֹהֶל רֹבַע עֲצָמוֹת שֶׁאֵין בָּהֶן לֹא רֹב בִּנְיָן וְלֹא רֹב מִנְיָן. אוֹ שֶׁנִּטְמָא בִּרְבִיעִית דָּם מִן הַמֵּת שֶׁהִיא מְטַמֵּא בְּמַגָּע וּבְמַשָּׂא וּבְאֹהֶל. אוֹ שֶׁנִּטְמָא בְּגוֹלֵל אוֹ בְּדוֹפֵק שֶׁהֵן מְטַמְּאִין בְּמַגָּע וּבְאֹהֶל. אוֹ שֶׁנִּטְמָא בְּאֵיבָר מִן הַחַי אוֹ בְּאֵיבָר מִן הַמֵּת שֶׁאֵין עֲלֵיהֶן בָּשָׂר כָּרָאוּי. הֲרֵי זֶה אֵינוֹ סוֹתֵר:","אַף עַל פִּי שֶׁבְּכָל אֵלּוּ הוּא טָמֵא טֻמְאַת שִׁבְעָה וּמַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי. אֵינוֹ מְגַלֵּחַ תִּגְלַחַת טֻמְאָה וְלֹא מֵבִיא קָרְבָּנוֹת וְלֹא סוֹתֵר אֶת הַקּוֹדְמִין. אֲבָל כָּל יְמֵי הַטֻּמְאָה אֵין עוֹלִין לוֹ מִמִּנְיַן יְמֵי נְזִירוּתוֹ:","נָגַע בְּאֹהֶל הַמֵּת אוֹ בְּכֵלִים הַנּוֹגְעִים בְּמֵת אֵינוֹ מַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי. וְיֵרָאֶה לִי שֶׁדִּין זֶה מְיֻחָד בְּנָזִיר. אֲבָל כָּל אָדָם שֶׁנִּטְמָא בִּכְלִי טֻמְאַת שִׁבְעָה יַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת טֻמְאַת מֵת. וְכֵן יֵרָאֶה לִי שֶׁזֶּה שֶׁאֵינוֹ מַזֶּה בַּשְּׁלִישִׁי וּבַשְּׁבִיעִי אִם נָגַע בְּכֵלִים כְּדֵי שֶׁיַּעֲלוּ לוֹ יְמֵי טֻמְאָתוֹ בְּכֵלִים מִמִּנְיַן יְמֵי נְזִירוּתוֹ:","נָזִיר שֶׁנִּצְטָרֵעַ וְהֻחְלַט כָּל יְמֵי חִלּוּטוֹ וְשִׁבְעַת יְמֵי סְפִירוֹ שֶׁסּוֹפֵר אַחַר שֶׁיִּטְהַר לְצָרַעְתּוֹ בֵּין תִּגְלַחַת רִאשׁוֹנָה לִשְׁנִיָּה אֵין עוֹלִין לוֹ מִימֵי נְזִירוּתוֹ. אֲבָל יְמֵי הֶסְגֵּר עוֹלִין לוֹ. וְכֵן אִם זָב בְּשָׂרוֹ בֵּין אִישׁ בֵּין אִשָּׁה כָּל יְמֵי זִיבָתָן עוֹלִין לָהֶן אַף עַל פִּי שֶׁהֵן טְמֵאִין. וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי הוּא:","אֵין צָרִיךְ לוֹמַר שֶׁאִם נִטְמָא הַנָּזִיר בִּשְׁאָר טֻמְאוֹת שֶׁיְּמֵי טֻמְאָתוֹ עוֹלִין לוֹ וְאֵינוֹ סוֹתֵר כְּלוּם. נִטְמָא בְּמֵת בְּתוֹךְ יְמֵי צָרַעְתּוֹ סוֹתֵר אֶת כָּל הַקּוֹדְמִין שֶׁהֲרֵי בִּנְזִירוּתוֹ עוֹמֵד וְאַף עַל פִּי שֶׁהוּא טָמֵא:","הַנָּזִיר מֻתָּר בְּטֻמְאַת מֵת מִצְוָה וּבְתִגְלַחַת מִצְוָה. וְאָסוּר בְּיֵין הַמִּצְוָה כְּיֵין הָרְשׁוּת. כֵּיצַד. מִי שֶׁנִּשְׁבַּע שֶׁיִּשְׁתֶּה הַיּוֹם יַיִן שֶׁהֲרֵי מִצְוָה עָלָיו לִשְׁתּוֹת וְאַחַר כָּךְ נָדַר בְּנָזִיר חָלָה נְזִירוּת עַל הַשְּׁבוּעָה וְאָסוּר בְּיַיִן. וְאֵין צָרִיךְ לוֹמַר שֶׁהוּא אָסוּר בְּיֵין קִדּוּשׁ וְהַבְדָּלָה שֶׁאֵינוֹ אֶלָּא מִדִּבְרֵי סוֹפְרִים:","וְכֵיצַד הוּא מֻתָּר בְּטֻמְאַת מֵת מִצְוָה. הָיָה מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַע בְּמֵת שֶׁאֵין שָׁם מִי שֶׁיִּקְבְּרֶנּוּ הֲרֵי זֶה מִטַּמֵּא לוֹ וְקוֹבְרוֹ. וּדְבָרִים אֵלּוּ דִּבְרֵי קַבָּלָה הֵן:","נָזִיר וְכֹהֵן שֶׁפָּגְעוּ בְּמֵת מִצְוָה יִטַּמֵּא נָזִיר אַף עַל פִּי שֶׁהוּא סוֹתֵר הַיָּמִים הָרִאשׁוֹנִים וּמֵבִיא קָרְבַּן טֻמְאָה. וְאַל יִטַּמֵּא כֹּהֵן. שֶׁזֶּה קְדֻשָּׁתוֹ קְדֻשַּׁת שָׁעָה וַאֲפִלּוּ הָיָה נְזִיר עוֹלָם. וְהַכֹּהֵן קְדֻשָּׁתוֹ קְדֻשַּׁת עוֹלָם:","פָּגְעוּ בּוֹ שְׁנֵי נְזִירִים אֶחָד נָזִיר שְׁלֹשִׁים יוֹם וְאֶחָד נָזִיר מֵאָה יוֹם יִטַּמֵּא נְזִיר שְׁלֹשִׁים. הָיָה אֶחָד נָזִיר לִזְמַן קָצוּב וְהַשֵּׁנִי נְזִיר עוֹלָם יִטַּמֵּא הַנָּזִיר לִזְמַן קָצוּב. שֶׁנְּזִירוּת עוֹלָם קְדֻשָּׁתוֹ חֲמוּרָה מִזֶּה:","וְכֵיצַד הוּא מֻתָּר בְּתִגְלַחַת מִצְוָה. נָזִיר שֶׁנִּצְטָרֵעַ וְנִרְפָּא מִצָּרַעְתּוֹ בְּתוֹךְ יְמֵי נְזִירוּת הֲרֵי זֶה מְגַלֵּחַ כָּל שְׂעָרוֹ שֶׁהֲרֵי תִּגְלַחְתּוֹ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר בִּמְצֹרָע (ויקרא יד ח) \"וְגִלַּח אֶת כָּל שְׂעָרוֹ\" וְגוֹ'. וְכָל מָקוֹם שֶׁאַתָּה מוֹצֵא מִצְוַת עֲשֵׂה וְלֹא תַּעֲשֶׂה אִם יָכוֹל אַתָּה לְקַיֵּם אֶת שְׁנֵיהֶם מוּטָב וְאִם לָאו יָבוֹא עֲשֵׂה וְיִדְחֶה אֶת לֹא תַּעֲשֶׂה. וַהֲלֹא נָזִיר שֶׁגִּלֵּחַ בִּימֵי נִזְרוֹ עָבַר עַל לֹא תַּעֲשֶׂה וַעֲשֵׂה שֶׁנֶּאֱמַר (במדבר ו ה) \"קָדשׁ יִהְיֶה גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ\" וּבְכָל מָקוֹם אֵין עֲשֵׂה דּוֹחָה לֹא תַּעֲשֶׂה וַעֲשֵׂה וְלָמָּה דּוֹחֶה עֲשֵׂה שֶׁל תִּגְלַחַת הַנֶּגַע לִנְזִירוּת. מִפְּנֵי שֶׁכְּבָר נִטְמָא הַנָּזִיר בְּצָרַעַת וִימֵי חִלּוּטוֹ אֵין עוֹלִין לוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וַהֲרֵי אֵינוֹ קָדוֹשׁ בָּהֶן. וּבָטַל הָעֲשֵׂה מֵאֵלָיו וְלֹא נִשְׁאַר אֶלָּא לֹא תַּעֲשֶׂה שֶׁהוּא (במדבר ו ה) \"תַּעַר לֹא יַעֲבֹר עַל רֹאשׁוֹ\". וּלְפִיכָךְ בָּא עֲשֵׂה שֶׁל תִּגְלַחַת הַצָּרַעַת וְדָחָה אוֹתוֹ:"],"Mishneh Torah, Negative Mitzvot 107":["שלא לשנות את הקודשים מקרבן לקרבן, שנאמר בבכור \"לא יקדיש איש, אותו\" (ויקרא כז,כו); כלומר, לא יקדישנו לקרבן אחר."],"Mishneh Torah, Negative Mitzvot 118":["שלא להותיר מחגיגת ארבעה עשר ליום השלישי, שנאמר \"ולא ילין מן הבשר\" (דברים טז,ד); מפי השמועה למדו שבבשר חגיגת ארבעה עשר הכתוב מדבר, וזה שנאמר \"לבוקר\" (שם) לבוקרו של יום שני של פסח, שהוא שלישי לשחיטה."],"Mishneh Torah, Negative Mitzvot 129":["שלא יאכל אדם שנטמא קודשים, שנאמר \"והנפש אשר תאכל בשר, מזבח השלמים אשר לה', וטומאתו, עליו\" (ויקרא ז,כ)."],"Mishneh Torah, Negative Mitzvot 14":["שלא לישבע בעבודה זרה לעובדיה, ולא משביעין אותן בה, שנאמר \"ושם אלוהים אחרים לא תזכירו, לא יישמע על פיך\" (שמות כג,יג)."],"Mishneh Torah, Negative Mitzvot 150":["שלא לאכול מעשר שני בטומאה ואפילו בירושלים עד שייפדה, שנאמר \"לא ביערתי ממנו בטמא\" (דברים כו,יד)."],"Mishneh Torah, Negative Mitzvot 161":["שלא ייקח כוהן גדול אלמנה, שנאמר \"אלמנה וגרושה וחללה זונה, את אלה לא ייקח\" (ויקרא כא,יד)."],"Mishneh Torah, Negative Mitzvot 172":["שלא לאכול בהמה טמאה, שנאמר \"אך את זה, לא תאכלו, ממעלי הגרה\" (ויקרא יא,ד; דברים יד,ז)."],"Mishneh Torah, Negative Mitzvot 183":["שלא לאכול גיד הנשה, שנאמר \"על כן לא יאכלו בני ישראל את גיד הנשה\" (בראשית לב,לג)."],"Mishneh Torah, Negative Mitzvot 194":["שלא לשתות יין נסך, שנאמר \"אשר חלב זבחימו יאכלו, ישתו יין נסיכם\" (דברים לב,לח)."],"Mishneh Torah, Negative Mitzvot 204":["שלא יאכל ענבים יבשים, שנאמר \"ויבשים לא יאכל\" (במדבר ו,ג)."],"Mishneh Torah, Negative Mitzvot 215":["שלא לזרוע כלאי זרעים, שנאמר \"שדך לא תזרע כלאיים\" (ויקרא יט,יט)."],"Mishneh Torah, Negative Mitzvot 226":["שלא לאסוף פירות יובל כאסיפת שאר השנים, שנאמר בו \"ולא תבצרו את נזיריה\" (ויקרא כה,יא)."],"Mishneh Torah, Negative Mitzvot 237":["שלא להשית יד בין לווה ומלווה בריבית, ולא להיות ערב, ולא עד, ולא לכתוב שטר ביניהם, שנאמר \"לא תשימון עליו, נשך\" (שמות כב,כד)."],"Mishneh Torah, Negative Mitzvot 248":["שלא לכחש בממון חברו, שנאמר \"לא תכחשו\" (ויקרא יט,יא)."],"Mishneh Torah, Negative Mitzvot 259":["שלא לעבוד בעבד עברי בפרך, שנאמר \"לֹא תִרְדֶּה בּוֹ בְּפָרֶךְ\" (ויקרא כה, מג)."],"Mishneh Torah, Negative Mitzvot 27":["שלא להתנבא בשקר, שנאמר \"אשר יזיד לדבר דבר בשמי, את אשר לא ציוויתיו\" (דברים יח,כ)."],"Mishneh Torah, Negative Mitzvot 280":["שלא להטות משפט גרים ויתומים, שנאמר \"לֹא תַטֶּה מִשְׁפַּט גֵר יָתוֹם\" (דברים כד, יז)."],"Mishneh Torah, Negative Mitzvot 291":["שלא יורה העד בדין שהעיד בו בדיני נפשות, שנאמר \"וְעֵד אֶחָד לֹא יַעֲנֶה בְּנֶפֶשׁ\" (במדבר לה, ל)."],"Mishneh Torah, Negative Mitzvot 301":["שלא לרגל, שנאמר \"לא תלך רכיל בעמיך\" (ויקרא יט,טז)."],"Mishneh Torah, Negative Mitzvot 312":["שלא להמרות על פי בית דין, שנאמר \"לא תסור, מכל הדבר\" (ראה דברים יז,יא)."],"Mishneh Torah, Negative Mitzvot 323":["שלא לעשות מלאכה בראשון של פסח, שנאמר \"כל מלאכה, לא ייעשה בהם\" (שמות יב,טז)."],"Mishneh Torah, Negative Mitzvot 334":["שלא לגלות ערוות בת הבן, שנאמר \"ערוות בת בנך\" (ויקרא יח,י)."],"Mishneh Torah, Negative Mitzvot 345":["שלא לגלות ערוות אחות אישה, שנאמר \"ואישה אל אחותה, לא תיקח\" (ויקרא יח,יח)."],"Mishneh Torah, Negative Mitzvot 356":["שלא יחזיר המגרש גרושתו אחר שנישאת לאחר, שנאמר \"לא יוכל בעלה הראשון אשר שילחה לשוב לקחתה\" (דברים כד,ד)."],"Mishneh Torah, Negative Mitzvot 38":["שלא לשאול בחלום מן המתים, שנאמר \"ודורש אל המתים\" (דברים יח,יא)."],"Mishneh Torah, Negative Mitzvot 49":["שלא להחיות אדם משבעה עממים, שנאמר \"לא תחייה, כל נשמה\" (דברים כ,טז)."],"Mishneh Torah, Negative Mitzvot 6":["שלא לעבוד עבודה זרה בדברים שדרכה להיעבד בהם, שנאמר \"ולא תעבדם\" (שמות כ,ד; שמות כג,כד; דברים ה,ח)."],"Mishneh Torah, Negative Mitzvot 70":["שלא יעבוד בעל מום, שנאמר \"אֲשֶׁר יִהְיֶה בוֹ מוּם\" (ויקרא כא, יז)."],"Mishneh Torah, Negative Mitzvot 81":["שלא לכבות אש המזבח, שנאמר \"אש, תמיד תוקד על המזבח--לא תכבה\" (ויקרא ו,ו)."],"Mishneh Torah, Negative Mitzvot 92":["שלא לשחוט בעלי מומין לשם קרבן, שנאמר \"לא תקריבו אלה, לה'\" (ויקרא כב,כב)."],"Mishneh Torah, Neighbors 13":["הַנּוֹתֵן מַתָּנָה אֵין בָּהּ דִּין בֶּן הַמֵּצַר. הָיָה כָּתוּב בִּשְׁטַר מתָּנָה שֶׁאַחֲרָיוּת מַתָּנָה זוֹ עַל הַנּוֹתֵן יֵשׁ בָּהּ דִּין בֶּן הַמֵּצַר הוֹאִיל וְיֵשׁ בָּהּ אַחֲרָיוּת מְכִירָה הִיא וְלֹא כָּתַב מַתָּנָה אֶלָּא לְבַטֵּל זְכוּת בֶּן הַמֵּצַר. וְכַמָּה נוֹתֵן לוֹ. מַה שֶּׁהִיא שָׁוָה:","אָמַר הַלּוֹקֵחַ כֵּן הוּא וְהַעֲרָמָה עָשִׂינוּ וּמְכִירָה הִיא בְּכָךְ וְכָךְ קְנִיתִיהָ נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כְּדִין הַשְּׁלוּחִין. וְיֵרָאֶה לִי שֶׁצָּרִיךְ לִטְעֹן דָּמִים שֶׁהֵן רְאוּיִין אוֹ יֶתֶר מְעַט. אֲבָל אִם אָמַר עַל שְׁוֵה מֵאָה בְּמָאתַיִם קָנִיתִי אֵינוֹ נֶאֱמָן:","הָיָה כָּתוּב בִּשְׁטַר מַתָּנָה וְקִבַּלְתִּי עָלַי אַחֲרָיוּת מַתָּנָה זוֹ שֶׁאִם תֵּצֵא מִיָּדוֹ אֶתֵּן לוֹ מָאתַיִם נוֹתֵן לוֹ בֶּן הַמֵּצַר מָאתַיִם וְאַחַר כָּךְ מְסַלְּקוֹ וְאַף עַל פִּי שֶׁאֵינוֹ שָׁוֶה אֶלָּא מָנֶה:","הֶחְלִיף חָצֵר בְּחָצֵר אֵין בָּהּ דִּין בַּעַל הַמֵּצַר. הֶחְלִיף חָצֵר בִּבְהֵמָה אוֹ בְּמִטַּלְטְלִין רוֹאִין דְּמֵי אוֹתָהּ הַבְּהֵמָה אוֹ דְּמֵי אוֹתָם הַמִּטַּלְטְלִין וְנוֹתֵן לוֹ בֶּן הַמֵּצַר וּמְסַלְּקוֹ. וְאֵינוֹ יָכוֹל לוֹמַר לוֹ תֵּן לִי כַּמָּה שֶׁלָּקַחְתִּי בּוֹ שֶׁזֶּה הַעֲרָמָה הִיא וְאֵינָהּ מוֹעֶלֶת כְּלוּם:","מָכַר לוֹ קַרְקַע מְעַט בְּאֶמְצַע שָׂדֵהוּ וְאַחַר כָּךְ מָכַר לוֹ קַרְקַע בְּצַד אוֹתָהּ שָׂדֶה שֶׁבָּאֶמְצַע. רוֹאִין אִם אוֹתוֹ הַמְּעַט שֶׁמָּכַר לוֹ תְּחִלָּה הִיא עִידִית אוֹ זִבּוּרִית לְגַבֵּי זֹאת הַקַּרְקַע שֶׁמָּכַר לוֹ בָּאַחֲרוֹנָה זָכָה הַלּוֹקֵחַ וְאֵין בֶּן הַמֵּצַר יָכוֹל לְסַלְּקוֹ שֶׁהֲרֵי הוּא עַצְמוֹ בֶּן מֵצַר הוּא מִפְּנֵי אוֹתוֹ מְעַט שֶׁקָּנָה בָּאֶמְצַע. וְאִם אוֹתוֹ מְעַט שֶׁקָּנָה בָּאֶמְצַע כְּמוֹ זֹאת שֶׁמָּכַר לוֹ בַּסּוֹף מִצִּדּוֹ הֲרֵי זֶה מַעֲרִים וּבֶן הַמֵּצַר מְסַלֵּק אוֹתוֹ מִן הַשָּׂדֶה שֶׁקָּנָה בַּסּוֹף:","הַמּוֹכֵר עַל תְּנַאי בֵּין שֶׁהִתְנָה מוֹכֵר בֵּין שֶׁהִתְנָה לוֹקֵחַ אֵין בַּעַל הַמֵּצַר יָכוֹל לְסַלְּקוֹ עַד שֶׁיִּתְקַיְּמוּ הַתְּנָאִין וְיִזְכֶּה הַלּוֹקֵחַ בַּקַּרְקַע וְלֹא תִּשָּׁאֵר בָּהּ עִלָּה עִמּוֹ כְּלָל וְאַחַר כָּךְ יְסַלֵּק אוֹתוֹ:","הַלּוֹקֵחַ שֶׁבָּנָה וְהִשְׁבִּיחַ אוֹ סָתַר וְהִפְסִיד בֶּן הַמֵּצַר מְסַלְּקוֹ וְנוֹתֵן לוֹ דָּמִים הָרְאוּיִין לוֹ וַהֲרֵי הוּא בְּכָל מַעֲשָׂיו כְּמוֹ הַשָּׁלִיחַ. וְכֵן אִם לָוָה הַלּוֹקֵחַ קֹדֶם שֶׁיְּסַלֵּק אוֹתוֹ בֶּן הַמֵּצַר וְסִלְּקוֹ בֶּן הַמֵּצַר אֵין בַּעַל חוֹב שֶׁלּוֹ טוֹרֵף מִיַּד בֶּן הַמֵּצַר. זֶהוּ הָעִקָּר בְּכָל אֵלּוּ הַדִּינִין שֶׁכָּל הַלּוֹקֵחַ בְּצַד מֵצַר חֲבֵרוֹ הוּא כְּמוֹ שָׁלִיחַ לַחֲבֵרוֹ וּלְתַקֵּן שְׁלָחוֹ וְלֹא לְעַוֵּת. לְפִיכָךְ אִם הִשְׁבִּיחַ נוֹטֵל הוֹצָאָה. וְאִם הִפְסִיד וְחָפַר וְהָרַס אוֹ אָכַל הַפֵּרוֹת מְנַכִּין אוֹתוֹ מִן הַדָּמִים. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמְּחַשְּׁבִין לוֹ הַפֵּרוֹת בְּשֶׁאֲכָלָן אַחַר שֶׁבָּא בֶּן הַמֵּצַר וְהֵבִיא מָעוֹת לְסַלְּקוֹ. אֲבָל כָּל הַפֵּרוֹת שֶׁאָכַל מִקֹּדֶם שֶׁלּוֹ הוּא אוֹכֵל וְאֵין מְחַשְּׁבִין אוֹתָן:","אֶחָד שֶׁלָּקַח שָׂדֶה אַחַת מִשְּׁנַיִם וּבָא בַּעַל הַמֵּצַר לְסַלְּקוֹ מַחֲצִית בִּלְבַד שֶׁלָּקַח מִן הָאֶחָד אֵינוֹ יָכוֹל לְסַלְּקוֹ. אוֹ מְסַלְּקוֹ מִכֻּלָּהּ אוֹ מַנִּיחַ כֻּלָּהּ. אֲבָל הַמּוֹכֵר קַרְקַע לִשְׁנַיִם יֵשׁ לְבַעַל הַמֵּצַר לְסַלֵּק שְׁנֵיהֶם אוֹ לְסַלֵּק אֶחָד וּלְהַנִּיחַ אֶחָד:","בֶּן הַמֵּצַר שֶׁבָּא לְסַלֵּק אֶת הַלּוֹקֵחַ וְקֹדֶם שֶׁיְּסַלְּקוֹ מָכַר לוֹ אֶת הַשָּׂדֶה שֶׁיֵּשׁ לוֹ עַל הַמֵּצַר אִבֵּד אֶת זְכוּתוֹ:","שָׁלִיחַ שֶׁמָּכַר וַהֲרֵי הוּא בַּעַל הַמֵּצַר אֵינוֹ מְסַלֵּק אֶת הַלּוֹקֵחַ שֶׁהֲרֵי הוּא מָכַר לוֹ וְאֵין לְךָ מְחִילָה גְּדוֹלָה מִזּוֹ:","בַּעַל חוֹב שֶׁל מוֹכֵר שֶׁטָּרַף הַשָּׂדֶה מִיַּד בַּעַל הַמֵּצַר הֲרֵי בַּעַל הַמֵּצַר חוֹזֵר וְטוֹרֵף מִן הַלּוֹקֵחַ שֶׁסִּלְּקוֹ וְהַלּוֹקֵחַ חוֹזֵר וְנוֹטֵל מִן הַמּוֹכֵר:","כָּל בַּעַל חוֹב שֶׁטָּרַף בְּחוֹבוֹ יֵשׁ לְבַעַל הַמֵּצַר לְסַלְּקוֹ. לֹא יְהֵא כֹּחַ הַטּוֹרֵף גָּדוֹל מִכֹּחַ הַלּוֹקֵחַ. וְאִם יִרְצֶה הַנִּטְרָף לִתֵּן הַדָּמִים שֶׁהָיוּ עָלָיו בְּחוֹבוֹ תַּחְזֹר לוֹ שָׂדֵהוּ לְעוֹלָם כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","קָטָן שֶׁהָיָה בֶּן הַמֵּצַר וְרָאָה בֵּית דִּין שֶׁזְּכוּת הוּא לוֹ מְסַלְּקִין לוֹ אֶת הַלּוֹקֵחַ אוֹ יִטּל לוֹ חֶלְקוֹ עִם שְׁאָר בַּעֲלֵי הַמֵּצַר כְּמוֹ שֶׁיִּרְאוּ:","בַּעַל שֶׁהָיְתָה אִשְׁתּוֹ בֶּן הַמֵּצַר הֲרֵי זֶה מְסַלֵּק אֶת הַלּוֹקֵחַ שֶׁכָּל נִכְסֵי אִשְׁתּוֹ בִּרְשׁוּתוֹ וְכָל זְכוּת שֶׁתָּבוֹא לְיָדָהּ זְכוּת הוּא לוֹ. אֲפִלּוּ קָנוּ מִיַּד אִשְׁתּוֹ שֶׁמָּחֲלָה בִּזְכוּת זוֹ לַלּוֹקֵחַ אֵינוֹ מוֹעִיל אֶלָּא הַבַּעַל מְסַלְּקוֹ. עָמְדָה הָאִשָּׁה מִדַּעְתָּהּ וְסִלְּקָה אֶת הַלּוֹקֵחַ וְכֵן הָעֶבֶד שֶׁהָיָה נוֹשֵׂא וְנוֹתֵן בְּנִכְסֵי אֲדוֹנָיו שֶׁסִּלֵּק אֶת הַלּוֹקֵחַ אִם רָצָה הַבַּעַל אוֹ הָאָדוֹן מְקַיֵּם עַל יְדֵיהֶן וְאִם רָצָה לֹא יְקַיֵּם וְתַחְזֹר לַלּוֹקֵחַ וְיַחְזִיר הַדָּמִים:"],"Mishneh Torah, Oaths 11":["כְּשֵׁם שֶׁשְּׁבוּעַת שָׁוְא וְשֶׁקֶר בְּלֹא תַּעֲשֶׂה. כָּךְ מִצְוַת עֲשֵׂה שֶׁיִּשָּׁבַע מִי שֶׁנִּתְחַיֵּב שְׁבוּעָה בְּבֵית דִּין בַּשֵּׁם שֶׁנֶּאֱמַר (דברים ו יג) (דברים י כ) \"וּבִשְׁמוֹ תִּשָּׁבֵעַ\" זוֹ מִצְוַת עֲשֵׂה. שֶׁהַשְּׁבוּעָה בִּשְׁמוֹ הַגָּדוֹל וְהַקָּדוֹשׁ מִדַּרְכֵי הָעֲבוֹדָה הִיא וְהִדּוּר וְקִדּוּשׁ גָּדוֹל הוּא לְהִשָּׁבַע בִּשְׁמוֹ:","וְאָסוּר לְהִשָּׁבַע בְּדָבָר אַחֵר עִם שְׁמוֹ. וְכָל הַמְשַׁתֵּף דָּבָר אַחֵר עִם שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁבוּעָה נֶעֱקָר מִן הָעוֹלָם. שֶׁאֵין שָׁם מִי שֶׁרָאוּי לַחְלֹק לוֹ כָבוֹד שֶׁנִּשְׁבָּעִין בִּשְׁמוֹ אֶלָּא הָאֶחָד בָּרוּךְ הוּא:","וּמֻתָּר לְאָדָם לְהִשָּׁבַע עַל הַמִּצְוָה לַעֲשׂוֹתָהּ כְּדֵי לְזָרֵז אֶת עַצְמוֹ וְאַף עַל פִּי שֶׁהוּא מֻשְׁבָּע עָלֶיהָ מֵהַר סִינַי שֶׁנֶּאֱמַר (תהילים קיט קו) \"נִשְׁבַּעְתִּי וָאֲקַיֵּמָה לִשְׁמֹר מִשְׁפְּטֵי צִדְקֶךָ\":","שְׁבוּעָה זוֹ שֶׁמַּשְׁבִּיעִין הַדַּיָּנִים לְמִי שֶׁנִּתְחַיֵּב שְׁבוּעָה הִיא הַנִּקְרֵאת שְׁבוּעַת הַדַּיָּנִין. בֵּין שֶׁהָיָה חַיָּב בִּשְׁבוּעָה זוֹ מִן הַתּוֹרָה בֵּין שֶׁהָיָה חַיָּב בָּהּ מִדִּבְרֵי סוֹפְרִים:","שְׁלֹשָׁה מִינֵי שְׁבוּעוֹת הֵן שֶׁחַיָּבִין בָּהֶן מִן הַתּוֹרָה. וְאֵלּוּ הֵן. מִי שֶׁטְּעָנוֹ חֲבֵרוֹ מִטַּלְטְלִין וְהוֹדָה בְּמִקְצָתָן וְכָפַר בְּמִקְצָתָן. וּמִי שֶׁכָּפַר בְּכָל הַמִּטַּלְטְלִין שֶׁטְּעָנוֹ וְעֵד אֶחָד מֵעִיד עָלָיו וּמַכְחִישׁוֹ הֲרֵי אֵלּוּ שְׁתֵּי שְׁבוּעוֹת עַל יְדֵי טַעֲנַת וַדַּאי וּכְפִירָה. וְכֵן שׁוֹמֵר שֶׁטּוֹעֵן שֶׁאָבַד דָּבָר שֶׁהִפְקִידוּ אֶצְלוֹ אוֹ נִגְנַב אוֹ מֵת וְכַיּוֹצֵא בָּזֶה הֲרֵי זֶה נִשְׁבַּע מִסָּפֵק. שֶׁאֵין בַּעַל הַפִּקָּדוֹן יוֹדֵעַ אִם אֱמֶת טוֹעֵן זֶה הַשּׁוֹמֵר אוֹ שֶׁקֶר. וְהוּא נִשְׁבַּע מִן הַתּוֹרָה שֶׁנֶּאֱמַר (שמות כב י) \"שְׁבוּעַת ה' תִּהְיֶה בֵּין שְׁנֵיהֶם\":","כָּל שְׁבוּעָה שֶׁמַּשְׁבִּיעִין אוֹתָהּ הַדַּיָּנִין חוּץ מִשְּׁלֹשָׁה מִינֵי שְׁבוּעוֹת אֵלּוּ הֲרֵי הִיא מִדִּבְרֵי סוֹפְרִים וְגַם הִיא הַנִּקְרֵאת שְׁבוּעַת הַדַּיָּנִין. וְגַם שְׁבוּעוֹת אֵלּוּ מִדִּבְרֵיהֶם שְׁנֵי מִינֵי שְׁבוּעוֹת הֵן. יֵשׁ מֵהֶן שְׁבוּעוֹת עַל יְדֵי טַעֲנַת וַדַּאי וּכְפִירָה כְּגוֹן שְׁבוּעַת שָׂכִיר וּפוֹגֵם שְׁטָרוֹ וְכַיּוֹצֵא בָּהֶן. וְיֵשׁ מֵהֶן שְׁבוּעוֹת בְּטַעֲנַת סָפֵק כְּגוֹן שְׁבוּעַת הַשֻּׁתָּפִין וְהָאֲרִיסִין וְכַיּוֹצֵא בָּהֶן. וּבְדִינֵי מָמוֹנוֹת יִתְבָּאֵר חִיּוּב כָּל אַחַת וְאַחַת מֵאֵלּוּ הַשְּׁבוּעוֹת וְדִינֵיהֶם:","וְיֵשׁ שָׁם שְׁבוּעָה אַחֶרֶת וְהִיא תַּקָּנַת חַכְמֵי הַגְּמָרָא וְהִיא הַנִּקְרֵאת שְׁבוּעַת הֶסֵּת. וְאַף עַל פִּי שֶׁבֵּית דִּין מַשְׁבִּיעִין אוֹתָהּ [הַיּוֹם] אֵינָהּ נִקְרֵאת שְׁבוּעַת הַדַּיָּנִין:","וּשְׁבוּעַת הַדַּיָּנִין בֵּין שֶׁהָיְתָה שֶׁל תּוֹרָה אוֹ שֶׁל דִּבְרֵי סוֹפְרִים בֵּין עַל טַעֲנַת וַדַּאי בֵּין עַל טַעֲנַת סָפֵק כָּךְ הִיא. הַנִּשְׁבָּע אוֹחֵז סֵפֶר תּוֹרָה בִּזְרוֹעוֹ וְהוּא עוֹמֵד וְנִשְׁבָּע בְּשֵׁם אוֹ בְּכִנּוּי בִּשְׁבוּעָה אוֹ בְּאָלָה מִפִּיו אוֹ מִפִּי הַדַּיָּנִין. וְהוֹרוּ רַבּוֹתַי שֶׁאֵין מַשְׁבִּיעִין שְׁבוּעַת הַדַּיָּנִין אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ:","כֵּיצַד מִפִּיו. כְּגוֹן שֶׁיֹּאמַר הֲרֵינִי נִשְׁבָּע בַּה' אֱלֹהֵי יִשְׂרָאֵל אוֹ בְּמִי שֶׁשְּׁמוֹ חַנּוּן אוֹ בְּמִי שֶׁשְּׁמוֹ רַחוּם שֶׁאֵינִי חַיָּב לָזֶה כְּלוּם. וְכֵן אִם אָמַר הֲרֵי הוּא אָרוּר לַה' אוֹ אָרוּר לְמִי שֶׁשְּׁמוֹ חַנּוּן אִם יֵשׁ לָזֶה אֶצְלִי כְּלוּם:","וְכֵיצַד מִפִּי הַדַּיָּנִין. כְּגוֹן שֶׁאָמְרוּ לוֹ מַשְׁבִּיעִין אָנוּ אוֹתְךָ בַּה' אֱלֹהֵי יִשְׂרָאֵל אוֹ בְּמִי שֶׁשְּׁמוֹ חַנּוּן שֶׁאֵין לָזֶה בְּיָדְךָ כְּלוּם וְהוּא עוֹנֶה אָמֵן. אוֹ שֶׁאָמְרוּ הֲרֵי פְּלוֹנִי בֶּן פְּלוֹנִי אָרוּר לַה' אֱלֹהֵי יִשְׂרָאֵל אוֹ לְמִי שֶׁשְּׁמוֹ חַנּוּן אִם יֵשׁ לִפְלוֹנִי אֶצְלוֹ מָמוֹן וְלֹא יוֹדֶה לוֹ וְהוּא עוֹנֶה אָמֵן זוֹ הִיא שְׁבוּעַת הַדַּיָּנִין:","הַדַּיָּנִין שֶׁהִשְׁבִּיעוּ בְּלֹא נְקִיטַת חֵפֶץ בְּיָדוֹ הֲרֵי אֵלּוּ טוֹעִים. וְחוֹזֵר וְנִשְׁבָּע וְסֵפֶר תּוֹרָה בְּיָדוֹ. וְאִם אָחַז תְּפִלִּין בְּיָדוֹ וְהִשְׁבִּיעוּהוּ אֵינוֹ חוֹזֵר וְנִשְׁבָּע שֶׁהֲרֵי אָחַז תּוֹרָה בְּיָדוֹ וּכְמוֹ סֵפֶר הֵן. הִשְׁבִּיעוּהוּ מְיֻשָּׁב אֵינוֹ חוֹזֵר וְנִשְׁבָּע:","תַּלְמִיד חָכָם לְכַתְּחִלָּה מַשְׁבִּיעִין אוֹתוֹ מְיֻשָּׁב וּתְפִלִּין בְּיָדוֹ וְאֵינוֹ צָרִיךְ לִטּוֹל סֵפֶר תּוֹרָה אֶלָּא תְּפִלִּין בְּכַפּוֹ חֵפֶץ הוּא וְנִשְׁבָּע בִּלְשׁוֹן הַקֹּדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין בֵּין שְׁבוּעַת הֶסֵּת לִשְׁבוּעַת הַדַּיָּנִין אֶלָּא נְקִיטַת חֵפֶץ. שֶׁאֵין הַנִּשְׁבָּע שְׁבוּעַת הֶסֵּת אוֹחֵז סֵפֶר תּוֹרָה אֶלָּא מַשְׁבִּיעִין אוֹתוֹ בְּשֵׁם אוֹ בְּכִנּוּי בִּשְׁבוּעָה אוֹ בְּאָלָה מִפִּיו אוֹ מִפִּי בֵּית דִּין כְּמוֹ שְׁבוּעַת הַדַּיָּנִין. וּכְבָר נָהֲגוּ הַכּל לִהְיוֹת סֵפֶר תּוֹרָה בְּיַד חַזַּן הַכְּנֶסֶת אוֹ שְׁאָר הָעָם בְּעֵת שֶׁמַּשְׁבִּיעִין שְׁבוּעַת הֶסֵּת כְּדֵי לְאַיֵּם עָלָיו:","הַדַּיָּנִין שֶׁהִשְׁבִּיעוּ אֶת הַנִּשְׁבָּע בְּכָל לָשׁוֹן שֶׁהוּא מַכִּיר הֲרֵי זוֹ כְּמִצְוָתָהּ וְכֵן הוֹרוּ הַגְּאוֹנִים. אֲבָל רַבּוֹתֵינוּ הוֹרוּ שֶׁאֵין מַשְׁבִּיעִים אֶלָּא בִּלְשׁוֹן הַקֹּדֶשׁ. וְאֵין רָאוּי לִסְמֹךְ עַל הוֹרָאָה זוֹ. וְאַף עַל פִּי שֶׁנָּהֲגוּ בְּכָל בָּתֵּי דִּינִין לְהִשָּׁבַע בִּלְשׁוֹן הַקֹּדֶשׁ צָרִיךְ לְהוֹדִיעַ אֶת הַנִּשְׁבָּע עַד שֶׁיְּהֵא מַכִּיר לְשׁוֹן הַשְּׁבוּעָה. שֶׁשְּׁבוּעַת הַדַּיָּנִין הִיא שְׁבוּעַת הַפִּקָּדוֹן בְּעַצְמָהּ. וְאַף שְׁבוּעַת הֶסֵּת נָהֲגוּ כָּל הָעָם לְהַשְׁבִּיעַ אוֹתָהּ בִּלְשׁוֹן הַקֹּדֶשׁ:","כָּל מִי שֶׁיִּתְחַיֵּב שְׁבוּעַת הַדַּיָּנִין שֶׁהִיא עַל יְדֵי טַעֲנַת וַדַּאי וּכְפִירָה בֵּין שֶׁהָיְתָה מִדִּבְרֵי תּוֹרָה בֵּין שֶׁהָיְתָה מִדִּבְרֵיהֶם מְאַיְּמִין עָלָיו כְּמוֹ שֶׁיִּתְבָּאֵר. וְכָל מִי שֶׁיִּתְחַיֵּב בָּהּ בְּטַעֲנַת סָפֵק בֵּין מִן הַתּוֹרָה בֵּין מִדִּבְרֵיהֶם אֵינוֹ צָרִיךְ אִיּוּם:","וְכֵיצַד מְאַיְּמִין עַל הַנִּשְׁבָּע. אוֹמְרִין לוֹ הֱוֵי יוֹדֵעַ שֶׁכָּל הָעוֹלָם כֻּלּוֹ נִזְדַּעֲזֵעַ בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמשֶׁה לֹא תִשָּׂא אֶת שֵׁם ה' אֱלֹהֶיךָ לַשָּׁוְא. וְכָל עֲבֵרוֹת שֶׁבַּתּוֹרָה נֶאֱמַר בָּהֶן וְנַקֵּה וְכָאן נֶאֱמַר (שמות כ ז) (דברים ה יא) \"לֹא יְנַקֶּה\". כָּל עֲבֵרוֹת שֶׁבַּתּוֹרָה נִפְרָעִין מִמֶּנּוּ וְכָאן מִמֶּנּוּ וּמִמִּשְׁפַּחְתּוֹ שֶׁמְּחַפִּין עַל זֶה. וְלֹא עוֹד אֶלָּא גּוֹרֵם לְהִפָּרַע מִשּׂוֹנְאֵיהֶם שֶׁל יִשְׂרָאֵל שֶׁכָּל יִשְׂרָאֵל עֲרֵבִין זֶה בָּזֶה שֶׁנֶּאֱמַר (הושע ד ב) \"אָלֹה וְכַחֵשׁ וְרָצֹחַ\" וְגוֹ' וְכָתוּב אַחֲרָיו (הושע ד ג) \"עַל כֵּן תֶּאֱבַל הָאָרֶץ וְאֻמְלַל כָּל יוֹשֵׁב בָּהּ\". כָּל עֲבֵרוֹת שֶׁבַּתּוֹרָה תּוֹלִין לוֹ שְׁנַיִם וּשְׁלֹשָׁה דּוֹרוֹת אִם יֵשׁ לוֹ זְכוּת וְכָאן נִפְרָעִין מִיָּד שֶׁנֶּאֱמַר (זכריה ה ד) \"הוֹצֵאתִיהָ נְאֻם ה' צְבָאוֹת וּבָאָה אֶל בֵּית הַגַּנָּב וְאֶל בֵּית הַנִּשְׁבָּע בִּשְׁמִי לַשָּׁקֶר\". הוֹצֵאתִיהָ מִיָּד. וּבָאָה אֶל בֵּית הַגַּנָּב זֶה הַגּוֹנֵב דַּעַת הַבְּרִיּוֹת וְאֵין לוֹ מָמוֹן עַל חֲבֵרוֹ וְטוֹעֲנוֹ בְּחִנָּם וּמַשְׁבִּיעוֹ. אֶל בֵּית הַנִּשְׁבָּע בִּשְׁמִי לַשֶּׁקֶר כְּמַשְׁמָעוֹ. (זכריה ה ד) \"וְכִלַּתּוּ וְאֶת עֵצָיו וְאֶת אֲבָנָיו\" דְּבָרִים שֶׁאֵין אֵשׁ וּמַיִם מְכַלִּין אוֹתָן שְׁבוּעַת שֶׁקֶר מְכַלָּה אוֹתָן:","וְעִנְיַן הָאִיּוּם הַזֶּה כֻּלּוֹ בְּלָשׁוֹן שֶׁהֵן מַכִּירִין אוֹמְרִים לָהֶם כְּדֵי שֶׁיָּבִינוּ בַּדְּבָרִים וְיַחְזֹר הַחוֹטֵא לְמוּטָב. אָמַר אֵינִי נִשְׁבָּע פּוֹטְרִין אוֹתוֹ וְנוֹתֵן מַה שֶּׁטָּעֲנוֹ חֲבֵרוֹ. וְכֵן אִם אָמַר הַטּוֹעֵן אֵינִי מַשְׁבִּיעוֹ וּפְטָרוֹ הוֹלְכִין לָהֶן:","אָמַר הֲרֵינִי נִשְׁבָּע וַחֲבֵרוֹ תּוֹבֵעַ. הָעוֹמְדִים שָׁם אוֹמְרִים זֶה לָזֶה (במדבר טז כו) \"סוּרוּ נָא מֵעַל אָהֳלֵי הָאֲנָשִׁים הָרְשָׁעִים\" וְגוֹ'. וְאוֹמְרִין לוֹ לֹא עַל דַּעְתְּךָ אָנוּ מַשְׁבִּיעִין אוֹתְךָ אֶלָּא עַל דַּעְתֵּנוּ וְעַל דַּעַת בֵּית דִּין:","אַף עַל פִּי שֶׁאֵין מְאַיְּמִין אִיּוּם זֶה בִּשְׁבוּעַת טַעֲנַת סָפֵק כְּמוֹ שֶׁבֵּאַרְנוּ וְלֹא בִּשְׁבוּעַת הֶסֵּת. צְרִיכִין הַדַּיָּנִין לִפְצֹר בְּבַעֲלֵי דִּינִין אוּלַי יַחְזְרוּ בָּהֶן עַד שֶׁלֹּא תִּהְיֶה שָׁם שְׁבוּעָה כְּלָל:","דָּבָר בָּרוּר וְגָלוּי שֶׁכָּל הַנִּשְׁבָּע שְׁבוּעַת הַדַּיָּנִין אוֹ שְׁבוּעַת הֶסֵּת בְּשֶׁקֶר שֶׁיְּהֵא חַיָּב מִשּׁוּם שְׁבוּעַת הַפִּקָּדוֹן שֶׁכְּבָר נִתְבָּאֲרוּ מִשְׁפָּטֶיהָ וְאֵינוֹ לוֹקֶה וְאַף עַל פִּי שֶׁהוּא מֵזִיד וְנִתְחַיֵּב לְשַׁלֵּם מַה שֶּׁנִּשְׁבַּע עָלָיו בְּתוֹסֶפֶת חֹמֶשׁ שֶׁהוּא רְבִיעַ הַקֶּרֶן עַד שֶׁיִּהְיֶה הוּא וְחֻמְשׁוֹ חֲמִשָּׁה. וּמֵבִיא קָרְבַּן אָשָׁם אִם יֵשׁ שָׁם בֵּית (דִּין) כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Offerings for Those with Incomplete Atonement 3":["כָּל הַיָּמִים שֶׁהַזָּב רוֹאֶה בָּהֶן זִיבוֹת הֲרֵי הוּא טָמֵא. וּכְשֶׁיִּפְסֹק הַזִּיבוֹת מוֹנֶה שִׁבְעָה יָמִים נְקִיִּים כְּזָבָה וְטוֹבֵל בַּשְּׁבִיעִי וּמַעֲרִיב שִׁמְשׁוֹ וּבַשְּׁמִינִי מֵבִיא קָרְבָּנוֹ אִם הָיָה בַּעַל שָׁלֹשׁ רְאִיּוֹת. וְאִם רָאָה רְאִיָּה שֶׁל זוֹב אֲפִלּוּ בְּסוֹף יוֹם שְׁבִיעִי אַחַר שֶׁטָּבַל סָתַר הַכּל וּמַתְחִיל לִמְנוֹת שִׁבְעָה יָמִים נְקִיִּים מֵאַחַר יוֹם רְאִיָּה הָאַחֲרוֹנָה:","זָב שֶׁרָאָה קֶרִי בְּאֶחָד מִשִּׁבְעַת יְמֵי הַסְּפִירָה אֵינוֹ סוֹתֵר אֶלָּא יוֹמוֹ בִּלְבַד וּמַשְׁלִים שִׁבְעָה יָמִים וּמֵבִיא קָרְבָּנוֹ. כֵּיצַד. רָאָה קֶרִי בַּיּוֹם הַחֲמִישִׁי סוֹפֵר אַחֲרָיו שְׁלֹשָׁה יָמִים וְטוֹבֵל בַּשְּׁלִישִׁי וּמֵבִיא קָרְבָּנוֹ בָּרְבִיעִי:","זָב שֶׁבָּדַק בְּיוֹם רִאשׁוֹן מִימֵי הַסְּפִירָה וּמָצָא טָהוֹר וְלֹא בָּדַק כָּל שִׁבְעָה וּבַיּוֹם הַשְּׁבִיעִי בָּדַק וּמָצָא טָהוֹר הֲרֵי זֶה בְּחֶזְקַת טָהֳרָה. אֲפִלּוּ בָּדַק בְּיוֹם הַטֻּמְאָה עַצְמָהּ וּמָצָא טָהוֹר וּפָסַק הַזּוֹב וְלֹא בָּדַק לְמָחָר בִּתְחִלַּת יְמֵי הַסְּפִירָה וּבָדַק בַּשְּׁבִיעִי אוֹ בַּשְּׁמִינִי וּמָצָא טָהוֹר עָלוּ לוֹ יְמֵי הַסְּפִירָה וַהֲרֵי זֶה בְּחֶזְקַת טָהֳרָה:","כָּל רְאִיָּה שֶׁהִיא סוֹתֶרֶת אֵינָהּ מְבִיאָה לִידֵי קָרְבָּן. כֵּיצַד. רָאָה שְׁתֵּי רְאִיּוֹת וְהִפְסִיק יוֹם אוֹ יוֹמַיִם וַהֲרֵי הוּא מוֹנֶה שִׁבְעָה יָמִים נְקִיִּים וּבְתוֹךְ הַשִּׁבְעָה רָאָה רְאִיָּה שֶׁל זוֹב אֵינָהּ מִצְטָרֶפֶת לִשְׁתַּיִם אֶלָּא סוֹתֶרֶת וּמַתְחִיל לִמְנוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. אֲפִלּוּ רָאָה בְּתוֹךְ יְמֵי הַסְּפִירָה שָׁלֹשׁ רְאִיּוֹת זוֹ אַחַר זוֹ. אֲפִלּוּ רָאָה אוֹתָם בְּיוֹם אֶחָד. אֲפִלּוּ רָאָה שָׁלֹשׁ רְאִיּוֹת בְּסוֹף יוֹם שְׁבִיעִי שֶׁל שִׁבְעָה יָמִים נְקִיִּים. אֵינוֹ מֵבִיא קָרְבָּן שֶׁרְאִיּוֹת אֵלּוּ לִסְתִירָה הֵן. רָאָה שָׁלֹשׁ רְאִיּוֹת בְּלֵיל שְׁמִינִי מֵבִיא קָרְבָּן שֶׁאֵין רְאִיּוֹת אֵלּוּ סוֹתְרִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּזָב בַּעַל שְׁתֵּי רְאִיּוֹת. אֲבָל בְּזָב בַּעַל שָׁלֹשׁ רְאִיּוֹת בְּלֵיל שְׁמִינִי שֶׁלְּאַחַר שִׁבְעַת יָמִים נְקִיִּים אֵינוֹ מֵבִיא קָרְבָּן שֵׁנִי עַל שָׁלֹשׁ רְאִיּוֹת אֵלּוּ אֶלָּא קָרְבָּן אֶחָד עַל הַשָּׁלֹשׁ הָרִאשׁוֹנוֹת. שֶׁאַף עַל פִּי שֶׁאֵין שָׁלֹשׁ אַחֲרוֹנוֹת סוֹתְרוֹת הֲרֵי לֹא יָצָא לִזְמַן שֶׁרָאוּי לְקָרְבָּן וְהַלַּיְלָה מְחֻסַּר זְמַן הוּא לַכּל. חוּץ מִיּוֹלֶדֶת שֶׁהִפִּילָה בְּלֵיל שְׁמוֹנִים וְאֶחָד שֶׁהִיא מְבִיאָה קָרְבָּן שֵׁנִי כְּמוֹ שֶׁבֵּאַרְנוּ. וְדָבָר זֶה מִפִּי הַקַּבָּלָה:","רָאָה רְאִיָּה אַחַת בְּלֵיל שְׁמִינִי וּשְׁתֵּי רְאִיּוֹת בְּיוֹם שְׁמִינִי הֲרֵי אֵלּוּ מִצְטָרְפִין וּמֵבִיא קָרְבָּן שֵׁנִי עַל זִיבוֹת הָאַחֲרוֹנוֹת. שֶׁהֲרֵי רְאִיָּה רִאשׁוֹנָה שֶׁל כָּל זָב כְּשִׁכְבַת זֶרַע הִיא חֲשׁוּבָה וְאִם רָאָה אַחֲרֶיהָ שְׁתַּיִם מִצְטָרֶפֶת עִמָּהֶם לְקָרְבָּן. אֲבָל אִם רָאָה שְׁתַּיִם בְּלֵיל שְׁמִינִי וְאַחַת בְּיוֹם שְׁמִינִי אֵין מִצְטָרֶפֶת וְאֵינוֹ מֵבִיא קָרְבָּן עַל הַזִּיבָה זוֹ הָאַחֲרוֹנָה:","הַכּל מִתְטַמְּאִין בְּזִיבָה אֲפִלּוּ קָטָן בֶּן יוֹמוֹ וְהַגֵּרִים וְהָעֲבָדִים וְחֵרֵשׁ וְשׁוֹטֶה. וְיֵרָאֶה לִי שֶׁמְּבִיאִין עֲלֵיהֶן כַּפָּרָה כְּדֵי לְהַאֲכִילָן בְּקָדָשִׁים וְחַטָּאתָן נֶאֱכֶלֶת שֶׁהֲרֵי הֵן כְּקָטָן שֶׁאֵינוֹ בֶּן דַּעַת. וּסְרִיס אָדָם וּסְרִיס חַמָּה מִתְטַמְּאִין בְּזִיבָה כְּכָל הָאֲנָשִׁים:","הַטֻּמְטוּם וְהָאַנְדְּרוֹגִינוּס נוֹתְנִין עֲלֵיהֶן חֻמְרֵי הָאִישׁ וְחֻמְרֵי הָאִשָּׁה. מִתְטַמְּאִין בְּדָם כְּנָשִׁים וּבְלֹבֶן כַּאֲנָשִׁים וְטֻמְאָתָן בְּסָפֵק. לְפִיכָךְ אִם הָיָה אֶחָד מֵהֶן בַּעַל שָׁלֹשׁ רְאִיּוֹת אוֹ זָבָה שֶׁרָאֲתָה דָּם שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה מְבִיאִין קָרְבָּן וְאֵינוֹ נֶאֱכָל. הָיָה מוֹנֶה שִׁבְעָה יָמִים נְקִיִּים לְלֹבֶן וְרָאָה אֹדֶם אוֹ לְאֹדֶם וְרָאָה לֹבֶן הֲרֵי זֶה אֵינוֹ סוֹתֵר:"],"Mishneh Torah, Offerings for Unintentional Transgressions 4":["הָעוֹשֶׂה עֲבֵרוֹת הַרְבֵּה בְּהֶעְלֵם אַחַת חַיָּב חַטָּאת עַל כָּל אַחַת וְאַחַת אֲפִלּוּ עָשָׂה הָאַרְבָּעִים וְשָׁלֹשׁ אֵלּוּ שֶׁמָּנִינוּ בְּהֶעְלֵם אַחַת חַיָּב אַרְבָּעִים וְשָׁלֹשׁ חַטָּאוֹת. וְכֵן אִם עָשָׂה מַעֲשֶׂה אֶחָד שֶׁהוּא חַיָּב עָלָיו מִשּׁוּם שֵׁמוֹת הַרְבֵּה חַיָּב עַל כָּל שֵׁם וְשֵׁם וְהוּא שֶׁהָיוּ הָאִסּוּרִין כֻּלָּן בָּאִין כְּאַחַת אוֹ אִסּוּר מוֹסִיף אוֹ אִסּוּר כּוֹלֵל. כֵּיצַד. הַשּׁוֹחֵט בֶּהֱמַת קָדָשִׁים חוּץ לָעֲזָרָה בְּשַׁבָּת לַעֲבוֹדָה זָרָה חַיָּב שָׁלֹשׁ חַטָּאוֹת. מִשּׁוּם שׁוֹחֵט קָדָשִׁים בַּחוּץ וּמִשּׁוּם מְחַלֵּל שַׁבָּת וּמִשּׁוּם עוֹבֵד עֲבוֹדָה זָרָה שֶׁהֲרֵי שְׁלֹשֶׁת הָאִסּוּרִין בָּאִין כְּאַחַת. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאוֹמֵר בִּגְמַר זְבִיחָה הוּא עוֹבֵד אוֹתָהּ. אֲבָל אִם לֹא הָיְתָה כַּוָּנָתוֹ לְכָךְ מִשֶּׁיִּשְׁחֹט בָּהּ מְעַט לְשֵׁם עֲבוֹדָה זָרָה תֵּאָסֵר וְאֵינוֹ חַיָּב מִשּׁוּם שְׁחוּטֵי חוּץ עַד שֶׁיִּשְׁחֹט שְׁנַיִם אוֹ רֹב שְׁנַיִם. וְנִמְצָא כְּשֶׁגָּמַר הַשְּׁחִיטָה שָׁחַט בְּהֵמָה הָאֲסוּרָה לְקָרְבָּן שֶׁאֵינוֹ חַיָּב עָלֶיהָ מִשּׁוּם שׁוֹחֵט בַּחוּץ כְּמוֹ שֶׁבֵּאַרְנוּ. הָיְתָה חַטָּאת הָעוֹף וְהָיָה חֲצִי קָנֶה שֶׁלָּהּ פָּגוּם וְהוֹסִיף בּוֹ כָּל שֶׁהוּא בְּשַׁבָּת לְשֵׁם עֲבוֹדָה זָרָה חַיָּב שָׁלֹשׁ חַטָּאוֹת שֶׁהֲרֵי שְׁלֹשֶׁת הָאִסּוּרִין בָּאִים כְּאַחַת. וְכֵן הָעוֹשֶׂה מְלָאכָה בְּיוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת בְּשַׁבָּת חַיָּב שְׁתֵּי חַטָּאוֹת מִפְּנֵי שֶׁשְּׁנֵי הָאִסּוּרִין בָּאִין כְּאַחַת. הַבָּא עַל אֵשֶׁת אָחִיו הַקַּיָּם כְּשֶׁהִיא נִדָּה מֵבִיא שָׁלֹשׁ חַטָּאוֹת מִשּׁוּם אֵשֶׁת אִישׁ וּמִשּׁוּם אֵשֶׁת אָח וְהֵן שְׁנֵי אִסּוּרִין הַבָּאִין כְּאַחַת וּמִשּׁוּם נִדָּה שֶׁהוּא אִסּוּר מוֹסִיף שֶׁמִּתּוֹךְ שֶׁנִּתְוַסֵּף בָּהּ אִסּוּר זֶה לְבַעְלָהּ נוֹסַף לִיבָמָהּ. וְכֵן כַּיּוֹצֵא בָּזֶה. הַבָּא עַל אָבִיו חַיָּב שְׁתַּיִם אַחַת מִשּׁוּם (ויקרא יח ז) \"עֶרְוַת אָבִיךָ לֹא תְגַלֵּה\" וּמִשּׁוּם (ויקרא יח כב) \"וְאֶת זָכָר לֹא תִשְׁכַּב\". וְכֵן הַבָּא עַל אֲחִי אָבִיו חַיָּב שְׁתַּיִם שֶׁנֶּאֱמַר (ויקרא יח יד) \"עֶרְוַת אֲחִי אָבִיךָ לֹא תְגַלֵּה\". הַבָּא עַל הַזָּכוּר וְהֵבִיא זָכוּר עָלָיו בְּהֶעְלֵם אַחַת אַף עַל פִּי שֶׁהֵן שְׁנֵי גּוּפִין אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת שֶׁנֶּאֱמַר וְאֶת זָכָר לֹא תִשְׁכַּב הַשּׁוֹכֵב וְהַנִּשְׁכָּב שֵׁם אֶחָד הוּא. וְכֵן הַבָּא עַל הַבְּהֵמָה וְהֵבִיא בְּהֵמָה עָלָיו בְּהֶעְלֵם אַחַת אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת. עָשׂוּ הַשּׁוֹכֵב וְהַנִּשְׁכָּב בִּבְהֵמָה וְזָכוּר כִּבְעִילָה אַחַת:","יֵשׁ בּוֹעֵל בְּעִילָה אַחַת וְחַיָּב עָלֶיהָ שְׁמוֹנֶה חַטָּאוֹת. כֵּיצַד. יַעֲקֹב שֶׁהָיְתָה לוֹ בַּת מִזִּלְפָּה וּשְׁמָהּ תִּמְנַע. נָשָׂא לָבָן תִּמְנַע וְהוֹלִיד מִמֶּנָּה בַּת וּשְׁמָהּ סֶרַח. וְאֵין לְלָבָן בַּת אֶלָּא רָחֵל לְבַדָּהּ. נִמְצֵאת סֶרַח בַּת בַּת יַעֲקֹב וַאֲחוֹת אִשְׁתּוֹ מֵאָבִיהָ הֵן שְׁנֵי אִסּוּרִין הַבָּאִין כְּאַחַת. נִשֵּׂאת סֶרַח לִרְאוּבֵן וְנֶאֶסְרָה עַל שְׁאָר בְּנֵי יַעֲקֹב נוֹסָף בָּהּ אִסּוּר לְיַעֲקֹב וַהֲרֵי הִיא כַּלָּתוֹ. מֵת רְאוּבֵן אוֹ גֵּרֵשׁ וְנִשֵּׂאת סֶרַח זוֹ לַאֲחִי יַעֲקֹב מֵאִמּוֹ מִתּוֹךְ שֶׁנֶּאֶסְרָה עַל שְׁאָר אֲחֵי יַעֲקֹב נוֹסַף לְיַעֲקֹב בָּהּ אִסּוּר אֵשֶׁת אָחִיו. מֵת אוֹ גֵּרֵשׁ וְנִשֵּׂאת סֶרַח זוֹ לְיִשְׁמָעֵאל מִתּוֹךְ שֶׁנֶּאֶסְרָה עַל שְׁאָר אֲחֵי יִשְׁמָעֵאל נוֹסַף לְיַעֲקֹב בָּהּ אִסּוּר אֵשֶׁת אֲחִי אָבִיו. מֵת יִשְׁמָעֵאל וְנָפְלָה לְיִבּוּם לִפְנֵי יִצְחָק וְעָבַר יִצְחָק וְיִבְּמָהּ אַף עַל פִּי שֶׁהִיא שְׁנִיָּה לוֹ מִתּוֹךְ שֶׁנֶּאֶסְרָה עַל שְׁאָר אֶחָיו נוֹסַף בָּהּ אִסּוּר לְיַעֲקֹב מִשּׁוּם אֵשֶׁת אָבִיו וּמִשּׁוּם אֵשֶׁת אִישׁ שֶׁשְּׁנֵי הָאִסּוּרִין בָּאִין כְּאַחַת. אִם שָׁגַג יַעֲקֹב וּבָא עַל סֶרַח זוֹ כְּשֶׁהִיא נִדָּה בְּחַיֵּי יִצְחָק בַּעְלָהּ וּבְחַיֵּי רָחֵל אֵשֶׁת יַעֲקֹב הֲרֵי זֶה חַיָּב עָלֶיהָ שְׁמוֹנֶה חַטָּאוֹת. מִשּׁוּם בַּת בִּתּוֹ. וּמִשּׁוּם אֲחוֹת אִשְׁתּוֹ. וּמִשּׁוּם כַּלָּתוֹ. וּמִשּׁוּם אֵשֶׁת אָחִיו. וּמִשּׁוּם אֵשֶׁת אֲחִי אָבִיו. וּמִשּׁוּם אֵשֶׁת אָבִיו. וּמִשּׁוּם אֵשֶׁת אִישׁ. וּמִשּׁוּם נִדָּה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל אֵלּוּ שֶׁתֵּאָסֵר זוֹ הָעֶרְוָה עֲלֵיהֶן בְּאִסּוּר מוֹסִיף. צָרִיךְ שֶׁיְּהוּ הָאֲנָשִׁים הָאֲחֵרִים מְצוּיִין בָּעוֹלָם כְּדֵי שֶׁתֵּאָסֵר עֲלֵיהֶן וּמִתּוֹךְ שֶׁתֵּאָסֵר עֲלֵיהֶן יִתְוַסֵּף אִסּוּר אַחֵר לָזֶה. אֲבָל אִם אֵינָן מְצוּיִין אֵין אוֹמְרִין הוֹאִיל אִלּוּ הָיָה לָזֶה בָּנִים אוֹ אַחִים הָיְתָה נֶאֶסְרָה עֲלֵיהֶן יִתְוַסֵּף בָּהּ אִסּוּר לַזָּקֵן. שֶׁהֲרֵי אֵין שָׁם עַתָּה לֹא בֵּן וְלֹא אָח. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","מִי שֶׁהָיָה נָשׂוּי שָׁלֹשׁ נָשִׁים. וּבָא עַל אִמָּהּ שֶׁל אַחַת מֵהֶן שֶׁהִיא אֵם אִמָּהּ שֶׁל שְׁנִיָּה שֶׁהִיא אֵם אָבִיהָ שֶׁל שְׁלִישִׁית. אַף עַל פִּי שֶׁזְּקֵנָה זוֹ הִיא חֲמוֹתוֹ וְאֵם חֲמוֹתוֹ וְאֵם חָמִיו וּשְׁלֹשָׁה שֵׁמוֹת הֵן וְאִסּוּר בַּת אַחַת הִיא אֵינוֹ חַיָּב אֶלָּא חַטָּאת אַחַת לְפִי שֶׁנֶּאֱמַר בְּאִשָּׁה וּבִתָּהּ וּבַת בְּנָהּ וּבַת בִּתָּהּ (ויקרא יח יז) \"שַׁאֲרָה הֵנָּה זִמָּה הִיא\". הַכָּתוּב עָשָׂה שְׁלֹשָׁה גּוּפִין כְּגוּף אֶחָד לְפִיכָךְ יֵחָשְׁבוּ הַשְּׁלֹשָׁה שֵׁמוֹת כְּשֵׁם אֶחָד:","אֲבָל הַבָּא עַל אֲחוֹתוֹ שֶׁהִיא אֲחוֹת אָבִיו וְהִיא אֲחוֹת אִמּוֹ חַיָּב שָׁלֹשׁ חַטָּאוֹת שֶׁנֶּאֱמַר (ויקרא כ יז) \"עֶרְוַת אֲחוֹתוֹ גִּלָּה\". חַיָּב עַל אֲחוֹתוֹ בִּפְנֵי עַצְמָהּ וְאַף עַל פִּי שֶׁהִיא אֲחוֹת אִמּוֹ וַאֲחוֹת אָבִיו. וְהֵיאַךְ תִּהְיֶה זֹאת כְּגוֹן שֶׁבָּא עַל אִמּוֹ וְהוֹלִיד מִמֶּנָּה שְׁתֵּי בָּנוֹת וּבָעַל אַחַת מִבְּנוֹתָיו וְהוֹלִיד מִמֶּנָּה בֵּן. כְּשֶׁיָּבוֹא הַמַּמְזֵר הַזֶּה עַל הַבַּת הַשֵּׁנִית. שֶׁהִיא אֲחוֹת אִמּוֹ הַמַּמְזֶרֶת. שֶׁהִיא אֲחוֹתוֹ מֵאָבִיו. שֶׁהִיא אֲחוֹת אָבִיו מֵאִמּוֹ. חַיָּב שָׁלֹשׁ חַטָּאוֹת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, One Who Injures a Person or Property 7":["הַמַּזִּיק מָמוֹן חֲבֵרוֹ הֶזֵּק שֶׁאֵינוֹ נִכָּר. הוֹאִיל וְלֹא נִשְׁתַּנָּה הַדָּבָר וְלֹא נִפְסְדָה צוּרָתוֹ הֲרֵי זֶה פָּטוּר מִן הַתַּשְׁלוּמִין דִּין תּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים אָמְרוּ הוֹאִיל וְהִפְחִית דְּמֵיהֶן הֲרֵי זֶה חַיָּב וּמְשַׁלֵּם מַה שֶּׁהִפְחִית מִדְּמֵיהֶן:","כֵּיצַד. הֲרֵי שֶׁטִּמֵּא אֳכָלִין טְהוֹרִים שֶׁל חֲבֵרוֹ אוֹ שֶׁדִּמֵּעַ לוֹ פֵּרוֹת אוֹ עֵרֵב לוֹ טִפַּת יֵין נֶסֶךְ בְּתוֹךְ יֵינוֹ שֶׁהֲרֵי אָסַר עָלָיו הַכּל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. שָׁמִין מַה שֶּׁהִפְסִיד וּמְשַׁלֵּם נֵזֶק שָׁלֵם מִן הַיָּפֶה שֶׁבִּנְכָסָיו כְּדֶרֶךְ כָּל הַמַּזִּיקִין:","וְדָבָר זֶה קְנָס הוּא שֶׁקְּנָסוּהוּ חֲכָמִים כְּדֵי שֶׁלֹּא יִהְיֶה כָּל אֶחָד מִן הַמַּשְׁחִיתִים הוֹלֵךְ וּמְטַמֵּא טָהֳרוֹתָיו שֶׁל חֲבֵרוֹ וְאוֹמֵר פָּטוּר אֲנִי. לְפִיכָךְ אִם מֵת זֶה שֶׁהִזִּיק הֶזֵּק שֶׁאֵינוֹ נִכָּר אֵין גּוֹבִין הַנֵּזֶק מִנְּכָסָיו שֶׁלֹּא קָנְסוּ חֲכָמִים אֶלָּא זֶה שֶׁעָבַר וְהִזִּיק. אֲבָל הַיּוֹרֵשׁ שֶׁלֹּא עָשָׂה כְּלוּם לֹא קְנָסוּהוּ. וְכֵן הַמַּזִּיק הֶזֵּק שֶׁאֵינוֹ נִכָּר בִּשְׁגָגָה אוֹ בְּאֹנֶס פָּטוּר שֶׁלֹּא קָנְסוּ אֶלָּא הַמִּתְכַּוֵּן לְהַזִּיק מִדַּעְתּוֹ:","הַכֹּהֲנִים שֶׁפִּגְּלוּ אֶת הַזֶּבַח בְּמֵזִיד חַיָּבִין לְשַׁלֵּם. בְּשׁוֹגֵג פְּטוּרִין. וְכֵן הָעוֹשֶׂה מְלָאכָה בְּפָרַת חַטָּאת וּבְמֵי חַטָּאת בְּמֵזִיד חַיָּב לְשַׁלֵּם. בְּשׁוֹגֵג פָּטוּר:","הִכְנִיס פָּרָה לְמַרְבֵּק כְּדֵי שֶׁתִּינַק וְתָדוּשׁ וְהִסִּיחַ דַּעְתּוֹ מִמֵּי חַטָּאת. פָּטוּר מִדִּינֵי אָדָם וְחַיָּב בְּדִינֵי שָׁמַיִם:","הַמְנַסֵּךְ יֵין חֲבֵרוֹ לַעֲבוֹדָה זָרָה לֹא נֶאֱסַר הַיַּיִן. שֶׁאֵין אָדָם מִיִּשְׂרָאֵל אוֹסֵר דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. וְאִם הָיָה לוֹ בּוֹ שֻׁתָּפוּת. אוֹ שֶׁהָיָה מוּמָר שֶׁהֲרֵי הוּא כְּעַכּוּ\"ם. אוֹ שֶׁהִתְרוּ בּוֹ וְקִבֵּל הַהַתְרָאָה שֶׁהֲרֵי הוּא מוּמָר. הֲרֵי זֶה אוֹסֵר הַיַּיִן וְחַיָּב לְשַׁלֵּם. וְהֵיאַךְ יִתְחַיֵּב זֶה לְשַׁלֵּם וַהֲרֵי הוּא מִתְחַיֵּב בְּנַפְשׁוֹ. מִפְּנֵי שֶׁמֵּעֵת שֶׁהִגְבִּיהוֹ נִתְחַיֵּב לְשַׁלֵּם וְאֵינוֹ מִתְחַיֵּב בְּנַפְשׁוֹ עַד שֶׁיְּנַסֵּךְ:","כָּל הַגּוֹרֵם לְהַזִּיק מָמוֹן חֲבֵרוֹ חַיָּב לְשַׁלֵּם נֵזֶק שָׁלֵם מִן הַיָּפֶה שֶׁבִּנְכָסָיו כִּשְׁאָר הַמַּזִּיקִין. אַף עַל פִּי שֶׁאֵינוֹ הוּא הַמַּזִּיק זֶה הַנֵּזֶק עַצְמוֹ בָּאַחֲרוֹנָה הוֹאִיל וְהוּא הַגּוֹרֵם הָרִאשׁוֹן חַיָּב. כֵּיצַד. הַזּוֹרֵק כְּלִי שֶׁלּוֹ מֵרֹאשׁ הַגַּג עַל גַּבֵּי כָּרִים וּכְסָתוֹת וּבָא אַחֵר וְקָדַם וְסִלֵּק אֶת הַכָּרִים מֵעַל הָאָרֶץ וְנֶחְבַּט הַכְּלִי בָּאָרֶץ וְנִשְׁבַּר חַיָּב נֵזֶק שָׁלֵם כְּאִלּוּ שְׁבָרוֹ בְּיָדוֹ שֶׁסִּלּוּק הַכָּרִים וְהַכְּסָתוֹת גָּרַם לוֹ שֶׁיִּשָּׁבֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַזּוֹרֵק כְּלִי שֶׁל חֲבֵרוֹ מֵרֹאשׁ הַגַּג עַל גַּבֵּי כָּרִים וּכְסָתוֹת שֶׁל בַּעַל הַכְּלִי וְקָדַם בַּעַל הַכְּלִי וְהֵסִיר הַכָּרִים הַזּוֹרֵק חַיָּב שֶׁזְּרִיקָתוֹ הוּא הַגּוֹרֵם הָרִאשׁוֹן לִשְׁבִירַת הַכְּלִי. וְאִם קָדַם אַחֵר וְסִלְּקָן שְׁנֵיהֶן חַיָּבִין הַזּוֹרֵק וְהַמְסַלֵּק שֶׁשְּׁנֵיהֶם גָּרְמוּ לְאַבֵּד מָמוֹנוֹ שֶׁל זֶה:","וְכֵן הַשּׂוֹרֵף שִׁטְרוֹתָיו שֶׁל חֲבֵרוֹ חַיָּב לְשַׁלֵּם כָּל הַחוֹב שֶׁהָיָה בַּשְּׁטָר. שֶׁאַף עַל פִּי שֶׁאֵין גּוּף הַשְּׁטָר מָמוֹן הֲרֵי גָּרַם לְאַבֵּד הַמָּמוֹן. וּבִלְבַד שֶׁיּוֹדֶה לוֹ הַמַּזִּיק שֶׁשְּׁטָר מְקֻיָּם הָיָה וְכָךְ וְכָךְ הָיָה כָּתוּב בּוֹ וּמֵחֲמַת שֶׁשְּׂרָפוֹ הוּא אֵינוֹ יָכוֹל לִגְבּוֹת הַחוֹב. אֲבָל אִם לֹא הֶאֱמִינוֹ אֵינוֹ מְשַׁלֵּם לוֹ אֶלָּא דְּמֵי הַנְּיָר בִּלְבַד:","וְכֵן רְאוּבֵן שֶׁהָיָה נוֹשֶׁה בְּשִׁמְעוֹן וּמָכַר הַשְּׁטָר לְלֵוִי וְחָזַר אַחַר שֶׁמְּכָרוֹ וּמְחָלוֹ לְשִׁמְעוֹן. הֲרֵי נִפְטַר שִׁמְעוֹן כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ וְנִתְחַיֵּב רְאוּבֵן לְשַׁלֵּם לְלֵוִי כָּל מַה שֶּׁבַּשְּׁטָר. שֶׁהֲרֵי גָּרַם לוֹ לְאַבֵּד הַשְּׁטָר וַהֲרֵי הוּא כְּמִי שֶׁשְּׂרָפוֹ. וְכֵן אִם מְחָלוֹ יוֹרֵשׁ רְאוּבֵן מְשַׁלֵּם הַמּוֹחֵל מִן הַיָּפֶה שֶׁבִּנְכָסָיו:","וְכֵן הָעוֹשֶׂה עַבְדּוֹ אַפּוֹתֵיקֵי וְחָזַר וְשִׁחְרְרוֹ חַיָּב הַמְשַׁחְרֵר לְשַׁלֵּם לְבַעַל הַחוֹב שֶׁהֲרֵי הִפְקִיעַ שִׁעְבּוּדוֹ וְגָרַם לְאַבֵּד מָמוֹנוֹ. וְכוֹפִין אֶת בַּעַל חוֹב גַּם הוּא לְשַׁחְרֵר הָעֶבֶד כְּדֵי שֶׁלֹּא יִפְגַּע בּוֹ וְיֹאמַר לוֹ עַבְדִּי אַתָּה. וְכֵן הַדּוֹחֵף מַטְבֵּעַ חֲבֵרוֹ וְנִתְגַּלְגֵּל וְיָרַד לַיָּם חַיָּב לְשַׁלֵּם. וְכֵן הַצּוֹרֵם אֹזֶן הַפָּרָה חַיָּב לְשַׁלֵּם שֶׁהֲרֵי גָּרַם לִפְחוֹת דָּמֶיהָ. וְכֵן הַמְרַקֵּעַ דִּינְרֵי חֲבֵרוֹ וְהֶעֱבִיר צוּרָתָן חַיָּב לְשַׁלֵּם מִשּׁוּם גּוֹרֵם. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הַדְּבָרִים:","הַזּוֹרֵק כְּלִי מֵרֹאשׁ הַגַּג לָאָרֶץ וְלֹא הָיָה תַּחְתָּיו כֵּלִים. וְקָדַם אַחֵר וּשְׁבָרוֹ בְּמַקֵּל כְּשֶׁהוּא בַּאֲוִיר קֹדֶם שֶׁיַּגִּיעַ לָאָרֶץ. הֲרֵי זֶה הָאַחֵר פָּטוּר שֶׁלֹּא שָׁבַר אֶלָּא כְּלִי שֶׁסּוֹפוֹ לְהִשָּׁבֵר מִיָּד בְּוַדַּאי וְנִמְצָא כְּשׁוֹבֵר כְּלִי שָׁבוּר וְאֵין זֶה כְּגוֹרֵם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה פָּטוּר:","שׁוֹר שֶׁהָיָה עוֹמֵד לַהֲרִיגָה מִפְּנֵי שֶׁהוּא מַזִּיק אֶת הַבְּרִיּוֹת. וְאִילָן הָעוֹמֵד לִקְצִיצָה מִפְּנֵי שֶׁהוּא מַזִּיק אֶת הָרַבִּים. וְקָדַם אֶחָד וְשָׁחַט שׁוֹר זֶה וְקָצַץ אִילָן זֶה שֶׁלֹּא מִדַּעַת הַבְּעָלִים. חַיָּב לְשַׁלֵּם לַבְּעָלִים כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים שֶׁהֲרֵי הִפְקִיעָן מִלַּעֲשׂוֹת מִצְוָה. וְאִם טָעַן וְאָמַר אַתָּה אָמַרְתָּ לִי לְהָרְגוֹ וּלְקָצְצוֹ. הוֹאִיל וְהוּא עוֹמֵד לְכָךְ הֲרֵי זֶה פָּטוּר:","וְכֵן מִי שֶׁשָּׁחַט חַיָּה וְעוֹף וּבָא אַחֵר וְכִסָּה הַדָּם שֶׁלֹּא מִדַּעַת הַשּׁוֹחֵט. חַיָּב לִתֵּן כְּמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים. וְיֵשׁ מִי שֶׁהוֹרָה שֶׁהוּא נוֹתֵן קְנָס קָצוּב וְהוּא עֲשָׂרָה זְהוּבִים. וְכֵן הוֹרוּ שֶׁכָּל הַמּוֹנֵעַ הַבְּעָלִים מֵעֲשׂוֹת מִצְוַת עֲשֵׂה שֶׁהֵן רְאוּיִין לַעֲשׂוֹתָהּ וְקָדַם אַחֵר וַעֲשָׂאָהּ מְשַׁלֵּם לַבְּעָלִים עֲשָׂרָה זְהוּבִים:","שָׁמִין לַמַּזִּיק בְּיָדוֹ כְּדֶרֶךְ שֶׁשָּׁמִין לוֹ אִם הִזִּיק מָמוֹנוֹ. כֵּיצַד. הֲרֵי שֶׁהָרַג בֶּהֱמַת חֲבֵרוֹ אוֹ שָׁבַר כֵּלָיו שָׁמִין כַּמָּה הָיְתָה הַבְּהֵמָה שָׁוָה וְכַמָּה הַנְּבֵלָה שָׁוָה. וְכַמָּה הָיָה הַכְּלִי שָׁוֶה וְהוּא שָׁלֵם וְכַמָּה שָׁוֶה עַתָּה. וּמְשַׁלֵּם הַפְּחָת לַנִּזָּק עִם הַנְּבֵלָה אוֹ הַכְּלִי הַשָּׁבוּר. כְּדֶרֶךְ שֶׁבֵּאַרְנוּ בְּשׁוֹרוֹ שֶׁהִזִּיק שֶׁדִּין אֶחָד הוּא. דָּרַךְ עֲנָבִים שֶׁל חֲבֵרוֹ שָׁמִין לוֹ הֶזֵּקוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כְּשֶׁגּוֹבִין הַפְּחָת מִן הַמַּזִּיק גּוֹבִין מִן הַמִּטַּלְטְלִין שֶׁלּוֹ. אִם אֵין לוֹ מִטַּלְטְלִין גּוֹבִין מִן הַיָּפֶה שֶׁבִּנְכָסָיו. וְכֵן הָאוֹנֵס וְהַמְפַתֶּה וְהַמּוֹצִיא שֵׁם רַע כֻּלָּן גּוֹבִין מֵהֶן מִן הַיָּפֶה שֶׁבִּנְכָסָיו:","כָּל הַמַּזִּיק מָמוֹן חֲבֵרוֹ וְאֵינוֹ יוֹדֵעַ מַה הִזִּיק. הֲרֵי הַנִּזָּק נִשְׁבַּע בְּתַקָּנַת חֲכָמִים וְנוֹטֵל כְּמוֹ שֶׁיִּטְעֹן הַנִּגְזָל. וְהוּא שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶן כְּמוֹ שֶׁבֵּאַרְנוּ בְּנִגְזָל:","כֵּיצַד. לָקַח כִּיס חֲבֵרוֹ וְהִשְׁלִיכוֹ לַיָּם אוֹ לָאֵשׁ. אוֹ שֶׁמְּסָרוֹ בְּיַד אַנָּס וְאָבַד. בַּעַל הַכִּיס אוֹמֵר זְהוּבִים הָיָה מָלֵא וְהַמַּזִּיק אוֹמֵר אֵינִי יוֹדֵעַ מֶה הָיָה בּוֹ שֶׁמָּא עָפָר אוֹ תֶּבֶן הָיָה מָלֵא. הֲרֵי הַנִּזָּק נִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל. וְהוּא שֶׁיִּטְעֹן דְּבָרִים שֶׁהוּא אָמוּד בָּהֶן אוֹ אָמוּד לְהַפְקִידָן אֶצְלוֹ וְדַרְכָּן לְהַנִּיחָן בַּכִּיס וְכַיּוֹצֵא בּוֹ. אֲבָל אִם אֵין דַּרְכָּן לְהַנִּיחָן בִּכְלִי זֶה הוּא פָּשַׁע בְּעַצְמוֹ. כֵּיצַד. הֲרֵי שֶׁחָטַף חֵמֶת אוֹ סַל מְלֵאִים וּמְחֻפִּים וְהִשְׁלִיכָם לַיָּם אוֹ שְׂרָפָן. וְטָעַן הַנִּזָּק שֶׁמַּרְגָּלִיּוֹת הָיוּ בְּתוֹכָן. אֵינוֹ נֶאֱמָן וְאֵין מַשְׁבִּיעִין אוֹתוֹ עַל כָּךְ. שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְהַנִּיחַ מַרְגָּלִיּוֹת בְּסַלִּים וּבַחֲמָתוֹת. וְאִם תָּפַשׂ אֵין מוֹצִיאִין מִיָּדוֹ. אֶלָּא נִשְׁבָּע שֶׁמַּרְגָּלִיּוֹת הָיוּ בָּהּ וְנוֹטֵל מִמַּה שֶּׁיֵּשׁ אֶצְלוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יָדַע הַמַּזִּיק שֶׁהַכִּיס הָיָה בּוֹ זְהוּבִים אֲבָל אֵינוֹ יוֹדֵעַ כַּמָּה הָיוּ. וְאוֹמֵר הַנִּזָּק אֶלֶף הָיוּ. נוֹטֵל אֶלֶף בְּלֹא שְׁבוּעָה. וְאֵינוֹ יָכוֹל לְהִשָּׁבַע כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן הַפִּקָּדוֹן:"],"Mishneh Torah, Other Sources of Defilement 19":["שְׁנֵּי שְׁבִילִין אֶחָד טָמֵא וְאֶחָד טָהוֹר הָלַךְ בְּאֶחָד מִהן וְאֵין יָדוּעַ בְּאֵי זֶה מֵהֶן הָלַךְ וְעָשָׂה טָהֳרוֹת וְנֶאֶכְלוּ וְהִזָּה שְׁלִישִׁי וּשְׁבִיעִי וְטָבַל וְטָהַר וְהָלַךְ בַּשֵּׁנִי וְעָשָׂה טָהֳרוֹת הֲרֵי אֵלּוּ טְהוֹרוֹת. אִם קַיָּמוֹת הָרִאשׁוֹנוֹת אֵלּוּ וְאֵלּוּ תְּלוּיוֹת שֶׁבְּוַדַּאי שֶׁאֶחָד מִן הַטָּהֳרוֹת טָמֵא. וְאִם לֹא טָהַר בֵּינְתַיִם הָרִאשׁוֹנוֹת תְּלוּיוֹת וְהַשְּׁנִיּוֹת יִשָּׂרְפוּ שֶׁהֲרֵי הֵן טְמֵאוֹת בְּוַדַּאי שֶׁזֶּה טָמֵא הוּא מִפְּנֵי שֶׁהָלַךְ בִּשְׁנֵי הַשְּׁבִילִין. וְכֵן הַשֶּׁרֶץ וְהַצְּפַרְדֵּעַ בִּרְשׁוּת הָרַבִּים וְאֵין צוּרָתָן נִכֶּרֶת וְאֵין יָדוּעַ אֵי זֶהוּ הַשֶּׁרֶץ וְנָגַע בְּאֶחָד מֵהֶן וְעָשָׂה טָהֳרוֹת וְנֶאֶכְלוּ וְטָבַל וְנָגַע בַּשֵּׁנִי וְעָשָׂה טָהֳרוֹת הֲרֵי אֵלּוּ טְהוֹרוֹת. וְאִם קַיָּמוֹת הָרִאשׁוֹנוֹת אֵלּוּ וְאֵלּוּ תְּלוּיוֹת. וְאִם לֹא טָבַל בֵּינְתַיִם הָרִאשׁוֹנוֹת תְּלוּיוֹת וְהַשְּׁנִיּוֹת יִשָּׂרְפוּ:","שְׁנֵי שְׁבִילִין אֶחָד טָמֵא וְאֶחָד טָהוֹר הָלַךְ בְּאֶחָד מֵהֶן וְעָשָׂה טָהֳרוֹת וּבָא חֲבֵרוֹ וְהָלַךְ בַּשֵּׁנִי וְעָשָׂה טָהֳרוֹת אִם בָּאוּ וְנִשְׁאֲלוּ זֶה אַחַר זֶה מוֹרִין לְכָל אֶחָד מֵהֶן בִּפְנֵי עַצְמוֹ שֶׁהוּא טָהוֹר. בָּאוּ שְׁנֵיהֶן כְּאֶחָד אוֹ שֶׁבָּא הָאֶחָד וְשָׁאַל עָלָיו וְעַל חֲבֵרוֹ וְאָמַר שְׁנַיִם הָיִינוּ וּבִשְׁנֵי הַשְּׁבִילִים הָלַכְנוּ וּשְׁתֵּי טָהֳרוֹת עָשִׂינוּ הֲרֵי שְׁנֵיהֶם טְמֵאִין וְטָהֳרוֹת שֶׁעָשׂוּ נִשְׂרָפוֹת. וְכֵן אִם נִטְמְאוּ בְּטֻמְאָה קַלָּה. כֵּיצַד. שְׁנֵי כִּכָּרִים אֶחָד טָמֵא וְאֶחָד טָהוֹר אָכַל אֶת אֶחָד מֵהֶם וְעָשָׂה טָהֳרוֹת וּבָא חֲבֵרוֹ וְאָכַל אֶת הַשֵּׁנִי וְעָשָׂה טָהֳרוֹת אִם נִשְׁאֲלוּ זֶה אַחַר זֶה שְׁנֵיהֶן טְהוֹרִין מִפְּנֵי שֶׁהֵן סָפֵק דִּבְרֵי סוֹפְרִים שֶׁהוּא מִכְּלַל הַסְּפֵקוֹת שֶׁטִּהֲרוּ חֲכָמִים כְּמוֹ שֶׁבֵּאַרְנוּ. נִשְׁאֲלוּ שְׁנֵיהֶן כְּאַחַת אוֹ שֶׁנִּשְׁאַל עָלָיו וְעַל חֲבֵרוֹ שְׁנֵיהֶן טְמֵאִין מִסָּפֵק וְטָהֳרוֹתָם נִשְׂרָפוֹת שֶׁהֲרֵי וַדַּאי אַחַת מֵהֶן טְמֵאָה. וַאֲפִלּוּ כִּכָּר אֶחָד טָמֵא שֶׁנִּתְעָרֵב בְּמֵאָה כִּכָּרוֹת טְהוֹרִין כֻּלָּן טְמֵאִין וְיִשָּׂרְפוּ:","כִּכָּר טָמֵא שֶׁנִּתְעָרֵב בְּתִשְׁעָה כִּכָּרוֹת טְהוֹרִין וּבָאוּ חֲמִשָּׁה בְּנֵי אָדָם וְאָכְלוּ חֲמִשָּׁה כִּכָּרוֹת מֵהֶן וּבָאוּ חֲמִשָּׁה בְּנֵי אָדָם אֲחֵרִים וְאָכְלוּ הַחֲמִשָּׁה הַנִּשְׁאָרִים הָרִאשׁוֹנִים טְמֵאִים מִפְּנֵי שֶׁאֵין לָהֶן אֲנָשִׁים אֲחֵרִים שֶׁיִּתְלוּ בָּהֶן וְהַחֲמִשָּׁה הָאֲנָשִׁים הָאַחֲרוֹנִים טְהוֹרִין מִפְּנֵי שֶׁהֵן תּוֹלִין בָּרִאשׁוֹנִים:","שְׁנֵי שְׁבִילִין אֶחָד טָמֵא וְאֶחָד טָהוֹר וְהָלְכוּ בָּהֶן שְׁנֵי אֲנָשִׁים אִישׁ אֶחָד טָהוֹר וְאִישׁ אֶחָד טָמֵא אֲפִלּוּ הָיָה הָאֶחָד תָּלוּי הֲרֵי זֶה הַטָּהוֹר תּוֹלֶה בַּתָּלוּי וְאוֹמְרִין זֶה הַטָּהוֹר הָלַךְ בַּשְּׁבִיל הַטָּהוֹר וַהֲרֵי הוּא בְּטָהֳרָתוֹ וְזֶה הַתָּלוּי הָלַךְ בַּשְּׁבִיל הַטָּמֵא. וְאַף עַל פִּי שֶׁנִּשְׁאֲלוּ שְׁנֵיהֶן כְּאֶחָד:"],"Mishneh Torah, Overview of Mishneh Torah Contents 11":["ספר נזקים","הלכותיו חמש, וזה הוא סידורן: הלכות נזקי ממון, הלכות גניבה, הלכות גזילה ואבידה, הלכות חובל ומזיק, הלכות רוצח ושמירת נפש.","הלכות נזקי ממון. יש בכללן ארבע מצוות עשה; וזה הוא פרטן: (א) דין השור; (ב) דין ההבער; (ג) דין הבור; (ד) דין הבעירה.","הלכות גניבה. יש בכללן שבע מצוות – שתי מצוות עשה, וחמש מצוות לא תעשה; וזה הוא פרטן: (א) שלא לגנוב ממון; (ב) דין הגנב; (ג) לצדק המאזניים עם המשקלות; (ד) שלא יעשה עוול במידות ובמשקלות; (ה) שלא יהיה לאדם אבן ואבן איפה ואיפה, אף על פי שאינו לוקח ונותן בהם; (ו) שלא יסיג גבול; (ז) שלא לגנוב נפשות.","הלכות גזילה ואבידה. יש בכללן שבע מצוות – שתי מצוות עשה, וחמש מצוות לא תעשה; וזה הוא פרטן: (א) שלא לגזול; (ב) שלא לעשוק; (ג) שלא לחמוד; (ד) שלא להתאוות; (ה) להשיב את הגזילה; (ו) שלא יתעלם מן האבידה; (ז) להשיב האבידה.","הלכות חובל ומזיק. מצות עשה אחת, והוא דין חובל בחברו או מזיק ממון חברו.","הלכות רוצח ושמירת נפש. יש בכללן שבע עשרה מצוות – שבע מצוות עשה, ועשר מצוות לא תעשה; וזה הוא פרטן: (א) שלא לרצוח; (ב) שלא ליקח כופר לנפש רוצח, אלא יומת; (ג) להגלות הרוצח בשגגה; (ד) שלא ליקח כופר למחוייב גלות; (ה) שלא יומת הרוצח כשירצח, קודם עמידה בדין; (ו) להציל הנרדף בנפשו של רודף; (ז) שלא לחוס על הרודף; (ח) שלא לעמוד על דם; (ט) להפריש ערי מקלט ולהכין להם הדרך; (י) לערוף את העגלה בנחל; (יא) שלא יעבוד באותה קרקע ולא תיזרע; (יב) שלא לשים דמים; (יג) לעשות מעקה; (יד) שלא יכשיל תמים בדבר; (טו) לפרוק עם מי שנכשל בדרך; (טז) לטעון עימו; (יז) שלא יניחנו בדרך נבהל במשאו וילך לו.","נמצאו כל המצוות הנכללות בספר זה, שש ושלושים – מהן שש עשרה מצוות עשה, ועשרים מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 1":["הַהֶפְקֵר כָּל הַמַּחֲזִיק בּוֹ זָכָה. וְכֵן הַמִּדְבָּרוֹת וְהַנְּהָרוֹת וְהַנְּחָלִים כָּל שֶׁבָּהֶן הֶפְקֵר וְכָל הַקּוֹדֵם בָּהֶן זָכָה. כְּגוֹן הָעֲשָׂבִים וְהָעֵצִים וְהַפֵּרוֹת שֶׁל אִילָנוֹת שֶׁל יַעַר וְכַיּוֹצֵא בָּהֶן:","הַצָּד דָּגִים מִן הַיָּמִים וּמִן הַנְּהָרוֹת. אוֹ שֶׁצָּד עוֹפוֹת אוֹ מִינֵי חַיּוֹת. הוֹאִיל וְאֵין לָהֶם בְּעָלִים זָכָה. וּבִלְבַד שֶׁלֹּא יָצוּד בִּשְׂדֵה חֲבֵרוֹ. וְאִם צָד שָׁם קָנָה. וְאִם הָיוּ הַדָּגִים בַּבֵּיבָרִים שֶׁל בְּעָלִים וְכֵן חַיָּה וְעוֹף שֶׁבַּבֵּיבָרִים. אַף עַל פִּי שֶׁהוּא בֵּיבָר גָּדוֹל וְהוּא מְחֻסַּר צִידָה הֲרֵי זֶה שֶׁל בַּעַל הַבֵּיבָרִים וְהַצָּד מִשָּׁם הֲרֵי זֶה גַּזְלָן:","אֲבָל הַלּוֹקֵחַ דָּגִים מִתּוֹךְ מְצוּדָתוֹ שֶׁל חֲבֵרוֹ כְּשֶׁהוּא בְּתוֹךְ הַיָּם. אוֹ שֶׁלָּקַח חַיָּה מִמְּצוּדָתוֹ כְּשֶׁהִיא פְּרוּסָה בַּמִּדְבָּר הֲרֵי זֶה אָסוּר מִדִּבְרֵי סוֹפְרִים. וְאִם הָיָה הַמְּצוּדָה כְּלִי וְלָקַח מִתּוֹךְ הַמְּצוּדָה הֲרֵי זֶה גַּזְלָן:","הַפּוֹרֵס מְצוּדָה בִּשְׂדֵה חֲבֵרוֹ וְצָד בָּהּ חַיָּה אוֹ עוֹף אַף עַל פִּי שֶׁאֵין לוֹ רְשׁוּת לַעֲשׂוֹת דָּבָר זֶה קָנָה. וְאִם הָיָה עוֹמֵד בַּעַל הַשָּׂדֶה בְּתוֹךְ שָׂדֵהוּ וְאָמַר זָכְתָה לִי שָׂדִי קָנָה בַּעַל הַשָּׂדֶה. וְאֵין לְבַעַל הַמְּצוּדָה כְּלוּם:","דָּגִים שֶׁקָּפְצוּ לְתוֹךְ הַסְּפִינָה קָנָה בַּעַל הַסְּפִינָה. שֶׁזּוֹ כְּחָצֵר הַמִּשְׁתַּמֶּרֶת הִיא וְאֵינָהּ חָצֵר הַמְהַלֶּכֶת. שֶׁהַמַּיִם הֵן שֶׁמּוֹלִיכִין אוֹתָהּ וְאֵינָהּ הוֹלֶכֶת מֵחֲמַת עַצְמָהּ:","גֵּר שֶׁמֵּת וְלֹא הוֹלִיד יִשְׂרָאֵל אַחַר שֶׁנִּתְגַּיֵּר אֵין לוֹ יוֹרְשִׁין אֶלָּא כָּל הַקּוֹדֵם וְהֶחֱזִיק בִּנְכָסָיו זָכָה. וְאֵין בַּעַל הַמֵּצַר יָכוֹל לְסַלְּקוֹ בְּדָמִים שֶׁזּוֹ כְּמַתָּנָה הִיא:","שְׁתֵּי שָׂדוֹת בְּנִכְסֵי הַגֵּר וּמֵצַר אֶחָד בֵּינֵיהֶן. הֶחֱזִיק בְּאַחַת מֵהֶן לִקְנוֹתָהּ קְנָאָהּ. הֶחֱזִיק בָּהּ לִקְנוֹת אוֹתָהּ וְאֶת חֲבֶרְתָּהּ. זוֹ שֶׁהֶחְזִיק בָּהּ קָנָה אֲבָל חֲבֶרְתָּהּ לֹא קָנָה. הֶחֱזִיק בָּהּ כְּדֵי לִקְנוֹת אֶת חֲבֶרְתָּהּ לֹא קָנָה אַחַת מֵהֶן. חֲבֶרְתָּהּ מִפְּנֵי שֶׁלֹּא הֶחֱזִיק בָּהּ. וְאוֹתָהּ מִפְּנֵי שֶׁלֹּא הֶחֱזִיק בָּהּ כְּדֵי לִקְנוֹתָהּ. הֶחֱזִיק בָּהּ כְּדֵי לִקְנוֹתָהּ וְלִקְנוֹת אֶת חֲבֶרְתָּהּ וְאֶת הַמֵּצַר שֶׁבֵּינֵיהֶן. אוֹ שֶׁהֶחְזִיק בַּמֵּצַר לִקְנוֹת שְׁתֵּיהֶן הֲרֵי זֶה סָפֵק. וְאִם בָּא אֶחָד וְהֶחֱזִיק בָּהּ כְּדֵי לִקְנוֹתָהּ זָכָה הָאַחֲרוֹן:","וְכֵן שְׁנֵי בָּתִּים זֶה לְפָנִים מִזֶּה שֶׁהֶחְזִיק בְּאֶחָד מֵהֶן לִקְנוֹתוֹ וְלִקְנוֹת אֶת הַשֵּׁנִי לֹא קָנָה אֶלָּא זֶה שֶׁהֶחְזִיק בּוֹ בִּלְבַד. הֶחֱזִיק בְּאֶחָד מֵהֶן כְּדֵי לִקְנוֹת אֶת הַשֵּׁנִי אַף זֶה שֶׁהֶחְזִיק בּוֹ לֹא קָנָה:","הַמַּחֲזִיק בִּשְׁטָר מִנִּכְסֵי הַגֵּר כְּדֵי לִקְנוֹת אֶת הַקַּרְקַע הַכְּתוּבָה בְּאוֹתוֹ שְׁטָר לֹא קָנָה אֶלָּא הַשְּׁטָר בִּלְבַד לָצוּר עַל פִּי צְלוֹחִיתוֹ וְכַיּוֹצֵא בָּזֶה:","שָׂדֶה הַמְצֻיֶּנֶת בִּמְצָרֶיהָ כֵּיוָן שֶׁהִכִּישׁ בָּהּ מַכּוֹשׁ אֶחָד קָנָה אֶת כֻּלָּהּ. וְאִם אֵינָהּ מְצֻיֶּנֶת בִּמְצָרֶיהָ קוֹנֶה מִמֶּנָּה בְּאוֹתוֹ מַכּוֹשׁ כְּדֵי שֶׁיֵּלֵךְ הַצֶּמֶד בִּשְׁעַת חֲרִישָׁה וְיַחְזֹר. הַמֵּצַר וְהֶחָצָב שֶׁמְּתַחֲמִין בּוֹ תְּחוּמִין מַפְסִיקִין בְּנִכְסֵי הַגֵּר. וְכָל הַמַּחֲזִיק בְּשָׂדֶה לֹא קָנָה אֶלָּא עַד הַמֵּצַר אוֹ עַד הֶחָצָב:","כָּל הַמַּפְסִיק לְפֵאָה מַפְסִיק בְּנִכְסֵי הַגֵּר. כֵּיצַד. הָיָה שָׁם נַחַל אוֹ אַמַּת הַמַּיִם וְכַיּוֹצֵא בָּהֶן לֹא קָנָה אֶלָּא עַד הַנַּחַל אוֹ עַד הָאַמָּה. וְכָל הַמַּפְסִיק בִּרְשׁוּת שַׁבָּת מַפְסִיק בְּנִכְסֵי הַגֵּר כְּגוֹן שֶׁהָיָה בֵּין שְׁתֵּי הַשָּׂדוֹת רְשׁוּת הַיָּחִיד אוֹ כַּרְמְלִית אֲפִלּוּ הָיָה בֵּינֵיהֶם רְשׁוּת שֶׁחוֹלֶקֶת לְגִטִּין:","כָּל דָּבָר הַמַּפְסִיק לְטֻמְאָה מַפְסִיק בְּנִכְסֵי הַגֵּר. כֵּיצַד. כְּגוֹן שֶׁנִּכְנַס אָדָם לְבִקְעָה זוֹ וְטֻמְאָה בַּבִּקְעָה בְּצִדָּהּ אַחֶרֶת וְאֵינוֹ יוֹדֵעַ אִם הִגִּיעַ לִמְקוֹם הַטֻּמְאָה אִם לָאו. כָּל מָקוֹם שֶׁמַּחֲזִיקִין אוֹתוֹ לְטֻמְאָה הֲרֵי הוּא כְּמָקוֹם אַחֵר, מֻחְלָק בִּפְנֵי עַצְמוֹ:","בִּקְעָה גְּדוֹלָה שֶׁיֵּשׁ בָּהּ שָׂדוֹת רַבּוֹת וְכֻלָּן שֶׁל גֵּר אֶחָד וְלֹא הָיָה בֵּינֵיהֶן לֹא מֵצַר וְלֹא חָצָב וְלֹא דָּבָר מִדְּבָרִים הַמַּפְסִיקִין. וּבָא אֶחָד וְהֶחֱזִיק בְּמִקְצָת הַבִּקְעָה לִקְנוֹת אֶת כֻּלָּהּ. כָּל הַנִּקְרָא עַל שֵׁם אוֹתוֹ הַגֵּר קוֹנֶה אוֹתוֹ:","עַכּוּ\"ם שֶׁמָּכַר מִטַּלְטְלִין לְיִשְׂרָאֵל אוֹ קָנָה מִטַּלְטְלִין מִיִּשְׂרָאֵל. קוֹנֶה בִּמְשִׁיכָה וּמַקְנֶה בִּמְשִׁיכָה אוֹ בְּדָמִים. אֲבָל הַקַּרְקַע אֵינוֹ קוֹנֶה אוֹתוֹ מִיִּשְׂרָאֵל אֶלָּא בִּשְׁטָר וְאֵינוֹ מַקְנֶה אוֹתוֹ לְיִשְׂרָאֵל אֶלָּא בִּשְׁטָר שֶׁאֵין דַּעְתּוֹ סוֹמֶכֶת אֶלָּא עַל הַשְּׁטָר. לְפִיכָךְ יִשְׂרָאֵל שֶׁלָּקַח שָׂדֶה מִן הָעַכּוּ\"ם וְנָתַן הַדָּמִים. וְקֹדֶם שֶׁיַּחְזִיק בָּהּ בָּא יִשְׂרָאֵל אַחֵר וְהֶחֱזִיק בָּהּ כְּדֶרֶךְ שֶׁמַּחֲזִיקִין בְּנִכְסֵי הַגֵּר זָכָה אַחֲרוֹן וְנוֹתֵן לָרִאשׁוֹן אֶת הַדָּמִים. מִפְּנֵי שֶׁהָעַכּוּ\"ם מֵעֵת שֶׁלָּקַח הַדָּמִים סִלֵּק רְשׁוּתוֹ וְיִשְׂרָאֵל לֹא קָנָה עַד שֶׁיַּגִּיעַ הַשְּׁטָר לְיָדוֹ. וְנִמְצְאוּ נְכָסִים אֵלּוּ כְּנִכְסֵי מִדְבָּר שֶׁכָּל הַמַּחֲזִיק בָּהֶן זָכָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁאֵין מִשְׁפָּט יָדוּעַ לַמֶּלֶךְ. אֲבָל אִם דִּין אוֹתוֹ הַמֶּלֶךְ וּמִשְׁפָּטוֹ שֶׁלֹּא יִזְכֶּה בַּקַּרְקַע אֶלָּא מִי שֶׁכּוֹתֵב בִּשְׁטָר אוֹ הַנּוֹתֵן דָּמִים וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ. עוֹשִׂין כְּפִי מִשְׁפַּט הַמֶּלֶךְ. שֶׁכָּל דִּינֵי הַמֶּלֶךְ בְּמָמוֹן עַל פִּיהֶן דָּנִין:"],"Mishneh Torah, Paschal Offering 1":["מִצְוַת עֲשֵׂה לִשְׁחֹט אֶת הַפֶּסַח בְּאַרְבָּעָה עָשָׂר לְחֹדֶשׁ נִיסָן אַחַר חֲצוֹת. וְאֵין שׁוֹחֲטִין אֶלָּא מִן הַכְּבָשִׂים אוֹ מִן הָעִזִּים בִּלְבַד זָכָר בֶּן שָׁנָה. וְאֶחָד הָאִישׁ וְאֶחָד הָאִשָּׁה חַיָּבִין בְּמִצְוָה זוֹ:","ומִי שֶׁבִּטֵּל מִצְוָה זוֹ בְּזָדוֹן וְעָבַר יוֹם אַרְבָּעָה עָשָׂר וְלֹא הִקְרִיב וְהוּא לֹא טָמֵא וְלֹא בַּדֶּרֶךְ רְחוֹקָה הֲרֵי זֶה חַיָּב כָּרֵת. וְאִם בִּטְּלָהּ בִּשְׁגָגָה פָּטוּר:","אֵין שׁוֹחֲטִין אֶת הַפֶּסַח אֶלָּא בַּעֲזָרָה כִּשְׁאָר הַקָּדָשִׁים. אַף בִּשְׁעַת הֶתֵּר הַבָּמוֹת לֹא הָיוּ מַקְרִיבִין אֶת הַפֶּסַח בְּבָמַת יָחִיד [ב.] וְכָל הַמַּקְרִיב אֶת הַפֶּסַח בְּבָמַת יָחִיד לוֹקֶה [ג.] שֶׁנֶּאֱמַר (דברים טז ה) \"לֹא תוּכַל לִזְבֹּחַ אֶת הַפָּסַח בְּאַחַד שְׁעָרֶיךָ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לַשּׁוֹחֵט בְּבָמַת יָחִיד אֲפִלּוּ בִּשְׁעַת הֶתֵּר הַבָּמוֹת:","שְׁחִיטַת הַפֶּסַח אַחַר חֲצוֹת. וְאִם שְׁחָטוֹ קֹדֶם חֲצוֹת פָּסוּל. וְאֵין שׁוֹחֲטִין אוֹתוֹ אֶלָּא אַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. אַחַר שֶׁמַּקְטִירִין קְטֹרֶת שֶׁל בֵּין הָעַרְבַּיִם וְאַחַר שֶׁמֵּיטִיבִין אֶת הַנֵּרוֹת מַתְחִילִין לִשְׁחֹט אֶת הַפְּסָחִים עַד סוֹף הַיּוֹם. וְאִם שְׁחָטוֹ אַחַר חֲצוֹת קֹדֶם תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם כָּשֵׁר וְיִהְיֶה אֶחָד מְמָרֵס בְּדַם הַפֶּסַח עַד שֶׁיִּזָּרֵק דַּם הַתָּמִיד וְאַחַר כָּךְ יִזְרֹק דַּם הַפֶּסַח אַחֲרָיו. וְאִם נִזְרַק דַּם הַפֶּסַח קֹדֶם דַּם הַתָּמִיד כָּשֵׁר:","הַשּׁוֹחֵט אֶת הַפֶּסַח בִּזְמַנּוֹ וְהָיָה לוֹ כְּזַיִת חָמֵץ בִּרְשׁוּתוֹ לוֹקֶה. שֶׁנֶּאֱמַר (שמות כג יח) \"לֹא תִזְבַּח עַל חָמֵץ דַּם זִבְחִי\". שֶׁלֹּא יִזְבַּח הַפֶּסַח וְהֶחָמֵץ קַיָּם. אֶחָד הַשּׁוֹחֵט וְאֶחָד הַזּוֹרֵק אֶת הַדָּם וְאֶחָד הַמַּקְטִיר אֶת הָאֵימוּרִין אִם הָיָה בִּרְשׁוּת אֶחָד מֵהֶם אוֹ בִּרְשׁוּת אֶחָד מִבְּנֵי חֲבוּרָה שֶׁאוֹכְלִין פֶּסַח זֶה כְּזַיִת חָמֵץ בִּשְׁעַת הַקְרָבָתוֹ הֲרֵי זֶה לוֹקֶה וְהַפֶּסַח כָּשֵׁר:","דַּם הַפֶּסַח טָעוּן שְׁפִיכָה כְּנֶגֶד הַיְסוֹד. וְאַחַר שֶׁשּׁוֹפְכִים דָּמוֹ מַפְשִׁיטִים אוֹתוֹ וְקוֹרְעִין אֶת בִּטְנוֹ וּמוֹצִיאִין אֶת אֵימוּרָיו וּמַקְטִירִין אוֹתָן חֲלָבִין כָּל זֶבַח וְזֶבַח לְבַדּוֹ. וּבַעַל הַזֶּבַח נוֹטֵל פִּסְחוֹ עִם הָעוֹר שֶׁלּוֹ וּמֵבִיא לְבֵיתוֹ לִירוּשָׁלַיִם וְצוֹלֵהוּ וְאוֹכֵל לָעֶרֶב:","הַמַּנִּיחַ אֵימוּרִים וְלֹא הִקְטִירָן עַד שֶׁלָּנוּ וְנִפְסְלוּ בְּלִינָה הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה. שֶׁנֶּאֱמַר (שמות כג יח) \"לֹא יָלִין חֵלֶב חַגִּי עַד בֹּקֶר\". וְאַף עַל פִּי שֶׁעָבַר אֵינוֹ לוֹקֶה לְפִי שֶׁאֵין בּוֹ מַעֲשֶׂה:","וּמַקְטִירִין חֶלְבֵי פְּסָחִים כָּל הַלַּיְלָה עַד שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁחָל אַרְבָּעָה עָשָׂר לִהְיוֹת בְּשַׁבָּת שֶׁהֲרֵי חֶלְבֵי שַׁבָּת קְרֵבִין בְּיוֹם טוֹב. אֲבָל אִם חָל אַרְבָּעָה עָשָׂר לִהְיוֹת בְּחל אֵין מַקְטִירִין חֶלְבֵי חֹל בְּיוֹם טוֹב:","הַפֶּסַח נִשְׁחָט בְּשָׁלֹשׁ כִּתּוֹת. שֶׁנֶּאֱמַר (שמות יב ו) \"וְשָׁחֲטוּ אֹתוֹ כּל קְהַל עֲדַת יִשְׂרָאֵל\". קָהָל. וְעֵדָה. וְיִשְׂרָאֵל. וְאֵין פּוֹחֲתִין מִשְּׁלֹשִׁים בְּנֵי אָדָם בְּכָל כַּת וְכַת:","הָיוּ הַכּל חֲמִשִּׁים. נִכְנָסִים בַּתְּחִלָּה שְׁלֹשִׁים וְשׁוֹחֲטִין. וְיוֹצְאִים עֲשָׂרָה וְנִכְנָסִין עֲשָׂרָה. וְחוֹזְרִין וְיוֹצְאִין עֲשָׂרָה וְנִכְנָסִין עֲשָׂרָה:","הָיוּ פָּחוֹת מֵחֲמִשִּׁים אֵין שׁוֹחֲטִין אֶת הַפֶּסַח לְכַתְּחִלָּה [וְאִם שָׁחֲטוּ כָּשֵׁר]. וְאִם שָׁחֲטוּ כֻּלָּן בְּבַת אַחַת כָּשֵׁר. כֵּיצַד נִשְׁחָט. נִכְנְסָה הַכַּת הָרִאשׁוֹנָה עַד שֶׁתִּתְמַלֵּא הָעֲזָרָה וְנוֹעֲלִין דַּלְתוֹת הָעֲזָרָה וּמַתְחִילִין לִשְׁחֹט אֶת פִּסְחֵיהֶן. וְכָל זְמַן שֶׁהֵן שׁוֹחֲטִין וּמַקְרִיבִין קוֹרְאִים הַלְּוִיִּים אֶת הַהַלֵּל. אִם גָּמְרוּ הַהַלֵּל וַעֲדַיִן לֹא שָׁלְמָה הַכַּת מִלְּהַקְרִיב שׁוֹנִים. וְאִם שָׁנוּ וְלֹא שָׁלְמוּ לְהַקְרִיב מְשַׁלְּשִׁין. וּמֵעוֹלָם לֹא שִׁלְּשׁוּ:","עַל כָּל קְרִיאָה וּקְרִיאָה תּוֹקְעִין שָׁלֹשׁ תְּקִיעוֹת בַּחֲצוֹצְרוֹת. תְּקִיעָה תְּרוּעָה וּתְקִיעָה. הוֹאִיל וְאֵין לוֹ נְסָכִים לִתְקֹעַ בִּשְׁעַת נִסּוּךְ תּוֹקְעִין בִּשְׁעַת שְׁחִיטָה:","הַכֹּהֲנִים עוֹמְדִים שׁוּרוֹת שׁוּרוֹת וּבִידֵיהֶן מִזְרְקֵי כֶּסֶף וּמִזְרְקֵי זָהָב. שׁוּרָה שֶׁכֻּלָּהּ כֶּסֶף כֶּסֶף. שׁוּרָה שֶׁכֻּלָּהּ זָהָב זָהָב. וְלֹא הָיוּ מְעֹרָבִים כְּדֵי שֶׁיִּהְיֶה לָהֶם נוֹי. וְלֹא הָיוּ לַמִּזְרָקִין שׁוּלַיִם כְּדֵי שֶׁלֹּא יַנִּיחוּם וְיִקְרַשׁ הַדָּם:","שָׁחַט הַשּׁוֹחֵט וְקִבֵּל הַכֹּהֵן. נוֹתְנוֹ לַחֲבֵרוֹ וַחֲבֵרוֹ לַחֲבֵרוֹ כְּדֵי שֶׁיִּתְעַסְּקוּ רַבִּים בַּמִּצְוָה עַד שֶׁיַּגִּיעַ הַדָּם אֵצֶל כֹּהֵן הַקָּרוֹב לַמִּזְבֵּחַ. שׁוֹפְכוֹ שְׁפִיכָה אַחַת כְּנֶגֶד הַיְסוֹד וּמְקַבֵּל מִזְרָק אֶחָד מָלֵא וְאַחַר כָּךְ מַחְזִיר אֶת הָרֵיקָן. וְתוֹלִין וּמַפְשִׁיטִין אֶת כֻּלּוֹ וְקוֹרְעוֹ וּמְמַחֶה אֶת קְרָבָיו עַד שֶׁמֵּסִיר מֵהֶן הַצּוֹאָה וְהַפֶּרֶשׁ. וּמוֹצִיא אֶת הָאֵימוּרִין וְנוֹתְנָן בִּכְלִי וּמוֹלְחָן וּמַקְטִירָן הַכֹּהֵן עַל גַּבֵּי הַמִּזְבֵּחַ. וְכֵיצַד תּוֹלִין וּמַפְשִׁיטִין. מַסְמְרוֹת שֶׁל בַּרְזֶל הָיוּ קְבוּעִין בַּכְּתָלִים וּבָעַמּוּדִים שֶׁבָּהֶן תּוֹלִין וּמַפְשִׁיטִין. וְכָל מִי שֶׁלֹּא מָצָא מָקוֹם לִתְלוֹת מַקְלוֹת דַּקִּים וַחֲלָקִים הָיוּ שָׁם מַנִּיחַ עַל כְּתֵפוֹ וְעַל כֶּתֶף חֲבֵרוֹ וְתוֹלֶה וּמַפְשִׁיט:","שָׁלְמוּ מִלְּהַקְרִיב פּוֹתְחִין דַּלְתוֹת הָעֲזָרָה וְיוֹצֵאת כַּת הָרִאשׁוֹנָה וְנִכְנְסָה שְׁנִיָּה. יָצָאת שְׁנִיָּה וְנִכְנְסָה שְׁלִישִׁית. כְּמַעֲשֵׂה רִאשׁוֹנָה כָּךְ מַעֲשֵׂה שְׁנִיָּה וּשְׁלִישִׁית. שָׁלְמָה כַּת שְׁלִישִׁית וְיָצָאת רוֹחֲצִים אֶת הָעֲזָרָה:","חָל אַרְבָּעָה עָשָׂר לִהְיוֹת בְּשַׁבָּת כְּמַעֲשֵׂהוּ בְּחל כָּךְ מַעֲשֵׂהוּ בְּשַׁבָּת. וְרוֹחֲצִין אֶת הָעֲזָרָה בְּשַׁבָּת שֶׁאֵין אִסּוּר שְׁבוּת בַּמִּקְדָּשׁ אֲפִלּוּ בְּדָבָר שֶׁאֵינוֹ צֹרֶךְ עֲבוֹדָה אִסּוּר שְׁבוּת בַּמִּקְדָּשׁ הֶתֵּר הוּא:","אֵין כָּל אֶחָד וְאֶחָד מוֹלִיךְ אֶת פִּסְחוֹ לְבֵיתוֹ בְּשַׁבָּת. אֶלָּא כַּת הָרִאשׁוֹנָה יוֹצְאִין בְּפִסְחֵיהֶם וְיוֹשְׁבִין בְּהַר הַבַּיִת. וְהַשְּׁנִיָּה יוֹצְאִין בְּפִסְחֵיהֶן וְיוֹשְׁבִין בַּחֵיל. וְהַשְּׁלִישִׁית עוֹמְדִין בִּמְקוֹמָן בָּעֲזָרָה. וְשׁוֹהִים הַכּל עַד מוֹצָאֵי שַׁבָּת וְהוֹלֵךְ כָּל אֶחָד בְּפִסְחוֹ לְבֵיתוֹ:","שְׁחִיטַת הַפֶּסַח וּזְרִיקַת דָּמוֹ וּמִחוּי קְרָבָיו וְהֶקְטֵר חֲלָבָיו דּוֹחִין אֶת הַשַּׁבָּת. שֶׁאִי אֶפְשָׁר לַעֲשׂוֹתָן קֹדֶם הַשַּׁבָּת שֶׁהֲרֵי קָבוּעַ לוֹ זְמַן שֶׁנֶּאֱמַר (במדבר ט ב ג) \"בְּמוֹעֲדוֹ\". אֲבָל הַרְכָּבָתוֹ וַהֲבָאָתוֹ מִחוּץ לַתְּחוּם וַחֲתִיכַת יַבָּלָתוֹ בִּכְלִי אֵינָן דּוֹחִין אֶת הַשַּׁבָּת שֶׁהֲרֵי אֶפְשָׁר לַעֲשׂוֹתָן קֹדֶם הַשַּׁבָּת. וְאִם יָכוֹל לַחְתֹּךְ יַבַּלְתּוֹ בְּיָדוֹ בְּשַׁבָּת חוֹתֵךְ. וְאִם הָיְתָה יְבֵשָׁה חוֹתְכָהּ אֲפִלּוּ בִּכְלִי שֶׁאֵין שְׁבוּת בַּמִּקְדָּשׁ כְּלָל. וְכֵן צְלִיָּתוֹ וַהֲדָחַת קְרָבָיו אֵינָן דּוֹחִין אֶת הַשַּׁבָּת שֶׁהֲרֵי אֶפְשָׁר לַעֲשׂוֹתָן לְאַחַר הַשַּׁבָּת:","שָׁכַח וְלֹא הֵבִיא סַכִּין לֹא יְבִיאֶנָּה בְּשַׁבָּת. אֶלָּא נוֹתְנָהּ בֵּין קַרְנֵי הַכֶּבֶשׂ אוֹ בְּצַמְרוֹ וּמַכִּישׁוֹ עַד שֶׁמְּבִיאוֹ לָעֲזָרָה וּמַקְדִּישׁוֹ שָׁם. וְאַף עַל פִּי שֶׁהוּא מְחַמֵּר בְּשַׁבָּת מְחַמֵּר כִּלְאַחַר יָד הוּא וּמִפְּנֵי הַמִּצְוָה מֻתָּר. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלֹּא הִקְדִּישׁ פִּסְחוֹ עֲדַיִן וְלֹא אָמַר זֶה פֶּסַח אֲבָל אִם הִקְדִּישׁוֹ לֹא יָבִיא סַכִּין עָלָיו מִפְּנֵי שֶׁהוּא עוֹבֵד בְּקָדָשִׁים. וּמִפְּנֵי מָה הִתִּירוּ לְהַקְדִּישׁ פִּסְחוֹ בְּשַׁבָּת הוֹאִיל וְקָבוּעַ לוֹ זְמַן מֻתָּר לְהַקְדִּישׁוֹ בְּשַׁבָּת. וְכֵן מַקְדִּישׁ אָדָם חֲגִיגָתוֹ בְּיוֹם טוֹב וְאֵינוֹ חוֹשֵׁשׁ:","הַשּׁוֹחֵט אֶת הַפֶּסַח וְנִמְצָא בַּעַל מוּם אוֹ טְרֵפָה הֲרֵי זֶה שׁוֹחֵט אַחֵר בֵּין בְּחל בֵּין בְּשַׁבָּת אֲפִלּוּ מֵאָה זֶה אַחַר זֶה שׁוֹחֵט וְהוֹלֵךְ עַד שֶׁיִּכְשַׁר אֶחָד אוֹ עַד שֶׁתֶּחֱשַׁךְ וְיִדָּחֶה לַשֵּׁנִי שֶׁהֲרֵי אָנוּס הוּא:"],"Mishneh Torah, Plaintiff and Defendant 11":["כָּל הַקַּרְקָעוֹת הַיְדוּעוֹת לבַעְלֵיהֶן אַף עַל פִּי שֶׁהֵן עַתָּה תַּחַת יַד אֲחֵרִים הֲרֵי הֵן בְּחֶזְקַת בַּעְלֵיהֶן. כֵּיצַד. רְאוּבֵן שֶׁהָיָה מִשְׁתַּמֵּשׁ בֶּחָצֵר כְּדֶרֶךְ שֶׁהָעָם מִשְׁתַּמְּשִׁין בְּחַצְרוֹתֵיהֶן. דָּר בָּהּ וּמַשְׂכִּירָהּ לַאֲחֵרִים וּבוֹנֶה וְסוֹתֵר. וְאַחַר זְמַן בָּא שִׁמְעוֹן וְטָעַן עָלָיו וְאָמַר לוֹ חָצֵר זוֹ שֶׁתַּחַת יָדְךָ שֶׁלִּי הִיא וּשְׂכוּרָה הִיא בְּיָדְךָ אוֹ שְׁאוּלָה. וֶהֱשִׁיבוֹ רְאוּבֵן שֶׁלְּךָ הָיְתָה וְאַתָּה מְכַרְתָּהּ לִי אוֹ נְתַתָּהּ לִי בְּמַתָּנָה. אִם אֵין עֵדִים לְשִׁמְעוֹן שֶׁהָיְתָה יְדוּעָה לוֹ נִשְׁבָּע רְאוּבֵן הֶסֵּת וְיַעֲמֹד בִּמְקוֹמוֹ. אֲבָל אִם הֵבִיא שִׁמְעוֹן עֵדִים שֶׁחָצֵר זוֹ שֶׁלּוֹ הָיְתָה הֲרֵי הִיא בְּחֶזְקַת שִׁמְעוֹן וְאוֹמְרִין לִרְאוּבֵן הָבֵא רְאָיָה שֶׁמְּכָרָהּ לְךָ אוֹ נְתָנָהּ לְךָ. וְאִם לֹא הֵבִיא רְאָיָה מְסַלְּקִין אוֹתוֹ מִמֶּנָּה וּמַחֲזִיקִין אוֹתָהּ לְשִׁמְעוֹן אַף עַל פִּי שֶׁאֵין רְאוּבֵן מוֹדֶה לְשִׁמְעוֹן שֶׁהִיא הָיְתָה שֶׁלּוֹ שֶׁהֲרֵי יֵשׁ עֵדִים לְשִׁמְעוֹן:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמַּצְרִיכִין רְאוּבֵן לְהָבִיא רְאָיָה אוֹ יִסְתַּלֵּק בְּשֶׁלֹּא נִשְׁתַּמֵּשׁ בָּהּ זְמַן מְרֻבֶּה. אֲבָל אִם הֵבִיא עֵדִים שֶׁאָכַל פֵּרוֹת קַרְקַע שָׁלֹשׁ שָׁנִים רְצוּפוֹת וְנֶהֱנָה בְּכֻלָּהּ כְּדֶרֶךְ שֶׁנֶּהֱנִין כָּל אָדָם בְּאוֹתָהּ קַרְקַע. וְהוּא שֶׁיִּהְיֶה אֶפְשָׁר לַבְּעָלִים הָרִאשׁוֹנִים שֶׁיֵּדְעוּ בָּזֶה שֶׁהֶחְזִיק וְלֹא מִחוּ בּוֹ. מַעֲמִידִין אוֹתָהּ בְּיַד רְאוּבֵן וְיִשָּׁבַע רְאוּבֵן הֶסֵּת שֶׁמְּכָרָהּ לוֹ שִׁמְעוֹן אוֹ נְתָנָהּ לוֹ וְיִפָּטֵר. מִפְּנֵי שֶׁאוֹמְרִים לוֹ לְשִׁמְעוֹן אִם אֱמֶת אַתָּה טוֹעֵן שֶׁלֹּא מָכַרְתָּ וְלֹא נָתַתָּ לָמָּה הָיָה זֶה מִשְׁתַּמֵּשׁ שָׁנָה אַחַר שָׁנָה בְּקַרְקָעֲךָ וְאֵין לְךָ עָלָיו לֹא שְׁטַר שְׂכִירוּת וְלֹא שְׁטַר מַשְׁכּוֹנָהּ וְלֹא מָחִיתָ בּוֹ. טָעַן וְאָמַר מִפְּנֵי שֶׁלֹּא הִגִּיעַ אֵלַי הַדָּבָר שֶׁהֲרֵי הָיִיתִי בִּמְדִינָה רְחוֹקָה אוֹמְרִים אִי אֶפְשָׁר שֶׁלֹּא יַגִּיעַ לְיָדְךָ הַדָּבָר בְּשָׁלֹשׁ שָׁנִים וְכֵיוָן שֶׁהִגִּיעַ לְךָ הָיָה לְךָ לִמְחוֹת בִּפְנֵי עֵדִים וְתוֹדִיעַ אוֹתָם שֶׁפְּלוֹנִי גָּזַל אוֹתִי לְמָחָר אֶתְבָּעֶנּוּ בְּדִין. הוֹאִיל וְלֹא מָחִיתָ אַתָּה הִפְסַדְתָּ עַל עַצְמְךָ. לְפִיכָךְ אִם הָיְתָה מִלְחָמָה וְשִׁבּוּשׁ דְּרָכִים בֵּין הַמָּקוֹם שֶׁהָיָה בּוֹ רְאוּבֵן וּבֵין הַמָּקוֹם שֶׁהָיָה בּוֹ שִׁמְעוֹן אֲפִלּוּ אֲכָלָהּ רְאוּבֵן עֶשֶׂר שָׁנִים מוֹצִיאִין אוֹתָהּ תַּחַת יָדוֹ וְחוֹזֶרֶת לְשִׁמְעוֹן מִפְּנֵי שֶׁיָּכוֹל לוֹמַר לֹא יָדַעְתִּי שֶׁזֶּה מִשְׁתַּמֵּשׁ בְּקַרְקָעִי:","הֵבִיא רְאוּבֵן עֵדִים שֶׁהָיָה שִׁמְעוֹן בָּא בְּכָל שָׁנָה וְעוֹמֵד בְּמָקוֹם זֶה שְׁלֹשִׁים יוֹם אוֹ פָּחוֹת. אוֹמְרִים לְשִׁמְעוֹן מִפְּנֵי מָה לֹא מָחִיתָ כְּשֶׁבָּאתָ אִבַּדְתָּ זְכוּתְךָ. טָעַן שִׁמְעוֹן וְאָמַר טָרוּד הָיִיתִי בַּשּׁוּק וְלֹא יָדַעְתִּי שֶׁזֶּה בְּתוֹךְ חֲצֵרִי הֲרֵי זוֹ טַעֲנָה. שֶׁכָּל שְׁלֹשִׁים יוֹם יִהְיֶה אָדָם טָרוּד בַּשּׁוּק. וְאִם עָמַד יוֹתֵר מִשְּׁלֹשִׁים יוֹם וְלֹא מִחָה אִבֵּד אֶת זְכוּתוֹ. וְיֵרָאֶה לִי שֶׁהַדִּין זֶה אֵינוֹ אֶלָּא בַּכְּפָרִים שֶׁהָעָם טְרוּדִין בַּשְּׁוָקִים שֶׁלָּהֶן:","וּמִפְּנֵי מָה אֵין אוֹמְרִין לִרְאוּבֵן אִם אֱמֶת הַדָּבָר שֶׁמָּכַר לְךָ אוֹ נָתַן לְךָ בְּמַתָּנָה לָמָּה לֹא נִזְהַרְתָּ בַּשְּׁטָר שֶׁלְּךָ. מִפְּנֵי שֶׁאֵין אָדָם נִזְהָר בִּשְׁטָרוֹ וְהוֹלֵךְ כָּל יָמָיו וַחֲזָקָה שֶׁאֵין אָדָם נִזְהָר בִּשְׁטָר אֶלָּא עַד שָׁלֹשׁ שָׁנִים. וְכֵיוָן שֶׁרוֹאֶה שֶׁאֵין אָדָם מְמַחֶה בּוֹ שׁוּב אֵינוֹ נִזְהָר:","הֲרֵי שֶׁמִּחָה שִׁמְעוֹן בִּמְדִינָה רְחוֹקָה מִפְּנֵי מָה לֹא יִטְעֹן רְאוּבֵן וְיֹאמַר לֹא שָׁמַעְתִּי שֶׁמִּחָה בִּי כְּדֵי שֶׁאֶזָּהֵר בַּשְּׁטָר. מִפְּנֵי שֶׁאוֹמֵר לוֹ חֲבֵרְךָ יֵשׁ לוֹ חָבֵר וַחֲבֵרוֹ יֵשׁ לוֹ חָבֵר וַחֲזָקָה שֶׁהִגִּיעַ אֵלֶיךָ הַדָּבָר וְכֵיוָן שֶׁיָּדַעְתָּ שֶׁמִּחָה בְּךָ בְּתוֹךְ שָׁלֹשׁ שָׁנִים בֶּאֱמֶת הָיָה לְךָ שְׁטָר וְלֹא נִזְהַרְתָּ בּוֹ אַתָּה הִפְסַדְתָּ עַל עַצְמְךָ:","לְפִיכָךְ אִם מִחָה שִׁמְעוֹן בִּפְנֵי עֵדִים וְאָמַר לָהֶם אַל תּוֹצִיאוּ דָּבָר זֶה מִפִּיכֶם אֵין זֶה מְחָאָה. אֲבָל אִם אָמְרוּ הָעֵדִים מֵעַצְמָן אֵין דָּבָר זֶה יוֹצֵא מִפִּינוּ הֲרֵי גַּם זוֹ מְחָאָה. שֶׁהַדָּבָר שֶׁאֵין אָדָם מְצֻוֶּה עָלָיו אוֹמְרוֹ שֶׁלֹּא בְּכַוָּנָה. וְכֵן אִם צִוָּה לְעֵדִים וְאָמַר לָהֶם אַל תּוֹדִיעוּהוּ אוֹ שֶׁאָמְרוּ הֵן מֵעַצְמָן אֵין אָנוּ מוֹדִיעִין אוֹתוֹ גַּם זוֹ מְחָאָה הִיא. אַף עַל פִּי שֶׁאֵינָן מוֹדִיעִין אוֹתוֹ מוֹדִיעִין הֵם לַאֲחֵרִים וְדָבָר זֶה יַגִּיעַ אֵלָיו:","כֵּיצַד הַמְּחָאָה. אוֹמֵר בִּפְנֵי שְׁנַיִם פְּלוֹנִי שֶׁהוּא מִשְׁתַּמֵּשׁ בַּחֲצֵרִי אוֹ בְּשָׂדִי גַּזְלָן הוּא וּלְעָתִיד אֲנִי תּוֹבֵעַ אוֹתוֹ בְּדִין. וְכֵן אִם אָמַר לָהֶם שְׂכוּרָה הִיא בְּיָדוֹ אוֹ מַשְׁכּוֹנָה וְאִם יִטְעֹן עָלַי שֶׁמָּכַרְתִּי אוֹ נָתַתִּי אֲנִי תּוֹבֵעַ אוֹתוֹ בְּדִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה הֲרֵי זוֹ מְחָאָה. אַף עַל פִּי שֶׁלֹּא מִחָה בִּמְדִינָה זוֹ שֶׁהֶחְזִיק בָּהּ זֶה. אֲבָל אִם אָמַר לָהֶן פְּלוֹנִי שֶׁמִּשְׁתַּמֵּשׁ בַּחֲצֵרִי גַּזְלָן הוּא אֵין זוֹ מְחָאָה. שֶׁהֲרֵי רְאוּבֵן אוֹמֵר כְּשֶׁשָּׁמַעְתִּי אָמַרְתִּי שֶׁמָּא חֵרֵף אוֹתִי בִּלְבַד וּלְפִיכָךְ לֹא נִזְהַרְתִּי בִּשְׁטָרִי:","מְחָאָה בִּפְנֵי שְׁנַיִם מְחָאָה וְכוֹתְבִין אַף עַל פִּי שֶׁלֹּא אָמַר לָהֶם כְּתֹבוּ. וְכֵיוָן שֶׁמִּחָה בְּשָׁנָה רִאשׁוֹנָה אֵינוֹ צָרִיךְ לַחְזֹר וְלִמְחוֹת בְּכָל שָׁנָה וְשָׁנָה. אֲבָל צָרִיךְ שֶׁלֹּא יִהְיֶה בֵּין מְחָאָה לִמְחָאָה שָׁלֹשׁ שָׁנִים גְּמוּרוֹת. לְפִיכָךְ צָרִיךְ לִמְחוֹת בְּסוֹף כָּל שָׁלֹשׁ שָׁנִים. וְאִם מִחָה וְעָמַד שָׁלֹשׁ שָׁנִים גְּמוּרוֹת וְאַחַר כָּךְ מִחָה אֵינָהּ מְחָאָה:","הֵבִיא רְאוּבֵן עֵדִים שֶׁזֶּה שִׁמְעוֹן בַּעַל הַשָּׂדֶה קִבֵּץ פֵּרוֹת שָׂדֶה זוֹ וּנְתָנָם לִי תַּעֲמֹד הַשָּׂדֶה בְּיַד רְאוּבֵן וַאֲפִלּוּ טָעַן שֶׁשִּׁמְעוֹן מְכָרָהּ לוֹ אוֹ נָתַן לוֹ הַיּוֹם שֶׁאִלּוּ לֹא מָכַר אוֹ נָתַן לֹא הָיָה מְשַׁמֵּשׁ אֶת רְאוּבֵן בְּשָׂדֶה זוֹ וְנוֹתֵן לוֹ פֵּרוֹתֶיהָ:","טָעַן שִׁמְעוֹן וְאָמַר אֱמֶת הָיָה הַדָּבָר וּלְפֵרוֹת הוֹרַדְתִּיו וְשֶׁלּוֹ הָיוּ הַפֵּרוֹת אֲבָל הַגּוּף לֹא מָכַרְתִּי נֶאֱמָן וְחוֹזֵר לְשִׁמְעוֹן אֶלָּא אִם כֵּן אֲכָלָהּ רְאוּבֵן בְּפָנָיו שָׁלֹשׁ שָׁנִים וְלֹא מִחָה בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Plaintiff and Defendant 8":["כָּל הַמִּטַּלְטְלִין בְּחֶזְקַת זֶה שֶׁהֵן תַּחַת יָדוֹ. אַף עַל פִּי שֶׁהֵבִיא הַתּוֹבֵעַ עֵדִים שֶׁהַמִּטַּלְטְלִין הַלָּלוּ יְדוּעִין לוֹ. כֵּיצַד. בֶּגֶד זֶה אוֹ כְּלִי זֶה שֶׁבְּיָדְךָ אוֹ שֶׁבְּתוֹךְ בֵּיתְךָ שֶׁלִּי הוּא. אוֹ הִפְקַדְתִּיהוּ אֶצְלְךָ. אוֹ הִשְׁאַלְתִּיהוּ לְךָ. וַהֲרֵי הָעֵדִים שֶׁהֵן יוֹדְעִין אוֹתוֹ מִקֹּדֶם בִּרְשׁוּתִי. וְהַנִּתְבָּע אוֹמֵר לֹא כִּי אֶלָּא אַתָּה מְכַרְתּוֹ לִי אוֹ נְתַתּוֹ לִי בְּמַתָּנָה. הֲרֵי זֶה הַנִּתְבָּע נִשְׁבָּע הֶסֵּת וְנִפְטָר:","טָעַן שֶׁהוּא מַשְׁכּוֹן בְּיָדוֹ יָכוֹל לִטְעֹן עַד כְּדֵי דָּמָיו וְנִשְׁבָּע בִּנְקִיטַת חֵפֶץ וְנוֹטֵל כְּמוֹ שֶׁבֵּאַרְנוּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּדְבָרִים שֶׁאֵינָן עֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר. כְּגוֹן בְּגָדִים וּפֵרוֹת וּכְלֵי תַּשְׁמִישׁ הַבַּיִת וּדְבָרִים שֶׁל סְחוֹרָה וְכַיּוֹצֵא בָּהֶן. אֲבָל דְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר אַף עַל פִּי שֶׁהֵן תַּחַת יָדוֹ שֶׁל זֶה וְאַף עַל פִּי שֶׁלֹּא הִשְׁאִילוֹ כְּלִי זֶה וְלֹא הִשְׂכִּירוֹ לוֹ בְּעֵדִים הֲרֵי הֵן בְּחֶזְקַת בַּעֲלֵיהֶן. כֵּיצַד. רְאוּבֵן שֶׁהָיָה לוֹ כְּלִי הֶעָשׂוּי לְהַשְׁאִיל וּלְהַשְׂכִּיר וְיֵשׁ לוֹ עֵדִים שֶׁהוּא יָדוּעַ לוֹ וַהֲרֵי אוֹתוֹ הַכְּלִי תַּחַת יַד שִׁמְעוֹן וּרְאוּבֵן טוֹעֵן שֶׁהוּא שָׁאוּל אוֹ שָׂכוּר. וְשִׁמְעוֹן טוֹעֵן אַתָּה מְכַרְתּוֹ לִי אַתָּה נְתַתּוֹ לִי בְּמַתָּנָה אַתָּה מִשְׁכַּנְתּוֹ בְּיָדִי אֵינוֹ נֶאֱמָן. אֶלָּא רְאוּבֵן נוֹטֵל כֶּלְיוֹ וְנִשְׁבָּע הֶסֵּת עַל טַעֲנַת שִׁמְעוֹן. וַאֲפִלּוּ מֵת שִׁמְעוֹן הֲרֵי רְאוּבֵן נוֹטֵל כֶּלְיוֹ. וְהוֹרוּ הַגְּאוֹנִים שֶׁיִּשָּׁבַע הֶסֵּת. שֶׁטּוֹעֲנִין לַיּוֹרֵשׁ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה כְּלִי זֶה נִרְאֶה וְעוֹמֵד בְּיַד שִׁמְעוֹן. אֲבָל אִם רְאוּבֵן טָעַן וְאָמַר לְשִׁמְעוֹן כְּלִי פְּלוֹנִי יֵשׁ לִי בְּיָדְךָ וְשָׂכוּר הוּא הוֹצִיאוֹ אֵלַי וַהֲרֵי יֵשׁ לִי עֵדִים שֶׁהוּא יָדוּעַ לִי. וְאָמַר לוֹ שִׁמְעוֹן אַתָּה מְכַרְתּוֹ לִי אַתָּה נְתַתּוֹ לִי בְּמַתָּנָה נֶאֱמָן וְנִשְׁבָּע שִׁמְעוֹן הֶסֵּת וְנִפְטָר. מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר לֹא הָיוּ דְּבָרִים מֵעוֹלָם וְאֵין בְּיָדִי כְּלוּם נֶאֱמָן לוֹמַר שֶׁיֶּשְׁנוֹ אֶצְלִי וְאַתָּה מְכַרְתּוֹ לִי:","אֵין כָּל הַדְּבָרִים הָאֵלּוּ אֲמוּרִים אֶלָּא שֶׁהָיָה בַּעַל הַכְּלִי טוֹעֵן אֲנִי הִפְקַדְתִּיו אֶצְלְךָ אוֹ הִשְׁאַלְתִּיהוּ אֶצְלְךָ. אֲבָל אִם טָעַן שֶׁכְּלִי זֶה הָיָה שֶׁלִּי וְנִגְנַב אוֹ אָבַד אוֹ נִגְזַל וְהֵבִיא עֵדִים שֶׁהוּא יָדוּעַ לוֹ וְזֶה שֶׁתַּחַת יָדוֹ אוֹמֵר אֵינִי יוֹדֵעַ אֲבָל אֲחֵרִים מְכָרוּהוּ לִי אוֹ נְתָנוּהוּ לִי בְּמַתָּנָה. אַף עַל פִּי שֶׁהוּא מִדְּבָרִים שֶׁעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר מַעֲמִידִין אוֹתוֹ בְּיַד זֶה שֶׁהוּא בְּיָדוֹ וְאֵינוֹ נִשְׁבָּע כְּלָל שֶׁהֲרֵי אֵין לוֹ טוֹעֵן:","יָצָא לַבְּעָלִים הָרִאשׁוֹנִים חֲזָקָה מִכְּלֵיהֶן שֶׁנִּגְנְבוּ. יִשָּׁבַע זֶה בִּנְקִיטַת חֵפֶץ כַּמָּה הוֹצִיא וְיִטּל וְיַחְזֹר הַכְּלִי לַבְּעָלִים הָרִאשׁוֹנִים כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת גְּנֵבָה. טָעַן אַתָּה מְכַרְתּוֹ לִי אוֹ נְתַתּוֹ לִי בְּמַתָּנָה. אַף עַל פִּי שֶׁיָּצָא לוֹ שֵׁם גְּנֵבָה אִם לֹא הָיָה מִדְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר הֲרֵי זֶה נִשְׁבָּע הֶסֵּת וְיַעֲמֹד הַכְּלִי בְּיָדוֹ. מִכָּאן אַתָּה לָמֵד לְכָל מִי שֶׁיֵּשׁ לוֹ מִטַּלְטְלִין בְּיָדוֹ אַף עַל פִּי שֶׁיָּכוֹל לוֹמַר שֶׁלְּקוּחִין הֵן בְּיָדִי וְיִשָּׁבַע הֶסֵּת וְיִפָּטֵר. אִם אָמַר שֶׁלְּךָ הֵן אֲבָל חַיָּב אַתָּה לִי כָּךְ וְכָךְ יִשָּׁבַע בִּנְקִיטַת חֵפֶץ וְאַחַר כָּךְ יִטּל כְּדִין כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין:","מִי שֶׁהָיוּ בְּיָדוֹ דְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר אַף עַל פִּי שֶׁהוֹדָה וְאָמַר לוֹ יוֹדֵעַ אֲנִי שֶׁהֵם שֶׁלְּךָ אֲבָל פְּלוֹנִי מְכָרָם לִי אוֹ נְתָנָם לִי בְּמַתָּנָה אֵין מוֹצִיאִין אוֹתָן מִיָּדוֹ. אֲפִלּוּ הֵבִיא זֶה עֵדִים שֶׁהָיוּ יְדוּעִין לוֹ. שֶׁאָדָם עָשׂוּי לִמְכֹּר אֶת כֵּלָיו:","טָעַן זֶה עָלָיו וְאָמַר שֶׁאֲנִי הִשְׂכַּרְתִּים לְךָ אוֹ הִשְׁאַלְתִּים לְךָ מוֹצִיאִין אוֹתָן מִיָּדוֹ. וְאִם הָיוּ מִדְּבָרִים שֶׁאֵינָן עֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר הֲרֵי זֶה נִשְׁבָּע הֶסֵּת שֶׁלֹּא הִשְׁאִיל לוֹ וְלֹא הִשְׂכִּיר לוֹ אֶלָּא מִפְּלוֹנִי לָקַח וְיַעֲמִיד כֵּלָיו בְּיָדוֹ:","אַל תִּטְעֶה בֵּין דְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר לִדְבָרִים שֶׁדַּרְכָּן לְהַשְׁאִיל וּלְהַשְׂכִּיר כְּמוֹ שֶׁטָּעוּ רַבִּים וּגְדוֹלִים. שֶׁכָּל הַדְּבָרִים רְאוּיִין לְהַשְׁאִיל וְדַרְכָּן לְהַשְׁאִיל אֲפִלּוּ חֲלוּקוֹ שֶׁל אָדָם וּמַצָּעוֹ וּמִטָּתוֹ רְאוּיִין לְהַשְׁאִיל. אֲבָל דְּבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר הֵם הַכֵּלִים שֶׁבְּנֵי אוֹתָהּ מְדִינָה עוֹשִׂין אוֹתָן מִתְּחִלַּת עֲשִׂיָּתָן כְּדֵי לְהַשְׁאִילָן וּלְהַשְׂכִּירָן וְלִטּל שְׂכָרָן וַהֲרֵי הֵן לְבַעְלֵיהֶן. כְּמוֹ קַרְקַע שֶׁאוֹכֵל פֵּרוֹתֶיהָ וְהַגּוּף קַיָּם כָּךְ אֵלּוּ הַכֵּלִים עִקַּר עֲשִׂיָּתָן כְּדֵי לֵהָנוֹת בִּשְׂכָרָן. כְּגוֹן הַיּוֹרוֹת הַגְּדוֹלוֹת שֶׁל נְחשֶׁת שֶׁמְּבַשְּׁלִין בָּהֶן בְּבֵית הַמִּשְׁתָּאוֹת. וּכְגוֹן כְּלִי נְחשֶׁת הַטּוּחַ בְּזָהָב שֶׁשּׂוֹכְרִין אוֹתוֹ לַכַּלָּה לְהִתְקַשֵּׁט בּוֹ. שֶׁעֲשִׂיַּת אֵלּוּ הַכֵּלִים אֵינָן לִמְכִירַת עַצְמָן וְלֹא לְהִשְׁתַּמֵּשׁ בָּהֶן בַּעַל הַבַּיִת בְּבֵיתוֹ אֶלָּא לְהַשְׁאִילָן לַאֲחֵרִים כְּדֵי לֵהָנוֹת כְּנֶגְדָּן אוֹ לְהַשְׂכִּירָן וְלִטּל שְׂכָרָן. וְכֵן אִם הָיָה לְאָדָם מִשְּׁאָר הַכֵּלִים וְיֵשׁ לוֹ עֵדִים שֶׁהוּא מַשְׂכִּירוֹ תָּמִיד וּמַשְׁאִילוֹ וְהֻחְזַק לוֹ שֶׁהוּא לְהַשְׁאִיל וּלְהַשְׂכִּיר הֲרֵי הֵן כְּכֵלִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר:","וּכְלִי שֶׁהֶפְסֵדוֹ מְרֻבֶּה מִשְּׂכָרוֹ וּבְנֵי אָדָם מַקְפִּידִין עָלָיו שֶׁלֹּא יַשְׁאִילוּהוּ הֲרֵי הוּא בְּחֶזְקַת שֶׁאֵינוֹ עָשׂוּי לְהַשְׁאִיל וּלְהַשְׂכִּיר כְּגוֹן סַכִּין שֶׁל שְׁחִיטָה. לְפִיכָךְ אֲפִלּוּ בָּאוּ בְּנֵי אָדָם וְהֵעִידוּ שֶׁהִשְׁאִילוֹ אוֹ הִשְׂכִּירוֹ זֶה אֵין מְבַטְּלִין בָּהֶן חֶזְקָתָן אֶלָּא הֲרֵי הֵן כְּכָל הַכֵּלִים. רְאָיָה לִדְבָרֵינוּ שֶׁהֲרֵי רָבָא הוֹצִיא זוּג שֶׁעוֹשִׂין בּוֹ הַסַּרְבָּל וְסֵפֶר הַגָּדָה בִּדְבָרִים הָעֲשׂוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר. וְלוּלֵי שֶׁנִּתְבָּרֵר לוֹ בְּעֵדִים שֶׁהֵן מִדְּבָרִים הָעֲשׂוּיִים לְהַשְׁאִיל לֹא הוֹצִיא מִתַּחַת יְדֵי יְתוֹמִים. הָא שְׁאָר הַזּוּגוֹת וּשְׁאָר הַסְּפָרִים אֵינָן בִּכְלַל דִּין זֶה אַף עַל פִּי שֶׁהֵן רְאוּיִין לְהַשְׁאִיל וּלְהַשְׂכִּיר. וְדָבָר זֶה עִקָּר גָּדוֹל בַּדִּין וְהוּא דָּבָר שֶׁל טַעַם שֶׁרָאוּי לִסְמֹךְ עָלָיו וְלָדוּן בּוֹ וּבָרוּר הוּא לְמוֹצְאֵי דַּעַת וְרָאוּי לַדַּיָּן לָשׂוּם אוֹתוֹ לְנֶגֶד עֵינָיו וְלֹא יָלוֹז:"],"Mishneh Torah, Positive Mitzvot 108":["להיות מי נדה מטמאין לאדם טהור, ומטהרין מטומאת מת בלבד. וכל אלו הדינין של טומאות אלו, רוב משפט כל טומאה וטומאה מהן מבואר בתורה שבכתב."],"Mishneh Torah, Positive Mitzvot 119":["להיות נטע רבעי קודש, שנאמר: \"יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים\" (ויקרא יט, כד)."],"Mishneh Torah, Positive Mitzvot 13":["לִקְשֹׁר תְּפִלִּין בַּיָּד, שֶׁנֶּאֱמָר: \"וּקְשַׁרְתָּם לְאוֹת עַל יָדֶךָ\" (דברים ו, ח)."],"Mishneh Torah, Positive Mitzvot 140":["למנות שני יובל שנים ושמיטים, שנאמר: \"וספרת לך, שבע . . .\" (ויקרא כה,ח)."],"Mishneh Torah, Positive Mitzvot 151":["לבדוק בסימני חגבים לידע טהור מן הטמא, שנאמר: \"אשר לו כרעיים\" (ויקרא יא,כא)."],"Mishneh Torah, Positive Mitzvot 162":["לשבות ביום חמישים, שנאמר: \"וקראתם בעצם היום הזה, מקרא קודש\" (ויקרא כג,כא)."],"Mishneh Torah, Positive Mitzvot 173":["למנות מלך, שנאמר: \"שום תשים עליך מלך\" (דברים יז,טו)."],"Mishneh Torah, Positive Mitzvot 184":["לעשות מעקה, שנאמר: \"ועשית מעקה לגגך\" (דברים כב,ח)."],"Mishneh Torah, Positive Mitzvot 195":["ליתן צדקה, שנאמר: \"פתוח תפתח את ידך\" (דברים טו,ח; דברים טו,יא)."],"Mishneh Torah, Positive Mitzvot 205":["להוכיח החוטא, שנאמר: \"הוכח תוכיח את עמיתך\" (ויקרא יט,יז)."],"Mishneh Torah, Positive Mitzvot 216":["לייבם אשת אח, שנאמר: \"יבמה יבוא עליה\" (דברים כה,ה)."],"Mishneh Torah, Positive Mitzvot 227":["להיות בית דין הורגין בחנק, שנאמר: \"מות יומת הנואף, והנואפת\" (ויקרא כ,י)."],"Mishneh Torah, Positive Mitzvot 238":["לדון בנזקי הבור, שנאמר: \"כי יפתח איש בור\" (שמות כא,לג)."],"Mishneh Torah, Positive Mitzvot 25":["לַעֲרֹךְ נֵרוֹת בַּמִּקְדָּשׁ, שֶׁנֶּאֱמָר: \"יַעֲרֹךְ אֹתוֹ אַהֲרֹן וּבָנָיו\" (שמות כז, כא)."],"Mishneh Torah, Positive Mitzvot 36":["להיות הכהנים עובדין במקדש משמרות משמרות, ובמועדים עובדין כאחד, שנאמר: \"וְכִי יָבוֹא הַלֵּוִי...\" (דברים יח, ו) \"לְבַד מִמְכָּרָיו עַל הָאָבוֹת\" (שם, ח)."],"Mishneh Torah, Positive Mitzvot 47":["להוסיף קרבן בראש השנה, שנאמר: \"וּבַחֹדֶשׁ הַשְּׁבִיעִי בְּאֶחָד לַחֹדֶשׁ וַעֲשִׂיתֶם...\" (במדבר כט, א)."],"Mishneh Torah, Positive Mitzvot 58":["לאכול את בשר פסח שני על מצה ומרור, שנאמר: \"עַל מַצּוֹת וּמְרוֹרִים יֹאכְלוּהוּ\" (במדבר ט, יא)."],"Mishneh Torah, Positive Mitzvot 69":["להקריב היחיד קרבן חטאת אם שגג במצות לא תעשה שחייבים עליה כרת, שנאמר: \"וְנֶפֶשׁ כִּי תֶחֱטָא\" (ויקרא ה, א)."],"Mishneh Torah, Positive Mitzvot 8":["לְהִדַּמּוֹת בִּדְרָכָיו הַטּוֹבִים וְהַיְּשָׁרִים, שֶׁנֶּאֱמָר: \"וְהָלַכְתָּ, בִּדְרָכָיו\" (דברים כח, ט)."],"Mishneh Torah, Positive Mitzvot 90":["לשרוף בשר קודש שנטמא, שנאמר: \"והבשר אשר ייגע בכל טמא\" (ויקרא ז,יט)."],"Mishneh Torah, Prayer and the Priestly Blessing 11":["כָּל מָקוֹם שֶׁיֵּשׁ בּוֹ עֲשָׂרָה מִיִּשְׂרָאֵל צָרִיךְ לְהָכִין לוֹ בַּיִת שֶׁיִּכָּנְסוּ בּוֹ לִתְפִלָּה בְּכָל עֵת תְּפִלָּה וּמָקוֹם זֶה נִקְרָא בֵּית הַכְּנֶסֶת. וְכוֹפִין בְּנֵי הָעִיר זֶה אֶת זֶה לִבְנוֹת לָהֶם בֵּית הַכְּנֶסֶת וְלִקְנוֹת לָהֶם סֵפֶר תּוֹרָה נְבִיאִים וּכְתוּבִים:","כְּשֶׁבּוֹנִין בֵּית הַכְּנֶסֶת אֵין בּוֹנִין אוֹתָהּ אֶלָּא בְּגָבְהָהּ שֶׁל עִיר שֶׁנֶּאֱמַר (משלי א כא) ״בְּרֹאשׁ הֹמִיּוֹת תִּקְרָא״. וּמַגְבִּיהִין אוֹתָהּ עַד שֶׁתְּהֵא גְּבוֹהָה מִכָּל חַצְרוֹת הָעִיר שֶׁנֶּאֱמַר (עזרא ט ט) ״וּלְרוֹמֵם אֶת בֵּית אֱלֹהֵינוּ״. וְאֵין פּוֹתְחִין פִּתְחֵי בֵּית הַכְּנֶסֶת אֶלָּא בַּמִּזְרָח שֶׁנֶּאֱמַר (במדבר ג לח) ״וְהַחֹנִים לִפְנֵי הַמִּשְׁכָּן קֵדְמָה״. וּבוֹנִין בּוֹ הֵיכָל שֶׁמַּנִּיחִין בּוֹ סֵפֶר תּוֹרָה. וּבוֹנִין הֵיכָל זֶה בָּרוּחַ שֶׁמִּתְפַּלְּלִין כְּנֶגְדּוֹ בְּאוֹתָהּ הָעִיר. כְּדֵי שֶׁיִּהְיוּ פְּנֵיהֶם אֶל מוּל הַהֵיכָל כְּשֶׁיַּעַמְדוּ לִתְפִלָּה:","וּמַעֲמִידִין בִּימָה בְּאֶמְצַע הַבַּיִת כְּדֵי שֶׁיַּעֲלֶה עָלֶיהָ הַקּוֹרֵא בַּתּוֹרָה אוֹ מִי אֲשֶׁר אוֹמֵר לָעָם דִּבְרֵי כִּבּוּשִׁין כְּדֵי שֶׁיִּשְׁמְעוּ כֻּלָּם. וּכְשֶׁמַּעֲמִידִין הַתֵּבָה שֶׁיֵּשׁ בָּהּ סֵפֶר תּוֹרָה מַעֲמִידִין אוֹתָהּ בָּאֶמְצַע וַאֲחוֹרֵי הַתֵּבָה כְּלַפֵּי הַהֵיכָל וּפָנֶיהָ כְּלַפֵּי הָעָם:","כֵּיצַד הָעָם יוֹשְׁבִין בְּבָתֵּי כְּנֵסִיּוֹת. הַזְּקֵנִים יוֹשְׁבִין וּפְנֵיהֶן כְּלַפֵּי הָעָם וַאֲחוֹרֵיהֶם כְּלַפֵּי הַהֵיכָל. וְכָל הָעָם יוֹשְׁבִין שׁוּרָה לִפְנֵי שׁוּרָה וּפְנֵי הַשּׁוּרָה לַאֲחוֹרֵי הַשּׁוּרָה שֶׁלְּפָנֶיהָ עַד שֶׁיִּהְיוּ פְּנֵי כָּל הָעָם כְּלַפֵּי הַקֹּדֶשׁ וּכְלַפֵּי הַזְּקֵנִים וּכְלַפֵּי הַתֵּבָה. וּבְעֵת שֶׁשְּׁלִיחַ צִבּוּר עוֹמֵד לִתְפִלָּה עוֹמֵד בָּאָרֶץ לִפְנֵי הַתֵּבָה וּפָנָיו לִפְנֵי הַקֹּדֶשׁ כִּשְׁאָר הָעָם:","בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת נוֹהֲגִין בָּהֶן כָּבוֹד וּמְכַבְּדִים אוֹתָן וּמַרְבִּיצִין אוֹתָן. וְנוֹהֲגִין כָּל יִשְׂרָאֵל בִּסְפָרַד וּבַמַּעֲרָב בְּשִׁנְעָר וּבְאֶרֶץ הַצְּבִי לְהַדְלִיק עֲשָׁשִׁיּוֹת בְּבָתֵּי כְּנֵסִיּוֹת וּלְהַצִּיעַ בְּקַרְקָעָן מַחְצְלָאוֹת כְּדֵי לֵישֵׁב עֲלֵיהֶם. וּבְעָרֵי אֱדוֹם יוֹשְׁבִין בָּהּ עַל הַכִּסְאוֹת:","בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת אֵין נוֹהֲגִין בָּהֶן קַלּוּת רֹאשׁ כְּגוֹן שְׂחוֹק וְהִתּוּל וְשִׂיחָה בְּטֵלָה. וְאֵין אוֹכְלִין בָּהֶן וְאֵין שׁוֹתִין בָּהֶן וְאֵין נֵאוֹתִין בָּהֶן וְאֵין מְטַיְּלִין בָּהֶן וְאֵין נִכְנָסִין בָּהֶן בַּחַמָּה מִפְּנֵי הַחַמָּה וּבַגְּשָׁמִים מִפְּנֵי הַגְּשָׁמִים. וַחֲכָמִים וְתַלְמִידֵיהֶם מֻתָּרִין לֶאֱכל וְלִשְׁתּוֹת בָּהֶן מִדֹּחַק:","וְאֵין מְחַשְּׁבִין בָּהֶן חֶשְׁבּוֹנוֹת אֶלָּא אִם כֵּן הָיוּ חֶשְׁבּוֹנוֹת שֶׁל מִצְוָה כְּגוֹן קֻפָּה שֶׁל צְדָקָה וּפִדְיוֹן שְׁבוּיִים וְכַיּוֹצֵא בָּהֶן. וְאֵין מַסְפִּידִין בָּהֶן אֶלָּא הֶסְפֵּד שֶׁל רַבִּים כְּגוֹן שֶׁיִּהְיֶה שָׁם הֶסְפֵּד גְּדוֹלֵי חַכְמֵי אוֹתָהּ הָעִיר שֶׁכָּל הָעָם מִתְקַבְּצִין וּבָאִין בִּגְלָלָן:","הָיָה לְבֵית הַכְּנֶסֶת אוֹ לְבֵית הַמִּדְרָשׁ שְׁנֵי פְּתָחִין לֹא יַעֲשֶׂנּוּ קַפַּנְדַּרְיָא כְּדֵי שֶׁיִּכָּנֵס בְּפֶתַח זֶה וְיֵצֵא בַּפֶּתַח שֶׁכְּנֶגְדּוֹ לְקָרֵב הַדֶּרֶךְ. שֶׁאָסוּר לִכָּנֵס בָּהֶן אֶלָּא לִדְבַר מִצְוָה:","מִי שֶׁצָּרִיךְ לִכָּנֵס לְבֵית הַכְּנֶסֶת לִקְרוֹת תִּינוֹק אוֹ חֲבֵרוֹ יִכָּנֵס וְיִקְרָא מְעַט אוֹ יֹאמַר שְׁמוּעָה וְאַחַר כָּךְ יִקְרָא חֲבֵרוֹ כְּדֵי שֶׁלֹּא יִכָּנֵס בִּשְׁבִיל חֲפָצָיו בִּלְבַד. וְאִם אֵינוֹ יוֹדֵעַ יֹאמַר לְתִינוֹק מִן הַתִּינוֹקוֹת קְרָא לִי הַפָּסוּק שֶׁאַתָּה קוֹרֵא בּוֹ. אוֹ יִשְׁהֶה מְעַט בְּבֵית הַכְּנֶסֶת וְאַחַר כָּךְ יֵצֵא. שֶׁהַיְשִׁיבָה שָׁם מֵעִסְקֵי הַמִּצְוֹת הִיא שֶׁנֶּאֱמַר (תהילים פד ה) ״אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ״ וְגוֹ׳‎:","מִי שֶׁנִּכְנַס לְהִתְפַּלֵּל אוֹ לִקְרוֹת מֻתָּר לוֹ לָצֵאת בַּפֶּתַח שֶׁכְּנֶגְדּוֹ כְּדֵי לְקָרֵב אֶת הַדֶּרֶךְ. וּמֻתָּר לָאָדָם לִכָּנֵס לְבֵית הַכְּנֶסֶת בְּמַקְלוֹ בְּמִנְעָלוֹ וּבַאֲפֻנְדָּתוֹ וּבָאָבָק שֶׁעַל רַגְלָיו. וְאִם הָיָה צָרִיךְ לָרֹק יָרֹק בְּבֵית הַכְּנֶסֶת:","בָּתֵּי כְּנֵסִיּוֹת וּבָתֵּי מִדְרָשׁוֹת שֶׁחָרְבוּ בִּקְדֻשָּׁתָן הֵן עוֹמְדוֹת שֶׁנֶּאֱמַר (ויקרא כו לא) ״וַהֲשִׁמּוֹתִי אֶת מִקְדְּשֵׁיכֶם״ אַף עַל פִּי שֶׁהֵן שׁוֹמְמִין בִּקְדֻשָּׁתָן הֵן עוֹמְדִין. וּכְשֵׁם שֶׁנּוֹהֲגִין בָּהֶן כָּבוֹד בְּיִשּׁוּבָן כָּךְ נוֹהֲגִין בָּהֶן בְּחֻרְבָּנָם חוּץ מִכִּבּוּד וְרִבּוּץ שֶׁאֵין מְכַבְּדִין אוֹתָן וְאֵין מַרְבִּיצִין אוֹתָן. עָלוּ בָּהֶן עֲשָׂבִים תּוֹלְשִׁין אוֹתָם וּמַנִּיחִין אוֹתָן בִּמְקוֹמָן כְּדֵי שֶׁיִּרְאוּ אוֹתָן הָעָם וְתֵעוֹר רוּחָם וְיִבְנוּם:","אֵין סוֹתְרִין בֵּית הַכְּנֶסֶת כְּדֵי לִבְנוֹת אַחֵר בִּמְקוֹמוֹ אוֹ בְּמָקוֹם אַחֵר. אֲבָל בּוֹנִין אַחֵר וְאַחַר כָּךְ סוֹתְרִין זֶה. שֶׁמָּא יֶאֱרַע לָהֶם אֹנֶס וְלֹא יִבְנוּ. אֲפִלּוּ כֹּתֶל אֶחָד מִמֶּנּוּ בּוֹנֶה הֶחָדָשׁ בְּצַד הַיָּשָׁן וְאַחַר כָּךְ סוֹתֵר הַיָּשָׁן:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלֹּא חָרְבוּ יְסוֹדוֹתָיו אוֹ שֶׁלֹּא נָטוּ כְּתָלָיו לִפּל. אֲבָל אִם חָרְבוּ יְסוֹדוֹתָיו אוֹ שֶׁנָּטוּ כְּתָלָיו לִפּל סוֹתְרִין אוֹתוֹ מִיָּד וּמַתְחִילִין לִבְנוֹת בִּמְהֵרָה בַּיּוֹם וּבַלַּיְלָה שֶׁמָּא תִּדְחֹק הַשָּׁעָה וְיִשָּׁאֵר חָרֵב:","מֻתָּר לַעֲשׂוֹת בֵּית הַכְּנֶסֶת בֵּית הַמִּדְרָשׁ. אֲבָל בֵּית הַמִּדְרָשׁ אָסוּר לַעֲשׂוֹתוֹ בֵּית הַכְּנֶסֶת. שֶׁקְּדֻשַּׁת בֵּית הַמִּדְרָשׁ יְתֵרָה עַל קְדֻשַּׁת בֵּית הַכְּנֶסֶת וּמַעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין. וְכֵן בְּנֵי הָעִיר שֶׁמָּכְרוּ בֵּית הַכְּנֶסֶת יֵשׁ לָהֶן לִקַּח בְּדָמָיו תֵּבָה. מָכְרוּ תֵּבָה יֵשׁ לָהֶן לִקַּח בְּדָמֶיהָ מִטְפָּחוֹת אוֹ תִּיק לְסֵפֶר תּוֹרָה. מָכְרוּ מִטְפָּחוֹת אוֹ תִּיק לוֹקְחִים בְּדָמָיו חֻמָּשִׁים. מָכְרוּ חֻמָּשִׁין לוֹקְחִין בְּדָמָיו סֵפֶר תּוֹרָה. אֲבָל אִם מָכְרוּ סֵפֶר תּוֹרָה אֵין לוֹקְחִין בְּדָמָיו אֶלָּא סֵפֶר תּוֹרָה אַחֵר שֶׁאֵין שָׁם קְדֻשָּׁה לְמַעְלָה מִקְּדֻשַּׁת סֵפֶר תּוֹרָה. וְכֵן בְּמוֹתָרֶיהָ:","וְכֵן אִם גָּבוּ הָעָם מָעוֹת לִבְנוֹת בֵּית הַמִּדְרָשׁ אוֹ לְבֵית הַכְּנֶסֶת אוֹ לִקְנוֹת תֵּבָה אוֹ מִטְפָּחוֹת וְתִיק אוֹ סֵפֶר תּוֹרָה וְרָצוּ לְשַׁנּוֹת כָּל מַה שֶּׁגָּבוּ. אֵין מְשַׁנִּין אוֹתָן אֶלָּא מִקְּדֻשָּׁה קַלָּה לִקְדֻשָּׁה חֲמוּרָה מִמֶּנָּה. אֲבָל אִם עֲשׂוּ מַה שֶּׁגָּבוּ לַעֲשׂוֹת וְהוֹתִירוּ מְשַׁנִּין הַמּוֹתָר לְכָל מַה שֶּׁיִּרְצוּ. וְכָל כְּלֵי בֵּית הַכְּנֶסֶת כְּבֵית הַכְּנֶסֶת. פָּרֹכֶת שֶׁעַל הָאָרוֹן שֶׁמַּנִּיחִים בּוֹ הַסְּפָרִים כְּמִטְפְּחוֹת הַסְּפָרִים. וְאִם הִתְנוּ עֲלֵיהֶם הֲרֵי הֵן כְּפִי הַתְּנַאי:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁמֻּתָּר לִמְכֹּר בֵּית הַכְּנֶסֶת, בְּבֵית הַכְּנֶסֶת שֶׁל כְּפָרִים שֶׁלֹּא עָשׂוּ אוֹתוֹ אֶלָּא עַל דַּעַת בְּנֵי הַכְּפָר לְבַדָּם שֶׁיִּהְיֶה לָהֶם לְהִתְפַּלֵּל בּוֹ שֶׁאִם רָצוּ כֻּלָּם לְמָכְרוֹ מֻתָּרִין. אֲבָל בֵּית הַכְּנֶסֶת שֶׁל כְּרַכִּין הוֹאִיל וְעַל דַּעַת כָּל אַנְשֵׁי הָעוֹלָם נַעֲשָׂה שֶׁיָּבוֹא וְיִתְפַּלֵּל בּוֹ כָּל הַבָּא אֶל הַמְּדִינָה נַעֲשָׂה שֶׁל כָּל יִשְׂרָאֵל וְאֵין מוֹכְרִין אוֹתוֹ לְעוֹלָם:","בְּנֵי הַכְּפָר שֶׁרָצוּ לִמְכֹּר בֵּית הַכְּנֶסֶת שֶׁלָּהֶן אוֹ לִבְנוֹת בְּדָמָיו בֵּית הַכְּנֶסֶת אַחֵר אוֹ לִקְנוֹת בְּדָמָיו תֵּבָה אוֹ סֵפֶר תּוֹרָה צְרִיכִין לְהַתְנוֹת עַל הַלּוֹקֵחַ שֶׁלֹּא לַעֲשׂוֹת אוֹתוֹ לֹא מֶרְחָץ וְלֹא בֻּרְסְקִי. וְהוּא הַמָּקוֹם שֶׁמְּעַבְּדִין בּוֹ אֶת הָעוֹרוֹת. וְלֹא בֵּית הַטְּבִילָה וְלֹא בֵּית הַמַּיִם. וְאִם הִתְנוּ שִׁבְעָה טוֹבֵי הָעִיר בְּמַעֲמַד אַנְשֵׁי הָעִיר בִּשְׁעַת מְכִירָה שֶׁיְּהֵא הַלּוֹקֵחַ מֻתָּר לַעֲשׂוֹת בּוֹ כָּל אֵלּוּ מֻתָּר:","וְכֵן אִם הִתְנוּ שִׁבְעָה טוֹבֵי הָעִיר בְּמַעֲמַד אַנְשֵׁי הָעִיר עַל מוֹתַר הַדָּמִים שֶׁיִּהְיוּ חֻלִּין הֲרֵי הֵן חֻלִּין. וּכְשֶׁלּוֹקְחִין הַדָּמִים וּבוֹנִין מֵהֶן בֵּית הַכְּנֶסֶת אַחֵר אוֹ שֶׁיִּקְנוּ מֵהֶם תֵּבָה אוֹ מִטְפָּחוֹת וְתִיק אוֹ חֻמָּשִׁין אוֹ סֵפֶר תּוֹרָה הַשְּׁאָר יְהֵא חֻלִּין כְּמוֹ שֶׁהִתְנוּ וְיַעֲשׂוּ בָּהֶן מַה שֶּׁיִּרְצוּ:","וְכֵן אִם קִבְּלוּ עֲלֵיהֶן כָּל אַנְשֵׁי הָעִיר אוֹ רֻבָּם אָדָם אֶחָד. כָּל מַה שֶּׁעָשָׂה עָשׂוּי וְהוּא מוֹכֵר וְנוֹתֵן לְבַדּוֹ כְּפִי מַה שֶּׁיִּרְאֶה וְיַתְנֶה כְּפִי מַה שֶּׁיִּרְאֶה:","כְּשֵׁם שֶׁמֻּתָּר לָהֶם לִמְכֹּר בֵּית הַכְּנֶסֶת כָּךְ נוֹתְנִין אוֹתוֹ בְּמַתָּנָה. שֶׁאִלּוּ לֹא הָיָה לָהֶם לַצִּבּוּר הֲנָיָה בְּמַתָּנָה זוֹ לֹא נְתָנוּהוּ. אֲבָל לֹא מַשְׂכִּירִין אוֹתוֹ וְלֹא מְמַשְׁכְּנִין אוֹתוֹ. וְכֵן כְּשֶׁסּוֹתְרִין בָּתֵּי כְּנֵסִיּוֹת לִבְנוֹתָן מֻתָּרִין לִמְכֹּר וּלְהַחֲלִיף וְלָתֵת בְּמַתָּנָה הַלְּבֵנִים וְהָעֵצִים וְהֶעָפָר שֶׁלָּהֶן. אֲבָל לְהַלְווֹתָן אָסוּר שֶׁאֵין הַקְּדֻשָּׁה עוֹלָה מֵהֶן אֶלָּא בְּדָמִים אוֹ בַּהֲנָיָה שֶׁהִיא כְּדָמִים:","רְחוֹבָהּ שֶׁל עִיר אַף עַל פִּי שֶׁהָעָם מִתְפַּלְּלִין בּוֹ בְּתַעֲנִיּוֹת וּבְמַעֲמָדוֹת מִפְּנֵי שֶׁהַקִּבּוּץ רַב וְאֵין בָּתֵּי כְּנֵסִיּוֹת מְכִילִין אוֹתָן אֵין בּוֹ קְדֻשָּׁה מִפְּנֵי שֶׁהוּא עַרְאַי וְלֹא נִקְבַּע לִתְפִלָּה. וְכֵן בָּתִּים וַחֲצֵרוֹת שֶׁהָעָם מִתְקַבְּצִין בָּהֶם לִתְפִלָּה אֵין בָּהֶם קְדֻשָּׁה מִפְּנֵי שֶׁלֹּא קָבְעוּ אוֹתָם לִתְפִלָּה בִּלְבַד אֶלָּא עַרְאַי מִתְפַּלְּלִים בָּהֶן כְּאָדָם שֶׁמִּתְפַּלֵּל בְּתוֹךְ בֵּיתוֹ:"],"Mishneh Torah, Prayer and the Priestly Blessing 9":["סֵדֶר תְּפִלּוֹת הַצִּבּוּר כָּךְ הוּא. בַּשַּׁחַר כָּל הָעָם יוֹשְׁבִים וּשְׁלִיחַ צִבּוּר יוֹרֵד לִפְנֵי הַתֵּבָה וְעוֹמֵד בְּאֶמְצַע הָעָם וּמַתְחִיל וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִים אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא בְּכָל כֹּחָן. וְעוֹנִין אָמֵן בְּסוֹף קַדִּישׁ. וְאַחַר כָּךְ אוֹמֵר בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְהֵם עוֹנִים בָּרוּךְ יְיָ׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד. וּמַתְחִיל וּפוֹרֵס עַל שְׁמַע בְּקוֹל רָם וְהֵם עוֹנִים אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה. וְהַיּוֹדֵעַ לְבָרֵךְ וְלִקְרוֹת עִמּוֹ קוֹרֵא עַד שֶׁמְּבָרֵךְ גָּאַל יִשְׂרָאֵל:","וְהַכּל עוֹמְדִין מִיָּד וּמִתְפַּלְּלִים בְּלַחַשׁ. וּמִי שֶׁאֵינוֹ יוֹדֵעַ לְהִתְפַּלֵּל עוֹמֵד וְשׁוֹתֵק עַד שֶׁיִּתְפַּלֵּל שְׁלִיחַ צִבּוּר בְּלַחַשׁ עִם שְׁאָר הָעָם. וְכָל מִי שֶׁיִּגְמֹר תְּפִלָּתוֹ עִם הַצִּבּוּר יַפְסִיעַ שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו וְיַעֲמֹד בַּמָּקוֹם שֶׁהִגִּיעַ אֵלָיו בְּעֵת שֶׁיַּפְסִיעַ:","וְאַחַר שֶׁיַּפְסִיעַ שְׁלִיחַ צִבּוּר שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו וְיַעֲמֹד מַתְחִיל וּמִתְפַּלֵּל בְּקוֹל רָם מִתְּחִלַּת הַבְּרָכוֹת לְהוֹצִיא אֶת מִי שֶׁלֹּא הִתְפַּלֵּל. וְהַכּל עוֹמְדִים וְשׁוֹמְעִים וְעוֹנִין אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה. בֵּין אֵלּוּ שֶׁלֹּא יָצְאוּ יְדֵי חוֹבָתָן בֵּין אֵלּוּ שֶׁכְּבָר יָצְאוּ יְדֵי חוֹבָתָן:","וְאוֹמֵר קְדֻשָּׁה בִּבְרָכָה שְׁלִישִׁית. וְכֵיוָן שֶׁהִגִּיעַ שְׁלִיחַ צִבּוּר לִקְדֻשָּׁה יֵשׁ רְשׁוּת לְכָל אֶחָד וְאֶחָד לַחֲזֹר בַּמָּקוֹם שֶׁעָמַד בּוֹ בַּתְּפִלָּה. וּכְשֶׁיַּגִּיעַ שְׁלִיחַ צִבּוּר לְמוֹדִים וְכוֹרֵעַ כָּל הָעָם שׁוֹחִין מְעַט וְלֹא יִשְׁחוּ יוֹתֵר מִדַּאי. וְאוֹמְרִים מוֹדִים אֲנַחְנוּ לָךְ יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי כָל בָּשָׂר יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ כֵּן תְּחַיֵּנוּ וּתְחָנֵנוּ וְתֶאֱסֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ לִשְׁמֹר חֻקֶּיךָ וּלְעָבְדְךָ בֶּאֱמֶת וְלַעֲשׂוֹת רְצוֹנְךָ בְּלֵבָב שָׁלֵם עַל שֶׁאָנוּ מוֹדִים לָךְ. וְכָל הָאוֹמֵר מוֹדִים מוֹדִים מְשַׁתְּקִין אוֹתוֹ:","וְאַחַר שֶׁיַּשְׁלִים כָּל הַתְּפִלָּה יֵשֵׁב וְיִפּל עַל פָּנָיו וְיִטֶּה מְעַט הוּא וְכָל הַצִּבּוּר וְיִתְחַנֵּן וְהוּא נוֹפֵל. וְיֵשֵׁב וְיַגְבִּיהַּ רֹאשׁוֹ הוּא וּשְׁאָר הָעָם וּמִתְחַנֵּן מְעַט בְּקוֹל רָם מְיֻשָּׁב. וְאַחַר כָּךְ יַעֲמֹד שְׁלִיחַ צִבּוּר לְבַדּוֹ וְאוֹמֵר קַדִּישׁ פַּעַם שְׁנִיָּה וְהֵם עוֹנִים כְּדֶרֶךְ שֶׁעוֹנִין בַּתְּחִלָּה. וְאוֹמֵר (תהילים עח לח) ״וְהוּא רַחוּם״ וְכוּ׳‎ (תהילים קמה א) ״תְּהִלָּה״ וְכוּ׳‎. הוּא עוֹמֵד וְהֵם יוֹשְׁבִים וְהֵם קוֹרְאִים עִמּוֹ. וְאַחַר כָּךְ אוֹמֵר (ישעיה נט כ) ״וּבָא לְצִיּוֹן גּוֹאֵל״ וְכוּ׳‎ (ישעיה נט כא) ״וַאֲנִי זֹאת״ וְכוּ׳‎ (תהילים כב ד) ״וְאַתָּה קָדוֹשׁ״ (ישעיה ו ג) ״וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ״ וְגוֹמֵר הַקְּדֻשָּׁה וְהֵם עוֹנִין (ישעיה ו ג) ״קָדוֹשׁ קָדוֹשׁ״ שָׁלֹשׁ פְּעָמִים. וְחוֹזֵר וְקוֹרֵא הַקְּדֻשָּׁה תַּרְגּוּם וְאוֹמֵר (יחזקאל ג יב) ״וַתִּשָּׂאֵנִי רוּחַ״ וְכוּ׳‎ וְקוֹרֵא אוֹתוֹ תַּרְגּוּם וְאוֹמֵר (שמות טו יח) ״יְיָ׳‎ יִמְלוֹךְ לְעוֹלָם וָעֶד״ וְקוֹרְאֵהוּ תַּרְגּוּם כְּדֵי לְהָבִין הָעָם:","וְאֵלּוּ הַפְּסוּקִים שֶׁלִּפְנֵי הַקְּדֻשָּׁה וְשֶׁל אַחֲרֶיהָ עִם תַּרְגּוּמָן הֵם הַנִּקְרָאִין סֵדֶר קְדֻשָּׁה. וְאַחַר כָּךְ מִתְחַנֵּן בְּדִבְרֵי תַּחֲנוּנִים וּבִפְסוּקֵי רַחֲמִים וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִין כְּדַרְכָּן וְנִפְטָרִין:","מִי שֶׁאָמַר בְּתַחֲנוּנִים מִי שֶׁרִחֵם עַל קַן צִפּוֹר שֶׁלֹּא לִקַּח הָאֵם עַל הַבָּנִים אוֹ שֶׁלֹּא לִשְׁחֹט אוֹתוֹ וְאֶת בְּנוֹ בְּיוֹם אֶחָד יְרַחֵם עָלֵינוּ וְכַיּוֹצֵא בְּעִנְיָן זֶה מְשַׁתְּקִין אוֹתוֹ. מִפְּנֵי שֶׁמִּצְוֹת אֵלּוּ גְּזֵרַת הַכָּתוּב הֵן וְאֵינָן רַחֲמִים. שֶׁאִלּוּ הָיוּ מִפְּנֵי רַחֲמִים לֹא הָיָה מַתִּיר לָנוּ שְׁחִיטָה כָּל עִקָּר. וְכֵן לֹא יַרְבֶּה בְּכִנּוּיִים שֶׁל שֵׁם וְיֹאמַר (דברים י יז) ״הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא״ וְהֶחָזָק וְהָאַמִּיץ וְהָעִזּוּז. שֶׁאֵין כֹּחַ בָּאָדָם לְהַגִּיעַ בְּסוֹף שְׁבָחָיו. אֶלָּא אוֹמֵר מַה שֶּׁאָמַר משֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם:","בְּמִנְחָה אוֹמֵר שְׁלִיחַ צִבּוּר (תהילים פד ה) ״אַשְׁרֵי יוֹשְׁבֵי בֵּיתֶךָ״ וְכוּ׳‎ (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ וְכוּ׳‎ קוֹרֵא הוּא וְהָעָם מְיֻשָּׁב וְעוֹמֵד שְׁלִיחַ צִבּוּר וְאוֹמֵר קַדִּישׁ וְהֵם עוֹמְדִים אַחֲרָיו וְעוֹנִין כְּדַרְכָּן וּמִתְפַּלְּלִין כֻּלָּם בְּלַחַשׁ. וְאַחַר כָּךְ חוֹזֵר שְׁלִיחַ צִבּוּר וּמִתְפַּלֵּל בְּקוֹל רָם כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית עַד שֶׁיַּשְׁלִים כָּל הַתְּפִלָּה. וְנוֹפְלִים עַל פְּנֵיהֶם וּמִתְחַנֵּן וּמַגְבִּיהַּ רֹאשׁוֹ הוּא וְהֵם. וּמִתְחַנֵּן מְעַט מְיֻשָּׁב כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית וְעוֹמֵד וְאוֹמֵר קַדִּישׁ וְכָל הָעָם עוֹנִין כְּדַרְכָּן וְנִפְטָרִין לְמַעֲשֵׂיהֶם:","בָּעֶרֶב כָּל הָעָם יוֹשְׁבִין וְהוּא עוֹמֵד וְאוֹמֵר (תהילים עח לח) ״וְהוּא רַחוּם״ כוּ׳‎ בָּרְכוּ אֶת יְיָ׳‎ הַמְבֹרָךְ וְכוּ׳‎ וְהֵם עוֹנִין בָּרוּךְ יְיָ׳‎ הַמְבֹרָךְ לְעוֹלָם וָעֶד. וּמַתְחִיל לִפְרֹס עַל שְׁמַע וְאוֹמֵר קַדִּישׁ וְאַחַר כָּךְ הַכּל עוֹמְדִים וּמִתְפַּלְּלִין בְּלַחַשׁ. וּכְשֶׁמַּשְׁלִימִין אוֹמֵר קַדִּישׁ וְהֵם נִפְטָרִין. וְאֵינוֹ חוֹזֵר לְהִתְפַּלֵּל בְּקוֹל רָם עַרְבִית לְפִי שֶׁאֵין תְּפִלַּת עַרְבִית חוֹבָה לְפִיכָךְ לֹא יְבָרֵךְ בְּרָכוֹת לְבַטָּלָה שֶׁאֵין כָּאן אָדָם שֶׁנִּתְחַיֵּב בָּהֶם כְּדֵי לְהוֹצִיאוֹ יְדֵי חוֹבָתוֹ:","בְּלֵילֵי שַׁבָּתוֹת חוֹזֵר שַׁ״ץ אַחַר שֶׁמִּתְפַּלֵּל בְּלַחַשׁ עִם הַצִּבּוּר וּמִתְפַּלֵּל בְּקוֹל רָם. אֲבָל אֵינוֹ מִתְפַּלֵּל שֶׁבַע אֶלָּא בְּרָכָה אַחַת מֵעֵין שֶׁבַע. וְכֵן הוּא אוֹמֵר בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא אֵל עֶלְיוֹן קוֹנֶה בְּרַחֲמָיו שָׁמַיִם וָאָרֶץ. מָגֵן אָבוֹת בִּדְבָרוֹ מְחַיֵּה מֵתִים בְּמַאֲמָרוֹ הָאֵל הַקָּדוֹשׁ שֶׁאֵין כָּמוֹהוּ הַמֵּנִיחַ לְעַמּוֹ בְּשַׁבַּת קָדְשׁוֹ כִּי בָם רָצָה לְהָנִיחַ לָהֶם לְפָנָיו נַעֲבֹד בְּיִרְאָה וָפַחַד וְנוֹדֶה לִשְׁמוֹ בְּכָל יוֹם תָּמִיד מֵעֵין הַבְּרָכוֹת אֵל הַהוֹדָאוֹת אֲדוֹן הַשָּׁלוֹם מְקַדֵּשׁ הַשַּׁבָּת וּמְבָרֵךְ הַשְּׁבִיעִי וּמֵנִיחַ בִּקְדֻשָּׁה לְעַם מְדֻשְּׁנֵי עֹנֶג זֵכֶר לְמַעֲשֵׂה בְרֵאשִׁית. אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ רְצֵה נָא בִּמְנוּחָתֵנוּ וְכוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ מְקַדֵּשׁ הַשַּׁבָּת. וְאוֹמֵר קַדִּישׁ וְנִפְטָרִין כָּל הָעָם:","וְלָמָּה תִּקְּנוּ חֲכָמִים זֶה. מִפְּנֵי שֶׁרֹב הָעָם בָּאִין לְהִתְפַּלֵּל עַרְבִית בְּלֵילֵי שַׁבָּתוֹת וְיִהְיֶה שָׁם מִי שֶׁנִּתְאַחֵר לָבוֹא וְלֹא הִשְׁלִים תְּפִלָּתוֹ וְיִשָּׁאֵר לְבַדּוֹ בְּבֵית הַכְּנֶסֶת וְיָבוֹא לִידֵי סַכָּנָה. לְפִיכָךְ חוֹזֵר שְׁלִיחַ צִבּוּר וּמִתְפַּלֵּל כְּדֵי שֶׁיִּתְעַכְּבוּ כָּל הָעָם עַד שֶׁיַּשְׁלִים הַמִּתְאַחֵר וְיֵצֵא עִמָּהֶם:","לְפִיכָךְ יוֹם טוֹב שֶׁחָל לִהְיוֹת בְּשַׁבָּת אוֹ יוֹם הַכִּפּוּרִים אוֹ רֹאשׁ חֹדֶשׁ אֵין שְׁלִיחַ צִבּוּר הַיּוֹרֵד עַרְבִית לִפְנֵי הַתֵּבָה מַזְכִּיר עִנְיַן הַיּוֹם בִּבְרָכָה זוֹ אֲבָל חוֹתֵם בָּהּ מְקַדֵּשׁ הַשַּׁבָּת בִּלְבַד לְפִי שֶׁלֹּא נִתְחַיֵּב הַיּוֹם בִּבְרָכָה זוֹ:","בְּשַׁבָּתוֹת וְיָמִים טוֹבִים כְּשֶׁגּוֹמֵר שְׁלִיחַ צִבּוּר תְּפִלַּת שַׁחֲרִית בְּקוֹל רָם אוֹמֵר קַדִּישׁ וְאַחַר כָּךְ (תהילים קמה א) ״תְּהִלָּה לְדָוִד״ וְכוּ׳‎ וְאוֹמֵר קַדִּישׁ. וּמִתְפַּלְּלִין מוּסָף בְּלַחַשׁ וְאַחַר כָּךְ מִתְפַּלֵּל מוּסָף בְּקוֹל רָם כְּדֶרֶךְ שֶׁעָשָׂה בְּשַׁחֲרִית. וְאוֹמֵר קַדִּישׁ אַחַר תְּפִלַּת מוּסָף וְהָעָם נִפְטָרִין. וְאֵין אוֹמְרִין קְדֻשָּׁה וְתַחֲנוּנִים אַחַר תְּפִלַּת שַׁחֲרִית כִּשְׁאָר הַיָּמִים אֶלָּא אוֹמֵר אוֹתָהּ קֹדֶם תְּפִלַּת הַמִּנְחָה. כֵּיצַד. קוֹרֵא תְּהִלָּה לְדָוִד וְאוֹמֵר סֵדֶר הַיּוֹם וְדִבְרֵי תַּחֲנוּנִים וְאוֹמֵר קַדִּישׁ וּמִתְפַּלְּלִין מִנְחָה וְחוֹזֵר וּמַשְׁמִיעַ תְּפִלַּת מִנְחָה בְּקוֹל רָם וְאוֹמֵר קַדִּישׁ:","בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד אוֹמֵר סֵדֶר קְדֻשָּׁה קֹדֶם תְּפִלַּת מוּסָף. בְּמוֹצָאֵי שַׁבָּת אוֹמֵר סֵדֶר הַיּוֹם גַּם אַחַר תְּפִלַּת הָעֶרֶב וְאוֹמְרִים קַדִּישׁ וְאַחַר כָּךְ מַבְדִּיל:"],"Mishneh Torah, Red Heifer 1":["מִצְוַת פָּרָה אֲדֻמָּה שֶׁתִּהְיֶה בַּת שָׁלֹשׁ שָׁנִים אוֹ בַּת אַרְבַּע. וְאִם הָיְתָה זְקֵנָה כְּשֵׁרָה אֶלָּא שֶׁאֵין מַמְתִּינִין לָהּ שֶׁמָּא תַּשְׁחִיר וְתִפָּסֵל. וְאֵין לוֹקְחִין עֶגְלָה וּמְגַדְּלִין אוֹתָהּ שֶׁנֶּאֱמַר (במדבר יט ב) \"וְיִקְחוּ אֵלֶיךָ פָרָה\" וְלֹא עֶגְלָה. לֹא מָצְאוּ אֶלָּא עֶגְלָה פּוֹסְקִין עָלֶיהָ דָּמִים וְתִהְיֶה אֵצֶל בְּעָלֶיהָ עַד שֶׁתַּגְדִּיל וְתֵעָשֶׂה פָּרָה. וְלוֹקְחִין אוֹתָהּ מִתְּרוּמַת הַלִּשְׁכָּה:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (במדבר יט ב) \"תְּמִימָה\" תְּמִימַת אַדְמִימוּת לֹא תְּמִימַת קוֹמָה אֶלָּא אִם הָיְתָה נַנָּסָה כְּשֵׁרָה כִּשְׁאָר הַקָּדָשִׁים. הָיוּ בָּהּ שְׁתֵּי שְׂעָרוֹת לְבָנוֹת אוֹ שְׁחוֹרוֹת בְּתוֹךְ גֻּמָּא אַחַת אוֹ בְּתוֹךְ שְׁנֵי כּוֹסוֹת וְהֵן מֻנָּחוֹת זוֹ עַל זוֹ פְּסוּלָה:","הָיוּ בָּהּ שְׁתֵּי שְׂעָרוֹת עִקָּרָן מַאֲדִים וְרֹאשָׁן מַשְׁחִיר עִקָּרָן מַשְׁחִיר וְרֹאשָׁן מַאֲדִים הַכּל הוֹלֵךְ אַחַר הָעִקָּר. וְגוֹזֵז בְּמִסְפָּרַיִם אֶת רֹאשָׁן הַמַּשְׁחִיר וְאֵינוֹ חוֹשֵׁשׁ מִשּׁוּם גִּזָּה בְּקָדָשִׁים שֶׁאֵין כַּוָּנָתוֹ לָגֹז:","וְצָרִיךְ שֶׁיִּשָּׁאֵר מִן הַמַּאֲדִים כְּדֵי שֶׁיִּנָּטֵל בְּזוּג שֶׁכָּל שְׂעָרָה שֶׁאֵינָהּ נִטֶּלֶת בְּזוּג הֲרֵי הִיא כְּאִלּוּ אֵינָהּ. לְפִיכָךְ אִם הָיוּ בָּהּ שְׁתֵּי שְׂעָרוֹת לְבָנוֹת אוֹ שְׁחוֹרוֹת שֶׁאֵינָן נִלְקָטִין בְּזוּג הֲרֵי זוֹ כְּשֵׁרָה:","הָיוּ קַרְנֶיהָ אוֹ טְלָפֶיהָ שְׁחוֹרִים יָגוֹד. גַּלְגַּל הָעַיִן וְהַשִּׁנַּיִם וְהַלָּשׁוֹן אֵין מַרְאֵיהֶן פּוֹסְלִים בְּפָרָה:","הָיְתָה בָּהּ יַבֶּלֶת וַחֲתָכָהּ. אַף עַל פִּי שֶׁצָּמַח בִּמְקוֹמָהּ שֵׂעָר אָדֹם פְּסוּלָה:","כָּל הַמּוּמִין הַפּוֹסְלִין בְּקָדָשִׁים פּוֹסְלִין בְּפָרָה שֶׁנֶּאֱמַר (במדבר יט ב) \"אֲשֶׁר אֵין בָּהּ מוּם\". הָיְתָה יוֹצֵא דֹּפֶן אוֹ מְחִיר אוֹ אֶתְנָן אוֹ טְרֵפָה אוֹ שֶׁנִּרְבְּעָה פְּסוּלָה. שֶׁכָּל הַפּוֹסְלִין אֶת הַקָּדָשִׁים לַמִּזְבֵּחַ פּוֹסְלִין אֶת הַפָּרָה וְאַף עַל פִּי שֶׁהִיא כְּקָדְשֵׁי בֶּדֶק הַבַּיִת הוֹאִיל וּקְרָאָהּ הַכָּתוּב חַטָּאת. וּמֻתָּר לִקַּח אוֹתָהּ מִן הָעַכּוּ\"ם וְאֵין חוֹשְׁשִׁין שֶׁמָּא רְבָעָהּ הָעַכּוּ\"ם שֶׁאֵינוֹ מַפְסִיד בְּהֶמְתּוֹ. יְתֵרָה פָּרָה עַל הַקָּדָשִׁים שֶׁהָעֲבוֹדָה פּוֹסֶלֶת בָּהּ שֶׁנֶּאֱמַר (במדבר יט ב) \"אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל\" וּבְעֶגְלָה עֲרוּפָה אוֹמֵר (דברים כא ג) \"אֲשֶׁר לֹא עֻבַּד בָּהּ אֲשֶׁר לֹא מָשְׁכָה בְּעֹל\" מָה עֹל הָאָמוּר בְּעֶגְלָה עָשָׂה שְׁאָר עֲבוֹדוֹת כְּעל אַף עֹל הָאָמוּר בְּפָרָה יִפְסל בָּהּ שְׁאָר עֲבוֹדוֹת כְּעל. אֶלָּא שֶׁהָעל פּוֹסֵל בֵּין בִּשְׁעַת עֲבוֹדָה בֵּין שֶׁלֹּא בִּשְׁעַת עֲבוֹדָה וּשְׁאָר עֲבוֹדוֹת אֵין פּוֹסְלוֹת אֶלָּא בִּשְׁעַת עֲבוֹדָה. כֵּיצַד. קָשַׁר עָלֶיהָ הָעל אַף עַל פִּי שֶׁלֹּא חָרַשׁ בָּהּ פְּסוּלָה. הִכְנִיסָהּ לָדוּשׁ אֵינָהּ נִפְסֶלֶת עַד שֶׁיָּדוּשׁ בָּהּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. רָכַב עָלֶיהָ. נִשְׁעַן עָלֶיהָ. נִתְלָה בִּזְנָבָהּ. וְעָבַר בָּהּ אֶת הַנָּהָר. קִפֵּל עָלֶיהָ אֶת הַמּוֹסֵרָה. נָתַן טַלִּיתוֹ עָלֶיהָ. נָתַן עָלֶיהָ כְּסוּת שֶׁל שַׂקִּים. פְּסוּלָה. קְשָׁרָהּ בְּמוֹסֵרָה אִם הָיְתָה מוֹרֶדֶת וּצְרִיכָה שְׁמִירָה כְּשֵׁרָה וְאִם לָאו פְּסוּלָה שֶׁכָּל שְׁמִירָה שֶׁאֵינָהּ צְרִיכָה מַשּׂוֹי הוּא. עָשָׂה בָּהּ סַנְדָּל שֶׁלֹּא תַּחְלֵּק. פֵּרַשׂ טַלִּיתוֹ עָלֶיהָ מִפְּנֵי הַזְּבוּבִין. כְּשֵׁרָה. זֶה הַכְּלָל כָּל שֶׁהוּא לְצָרְכָּהּ כְּשֵׁרָה לְצֹרֶךְ אַחֵר פְּסוּלָה. נַעֲשֵׂית בָּהּ מְלָאכָה מֵאֵלֶיהָ אוֹ שֶׁעָלָה עָלֶיהָ עֹל מֵאֵלָיו. אִם לִרְצוֹנוֹ פְּסוּלָה שֶׁנֶּאֱמַר אֲשֶׁר לֹא עֻבַּד בָּהּ שֶׁאִם עֻבַּד בָּהּ לִרְצוֹנוֹ הֲרֵי זֶה כְּמִי שֶׁעָבַד בָּהּ. לְפִיכָךְ אִם שָׁכַן עָלֶיהָ הָעוֹף כְּשֵׁרָה. עָלָה עָלֶיהָ זָכָר פְּסוּלָה. וְאֵין צָרִיךְ לוֹמַר שֶׁהַמְעֻבֶּרֶת פְּסוּלָה. הִכְנִיסָהּ לִרְבָקָה וְדָשָׁה מֵאֵלֶיהָ כְּשֵׁרָה. הִכְנִיסָהּ כְּדֵי שֶׁתִּינַק וְתָדוּשׁ פְּסוּלָה שֶׁהֲרֵי עָשָׂה לִרְצוֹנוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","פָּרָה שֶׁנּוֹלַד בָּהּ פְּסוּל תִּפָּדֶה. וְכֵן אִם מֵתָה תִּפָּדֶה מִפְּנֵי עוֹרָהּ. אֲבָל לֹא לְהַאֲכִיל בְּשָׂרָהּ לִכְלָבִים:","נִשְׁחֲטָה לְשֵׁם חֻלִּין תִּפָּדֶה וְאֵינָהּ מְכַפֶּרֶת. נִשְׁחֲטָה עַל גַּב מַעֲרַכְתָּהּ אֵין לָהּ פִּדְיוֹן עוֹלָמִית:","לָקְחוּ פָּרָה וּמָצְאוּ אַחֶרֶת נָאָה מִמֶּנָּה הֲרֵי זוֹ תִּפָּדֶה שֶׁלֹּא בְּמוּם:","אַף כֹּהֵן הֶדְיוֹט כָּשֵׁר לִשְׂרֵפַת הַפָּרָה שֶׁנֶּאֱמַר (במדבר יט ג) \"וּנְתַתֶּם אֹתָהּ אֶל אֶלְעָזָר הַכֹּהֵן\" וַעֲדַיִן אַהֲרֹן הָיָה קַיָּם. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ זוֹ נַעֲשֵׂית בְּאֶלְעָזָר וּשְׁאָר כָּל הַפָּרוֹת בֵּין בְּכֹהֵן גָּדוֹל בֵּין בְּכֹהֵן הֶדְיוֹט:","וְהָעוֹשֶׂה אוֹתָהּ לוֹבֵשׁ אַרְבָּעָה כֵּלִים שֶׁל כֹּהֵן הֶדְיוֹט. בֵּין שֶׁעֲשָׂאָהּ כֹּהֵן הֶדְיוֹט בֵּין שֶׁעֲשָׂאָהּ כֹּהֵן גָּדוֹל:","כָּל הָעוֹסְקִין בַּפָּרָה מִתְּחִלָּה וְעַד סוֹף שֶׁהָיוּ טְבוּלֵי יוֹם כְּשֵׁרִים לְמַעֲשֵׂה הַפָּרָה וּלְקַדֵּשׁ וּלְהַזּוֹת מֵאֶפְרָהּ וְאַף עַל פִּי שֶׁעֲדַיִן לֹא הֶעֱרִיב שִׁמְשָׁן. שֶׁזֶּה שֶׁנֶּאֱמַר בְּכָל הַפָּרָשָׁה (במדבר יט ט) \"אִישׁ טָהוֹר\" הוּא הַטָּהוֹר לְמַעֲשֵׂר שֵׁנִי אַף עַל פִּי שֶׁאֵינוֹ טָהוֹר לִתְרוּמָה עַד שֶׁיַּעֲרִיב שִׁמְשׁוֹ הֲרֵי זֶה טָהוֹר לְפָרָה:","הַצְּדוֹקִין הָיוּ אוֹמְרִים שֶׁאֵין מַעֲשֵׂה הַפָּרָה כָּשֵׁר אֶלָּא בִּמְעֹרָבֵי שֶׁמֶשׁ. לְפִיכָךְ הָיוּ בֵּית דִּין בְּבַיִת שֵׁנִי מְטַמְּאִין אֶת הַכֹּהֵן הַשּׂוֹרֵף אֶת הַפָּרָה בְּשֶׁרֶץ וְכַיּוֹצֵא בּוֹ וְטוֹבֵל וְאַחַר כָּךְ עוֹסֵק בָּהּ כְּדֵי לְבַטֵּל דִּבְרֵי אֵלּוּ הַזֵּדִים שֶׁמּוֹרִים מֵהָעוֹלֶה עַל רוּחָם לֹא מִן הַקַּבָּלָה. וְכֵן כָּל הַכֵּלִים שֶׁמַּכְנִיסִין לְתוֹכָם אֵפֶר הַפָּרָה כֻּלָּם טְבוּלֵי יוֹם:","הַחוֹתֵךְ שְׁפוֹפֶרֶת שֶׁל קָנֶה לְהַנִּיחַ בָּהּ אֵפֶר חַטָּאת יְטַמֵּא אוֹתָהּ וְיִטְבְּלֶנָּה וְאַחַר כָּךְ יַנִּיחַ בָּהּ. וְהַחוֹתְכָהּ וְהַמַּטְבִּילָהּ טָעוּן טְבִילָה מִפְּנֵי שֶׁעֲשָׂאוּהָ כִּטְמֵא מֵת בַּשְּׁבִיעִי שֶׁלּוֹ וּלְפִיכָךְ אֵינָהּ צְרִיכָה הַזָּאָה שְׁלִישִׁי וּשְׁבִיעִי אֶלָּא מְטַמְּאָהּ כְּדֵי לְהַרְאוֹת לַצְּדוֹקִין וּמַטְבִּילָהּ וְנוֹתֵן בָּהּ:"],"Mishneh Torah, Red Heifer 7":["הַמְּלָאכָה פּוֹסֶלֶת בְּמַיִם קֹדֶם שֶׁיִּתְקַדְּשׁוּ וְאֵינָהּ פּוֹסֶלֶת בְּהַזָּאָה. וּדְבָרִים אֵלּוּ הֵן דִּבְרֵי קַבָּלָה. כֵּיצַד. הַמְמַלֵּא מַיִם לְקִדּוּשׁ וְנִתְעַסֵּק בִּמְלָאכָה אַחֶרֶת בִּשְׁעַת הַמִּלּוּי אוֹ בִּשְׁעַת הוֹלָכַת הַמַּיִם שֶׁמְּמַלֵּא אוֹ בְּעֵת שֶׁמְּעָרֶה אוֹתָן מִכְּלִי אֶל כְּלִי פְּסָלָן. לְעוֹלָם הַמְּלָאכָה פּוֹסֶלֶת בְּמַיִם עַד שֶׁיָּטִיל לָהֶן אֶת הָאֵפֶר. הֵטִיל אֶת הָאֵפֶר וְנִתְקַדְּשׁוּ וְנַעֲשׂוּ מֵי נִדָּה אֵין הַמְּלָאכָה פּוֹסֶלֶת בָּהֶן אֶלָּא הַמּוֹלִיךְ הַמַּיִם הַמֻּקְדָּשִׁין אוֹ מְעָרֶה אוֹתָן מִכְּלִי לִכְלִי וְהוּא עוֹסֵק בִּמְלָאכָה אַחֶרֶת אֵין בְּכָךְ כְּלוּם. וְכֵן מַזֶּה מֵהֶן בְּיָדוֹ אַחַת וְהוּא עוֹשֶׂה מְלָאכָה בְּיָדוֹ הָאַחֶרֶת:","הַשָּׂכָר פָּסוּל בְּקִדּוּשׁ וּבַהַזָּיָה וְאֵינוֹ פּוֹסֵל בְּמִלּוּי. כֵּיצַד. הַנּוֹטֵל שְׂכָרוֹ לְקַדֵּשׁ מֵי חַטָּאת אוֹ לְהַזּוֹת מֵהֶן הֲרֵי אוֹתָן הַמַּיִם כְּמֵי הַמְּעָרָה וְהָאֵפֶר כְּאֵפֶר מַקְלֶה שֶׁאֵינוֹ כְּלוּם. אֲבָל נוֹטֵל הוּא שָׂכָר לְמַלְּאוֹת הַמַּיִם אוֹ לְהוֹלִיכָן. וּמְקַדְּשִׁין אוֹתָן בְּחִנָּם וּמַזֶּה מֵהֶן הַמַּזֶּה בְּחִנָּם. הָיָה הַמְקַדֵּשׁ אוֹ הַמַּזֶּה זָקֵן שֶׁאֵינוֹ יָכוֹל לְהַלֵּךְ עַל רַגְלָיו וּבָא הַטָּמֵא וּבִקֵּשׁ מִמֶּנּוּ לַהֲלֹךְ עִמּוֹ בְּמָקוֹם רָחוֹק לְקַדֵּשׁ אוֹ לְהַזּוֹת הֲרֵי זֶה מַרְכִּיבוֹ עַל הַחֲמוֹר וְנוֹתֵן שְׂכָרוֹ כְּפוֹעֵל בָּטֵל שֶׁבָּטֵל מֵאוֹתָהּ מְלָאכָה שֶׁבִּטְּלוֹ מִמֶּנָּה. וְכֵן אִם הָיָה כֹּהֵן וְהָיָה טָמֵא בְּטֻמְאָה הַמּוֹנַעְתּוֹ מִלֶּאֱכל תְּרוּמָתוֹ בְּעֵת שֶׁיֵּלֵךְ עִמּוֹ לְהַזּוֹת אוֹ לְקַדֵּשׁ הֲרֵי זֶה מַאֲכִילוֹ וּמַשְׁקֵהוּ וְסָכוֹ. וְאִם בִּטְּלוֹ מִמְּלָאכָה נוֹתֵן לוֹ שְׂכָרוֹ כְּפוֹעֵל בָּטֵל שֶׁל אוֹתָהּ מְלָאכָה. שֶׁכָּל אֵלּוּ הַדְּבָרִים אֵינָן שָׂכָר שֶׁנִּשְׂתַּכֵּר בְּקִדּוּשׁ אוֹ בְּהַזָּאָה שֶׁהֲרֵי לֹא הִרְוִיחַ כְּלוּם וְלֹא נָטַל אֶלָּא כְּנֶגֶד מַה שֶּׁהִפְסִיד:","הַמְמַלֵּא בְּאַחַת יָדוֹ וְעוֹשֶׂה מְלָאכָה בְּיָדוֹ הָאַחֶרֶת אוֹ הַמְמַלֵּא לוֹ וּלְאַחֵר אוֹ שֶׁמִּלֵּא לִשְׁנַיִם כְּאַחַת שְׁנֵיהֶן פְּסוּלִין שֶׁהַמִּלּוּי מְלָאכָה וְנִמְצָא כָּל מִלּוּי מִשְּׁנֵיהֶם כְּאִלּוּ עָשָׂה עִמּוֹ מְלָאכָה אַחֶרֶת. וּכְבָר הוֹדַעְנוּ שֶׁהַמְּלָאכָה פּוֹסֶלֶת בְּמִלּוּי בֵּין שֶׁמִּלֵּא לְעַצְמוֹ בֵּין שֶׁמִּלֵּא לַאֲחֵרִים:","הַמְמַלֵּא לַאֲחֵרִים אֲפִלּוּ מִלֵּא אֶלֶף חָבִיּוֹת זוֹ אַחַר זוֹ לְאֶלֶף בְּנֵי אָדָם כֻּלָּן כְּשֵׁרִים וְכָל אֶחָד מֵהֶן נוֹטֵל הַמַּיִם שֶׁלּוֹ וּמְקַדְּשָׁן. מִלֵּא לְעַצְמוֹ חָבִית אַחַר חָבִית אִם נִתְכַּוֵּן לְקַבֵּץ כָּל הֶחָבִיּוֹת לִכְלִי אֶחָד וּלְהַשְׁלִיךְ עֲלֵיהֶן אֶת הָאֵפֶר וּמְקַדְּשָׁן קִדּוּשׁ אֶחָד כֻּלָּן כְּשֵׁרִים שֶׁהַכּל מִלּוּי אֶחָד הוּא. אֲבָל אִם נִתְכַּוֵּן לְקַדֵּשׁ כָּל חָבִית וְחָבִית בִּפְנֵי עַצְמָהּ כֻּלָּן פְּסוּלִין חוּץ מִן הָאַחֲרוֹנָה שֶׁהָרִאשׁוֹנָה נִפְסֶלֶת בַּמְּלָאכָה שֶׁעָשָׂה קֹדֶם שֶׁיְּקַדֵּשׁ וְהוּא מִלּוּי הַשְּׁנִיָּה. וְכֵן הַשְּׁנִיָּה נִפְסֶלֶת בְּמִלּוּי הַשְּׁלִישִׁית וְאֵין כְּשֵׁרָה אֶלָּא אַחֲרוֹנָה:","חֲמִשָּׁה שֶׁמִּלְּאוּ חָמֵשׁ חָבִיּוֹת לְקַדְּשָׁם חֲמִשָּׁה קִדּוּשִׁים כְּגוֹן שֶׁיַּשְׁלִיךְ הָאֵפֶר עַל כָּל אַחַת וְאַחַת בִּפְנֵי עַצְמוֹ וְנִמְלְכוּ לְעָרְבָן וּלְקַדְּשָׁן כֻּלָּן קִדּוּשׁ אֶחָד אוֹ שֶׁמִּלְּאוּם לְקַדְּשָׁן קִדּוּשׁ אֶחָד וְנִמְלְכוּ לְקַדְּשָׁן חֲמִשָּׁה קִדּוּשִׁין כֻּלָּן כְּשֵׁרִין שֶׁהֲרֵי לֹא נִתְעַסֵּק הַמְמַלֵּא בְּמִלּוּי אַחֵר. אֲבָל הַיָּחִיד שֶׁמִּלֵּא חָמֵשׁ חָבִיּוֹת לְקַדְּשָׁם חֲמִשָּׁה קִדּוּשִׁין אַף עַל פִּי שֶׁחָזַר וְנִמְלַךְ לְקַדְּשָׁן קִדּוּשׁ אֶחָד אֵין כָּשֵׁר אֶלָּא אַחֲרוֹן. מִלְּאָן לְקַדְּשָׁן קִדּוּשׁ אֶחָד וְנִמְלַךְ לְקַדְּשָׁן חֲמִשָּׁה קִדּוּשִׁין אֵין כָּשֵׁר אֶלָּא זֶה שֶׁקִּדֵּשׁ בַּתְּחִלָּה. וְכֵן אִם אָמַר לְאַחֵר קַדֵּשׁ לְךָ אֶת אֵלּוּ אֵין כָּשֵׁר אֶלָּא זוֹ שֶׁנִּתְקַדְּשָׁה מֵהֶן בַּתְּחִלָּה. אֲבָל אִם אָמַר לוֹ קַדֵּשׁ לִי אֶת אֵלּוּ הֲרֵי כֻּלָּן כְּשֵׁרִין שֶׁהֲרֵי לְקִדּוּשׁ אֶחָד מִלְּאָן וְאַף עַל פִּי שֶׁנִּמְלַךְ עָלֶיהָ לְקַדְּשָׁהּ חֲמִשָּׁה קִדּוּשִׁין הֲרֵי לֹא קִדֵּשׁ הוּא אֶלָּא אַחֵר קִדֵּשׁ לוֹ:","הָרוֹצֶה לְמַלְּאוֹת מַיִם לְקַדְּשָׁן וּמַיִם אֲחֵרִים לִצְרָכָיו מְמַלֵּא אֶת שֶׁל צְרָכָיו תְּחִלָּה וְקוֹשְׁרָן וְטוֹעֲנָן לַאֲחוֹרָיו וְאַחַר כָּךְ מְמַלֵּא אֶת שֶׁל חַטָּאת כְּדֵי שֶׁלֹּא יִתְעַסֵּק בִּמְלָאכָה אַחַר הַמִּלּוּי וְנוֹתְנָם לְפָנָיו וְהוֹלֵךְ:","שְׁנַיִם שֶׁהָיוּ מְמַלְּאִין כָּל אֶחָד וְאֶחָד לְעַצְמוֹ וְהִגְבִּיהוּ זֶה עַל זֶה וְנָטַל זֶה לָזֶה קוֹץ מִיָּדוֹ אוֹ מִגּוּפוֹ בִּשְׁעַת מִלּוּאוֹ אִם מִלְּאוּ שְׁנֵיהֶם לְקִדּוּשׁ אֶחָד הַמַּיִם כְּשֵׁרִים וְאִם מִלְּאוּ לְקַדֵּשׁ כָּל אֶחָד לְעַצְמוֹ זֶה שֶׁהִגְבִּיהַּ אוֹ הוֹצִיא אֶת הַקּוֹץ פָּסַל מֵימָיו:","הַשּׁוֹאֵל חֶבֶל לְמַלְּאוֹת בּוֹ וּמִלֵּא וְנָטַל הַחֶבֶל בְּיָדָיו וּמֵימָיו עַל כְּתֵפוֹ וּפָגַע בַּבְּעָלִים בְּדַרְכּוֹ וְנָתַן לָהֶן אֶת הַחֶבֶל כְּשֶׁהוּא מְהַלֵּךְ כְּשֵׁרִין. וְאִם יָצָא מִן הַדֶּרֶךְ כְּדֵי לְהוֹלִיךְ הַחֶבֶל לַבְּעָלִים פָּסַל אֶת הַמַּיִם:","מִי שֶׁהָיָה מְמַלֵּא וּמַשְׁלִיךְ הַחֶבֶל שֶׁמִּלֵּא בּוֹ עַל הָאָרֶץ וְאַחַר שֶׁמִּלֵּא חָזַר וְקִבֵּץ עַל יָדוֹ פְּסָלָן. וְאִם הָיָה דּוֹלֶה וּמְקַבֵּץ לְתוֹךְ יָדוֹ הַמַּיִם כְּשֵׁרִים:","הַמְמַלֵּא וְנוֹתֵן לֶחָבִית עַד שֶׁיְּמַלְּאֶנָּה מַיִם וְהִצְנִיעַ אֶת הֶחָבִית שֶׁלֹּא תִּשָּׁבֵר בְּשָׁעָה שֶׁהָיָה מְמַלֵּא אוֹ שֶׁכְּפָאָהּ עַל פִּיהָ עַל מְנָת לְנַגְּבָהּ לְמַלְּאוֹת בָּהּ כָּשֵׁר שֶׁזֶּה מִצֹּרֶךְ הַמִּלּוּי הוּא. אֲבָל אִם הִצְנִיעָהּ אוֹ נִגְּבָהּ כְּדֵי לְהוֹלִיךְ בָּהּ אֶת הַקִּדּוּשׁ פָּסַל שֶׁהֲרֵי עָשָׂה מְלָאכָה שֶׁאֵינָהּ לְצֹרֶךְ הַמִּלּוּי. וְכֵן הַמְמַלֵּא וְנוֹתֵן לְשֹׁקֶת וּפִנָּה חַרְסִית מִן הַשֹּׁקֶת בִּשְׁעַת מִלּוּי אִם בִּשְׁבִיל שֶׁתַּחְזִיק מַיִם רַבִּים כְּשֵׁרִים שֶׁהֲרֵי זוֹ צֹרֶךְ הַמִּלּוּי וְאִם בִּשְׁבִיל שֶׁלֹּא יִהְיוּ הַחֲרָסִין מְעַכְּבִין אוֹתוֹ בְּשָׁעָה שֶׁהוּא זוֹלֵף אֶת הַמַּיִם שֶׁמִּלֵּא בַּשֹּׁקֶת הֲרֵי אֵלּוּ פְּסוּלִין:","הַמְמַלֵּא דְּלִי לִשְׁתּוֹת וְנִמְלַךְ וְחִשֵּׁב עָלָיו לְמֵי חַטָּאת אִם עַד שֶׁלֹּא הִגִּיעַ הַדְּלִי לַמַּיִם חִשֵּׁב מְעָרֶה וְאֵין צָרִיךְ לְנַגֵּב וְאִם מִשֶּׁהִגִּיעַ הַדְּלִי לַמַּיִם חִשֵּׁב מְעָרֶה וְצָרִיךְ לְנַגֵּב וְאַחַר כָּךְ יְמַלֵּא בּוֹ לְחַטָּאת. שִׁלְשֵׁל הַדְּלִי וְנִפְסַק הַחֶבֶל מִיָּדוֹ אִם עַד שֶׁלֹּא הִגִּיעַ הַדְּלִי לַמַּיִם חִשֵּׁב עָלָיו מְעָרֶה וְאֵין צָרִיךְ לְנַגֵּב. נִמְלַךְ וְהוּא עוֹדֵהוּ בְּתוֹךְ הַמַּיִם וְחִשֵּׁב עָלָיו לְמֵי חַטָּאת מְעָרֶה וְאֵינוֹ צָרִיךְ לְנַגֵּב. מַיִם שֶׁמִּלְּאָן לְמֵי חַטָּאת וְאַחַר שֶׁנִּתְמַלֵּא חִשֵּׁב עֲלֵיהֶן לִשְׁתּוֹתָן כְּשֶׁיַּטֶּה אֶת הַכְּלִי לִשְׁתּוֹת פָּסַל הַמַּיִם אַף עַל פִּי שֶׁלֹּא שָׁתָה מֵהֶן כְּלוּם:"],"Mishneh Torah, Repentance 9":["מֵאַחַר שֶׁנּוֹדַע שֶׁמַּתַּן שְׂכָרָן שֶׁל מִצְוֹת וְהַטּוֹבָה שֶׁנִּזְכֶּה לָהּ אִם שָׁמַרְנוּ דֶּרֶךְ ה' הַכָּתוּב בַּתּוֹרָה הִיא חַיֵּי הָעוֹלָם הַבָּא שֶׁנֶּאֱמַר (דברים כב ז) \"לְמַעַן יִיטַב לָךְ וְהַאֲרַכְתָּ יָמִים\". וְהַנְּקָמָה שֶׁנּוֹקְמִים מִן הָרְשָׁעִים שֶׁעָזְבוּ אָרְחוֹת הַצֶּדֶק הַכְּתוּבוֹת בַּתּוֹרָה הִיא הַכָּרֵת שֶׁנֶּאֱמַר (במדבר טו לא) \"הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִיא עֲוֹנָהּ בָּהּ\". מַהוּ זֶה שֶׁכָּתוּב בְּכָל הַתּוֹרָה כֻּלָּהּ אִם תִּשְׁמְעוּ יַגִּיעַ לָכֶם כָּךְ (ויקרא כו יד) \"וְאִם לֹא תִּשְׁמְעוּ\" יִקְרֶה אֶתְכֶם כָּךְ. וְכָל אוֹתָן הַדְּבָרִים בָּעוֹלָם הַזֶּה. כְּגוֹן שֹׂבַע וְרָעָב וּמִלְחָמָה וְשָׁלוֹם וּמַלְכוּת וְשִׁפְלוּת וִישִׁיבַת הָאָרֶץ וְגָלוּת וְהַצְלָחַת מַעֲשֶׂה וְהֶפְסֵדוֹ וּשְׁאָר כָּל דִּבְרֵי הַבְּרִית. כָּל אוֹתָן הַדְּבָרִים אֱמֶת הָיוּ וְיִהְיוּ וּבִזְמַן שֶׁאָנוּ עוֹשִׂים כָּל מִצְוֹת הַתּוֹרָה יַגִּיעוּ אֵלֵינוּ טוֹבוֹת הָעוֹלָם הַזֶּה כֻּלָּן. וּבִזְמַן שֶׁאָנוּ עוֹבְרִין עֲלֵיהֶן תִּקְרֶאנָה אוֹתָנוּ הָרָעוֹת הַכְּתוּבוֹת. וְאַף עַל פִּי כֵן אֵין אוֹתָן הַטּוֹבוֹת הֵם סוֹף מַתַּן שְׂכָרָן שֶׁל מִצְוֹת וְלֹא אוֹתָן הָרָעוֹת הֵם סוֹף הַנְּקָמָה שֶׁנּוֹקְמִין מֵעוֹבֵר עַל כָּל הַמִּצְוֹת. אֶלָּא כָּךְ הוּא הֶכְרֵעַ כָּל הַדְּבָרִים. הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָנוּ תּוֹרָה זוֹ עֵץ חַיִּים הִיא. וְכָל הָעוֹשֶׂה כָּל הַכָּתוּב בָּהּ וְיוֹדְעוֹ דֵּעָה גְּמוּרָה נְכוֹנָה זוֹכֶה בָּהּ לְחַיֵּי הָעוֹלָם הַבָּא. וּלְפִי גֹּדֶל מַעֲשָׂיו וְרֹב חָכְמָתוֹ הוּא זוֹכֶה. וְהִבְטִיחָנוּ בַּתּוֹרָה שֶׁאִם נַעֲשֶׂה אוֹתָהּ בְּשִׂמְחָה וּבְטוֹבַת נֶפֶשׁ וְנֶהְגֶּה בְּחָכְמָתָהּ תָּמִיד שֶׁיָּסִיר מִמֶּנּוּ כָּל הַדְּבָרִים הַמּוֹנְעִים אוֹתָנוּ מִלַּעֲשׂוֹתָהּ כְּגוֹן חלִי וּמִלְחָמָה וְרָעָב וְכַיּוֹצֵא בָּהֶן. וְיַשְׁפִּיעַ לָנוּ כָּל הַטּוֹבוֹת הַמַּחֲזִיקוֹת אֶת יָדֵינוּ לַעֲשׂוֹת הַתּוֹרָה כְּגוֹן שֹׂבַע וְשָׁלוֹם וְרִבּוּי כֶּסֶף וְזָהָב. כְּדֵי שֶׁלֹּא נַעֲסֹק כָּל יָמֵינוּ בִּדְבָרִים שֶׁהַגּוּף צָרִיךְ לָהֶן אֶלָּא נֵשֵׁב פְּנוּיִים לִלְמֹד בַּחָכְמָה וְלַעֲשׂוֹת הַמִּצְוָה כְּדֵי שֶׁנִּזְכֶּה לְחַיֵּי הָעוֹלָם הַבָּא. וְכֵן הוּא אוֹמֵר בַּתּוֹרָה אַחַר שֶׁהִבְטִיחַ בְּטוֹבוֹת הָעוֹלָם הַזֶּה (דברים ו כה) \"וּצְדָקָה תִּהְיֶה לָּנוּ\" וְגוֹ'. וְכֵן הוֹדִיעָנוּ בַּתּוֹרָה שֶׁאִם נַעֲזֹב הַתּוֹרָה מִדַּעַת וְנַעֲסֹק בְּהַבְלֵי הַזְּמַן כָּעִנְיָן שֶׁנֶּאֱמַר (דברים לב טו) \"וַיִּשְׁמַן יְשֻׁרוּן וַיִּבְעָט\", שֶׁדַּיַן הָאֱמֶת יָסִיר מִן הַעוֹזְבִים כָּל טוֹבוֹת הָעוֹלָם הַזֶּה שֶׁהֵן חִזְּקוּ יְדֵיהֶם לִבְעֹט וּמֵבִיא עֲלֵיהֶם כָּל הָרָעוֹת הַמּוֹנְעִים אוֹתָן מִלִּקְנוֹת הָעוֹלָם הַבָּא כְּדֵי שֶׁיֹּאבְדוּ בְּרִשְׁעָם. הוּא שֶׁכָּתוּב בַּתּוֹרָה (דברים כח מז) \"תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה'\" וְגוֹ', (דברים כח מח) \"וְעָבַדְתָּ אֶת אֹיְבֶיךָ אֲשֶׁר יְשַׁלְּחֶנּוּ ה' בָּךְ\". נִמְצָא פֵּרוּשׁ כָּל אוֹתָן הַבְּרָכוֹת וְהַקְּלָלוֹת עַל דֶּרֶךְ זוֹ, כְּלוֹמַר אִם עֲבַדְתֶּם אֶת ה' בְּשִׂמְחָה וּשְׁמַרְתֶּם דַּרְכּוֹ מַשְׁפִּיעַ לָכֶם הַבְּרָכוֹת הָאֵלּוּ וּמַרְחִיק הַקְּלָלוֹת מִכֶּם עַד שֶׁתִּהְיוּ פְּנוּיִים לְהִתְחַכֵּם בַּתּוֹרָה וְלַעֲסֹק בָּהּ כְּדֵי שֶׁתִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא וְיִיטַב לְךָ לְעוֹלָם שֶׁכֻּלּוֹ טוֹב וְתַאֲרִיךְ יָמִים לְעוֹלָם שֶׁכֻּלּוֹ אָרֹךְ וְנִמְצֵאתֶם זוֹכִין לִשְׁנֵי הָעוֹלָמוֹת, לְחַיִּים טוֹבִים בָּעוֹלָם הַזֶּה הַמְּבִיאִים לְחַיֵּי הָעוֹלָם הַבָּא. שֶׁאִם לֹא יִקְנֶה פֹּה חָכְמָה וּמַעֲשִׂים טוֹבִים אֵין לוֹ בְּמָה יִזְכֶּה שֶׁנֶּאֱמַר (קהלת ט י) \"כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בִּשְׁאוֹל\". וְאִם עֲזַבְתֶּם אֶת ה' וּשְׁגִיתֶם בְּמַאֲכָל וּבְמִשְׁתֶּה וּזְנוּת וְדוֹמֶה לָהֶם מֵבִיא עֲלֵיכֶם כָּל הַקְּלָלוֹת הָאֵלּוּ וּמֵסִיר כָּל הַבְּרָכוֹת עַד שֶׁיִּכְלוּ יְמֵיכֶם בְּבֶהָלָה וָפַחַד וְלֹא יִהְיֶה לָכֶם לֵב פָּנוּי וְלֹא גּוּף שָׁלֵם לַעֲשׂוֹת הַמִּצְוֹת כְּדֵי שֶׁתֹּאבְדוּ מֵחַיֵּי הָעוֹלָם הַבָּא וְנִמְצָא שֶׁאִבַּדְתֶּם שְׁנֵי עוֹלָמוֹת. שֶׁבִּזְמַן שֶׁאָדָם טָרוּד בָּעוֹלָם הַזֶּה בְּחלִי וּבְמִלְחָמָה וּרְעָבוֹן אֵינוֹ מִתְעַסֵּק לֹא בַּחָכְמָה וְלֹא בַּמִצְוֹת שֶׁבָּהֶן זוֹכִין לְחַיֵּי הָעוֹלָם הַבָּא:","וּמִפְּנֵי זֶה נִתְאַוּוּ כָּל יִשְׂרָאֵל נְבִיאֵיהֶם וְחַכְמֵיהֶם לִימוֹת הַמָּשִׁיחַ כְּדֵי שֶׁיָּנוּחוּ מִמַּלְכֻיּוֹת שֶׁאֵינָן מְנִיחוֹת לָהֶן לַעֲסֹק בַּתּוֹרָה וּבַמִּצְוֹת כַּהֹגֶן. וְיִמְצְאוּ לָהֶם מַרְגּוֹעַ וְיִרְבּוּ בְּחָכְמָה כְּדֵי שֶׁיִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא. לְפִי שֶׁבְּאוֹתָן הַיָּמִים תִּרְבֶּה הַדֵּעָה וְהַחָכְמָה וְהָאֱמֶת שֶׁנֶּאֱמַר (ישעיה יא ט) \"כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה'\". וְנֶאֱמַר (ירמיה לא לג) \"וְלֹא יְלַמְּדוּ אִישׁ אֶת אָחִיו וְאִישׁ אֶת רֵעֵהוּ\". וְנֶאֱמַר (יחזקאל לו כו) \"וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן מִבְּשַׂרְכֶם\". מִפְּנֵי שֶׁאוֹתוֹ הַמֶּלֶךְ שֶׁיַּעֲמֹד מִזֶּרַע דָּוִד בַּעַל חָכְמָה יִהְיֶה יֶתֶר מִשְּׁלֹמֹה. וְנָבִיא גָּדוֹל הוּא קָרוֹב לְמשֶׁה רַבֵּנוּ. וּלְפִיכָךְ יְלַמֵּד כָּל הָעָם וְיוֹרֶה אוֹתָם דֶּרֶךְ ה'. וְיָבוֹאוּ כָּל הַגּוֹיִם לְשָׁמְעוֹ שֶׁנֶּאֱמַר (ישעיה ב ב) \"וְהָיָה בְּאַחֲרִית הַיָּמִים נָכוֹן יִהְיֶה הַר בֵּית ה' בְּרֹאשׁ הֶהָרִים\". וְסוֹף כָּל הַשָּׂכָר כֻּלּוֹ וְהַטּוֹבָה הָאַחֲרוֹנָה שֶׁאֵין לָהּ הֶפְסֵק וְגֵרָעוֹן הוּא חַיֵּי הָעוֹלָם הַבָּא. אֲבָל יְמוֹת הַמָּשִׁיחַ הוּא הָעוֹלָם הַזֶּה וְעוֹלָם כְּמִנְהָגוֹ הוֹלֵךְ אֶלָּא שֶׁהַמַּלְכוּת תַּחֲזֹר לְיִשְׂרָאֵל. וּכְבָר אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים אֵין בֵּין הָעוֹלָם הַזֶּה לִימוֹת הַמָּשִׁיחַ אֶלָּא שִׁעְבּוּד מַלְכֻיּוֹת בִּלְבַד:"],"Mishneh Torah, Ritual Slaughter 1":["מִצְוַת עֲשֵׂה שֶׁיִּשְׁחֹט מִי שֶׁיִּרְצֶה לֶאֱכל בְּשַׂר בְּהֵמָה חַיָּה וְעוֹף וְאַחַר כָּךְ יֹאכַל שֶׁנֶּאֱמַר (דברים יב כא) \"וְזָבַחְתָּ מִבְּקָרְךָ וּמִצֹּאנְךָ\". וְנֶאֱמַר בִּבְכוֹר בַּעַל מוּם (דברים יב כב) \"אַךְ כַּאֲשֶׁר יֵאָכֵל אֶת הַצְּבִי וְאֶת הָאַיָּל\". הָא לָמַדְתָּ שֶׁחַיָּה כִּבְהֵמָה לְעִנְיַן שְׁחִיטָה. וּבְעוֹף הוּא אוֹמֵר (ויקרא יז יג) \"אֲשֶׁר יָצוּד צֵיד חַיָּה אוֹ עוֹף\" וְגוֹ' (ויקרא יז יג) \"וְשָׁפַךְ אֶת דָּמוֹ\" מְלַמֵּד שֶׁשְּׁפִיכַת דַּם הָעוֹף כִּשְׁפִיכַת דַּם הַחַיָּה:","וְהִלְכוֹת שְׁחִיטָה בְּכֻלָּן אַחַת הֵן. לְפִיכָךְ הַשּׁוֹחֵט בְּהֵמָה אוֹ חַיָּה אוֹ עוֹף מְבָרֵךְ תְּחִלָּה אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל הַשְּׁחִיטָה. וְאִם לֹא בֵּרֵךְ בֵּין בְּשׁוֹגֵג בֵּין בְּמֵזִיד הַבָּשָׂר מֻתָּר. וְאָסוּר לֶאֱכל מִן הַשְּׁחוּטָה כָּל זְמַן שֶׁהִיא מְפַרְכֶּסֶת. וְהָאוֹכֵל מִמֶּנָּה קֹדֶם שֶׁתֵּצֵא נַפְשָׁהּ עוֹבֵר בְּלֹא תַּעֲשֶׂה. וַהֲרֵי הוּא בִּכְלַל (ויקרא יט כו) \"לֹא תֹאכְלוּ עַל הַדָּם\" וְאֵינוֹ לוֹקֶה. וּמֻתָּר לַחְתֹּךְ מִמֶּנָּה אַחַר שְׁחִיטָה קֹדֶם שֶׁתֵּצֵא נַפְשָׁהּ וּמוֹלְחוֹ יָפֶה יָפֶה וּמְדִיחוֹ יָפֶה יָפֶה וּמַנִּיחוֹ עַד שֶׁתָּמוּת וְאַחַר כָּךְ יֹאכְלֶנּוּ:","דָּגִים וַחֲגָבִים אֵינָן צְרִיכִים שְׁחִיטָה אֶלָּא אֲסִיפָתָן הִיא הַמַּתֶּרֶת אוֹתָן. הֲרֵי הוּא אוֹמֵר (במדבר יא כב) \"הֲצֹאן וּבָקָר יִשָּׁחֵט לָהֶם וּמָצָא לָהֶם אִם אֶת כָּל דְּגֵי הַיָּם יֵאָסֵף לָהֶם\", אֲסֵפַת דָּגִים כִּשְׁחִיטַת בָּקָר וְצֹאן. וּבַחֲגָבִים נֶאֱמַר (ישעיה לג ד) \"אֹסֶף הֶחָסִיל\", בַּאֲסִיפָה לְבַדָּהּ. לְפִיכָךְ אִם מֵתוּ מֵאֲלֵיהֶן בְּתוֹךְ הַמַּיִם מֻתָּרִין. וּמֻתָּר לְאָכְלָן חַיִּים:","זְבִיחָה זוֹ הָאֲמוּרָה בַּתּוֹרָה סְתָם צָרִיךְ לְפָרֵשׁ אוֹתָהּ וְלֵידַע בְּאֵי זֶה מָקוֹם מִן הַבְּהֵמָה שׁוֹחֲטִין. וְכַמָּה שִׁעוּר הַשְּׁחִיטָה. וּבְאֵי זֶה דָּבָר שׁוֹחֲטִין. וּמָתַי שׁוֹחֲטִין. וְהֵיכָן שׁוֹחֲטִין. וְכֵיצַד שׁוֹחֲטִין. וּמַה הֵן הַדְּבָרִים הַמַּפְסִידִין אֶת הַשְּׁחִיטָה. וּמִי הוּא הַשּׁוֹחֵט. וְעַל כָּל הַדְּבָרִים הָאֵלּוּ צִוָּנוּ בַּתּוֹרָה וְאָמַר (דברים יב כא) \"וְזָבַחְתָּ מִבְּקָרְךָ\" וְגוֹ' (דברים יב כא) \"כַּאֲשֶׁר צִוִּיתִךָ וְאָכַלְתָּ בִּשְׁעָרֶיךָ\" וְגוֹ' שֶׁכָּל הַדְּבָרִים הָאֵלּוּ עַל פֶּה צִוָּה בָּהֶן כִּשְׁאָר תּוֹרָה שֶׁבְּעַל פֶּה שֶׁהִיא הַנִּקְרֵאת (שמות כד יב) \"מִצְוָה\" כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְחִלַּת חִבּוּר זֶה:","מְקוֹם הַשְּׁחִיטָה מִן הַחַי הוּא הַצַּוָּאר. וְכָל הַצַּוָּאר כָּשֵׁר לִשְׁחִיטָה. כֵּיצַד. בַּוֵּשֶׁט מִתְּחִלַּת הַמָּקוֹם שֶׁכְּשֶׁחוֹתְכִין אוֹתוֹ מִתְכַּוֵּץ עַד מָקוֹם שֶׁיַּשְׂעִיר וְיַתְחִיל לִהְיוֹת פְּרָצִין פְּרָצִין כְּכֶרֶס. זֶה הוּא מְקוֹם הַשְּׁחִיטָה בַּוֵּשֶׁט:","שָׁחַט לְמַעְלָה מִמָּקוֹם זֶה וְהוּא הַנִּקְרָא תַּרְבַּץ הַוֵּשֶׁט אוֹ לְמַטָּה מִמָּקוֹם זֶה וְהוּא מִתְּחִלַּת בְּנֵי מֵעַיִם שְׁחִיטָתוֹ פְּסוּלָה. וְשִׁעוּר תַּרְבַּץ הַוֵּשֶׁט שֶׁאֵינוֹ רָאוּי לִשְׁחִיטָה לְמַעְלָה בִּבְהֵמָה וְחַיָּה כְּדֵי שֶׁיֹּאחַז בִּשְׁתֵּי אֶצְבְּעוֹתָיו וּבְעוֹף הַכּל לְפִי גָּדְלוֹ וְקָטְנוֹ. וּלְמַטָּה עַד הַזֶּפֶק:","וְאֵי זֶה הוּא מְקוֹם שְׁחִיטָה בַּקָּנֶה. מִשִּׁפּוּי כּוֹבַע וּלְמַטָּה עַד רֹאשׁ כְּנַף הָרֵאָה כְּשֶׁתִּמְשֹׁךְ הַבְּהֵמָה צַוָּארָהּ לִרְעוֹת. זֶה הוּא מְקוֹם הַשְּׁחִיטָה בַּקָּנֶה. וְכָל שֶׁכְּנֶגֶד הַמָּקוֹם הַזֶּה מִבַּחוּץ נִקְרָא צַוָּאר:","אָנְסָה הַבְּהֵמָה עַצְמָהּ וּמָשְׁכָה צַוָּארָהּ הַרְבֵּה אוֹ שֶׁאִנֵּס הַשּׁוֹחֵט אֶת הַסִּימָנִין וּמְשָׁכָן לְמַעְלָה וְשָׁחַט בִּמְקוֹם שְׁחִיטָה בַּצַּוָּאר וְנִמְצֵאת הַשְּׁחִיטָה בַּקָּנֶה אוֹ בַּוֵּשֶׁט שֶׁלֹּא בִּמְקוֹם שְׁחִיטָה הֲרֵי זֶה סְפֵק נְבֵלָה:","וְצָרִיךְ הַשּׁוֹחֵט שֶׁיִּשְׁחֹט בְּאֶמְצַע הַצַּוָּאר. וְאִם שָׁחַט מִן הַצְּדָדִין שְׁחִיטָתוֹ כְּשֵׁרָה. וְכַמָּה הוּא שִׁעוּר הַשְּׁחִיטָה. שְׁנֵי הַסִּימָנִין שֶׁהֵן הַקָּנֶה וְהַוֵּשֶׁט הַשְּׁחִיטָה הַמְעֻלָּה שֶׁיֵּחָתְכוּ שְׁנֵיהֶן בֵּין בִּבְהֵמָה בֵּין בְּעוֹף. וְלָזֶה יִתְכַּוֵּן הַשּׁוֹחֵט. וְאִם שָׁחַט רֹב אֶחָד מֵהֶן בְּעוֹף וְרֹב הַשְּׁנַיִם בִּבְהֵמָה וּבְחַיָּה שְׁחִיטָתוֹ כְּשֵׁרָה:","שָׁחַט הָאֶחָד כֻּלּוֹ וְחֶצְיָהּ הַשֵּׁנִי בִּבְהֵמָה שְׁחִיטָתוֹ פְּסוּלָה. רֻבּוֹ שֶׁל זֶה וְרֻבּוֹ שֶׁל זֶה אַף עַל פִּי שֶׁלֹּא שָׁחַט מִכָּל אֶחָד מֵהֶן אֶלָּא יֶתֶר עַל חֶצְיוֹ כְּחוּט הַשַּׂעֲרָה הֲרֵי זוֹ כְּשֵׁרָה. כֵּיוָן שֶׁשָּׁחַט יֶתֶר עַל חֶצְיוֹ כָּל שֶׁהוּא רֻבּוֹ הוּא:","שָׁחַט חֶצְיוֹ שֶׁל זֶה וְחֶצְיוֹ שֶׁל זֶה אֲפִלּוּ בְּעוֹף שְׁחִיטָתוֹ פְּסוּלָה. קָנֶה שֶׁהָיָה חֶצְיוֹ פָּסוּק וְשָׁחַט עַל מָקוֹם הֶחָתוּךְ מְעַט וְהִשְׁלִימוֹ לְרֹב בֵּין שֶׁהִתְחִיל לִשְׁחֹט בַּמָּקוֹם הַשָּׁלֵם וּפָגַע בַּחֲתָךְ בֵּין שֶׁהִכְנִיס אֶת הַסַּכִּין בַּחֲתָךְ וְהִשְׁלִימוֹ לְרֹב שְׁחִיטָתוֹ כְּשֵׁרָה:","כָּל הַשּׁוֹחֵט צָרִיךְ לִבְדֹּק הַסִּימָנִין לְאַחַר שְׁחִיטָה. וְאִם לֹא בָּדַק וְנֶחְתַּךְ הָרֹאשׁ קֹדֶם שֶׁיִּבָּדֵק הֲרֵי זוֹ נְבֵלָה. וַאֲפִלּוּ הָיָה הַשּׁוֹחֵט זָרִיז וּמָהִיר:","כָּל בְּהֵמָה בְּחַיֶּיהָ בְּחֶזְקַת אִסּוּר עוֹמֶדֶת עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁנִּשְׁחֲטָה שְׁחִיטָה כְּשֵׁרָה:","ובְּאֵי זֶה דָּבָר שׁוֹחֲטִין. בְּכָל דָּבָר בֵּין בְּסַכִּין שֶׁל מַתֶּכֶת בֵּין בְּצוּר אוֹ בִּזְכוּכִית אוֹ בִּקְרוּמִית שֶׁל קְנֵה הָאֲגַם וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים הַחוֹתְכִין. וְהוּא שֶׁיִּהְיֶה פִּיהָ חַד וְלֹא יִהְיֶה בָּהּ פְּגָם. אֲבָל אִם הָיָה כְּמוֹ תֶּלֶם בְּחֻדּוֹ שֶׁל דָּבָר שֶׁשּׁוֹחֲטִין בּוֹ וַאֲפִלּוּ הָיָה הַתֶּלֶם קָטָן בְּיוֹתֵר שְׁחִיטָתוֹ פְּסוּלָה:","הָיָה הַתֶּלֶם הַזֶּה מֵרוּחַ אַחַת לֹא יִשְׁחֹט בָּהּ. וְאִם שָׁחַט דֶּרֶךְ הָרוּחַ שֶׁאֵין הַפְּגִימָה נִכֶּרֶת בָּהּ שְׁחִיטָתוֹ כְּשֵׁרָה:","כֵּיצַד. סַכִּין שֶׁתִּבָּדֵק בְּהוֹלָכָה וְלֹא תַּרְגִּישׁ שֶׁיֵּשׁ בָּהּ פְּגָם וּכְשֶׁתַּחְזִיר אוֹתָהּ בַּהֲבָאָה תַּרְגִּישׁ שֶׁיֵּשׁ בָּהּ פְּגָם. אִם שָׁחַט בָּהּ דֶּרֶךְ הוֹלָכָה וְלֹא הֵבִיא שְׁחִיטָתוֹ כְּשֵׁרָה. וְאִם הֵבִיא שְׁחִיטָתוֹ פְּסוּלָה:","סַכִּין שֶׁהִיא עוֹלָה וְיוֹרֶדֶת כְּנָחָשׁ וְאֵין בָּהּ פְּגָם שׁוֹחֲטִין בָּהּ לְכַתְּחִלָּה. וסַכִּין שֶׁפִּיהָ חָלָק וְאֵינָהּ חַדָּה הוֹאִיל וְאֵין בָּהּ פְּגָם שׁוֹחֲטִין בָּהּ. וְאַף עַל פִּי שֶׁהוֹלִיךְ וְהֵבִיא בָּהּ כָּל הַיּוֹם עַד שֶׁשָּׁחְטָה שְׁחִיטָתוֹ כְּשֵׁרָה:","סַכִּין חַדָּה שֶׁהֻשְׁחֲזָה וַהֲרֵי אֵינָהּ חֲלָקָה אֶלָּא מַגָּעָתָהּ כְּמַגָּע רֹאשׁ הַשִּׁבּלֶת שֶׁהוּא מִסְתַּבֵּךְ בְּאֶצְבַּע. הוֹאִיל וְאֵין בָּהּ פְּגָם שׁוֹחֲטִין בָּהּ:","הַתּוֹלֵשׁ קָנֶה אוֹ שֵׁן אוֹ שֶׁקָּצַץ צוּר אוֹ צִפֹּרֶן וַהֲרֵי הֵן חַדִּין וְאֵין בָּהֶן פְּגָם שׁוֹחֲטִין בָּהֶן. וְאִם נְעָצָן בַּקַּרְקַע לֹא יִשְׁחֹט בָּהֶן כְּשֶׁהֵן נְעוּצִין. וְאִם שָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","שָׁחַט בָּהֶן כְּשֶׁהֵן מְחֻבָּרִין מִתְּחִלַּת בְּרִיָּתָן קֹדֶם שֶׁיַּעֲקֹר אוֹתָן שְׁחִיטָתוֹ פְּסוּלָה. וְאַף עַל פִּי שֶׁאֵין בָּהֶם פְּגָם:","לָקַח לְחִי בְּהֵמָה שֶׁיֵּשׁ בּוֹ שִׁנַּיִם חַדּוֹת וְשָׁחַט בָּהֶן שְׁחִיטָתוֹ פְּסוּלָה. מִפְּנֵי שֶׁהֵן כְּמַגָּל. אֲבָל בְּשֵׁן אַחַת הַקְּבוּעָה בַּלֶּחִי שׁוֹחֵט בָּהּ לְכַתְּחִלָּה וְאַף עַל פִּי שֶׁהִיא קְבוּעָה בּוֹ:","לִבֵּן הַסַּכִּין בָּאוּר וְשָׁחַט בָּהּ שְׁחִיטָתוֹ כְּשֵׁרָה. סַכִּין שֶׁצִּדָּהּ אֶחָד מַגָּל וְצִדָּהּ הַשֵּׁנִי יָפֶה לֹא יִשְׁחֹט בַּצַּד הַיָּפֶה לְכַתְּחִלָּה גְּזֵרָה שֶׁמָּא יִשְׁחֹט בַּצַּד הָאַחֵר. וְאִם שָׁחַט הוֹאִיל וּבַצַּד הַיָּפֶה שָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","הַשּׁוֹחֵט צָרִיךְ שֶׁיִּבְדֹּק הַסַּכִּין בְּחֻדָּהּ וּמִצַּד זֶה וּמִצַּד זֶה. וְכֵיצַד בּוֹדְקָהּ. מוֹלִיכָהּ וּמְבִיאָהּ עַל בְּשַׂר אֶצְבָּעוֹ וּמוֹלִיכָהּ וּמְבִיאָהּ עַל צִפָּרְנוֹ מִשָּׁלֹשׁ רוּחוֹתֶיהָ שֶׁהֵן פִּיהָ וּשְׁנֵי צְדָדָיו כְּדֵי שֶׁלֹּא יִהְיֶה בָּהּ פְּגָם כְּלָל וְאַחַר כָּךְ יִשְׁחֹט בָּהּ:","וְצָרִיךְ לִבְדֹּק כֵּן אַחַר הַשְּׁחִיטָה שֶׁאִם מָצָא בָּהּ פְּגָם אַחַר הַשְּׁחִיטָה הֲרֵי זוֹ סְפֵק נְבֵלָה שֶׁמָּא בָּעוֹר נִפְגְּמָה וּכְשֶׁשָּׁחַט הַסִּימָנִים בְּסַכִּין פְּגוּמָה שָׁחַט. לְפִיכָךְ הַשּׁוֹחֵט בְּהֵמוֹת רַבּוֹת אוֹ עוֹפוֹת רַבִּים צָרִיךְ לִבְדֹּק בֵּין כָּל אַחַת וְאַחַת. שֶׁאִם לֹא בָּדַק וּבָדַק בָּאַחֲרוֹנָה וְנִמְצֵאת סַכִּין פְּגוּמָה הֲרֵי הַכּל סְפֵק נְבֵלוֹת וַאֲפִלּוּ הָרִאשׁוֹנָה:","בָּדַק הַסַּכִּין וְשָׁחַט בָּהּ וְלֹא בְּדָקָהּ אַחַר שְׁחִיטָה וְשָׁבַר בָּהּ עֶצֶם אוֹ עֵץ וְכַיּוֹצֵא בָּהֶן וְאַחַר כָּךְ בָּדַק וּמְצָאָהּ פְּגוּמָה שְׁחִיטָתוֹ כְּשֵׁרָה. שֶׁחֶזְקַת הַסַּכִּין שֶׁנִּפְגְּמָה בַּדָּבָר הַקָּשֶׁה שֶׁשָּׁבַר בָּהּ. וְכֵן אִם פָּשַׁע וְלֹא בָּדַק הַסַּכִּין אוֹ שֶׁאָבְדָה הַסַּכִּין עַד שֶׁלֹּא יִבְדֹּק שְׁחִיטָתוֹ כְּשֵׁרָה:","כָּל טַבָּח שֶׁלֹּא בָּדַק הַסַּכִּין שֶׁלּוֹ שֶׁשּׁוֹחֵט בָּהּ לִפְנֵי חָכָם וְשָׁחַט בָּהּ לְעַצְמוֹ בּוֹדְקִין אוֹתָהּ. אִם נִמְצֵאת יָפָה וּבְדוּקָה מְנַדִּין אוֹתוֹ לְפִי שֶׁיִּסְמֹךְ עַל עַצְמוֹ פַּעַם אַחֶרֶת וְתִהְיֶה פְּגוּמָה וְיִשְׁחֹט בָּהּ. ואִם נִמְצֵאת פְּגוּמָה מַעֲבִירִין אוֹתוֹ וּמְנַדִּין אוֹתוֹ וּמַכְרִיזִין עַל כָּל בָּשָׂר שֶׁשָּׁחַט שֶׁהוּא טְרֵפָה:","כַּמָּה הוּא אֹרֶךְ הַסַּכִּין שֶׁשּׁוֹחֵט. כָּל שֶׁהוּא. וְהוּא שֶׁלֹּא יִהְיֶה דָּבָר דַּק שֶׁנּוֹקֵב וְאֵינוֹ שׁוֹחֵט כְּמוֹ רֹאשׁ הָאִזְמֵל הַקָּטָן וְכַיּוֹצֵא בּוֹ:","וּמָתַי שׁוֹחֲטִין. בְּכָל זְמַן. בֵּין בַּיּוֹם בֵּין בַּלַּיְלָה. וְהוּא שֶׁתִּהְיֶה אֲבוּקָה עִמּוֹ כְּדֵי שֶׁיִּרְאֶה מַה יַּעֲשֶׂה. וְאִם שָׁחַט בַּאֲפֵלָה שְׁחִיטָתוֹ כְּשֵׁרָה:","הַשּׁוֹחֵט בְּיוֹם הַכִּפּוּרִים אוֹ בְּשַׁבָּת בְּשׁוֹגֵג אַף עַל פִּי שֶׁאִלּוּ הָיָה מֵזִיד הָיָה מִתְחַיֵּב בְּנַפְשׁוֹ אוֹ מִתְחַיֵּב מַלְקוֹת עַל יוֹם הַכִּפּוּרִים שְׁחִיטָתוֹ כְּשֵׁרָה:"],"Mishneh Torah, Ritual Slaughter 8":["חֲסֵרָה כֵּיצַד. שְׁנֵי אֵיבָרִים הֵן שֶׁאִם חָסֵר מִמִּנְיָנָם טְרֵפָה. וְאֵלּוּ הֵן. הָרֵאָה וְהָרַגְלַיִם. וְחָמֵשׁ אֻנּוֹת יֵשׁ לָרֵאָה כְּשֶׁיִּתְלֶה אוֹתָהּ אָדָם בְּיָדוֹ וּפְנֵי רֵאָה כְּנֶגֶד פָּנָיו. שָׁלֹשׁ מִן הַיָּמִין. וּשְׁתַּיִם מִן הַשְּׂמֹאל. וּבְצַד יָמִין מִמֶּנָּה כְּמוֹ אֹזֶן קְטַנָּה וְאֵינָהּ בְּצַד הָאֻנּוֹת וְיֵשׁ לָהּ כְּמוֹ כִּיס בִּפְנֵי עַצְמָהּ וְהִיא בְּתוֹךְ הַכִּיס. וְאֹזֶן זוֹ קְטַנָּה הִיא הַנִּקְרָא וַרְדָּא מִפְּנֵי שֶׁהִיא דּוֹמָה לְוֶרֶד וְאֵינָהּ מִן הַמִּנְיָן. לְפִיכָךְ אִם לֹא נִמְצֵאת הַוַּרְדָּא מֻתֶּרֶת. שֶׁכָּךְ הִיא דַּרְכָּהּ יֵשׁ בְּהֵמוֹת תִּמָּצֵא בָּהֶם וְיֵשׁ בְּהֵמוֹת לֹא תִּמָּצֵא בָּהֶם. וְאִם נִמְצֵאת נְקוּבָה אַף עַל פִּי שֶׁהַכִּיס שֶׁלָּהּ סוֹתֵם אֶת הַנֶּקֶב הֲרֵי זוֹ טְרֵפָה:","חָסֵר מִנְיַן הָאֻנּוֹת וְנִמְצֵאת אַחַת מִן הַשְּׂמֹאל אוֹ שְׁתַּיִם מִן הַיָּמִין טְרֵפָה. וְאִם נִמְצְאוּ שְׁתַּיִם בְּיָמִין וְזֹאת הַוַּרְדָּא הֲרֵי זוֹ מֻתֶּרֶת:","נִתְחַלְּפוּ הָאֻנּוֹת וְנִמְצְאוּ שָׁלֹשׁ מִן שְׂמֹאל וּשְׁתַּיִם מִן הַיָּמִין בְּלֹא וֶרֶד. אוֹ שֶׁהָיָה הַוֶּרֶד עִם הַשָּׁלֹשׁ בְּצַד שְׂמֹאל. הֲרֵי זוֹ טְרֵפָה שֶׁהִיא חֲסֵרָה מִצַּד הַיָּמִין:","נִתְוַסְּפוּ הָאֻנּוֹת בְּמִנְיָנָם אִם הָיְתָה הָאֹזֶן הַיְתֵרָה בְּצַד הָאֻנּוֹת אוֹ מִלִּפְנֵי הָרֵאָה שֶׁהוּא לְעֻמַּת הַלֵּב מֻתֶּרֶת. וְאִם הָיְתָה עַל גַּבָּהּ שֶׁהוּא לְעֻמַּת הַצְּלָעוֹת הֲרֵי זוֹ טְרֵפָה שֶׁהַיָּתֵר כְּחָסֵר. וְהוּא שֶׁתִּהְיֶה כְּמוֹ עָלֶה שֶׁל הֲדַס. אֲבָל פָּחוֹת מִזֶּה אֵינָהּ אֹזֶן וּמֻתֶּרֶת:","אֹזֶן שֶׁנִּמְצֵאת דְּבוּקָה בַּחֲבֶרְתָּהּ הַסְּמוּכָה לָהּ מֻתֶּרֶת. וְאִם נִסְמְכוּ שֶׁלֹּא עַל הַסֵּדֶר כְּגוֹן שֶׁנִּסְמְכָה רִאשׁוֹנָה לַשְּׁלִישִׁית טְרֵפָה:","נִמְצְאוּ שְׁתֵּי הָאֻנּוֹת כְּאֻנָּה אַחַת וְאֵינָן נִרְאוֹת כִּשְׁתַּיִם דְּבוּקוֹת אִם הָיָה בֵּינֵיהֶן כְּמוֹ עֲלֵה הַהֲדַס בֵּין בְּעִקָּרָן בֵּין בְּאֶמְצָעָן בֵּין בְּסוֹפָן כְּדֵי שֶׁיֻּכַּר שֶׁהֵן שְׁתַּיִם דְּבוּקוֹת מֻתֶּרֶת וְאִם לָאו הֲרֵי זוֹ חֲסֵרָה וּטְרֵפָה:","נִמְצֵאת כֻּלָּהּ שְׁתֵּי עֲרוּגוֹת וְאֵין לָהּ חִתּוּךְ אָזְנַיִם טְרֵפָה. וְכֵן אִם חָסֵר גּוּף הָרֵאָה אַף עַל פִּי שֶׁלֹּא נִקְּבָה הֲרֵי זוֹ כְּמִי שֶׁחָסֵר מִנְיַן הָאֻנּוֹת וּטְרֵפָה. לְפִיכָךְ אִם נִמְצָא מִמֶּנָּה מָקוֹם יָבֵשׁ עַד שֶׁיִּפָּרֵךְ בְּצִפֹּרֶן הֲרֵי זוֹ כְּחָסֵר וּטְרֵפָה וַאֲפִלּוּ הָיָה כָּל שֶׁהוּא:","רֵאָה שֶׁנִּמְצֵאת נְפוּחָה כְּמוֹ עִקַּר חֲרָיוֹת שֶׁל דֶּקֶל אוֹסְרִין אוֹתָהּ מִסָּפֵק. שֶׁזּוֹ תּוֹסֶפֶת מְשֻׁנָּה בְּגוּפָהּ וְשֶׁמָּא הַתּוֹסֶפֶת בַּגּוּף כְּחִסָּרוֹן כְּמוֹ שֶׁאָמַר בְּמִנְיָן:","הַבְּהֵמָה שֶׁפָּחֲדָה וְיָרְאָה עַד שֶׁצָּמְקָה הָרֵאָה שֶׁלָּהּ וְקָרְבָה לִהְיוֹת יְבֵשָׁה. אִם פָּחֲדָה בִּידֵי שָׁמַיִם כְּגוֹן שֶׁשָּׁמְעָה קוֹל רַעַם אוֹ רָאֲתָה זִקִּים וְכַיּוֹצֵא בָּזֶה מֻתֶּרֶת. וְאִם פָּחֲדָה בִּידֵי אָדָם כְּגוֹן שֶׁשָּׁחֲטוּ לְפָנֶיהָ בְּהֵמָה אַחֶרֶת וְכַיּוֹצֵא בָּזֶה הֲרֵי זוֹ כַּחֲסֵרָה וּטְרֵפָה:","כֵּיצַד בּוֹדְקִין אוֹתָהּ. מוֹשִׁיבִין אֶת הָרֵאָה בְּמַיִם מֵעֵת לְעֵת. וְאִם הָיָה זְמַן הַקֹּר מוֹשִׁיבִין אוֹתָהּ בְּמַיִם פּוֹשְׁרִין וּבִכְלִי שֶׁאֵין הַמַּיִם מִתְמַצִּין מִגַּבּוֹ וְנֹזְלִים כְּדֵי שֶׁלֹּא יִצֹּנּוּ בִּמְהֵרָה. וְאִם הָיָה זְמַן הַחֹם מוֹשִׁיבִין אוֹתָהּ בְּמַיִם צוֹנֵן בִּכְלִי שֶׁהַמַּיִם מִתְמַצִּין מִגַּבּוֹ כְּדֵי שֶׁיִּשָּׁאֲרוּ קָרִים. אִם חָזְרָה לִבְרִיָּתָהּ הֲרֵי זוֹ בִּידֵי שָׁמַיִם וּמֻתֶּרֶת. וְאִם לֹא חָזְרָה בִּידֵי אָדָם הִיא וּטְרֵפָה:","בְּהֵמָה שֶׁהָיְתָה חֲסֵרָה רֶגֶל בִּתְחִלַּת בְּרִיָּתָהּ טְרֵפָה. וְכֵן אִם הָיְתָה יְתֵרָה רֶגֶל. שֶׁכָּל הַיָּתֵר כְּחָסֵר הוּא. אֲבָל אִם הָיוּ לָהּ שָׁלֹשׁ יָדַיִם אוֹ יָד אַחַת מֻתֶּרֶת. לְפִיכָךְ אִם נֶחְתַּךְ הַיָּד שֶׁלָּהּ מֻתֶּרֶת. נֶחְתַּךְ הָרֶגֶל מִן הָאַרְכֻּבָּה וּלְמַעְלָה טְרֵפָה. מִן הָאַרְכֻּבָּה וּלְמַטָּה מֻתֶּרֶת. בְּאֵי זוֹ אַרְכֻּבָּה אָמְרוּ בְּאַרְכֻּבָּה שֶׁהוּא סוֹף הַיָּרֵךְ הַסָּמוּךְ לַגּוּף:","נִשְׁבַּר הָעֶצֶם לְמַעְלָה מִן הָאַרְכֻּבָּה אִם יָצָא כֻּלּוֹ אוֹ רֻבּוֹ לַחוּץ הֲרֵי זֶה כְּמָה שֶׁנֶּחְתַּךְ וְנָפַל וּטְרֵפָה. וְאִם הָיָה הַבָּשָׂר אוֹ הָעוֹר חוֹפֶה רֹב עָבְיוֹ וְרֹב הֶקֵּפוֹ שֶׁל עֶצֶם שֶׁנִּשְׁבַּר הֲרֵי זוֹ מֻתֶּרֶת וַאֲפִלּוּ נָפַל מִקְצָת הָעֶצֶם שֶׁנִּשְׁבַּר וְהָלַךְ לוֹ. וְגִידִים הָרַכִּים אֵינָן חֲשׁוּבִין כְּבָשָׂר:","צֹמֶת הַגִּידִין הֵן בִּבְהֵמָה וּבְחַיָּה לְמַעְלָה מִן הֶעָקֵב בְּמָקוֹם שֶׁתּוֹלִין בּוֹ הַטַּבָּחִים הַבְּהֵמָה. וְהֵן שְׁלֹשָׁה גִּידִין לְבָנִים. אֶחָד עָבֶה וּשְׁנַיִם דַּקִּים. וּמִמָּקוֹם שֶׁיַּתְחִיל וְהֵן קָשִׁים וּלְבָנִים עַד שֶׁיָּסוּר הַלֹּבֶן מֵהֶן וְיַתְחִילוּ לְהִתְאַדֵּם וּלְהִתְרַכֵּךְ הוּא צֹמֶת הַגִּידִים. וְהוּא כְּאֹרֶךְ שֵׁשׁ עֶשְׂרֵה אֶצְבָּעוֹת בְּשׁוֹר:","וּמִנְיַן גִּידִים אֵלּוּ בָּעוֹף שִׁשָּׁה עָשָׂר גִּידִין. תְּחִלָּתָן מִן הָעֶצֶם שֶׁל מַטָּה מֵאֶצְבַּע יְתֵרָה עַד סוֹף הָרֶגֶל שֶׁהוּא עָשׂוּי קַשְׂקַשִּׂים קַשְׂקַשִּׂים:","בְּהֵמָה שֶׁנֶּחְתְּכוּ רַגְלֶיהָ בִּמְקוֹם צֹמֶת הַגִּידִין טְרֵפָה. וְאַל תִּתְמַהּ וְתֹאמַר כֵּיצַד תַּחְתֹּךְ לְמַעְלָה מִצֹּמֶת הַגִּידִים וְהִיא מֻתֶּרֶת עַד שֶׁתַּחְתֹּךְ לְמַעְלָה מִן הָאַרְכֻּבָּה הָעֶלְיוֹנָה כְּמוֹ שֶׁבֵּאַרְנוּ וְאִם נֶחְתַּךְ לְמַטָּה מִצֹּמֶת הַגִּידִים אֲסוּרָה. שֶׁבִּטְרֵפוֹת תַּחְתֹּךְ מִכָּאן וְתִחְיֶה וּמִכָּאן וְתָמוּת. וְלֹא נֶאֶסְרָה בְּהֵמָה זוֹ מִפְּנֵי שֶׁהִיא חֲתוּכַת רֶגֶל מִמָּקוֹם זֶה אֶלָּא מִפְּנֵי שֶׁנֶּחְתְּכוּ הַגִּידִין שֶׁחֲתִיכָתָן מִכְּלַל הַטְּרֵפוֹת כְּמוֹ שֶׁיִּתְבָּאֵר:","נְטוּלָה כֵּיצַד. שְׁלֹשָׁה אֵיבָרִים הֵן שֶׁאִם נִטְּלוּ טְרֵפָה וְאַף עַל פִּי שֶׁאֵין בָּהֶן דִּין נֶקֶב וְלֹא דִּין חֶסְרוֹן. וְאֵלּוּ הֵן. צֹמֶת הַגִּידִים. וְהַכָּבֵד. וּלְחִי הָעֶלְיוֹן:","וּכְבָר בֵּאַרְנוּ שֶׁהַבְּהֵמָה שֶׁנֶּחְתַּךְ רַגְלָהּ וְכֵן הָעוֹף בִּמְקוֹם צֹמֶת הַגִּידִים לֹא נַעֲשׂוּ טְרֵפָה אֶלָּא מִפְּנֵי שֶׁנֶּחְתְּכוּ הַגִּידִין. לְפִיכָךְ אִם נֶחְתְּכוּ הַגִּידִים לְבַדָּם וְהָרֶגֶל קַיֶּמֶת טְרֵפָה שֶׁהֲרֵי נִטְּלָה צֹמֶת הַגִּידִים:","נֶחְתַּךְ בִּבְהֵמָה הָאֶחָד הֶעָבֶה לְבַדּוֹ מֻתֶּרֶת. שֶׁהֲרֵי נִשְׁאֲרוּ שְׁנַיִם. נֶחְתְּכוּ הַשְּׁנַיִם הַדַּקִּין מֻתֶּרֶת שֶׁהֲרֵי הָאֶחָד הֶעָבֶה גְּדוֹל שְׁנֵיהֶן וַהֲרֵי לֹא נִטַּל כָּל הַצֹּמֶת אֶלָּא מִעוּטָהּ. נֶחְתַּךְ רֻבּוֹ שֶׁל כָּל אֶחָד מֵהֶן טְרֵפָה. וְאֵין צָרִיךְ לוֹמַר שֶׁנֶּחְתְּכוּ כֻּלָּן אוֹ נִטְּלוּ כֻּלָּן:","וּבָעוֹף אֲפִלּוּ נֶחְתַּךְ רֻבּוֹ שֶׁל (כָּל) אֶחָד מִן הַשִּׁשָּׁה עָשָׂר טְרֵפָה:","וְעוֹף שֶׁנִּשְׁתַּבְּרוּ אֲגַפָּיו מֻתָּר כִּבְהֵמָה שֶׁנֶּחְתְּכוּ יָדֶיהָ:","כָּבֵד שֶׁנִּטְּלָה כֻּלָּהּ טְרֵפָה. וְאִם נִשְׁתַּיֵּר מִמֶּנָּה כְּזַיִת בְּמָקוֹם שֶׁהִיא תְּלוּיָה בּוֹ וּכְזַיִת בִּמְקוֹם מָרָה הֲרֵי זוֹ מֻתֶּרֶת. נִדַּלְדְּלָה הַכָּבֵד וַהֲרֵי הִיא מְעֹרָה בַּטַּרְפַּשׁ שֶׁלָּהּ מֻתֶּרֶת. נִטַּל מִמֶּנָּה מָקוֹם שֶׁהִיא תְּלוּיָה בּוֹ וּמְקוֹם הַמָּרָה וְאַף עַל פִּי שֶׁהַשְּׁאָר קַיָּם כְּמוֹ שֶׁהוּא טְרֵפָה:","נִשְׁאַר בָּהּ כְּזַיִת בִּמְקוֹם מָרָה וּכְזַיִת בְּמָקוֹם שֶׁהִיא תְּלוּיָה בּוֹ כְּשֵׁרָה. אֲבָל הָיָה מְפֻזָּר מְעַט בְּכָאן וּמְעַט בְּכָאן אוֹ שֶׁהָיָה מְרֻדָּד אוֹ שֶׁהָיָה אָרֹךְ כִּרְצוּעָה הֲרֵי זוֹ סָפֵק וְיֵרָאֶה לִי שֶׁהִיא אֲסוּרָה:","לְחִי הָעֶלְיוֹן שֶׁנִּטַּל טְרֵפָה. אֲבָל אִם נִטַּל הַתַּחְתּוֹן כְּגוֹן שֶׁנִּגְמַם עַד מְקוֹם הַסִּימָנִין וְלֹא נֶעֶקְרוּ הֲרֵי זוֹ מֻתֶּרֶת:","כָּל אֵיבָר שֶׁנֶּאֱמַר בּוֹ שֶׁאִם הָיָה חָסֵר טְרֵפָה כָּךְ אִם נִטַּל טְרֵפָה. אֲבָל אֵיבָר שֶׁנֶּאֱמַר בּוֹ אִם נִטַּל טְרֵפָה אֵינָהּ נֶאֱסֶרֶת אֶלָּא אִם נֶחְתַּךְ אוֹתוֹ אֵיבָר. אֲבָל אִם נִבְרֵאת חֲסֵרָה אוֹתוֹ אֵיבָר הֲרֵי זוֹ מֻתֶּרֶת. שֶׁאִם לֹא תֹּאמַר כֵּן נִמְצֵאת הַחֲסֵרָה וְהַנְּטוּלָה אַחַת. וְכָל אֵיבָר שֶׁנֶּאֱמַר בּוֹ שֶׁאִם נִטַּל מֻתֶּרֶת קַל וָחֹמֶר אִם חָסֵר מִתְּחִלַּת בְּרִיָּתָהּ וְלֹא נִבְרָא שֶׁהִיא מֻתֶּרֶת:","בְּהֵמָה שֶׁנִּטְּלָה הָאֵם שֶׁלָּהּ וְהוּא בֵּית הָרֶחֶם אוֹ שֶׁנִּטְּלוּ הַכְּלָיוֹת הֲרֵי זוֹ מֻתֶּרֶת. לְפִיכָךְ אִם נִבְרֵאת בְּכוּלְיָא אַחַת אוֹ בְּשָׁלֹשׁ כְּלָיוֹת מֻתֶּרֶת. וְכֵן אִם נִקְּבָה הַכּוּלְיָא מֻתֶּרֶת:","אַף עַל פִּי שֶׁהַכּוּלְיָא שֶׁנִּטְּלָה אוֹ חֲסֵרָה מֻתֶּרֶת אִם נִמְצֵאת קְטַנָּה בְּיוֹתֵר. וְהַקְּטַנָּה בְּדָקָה עַד כְּפוֹל וּבְגַסָּה עַד כְּעֵנָב. טְרֵפָה. וְכֵן אִם לָקְתָה הַכּוּלְיָא וְהוּא שֶׁיֵּעָשֶׂה בְּשָׂרָהּ כִּבְשַׂר הַמֵּת שֶׁהִבְאִישׁ אַחַר יָמִים שֶׁאִם תֶּאֱחֹז בְּמִקְצָתוֹ יִתְמַסְמֵס וְיִפּל וְהִגִּיעַ חלִי זֶה עַד הַלָּבָן שֶׁבְּתוֹךְ הַכּוּלְיָא הֲרֵי זוֹ טְרֵפָה. וְכֵן אִם נִמְצֵאת בַּכּוּלְיָא לֵחָה אַף עַל פִּי שֶׁאֵינָהּ סְרוּחָה אוֹ שֶׁנִּמְצָא בָּהּ מַיִם עֲכוּרִין אוֹ סְרוּחִים הֲרֵי זוֹ טְרֵפָה. אֲבָל אִם נִמְצְאוּ בָּהּ מַיִם זַכִּים הֲרֵי זוֹ מֻתֶּרֶת:"],"Mishneh Torah, Robbery and Lost Property 2":["הַגְּזֵלָה שֶׁלֹּא נִשְׁתַּנֵּית אֶלָּא הֲרֵי הִיא כְּמוֹ שֶׁהָיְתָה אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה וְאַף עַל פִּי שֶׁמֵּת הַגַּזְלָן וַהֲרֵי הִיא בְּיַד בָּנָיו הֲרֵי זוֹ חוֹזֶרֶת לִבְעָלֶיהָ בְּעַצְמָהּ. וְאִם נִשְׁתַּנֵּית בְּיַד הַגַּזְלָן אַף עַל פִּי שֶׁעֲדַיִן לֹא נִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה קְנָאָהּ בְּשִׁנּוּי וּמְשַׁלֵּם דָּמֶיהָ כִּשְׁעַת הַגְּזֵלָה:","וְדִין זֶה דִּין תּוֹרָה הוּא שֶׁנֶּאֱמַר (ויקרא ה כג) \"וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל\". מִפִּי הַשְּׁמוּעָה לָמְדוּ אִם הִיא כְּשֶׁגְּזָלָהּ מְשַׁלֵּם אוֹתָהּ וְאִם נִשְׁתַּנֵּית בְּיָדוֹ מְשַׁלֵּם דָּמֶיהָ. נִתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה וְלֹא נִשְׁתַּנֵּית קָנָה הַגַּזְלָן כָּל הַשֶּׁבַח שֶׁהִשְׁבִּיחָה אַחַר יֵאוּשׁ וְאֵינוֹ מְשַׁלֵּם אֶלָּא כִּשְׁעַת הַגְּזֵלָה. וְדָבָר זֶה מִדִּבְרֵיהֶם מִפְּנֵי תַּקָּנַת הַשָּׁבִים. וּכְשֶׁמַּחְזִיר לוֹ הַגְּזֵלָה שָׁמִין לוֹ הַשֶּׁבַח וְנוֹטֵל מִן הַנִּגְזָל:","מְכָרָהּ הַגַּזְלָן אוֹ נְתָנָהּ בְּמַתָּנָה אַף עַל פִּי שֶׁלֹּא נִשְׁתַּנֵּית הַגְּזֵלָה אֵינָהּ חוֹזֶרֶת בְּעַצְמָהּ מִיַּד הַלּוֹקֵחַ הוֹאִיל וְנִתְיָאֲשׁוּ הַבְּעָלִים בֵּין לִפְנֵי מְכִירָה וּנְתִינָה בֵּין לְאַחַר מְכִירָה וּנְתִינָה קְנָאָהּ הַלּוֹקֵחַ בְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת:","הַגּוֹזֵל וְהִשְׁבִּיחַ וּמָכַר אוֹ הוֹרִישׁ לִפְנֵי יֵאוּשׁ מַה שֶּׁהִשְׁבִּיחַ הוֹרִישׁ וּמַה שֶּׁהִשְׁבִּיחַ מָכַר וְקָנָה לוֹקֵחַ אוֹ יוֹרֵשׁ אֶת הַשֶּׁבַח. וְנוֹטֵל דְּמֵי הַשֶּׁבַח מִן הַנִּגְזָל וּמַחֲזִיר לוֹ הַגְּזֵלָה. וְחוֹזֵר הַנִּגְזָל וְנוֹטֵל דְּמֵי הַשֶּׁבַח מִן הַגַּזְלָן שֶׁהֲרֵי לֹא נִתְיָאֵשׁ. וְכֵן אִם הִשְׁבִּיחַ הַלּוֹקֵחַ אוֹ הַיּוֹרֵשׁ נוֹטֵל הַשֶּׁבַח מִן הַנִּגְזָל:","מָכַר הַגַּזְלָן לְעַכּוּ\"ם אַף עַל פִּי שֶׁהִשְׁבִּיחַ הָעַכּוּ\"ם חוֹזֶרֶת לִבְעָלֶיהָ. מְכָרָהּ הָעַכּוּ\"ם לְיִשְׂרָאֵל אַחַר שֶׁהִשְׁבִּיחַ הוֹאִיל וְהַגַּזְלָן יִשְׂרָאֵל וְזֶה שֶׁהִיא בְּיָדוֹ יִשְׂרָאֵל קָנָה הַשֶּׁבַח. וְאִם תָּפַשׂ הַנִּגְזָל אֵין מוֹצִיאִין מִיָּדוֹ:","כְּבָר בֵּאַרְנוּ שֶׁהַגְּזֵלָה שֶׁהִשְׁבִּיחָה אַחַר יֵאוּשׁ אוֹ אַחַר שֶׁנִּשְׁתַּנֵּית הַשֶּׁבַח לַגַּזְלָן מִפְּנֵי תַּקָּנַת הַשָּׁבִים אַף עַל פִּי שֶׁהִשְׁבִּיחָה מֵאֵלֶיהָ. כֵּיצַד. גָּזַל פָּרָה וְנִתְעַבְּרָה אֶצְלוֹ בֵּין שֶׁיָּלְדָה קֹדֶם שֶׁתְּבָעוֹ בְּדִין בֵּין שֶׁעֲדַיִן לֹא יָלְדָה. גָּזַל רָחֵל וְנִטְעֲנָה אֶצְלוֹ בֵּין שֶׁגְּזָזָהּ קֹדֶם שֶׁתְּבָעוֹ בַּדִּין בֵּין שֶׁעֲדַיִן לֹא גְּזָזָהּ. הוֹאִיל וְנִתְיָאֲשׁוּ הַבְּעָלִים מְשַׁלֵּם כִּשְׁעַת הַגְּזֵלָה. וְאִם יָלְדָה וּגְזָזָהּ הַגִּזּוֹת וְהַוְּלָדוֹת שֶׁל גַּזְלָן. וְאִם עֲדַיִן לֹא יָלְדָה וְלֹא גְּזָזָהּ שָׁמִין לוֹ וְנוֹטֵל הַשֶּׁבַח מִן הַנִּגְזָל וּמַחֲזִיר הַבְּהֵמָה עַצְמָהּ:","גָּזַל פָּרָה מְעֻבֶּרֶת וְנִתְיָאֲשׁוּ הַבְּעָלִים וְאַחַר כָּךְ יָלְדָה. רָחֵל טְעוּנָה וְנִתְיָאֲשׁוּ הַבְּעָלִים וְאַחַר כָּךְ גְּזָזָהּ. מְשַׁלֵּם דְּמֵי פָּרָה הָעוֹמֶדֶת לֵילֵד וּדְמֵי רָחֵל הָעוֹמֶדֶת לִגָּזֵז. וְאִם לִפְנֵי יֵאוּשׁ אוֹ קֹדֶם שֶׁנִּשְׁתַּנָּה יָלְדָה אוֹ גְּזָזָהּ הֲרֵי הַגִּזּוֹת וְהַוְּלָדוֹת שֶׁל בְּעָלִים. וְאַף עַל פִּי שֶׁנִּתְעַבְּרָה אוֹ נִטְעֲנָה בְּיַד הַגַּזְלָן הוֹאִיל וְלֹא נִתְיָאֲשׁוּ הַבְּעָלִים וְלֹא נִשְׁתַּנֵּית הַגְּזֵלָה. בִּרְשׁוּת בְּעָלֶיהָ הִיא עֲדַיִן אַף עַל פִּי שֶׁהַגַּזְלָן חַיָּב בָּאֳנָסֶיהָ:","גָּנַב אוֹ גָּזַל וְהִקְדִּישׁ וְטָבַח אַחַר שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים הֲרֵי הִיא בִּרְשׁוּת הַגַּזְלָן מִשָּׁעָה שֶׁהִקְדִּישָׁהּ בִּלְבַד כְּדֵי שֶׁלֹּא יְהֵא חוֹטֵא נִשְׂכָּר. וְכָל וַלְדוֹתֶיהָ וְגִזּוֹתֶיהָ מִשְּׁעַת גְּנֵבָה עַד שְׁעַת הֶקְדֵּשׁ שֶׁל בְּעָלִים:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁבַח הַבָּא מֵאֵלָיו כְּגוֹן גִּזּוֹת וּוְלָדוֹת. אֲבָל אִם הָיְתָה כְּחוּשָׁה וּפִטְּמָהּ אֲפִלּוּ לִפְנֵי יֵאוּשׁ נוֹטֵל מִן הַנִּגְזָל שְׁבַח הַפִּטּוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִשֶּׁבַח שֶׁיֵּשׁ בּוֹ הוֹצָאָה:","שִׁנּוּי הַחוֹזֵר לִבְרִיָּתוֹ אֵינוֹ שִׁנּוּי. כֵּיצַד. הַגּוֹזֵל עֵצִים וְדִבְּקָן בְּמַסְמְרִים וְעָשָׂה מֵהֶן תֵּבָה אֵינוֹ שִׁנּוּי שֶׁהֲרֵי אֶפְשָׁר לְפָרְקָן וְחוֹזְרִין לוּחוֹת כְּשֶׁהָיוּ:","גָּזַל עָפָר וַעֲשָׂאָהוּ לְבֵנָה לֹא קָנָה שֶׁאִם יָדֹק הַלְּבֵנָה תַּחְזֹר עָפָר כְּשֶׁהָיְתָה. גָּזַל לָשׁוֹן שֶׁל מַתֶּכֶת וַעֲשָׂאָהוּ מַטְבֵּעַ לֹא קָנָה שֶׁאִם יַתִּיךְ הַמַּטְבֵּעַ יַחְזֹר לָשׁוֹן כְּשֶׁהָיְתָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֲבָל הַגּוֹזֵל עֵצִים וּשְׂרָפָן וְקִצְּצָן אוֹ חָקַק בָּהֶן וַעֲשָׂאָן כֵּלִים. אוֹ שֶׁגָּזַל צֶמֶר וּצְבָעוֹ אוֹ נִפְּצוֹ וְלִבְּנוֹ. אוֹ שֶׁגָּזַל טָווּי וְעָשָׂהוּ בֶּגֶד. אוֹ שֶׁגָּזַל לְבֵנָה וַעֲשָׂאָהּ עָפָר אוֹ אֲבָנִים וְסִתְּתָן אוֹ מָעוֹת וְהִתִּיכָן. הֲרֵי זֶה שִׁנּוּי בְּיָדוֹ שֶׁאִם יַעֲשֵׂם מָעוֹת אֲחֵרוֹת פָּנִים חֲדָשׁוֹת הֵן. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","הַגּוֹזֵל מָעוֹת יְשָׁנוֹת וְשָׁפָן וְחִדְּשָׁן לֹא קָנָה שֶׁהֲרֵי מִתְיַשְּׁנִין וְחוֹזְרִין כְּשֶׁהָיוּ. גָּזַל מָעוֹת חֲדָשִׁים וְיִשְּׁנָם קָנָה שֶׁאִם יְחַדְּשֵׁם פָּנִים חֲדָשׁוֹת הֵן. גָּזַל דֶּקֶל מְחֻבָּר וְקִצְּצוֹ לֹא קָנָה וַאֲפִלּוּ כְּרָתוֹ חֻלְיוֹת חֻלְיוֹת. עָשָׂהוּ קוֹרוֹת קָנָה:","גָּזַל קוֹרוֹת גְּדוֹלוֹת וַעֲשָׂאָן קְטַנּוֹת לֹא קָנָה. עֲשָׂאָן לוּחוֹת עַד שֶׁנִּשְׁתַּנָּה שְׁמָם קָנָה. גָּזַל לוּלָב וְהִפְרִיד עָלָיו קָנָה הֶעָלִים. גָּזַל עָלִים וַעֲשָׂאָן חֻפִּיָיה קָנָה. גָּזַל טָלֶה וְנַעֲשָׂה אַיִל עֵגֶל וְנַעֲשָׂה שׁוֹר הֲרֵי זֶה שִׁנּוּי בְּיָדוֹ וְקָנָהוּ וּמְשַׁלֵּם כִּשְׁעַת הַגְּזֵלָה. וְאַף עַל פִּי שֶׁלֹּא נִתְיָאֲשׁוּ הַבְּעָלִים:","גָּזַל כְּלִי וּשְׁבָרוֹ אֵין שָׁמִין לוֹ הַפְּחָת אֶלָּא מְשַׁלֵּם דָּמָיו וְהַכְּלִי הַשָּׁבוּר שֶׁל גַּזְלָן. וְאִם רָצוּ הַבְּעָלִים לִטּל הַכְּלִי הַשָּׁבוּר נוֹטְלִין וּמְשַׁלֵּם הַפְּחָת. שֶׁזּוֹ תַּקָּנָה הִיא לַבְּעָלִים וְאִם לֹא רָצוּ הָרְשׁוּת בְּיָדָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","גְּזֵלָה שֶׁלֹּא נִשְׁתַּנֵּית וְהוּקְרָה אַף עַל פִּי שֶׁנִּתְיָאֲשׁוּ הַבְּעָלִים מִמֶּנָּה הֲרֵי זוֹ חוֹזֶרֶת לַבְּעָלִים וְאֵין לַגַּזְלָן בָּהּ כְּלוּם. שֶׁלֹּא תִּקְּנוּ לַגַּזְלָן אֶת הַשֶּׁבַח אַחַר יֵאוּשׁ אֶלָּא כְּגוֹן גִּזּוֹת וּוְלָדוֹת. אֲבָל שֶׁבַח הַיֹּקֶר אִם הָיְתָה הַגְּזֵלָה חוֹזֶרֶת בְּעֵינֶיהָ אֵינוֹ זוֹכֶה בָּהּ:"],"Mishneh Torah, Sabbath 13":["אֵין הַמּוֹצִיא מֵרְשׁוּת לִרְשׁוּת אוֹ הַמַּעֲבִיר בִּרְשׁוּת הָרַבִּים חוּץ לְאַרְבַּע אַמּוֹת חַיָּב עַד שֶׁיַּעֲקֹר חֵפֶץ מֵעַל גַּבֵּי מָקוֹם שֶׁיֵּשׁ בּוֹ אַרְבָּעָה טְפָחִים עַל אַרְבָּעָה טְפָחִים אוֹ יָתֵר וְיַנִּיחַ עַל גַּבֵּי מָקוֹם שֶׁיֵּשׁ בּוֹ אַרְבָּעָה עַל אַרְבָּעָה טְפָחִים:","יָדוֹ שֶׁל אָדָם חֲשׁוּבָה לוֹ כְּאַרְבָּעָה עַל אַרְבָּעָה. לְפִיכָךְ אִם עָקַר הַחֵפֶץ מִיַּד אָדָם הָעוֹמֵד בִּרְשׁוּת זוֹ וְהִנִּיחוֹ בְּיַד אָדָם אַחֵר הָעוֹמֵד בִּרְשׁוּת שְׁנִיָּה חַיָּב. וְכֵן אִם הָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת אֵלּוּ וּפָשַׁט יָדוֹ לִרְשׁוּת שְׁנִיָּה וְעָקַר הַחֵפֶץ מִמֶּנָּה אוֹ מִיַּד אָדָם הָעוֹמֵד בָּהּ וְהֶחֱזִיר יָדוֹ אֵלָיו חַיָּב. וְאַף עַל פִּי שֶׁלֹּא הִנִּיחַ הַחֵפֶץ בְּמָקוֹם שֶׁהוּא עוֹמֵד בּוֹ הוֹאִיל וְהוּא בְּיָדוֹ הֲרֵי הוּא כְּמֻנָּח בָּאָרֶץ:","הָיָה אוֹכֵל וְיוֹצֵא מֵרְשׁוּת לִרְשׁוּת וְחִשֵּׁב לְהוֹצִיא הָאוֹכֵל שֶׁבְּפִיו מֵרְשׁוּת לִרְשׁוּת חַיָּב. מִפְּנֵי שֶׁמַּחֲשַׁבְתּוֹ מְשִׂימָה פִּיו מְקוֹם אַרְבָּעָה אַף עַל פִּי שֶׁלֹּא הוֹצִיא כְּדֶרֶךְ הַמּוֹצִיאִין. וְכֵן מִי שֶׁהָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת אֵלּוּ וְהִשְׁתִּין מַיִם אוֹ רָקַק בִּרְשׁוּת שְׁנִיָּה חַיָּב שֶׁהֲרֵי עָקַר מֵרְשׁוּת זוֹ וְהִנִּיחַ בִּרְשׁוּת שְׁנִיָּה וּמַחֲשַׁבְתּוֹ עוֹשָׂה אוֹתוֹ כְּאִלּוּ עָקַר מֵעַל גַּבֵּי מְקוֹם אַרְבָּעָה. הָיָה עוֹמֵד בִּרְשׁוּת זוֹ וּפִי אַמָּה בִּרְשׁוּת שְׁנִיָּה וְהִשְׁתִּין בָּהּ פָּטוּר:","הָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת וּפָשַׁט יָדוֹ לִרְשׁוּת שְׁנִיָּה וְנָטַל מִשָּׁם מַיִם מֵעַל גַּבֵּי גּוּמָא מְלֵאָה מַיִם וְהוֹצִיאָן חַיָּב. שֶׁהַמַּיִם כֻּלָּן כְּאִלּוּ הֵן מֻנָּחִין עַל הָאָרֶץ. אֲבָל אִם הָיָה כְּלִי צָף עַל גַּבֵּי מַיִם וּפֵרוֹת בְּתוֹךְ הַכְּלִי וּפָשַׁט יָדוֹ וְלָקַח מִן הַפֵּרוֹת וְהוֹצִיא פָּטוּר. שֶׁהֲרֵי לֹא נָחוּ הַפֵּרוֹת עַל גַּבֵּי הָאָרֶץ וְנִמְצָא שֶׁלֹּא עָקַר מֵעַל גַּבֵּי מְקוֹם אַרְבָּעָה. וְאֵין צָרִיךְ לוֹמַר אִם הָיוּ הַפֵּרוֹת צָפִין עַל פְּנֵי הַמַּיִם וְהוֹצִיאָם שֶׁהוּא פָּטוּר. וְכֵן אִם הָיָה שֶׁמֶן צָף עַל פְּנֵי הַמַּיִם וְקָלַט מִן הַשֶּׁמֶן וְהוֹצִיאוֹ פָּטוּר:","כְּבָר אָמַרְנוּ שֶׁאֵין הַמּוֹצִיא מֵרְשׁוּת לִרְשׁוּת חַיָּב עַד שֶׁיַּעֲקֹר וְיַנִּיחַ. אֲבָל אִם עָקַר וְלֹא הִנִּיחַ אוֹ הִנִּיחַ וְלֹא עָקַר פָּטוּר. לְפִיכָךְ מִי שֶׁהָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת וּפָשַׁט יָדוֹ לִרְשׁוּת שְׁנִיָּה וְחֵפֶץ בְּיָדוֹ וּנְטָלוֹ אַחֵר מִמֶּנּוּ אוֹ שֶׁנָּתַן אַחֵר לְיָדוֹ חֵפֶץ וְהֶחֱזִיר יָדוֹ אֵלָיו שְׁנֵיהֶם פְּטוּרִים שֶׁזֶּה עָקַר וְזֶה הִנִּיחַ:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיְתָה יָדוֹ לְמַעְלָה מִשְּׁלֹשָׁה. אֲבָל הָיְתָה יָדוֹ בְּתוֹךְ שְׁלֹשָׁה סָמוּךְ לָאָרֶץ הֲרֵי זֶה כְּמִי שֶׁהִנִּיחַ בָּאָרֶץ וְחַיָּב:","הָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת אֵלּוּ וּפָשַׁט חֲבֵרוֹ יָד מֵרְשׁוּת שְׁנִיָּה וְנָטַל חֵפֶץ מִיַּד זֶה הָעוֹמֵד בִּרְשׁוּת זוֹ וְהִכְנִיסוֹ אֶצְלוֹ אוֹ שֶׁהוֹצִיא חֵפֶץ מֵאֶצְלוֹ וְהִנִּיחַ בְּיַד זֶה הָעוֹמֵד. זֶה הָעוֹמֵד לֹא עָשָׂה כְּלוּם שֶׁהֲרֵי חֲבֵרוֹ נָתַן בְּיָדוֹ אוֹ נָטַל מִיָּדוֹ וַחֲבֵרוֹ חַיָּב שֶׁהֲרֵי עָקַר וְהִנִּיחַ:","הָיָה עוֹמֵד בְּאַחַת מִשְּׁתֵּי רְשׁוּיוֹת אֵלּוּ וְנָתַן חֲבֵרוֹ חֵפֶץ בְּיָדוֹ אוֹ עַל גַּבָּיו וְיָצָא בְּאוֹתוֹ הַחֵפֶץ לִרְשׁוּת שְׁנִיָּה וְעָמַד שָׁם חַיָּב. מִפְּנֵי שֶׁעֲקִירַת גּוּפוֹ בַּחֵפֶץ שֶׁעָלָיו כַּעֲקִירַת חֵפֶץ מֵאוֹתָהּ רְשׁוּת וַעֲמִידָתוֹ בְּאוֹתוֹ הַחֵפֶץ כְּהַנָּחַת הַחֵפֶץ בַּקַּרְקַע שֶׁעָמַד בָּהּ. לְפִיכָךְ אִם יָצָא בַּחֵפֶץ שֶׁבְּיָדוֹ אוֹ עַל גַּבָּיו וְלֹא עָמַד בִּרְשׁוּת שְׁנִיָּה אֶלָּא חָזַר וְנִכְנַס וְהוּא בְּיָדוֹ אֲפִלּוּ יָצָא וְנִכְנַס כָּל הַיּוֹם כֻּלּוֹ עַד שֶׁיָּצָא הַיּוֹם פָּטוּר. לְפִי שֶׁעָקַר וְלֹא הִנִּיחַ. וַאֲפִלּוּ עָמַד לְתַקֵּן הַמַּשּׂאוֹי שֶׁעָלָיו עֲדַיִן הוּא פָּטוּר עַד שֶׁיַּעֲמֹד לָנוּחַ:","וְכֵן מִי שֶׁהָיְתָה חֲבִילָתוֹ עַל כְּתֵפוֹ וְרָץ בָּהּ אֲפִלּוּ כָּל הַיּוֹם אֵינוֹ חַיָּב עַד שֶׁיַּעֲמֹד. וְהוּא שֶׁיִּהְיֶה רָץ בָּהּ. אֲבָל אִם הָלַךְ מְעַט מְעַט הֲרֵי זֶה כְּעוֹקֵר וּמַנִּיחַ וְאָסוּר. לְפִיכָךְ מִי שֶׁקָּדַשׁ עָלָיו הַיּוֹם וַחֲבִילָתוֹ עַל כְּתֵפוֹ רָץ בָּהּ עַד שֶׁיַּגִּיעַ לְבֵיתוֹ וְזוֹרְקָהּ שָׁם כִּלְאַחַר יָד:","עָקַר הַחֵפֶץ מֵרְשׁוּת הָרַבִּים וְהָלַךְ בּוֹ פָּחוֹת מֵאַרְבַּע אַמּוֹת וְעָמַד וְחָזַר וְהָלַךְ פָּחוֹת מֵאַרְבַּע אַמּוֹת וְעָמַד אֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ פָּטוּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁעָמַד לָנוּחַ. אֲבָל אִם עָמַד לְתַקֵּן מַשָּׂאוֹ הֲרֵי זֶה כִּמְהַלֵּךְ וּכְשֶׁיַּעֲמֹד חוּץ לְאַרְבַּע אַמּוֹת חַיָּב. וְהוּא שֶׁיַּעֲמֹד חוּץ לְאַרְבַּע אַמּוֹת לָנוּחַ. אֲבָל אִם יַעֲמֹד לְתַקֵּן מַשָּׂאוֹ עֲדַיִן הוּא כִּמְהַלֵּךְ וְאֵינוֹ חַיָּב עַד שֶׁיַּעֲמֹד לָנוּחַ חוּץ לְאַרְבַּע אַמּוֹת:","הָיָה קָנֶה אוֹ רֹמַח וְכַיּוֹצֵא בּוֹ מֻנָּח עַל הָאָרֶץ וְהִגְבִּיהַּ הַקָּצֶה הָאֶחָד וְהָיָה הַקָּצֶה הַשֵּׁנִי מֻנָּח בָּאָרֶץ וְהִשְׁלִיכוֹ לְפָנָיו וְחָזַר וְהִגְבִּיהַּ הַקָּצֶה הַשֵּׁנִי שֶׁהָיָה מֻנָּח בָּאָרֶץ וְהִשְׁלִיכוֹ לְפָנָיו עַל דֶּרֶךְ זוֹ עַד שֶׁהֶעֱבִיר הַחֵפֶץ כַּמָּה מִילִין פָּטוּר. לְפִי שֶׁלֹּא עָקַר הַחֵפֶץ כֻּלּוֹ מֵעַל גַּבֵּי הָאָרֶץ. וְאִם מָשַׁךְ הַחֵפֶץ וּגְרָרוֹ עַל הָאָרֶץ מִתְּחִלַּת אַרְבַּע לְסוֹף אַרְבַּע חַיָּב שֶׁהַמְגַלְגֵּל עוֹקֵר הוּא:","עָקַר הַחֵפֶץ מִזָּוִית זוֹ לְהַנִּיחוֹ בְּזָוִית אַחֶרֶת שֶׁנִּמְצֵאת זוֹ הָעֲקִירָה עֲקִירָה הַמֻּתֶּרֶת וְנִמְלַךְ בַּדֶּרֶךְ וְהוֹצִיאוֹ לִרְשׁוּת שְׁנִיָּה פָּטוּר. מִפְּנֵי שֶׁלֹּא הָיְתָה עֲקִירָה רִאשׁוֹנָה לְכָךְ וְנִמְצֵאת כָּאן הַנָּחָה בְּלֹא עֲקִירָה. וְכֵן הָעוֹקֵר חֵפֶץ וְהִנִּיחוֹ עַל חֲבֵרוֹ כְּשֶׁהוּא מְהַלֵּךְ וּבְעֵת שֶׁיִּרְצֶה חֲבֵרוֹ לַעֲמֹד נְטָלוֹ מֵעַל גַּבֵּי חֲבֵרוֹ הֲרֵי זֶה פָּטוּר שֶׁהֲרֵי יֵשׁ כָּאן עֲקִירָה בְּלֹא הַנָּחָה:","הַזּוֹרֵק חֵפֶץ מֵרְשׁוּת לִרְשׁוּת אוֹ מִתְּחִלַּת אַרְבַּע לְסוֹף אַרְבַּע בִּרְשׁוּת הָרַבִּים וְקֹדֶם שֶׁיָּנוּחַ קְלָטוֹ אַחֵר בְּיָדוֹ אוֹ קְלָטוֹ כֶּלֶב אוֹ נִשְׂרַף פָּטוּר. מִפְּנֵי שֶׁאֵין זוֹ הַנָּחָה שֶׁנִּתְכַּוֵּן לָהּ. לְפִיכָךְ אִם נִתְכַּוֵּן בִּשְׁעַת זְרִיקָה לְכָךְ חַיָּב:","הַזּוֹרֵק חֵפֶץ מֵרְשׁוּת לִרְשׁוּת וְהָיָה קָשׁוּר בְּחֶבֶל וַאֲגָדוֹ בְּיָדוֹ. אִם יָכוֹל לִמְשֹׁךְ הַחֵפֶץ אֶצְלוֹ פָּטוּר. שֶׁהֲרֵי אֵין כָּאן הֲנָחָה גְּמוּרָה וְנִמְצָא כְּמִי שֶׁעָקַר וְלֹא הִנִּיחַ:","הַזּוֹרֵק וְנָחָה בְּתוֹךְ יָדוֹ שֶׁל חֲבֵרוֹ. אִם עָמַד חֲבֵרוֹ בִּמְקוֹמוֹ וְקִבְּלָהּ הַזּוֹרֵק חַיָּב שֶׁהֲרֵי עָקַר וְהִנִּיחַ. וְאִם נֶעֱקַר חֲבֵרוֹ מִמְּקוֹמוֹ וְקִבְּלָהּ פָּטוּר. זָרַק וְרָץ הַזּוֹרֵק עַצְמוֹ אַחַר הַחֵפֶץ וְקִבְּלוֹ בְּיָדוֹ בִּרְשׁוּת אַחֶרֶת אוֹ חוּץ לְאַרְבַּע אַמּוֹת פָּטוּר כְּאִלּוּ נֶעֱקַר אַחֵר וְקִבְּלוֹ. שֶׁאֵין הַהַנָּחָה גְּמוּרָה עַד שֶׁיָּנוּחַ הַחֵפֶץ בְּמָקוֹם שֶׁהָיָה לוֹ לָנוּחַ בּוֹ בִּשְׁעַת עֲקִירָה:","הַזּוֹרֵק מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד וּרְשׁוּת הָרַבִּים בָּאֶמְצַע אַף עַל פִּי שֶׁעָבַר הַחֵפֶץ בַּאֲוִיר רְשׁוּת הָרַבִּים פָּטוּר. וְהוּא שֶׁיַּעֲבֹר לְמַעְלָה מִשְּׁלֹשָׁה טְפָחִים אֲבָל אִם עָבַר בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לָאָרֶץ וְנָח עַל גַּבֵּי מַשֶּׁהוּ אַף עַל פִּי שֶׁנֶּעֱקַר אוֹ נִתְגַּלְגֵּל וְיָצָא הַחֵפֶץ מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד אַחֶרֶת הֲרֵי הוּא כְּמִי שֶׁנִּשְׁאַר עוֹמֵד בִּרְשׁוּת הָרַבִּים וּלְפִיכָךְ חַיָּב. וְכֵן הַזּוֹרֵק מֵרְשׁוּת הָרַבִּים לִרְשׁוּת הָרַבִּים וּרְשׁוּת הַיָּחִיד בָּאֶמְצַע פָּטוּר. וְאִם עָבַר הַחֵפֶץ בְּפָחוֹת מִשְּׁלֹשָׁה סָמוּךְ לָאָרֶץ וְנָח עַל גַּבֵּי מַשֶּׁהוּ אַף עַל פִּי שֶׁחָזַר וְנִתְגַּלְגֵּל וְיָצָא לִרְשׁוּת הָרַבִּים הַשְּׁנִיָּה הֲרֵי הוּא כְּמִי שֶׁנִּשְׁאַר עוֹמֵד בִּרְשׁוּת הַיָּחִיד וּלְפִיכָךְ חַיָּב:","הַמַּעֲבִיר אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים זוֹ עִם רְשׁוּת הָרַבִּים הַשְּׁנִיָּה חַיָּב מִפְּנֵי שֶׁאַרְבַּע אַמּוֹת בִּשְׁתֵּי רְשׁוּיוֹת הָרַבִּים מִצְטָרְפִים מִפְּנֵי שֶׁלֹּא נָח הַחֵפֶץ בָּרְשׁוּת שֶׁבֵּינֵיהֶן:","הַמּוֹשִׁיט מֵרְשׁוּת הַיָּחִיד לִרְשׁוּת הַיָּחִיד וּרְשׁוּת הָרַבִּים בָּאֶמְצַע חַיָּב. וַאֲפִלּוּ הוֹשִׁיט לְמַעְלָה מֵאֲוִיר רְשׁוּת הָרַבִּים. שֶׁכֵּן הָיְתָה עֲבוֹדַת הַלְוִיִּם בַּמִּשְׁכָּן מוֹשִׁיטִין אֶת הַקְּרָשִׁים מֵעֲגָלָה לַעֲגָלָה וּרְשׁוּת הָרַבִּים בֵּין שְׁתֵּי הָעֲגָלוֹת וְכָל עֲגָלָה וַעֲגָלָה רְשׁוּת הַיָּחִיד הִיא:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שְׁתֵּי רְשׁוּת הַיָּחִיד בְּאֹרֶךְ רְשׁוּת הָרַבִּים כְּמוֹ שֶׁהָעֲגָלוֹת מְהַלְּכוֹת בִּרְשׁוּת הָרַבִּים זוֹ אַחַר זוֹ. אֲבָל אִם הָיוּ שְׁתֵּי הָרְשֻׁיּוֹת בִּשְׁנֵי צִדֵּי רְשׁוּת הָרַבִּים אַף הַמּוֹשִׁיט מֵרְשׁוּת הַיָּחִיד זוֹ לִרְשׁוּת הַיָּחִיד שֶׁכְּנֶגְדָּהּ פָּטוּר:","שָׁכַח וּפָשַׁט יָדוֹ וְהִיא מְלֵאָה פֵּרוֹת וְהוֹצִיאָהּ מֵחָצֵר זוֹ לְהַכְנִיסָהּ לֶחָצֵר שֶׁבְּצִדָּהּ וְנִזְכַּר קֹדֶם שֶׁיַּכְנִיס וַהֲרֵי יָדוֹ תְּלוּיָה בַּאֲוִיר רְשׁוּת הָרַבִּים מֻתָּר לְהַחֲזִירָהּ אֵלָיו לַחֲצֵרוֹ. אֲבָל לְהַכְנִיסָהּ לְאוֹתָהּ הֶחָצֵר הַשְּׁנִיָּה אָסוּר. כְּדֵי שֶׁלֹּא יַעֲשֶׂה מַחֲשַׁבְתּוֹ שֶׁחָשַׁב בִּשְׁעַת שְׁגָגָה. וְאִם הוֹצִיא יָדוֹ בְּמֵזִיד הֲרֵי זֶה אָסוּר לְהַחֲזִירָהּ אֶצְלוֹ אֶלָּא קָנְסוּ אוֹתוֹ שֶׁתְּהֵא יָדוֹ תְּלוּיָה עַד שֶׁתֶּחְשַׁךְ:","הַמִּתְכַּוֵּן לִזְרֹק שְׁמוֹנֶה אַמּוֹת בִּרְשׁוּת הָרַבִּים וְנָח הַחֵפֶץ בְּסוֹף אַרְבַּע חַיָּב שֶׁהֲרֵי נַעֲשָׂה כְּשִׁעוּר הַמְּלָאכָה וְנַעֲשֵׂית מַחֲשַׁבְתּוֹ. שֶׁהַדָּבָר יָדוּעַ שֶׁאֵין זֶה הַחֵפֶץ מַגִּיעַ לְסוֹף שְׁמוֹנֶה עַד שֶׁיַּעֲבֹר עַל כָּל מָקוֹם וּמָקוֹם מִכָּל הַשְּׁמוֹנֶה. אֲבָל אִם נִתְכַּוֵּן לִזְרֹק אַרְבַּע וְנָח הַחֵפֶץ בְּסוֹף שְׁמוֹנֶה פָּטוּר. לְפִי שֶׁנָּח בְּמָקוֹם שֶׁלֹּא חָשַׁב שֶׁתַּעֲבֹר בּוֹ וְכָל שֶׁכֵּן שֶׁתָּנוּחַ. לְפִיכָךְ אִם חָשַׁב בְּעֵת זְרִיקָה שֶׁיָּנוּחַ הַחֵפֶץ בְּכָל מָקוֹם שֶׁיִּרְצֶה חַיָּב:","זָרַק לְתוֹךְ אַרְבַּע אַמּוֹת וְנִתְגַּלְגֵּל חוּץ לְאַרְבַּע אַמּוֹת פָּטוּר. זָרַק חוּץ לְאַרְבַּע אַמּוֹת וְנִתְגַּלְגֵּל לְתוֹךְ אַרְבַּע אַמּוֹת אִם נָח עַל גַּבֵּי מַשֶּׁהוּ חוּץ לְאַרְבַּע אַמּוֹת וְאַחַר כָּךְ נִתְגַּלְגֵּל וְנִכְנַס לְתוֹךְ אַרְבַּע אַמּוֹת חַיָּב וְאִם לֹא נָח כְּלָל הֲרֵי זֶה פָּטוּר:"],"Mishneh Torah, Sabbath 24":["יֵשׁ דְּבָרִים שֶׁהֵן אֲסוּרִין בְּשַׁבָּת אַף עַל פִּי שֶׁאֵינָם דּוֹמִין לִמְלָאכָה וְאֵינָם מְבִיאִין לִידֵי מְלָאכָה. וּמִפְּנֵי מָה נֶאֶסְרוּ מִשּׁוּם שֶׁנֶּאֱמַר (ישעיה נח יג) \"אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךָ עֲשׂוֹת חֲפָצֶיךָ בְּיוֹם קָדְשִׁי\" וְנֶאֱמַר (ישעיה נח יג) \"וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךָ מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר\". לְפִיכָךְ אָסוּר לְאָדָם לְהַלֵּךְ בַּחֲפָצָיו בְּשַׁבָּת וַאֲפִלּוּ לְדַבֵּר בָּהֶן כְּגוֹן שֶׁיְּדַבֵּר עִם שֻׁתָּפוֹ מַה יִּמְכֹּר לְמָחָר אוֹ מַה יִּקְנֶה אוֹ הֵיאַךְ יִבְנֶה בַּיִת זֶה וּבְאֵי זֶה סְחוֹרָה יֵלֵךְ לְמָקוֹם פְּלוֹנִי. כָּל זֶה וְכַיּוֹצֵא בּוֹ אָסוּר שֶׁנֶּאֱמַר וְדַבֵּר דָּבָר דִּבּוּר אָסוּר הִרְהוּר מֻתָּר:","אָסוּר לְאָדָם לִפְקֹד גִּנּוֹתָיו וּשְׂדוֹתָיו בְּשַׁבָּת כְּדֵי לִרְאוֹת מַה הֵן צְרִיכִין אוֹ הֵיאַךְ הֵן פֵּרוֹתֵיהֶן. שֶׁהֲרֵי זֶה מְהַלֵּךְ לַעֲשׂוֹת חֶפְצוֹ. וְכֵן אָסוּר לְאָדָם שֶׁיֵּצֵא בְּשַׁבָּת עַד סוֹף הַתְּחוּם וְיֵשֵׁב שָׁם עַד שֶׁתֶּחְשַׁךְ כְּדֵי שֶׁיִּהְיֶה קָרוֹב לַעֲשׂוֹת חֲפָצָיו בְּמוֹצָאֵי שַׁבָּת. שֶׁהֲרֵי נִמְצָא הִלּוּכוֹ בְּשַׁבָּת לַעֲשׂוֹת חֲפָצָיו:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֶחְשִׁיךְ עַל הַתְּחוּם לַעֲשׂוֹת דָּבָר שֶׁאָסוּר בְּשַׁבָּת לַעֲשׂוֹתוֹ. אֲבָל אִם הֶחְשִׁיךְ לַעֲשׂוֹת דָּבָר שֶׁמֻּתָּר לַעֲשׂוֹתוֹ בְּשַׁבָּת הֲרֵי זֶה מֻתָּר. כֵּיצַד. אֵין מַחְשִׁיכִין עַל הַתְּחוּם לְהָבִיא פֵּרוֹת מְחֻבָּרִין אוֹ לִשְׂכֹּר פּוֹעֲלִין. אֲבָל מַחְשִׁיךְ הוּא לִשְׁמֹר פֵּרוֹת שֶׁהֲרֵי מֻתָּר לִשְׁמֹר בְּשַׁבָּת. וּמַחְשִׁיךְ לְהָבִיא בְּהֵמָה אוֹ פֵּרוֹת תְּלוּשִׁין. שֶׁהַבְּהֵמָה קוֹרֵא לָהּ וְהִיא בָּאָה אַף עַל פִּי שֶׁהִיא חוּץ לַתְּחוּם. וּפֵרוֹת תְּלוּשִׁין אִלּוּ הָיוּ שָׁם מְחִצּוֹת הָיָה מֻתָּר לַהֲבִיאָן בְּשַׁבָּת. וְכֵן אוֹמֵר אָדָם לַחֲבֵרוֹ לִכְרַךְ פְּלוֹנִי אֲנִי הוֹלֵךְ לְמָחָר שֶׁאִם הָיוּ שָׁם בּוּרְגָנִים הָיָה הוֹלֵךְ לְשָׁם בְּשַׁבָּת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מֻתָּר לְאָדָם לוֹמַר לְפוֹעֵל הַנִּרְאֶה שֶׁתַּעֲמֹד עִמִּי לָעֶרֶב. אֲבָל לֹא יֹאמַר לוֹ הֱיֵה נָכוֹן לִי לָעֶרֶב שֶׁנִּמְצָא עוֹשֶׂה חֶפְצוֹ בְּשַׁבָּת. וְאָסוּר לָרוּץ וּלְדַלֵּג בְּשַׁבָּת שֶׁנֶּאֱמַר (ישעיה נח יג) \"מֵעֲשׂוֹת דְּרָכֶיךָ\" שֶׁלֹּא יְהֵא הִלּוּכְךָ שֶׁל שַׁבָּת כְּהִלּוּכְךָ שֶׁל חֹל. וְיוֹרֵד אָדָם לְבוֹר וְשִׁיחַ וּמְעָרָה אֲפִלּוּ הֵן מֵאָה אַמָּה וּמְטַפֵּס וְיוֹרֵד וְשׁוֹתֶה וּמְטַפֵּס וְעוֹלֶה. וְאָסוּר לְהַרְבּוֹת בְּשִׂיחָה בְּטֵלָה שֶׁנֶּאֱמַר (ישעיה נח יג) \"וְדַבֵּר דָּבָר\" שֶׁלֹּא יְהֵא דִּבּוּרְךָ שֶׁל שַׁבָּת כְּדִבּוּרְךָ שֶׁל חל:","מֻתָּר לָרוּץ בְּשַׁבָּת לִדְבַר מִצְוָה כְּגוֹן שֶׁיָּרוּץ לְבֵית הַכְּנֶסֶת אוֹ לְבֵית הַמִּדְרָשׁ. וּמְחַשְּׁבִין חֶשְׁבּוֹנוֹת שֶׁל מִצְוָה וּמוֹדְדִין מְדִידָה שֶׁל מִצְוָה כְּגוֹן מִקְוֶה לֵידַע אִם יֵשׁ כַּשִּׁעוּר אוֹ בֶּגֶד לֵידַע אִם מְקַבֵּל טֻמְאָה. וּפוֹסְקִין צְדָקָה לָעֲנִיִּים. וְהוֹלְכִין לְבָתֵּי כְּנֵסִיּוֹת וּלְבָתֵּי מִדְרָשׁוֹת וַאֲפִלּוּ לְטַרְטֵיאוֹת וּטְרַקְלִין שֶׁל כּוּתִים לְפַקֵּחַ עַל עִסְקֵי רַבִּים בְּשַׁבָּת. וּמְשַׁדְּכִין עַל הַתִּינוֹקֶת לֵיאָרֵס וְעַל הַתִּינוֹק לְלַמְּדוֹ סֵפֶר וּלְלַמְּדוֹ אֻמָּנוּת. וּמְבַקְּרִין חוֹלִין וּמְנַחֲמִים אֲבֵלִים. וְהַנִּכְנָס לְבַקֵּר אֶת הַחוֹלֶה אוֹמֵר שַׁבָּת הִיא מִלִּזְעֹק וּרְפוּאָה קְרוֹבָה לָבוֹא. וּמַחְשִׁיכִין עַל הַתְּחוּם לְפַקֵּחַ עַל עִסְקֵי כַּלָּה וְעַל עִסְקֵי הַמֵּת לְהָבִיא לוֹ אָרוֹן וְתַכְרִיכִין. וְאוֹמֵר לוֹ לֵךְ לְמָקוֹם פְּלוֹנִי לֹא מָצָאתָ שָׁם הָבֵא מִמָּקוֹם פְּלוֹנִי לֹא מָצָאתָ בְּמָנֶה הָבֵא בְּמָאתַיִם. וּבִלְבַד שֶׁלֹּא יִזְכֹּר לוֹ סְכוּם מִקָּח. שֶׁכָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן מִצְוָה הֵן וְנֶאֱמַר (ישעיה נח יג) \"עֲשׂוֹת חֲפָצֶיךָ\" וְכוּ' חֲפָצֶךָ אֲסוּרִין חֶפְצֵי שָׁמַיִם מֻתָּרִין:","מַפְלִיגִין בַּיָּם הַגָּדוֹל בְּעֶרֶב שַׁבָּת לִדְבַר מִצְוָה וּפוֹסֵק עִמּוֹ לִשְׁבֹּת וְאֵינוֹ שׁוֹבֵת. וּמְפִירִין נְדָרִים בְּשַׁבָּת בֵּין לְצֹרֶךְ שַׁבָּת בֵּין שֶׁלֹּא לְצֹרֶךְ שַׁבָּת. וְנִשְׁאָלִין לְחָכָם עַל הַנְּדָרִים שֶׁהֵן לְצֹרֶךְ הַשַּׁבָּת וּמַתִּירִין אַף עַל פִּי שֶׁהָיָה לָהֶן פְּנַאי לְהַתִּירָן קֹדֶם הַשַּׁבָּת שֶׁדְּבָרִים אֵלּוּ מִצְוָה הֵן:","אֵין עוֹנְשִׁין בְּשַׁבָּת אַף עַל פִּי שֶׁהָעֹנֶשׁ מִצְוַת עֲשֵׂה אֵינָהּ דּוֹחָה שַׁבָּת. כֵּיצַד. הֲרֵי שֶׁנִּתְחַיֵּב בְּבֵית דִּין מַלְקוֹת אוֹ מִיתָה אֵין מַלְקִין אוֹתוֹ וְאֵין מְמִיתִין אוֹתוֹ בְּשַׁבָּת שֶׁנֶּאֱמַר (שמות לה ג) \"לֹא תְבַעֲרוּ אֵשׁ בְּכל משְׁבֹתֵיכֶם בְּיוֹם הַשַּׁבָּת\" זוֹ אַזְהָרָה לְבֵית דִּין שֶׁלֹּא יִשְׂרְפוּ בְּשַׁבָּת מִי שֶׁנִּתְחַיֵּב שְׂרֵפָה וְהוּא הַדִּין לִשְׁאָר עֳנָשִׁין:","מֻתָּר לְאָדָם לִשְׁמֹר פֵּרוֹתָיו בְּשַׁבָּת בֵּין תְּלוּשִׁים בֵּין מְחֻבָּרִין. וְאִם בָּא אָדָם לִטּל מֵהֶן אוֹ בְּהֵמָה וְחַיָּה לֶאֱכל מֵהֶן גּוֹעֵר בָּהֶן וּמַכֶּה בָּהֶם וּמַרְחִיקָן. וַהֲלֹא דָּבָר זֶה מֵחֲפָצָיו הוּא וְלָמָּה הוּא מֻתָּר. מִפְּנֵי שֶׁלֹּא נֶאֱסַר אֶלָּא לְהַקְנוֹת לְעַצְמוֹ חֲפָצִים שֶׁאֵינָן עַתָּה מְצוּיִים אוֹ לְהִשְׂתַּכֵּר וּלְהַרְוִיחַ וּלְהִטָּפֵל בַּהֲנָאָה שֶׁתָּבוֹא לְיָדוֹ. אֲבָל לִשְׁמֹר מָמוֹנוֹ שֶׁכְּבָר בָּא לְיָדוֹ עַד שֶׁיַּעֲמֹד כְּמוֹת שֶׁהוּא מֻתָּר. הָא לְמָה זֶה דּוֹמֶה לְנוֹעֵל בֵּיתוֹ מִפְּנֵי הַגַּנָּבִים:","הַמְשַׁמֵּר זְרָעָיו מִפְּנֵי הָעוֹפוֹת וּמִקְשָׁאָיו וּמִדְלָעָיו מִפְּנֵי הַחַיָּה לֹא יְסַפֵּק וְלֹא יְרַקֵּד כְּדֶרֶךְ שֶׁעוֹשֶׂה בְּחֹל גְּזֵרָה שֶׁמָּא יִטּל צְרוֹר וְיִזְרֹק אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים:","כָּל הַדְּבָרִים שֶׁהֵן אֲסוּרִין מִשּׁוּם שְׁבוּת לֹא גָּזְרוּ עֲלֵיהֶן בֵּין הַשְּׁמָשׁוֹת אֶלָּא בְּעַצְמוֹ שֶׁל יוֹם הוּא שֶׁהֵן אֲסוּרִין אֲבָל בֵּין הַשְּׁמָשׁוֹת מֻתָּרִין. וְהוּא שֶׁיִּהְיֶה שָׁם דְּבַר מִצְוָה אוֹ דֹּחַק. כֵּיצַד. מֻתָּר לוֹ בֵּין הַשְּׁמָשׁוֹת לַעֲלוֹת בָּאִילָן אוֹ לָשׁוּט עַל פְּנֵי הַמַּיִם לְהָבִיא לוּלָב אוֹ שׁוֹפָר. וְכֵן מוֹרִיד מִן הָאִילָן אוֹ מוֹצִיא מִן הַכַּרְמְלִית עֵרוּב שֶׁעָשָׂה. וְכֵן אִם הָיָה טָרוּד וְנֶחְפָּז וְנִצְרָךְ לְדָבָר שֶׁהוּא מִשּׁוּם שְׁבוּת בֵּין הַשְּׁמָשׁוֹת הֲרֵי זֶה מֻתָּר. אֲבָל אִם לֹא הָיָה שָׁם דֹּחַק וְלֹא דְּבַר מִצְוָה אָסוּר. לְפִיכָךְ אֵין מְעַשְּׂרִין אֶת הַוַּדַּאי בֵּין הַשְּׁמָשׁוֹת אַף עַל פִּי שֶׁאִסּוּר הַפְרָשַׁת הַמַּעֲשֵׂר בְּשַׁבָּת מִשּׁוּם שְׁבוּת. אֲבָל מְעַשְּׂרִים אֶת הַדְּמַאי:","קָטָן שֶׁעָשָׂה בְּשַׁבָּת דָּבָר שֶׁהוּא מִשּׁוּם שְׁבוּת כְּגוֹן שֶׁתָּלַשׁ מֵעָצִיץ שֶׁאֵינוֹ נָקוּב אוֹ טִלְטֵל בְּכַרְמְלִית אֵין בֵּית דִּין מְצֻוִּין לְהַפְרִישׁוֹ. וְכֵן אִם הִנִּיחוֹ אָבִיו אֵין מְמַחִין בְּיָדוֹ:","אָסְרוּ חֲכָמִים לְטַלְטֵל מִקְצָת דְּבָרִים בְּשַׁבָּת כְּדֶרֶךְ שֶׁהוּא עוֹשֶׂה בְּחֹל. וּמִפְּנֵי מָה נָגְעוּ בְּאִסּוּר זֶה. אָמְרוּ וּמָה אִם הִזְהִירוּ נְבִיאִים וְצִוּוּ שֶׁלֹּא יִהְיֶה הִלּוּכְךָ בְּשַׁבָּת כְּהִלּוּכְךָ בְּחֹל וְלֹא שִׂיחַת הַשַּׁבָּת כְּשִׂיחַת החֹל שֶׁנֶּאֱמַר (ישעיה נח יג) \"וְדַבֵּר דָּבָר\" קַל וָחֹמֶר שֶׁלֹּא יִהְיֶה טִלְטוּל בְּשַׁבָּת כְּטִלְטוּל בְּחֹל כְּדֵי שֶׁלֹּא יִהְיֶה כְּיוֹם חֹל בְּעֵינָיו וְיָבוֹא לְהַגְבִּיהַּ וּלְתַקֵּן כֵּלִים מִפִּנָּה לְפִנָּה אוֹ מִבַּיִת לְבַיִת אוֹ לְהַצְנִיעַ אֲבָנִים וְכַיּוֹצֵא בָּהֶן שֶׁהֲרֵי הוּא בָּטֵל וְיוֹשֵׁב בְּבֵיתוֹ וִיבַקֵּשׁ דָּבָר שֶׁיִּתְעַסֵּק בּוֹ וְנִמְצָא שֶׁלֹּא שָׁבַת וּבִטֵּל הַטַּעַם שֶׁנֶּאֱמַר בְּתוֹרָה (שמות כב יב) (דברים ה יג) \"לְמַעַן יָנוּחַ\":","וְעוֹד כְּשֶׁיְּבַקֵּר וִיטַלְטֵל כֵּלִים שֶׁמְּלַאכְתָּן לְאִסּוּר אֶפְשָׁר שֶׁיִּתְעַסֵּק בָּהֶן מְעַט וְיָבֹא לִידֵי מְלָאכָה. וְעוֹד מִפְּנֵי שֶׁמִּקְצָת הָעָם אֵינָם בַּעֲלֵי אֻמָּנֻיּוֹת אֶלָּא בְּטֵלִין כָּל יְמֵיהֶן כְּגוֹן הַטַּיָּלִין וְיוֹשְׁבֵי קְרָנוֹת שֶׁכָּל יְמֵיהֶן הֵן שׁוֹבְתִים מִמְּלָאכָה וְאִם יִהְיֶה מֻתָּר לְהַלֵּךְ וּלְדַבֵּר וּלְטַלְטֵל כִּשְׁאָר הַיָּמִים נִמְצָא שֶׁלֹּא שָׁבַת שְׁבִיתָה הַנִּכֶּרֶת. לְפִיכָךְ שְׁבִיתָה מִדְּבָרִים אֵלּוּ הִיא שְׁבִיתָה הַשָּׁוָה בְּכָל אָדָם. וּמִפְּנֵי דְּבָרִים אֵלּוּ נָגְעוּ בְּאִסּוּר הַטִּלְטוּל. וְאָסְרוּ שֶׁלֹּא יְטַלְטֵל אָדָם בְּשַׁבָּת אֶלָּא כֵּלִים הַצָּרִיךְ לָהֶם כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Sabbath 8":["הַחוֹרֵשׁ כָּל שֶׁהוּא חַיָּב. הַמְנַכֵּשׁ בְּעִקְּרֵי הָאִילָנוֹת וְהַמְקַרְסֵם עֲשָׂבִים אוֹ הַמְזָרֵד אֶת הַשָּׂרִיגִים כְּדֵי לְיַפּוֹת אֶת הַקַּרְקַע הֲרֵי זֶה תּוֹלֶדֶת חוֹרֵשׁ וּמִשֶּׁיַּעֲשֶׂה כָּל שֶׁהוּא חַיָּב. וְכֵן הַמַּשְׁוֶה פְּנֵי הַשָּׂדֶה כְּגוֹן שֶׁהִשְׁפִּיל הַתֵּל וְרִדְּדוֹ אוֹ מִלֵּא הַגַּיְא חַיָּב מִשּׁוּם חוֹרֵשׁ. וְשִׁעוּרוֹ כָּל שֶׁהוּא. וְכֵן כָּל הַמַּשְׁוֶה גֻּמּוֹת שִׁעוּרוֹ כָּל שֶׁהוּא:","הַזּוֹרֵעַ כָּל שֶׁהוּא חַיָּב. הַזּוֹמֵר אֶת הָאִילָן כְּדֵי שֶׁיִּצְמַח הֲרֵי זֶה מֵעֵין זוֹרֵעַ. אֲבָל הַמַּשְׁקֶה צְמָחִין וְאִילָנוֹת בְּשַׁבָּת הֲרֵי זֶה תּוֹלֶדֶת זוֹרֵעַ וְחַיָּב בְּכָל שֶׁהוּא. וְכֵן הַשּׁוֹרֶה חִטִּין וּשְׂעוֹרִין וְכַיּוֹצֵא בָּהֶן בַּמַּיִם הֲרֵי זֶה תּוֹלֶדֶת זוֹרֵעַ וְחַיָּב בְּכָל שֶׁהוּא:","הַקּוֹצֵר כִּגְרוֹגֶרֶת חַיָּב. וְתוֹלֵשׁ תּוֹלֶדֶת קוֹצֵר הוּא. וְכָל הָעוֹקֵר דָּבָר מִגִּדּוּלוֹ חַיָּב מִשּׁוּם קוֹצֵר. לְפִיכָךְ צְרוֹר שֶׁעָלוּ בּוֹ עֲשָׂבִים וּכְשׁוּת שֶׁעָלָה בַּסְּנֶה וַעֲשָׂבִים שֶׁצָּמְחוּ עַל גַּב הֶחָבִית. הַתּוֹלֵשׁ מֵהֶן חַיָּב שֶׁזֶּה הוּא מְקוֹם גִּדּוּלָן. אֲבָל הַתּוֹלֵשׁ מֵעָצִיץ שֶׁאֵינוֹ נָקוּב פָּטוּר מִפְּנֵי שֶׁאֵין זֶה מְקוֹם גִּדּוּלוֹ. וְעָצִיץ נָקוּב בִּכְדֵי שֹׁרֶשׁ קָטָן הֲרֵי הוּא כְּאֶרֶץ וְהַתּוֹלֵשׁ מִמֶּנּוּ חַיָּב:","כָּל זֶרַע שֶׁקְּצִירָתוֹ מַצְמַחַת אוֹתוֹ וּמְגַדַּלְתּוֹ כְּגוֹן אַסְפַּסְתָּא וְסִלְקָא. הַקּוֹצְרוֹ בִּשְׁגָגָה חַיָּב שְׁתֵּי חַטָּאוֹת. אַחַת מִפְּנֵי שֶׁהוּא קוֹצֵר וְאַחַת מִפְּנֵי שֶׁהוּא נוֹטֵעַ. וְכֵן הַזּוֹמֵר וְהוּא צָרִיךְ לָעֵצִים חַיָּב מִשּׁוּם קוֹצֵר וּמִשּׁוּם נוֹטֵעַ. גַּבְשׁוּשִׁית שֶׁל עָפָר שֶׁעָלוּ בָּהּ עֲשָׂבִים, הִגְבִּיהָהּ מֵעַל הָאָרֶץ וְהִנִּיחָהּ עַל גַּבֵּי יְתֵדוֹת חַיָּב מִשּׁוּם תּוֹלֵשׁ. הָיְתָה עַל גַּבֵּי יְתֵדוֹת וְהִנִּיחָהּ עַל הָאָרֶץ חַיָּב מִשּׁוּם זוֹרֵעַ. תְּאֵנִים שֶׁיָּבְשׁוּ בְּאִבֵּיהֶן וְכֵן אִילָן שֶׁיָּבְשׁוּ פֵּרוֹתָיו בּוֹ. הַתּוֹלֵשׁ מֵהֶן בְּשַׁבָּת חַיָּב אַף עַל פִּי שֶׁהֵן כַּעֲקוּרִין לְעִנְיַן טֻמְאָה:","הַתּוֹלֵשׁ עֻלְשִׁין הַמְזָרֵד זְרָדִין. אִם לַאֲכִילָה שִׁעוּרוֹ כִּגְרוֹגֶרֶת. וְאִם לִבְהֵמָה שִׁעוּרוֹ כִּמְלוֹא פִּי גְּדִי. וְאִם לְהַסָּקָה שִׁעוּרוֹ כְּדֵי לְבַשֵּׁל בֵּיצָה. הַמְעַמֵּר אֳכָלִין אִם לַאֲכִילָה שִׁעוּרוֹ כִּגְרוֹגֶרֶת. וְאִם עִמֵּר לִבְהֵמָה שִׁעוּרוֹ כִּמְלוֹא פִּי גְּדִי. וְאִם לְהַסָּקָה שִׁעוּרוֹ כְּדֵי לְבַשֵּׁל בֵּיצָה. וּבֵיצָה הָאֲמוּרָה בְּכָל מָקוֹם הִיא בֵּיצָה בֵּינוֹנִית שֶׁל תַּרְנְגוֹלִין. וְכָל מָקוֹם שֶׁנֶּאֱמַר כְּדֵי לְבַשֵּׁל בֵּיצָה הוּא כְּדֵי לְבַשֵּׁל כִּגְרוֹגֶרֶת מִבֵּיצָה וּגְרוֹגֶרֶת אֶחָד מִשְּׁלֹשָׁה בְּבֵיצָה. וְאֵין עִמּוּר אֶלָּא בְּגִדּוּלֵי קַרְקַע:","הַמְקַבֵּץ דְּבֵלָה וְעָשָׂה מִמֶּנָּה עִגּוּלָה אוֹ שֶׁנִּקֵּב תְּאֵנִים וְהִכְנִיס הַחֶבֶל בָּהֶן עַד שֶׁנִּתְקַבְּצוּ גּוּף אֶחָד. הֲרֵי זֶה תּוֹלֶדֶת מְעַמֵּר וְחַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַדָּשׁ כִּגְרוֹגֶרֶת חַיָּב וְאֵין דִּישָׁה אֶלָּא בְּגִדּוּלֵי קַרְקַע. וְהַמְפָרֵק הֲרֵי הִיא תּוֹלֶדֶת הַדָּשׁ וְחַיָּב וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. הַחוֹלֵב אֶת הַבְּהֵמָה חַיָּב מִשּׁוּם מְפָרֵק וְכֵן הַחוֹבֵל בְּחַי שֶׁיֵּשׁ לוֹ עוֹר חַיָּב מִשּׁוּם מְפָרֵק. וְהוּא שֶׁיִּהְיֶה צָרִיךְ לַדָּם שֶׁיֵּצֵא מִן הַחַבּוּרָה. אֲבָל אִם נִתְכַּוֵּן לְהַזִּיק בִּלְבַד פָּטוּר מִפְּנֵי שֶׁהוּא מְקַלְקֵל. וְאֵינוֹ חַיָּב עַד שֶׁיִּהְיֶה בַּדָּם אוֹ בַּחָלָב שֶׁהוֹצִיא כִּגְרוֹגֶרֶת:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּחוֹבֵל בִּבְהֵמָה וְחַיָּה וְעוֹף וְכַיּוֹצֵא בָּהֶם. אֲבָל הַחוֹבֵל בַּחֲבֵרוֹ אַף עַל פִּי שֶׁנִּתְכַּוֵּן לְהַזִּיק חַיָּב מִפְּנֵי נַחַת רוּחוֹ שֶׁהֲרֵי נִתְקָרְרָה דַּעְתּוֹ וְשָׁכְכָה חֲמָתוֹ וַהֲרֵי הוּא כִּמְתַקֵּן. וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לַדָּם שֶׁהוֹצִיא מִמֶּנּוּ חַיָּב:","שְׁמוֹנָה שְׁרָצִים הָאֲמוּרִים בַּתּוֹרָה הֵן שֶׁיֵּשׁ לָהֶן עוֹרוֹת לְעִנְיַן שַׁבָּת כְּמוֹ חַיָּה וּבְהֵמָה וְעוֹף. אֲבָל שְׁאָר שְׁקָצִים וּרְמָשִׂים אֵין לָהֶן עוֹר. לְפִיכָךְ הַחוֹבֵל בָּהֶן פָּטוּר. וְאֶחָד הַחוֹבֵל בִּבְהֵמָה חַיָּה וְעוֹף אוֹ בִּשְׁמוֹנָה שְׁרָצִים וְעָשָׂה בָּהֶן חַבּוּרָה וְיָצָא מֵהֶם דָּם אוֹ שֶׁנִּצְרַר הַדָּם אַף עַל פִּי שֶׁלֹּא יָצָא חַיָּב:","הַסּוֹחֵט אֶת הַפֵּרוֹת לְהוֹצִיא מֵימֵיהֶן חַיָּב מִשּׁוּם מְפָרֵק. וְאֵינוֹ חַיָּב עַד שֶׁיִּהְיֶה בַּמַּשְׁקִין שֶׁסָּחַט כִּגְרוֹגֶרֶת. וְאֵין חַיָּבִים מִן הַתּוֹרָה אֶלָּא עַל דְּרִיכַת זֵיתִים וַעֲנָבִים בִּלְבַד. וּמֻתָּר לִסְחֹט אֶשְׁכּוֹל שֶׁל עֲנָבִים לְתוֹךְ הָאֹכֶל. שֶׁמַּשְׁקֶה הַבָּא לְאֹכֶל אֹכֶל הוּא וְנִמְצָא כִּמְפָרֵק אֹכֶל מֵאֹכֶל. אֲבָל אִם סָחַט לִכְלִי שֶׁאֵין בּוֹ אֹכֶל הֲרֵי זֶה דּוֹרֵךְ וְחַיָּב. וְהַחוֹלֵב לְתוֹךְ הָאֹכֶל אוֹ הַיּוֹנֵק בְּפִיו פָּטוּר וְאֵינוֹ חַיָּב עַד שֶׁיַּחֲלֹב לְתוֹךְ הַכְּלִי:","הַזּוֹרֶה אוֹ הַבּוֹרֵר כִּגְרוֹגֶרֶת חַיָּב. וְהַמְחַבֵּץ הֲרֵי הוּא תּוֹלֶדֶת בּוֹרֵר. וְכֵן הַבּוֹרֵר שְׁמָרִים מִתּוֹךְ הַמַּשְׁקִין הֲרֵי זֶה תּוֹלֶדֶת בּוֹרֵר אוֹ תּוֹלֶדֶת מְרַקֵּד וְחַיָּב. שֶׁהַזּוֹרֶה וְהַבּוֹרֵר וְהַמְרַקֵּד דּוֹמִין עִנְיְנֵיהֶם זֶה לָזֶה. וּמִפְּנֵי מָה מָנוּ אוֹתָן בִּשְׁלֹשָׁה מִפְּנֵי שֶׁכָּל מְלָאכָה שֶׁהָיְתָה בַּמִּשְׁכָּן מוֹנִין אוֹתָהּ בִּפְנֵי עַצְמָהּ:","הַבּוֹרֵר אֹכֶל מִתּוֹךְ פְּסלֶת אוֹ שֶׁהָיוּ לְפָנָיו שְׁנֵי מִינֵי אֳכָלִין וּבֵרֵר מִין מִמִּין אַחֵר בְּנָפָה וּבִכְבָרָה חַיָּב. בְּקָנוֹן אוֹ בְּתַמְחוּי פָּטוּר. וְאִם בֵּרֵר בְּיָדוֹ לֶאֱכל לְאַלְתַּר מֻתָּר:","וְהַבּוֹרֵר פְּסלֶת מִתּוֹךְ הָאֹכֶל וַאֲפִלּוּ בְּיָדוֹ אַחַת חַיָּב. וְהַבּוֹרֵר תֻּרְמוֹסִין מִתּוֹךְ פְּסלֶת שֶׁלָּהֶן חַיָּב מִפְּנֵי שֶׁהַפְּסלֶת שֶׁלָּהֶן מְמַתֶּקֶת אוֹתָן כְּשֶׁיִּשְׁלְקוּ אוֹתָן עִמָּהֶם וְנִמְצָא כְּבוֹרֵר פְּסלֶת מִתּוֹךְ אֹכֶל וְחַיָּב. הַבּוֹרֵר אֹכֶל מִתּוֹךְ פְּסלֶת בְּיָדוֹ לְהַנִּיחוֹ אֲפִלּוּ לְבוֹ בַּיּוֹם נַעֲשָׂה כְּבוֹרֵר לָאוֹצָר וְחַיָּב. הָיוּ לְפָנָיו שְׁנֵי מִינֵי אֳכָלִין מְעֹרָבִין בּוֹרֵר אֶחָד מֵאַחֵר וּמַנִּיחַ לֶאֱכל מִיָּד. וְאִם בֵּרֵר וְהִנִּיחַ לְאַחַר זְמַן אֲפִלּוּ לְבוֹ בַּיּוֹם כְּגוֹן שֶׁבֵּרֵר בְּשַׁחֲרִית לֶאֱכל בֵּין הָעַרְבַּיִם חַיָּב:","המְשַׁמֵּר יַיִן אוֹ שֶׁמֶן אוֹ מַיִם וְכֵן שְׁאָר הַמַּשְׁקִין בַּמְּשַׁמֶּרֶת שֶׁלָּהֶן חַיָּב. וְהוּא שֶׁיְּשַׁמֵּר כִּגְרוֹגֶרֶת. אֲבָל מְסַנְּנִין יַיִן שֶׁאֵין בּוֹ שְׁמָרִים אוֹ מַיִם צְלוּלִין בְּסוּדָרִין וּבִכְפִיפָה מִצְרִית כְּדֵי שֶׁיְּהֵא צָלוּל בְּיוֹתֵר. וְנוֹתְנִין מַיִם עַל גַּבֵּי שְׁמָרִים בִּשְׁבִיל שֶׁיִּצּוֹלוּ. וְנוֹתְנִין בֵּיצָה טְרוּפָה לִמְסַנֶּנֶת שֶׁל חַרְדָּל כְּדֵי שֶׁיִּצָּלֵל. חַרְדָּל שֶׁלָּשׁוֹ מֵעֶרֶב שַׁבָּת. לְמָחָר מְמַחֶה וְשׁוֹתֶה בֵּין בַּיָּד בֵּין בִּכְלִי. וְכֵן יַיִן מִגִּתּוֹ כָּל זְמַן שֶׁהוּא תּוֹסֵס טוֹרֵף חָבִית בִּשְׁמָרֶיהָ וְנוֹתֵן לְתוֹךְ הַסּוּדָרִין. שֶׁעֲדַיִן לֹא נִפְרְשׁוּ הַשְּׁמָרִים מִן הַיַּיִן יָפֶה יָפֶה וְכָל הַיַּיִן כְּגוּף אֶחָד הוּא. וְכֵן הַחַרְדָּל וְכָל כַּיּוֹצֵא בּוֹ:","הַטּוֹחֵן כִּגְרוֹגֶרֶת חַיָּב. וְכָל הַשּׁוֹחֵק תַּבְלִין וְסַמָּנִין בְּמַכְתֶּשֶׁת הֲרֵי זֶה טוֹחֵן וְחַיָּב. הַמְחַתֵּךְ יָרָק תָּלוּשׁ הֲרֵי זֶה תּוֹלֶדֶת טוֹחֵן. וְכֵן הַנּוֹסֵר עֵצִים לֵהָנוֹת בִּנְסֹרֶת שֶׁלָּהֶן אוֹ הַשָּׁף לָשׁוֹן שֶׁל מַתֶּכֶת חַיָּב מִשֶּׁיָּשׁוּף כָּל שֶׁהוּא. אֲבָל הַמְחַתֵּךְ עֵצִים אֵינוֹ חַיָּב עַד שֶׁיְּדַקְדֵּק מֵהֶן כְּדֵי לְבַשֵּׁל כִּגְרוֹגֶרֶת מִבֵּיצָה:","הַמְרַקֵּד כִּגְרוֹגֶרֶת חַיָּב. הַלָּשׁ כִּגְרוֹגֶרֶת חַיָּב הַמְגַבֵּל אֶת הֶעָפָר הֲרֵי זֶה תּוֹלֶדֶת לָשׁ. וְכַמָּה שִׁעוּרוֹ כְּדֵי לַעֲשׂוֹת פִּי כּוּר שֶׁל צוֹרְפֵי זָהָב. וְאֵין גִּבּוּל בְּאֵפֶר וְלֹא בְּחוֹל הַגַּס וְלֹא בְּמֻרְסָן וְלֹא בְּכַיּוֹצֵא בָּהֶן. וְהַנּוֹתֵן זֶרַע שֻׁמְשְׁמִין אוֹ זֶרַע פִּשְׁתָּן וְכַיּוֹצֵא בָּהֶן בְּמַיִם חַיָּב מִשּׁוּם לָשׁ. מִפְּנֵי שֶׁהֵן מִתְעָרְבִין וְנִתְלִין זֶה בָּזֶה:"],"Mishneh Torah, Sabbatical Year and the Jubilee 7":["פֵּרוֹת שְׁבִיעִית אֵין אוֹכְלִין מֵהֶן אֶלָּא כָּל זְמַן שֶׁאוֹתוֹ הַמִּין מָצוּי בַּשָּׂדֶה שֶׁנֶּאֱמַר (ויקרא כה ז) \"וְלִבְהֶמְתְּךָ וְלַחַיָּה אֲשֶׁר בְּאַרְצֶךָ תִּהְיֶה כָל תְּבוּאָתָהּ לֶאֱכל\". כָּל זְמַן שֶׁחַיָּה אוֹכֶלֶת מִמִּין זֶה מִן הַשָּׂדֶה אַתָּה אוֹכֵל מִמַּה שֶּׁבַּבַּיִת. כָּלָה לַחַיָּה מִן הַשָּׂדֶה חַיָּב לְבַעֵר אוֹתוֹ הַמִּין מִן הַבַּיִת וְזֶהוּ בִּעוּר שֶׁל פֵּרוֹת שְׁבִיעִית:","כֵּיצַד. הֲרֵי שֶׁהָיוּ לוֹ גְּרוֹגָרוֹת שְׁבִיעִית בְּתוֹךְ בֵּיתוֹ אוֹכֵל מֵהֶן כָּל זְמַן שֶׁהַתְּאֵנִים בָּאִילָנוֹת בַּשָּׂדֶה. כָּלוּ הַתְּאֵנִים מִן הַשָּׂדֶה אָסוּר לֶאֱכל מֵאוֹתָן שֶׁבַּבַּיִת אֶלָּא מְבַעֵר אוֹתָן:","הָיוּ לוֹ פֵּרוֹת מְרֻבִּין מְחַלְּקָן מְזוֹן שָׁלֹשׁ סְעֻדּוֹת לְכָל אֶחָד וְאֶחָד. וְאָסוּר לֶאֱכל אַחַר הַבִּעוּר בֵּין לַעֲנִיִּים בֵּין לַעֲשִׁירִים. וְאִם לֹא מָצָא אוֹכְלִין בִּשְׁעַת הַבִּעוּר שׂוֹרֵף בָּאֵשׁ אוֹ מַשְׁלִיךְ לְיָם הַמֶּלַח וּמְאַבְּדָן לְכָל דָּבָר שֶׁמְּאַבֵּד:","הָיוּ לוֹ צִמּוּקִין שֶׁל שְׁבִיעִית. וְכָלוּ הָעֲנָבִים מִן הַשָּׂדֶה מִן הַגַּגּוֹת וְהַפַּרְדֵּסִים שֶׁהֵן הֶפְקֵר. אַף עַל פִּי שֶׁעֲדַיִן יֵשׁ עֲנָבִים בַּגְּפָנִים שֶׁבְּתוֹךְ הַחֲצֵרוֹת אֵינוֹ אוֹכֵל מִן הַצִּמּוּקִין מִפְּנֵי עֲנָבִים אֵלּוּ שֶׁבְּחָצֵר. לְפִי שֶׁאֵינָן מְצוּיִין לַחַיָּה. אֲבָל אִם יֵשׁ עֲנָבִים קָשִׁים בְּיוֹתֵר שֶׁאֵינָן נִגְמָרִין אֶלָּא בְּסוֹף הַשָּׁנָה הֲרֵי זֶה אוֹכֵל מִן הַצִּמּוּקִין בִּשְׁבִילָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אִילָן שֶׁעוֹשֶׂה פֵּרוֹת שְׁתֵּי פְּעָמִים בְּשָׁנָה וְהָיוּ לוֹ מִפֵּרוֹתָיו הָרִאשׁוֹנוֹת הֲרֵי זֶה אוֹכֵל מֵהֶן כָּל זְמַן שֶׁפֵּרוֹת שְׁנִיּוֹת מְצוּיוֹת בַּשָּׂדֶה. שֶׁהֲרֵי מֵאוֹתוֹ הַמִּין בַּשָּׂדֶה. אֲבָל פֵּרוֹת הַסְּתָו אֵין אוֹכְלִים בִּשְׁבִילָן. מִפְּנֵי שֶׁדּוֹמִין לַפֵּרוֹת שֶׁל שָׁנָה אַחֶרֶת:","הַכּוֹבֵשׁ שְׁלֹשָׁה כְּבָשִׁים בְּחָבִית אַחַת. כָּל שֶׁכָּלָה מִינוֹ מִן הַשָּׂדֶה יְבָעֵר מִינוֹ מִן הֶחָבִית. וְאִם הִתְחִיל בָּהּ הֲרֵי הַכּל כִּמְבֹעָר. וּכְשֵׁם שֶׁמְּבַעֵר אָכֳלֵי אָדָם כָּךְ מְבַעֵר אָכֳלֵי בְּהֵמָה מִן הַבַּיִת. וְאֵינוֹ מַאֲכִילָן לִבְהֵמָה אִם כָּלָה אוֹתוֹ הַמִּין מִן הַשָּׂדֶה:","וּכְשֵׁם שֶׁמְּבַעֲרִין אֶת הַפֵּרוֹת כָּךְ מְבַעֲרִין אֶת הַדָּמִים. כֵּיצַד. הֲרֵי שֶׁמָּכַר רִמּוֹנִים שֶׁל שְׁבִיעִית וַהֲרֵי הוּא אוֹכֵל בִּדְמֵיהֶן. וְכָלוּ הָרִמּוֹנִים מִן הָאִילָנוֹת שֶׁבַּשָּׂדֶה וְנִשְׁאַר אֶצְלוֹ מִן הַדָּמִים שֶׁמָּכַר בָּהֶן חַיָּב לְבַעֲרָן:","כֵּיצַד עוֹשֶׂה. קוֹנֶה בָּהֶן. מַאֲכָלוֹת וּמְחַלְּקָן מְזוֹן שָׁלֹשׁ סְעֻדּוֹת לְכָל אֶחָד וְאֶחָד. אוֹ יַשְׁלִיכֵם לְיָם הַמֶּלַח אִם לֹא מָצָא אוֹכְלִין:","שָׁלֹשׁ אֲרָצוֹת לְבִעוּר. אֶרֶץ יְהוּדָה כֻּלָּהּ הָהָר וְהַשְּׁפֵלָה וְהָעֵמֶק אֶרֶץ אַחַת. עֵבֶר הַיַּרְדֵּן כֻּלּוֹ שִׁפְלַת לוּד וְהַר שִׁפְלַת לוּד וּמִבֵּית חוֹרוֹן עִם הַיָּם אֶרֶץ אַחַת. וְהַגָּלִיל כֻּלּוֹ הָעֶלְיוֹן וְהַתַּחְתּוֹן וּתְחוּם טְבֶרְיָא אֶרֶץ אַחַת. וְאוֹכְלִין בְּכָל אַחַת וְאַחַת מִשְּׁלָשְׁתָּן עַד שֶׁיִּכְלֶה הָאַחֲרוֹן שֶׁבָּהּ:","כֵּיצַד. הָיוּ לוֹ פֵּרוֹת בְּאֶרֶץ יְהוּדָה. אוֹכֵל מֵהֶן כָּל זְמַן שֶׁיֵּשׁ מֵאוֹתוֹ הַמִּין בְּכָל אֶרֶץ יְהוּדָה כֻּלָּהּ. וְכֵן אִם הָיוּ לוֹ פֵּרוֹת גָּלִיל. וְכֵן בְּעֵבֶר הַיַּרְדֵּן:","וְשָׁלֹשׁ אֲרָצוֹת אֵלּוּ כֻּלָּן חֲשׁוּבוֹת כְּאֶרֶץ אַחַת לְחָרוּבִין וּלְזֵיתִים וְלִתְמָרִים. וְאוֹכְלִין בַּתְּמָרִים עַד שֶׁיִּכְלֶה הָאַחֲרוֹן שֶׁבְּצֹעַר. וְאֵימָתַי הוּא כָּלֶה. עַד הַפּוּרִים. וְאוֹכְלִין בְּזֵיתִים עַד הָעֲצֶרֶת. וּבַעֲנָבִים עַד הַפֶּסַח שֶׁל מוֹצָאֵי שְׁבִיעִית. וּבִגְרוֹגְרוֹת עַד הַחֲנֻכָּה:","הַמּוֹלִיךְ פֵּרוֹת שְׁבִיעִית מִמָּקוֹם שֶׁכָּלוּ לְמָקוֹם שֶׁלֹּא כָּלוּ אוֹ מִמָּקוֹם שֶׁלֹּא כָּלוּ לַמָּקוֹם שֶׁכָּלוּ חַיָּב לְבַעֵר. לְפִי שֶׁנּוֹתְנִין עָלָיו חֻמְרֵי מָקוֹם שֶׁיָּצָא מִשָּׁם וְחֻמְרֵי מָקוֹם שֶׁהָלַךְ לְשָׁם. וּפֵרוֹת הָאָרֶץ שֶׁיָּצְאוּ לְחוּצָה לָאָרֶץ מִתְבַּעֲרִים בִּמְקוֹמָן וְלֹא יַעֲבִירֵם מִמָּקוֹם לְמָקוֹם:","כְּלָל גָּדוֹל אָמְרוּ בַּשְּׁבִיעִית כָּל שֶׁהוּא מַאֲכַל אָדָם אוֹ מַאֲכַל בְּהֵמָה אוֹ מִמִּין הַצּוֹבְעִין אִם אֵינוֹ מִתְקַיֵּם בָּאָרֶץ יֵשׁ לוֹ וּלְדָמָיו שְׁבִיעִית וְחַיָּב בְּבִעוּר הוּא וְדָמָיו. כְּגוֹן עֲלֵי הַלּוּף הַשּׁוֹטֶה וַעֲלֵי הַדַּנְדַּנָּה וְהָעֵלְשִׁין מַאֲכַל אָדָם. וּכְגוֹן הַחוֹחִים וְהַדַּרְדָּרִין מַאֲכַל הַבְּהֵמָה. וּכְגוֹן אִסְטִס וְקוֹצָה מִמִּין הַצּוֹבְעִין. וְאִם הָיָה מִתְקַיֵּם בָּאָרֶץ כְּגוֹן הַפּוּאָה וְהַרִכְפָּה מִמִּין הַצּוֹבְעִין אַף עַל פִּי שֶׁיֵּשׁ לוֹ שְׁבִיעִית וּלְדָמָיו שְׁבִיעִית אֵין לָהֶם בִּעוּר וְלֹא לִדְמֵיהֶם שֶׁהֲרֵי מִתְקַיֵּם בָּאָרֶץ אֶלָּא נֶהֱנִין וְצוֹבְעִין בּוֹ עַד רֹאשׁ הַשָּׁנָה:","וְכָל שֶׁאֵינוֹ מְיֻחָד לֹא לְמַאֲכַל אָדָם וְלֹא לְמַאֲכַל בְּהֵמָה וְאֵינוֹ מִמִּין הַצּוֹבְעִים. הוֹאִיל וְאֵינוֹ לְעֵצִים יֵשׁ לוֹ וּלְדָמָיו שְׁבִיעִית. אֲבָל אֵין לָהֶם בִּעוּר אַף עַל פִּי שֶׁאֵינוֹ מִתְקַיֵּם בָּאָרֶץ אֶלָּא נֶהֱנִין בּוֹ אוֹ בְּדָמָיו עַד רֹאשׁ הַשָּׁנָה כְּגוֹן עִקְּרֵי הַלּוּף הַשּׁוֹטֶה וְעִקַּר הַדַּנְדַּנָּה וְהָעַקְרְבָנִין:","קְלִפֵּי רִמּוֹן וְהַנֵּץ שֶׁלּוֹ קְלִפֵּי אֱגוֹזִים וְהַגַּרְעִינִין יֵשׁ לָהֶם שְׁבִיעִית וְלִדְמֵיהֶם שְׁבִיעִית אֲבָל אֵין לָהֶם בִּעוּר וְלֹא לִדְמֵיהֶם. לוּלְבֵי זְרָדִים וְהֶחָרוּבִים יֵשׁ לָהֶם וְלִדְמֵיהֶם שְׁבִיעִית וּבִעוּר. לוּלְבֵי הָאֵלָה וְהַבָּטְנָה וְהָאֲטָדִין יֵשׁ לָהֶן וְלִדְמֵיהֶן שְׁבִיעִית אֲבָל אֵין לָהֶם בִּעוּר. אֲבָל לְעָלִים שֶׁלָּהֶן יֵשׁ בִּעוּר:","אֵיזוֹ הִיא שְׁעַת בִּעוּר הֶעָלִין בְּעֵת שֶׁיִּבּוֹלוּ וְנוֹשְׁרִין מֵאִילָנוֹתֵיהֶן. עֲלֵי זֵיתִים וַעֲלֵי קָנִים וַעֲלֵי חָרוּבִין אֵין לָהֶם בִּעוּר לְפִי שֶׁאֵינָן נוֹבְלוֹת וְכָלוֹת:","וְעַד מָתַי יִהְיֶה אָדָם רַשַּׁאי לִלְקֹט עֲשָׂבִים לַחִין בַּשְּׁבִיעִית עַד שֶׁיִּיבַשׁ הַמָּתוֹק וִיגַבֵּב. עֲשָׂבִים יְבֵשִׁים עַד שֶׁתֵּרֵד רְבִיעָה שְׁנִיָּה בְּמוֹצָאֵי שְׁבִיעִית:","וְעַד מָתַי יִהְיוּ הָעֲנִיִּים מֻתָּרִין לְהִכָּנֵס בְּפַרְדֵּסוֹת בְּמוֹצָאֵי שְׁבִיעִית לְאִסּוּף פֵּרוֹת שְׁבִיעִית. עַד שֶׁתֵּרֵד רְבִיעָה שְׁנִיָּה:","הַוֶּרֶד וְהַכֹּפֶר וְהַלֹּטֶם יֵשׁ לָהֶן וְלִדְמֵיהֶן שְׁבִיעִית. הַקְּטָף וְהוּא שָׂרָף הַיּוֹצֵא מֵהָאִילָנוֹת מִן הֶעָלִים וּמֵהָעִקָּרִים אֵין לוֹ שְׁבִיעִית. וְהַיּוֹצֵא מִן הַפַּגִּים יֵשׁ לוֹ וּלְדָמָיו שְׁבִיעִית:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּאִילַן מַאֲכָל. אֲבָל בְּאִילַן סְרָק אַף הַיּוֹצֵא מִן הֶעָלִין וּמִן הָעִקָּרִים כִּפְרִי שֶׁלָּהֶן וְיֵשׁ לוֹ וּלְדָמָיו שְׁבִיעִית:","הַכּוֹבֵשׁ וֶרֶד שְׁבִיעִית בְּשֶׁמֶן שֶׁל שִׁשִּׁית יְלַקֵּט אֶת הַוֶּרֶד וְהַשֶּׁמֶן מֻתָּר. כְּבָשׁוֹ בְּשֶׁמֶן שֶׁל מוֹצָאֵי שְׁבִיעִית חַיָּב לְבַעֵר הַשֶּׁמֶן שֶׁהֲרֵי הַוֶּרֶד יָבֵשׁ הוּא וּכְבָר נִתְחַיֵּב בְּבִעוּר:","חָרוּבִין שֶׁל שְׁבִיעִית שֶׁכְּבָשָׁן בְּיֵין שִׁשִּׁית אוֹ בְּיֵין מוֹצָאֵי שְׁבִיעִית חַיָּב לְבַעֵר הַיַּיִן. שֶׁהֲרֵי טַעַם פֵּרוֹת שְׁבִיעִית בּוֹ. זֶה הַכְּלָל פֵּרוֹת שְׁבִיעִית שֶׁנִּתְעָרְבוּ בְּפֵרוֹת אֲחֵרוֹת מִין בְּמִינוֹ בְּכָל שֶׁהוּא וְשֶׁלֹּא בְּמִינוֹ בְּנוֹתֵן טָעַם:"],"Mishneh Torah, Sacrifices Rendered Unfit 18":["כָּל הַמְחַשֵּׁב מַחֲשָׁבָה שֶׁאֵינהּ נָכוֹנָה בְּקָדָשִׁים. הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁהֲרֵי הוּא אוֹמֵר (ויקרא ז יח) \"לֹא יֵחָשֵׁב\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁבִּכְלַל דִּין זֶה שֶׁלֹּא יַפְסִיד הַקָּדָשִׁים בְּמַחְשָׁבָה. שֶׁהֲרֵי זֶה דּוֹמֶה לְמַטִּיל מוּם בְּקָדָשִׁים. וְאַף עַל פִּי כֵן אֵינוֹ לוֹקֶה שֶׁאֵין הַמַּחְשָׁבָה מַעֲשֶׂה:","כָּל קָרְבָּן שֶׁנֶּאֱמַר שֶׁהוּא פָּסוּל בֵּין שֶׁנִּפְסַל בְּמַחְשָׁבָה בֵּין בְּמַעֲשֶׂה בֵּין שֶׁאֵרַע בּוֹ דָּבָר שֶׁפְּסָלוֹ. כָּל הָאוֹכֵל מִמֶּנּוּ כְּזַיִת בְּמֵזִיד לוֹקֶה שֶׁנֶּאֱמַר (דברים יד ג) \"לֹא תֹאכַל כָּל תּוֹעֵבָה\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵין הַכָּתוּב מַזְהִיר אֶלָּא עַל פְּסוּלֵי הַמֻּקְדָּשִׁין:","וְכֵן קָדָשִׁים שֶׁהֻטַּל בָּהֶם מוּם. הָאוֹכֵל מֵהֶם כְּזַיִת לוֹקֶה. הֲרֵי הֵם בִּכְלַל (דברים יד ג) \"כָּל תּוֹעֵבָה\" עַד שֶׁיִּוָּלֵד לָהֶם מוּם אַחֵר וְיֵאָכְלוּ בְּמוּמָן כְּמוֹ שֶׁבֵּאַרְנוּ. וְכָל שֶׁפִּסּוּלוֹ מִסָּפֵק אֵין לוֹקִין עָלָיו:","כָּל קָרְבָּן שֶׁנִּתְפַּגֵּל בְּמַחְשֶׁבֶת הַזְּמַן כְּמוֹ שֶׁבֵּאַרְנוּ כָּל הָאוֹכֵל מִמֶּנּוּ כְּזַיִת בְּמֵזִיד חַיָּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא ז יח) \"וְהַנֶּפֶשׁ הָאֹכֶלֶת מִמֶּנּוּ עֲוֹנָהּ תִּשָּׂא\". וְאִם אָכַל מִמֶּנּוּ בִּשְׁגָגָה מֵבִיא חַטָּאת קְבוּעָה:","אֵין חַיָּבִין כָּרֵת אֶלָּא עַל אֲכִילַת דְּבָרִים שֶׁהֻתְּרוּ בֵּין לְאָדָם בֵּין לַמִּזְבֵּחַ. אֲבָל אִם אָכַל מִן הַמַּתִּיר עַצְמוֹ אֵינוֹ חַיָּב כָּרֵת אֶלָּא לוֹקֶה כְּאוֹכֵל פְּסוּלֵי הַמֻּקְדָּשִׁין שֶׁאֵין בָּהֶם פִּגּוּל. כֵּיצַד. מִנְחָה שֶׁנִּתְפַּגְּלָה. הָאוֹכֵל כְּזַיִת מִשְּׁיָרֶיהָ בְּמֵזִיד חַיָּב כָּרֵת. אֲבָל אִם אָכַל מִן הַקֹּמֶץ שֶׁלָּהּ אוֹ מִן הַלְּבוֹנָה אֵינוֹ חַיָּב כָּרֵת. לְפִי שֶׁהֵן הֵן הַמַּתִּירִים אֶת הַשְּׁיָרִים לְאָדָם. וְכֵן זֶבַח שֶׁנִּתְפַּגֵּל. הָאוֹכֵל כְּזַיִת מִבְּשָׂרוֹ אוֹ מֵאֵימוּרָיו אוֹ מִבְּשַׂר הָעוֹלָה חַיָּב כָּרֵת. אֲבָל אִם אָכַל כְּזַיִת מִן הַדָּם אֵינוֹ חַיָּב עָלָיו מִשּׁוּם פִּגּוּל. שֶׁהַדָּם מַתִּיר אֶת הָאֵימוּרִין לִקָּרֵב לַמִּזְבֵּחַ וְהָאֵימוּרִין מַתִּירִין אֶת הַבָּשָׂר לָאָדָם. וְדַם הָעוֹלָה מַתִּיר בְּשָׂרָהּ לַמִּזְבֵּחַ. וְדַם חַטַּאת הָעוֹף מַתִּיר בְּשָׂרָהּ לַכֹּהֲנִים. וְדַם עוֹלַת הָעוֹף מַתִּיר בְּשָׂרָהּ לַמִּזְבֵּחַ. וְדַם חַטָּאוֹת הַנִּשְׂרָפוֹת מַתִּיר אֵימוּרֵיהֶם לַמִּזְבֵּחַ. לְפִיכָךְ חַיָּבִין עַל אֵימוּרֵיהֶן מִשּׁוּם פִּגּוּל. הַקֹּמֶץ וְהַלְּבוֹנָה מַתִּירִין הַשְּׁיָרִים לַכֹּהֲנִים. שְׁנֵי כִּבְשֵׂי עֲצֶרֶת מַתִּירִין שְׁתֵּי הַלֶּחֶם לַכֹּהֲנִים. וְכֵן שְׁנֵי בְּזִיכֵי לְבוֹנָה מַתִּירִין לֶחֶם הַפָּנִים לַכֹּהֲנִים. אֲבָל דְּבָרִים שֶׁאֵין לָהֶם מַתִּירִין כְּגוֹן בְּשַׂר חַטָּאוֹת הַנִּשְׂרָפוֹת וּמְנָחוֹת הַנִּשְׂרָפוֹת אֵינָן מִתְפַּגְּלִין לְעוֹלָם:","וְאֵלּוּ דְּבָרִים שֶׁאֵין חַיָּבִין עֲלֵיהֶן מִשּׁוּם פִּגּוּל לְעוֹלָם. הַקֹּמֶץ. וְהַלְּבוֹנָה. וְהַקְּטֹרֶת. וְהַדָּם. וְהַיַּיִן. בֵּין יַיִן הַבָּא עִם הַנְּסָכִים בֵּין יַיִן הַבָּא בִּפְנֵי עַצְמוֹ. וּמְנָחוֹת הַנִּשְׂרָפוֹת כֻּלָּן שֶׁהֲרֵי אֵין לָהֶם קֹמֶץ לְהַתִּירָן. כְּגוֹן מִנְחַת כֹּהֲנִים וּמִנְחַת נְסָכִים וּבְשַׂר חַטָּאוֹת הַנִּשְׂרָפוֹת. וְלוֹג שֶׁמֶן שֶׁל מְצֹרָע. וְאִם תֹּאמַר וַהֲלֹא דַּם הָאָשָׁם מַתִּירוֹ. אֵינוֹ תָּלוּי בּוֹ שֶׁהֲרֵי אָדָם מֵבִיא אֲשָׁמוֹ הַיּוֹם וְלוֹג אַחַר כַּמָּה יָמִים כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","אָסוּר לְהוֹתִיר מִבְּשַׂר הַקָּדָשִׁים לְאַחַר זְמַן אֲכִילָתָן שֶׁנֶּאֱמַר בְּקָרְבַּן תּוֹדָה (ויקרא כב ל) \"לֹא תוֹתִירוּ מִמֶּנּוּ עַד בֹּקֶר\" וְהוּא הַדִּין לִשְׁאָר הַקָּדָשִׁים כֻּלָּם. וְהַמּוֹתִיר אֵינוֹ לוֹקֶה שֶׁהֲרֵי נִתְּקוֹ הַכָּתוּב לַעֲשֵׂה שֶׁנֶּאֱמַר (שמות יב י) \"וְהַנֹּתָר מִמֶּנּוּ עַד בֹּקֶר בְּאֵשׁ תִּשְׂרֹפוּ\":","הָאוֹכֵל כְּזַיִת מִבְּשַׂר קָדָשִׁים שֶׁנּוֹתַר. בְּמֵזִיד חַיָּב כָּרֵת בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה שֶׁנֶּאֱמַר (ויקרא יט ח) \"וְאֹכְלָיו עֲוֹנוֹ יִשָּׂא כִּי אֶת קֹדֶשׁ ה' חִלֵּל וְנִכְרְתָה\". וּמֵאֵימָתַי יִתְחַיֵּב כָּרֵת עַל אֲכִילַת הַנּוֹתָר. אִם קָדְשֵׁי קָדָשִׁים הֵם חַיָּב עֲלֵיהֶן מֵאַחַר שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. וְאִם קָדָשִׁים קַלִּים הֵם חַיָּב עֲלֵיהֶן מִשְּׁקִיעַת הַחַמָּה שֶׁל יוֹם שֵׁנִי שֶׁהוּא תְּחִלַּת הַלַּיְלָה שֶׁל יוֹם שְׁלִישִׁי. וְהֵיכָן הִזְהִיר הַכָּתוּב עַל הַפִּגּוּל וְעַל הַנּוֹתָר. בַּמִּלּוּאִים. שֶׁהֲרֵי נֶאֱמַר שָׁם (שמות כט לג) \"לֹא יֹאכַל כִּי קֹדֶשׁ הֵם\" לְהַזְהִיר עַל כָּל שֶׁפְּסוּלוֹ בְּקֹדֶשׁ שֶׁהוּא בְּלֹא תַּעֲשֶׂה עַל אֲכִילָתוֹ:","וְהַפִּגּוּל וְהַנּוֹתָר מִצְטָרְפִין זֶה עִם זֶה לִכְזַיִת. וְכָל הַפִּגּוּלִים וְהַנּוֹתָרִין מִצְטָרְפִין:","אָסוּר לְטַמֵּא אֶת הַקָּדָשִׁים אוֹ לְסַבֵּב לָהֶם טֻמְאָה שֶׁהֲרֵי פּוֹסְלָן. וְהַמְטַמֵּא אֶת הַקָּדָשִׁים אֵינוֹ לוֹקֶה. אֲבָל אָדָם טָהוֹר שֶׁאָכַל כְּזַיִת מִקָּדָשִׁים שֶׁנִּטְמְאוּ לוֹקֶה. שֶׁנֶּאֱמַר (ויקרא ז יט) \"וְהַבָּשָׂר אֲשֶׁר יִגַּע בְּכָל טָמֵא לֹא יֵאָכֵל\". וְהוּא הַדִּין לִשְׁאָר הַקָּרְבָּנוֹת שֶׁאִם אָכַל כְּזַיִת מִלְּבוֹנַת הַמִּנְחָה שֶׁנִּטְמְאָה אַחַר שֶׁנִּתְקַדְּשָׁה בִּכְלִי לוֹקֶה. אֶחָד קָדָשִׁים שֶׁנִּטְמְאוּ לִפְנֵי כַּפָּרָה אוֹ לְאַחַר כַּפָּרָה. בֵּין שֶׁנִּטְמְאוּ בְּאַב הַטֻּמְאָה אוֹ בִּוְלַד הַטֻּמְאָה שֶׁל דִּבְרֵי תּוֹרָה. אֲבָל אִם נִטְמְאוּ בְּטֻמְאוֹת שֶׁל דִּבְרֵיהֶם אֵינוֹ לוֹקֶה עַל אֲכִילָתָן. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְאֵינוֹ לוֹקֶה אֶלָּא הָאוֹכֵל אַחַר זְרִיקַת דָּמִים. אֲבָל אִם אָכַל קֹדֶם זְרִיקָה אֵינוֹ לוֹקֶה מִשּׁוּם אוֹכֵל קֹדֶשׁ טָמֵא. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","כָּל אָדָם שֶׁנִּטְמָא טֻמְאָה שֶׁחַיָּבִין עָלֶיהָ כָּרֵת עַל בִּיאַת הַמִּקְדָּשׁ וְאָכַל כְּזַיִת מִן הַקָּדָשִׁים בֵּין בְּקֹדֶשׁ טָהוֹר בֵּין בְּקֹדֶשׁ טָמֵא. בְּמֵזִיד הֲרֵי זֶה נִתְחַיֵּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא ז כ) \"וְהַנֶּפֶשׁ אֲשֶׁר תֹּאכַל מִזֶּבַח הַשְּׁלָמִים אֲשֶׁר לַה' וְטֻמְאָתוֹ עָלָיו וְנִכְרְתָה\". וְאִם אָכַל בִּשְׁגָגָה מֵבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד. וּמִנַּיִן שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּטֻמְאַת הַגּוּף שֶׁנֶּאֱמַר (ויקרא ז כא) \"וְנֶפֶשׁ כִּי תִגַּע בְּכָל טָמֵא בְּטֻמְאַת אָדָם אוֹ בִּבְהֵמָה טְמֵאָה אוֹ בְּכָל שֶׁקֶץ טָמֵא וְאָכַל מִבְּשַׂר זֶבַח הַשְּׁלָמִים אֲשֶׁר לַה' וְנִכְרְתָה\". וְהוּא הַדִּין לִשְׁאָר קָדְשֵׁי מִזְבֵּחַ. וְהֵיכָן הִזְהִיר עַל עָוֹן זֶה בְּיוֹלֶדֶת שֶׁהֲרֵי נֶאֱמַר בָּהּ (ויקרא יב ד) \"בְּכָל קֹדֶשׁ לֹא תִגָּע\":","מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לְטָמֵא שֶׁלֹּא יֹאכַל קֹדֶשׁ קֹדֶם שֶׁיִּטְבּל. וְהָאוֹכֵל קֹדֶשׁ אַחַר שֶׁטָּבַל קֹדֶם שֶׁיֶּעֱרַב שִׁמְשׁוֹ קֹדֶם שֶׁיָּבִיא כַּפָּרָתוֹ לוֹקֶה. וְאֵינוֹ חַיָּב כָּרֵת שֶׁנֶּאֱמַר (ויקרא ז כ) \"וְטֻמְאָתוֹ עָלָיו\" עַד שֶׁתִּהְיֶה כָּל טֻמְאָתוֹ עָלָיו:","הָיָה טָמֵא בְּטֻמְאוֹת שֶׁל דִּבְרֵיהֶם אֵינוֹ לוֹקֶה. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵינוֹ חַיָּב כָּרֵת. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אֵינוֹ חַיָּב כָּרֵת עַל קֹדֶשׁ שֶׁיֵּשׁ לוֹ מַתִּירִין עַד שֶׁיֹּאכַל מִמֶּנּוּ אַחַר שֶׁקָּרְבוּ מַתִּירָיו. אֲבָל אִם אָכַל אֶת הַבָּשָׂר קֹדֶם זְרִיקַת הַדָּם אֵינוֹ לוֹקֶה מִשּׁוּם טָמֵא שֶׁאָכַל אֶת הַקֹּדֶשׁ. זֶה הַכְּלָל כָּל שֶׁיֵּשׁ לוֹ מַתִּירִין אֵין חַיָּבִין עָלָיו מִשּׁוּם פִּגּוּל אוֹ מִשּׁוּם נוֹתָר אוֹ מִשּׁוּם טָמֵא עַד שֶׁיֻּקְרְבוּ מַתִּירָיו כְּהִלְכָתָן. וְכָל שֶׁאֵין לוֹ מַתִּירִין כֵּיוָן שֶׁקָּדַשׁ בִּכְלִי חַיָּבִין עָלָיו מִשּׁוּם טֻמְאָה. אֲפִלּוּ נִטְמָא הַבָּשָׂר קֹדֶם שֶׁיִּטָּמֵא הָאוֹכֵל הוֹאִיל וְקָרְבוּ הַמַּתִּירִין וְאַחַר כָּךְ אָכַל חַיָּב כָּרֵת. וְכֵן אִם אָכַל מִבְּשַׂר חַטָּאוֹת הַנִּשְׂרָפוֹת וְהוּא טָמֵא אַחַר שֶׁנִּזְרַק דָּמָם הֲרֵי זֶה חַיָּב כָּרֵת:","כְּבָר נִתְבָּאֵר לְךָ שֶׁאַף דְּבָרִים שֶׁאֵין חַיָּבִין עֲלֵיהֶן מִשּׁוּם פִּגּוּל חַיָּבִין עֲלֵיהֶן מִשּׁוּם נוֹתָר וְטָמֵא. כֵּיצַד. דְּבָרִים שֶׁאֵין לָהֶם מַתִּירִין אֵין חַיָּבִין עֲלֵיהֶן מִשּׁוּם פִּגּוּל וְחַיָּבִין עֲלֵיהֶם מִשּׁוּם נוֹתָר וְטָמֵא. וְכֵן הַמַּתִּירִין עַצְמָן אַף עַל פִּי שֶׁאֵין חַיָּבִין עֲלֵיהֶם מִשּׁוּם פִּגּוּל כְּמוֹ שֶׁבֵּאַרְנוּ חַיָּבִין עֲלֵיהֶן מִשּׁוּם נוֹתָר וְטָמֵא. חוּץ מִן הַדָּם שֶׁאֵין חַיָּבִין עָלָיו לְעוֹלָם אֶלָּא מִשּׁוּם דָּבָר אֶחָד בִּלְבַד:","טָמֵא שֶׁאָכַל אֵימוּרִין חַיָּב כָּרֵת:","אָכַל פֶּסַח שֶׁלֹּא נִצְלָה. וְלַחְמֵי תּוֹדָה שֶׁלֹּא הוּרְמָה חַלָּתָן. הֲרֵי זֶה חַיָּב כָּרֵת מִשּׁוּם טֻמְאַת הַגּוּף. אַף עַל פִּי שֶׁאֵינָן רְאוּיִין לְמַה שֶּׁהֵן. אִי אֶפְשָׁר שֶׁיִּתְחַיֵּב אָדָם עַל אֲכִילָה אַחַת מִשּׁוּם פִּגּוּל וּמִשּׁוּם נוֹתָר. שֶׁהַפִּגּוּל הוּא הַקָּרְבָּן שֶׁנִּפְסַל בְּמַחְשֶׁבֶת הַזְּמַן וְאֵינוֹ עוֹלֶה לְשֵׁם קָרְבָּן וְלֹא נִרְצָה כְּלָל. וְהַנּוֹתָר הוּא הַנִּשְׁאָר מִקָּרְבָּן שֶׁקָּרֵב כְּמִצְוָתוֹ לְאַחַר זְמַן אֲכִילָתוֹ:","הַפִּגּוּל וְהַנּוֹתָר וְהַטָּמֵא שֶׁבְּלָלָן זֶה בָּזֶה וַאֲכָלָן חַיָּב. אַף עַל פִּי שֶׁרִבָּה מִין עַל חֲבֵרוֹ אֵינוֹ מְבַטְּלוֹ שֶׁאֵין הָאִסּוּרִין מְבַטְּלִין זֶה אֶת זֶה:","וּפִגּוּל אוֹ נוֹתָר אוֹ טָמֵא שֶׁהֶעֱלָן לְרֹאשׁ הַמִּזְבֵּחַ מִשֶּׁמָּשְׁלָה הָאוּר בְּרֻבָּן פָּקַע אִסּוּרָן מֵהֶן. וְהָאֵמוּרִין מִצְטָרְפִין עִם הַבָּשָׂר לִכְזַיִת בֵּין בְּעוֹלָה בֵּין בִּשְׁאָר קָדָשִׁים לְחַיֵּב עָלָיו מִשּׁוּם פִּגּוּל אוֹ נוֹתָר אוֹ טָמֵא:","זֶבַח שֶׁנִּתְפַּגֵּל. אוֹ שֶׁנּוֹתַר לְאַחַר זְמַנּוֹ וְאָכַל מִמֶּנּוּ. מִן הָעוֹר. אוֹ מִן הַמָּרָק. אוֹ מִן הַתַּבְלִין. אוֹ מִן הָאָלָל. אוֹ מִן הַמֻּרְאָה. מִן הַגִּידִים וּמִן הַקַּרְנַיִם וּמִן הַטְּלָפַיִם. מִן הַצִּפָּרְנַיִם מִן הַחַרְטֹם וּמִן הַנּוֹצָה וּמִבֵּיצֵי הָעוֹף. אֵינוֹ חַיָּב כָּרֵת. וְכֵן טְמֵא הַגּוּף שֶׁאָכַל דְּבָרִים אֵלּוּ מִקָּרְבָּן כָּשֵׁר אֵינוֹ חַיָּב כָּרֵת. אֲבָל מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אָכַל מִן הַשָּׁלִיל. אוֹ מִן הַשִּׁלְיָא. חַיָּב מִשּׁוּם פִּגּוּל וְנוֹתָר וְטָמֵא כְּאוֹכֵל מִשְּׁאָר בְּשַׂר הַזֶּבַח:","קָדְשֵׁי עַכּוּ\"ם אֵין חַיָּבִין עֲלֵיהֶם מִשּׁוּם פִּגּוּל וְנוֹתָר וְטָמֵא. וְכֵן דַּם הַקָּדָשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הַלְּבוֹנָה וְהַקְּטֹרֶת וְהָעֵצִים אֵין חַיָּבִין עֲלֵיהֶן כָּרֵת לֹא מִשּׁוּם פִּגּוּל וְלֹא מִשּׁוּם נוֹתָר וְלֹא מִשּׁוּם טֻמְאַת הַגּוּף:"],"Mishneh Torah, Sacrificial Procedure 11":["כָּל הָאוֹכֵל כְּזַיִת מִבְּשַׂר הָעוֹלָה בֵּין לִפְנִי זְרִיקַת דָּמָהּ בֵּין לְאַחַר זְרִיקַת דָּמָהּ לוֹקֶה שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" וְגוֹ' (דברים יב יז) \"וְכָל נְדָרֶיךָ אֲשֶׁר תִּדֹּר\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לְאוֹכֵל בְּשַׂר הָעוֹלָה:","וְחֶלְבָּהּ וּבְשָׂרָהּ וְסָלְתָּהּ וְשַׁמְנָהּ וְיַיִן שֶׁל נְסָכֶיהָ חֲמִשְּׁתָן מִצְטָרְפִין לִכְזַיִת:","וְכֵן הָאוֹכֵל כְּזַיִת מִכָּל הָאֵימוּרִין בֵּין לִפְנֵי זְרִיקָה בֵּין לְאַחַר זְרִיקָה בֵּין כֹּהֵן בֵּין יִשְׂרָאֵל לוֹקֶה. שֶׁהָאֵימוּרִין כָּלִיל לַמִּזְבֵּחַ כְּכָל הָעוֹלָה וַהֲרֵי נֶאֱמַר בְּמִנְחַת כֹּהֲנִים (ויקרא ו טז) \"כָּלִיל תִּהְיֶה לֹא תֵאָכֵל\" כָּל שֶׁהוּא כָּלִיל לַמִּזְבֵּחַ אֲכִילָתוֹ בְּלֹא תַּעֲשֶׂה וְלוֹקִין עָלָיו בִּכְזַיִת. וְכֵן הָאוֹכֵל כְּזַיִת מִבְּשַׂר חַטָּאוֹת הַנִּשְׂרָפוֹת לוֹקֶה שֶׁנֶּאֱמַר (ויקרא ו כג) \"וְכָל חַטָּאת אֲשֶׁר יוּבָא מִדָּמָהּ אֶל אֹהֶל מוֹעֵד\" (ויקרא ו כג) \"לֹא תֵאָכֵל בָּאֵשׁ תִּשָּׂרֵף\":","כָּל הָאוֹכֵל כְּזַיִת מִבְּשַׂר הַקָּדָשִׁים אֲפִלּוּ קָדָשִׁים קַלִּים קֹדֶם זְרִיקַת דָּמָם לוֹקֶה. שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ\" (דברים יב יז) \"וְנִדְבֹתֶיךָ\". כְּלוֹמַר לֹא תוּכַל לֶאֱכל נִדְבוֹתֶיךָ בִּשְׁעָרֶיךָ קֹדֶם שֶׁזּוֹרְקִין דָּמָן בְּשַׁעֲרֵי הַמָּקוֹם. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לְאוֹכֵל תּוֹדָה אוֹ שְׁלָמִים קדֶם זְרִיקַת דָּמִים. וְהוּא הַדִּין לִשְׁאָר קָדָשִׁים בֵּין קַלִּים בֵּין חֲמוּרִים. וְשִׁשָּׁה דְּבָרִים שֶׁבְּתוֹדָה שֶׁהֵם הַחֵלֶב וְהַבָּשָׂר וְהַסּלֶת וְהַשֶּׁמֶן וְהַיַּיִן וְהַלֶּחֶם כֻּלָּן מִצְטָרְפִין לִכְזַיִת:","כָּל הָאוֹכֵל כְּזַיִת מִבְּשַׂר קָדְשֵׁי קָדָשִׁים חוּץ לָעֲזָרָה לוֹקֶה שֶׁנֶּאֱמַר (דברים יב יז) \"לֹא תוּכַל לֶאֱכל בִּשְׁעָרֶיךָ מַעְשַׂר דְּגָנְךָ תִּירשְׁךָ וְיִצְהָרֶךָ וּבְכֹרֹת בְּקָרְךָ וְצֹאנֶךָ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ אַזְהָרָה לְאוֹכֵל מִבְּשַׂר חַטָּאוֹת וַאֲשָׁמוֹת חוּץ לָעֲזָרָה. וְהוּא הַדִּין לְאוֹכֵל קָדָשִׁים קַלִּים חוּץ לִירוּשָׁלַיִם שֶׁהוּא לוֹקֶה. שֶׁחוֹמַת יְרוּשָׁלַיִם לְקָדָשִׁים קַלִּים כְּחוֹמַת הָעֲזָרָה לְקָדְשֵׁי קָדָשִׁים. וְאֶחָד בְּשַׂר חַטָּאת וְאָשָׁם אוֹ שְׁיָרֵי מְנָחוֹת:","בְּשַׂר קָדְשֵׁי קָדָשִׁים שֶׁיָּצָא חוּץ לְחוֹמַת הָעֲזָרָה וּבְשַׂר קָדָשִׁים קַלִּים שֶׁיָּצָא חוּץ לְחוֹמַת יְרוּשָׁלַיִם נִפְסַל וְנֶאֱסַר לְעוֹלָם. וְאַף עַל פִּי שֶׁחָזַר לִמְקוֹמוֹ אָסוּר לְאָכְלוֹ וְהָאוֹכֵל מִמֶּנּוּ כְּזַיִת לוֹקֶה. שֶׁנֶּאֱמַר (שמות כב ל) \"וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ\". כֵּיוָן שֶׁיָּצָא בָּשָׂר חוּץ לִמְחִיצָתוֹ נַעֲשָׂה כִּטְרֵפָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מַאֲכָלוֹת אֲסוּרוֹת:","נִכְנַס בְּשַׂר קָדָשִׁים קַלִּים לַהֵיכָל הֲרֵי זֶה כָּשֵׁר:","זָר שֶׁאָכַל כְּזַיִת מִבְּשַׂר קָדְשֵׁי קָדָשִׁים בָּעֲזָרָה אַחַר זְרִיקַת דָּמִים לוֹקֶה. שֶׁנֶּאֱמַר (שמות כט לג) \"וְאָכְלוּ אֹתָם אֲשֶׁר כֻּפַּר בָּהֶם\" וְגוֹ' (שמות כט לג) \"וְזָר לֹא יֹאכַל\" וְגוֹ'. בְּמָקוֹם שֶׁהַכֹּהֵן אוֹכֵל וּבְעֵת שֶׁרָאוּי לֶאֱכל אִם אֲכָלוֹ שָׁם הַזָּר לוֹקֶה. אֲבָל אִם אָכַל הַזָּר בְּשַׂר קָדְשֵׁי קָדָשִׁים בַּחוּץ לוֹקֶה מִשּׁוּם אוֹכֵל בַּחוּץ לֹא מִשּׁוּם זָר שֶׁאָכַל קֹדֶשׁ. שֶׁהֲרֵי אֵינָם רְאוּיִין שָׁם לַכֹּהֲנִים. וְכֵן אִם אֲכָלָן בָּעֲזָרָה קֹדֶם זְרִיקָה לוֹקֶה מִשּׁוּם אוֹכֵל קֹדֶם זְרִיקָה בִּלְבַד לֹא מִשּׁוּם זָרוּת:","זָר שֶׁאָכַל כְּזַיִת מֵחַטַּאת הָעוֹף לוֹקֶה שְׁתַּיִם. אַחַת מִשּׁוּם זָר שֶׁאָכַל אֶת הַקֹּדֶשׁ. וְאַחַת מִשּׁוּם אוֹכֵל נְבֵלָה. שֶׁכָּל מְלִיקָה נְבֵלָה הִיא וּכְשֶׁהֻתְּרָה לַכֹּהֲנִים הֻתְּרָה לֹא לְזָרִים. וַהֲרֵי הֵן שְׁנֵי אִסּוּרִין הַבָּאִין כְּאֶחָד כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sacrificial Procedure 5":["כְּבָר בֵּאַרְנוּ שֶׁשְּׁחִיטַת הַקָּדָשִׁים כְּשֵׁרָה בְּזָרִים וּמִקַּבָּלַת הַדָּם וְאֵילָךְ מִצְוַת כְּהֻנָּה וְכָל הַזְּבָחִים קִבּוּל דָּמָן בִּכְלִי שָׁרֵת בְּיַד כֹּהֵן. אֲבָל מְקוֹם שְׁחִיטָתָן וּמְקוֹם קִבּוּל דָּמָן אֵינוֹ שָׁוֶה בְּכֻלָּן:","כֵּיצַד. קָדְשֵׁי קָדָשִׁים אֵין שׁוֹחֲטִין אוֹתָן וְאֵין מְקַבְּלִין אֶת דָּמָן אֶלָּא בִּצְפוֹן הַמִּזְבֵּחַ בְּכָל הַמָּקוֹם שֶׁבֵּאַרְנוּ גְּבוּלוֹתָיו בִּתְחִלַּת סֵפֶר זֶה. וְקָדָשִׁים קַלִּים שְׁחִיטָתָן וְקִבּוּל דָּמָן בְּכָל מָקוֹם מִן הָעֲזָרָה:","וּמִנַּיִן שֶׁאֵין שׁוֹחֲטִין קָדְשֵׁי קָדָשִׁים אֶלָּא בַּצָּפוֹן. שֶׁהֲרֵי נֶאֱמַר בְּעוֹלָה (ויקרא א יא) \"וְשָׁחַט אֹתוֹ עַל יֶרֶךְ הַמִּזְבֵּחַ צָפֹנָה\" וּבְחַטָּאת הוּא אוֹמֵר (ויקרא ו יח) \"בִּמְקוֹם אֲשֶׁר תִּשָּׁחֵט הָעלָה תִּשָּׁחֵט הַחַטָּאת\". וּכְשֵׁם שֶׁהַחַטָּאת נִקְרֵאת קֹדֶשׁ קָדָשִׁים כָּךְ הָעוֹלָה נִקְרֵאת קֹדֶשׁ קָדָשִׁים. וּבְאָשָׁם הוּא אוֹמֵר (ויקרא ז ב) \"בִּמְקוֹם אֲשֶׁר יִשְׁחֲטוּ אֶת הָעלָה יִשְׁחֲטוּ אֶת הָאָשָׁם\". וְשַׁלְמֵי צִבּוּר הֻקְּשׁוּ לְחַטָּאת שֶׁנֶּאֱמַר (ויקרא כג יט) \"וַעֲשִׂיתֶם שְׂעִיר עִזִּים אֶחָד לְחַטָּאת וּשְׁנֵי כְבָשִׂים בְּנֵי שָׁנָה לְזֶבַח שְׁלָמִים\" לְפִיכָךְ הֵן קָדְשֵׁי קָדָשִׁים כְּחַטָּאת וְנִשְׁחָטִין בִּמְקוֹם שְׁחִיטָתָהּ. וּמְקוֹם שְׁחִיטָה הוּא מְקוֹם הַקַּבָּלָה:","וּמִנַּיִן שֶׁשּׁוֹחֲטִים קָדָשִׁים קַלִּים בְּכָל הָעֲזָרָה אֲפִלּוּ אֲחוֹרֵי הַהֵיכָל. שֶׁהֲרֵי נֶאֱמַר בִּשְׁלָמִים (ויקרא ג ב) \"וּשְׁחָטוֹ פֶּתַח אֹהֶל מוֹעֵד\" לְהַכְשִׁיר כָּל הָרוּחוֹת שֶׁהֲרֵי לֹא יִחֵד לָהֶם רוּחַ. וְהוּא הַדִּין לִשְׁאָר הַקָּדָשִׁים קַלִּים. וְאִם שְׁחָטָם בַּהֵיכָל כְּשֵׁרִים. אֲבָל אִם שְׁחָטָן בְּגַגּוֹ שֶׁל הֵיכָל פְּסוּלִין שֶׁאֵין הַגַּגּוֹת רְאוּיוֹת לִשְׁחִיטָה כְּלָל אֶלָּא בְּקַרְקַע הָעֲזָרָה:","שְׁלָמִים שֶׁשְּׁחָטָן קֹדֶם שֶׁיִּפָּתְחוּ דַּלְתוֹת הַהֵיכָל פְּסוּלִין שֶׁנֶּאֱמַר (ויקרא ג ב) \"פֶּתַח אֹהֶל מוֹעֵד\" בִּזְמַן שֶׁפָּתוּחַ. אֲפִלּוּ הָיוּ דַּלְתוֹתָיו מֻגָּפוֹת הֲרֵי זֶה כְּנָעוּל. אֲבָל הַפָּרֹכֶת שֶׁעָלָיו אֵינָהּ פּוֹסֶלֶת:","הָעוֹלָה וְהָאָשָׁם וְהַשְּׁלָמִים בֵּין שֶׁל יָחִיד בֵּין שֶׁל צִבּוּר זְרִיקַת דַּם שְׁלָשְׁתָּן עַל גַּבֵּי הַמִּזְבֵּחַ שָׁוָה לְעוֹלָה. וְכֵיצַד הוּא עוֹשֶׂה. כְּשֶׁלּוֹקֵחַ הַכֹּהֵן הַדָּם בַּמִּזְרָק וְזוֹרֵק מִמֶּנּוּ בַּמִּזְרָק שְׁתֵּי זְרִיקוֹת עַל שְׁתֵּי זָוִיּוֹת הַמִּזְבֵּחַ בַּאֲלַכְסוֹן מֵחֲצִי הַמִּזְבֵּחַ וּלְמַטָּה עַל קֶרֶן מִזְרָחִית צְפוֹנִית וְעַל קֶרֶן מַעֲרָבִית דְּרוֹמִית. וּמִתְכַּוֵּן כְּשֶׁיִּזָּרֵק הַדָּם עַל הַקֶּרֶן שֶׁיִּהְיֶה הַדָּם מַקִּיף עַל הַזָּוִיּוֹת כְּמִין גַּ\"ם. כְּדֵי שֶׁיִּמָּצֵא הַדָּם שֶׁל שְׁתֵּי מַתָּנוֹת עַל אַרְבָּעָה כָּתְלֵי הַמִּזְבֵּחַ לְפִי שֶׁנֶּאֱמַר בְּעוֹלָה וּבִשְׁלָמִים (ויקרא ז ב) (ויקרא ט יח) \"סָבִיב\" וְהוּא הַדִּין לְאָשָׁם. וּשְׁיָרֵי הַדָּם נִשְׁפָּכִין עַל הַיְסוֹד הַדְּרוֹמִי:","הַחַטָּאוֹת הַנֶּאֱכָלוֹת דָּמָן טָעוּן אַרְבַּע מַתָּנוֹת עַל אַרְבַּע קַרְנוֹת הַמִּזְבֵּחַ הַחִיצוֹן מֵחֲצִי מִזְבֵּחַ וּלְמַעְלָה לְפִי שֶׁנֶּאֱמַר בָּהּ (ויקרא ד כה) (ויקרא ד לד) \"עַל קַרְנוֹת הַמִּזְבֵּחַ\". וְכֵיצַד הוּא עוֹשֶׂה. כְּשֶׁלּוֹקֵחַ הַכֹּהֵן הַדָּם בַּמִּזְרָק מוֹלִיכוֹ אֵצֶל הַמִּזְבֵּחַ וְטוֹבֵל אֶצְבָּעוֹ הַיְמָנִית הַסְּמוּכָה לַגּוּדָל בְּדָם. וְסוֹמֵךְ בְּאֶצְבָּעוֹ הַגְּדוֹלָה מִכָּאן וּבַגּוּדָל מִכָּאן וּמְחַטֵּא וְיוֹרֵד כְּנֶגֶד חֻדָּהּ שֶׁל קֶרֶן עַד שֶׁיִּכְלֶה כָּל הַדָּם שֶׁבְּאֶצְבָּעוֹ. וְכֵן הוּא עוֹשֶׂה בְּכָל קֶרֶן וְקֶרֶן. וְאִם נָתַן סָמוּךְ לַקֶּרֶן כְּאַמָּה אַחַת מִכָּאן אוֹ מִכָּאן כִּפֵּר:","וְצָרִיךְ לִטְבּל אֶצְבָּעוֹ עַל כָּל קֶרֶן וְקֶרֶן. וּכְשֶׁגּוֹמֵר הַנְּתִינָה עַל הַקֶּרֶן מְקַנֵּחַ אֶצְבָּעוֹ בִּשְׂפַת הַמִּזְרָק. וְאַחַר כָּךְ טוֹבֵל פַּעַם שְׁנִיָּה. שֶׁשְּׁיָרֵי הַדָּם שֶׁבְּאֶצְבָּעוֹ פְּסוּלִין לִתֵּן מֵהֶן עַל קֶרֶן אַחֶרֶת:","אֵין בְּכָל הַקָּרְבָּנוֹת קָרְבָּן שֶׁטָּעוּן הַזָּיַת דָּם בְּאֶצְבָּעוֹ אֶלָּא חַטָּאת בִּלְבַד שֶׁנֶּאֱמַר בָּהּ (ויקרא ט ט) \"וְטָבַל אֶצְבָּעוֹ בַּדָּם\". וְצָרִיךְ שֶׁיִּהְיֶה שָׁם דָּם כְּדֵי טְבִילָה לֹא שֶׁיִּסָּפֵג אֶצְבָּעוֹ מִדָּם:","וּמִנַּיִן הוּא מַתְחִיל. עוֹלֶה בַּכֶּבֶשׁ וּפוֹנֶה לִימִינוֹ וּמְהַלֵּךְ עַל הַסּוֹבֵב וְנוֹתֵן בְּקֶרֶן דְּרוֹמִית מִזְרָחִית תְּחִלָּה. וְאַחַר כָּךְ בַּקֶּרֶן הַשְּׁנִיָּה הַסְּמוּכָה לָהּ שֶׁהִיא מִזְרָחִית צְפוֹנִית. וְאַחַר כָּךְ בְּקֶרֶן שְׁלִישִׁית הַסְּמוּכָה לָהּ שֶׁהִיא צְפוֹנִית מַעֲרָבִית. וְאַחַר כָּךְ בְּקֶרֶן רְבִיעִית הַסְּמוּכָה לָהּ שֶׁהִיא מַעֲרָבִית דְּרוֹמִית. וְעַל יְסוֹד אוֹתָהּ הַקֶּרֶן שֶׁהִשְׁלִים בָּהּ הַמַּתָּנוֹת הוּא שׁוֹפֵךְ שְׁיָרֵי הַדָּם שֶׁנֶּאֱמַר (ויקרא ד יח) \"וְאֵת כָּל הַדָּם יִשְׁפֹּךְ אֶל יְסוֹד מִזְבַּח\" (הָעלָה) זֶה יְסוֹד דְּרוֹמִי:","כָּל הַחַטָּאוֹת הַנִּשְׂרָפוֹת דָּמָם נִכְנָס לְפָנִים לַהֵיכָל וּמַזִּין מִמֶּנּוּ שָׁם כַּאֲשֶׁר מְפֹרָשׁ בַּתּוֹרָה. וּשְׁיָרֵי הַדָּם שׁוֹפְכָן עַל יְסוֹד הַמַּעֲרָבִי שֶׁל מִזְבֵּחַ הַחִיצוֹן שֶׁהוּא פּוֹגֵעַ בּוֹ תְּחִלָּה בְּצֵאתוֹ מִן הַהֵיכָל:","וְהֵיכָן מַזִּין מִדָּמָן. וְכַמָּה מַזֶּה מֵהֶם. פַּר וְשָׂעִיר שֶׁל יוֹם הַכִּפּוּרִים דַּם כָּל אֶחָד מֵהֶן טָעוּן שְׁמוֹנֶה הַזָּיוֹת עַל בֵּין הַבַּדִּים וּשְׁמוֹנֶה עַל הַפָּרֹכֶת. וּמְעָרֵב דַּם הַפָּר וְהַשָּׂעִיר וּמַזֶּה מִשְּׁנֵיהֶם אַרְבַּע הַזָּאוֹת עַל אַרְבַּע קַרְנוֹת מִזְבַּח הַזָּהָב שֶׁבַּהֵיכָל. וְשֶׁבַע הַזָּיוֹת עַל אֶמְצָעוֹ שֶׁל מִזְבֵּחַ זֶה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת עֲבוֹדַת יוֹם הַכִּפּוּרִים. וְאִם לֹא כִּוֵּן בַּהַזָּיוֹת שֶׁבִּפְנִים כְּשֵׁרוֹת:","פָּרִים הַנִּשְׂרָפִין וּשְׂעִירִים הַנִּשְׂרָפִין זוֹרֵק דָּם מִכָּל אֶחָד מֵהֶם שֶׁבַע הַזָּיוֹת עַל הַפָּרֹכֶת הַמַּבְדֶּלֶת בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקָּדָשִׁים. וְאַרְבַּע הַזָּיוֹת עַל אַרְבַּע קַרְנוֹת מִזְבַּח הַזָּהָב:","וְכָל הַדָּמִים הַנִּתָּנִין עַל מִזְבַּח הַזָּהָב כְּשֶׁהוּא נִכְנָס עוֹמֵד בֵּין הַמִּזְבֵּחַ לַמְּנוֹרָה וְהַמִּזְבֵּחַ לְפָנָיו. וְנוֹתֵן עַל קַרְנוֹת הַמִּזְבֵּחַ מִבַּחוּץ. מַתְחִיל מִקֶּרֶן מִזְרָחִית צְפוֹנִית לִצְפוֹנִית מַעֲרָבִית לְמַעֲרָבִית דְּרוֹמִית לִדְרוֹמִית מִזְרָחִית:","פַּר כֹּהֵן מָשִׁיחַ הַבָּא עַל כָּל הַמִּצְוֹת כֹּהֵן הַמָּשִׁיחַ עַצְמוֹ מְקַבֵּל דָּמוֹ וּמַזֶּה מִמֶּנּוּ מִבִּפְנִים וְאִם קִבֵּל וְהִזָּה כֹּהֵן הֶדְיוֹט כָּשֵׁר:","שְׂעִירֵי עֲבוֹדָה זָרָה וְהֵן שְׂעִירִין הַנִּשְׂרָפִין לֹא נִתְפָּרֵשׁ בָּהֶן בַּתּוֹרָה כֵּיצַד נוֹתֵן דָּמָן וּלְהֵיכָן הוּא נוֹתֵן. אֶלָּא לְפִי שֶׁהֵן חַטַּאת הַקָּהָל דִּינָן כְּדִין פַּר הֶעְלֵם שֶׁהוּא חַטַּאת הַקָּהָל לְכָל הָאָמוּר בּוֹ לְמַתַּן דָּמִים וְלִשְׂרֵפָה וּלְטַמֵּא אֶת הַשּׂוֹרֵף:","הַבְּכוֹר וְהַמַּעֲשֵׂר וְהַפֶּסַח דַּם כָּל אֶחָד מֵהֶן טָעוּן מַתָּנָה אַחַת בִּשְׁפִיכָה כְּנֶגֶד הַיְסוֹד בְּאֵי זוֹ רוּחַ שֶׁיִּרְצֶה מִשְּׁלֹשׁ זָוִיּוֹת הַמִּזְבֵּחַ. שֶׁהֲרֵי קֶרֶן מִזְרָחִית דְּרוֹמִית לֹא הָיָה לָהּ יְסוֹד כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִנַּיִן שֶׁאֵינָן טְעוּנִין אֶלָּא מַתָּנָה אַחַת שֶׁהֲרֵי נֶאֱמַר בִּבְכוֹר (במדבר יח יז) \"וְאֶת דָּמָם תִּזְרֹק עַל הַמִּזְבֵּחַ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהוּא הַדִּין בְּמַעֲשֵׂר וּבְפֶסַח שֶׁנּוֹתֵן דָּמָן מַתָּנָה אַחַת כִּבְכוֹר:","כָּל הַזְּבָחִים מַקְטִירִין אֵימוּרֵיהֶן עַל גַּבֵּי הַמִּזְבֵּחַ אַחַר שֶׁזּוֹרְקִין הַדָּם תְּחִלָּה. וְכָל הַזְּבָחִים מַפְשִׁיטִין אוֹתָן וְאַחַר כָּךְ מוֹצִיאִין אֶת אֵימוּרֵיהֶן. וְאֵין מַפְשִׁיטִין אוֹתָן עַד שֶׁיִּזָּרֵק הַדָּם. חוּץ מֵחֲטָאוֹת הַנִּשְׂרָפוֹת שֶׁאֵין מַפְשִׁיטִין אוֹתָם כְּלָל שֶׁנֶּאֱמַר (ויקרא טז כז) \"אֶת עוֹרָם וְאֶת בְּשָׂרָם\". נִמְצֵאתָ אוֹמֵר זוֹרֵק תְּחִלָּה וְאַחַר כָּךְ מַפְשִׁיט וְקוֹרֵעַ וּמוֹצִיא הָאֵימוּרִין וּמַקְטִיר:","כָּל עוֹרוֹת קָדְשֵׁי הַקָּדָשִׁים לַכֹּהֲנִים בֵּין בְּקָרְבְּנוֹת צִבּוּר בֵּין בְּקָרְבְּנוֹת יָחִיד שֶׁנֶּאֱמַר (ויקרא ז ח) \"עוֹר הָעלָה אֲשֶׁר הִקְרִיב\". אֲבָל עוֹרוֹת קָדָשִׁים קַלִּים לַבְּעָלִים. וְכָל עוֹלָה שֶׁלֹּא זָכָה הַמִּזְבֵּחַ בִּבְשָׂרָהּ לֹא זָכוּ הַכֹּהֲנִים בְּעוֹרָהּ שֶׁנֶּאֱמַר (ויקרא ז ח) \"עלַת אִישׁ\" עוֹלָה שֶׁעָלְתָה לְאִישׁ:","כָּל קָדְשֵׁי הַקָּדָשִׁים שֶׁאֵרַע בָּהֶן פִּסּוּל קֹדֶם הֶפְשֵׁטָן אֵין עוֹרוֹתֵיהֶן לַכֹּהֲנִים. לְאַחַר הֶפְשֵׁטָן עוֹרָן לַכֹּהֲנִים. וְכָל הָעוֹרוֹת מְחַלְּקִין אוֹתָן אַנְשֵׁי מִשְׁמָר בֵּינֵיהֶן מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת:","הַמַּתְפִּיס עוֹלָתוֹ לְבֶדֶק הַבַּיִת. וְכֵן הַמַּקְדִּישׁ נְכָסָיו וְהָיוּ בָּהֶן זְכָרִים שֶׁדִּינָן שֶׁיִּקָּרְבוּ עוֹלוֹת אֵין עוֹרוֹתֵיהֶן לַכֹּהֲנִים שֶׁנֶּאֱמַר עלַת אִישׁ פְּרָט לְעוֹלַת הֶקְדֵּשׁ. אֶלָּא יִמָּכְרוּ הָעוֹרוֹת וְיִפְּלוּ לְבֶדֶק הַבַּיִת. אֶחָד (ויקרא ז ח) \"עוֹלַת אִישׁ\" אוֹ אִשָּׁה אוֹ עַכּוּ\"ם אוֹ עֶבֶד עוֹרוֹתֵיהֶן לַכֹּהֲנִים לֹא נֶאֱמַר אִישׁ אֶלָּא לְהוֹצִיא הַהֶקְדֵּשׁ:"],"Mishneh Torah, Sales 16":["הַמּוֹכֵר זֵרְעוֹנֵי גִּנָּה שֶׁאֵין עַצְמָן שֶׁל זֵרְעוֹנִים נֶאֱכָל לַחֲבֵרוֹ וְלֹא צָמְחוּ חַיָּב בְּאַחֲרָיוּתָן וּמַחֲזִיר לוֹ אֶת הַדָּמִים שֶׁלָּקַח מִמֶּנּוּ שֶׁחֶזְקָתָן לִזְרִיעָה. וְהוּא שֶׁלֹּא צָמְחוּ מֵחֲמַת עַצְמָן אֲבָל אִם לָקְתָה הָאָרֶץ בְּבָרָד וְכַיּוֹצֵא בּוֹ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן שֶׁמָּא מֵחֲמַת הַבָּרָד לֹא צָמְחוּ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מָכַר לוֹ זְרָעִים הַנֶּאֱכָלִין כְּגוֹן חִטִּים וּשְׂעוֹרִים וּזְרָעָן וְלֹא צָמְחוּ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן. אֲפִלּוּ הָיָה זֶרַע פִּשְׁתָּן שֶׁרֹב בְּנֵי אָדָם קוֹנִין אוֹתָהּ לִזְרִיעָה. הוֹאִיל וְאוֹכְלִין אוֹתָהּ אֵינוֹ חַיָּב בְּאַחֲרָיוּת זְרִיעָתוֹ. וְאִם הוֹדִיעוֹ שֶׁהוּא קוֹנֶה לְזֶרַע חַיָּב בְּאַחֲרָיוּתָן. וְהוּא הַדִּין לִדְבָרִים הַנִּמְכָּרִים לִרְפוּאָה וְלִצְבִיעָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִכָּאן אַתָּה לָמֵד שֶׁכָּל הַלּוֹקֵחַ מֵחֲבֵרוֹ מִקָּח וְהוֹדִיעוֹ שֶׁהוּא מוֹלִיכוֹ לִמְדִינָה פְּלוֹנִית לְמָכְרוֹ שָׁם וְאַחַר שֶׁהוֹלִיכוֹ לְשָׁם נִמְצָא בּוֹ מוּם. אֵינוֹ יָכוֹל לוֹמַר הַחֲזִיר לִי מִקָּחִי לְכָאן. אֶלָּא מַחְזִיר לוֹ אֶת הַדָּמִים וְהַמּוֹכֵר מְטַפֵּל לְהָבִיא מִמְכָּרוֹ אוֹ לְמָכְרוֹ שָׁם. וַאֲפִלּוּ אָבַד אוֹ נִגְנַב אַחַר שֶׁהוֹדִיעוֹ הֲרֵי הוּא בִּרְשׁוּת מוֹכֵר. אֲבָל אִם לֹא הוֹדִיעוֹ שֶׁמּוֹלִיכוֹ לִמְדִינָה אַחֶרֶת וְהוֹלִיכוֹ וְנִמְצָא שָׁם בּוֹ מוּם הֲרֵי זֶה בִּרְשׁוּת לוֹקֵחַ עַד שֶׁיַּחְזִיר הַמִּקָּח בְּמוּמוֹ לַמּוֹכֵר:","הַלּוֹקֵחַ מִקָּח וְנִמְצָא בּוֹ מוּם וְאַחַר כָּךְ אָבַד אוֹ נִגְנַב הֲרֵי הוּא בִּרְשׁוּת הַלּוֹקֵחַ עַד שֶׁיַּחְזִיר הַמִּקָּח לַמּוֹכֵר. וְאִם הִתְלִיעַ וְנִפְסַד מֵחֲמַת אֹרֶךְ הַזְּמַן הֲרֵי זֶה בִּרְשׁוּת הַמּוֹכֵר. וְאִם הָיָה לוֹ לְהוֹדִיעַ לַמּוֹכֵר וְלֹא הוֹדִיעוֹ הֲרֵי זֶה בִּרְשׁוּת לוֹקֵחַ:","הַמּוֹכֵר שׁוֹר לַחֲבֵרוֹ וְנִמְצָא נַגְחָן יָכוֹל לוֹמַר לוֹ לִשְׁחִיטָה מְכַרְתִּיו לְךָ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה הַלּוֹקֵחַ קוֹנֶה לִשְׁחִיטָה וְלַחֲרִישָׁה. אֲבָל אִם הָיָה יוֹדֵעַ שֶׁהוּא קוֹנֶה לַחֲרִישָׁה בִּלְבַד הֲרֵי זֶה מִקַּח טָעוּת וְחוֹזֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר בְּהֵמָה לַחֲבֵרוֹ לִטְבִיחָה וּשְׁחָטָהּ וְנִמְצֵאת טְרֵפָה. אִם נוֹדַע בְּוַדַּאי שֶׁהָיְתָה טְרֵפָה כְּשֶׁלְּקָחָהּ הֲרֵי זֶה מַחְזִיר לוֹ אֶת הַשְּׁחוּטָה וְיַחְזִיר הַמּוֹכֵר אֶת הַדָּמִים. מִכָּאן אַתָּה לָמֵד שֶׁהַמּוֹכֵר דָּבָר שֶׁהָיָה מוּם בְּמִמְכָּרוֹ וְעָשָׂה בּוֹ הַלּוֹקֵחַ מוּם אַחֵר קֹדֶם שֶׁיִּוָּדַע לוֹ הַמּוּם הָרִאשׁוֹן. אִם עָשָׂה דָּבָר שֶׁדַּרְכּוֹ לַעֲשׂוֹתוֹ כְּגוֹן זֶה שֶׁשָּׁחַט אֶת הַטְּרֵפָה פָּטוּר. וְאִם שָׁנָה וְעָשָׂה מוּם אַחֵר קֹדֶם שֶׁיִּוָּדַע לוֹ הַמּוּם [הָרִאשׁוֹן] מַחְזִיר הַמִּקָּח לִבְעָלָיו וּמְשַׁלֵּם דְּמֵי הַמּוּם שֶׁעָשָׂה:","קָנָה בֶּגֶד וּקְרָעוֹ לַעֲשׂוֹת מִמֶּנּוּ חָלוּק וְאַחַר כָּךְ נוֹדַע הַמּוּם מֵחֲמַת הַקְּרִיעָה מַחְזִיר לוֹ אֶת הַקְּרָעִים. תְּפָרוֹ וְאַחַר כָּךְ נוֹדַע הַמּוּם. אִם הִשְׁבִּיחַ נוֹטֵל שֶׁבַח הַתְּפִירָה מִן הַמּוֹכֵר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר קַרְקַע לַחֲבֵרוֹ וְאָכַל פֵּרוֹתֶיהָ וּלְאַחַר זְמַן נִרְאֶה לוֹ בָּהּ מוּם. אִם רָצָה לְהַחְזִיר קַרְקַע לַבְּעָלִים מַחְזִיר כָּל הַפֵּרוֹת שֶׁאָכַל. וְאִם הָיָה חָצֵר וְדָר בּוֹ צָרִיךְ לְהַעֲלוֹת לוֹ שָׂכָר:","הַמּוֹכֵר דָּבָר שֶׁיֵּשׁ בּוֹ מוּם שֶׁאֵינוֹ נִרְאֶה וְאָבַד הַמִּקָּח מֵחֲמַת אוֹתוֹ הַמּוּם הֲרֵי זֶה מַחְזִיר אֶת הַדָּמִים:","[כֵּיצַד]. הַמּוֹכֵר שׁוֹר לַחֲבֵרוֹ שֶׁאֵין לוֹ טוֹחֲנוֹת וְהִנִּיחוֹ הַלּוֹקֵחַ עִם הַבָּקָר שֶׁלּוֹ וְהָיָה מַנִּיחַ הַמַּאֲכָל לִפְנֵי כֻּלָּן וְאוֹכְלִין וְלֹא הָיָה יוֹדֵעַ שֶׁזֶּה אֵינוֹ אוֹכֵל עַד שֶׁמֵּת בָּרָעָב. הֲרֵי זֶה מַחְזִיר לוֹ אֶת הַנְּבֵלָה וְיַחְזִיר זֶה אֶת הַדָּמִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיָה הַמּוֹכֵר סַרְסוּר שֶׁלּוֹקֵחַ מִזֶּה וּמוֹכֵר לָזֶה וְאֵינוֹ מַשְׁהֶה הַמִּקָּח עִמּוֹ וְלֹא יָדַע בְּמוּם זֶה. הֲרֵי הַסַּרְסוּר נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁלֹּא יָדַע בְּמוּם זֶה וְיִפָּטֵר. מִפְּנֵי שֶׁהָיָה עַל הַלּוֹקֵחַ לִבְדֹּק הַשּׁוֹר בִּפְנֵי עַצְמוֹ וּלְהַחְזִירוֹ לוֹ קֹדֶם שֶׁיָּמוּת וְיִהְיֶה הַסַּרְסוּר מַחְזִירוֹ עַל הַמּוֹכֵר הָרִאשׁוֹן. הוֹאִיל וְלֹא עָשָׂה הוּא הַלּוֹקֵחַ הִפְסִיד עַל עַצְמוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַשּׁוֹחֵט אֶת הַבְּכוֹר וּמְכָרוֹ וְנוֹדַע שֶׁלֹּא הֶרְאָהוּ לְמֻמְחֶה מַה שֶּׁאָכַל אָכַל וְיַחְזִיר לוֹ הַדָּמִים. וְהַנִּשְׁאָר מִן הַבָּשָׂר בְּיַד הַלָּקוֹחוֹת יְקַבֵּל וְיַחְזִיר לָהֶם אֶת הַדָּמִים. וְכֵן הַשּׁוֹחֵט אֶת הַפָּרָה וּמְכָרָהּ וְנוֹדַע שֶׁהִיא טְרֵפָה. מַה שֶּׁאָכַל אָכַל וְיַחְזִיר לוֹ אֶת הַדָּמִים וּמַה שֶּׁלֹּא אָכַל יַחְזִיר אֶת הַבָּשָׂר לַטַּבָּח וְיַחְזִיר לוֹ אֶת הַדָּמִים:","מָכַר הַלּוֹקֵחַ בָּשָׂר זֶה שֶׁל טְרֵפָה לְנָכְרִים. אוֹ שֶׁהֶאֱכִילוֹ לַכְּלָבִים. יְחַשֵּׁב עִם הַטַּבָּח עַל דְּמֵי הַטְּרֵפָה וְיַחְזִיר לוֹ הַטַּבָּח אֶת הַמּוֹתָר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמּוֹכֵר בָּשָׂר לַחֲבֵרוֹ וְנִמְצָא בְּשַׂר בְּכוֹר. פֵּרוֹת וְנִמְצְאוּ טְבָלִים. יַיִן וְנִמְצָא יֵין נֶסֶךְ. מַה שֶּׁאָכַל אָכַל וְיַחְזִיר לוֹ אֶת הַדָּמִים. וְכֵן כָּל הַמּוֹכֵר דָּבָר שֶׁאָסוּר לְאָכְלוֹ מִן הַתּוֹרָה כָּךְ הוּא דִּינוֹ. בֵּין שֶׁהָיָה אִסּוּרוֹ בְּכָרֵת בֵּין שֶׁהָיָה אִסּוּרוֹ בְּלָאו בִּלְבַד. אֲבָל הַמּוֹכֵר דָּבָר לַחֲבֵרוֹ שֶׁאִסּוּר אֲכִילָתוֹ מִדִּבְרֵי סוֹפְרִים. אִם הָיוּ הַפֵּרוֹת קַיָּמִין מַחְזִיר אֶת הַפֵּרוֹת וְנוֹטֵל אֶת דָּמָיו. וְאִם אֲכָלָן אָכַל וְאֵין הַמּוֹכֵר מַחְזִיר לוֹ כְּלוּם. וְכָל אִסּוּרֵי הֲנָיָה בֵּין מִדִּבְרֵי תּוֹרָה בֵּין מִדִּבְרֵיהֶם מַחְזִיר אֶת הַדָּמִים וְאֵין בָּהֶן דִּין מְכִירָה כְּלָל:"],"Mishneh Torah, Sales 27":["הַמּוֹכֵר אֶת הַסְּפִינָה מָכַר אֶת הַתֹּרֶן וְאֶת הַנֵּס וְאֶת הָעֳגָנִים שֶׁלָּהּ וְאֶת כָּל הַמְּשׁוֹטִין הַמַּנְהִיגִין אוֹתָהּ. וְאֶת הַכֶּבֶשׁ וְהָאַסְכָּלָה שֶׁעוֹלִין בָּהֶן לַסְּפִינָה וְיוֹרְדִין עָלֶיהָ. וְאֶת בֵּית הַמַּיִם שֶׁבְּתוֹכָהּ. אֲבָל לֹא מָכַר אֶת הַבִּיצִּית וְהִיא הַסְּפִינָה הַקְּטַנָּה שֶׁהוֹלְכִים בָּהּ עַל הַמַּיִם הַקְּרוֹבִים לַיַּבָּשָׁה. וְלֹא מָכַר הַדּוּגִית וְהִיא הַסְּפִינָה הַקְּטַנָּה שֶׁצָּדִין בָּהּ הַמַּלָּחִים אֶת הַדָּגִים. וְלֹא מָכַר אֶת הָעֲבָדִים הָעוֹשִׂין בָּהֶן. וְלֹא אֶת הַמַּרְצוּפִין. וְלֹא אֶת הַסְּחוֹרָה שֶׁבְּתוֹכָהּ. וּבִזְמַן שֶׁאָמַר לוֹ הִיא וְכָל מַה שֶּׁבְּתוֹכָהּ אֲנִי מוֹכֵר הֲרֵי כֻּלָּן מְכוּרִין:","הַמּוֹכֵר אֶת הַקָּרוֹן לֹא מָכַר אֶת הַפְּרָדוֹת בִּזְמַן שֶׁאֵינָן קְשׁוּרוֹת עִמּוֹ. מָכַר אֶת הַפְּרָדוֹת לֹא מָכַר אֶת הַקָּרוֹן. מָכַר אֶת הַצֶּמֶד לֹא מָכַר אֶת הַבָּקָר. מָכַר אֶת הַבָּקָר לֹא מָכַר אֶת הַצֶּמֶד. וַאֲפִלּוּ בְּמָקוֹם שֶׁקּוֹרִין מִקְצָתָן לְצֶמֶד בָּקָר:","הַמּוֹכֵר אֶת הָעֹל מָכַר אֶת הַפָּרָה. מָכַר אֶת הַפָּרָה לֹא מָכַר אֶת הָעֹל. מָכַר אֶת הַעֲגָלָה מָכַר אֶת הַבָּקָר. מָכַר אֶת הַבָּקָר לֹא מָכַר אֶת הַעֲגָלָה. וְאֵין הַדָּמִים רְאָיָה בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן:","וְכֵן הַמּוֹכֵר אֶת הַחֲמוֹר מָכַר אֶת הַמִּרְדַּעַת וְאֶת הָאֻכָּף אַף עַל פִּי שֶׁאֵינָן עָלָיו. אֲבָל לֹא מָכַר אֶת הַשַּׂק וְלֹא מֶרְכֶּבֶת הַנָּשִׁים וַאֲפִלּוּ הָיוּ עָלָיו בִּשְׁעַת הַמֶּכֶר:","וְאֵין הַדָּמִים רְאָיָה שֶׁאִם טָעָה בִּכְדֵי שֶׁהַדַּעַת טוֹעָה יֵשׁ לוֹ אוֹנָאָה אוֹ בִּטּוּל מִקָּח כְּדִין כָּל הַמּוֹכֵר וְלוֹקֵחַ. וְאִם טָעָה בִּכְדֵי שֶׁאֵין הַדַּעַת טוֹעָה לֹא בָּטַל הַמִּקָּח. שֶׁזֶּה מַתָּנָה נָתַן לוֹ וְאֵין לוֹ אֶלָּא הַחֲמוֹר בְּלֹא שַׂקִּים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה אֵין מְבִיאִין בּוֹ רְאָיָה מִן הַדָּמִים:","הַמּוֹכֵר אֶת הַשִּׁפְחָה מָכַר כֵּלִים שֶׁעָלֶיהָ אֲפִלּוּ הֵם מֵאָה. אֲבָל לֹא מָכַר הַשֵּׁירִים וְלֹא הַנְּזָמִים וְלֹא הַטַּבָּעוֹת וְלֹא אֶת הַקַּטְלָאוֹת שֶׁבְּצַוָּארָהּ. וְאִם אָמַר לוֹ שִׁפְחָה וְכָל מַה שֶּׁעָלֶיהָ הֲרֵי כֻּלָּן מְכוּרִין אַף עַל פִּי שֶׁיֵּשׁ עָלֶיהָ כֵּלִים שֶׁל מֵאָה מָנֶה:","הָאוֹמֵר לַחֲבֵרוֹ שִׁפְחָה מְעֵבֶּרֶת אֲנִי מוֹכֵר לְךָ. פָּרָה מְעֵבֶּרֶת אֲנִי מוֹכֵר לְךָ. מָכַר לוֹ אֶת הַוָּלָד. שִׁפְחָה מֵינִיקָה אֲנִי מוֹכֵר לְךָ. פָּרָה מֵינִיקָה אֲנִי מוֹכֵר לְךָ. לֹא מָכַר לוֹ אֶת הַוָּלָד. חֲמוֹרָה מֵינִיקָה אֲנִי מוֹכֵר לְךָ מָכַר לוֹ אֶת הַסְּיָח שֶׁאֵין אָדָם קוֹנֶה חֲמוֹרָה לַחֲלָבָהּ:","הָאוֹמֵר לַחֲבֵרוֹ רֹאשׁ עֶבֶד זֶה אוֹ רֹאשׁ חֲמוֹר זֶה אֲנִי מוֹכֵר לְךָ הֲרֵי זֶה מָכַר חֶצְיוֹ. וְכֵן הַדִּין בְּכָל אֵיבָר שֶׁהַנְּשָׁמָה תְּלוּיָה בּוֹ. אָמַר לוֹ יַד עֶבֶד זֶה אוֹ יַד חֲמוֹר זֶה אֲנִי מוֹכֵר לְךָ מְשַׁמְּנִין בֵּינֵיהֶם. וְכֵן הַדִּין בְּכָל אֵיבָר שֶׁאֵין הַנְּשָׁמָה תְּלוּיָה בּוֹ. אָמַר לוֹ רֹאשׁ פָּרָה זוֹ אֲנִי מוֹכֵר לְךָ לֹא מָכַר אֶלָּא הָרֹאשׁ בִּלְבַד שֶׁהֲרֵי רֹאשָׁהּ נִמְכֶּרֶת תָּמִיד בַּמִּטְבָּחַיִם:","מָכַר אֶת הָרֹאשׁ בִּבְהֵמָה גַּסָּה לֹא מָכַר אֶת הָרַגְלַיִם. מָכַר אֶת הָרַגְלַיִם לֹא מָכַר אֶת הָרֹאשׁ. מָכַר אֶת הַקָּנֶה לֹא מָכַר אֶת הַכָּבֵד. מָכַר אֶת הַכָּבֵד לֹא מָכַר אֶת הַקָּנֶה. אֲבָל בִּבְהֵמָה דַּקָּה מָכַר אֶת הָרֹאשׁ מָכַר אֶת הָרַגְלַיִם. מָכַר אֶת הָרַגְלַיִם לֹא מָכַר אֶת הָרֹאשׁ. מָכַר אֶת הַקָּנֶה מָכַר אֶת הַכָּבֵד. מָכַר אֶת הַכָּבֵד לֹא מָכַר אֶת הַקָּנֶה:","הַמּוֹכֵר אֶת הַבּוֹר לֹא מָכַר אֶת מֵימָיו. מָכַר אֶת הָאַשְׁפָּה מָכַר אֶת זִבְלָהּ. מָכַר כַּוֶּרֶת מָכַר דְּבוֹרִים. מָכַר שׁוֹבָךְ מָכַר אֶת הַיּוֹנִים:","אַל יָלוֹז מֵעֵינֶיךָ הָעִקָּר הַגָּדוֹל בִּדְבָרִים אֵלּוּ שֶׁהוּא מִנְהַג הַמְּדִינָה וְהַשֵּׁמוֹת הַיְדוּעִים בְּיִחוּד לְכָל דָּבָר וְדָבָר. וּבְמָקוֹם שֶׁאֵין מִנְהָג וְלֹא שֵׁם שֶׁהַכּל אוֹמְרִים לוֹ בְּיִחוּד וְלֹא שִׁתּוּף הוֹלְכִין אַחַר אֵלּוּ הַכְּלָלוֹת שֶׁבֵּאֲרוּ חֲכָמִים כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Sanctification of the New Month 10":["שְׁנַּת הַחַמָּה לְמִי שֶׁהוּא אוֹמֵר שֶׁהִיא פָּחוֹת מֵרְבִיעַ מֵחַכְמֵי יִשְׂרָאֵל. יֵשׁ מִי שֶׁאוֹמֵר שס\"ה יוֹם וְחָמֵשׁ שָׁעוֹת וְתתקצ\"ז חֲלָקִים וּמ\"ח רֶגַע. וְהָרֶגַע אֶחָד מֵע\"ו בְּחֵלֶק. וּלְפִי חֶשְׁבּוֹן זֶה תִּהְיֶה תּוֹסֶפֶת שְׁנַת הַחַמָּה עַל שְׁנַת הַלְּבָנָה י' יָמִים וְכ\"א שָׁעָה וְקכ\"א חֵלֶק וּמ\"ח רֶגַע. סִימָן לָהֶן יכ\"א קכ\"א מ\"ח. וְלֹא תִּמְצָא תּוֹסֶפֶת בְּמַחֲזוֹר שֶׁל י\"ט שָׁנָה כְּלָל אֶלָּא בְּכָל מַחֲזוֹר מֵהֶם יִשְׁלְמוּ שְׁנֵי הַחַמָּה עִם שְׁנֵי הַלְּבָנָה הַפְּשׁוּטוֹת וְהַמְעֵבָּרוֹת:","בֵּין כָּל תְּקוּפָה וּתְקוּפָה לְפִי חֶשְׁבּוֹן זֶה צ\"א יוֹם וְז' שָׁעוֹת וְתקי\"ט חֲלָקִים וְל\"א רֶגַע. סִימָן לָהֶם צ\"א ת\"ק י\"ט ל\"א. וּכְשֶׁתֵּדַע תְּקוּפָה מִן הַתְּקוּפוֹת אֵימָתַי הָיְתָה. תַּחְשֹׁב מֵאוֹתוֹ רֶגַע מִנְיָן זֶה וְתֵדַע תְּקוּפָה שֶׁאַחֲרֶיהָ עַל הַדֶּרֶךְ שֶׁבֵּאַרְנוּ בִּתְקוּפַת הַשָּׁנָה שֶׁהִיא רְבִיעַ:","תְּקוּפַת נִיסָן לְפִי חֶשְׁבּוֹן זֶה הָיְתָה בְּשָׁנָה רִאשׁוֹנָה שֶׁל יְצִירָה קֹדֶם מוֹלַד נִיסָן בְּט' שָׁעוֹת וְתרמ\"ב חֲלָקִים. סִימָן לָהֶם ט' תרמ\"ב. וְכֵן הִיא לְעוֹלָם בְּכָל שָׁנָה רִאשׁוֹנָה שֶׁל כָּל מַחֲזוֹר קֹדֶם מוֹלַד נִיסָן בְּתֵשַׁע שָׁעוֹת וְתרמ\"ב חֲלָקִים:","כְּשֶׁתֵּדַע תְּקוּפַת נִיסָן שֶׁל שָׁנָה רִאשׁוֹנָה מִן הַמַּחֲזוֹר. תַּחְשֹׁב מִמֶּנָּה צ\"א יוֹם וְז' שָׁעוֹת וְתקי\"ט חֲלָקִים וְל\"א רֶגַע לְכָל תְּקוּפָה וּתְקוּפָה עַד סוֹף הַמַּחֲזוֹר:","אִם תִּרְצֶה לֵידַע מָתַי תִּהְיֶה תְּקוּפַת נִיסָן לְפִי חֶשְׁבּוֹן זֶה. תֵּדַע תְּחִלָּה שָׁנִים גְּמוּרוֹת שֶׁעָבְרוּ מִן הַמַּחֲזוֹר. וְתִקַּח לְכָל שָׁנָה מֵהֶן תּוֹסֶפֶת. וְהִיא יכ\"א קכ\"א מ\"ח. וְקַבֵּץ כָּל הָרְגָעִים חֲלָקִים וְכָל הַחֲלָקִים שָׁעוֹת וְכָל הַשָּׁעוֹת יָמִים כְּדֶרֶךְ שֶׁתַּחְשֹׁב בַּמּוֹלָדוֹת. וְתִגְרַע מִן הַכּל הַט' שָׁעוֹת וְתרמ\"ב חֲלָקִים. וְהַנִּשְׁאָר תַּשְׁלִיךְ חָדְשֵׁי לְבָנָה. וְהַנִּשְׁאָר שֶׁאֵין בּוֹ חֹדֶשׁ לְבָנָה תּוֹסִיף אוֹתוֹ עַל מוֹלַד נִיסָן שֶׁל אוֹתָהּ שָׁנָה. וּבְרֶגַע שֶׁיַּגִּיעַ הַמִּנְיָן בּוֹ תִּהְיֶה תְּקוּפַת נִיסָן שֶׁל אוֹתָהּ שָׁנָה:","וְנִרְאִין לִי הַדְּבָרִים שֶׁעַל חֶשְׁבּוֹן תְּקוּפָה זוֹ הָיוּ סוֹמְכִין לְעִנְיַן עִבּוּר הַשָּׁנָה בְּעֵת שֶׁבֵּית דִּין הַגָּדוֹל מָצוּי. שֶׁהָיוּ מְעַבְּרִין מִפְּנֵי הַזְּמַן אוֹ מִפְּנֵי הַצֹּרֶךְ. לְפִי שֶׁחֶשְׁבּוֹן זֶה הוּא הָאֱמֶת יוֹתֵר מִן הָרִאשׁוֹן. וְהוּא קָרוֹב מִן הַדְּבָרִים שֶׁנִּתְבָּאֲרוּ בְּאִצְטַגְנִינוּת יוֹתֵר מִן הַחֶשְׁבּוֹן הָרִאשׁוֹן שֶׁהָיְתָה בּוֹ שְׁנַת הַחַמָּה שס\"ה יוֹם וּרְבִיעַ יוֹם:","וְחֶשְׁבּוֹן שְׁתֵּי תְּקוּפוֹת הָאֵלּוּ שֶׁבֵּאַרְנוּ דַּרְכָּם הַכּל בְּקֵרוּב הוּא וּבְמַהֲלַךְ הַשֶּׁמֶשׁ הָאֶמְצָעִי לֹא בִּמְקוֹמָהּ הָאֲמִתִּי. אֲבָל בִּמְקוֹם הַשֶּׁמֶשׁ הָאֲמִתִּי תִּהְיֶה תְּקוּפַת נִיסָן בִּזְמַנִּים אֵלּוּ בִּכְמוֹ שְׁנֵי יָמִים קֹדֶם שְׁתֵּי הַתְּקוּפוֹת שֶׁיּוֹצְאִין בְּחֶשְׁבּוֹן זֶה. בֵּין בְּחֶשְׁבּוֹן מִי שֶׁחָשַׁב רְבִיעַ יוֹם גָּמוּר בֵּין לְמִי שֶׁמְּחַשֵּׁב לְפָחוֹת מֵרְבִיעַ יוֹם:"],"Mishneh Torah, Sanctification of the New Month 4":["שָׁנָּה מְעֻבֶּרֶת הִיא שָׁנָה שֶׁמּוֹסִיפִין בָּהּ חֹדֶשׁ. וְאֵין מוֹסִיפִין לְעוֹלָם אֶלָּא אֲדָר וְעוֹשִׂין אוֹתָהּ שָׁנָה שְׁנֵי אֲדָרִין אֲדָר רִאשׁוֹן וַאֲדָר שֵׁנִי. וּמִפְּנֵי מָה מוֹסִיפִין חֹדֶשׁ זֶה מִפְּנֵי זְמַן הָאָבִיב כְּדֵי שֶׁיְּהֵא הַפֶּסַח בְּאוֹתוֹ זְמַן שֶׁנֶּאֱמַר (דברים טז א) \"שָׁמוֹר אֶת חֹדֶשׁ הָאָבִיב\" שֶׁיִּהְיֶה חֹדֶשׁ זֶה בִּזְמַן הָאָבִיב. וְלוּלֵא הוֹסָפַת הַחֹדֶשׁ הַזֶּה הַפֶּסַח בָּא פְּעָמִים בִּימוֹת הַחַמָּה וּפְעָמִים בִּימוֹת הַגְּשָׁמִים:","עַל שְׁלֹשָׁה סִימָנִין מְעַבְּרִין אֶת הַשָּׁנָה. עַל הַתְּקוּפָה וְעַל הָאָבִיב וְעַל פֵּרוֹת הָאִילָן. כֵּיצַד. בֵּית דִּין מְחַשְּׁבִין וְיוֹדְעִין אִם תִּהְיֶה תְּקוּפַת נִיסָן בְּשִׁשָּׁה עָשָׂר בְּנִיסָן אוֹ אַחַר זְמַן זֶה מְעַבְּרִין אוֹתָהּ הַשָּׁנָה. וְיַעֲשׂוּ אוֹתוֹ נִיסָן אֲדָר שֵׁנִי כְּדֵי שֶׁיִּהְיֶה הַפֶּסַח בִּזְמַן הָאָבִיב. וְעַל סִימָן זֶה סוֹמְכִין וּמְעַבְּרִין וְאֵין חוֹשְׁשִׁין לְסִימָן אַחֵר:","וְכֵן אִם רָאוּ בֵּית דִּין שֶׁעֲדַיִן לֹא הִגִּיעַ הָאָבִיב אֶלָּא עֲדַיִן אָפֵל הוּא. וְלֹא צָמְחוּ פֵּרוֹת הָאִילָן שֶׁדַּרְכָּן לִצְמֹחַ בִּזְמַן הַפֶּסַח. סוֹמְכִין עַל שְׁנֵי סִימָנִין אֵלּוּ וּמְעַבְּרִין אֶת הַשָּׁנָה. וְאַף עַל פִּי שֶׁהַתְּקוּפָה קֹדֶם לְשִׁשָּׁה עָשָׂר בְּנִיסָן הֲרֵי הֵן מְעַבְּרִין. כְּדֵי שֶׁיִּהְיֶה הָאָבִיב מָצוּי לְהַקְרִיב מִמֶּנּוּ עֹמֶר הַתְּנוּפָה בְּשִׁשָּׁה עָשָׂר בְּנִיסָן. וּכְדֵי שֶׁיִּהְיוּ הַפֵּרוֹת צוֹמְחִין כְּדֶרֶךְ כָּל זְמַן הָאָבִיב:","וְעַל שָׁלֹשׁ אֲרָצוֹת הָיוּ סוֹמְכִין בָּאָבִיב. עַל אֶרֶץ יְהוּדָה וְעַל עֵבֶר הַיַּרְדֵּן וְעַל הַגָּלִיל. וְאִם הִגִּיעַ הָאָבִיב בִּשְׁתֵּי אֲרָצוֹת מֵאֵלּוּ וּבְאַחַת לֹא הִגִּיעַ אֵין מְעַבְּרִין. וְאִם הִגִּיעַ בְּאַחַת מֵהֶן וְלֹא הִגִּיעַ בִּשְׁתַּיִם מְעַבְּרִין אִם עֲדַיִן לֹא צָמְחוּ פֵּרוֹת הָאִילָן. וְאִלּוּ הֵן הַדְּבָרִים שֶׁהֵן הָעִקָּר שֶׁמְּעַבְּרִין בִּשְׁבִילָן כְּדֵי שֶׁיִּהְיוּ הַשָּׁנִים שְׁנֵי חַמָּה:","וְיֵשׁ שָׁם דְּבָרִים אֲחֵרִים שֶׁהָיוּ בֵּית דִּין מְעַבְּרִין בִּשְׁבִילָן מִפְּנֵי הַצֹּרֶךְ. וְאֵלּוּ הֵן. מִפְּנֵי הַדְּרָכִים שֶׁאֵינָן מְתֻקָּנִין וְאֵין הָעָם יְכוֹלִין לַעֲלוֹת מְעַבְּרִין אֶת הַשָּׁנָה עַד שֶׁיִּפָּסְקוּ הַגְּשָׁמִים וִיתַקְּנוּ הַדְּרָכִים. וּמִפְּנֵי הַגְּשָׁרִים שֶׁנֶּהֶרְסוּ וְנִמְצְאוּ הַנְּהָרוֹת מַפְסִיקִין וּמוֹנְעִין אֶת הָעָם וּמִסְתַּכְּנִין בְּעַצְמָן וּמֵתִים מְעַבְּרִין אֶת הַשָּׁנָה עַד שֶׁיְּתַקְּנוּ הַגְּשָׁרִים. וּמִפְּנֵי תַּנּוּרֵי פְּסָחִים שֶׁאָבְדוּ בַּגְּשָׁמִים וְאֵין לָהֶם מָקוֹם לִצְלוֹת אֶת פִּסְחֵיהֶם מְעַבְּרִין אֶת הַשָּׁנָה עַד שֶׁיִּבָּנוּ הַתַּנּוּרִים וְיִיבְשׁוּ. וּמִפְּנֵי גָּלֻיּוֹת יִשְׂרָאֵל שֶׁנֶּעֶקְרוּ מִמְּקוֹמָן וַעֲדַיִן לֹא הִגִּיעוּ לִירוּשָׁלַיִם מְעַבְּרִין אֶת הַשָּׁנָה כְּדֵי שֶׁיִּהְיֶה לָהֶם פְּנַאי לְהַגִּיעַ:","אֲבָל אֵין מְעַבְּרִין אֶת הַשָּׁנָה לֹא מִפְּנֵי הַשֶּׁלֶג וְלֹא מִפְּנֵי הַצִּנָּה וְלֹא מִפְּנֵי גָּלֻיּוֹת יִשְׂרָאֵל שֶׁעֲדַיִן לֹא נֶעֶקְרוּ מִמְּקוֹמָם. וְלֹא מִפְּנֵי הַטֻּמְאָה. כְּגוֹן שֶׁהָיוּ רֹב הַקָּהָל אוֹ רֹב הַכֹּהֲנִים טְמֵאִים אֵין מְעַבְּרִין אֶת הַשָּׁנָה כְּדֵי שֶׁיִּהְיֶה לָהֶם פְּנַאי לִטַּהֵר וְיַעֲשׂוּ בְּטָהֳרָה אֶלָּא יַעֲשׂוּ בְּטֻמְאָה. וְאִם עִבְּרוּ אֶת הַשָּׁנָה מִפְּנֵי הַטֻּמְאָה הֲרֵי זוֹ מְעֻבֶּרֶת:","יֵשׁ דְּבָרִים שֶׁאֵין מְעַבְּרִין בִּשְׁבִילָן כְּלָל אֲבָל עוֹשִׂין אוֹתָן סַעַד לְשָׁנָה שֶׁצְּרִיכָה עִבּוּר מִפְּנֵי הַתְּקוּפָה אוֹ מִפְּנֵי הָאָבִיב וּפֵרוֹת הָאִילָן. וְאֵלּוּ הֵן. מִפְּנֵי הַגְּדָיִים וְהַטְּלָאִים שֶׁעֲדַיִן לֹא נוֹלְדוּ אוֹ שֶׁהֵן מְעַט. ומִפְּנֵי הַגּוֹזָלוֹת שֶׁלֹּא פָּרְחוּ. אֵין מְעַבְּרִין בִּשְׁבִיל אֵלּוּ כְּדֵי שֶׁיִּהְיוּ הַגְּדָיִים וְהַטְּלָאִים מְצוּיִין לִפְסָחִים וְהַגּוֹזָלוֹת מְצוּיִין לִרְאִיָּה אוֹ לְמִי שֶׁנִּתְחַיֵּב בְּקָרְבַּן הָעוֹף. אֲבָל עוֹשִׂין אוֹתָן סַעַד לְשָׁנָה:","כֵּיצַד עוֹשִׂין אוֹתָן סַעַד לְשָׁנָה. אוֹמְרִין שָׁנָה זוֹ צְרִיכָה עִבּוּר מִפְּנֵי הַתְּקוּפָה שֶׁמָּשְׁכָה אוֹ מִפְּנֵי הָאָבִיב וּפֵרוֹת הָאִילָן שֶׁלֹּא הִגִּיעוּ וְעוֹד שֶׁהַגְּדָיִים קְטַנִּים וְהַגּוֹזָלוֹת רַכִּים:","אֵין מְעַבְּרִין אֶת הַשָּׁנָה אֶלָּא בִּמְזֻמָּנִין לָהּ. כֵּיצַד. יֹאמַר רֹאשׁ בֵּית דִּין הַגָּדוֹל לִפְלוֹנִי וּפְלוֹנִי מִן הַסַּנְהֶדְרִין הֱיוּ מְזֻמָּנִין לְמָקוֹם פְּלוֹנִי שֶׁנְּחַשֵּׁב וְנִרְאֶה וְנֵדַע אִם שָׁנָה זוֹ צְרִיכָה עִבּוּר אוֹ אֵינָהּ צְרִיכָה. וְאוֹתָן שֶׁהֻזְמְנוּ בִּלְבַד הֵן שֶׁמְּעַבְּרִין אוֹתָהּ. וּבְכַמָּה מְעַבְּרִין אוֹתָהּ. מַתְחִילִין בִּשְׁלֹשָׁה דַּיָּנִין מִכְּלַל סַנְהֶדְרֵי גְּדוֹלָה מִמִּי שֶּׁסָּמְכוּ אוֹתָן. אָמְרוּ שְׁנַיִם לֹא נֵשֵׁב וְלֹא נִרְאֶה אִם צְרִיכָה עִבּוּר אִם לָאו וְאֶחָד אָמַר נֵשֵׁב וְנִבְדֹּק. בָּטֵל יָחִיד בְּמִעוּטוֹ. אָמְרוּ שְׁנַיִם נֵשֵׁב וְנִרְאֶה וְאֶחָד אוֹמֵר לֹא נֵשֵׁב. מוֹסִיפִין עוֹד שְׁנַיִם מִן הַמְזֻמָּנִים וְנוֹשְׂאִים וְנוֹתְנִין בַּדָּבָר:","שְׁנַיִם אוֹמְרִים צְרִיכָה עִבּוּר וּשְׁלֹשָׁה אוֹמְרִין אֵינָהּ צְרִיכָה. בָּטְלוּ שְׁנַיִם בְּמִעוּטָן. שְׁלֹשָׁה אוֹמְרִין צְרִיכָה עִבּוּר וּשְׁנַיִם אוֹמְרִין אֵינָהּ צְרִיכָה עִבּוּר. מוֹסִיפִין שְׁנַיִם מִן הַמְזֻמָּנִין לָהּ וְנוֹשְׂאִין וְנוֹתְנִין וְגוֹמְרִין בְּשִׁבְעָה. אִם גָּמְרוּ כֻּלָּם לְעַבֵּר אוֹ שֶׁלֹּא לְעַבֵּר עוֹשִׂין כְּמוֹ שֶׁגָּמְרוּ. וְאִם נֶחְלְקוּ הוֹלְכִים אַחַר הָרֹב בֵּין לְעַבֵּר בֵּין שֶׁלֹּא לְעַבֵּר. וְצָרִיךְ שֶׁיְּהֵא רֹאשׁ בֵּית דִּין הַגָּדוֹל שֶׁהוּא רֹאשׁ יְשִׁיבָה שֶׁל אֶחָד וְשִׁבְעִים מִכְּלַל הַשִּׁבְעָה. וְאִם גָּמְרוּ בִּשְׁלֹשָׁה לְעַבֵּר הֲרֵי זוֹ מְעֻבֶּרֶת וְהוּא שֶׁיְּהֵא הַנָּשִׂיא עִמָּהֶן אוֹ שֶׁיִּרְצֶה. וּבְעִבּוּר הַשָּׁנָה מַתְחִילִין מִן הַצַּד. וּלְקִדּוּשׁ הַחֹדֶשׁ מַתְחִילִין מִן הַגָּדוֹל:","אֵין מוֹשִׁיבִין לְעִבּוּר הַשָּׁנָה לֹא מֶלֶךְ וְלֹא כֹּהֵן גָּדוֹל. מֶלֶךְ מִפְּנֵי חֵילוֹתָיו וּמִלְחֲמוֹתָיו שֶׁמָּא דַּעְתּוֹ נוֹטָה בִּשְׁבִילָן לְעַבֵּר אוֹ שֶׁלֹּא לְעַבֵּר. וְכֹהֵן גָּדוֹל מִפְּנֵי הַצִּנָּה שֶׁמָּא לֹא תִּהְיֶה דַּעְתּוֹ נוֹטָה לְעַבֵּר כְּדֵי שֶׁלֹּא יָבֹא תִּשְׁרֵי בִּימֵי הַקֹּר וְהוּא טוֹבֵל בְּיוֹם הַכִּפּוּרִים חָמֵשׁ טְבִילוֹת:","הָיָה רֹאשׁ בֵּית דִּין הַגָּדוֹל וְהוּא הַנִּקְרָא נָשִׂיא בְּדֶרֶךְ רְחוֹקָה אֵין מְעַבְּרִין אוֹתָהּ אֶלָּא עַל תְּנַאי אִם יִרְצֶה הַנָּשִׂיא. בָּא וְרָצָה הֲרֵי זוֹ מְעֻבֶּרֶת. לֹא רָצָה אֵינָהּ מְעֻבֶּרֶת. וְאֵין מְעַבְּרִין אֶת הַשָּׁנָה אֶלָּא בְּאֶרֶץ יְהוּדָה שֶׁהַשְּׁכִינָה בְּתוֹכָהּ שֶׁנֶּאֱמַר (דברים יב ה) \"לְשִׁכְנוֹ תִדְרְשׁוּ\". וְאִם עִבְּרוּהָ בַּגָּלִיל מְעֻבֶּרֶת. וְאֵין מְעַבְּרִין אֶלָּא בַּיּוֹם. וְאִם עִבְּרוּהָ בַּלַּיְלָה אֵינָהּ מְעֻבֶּרֶת:","יֵשׁ לְבֵית דִּין לְחַשֵּׁב וְלִקְבֹּעַ וְלֵידַע אֵי זוֹ שָׁנָה תִּהְיֶה מְעֻבֶּרֶת בְּכָל עֵת שֶׁיִּרְצֶה אֲפִלּוּ לְכַמָּה שָׁנִים. אֲבָל אֵין אוֹמְרִין שָׁנָה פְּלוֹנִית מְעֻבֶּרֶת אֶלָּא אַחַר רֹאשׁ הַשָּׁנָה הוּא שֶׁאוֹמֵר שָׁנָה זוֹ מְעֻבֶּרֶת. וְדָבָר זֶה מִפְּנֵי הַדְּחָק אֲבָל שֶׁלֹּא בִּשְׁעַת הַדְּחָק אֵין מוֹדִיעִין שֶׁהִיא מְעֻבֶּרֶת אֶלָּא בַּאֲדָר הוּא שֶׁאוֹמֵר שָׁנָה זוֹ מְעֻבֶּרֶת וְחֹדֶשׁ הַבָּא אֵינוֹ נִיסָן אֶלָּא אֲדָר שֵׁנִי. אָמְרוּ לִפְנֵי רֹאשׁ הַשָּׁנָה שָׁנָה זוֹ שֶׁתִּכָּנֵס מְעֻבֶּרֶת אֵינָהּ מְעֻבֶּרֶת בַּאֲמִירָה זוֹ:","הִגִּיעַ יוֹם שְׁלֹשִׁים בַּאֲדָר וְלֹא עִבְּרוּ עֲדַיִן הַשָּׁנָה לֹא יְעַבְּרוּ אוֹתָהּ כְּלָל. שֶׁאוֹתוֹ הַיּוֹם רָאוּי לִהְיוֹת רֹאשׁ חֹדֶשׁ נִיסָן וּמִשֶּׁיִּכָּנֵס נִיסָן וְלֹא עִבְּרוּ אֵינָן יְכוֹלִים לְעַבֵּר. וְאִם עִבְּרוּהָ בְּיוֹם שְׁלֹשִׁים שֶׁל אֲדָר הֲרֵי זוֹ מְעֻבֶּרֶת. בָּאוּ עֵדִים אַחַר שֶׁעִבְּרוּ וְהֵעִידוּ עַל הַיָּרֵחַ הֲרֵי אֵלּוּ מְקַדְּשִׁין אֶת הַחֹדֶשׁ בְּיוֹם שְׁלֹשִׁים וְיִהְיֶה רֹאשׁ חֹדֶשׁ אֲדָר שֵׁנִי. וְאִלּוּ קִדְּשׁוּהוּ קֹדֶם שֶׁיְּעַבְּרוּ אֶת הַשָּׁנָה שׁוּב לֹא הָיוּ מְעַבְּרִין שֶׁאֵין מְעַבְּרִין בְּנִיסָן:","אֵין מְעַבְּרִין אֶת הַשָּׁנָה בִּשְׁנַת רְעָבוֹן שֶׁהַכּל רָצִים לְבַיִת הַגְּרָנוֹת לֶאֱכל וְלִחְיוֹת וְאִי אֶפְשָׁר לְהוֹסִיף לָהֶן זְמַן לֶאֱסֹר הֶחָדָשׁ. וְאֵין מְעַבְּרִין בִּשְׁבִיעִית שֶׁיַּד הַכּל שׁוֹלֶטֶת עַל הַסְּפִיחִין וְלֹא יִמְצְאוּ לְקַּרֵב הָעֹמֶר וּשְׁתֵּי הַלֶּחֶם. וּרְגִילִין הָיוּ לְעַבֵּר בְּעֶרֶב שְׁבִיעִית:","יֵרָאֶה לִי שֶׁזֶּה שֶׁאָמְרוּ חֲכָמִים אֵין מְעַבְּרִין בִּשְׁנַת רְעָבוֹן וּבִשְׁבִיעִית. שֶׁלֹּא יְעַבְּרוּ בָּהֶם מִפְּנֵי צֹרֶךְ הַדְּרָכִים וְהַגְּשָׁרִים וְכַיּוֹצֵא בָּהֶם. אֲבָל אִם הָיְתָה הַשָּׁנָה רְאוּיָה לְהִתְעַבֵּר מִפְּנֵי הַתְּקוּפָה אוֹ מִפְּנֵי הָאָבִיב וּפֵרוֹת הָאִילָן מְעַבְּרִין לְעוֹלָם בְּכָל זְמַן:","כְּשֶׁמְּעַבְּרִין בֵּית דִּין אֶת הַשָּׁנָה כּוֹתְבִין אִגְּרוֹת לְכָל הַמְּקוֹמוֹת הָרְחוֹקִים וּמוֹדִיעִים אוֹתָן שֶׁעִבְּרוּהָ וּמִפְּנֵי מָה עִבְּרוּ. וְעַל לְשׁוֹן הַנָּשִׂיא נִכְתָּבוֹת. וְאוֹמֵר לָהֶן יוֹדֵעַ לָכֶם שֶׁהִסְכַּמְתִּי אֲנִי וַחֲבֵרַי וְהוֹסַפְנוּ עַל שָׁנָה זוֹ כָּךְ וְכָךְ. רָצוּ תִּשְׁעָה וְעֶשְׂרִים יוֹם רָצוּ שְׁלֹשִׁים יוֹם. שֶׁחֹדֶשׁ הָעִבּוּר הָרְשׁוּת לְבֵית דִּין לְהוֹסִיפוֹ מָלֵא אוֹ חָסֵר לָאֲנָשִׁים הָרְחוֹקִים שֶׁמּוֹדִיעִין אוֹתָם. אֲבָל הֵם לְפִי הָרְאִיָּה הֵם עוֹשִׂים אִם מָלֵא אִם חָסֵר:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 11":["מִצְוַת עֲשֵׂה לְהִתְוַדּוֹת לִפְני ה' אַחַר שֶׁמּוֹצִיאִין כָּל הַמַּתָּנוֹת שֶׁבְּזֶרַע הָאָרֶץ וְזֶהוּ הַנִּקְרָא וִדּוּי מַעֲשֵׂר:","וְאֵין מִתְוַדִּין וִדּוּי זֶה אֶלָּא אַחַר הַשָּׁנָה שֶׁמַּפְרִישִׁין בָּהּ מַעֲשַׂר עָנִי שֶׁנֶּאֱמַר (דברים כו יב) \"כִּי תְכַלֶּה לַעְשֵׂר\" (דברים כו יג) \"וְאָמַרְתָּ לִפְנֵי ה' אֱלֹהֶיךָ בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת\":","אֵימָתַי מִתְוַדִּין. בְּמִנְחָה בְּיוֹם טוֹב הָאַחֲרוֹן שֶׁל פֶּסַח שֶׁל רְבִיעִית וְשֶׁל שְׁבִיעִית. שֶׁנֶּאֱמַר (דברים כו יב) \"כִּי תְכַלֶּה לַעְשֵׂר\". בְּרֶגֶל שֶׁכָּל הַמַּעַשְׂרוֹת כָּלִים בּוֹ. וְאֵין הַפֶּסַח מַגִּיעַ מִשָּׁנָה רְבִיעִית אֶלָּא כָּל פֵּרוֹת שְׁלִישִׁית נִתְעַשְּׂרוּ בֵּין פֵּרוֹת הָאִילָן בֵּין פֵּרוֹת הָאָרֶץ:","אֵין מִתְוַדִּין אֶלָּא בַּיּוֹם. וְכָל הַיּוֹם כָּשֵׁר לְוִדּוּי הַמַּעֲשֵׂר. וּבֵין בִּפְנֵי הַבַּיִת וּבֵין שֶׁלֹּא בִּפְנֵי הַבַּיִת חַיָּב לְבַעֵר וּלְהִתְוַדּוֹת:","וִדּוּי זֶה נֶאֱמַר בְּכָל לָשׁוֹן שֶׁנֶּאֱמַר (דברים כו יג) \"וְאָמַרְתָּ לִפְנֵי ה' אֱלֹהֶיךָ\" בְּכָל לָשׁוֹן שֶׁאַתָּה אוֹמֵר. וְכָל אֶחָד וְאֶחָד אוֹמְרוֹ בִּפְנֵי עַצְמוֹ. וְאִם רָצוּ רַבִּים לְהִתְוַדּוֹת כְּאֶחָד מִתְוַדִּין:","וּמִצְוָתוֹ בַּמִּקְדָּשׁ שֶׁנֶּאֱמַר (דברים כו יג) \"לִפְנֵי ה'\". וְאִם הִתְוַדָּה בְּכָל מָקוֹם יָצָא:","אֵינוֹ מִתְוַדֶּה עַד שֶׁלֹּא יִשָּׁאֵר אֶצְלוֹ אַחַת מִן הַמַּתָּנוֹת. שֶׁכֵּן הוּא אוֹמֵר בַּוִּדּוּי (דברים כו יג) \"בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת\". וְעֶרֶב יוֹם טוֹב הָאַחֲרוֹן הָיָה הַבִּעוּר וּלְמָחָר מִתְוַדִּין:","כֵּיצַד הוּא עוֹשֶׂה. אִם נִשְׁאָר אֶצְלוֹ תְּרוּמָה וּתְרוּמַת מַעֲשֵׂר נוֹתְנָהּ לַכֹּהֵן. מַעֲשֵׂר רִאשׁוֹן נוֹתְנוֹ לְלֵוִי. מַעֲשַׂר עָנִי נוֹתְנוֹ לָעֲנִיִּים. נִשְׁאֲרוּ אֶצְלוֹ פֵּרוֹת מַעֲשֵׂר שֵׁנִי שֶׁל וַדַּאי אוֹ נֶטַע רְבָעִי אוֹ מְעוֹת פְּדִיָּתָן הֲרֵי זֶה מְבַעֲרָן וּמַשְׁלִיךְ לַיָּם אוֹ שׂוֹרֵף. נִשְׁאָר אֶצְלוֹ מַעֲשֵׂר שֵׁנִי שֶׁל דְּמַאי אֵינוֹ חַיָּב לְבַעֲרוֹ. נִשְׁאָר אֶצְלוֹ בִּכּוּרִים הֲרֵי הֵן מִתְבַּעֲרִין בְּכָל מָקוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁשּׂוֹרֵף וּמְבַעֵר כְּשֶׁנִּשְׁאֲרוּ אֶצְלוֹ פֵּרוֹת שֶׁאֵינוֹ יָכוֹל לֶאֱכל כֻּלָּן קֹדֶם שֶׁיִּכָּנֵס יוֹם טוֹב. אֲבָל אִם נִשְׁאָר תַּבְשִׁיל שֶׁל מַעֲשֵׂר שֵׁנִי וְנֶטַע רְבָעִי אֵינוֹ צָרִיךְ לְבַעֲרוֹ שֶׁהַתַּבְשִׁיל כִּמְבֹעָר. וְכֵן יַיִן וְתַבְלִין הֲרֵי הֵן כִּמְבֹעֲרִין:","פֵּרוֹת שֶׁלֹּא הִגִּיעוּ לְעוֹנַת הַמַּעַשְׂרוֹת בִּשְׁעַת הַבִּעוּר אֵין מְעַכְּבִין אוֹתוֹ לְהִתְוַדּוֹת וְאֵינוֹ חַיָּב לְבַעֲרָן:","מִי שֶׁהָיוּ פֵּרוֹתָיו רְחוֹקִין מִמֶּנּוּ וְהִגִּיעַ יוֹם הַבִּעוּר הֲרֵי זֶה קוֹרֵא שֵׁם לַמַּתָּנוֹת וּמְזַכֶּה לָהֶן לְבַעְלֵיהֶן עַל גַּב קַרְקַע אוֹ לְמִי שֶׁזּוֹכֶה לָהֶן לְבַעֲלֵיהֶן וּמִתְוַדֶּה לְמָחָר. שֶׁנְּתִינַת הַמִּטַּלְטְלִין עַל גַּבֵּי קַרְקַע אֵינָהּ אֶלָּא מַתָּנָה שֶׁיֵּשׁ בָּהּ חִזּוּק. אֲבָל אֵינוֹ יָכוֹל לְהַקְנוֹת לָהֶם הַמַּעֲשֵׂר בַּחֲלִיפִין מִפְּנֵי שֶׁנִּרְאֶה כִּמְכִירָה. וְהַמַּעַשְׂרוֹת וְהַתְּרוּמוֹת וְהַמַּתָּנוֹת נֶאֱמַר בָּהֶן נְתִינָה לֹא מְכִירָה:","וּמִנַּיִן שֶׁאֵינוֹ יָכוֹל לְהִתְוַדּוֹת עַד שֶׁיּוֹצִיא כָּל הַמַּתָּנוֹת שֶׁנֶּאֱמַר (דברים כו יג) \"בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת\". הַקֹּדֶשׁ זֶה מַעֲשֵׂר שֵׁנִי וְנֶטַע רְבָעִי הַקָּרוּי קֹדֶשׁ. מִן הַבַּיִת זוֹ חַלָּה שֶׁהִיא הַמַּתָּנָה שֶׁל כֹּהֲנִים בַּבַּיִת. נְתַתִּיו לַלֵּוִי זֶה מַעֲשֵׂר רִאשׁוֹן. וְגַם נְתַתִּיו מִכְּלָל שֶׁקְּדָמַתּוּ מַתָּנָה אַחֶרֶת וְהִיא תְּרוּמָה גְּדוֹלָה וּתְרוּמַת מַעֲשֵׂר. לַגֵּר לַיָּתוֹם וְלָאַלְמָנָה זֶה מַעֲשַׂר עָנִי וְלֶקֶט שִׁכְחָה וּפֵאָה. אַף עַל פִּי שֶׁאֵין לֶקֶט שִׁכְחָה וּפֵאָה מְעַכְּבִין אֶת הַוִּדּוּי:","וְצָרִיךְ לְהַפְרִישׁ הַמַּתָּנוֹת עַל הַסֵּדֶר וְאַחַר כָּךְ יִתְוַדֶּה שֶׁנֶּאֱמַר (דברים כו יג) \"כְּכָל מִצְוָתְךָ אֲשֶׁר צִוִּיתָנִי\". הָא אִם הִקְדִּים מַעֲשֵׂר שֵׁנִי לְרִאשׁוֹן אֵינוֹ יָכוֹל לְהִתְוַדּוֹת. נִשְׂרַף טִבְלוֹ אֵינוֹ יָכוֹל לְהִתְוַדּוֹת שֶׁהֲרֵי לֹא הִפְרִישׁ מַתָּנוֹת וְלֹא נְתָנָן לְבַעֲלֵיהֶן. וּבִזְמַן שֶׁהָיוּ נוֹתְנִין מַעֲשֵׂר רִאשׁוֹן לַכֹּהֲנִים לֹא הָיוּ מִתְוַדִּין שֶׁנֶּאֱמַר (דברים כו יג) \"וְגַם נְתַתִּיו לַלֵּוִי\":","מִי שֶׁאֵין לוֹ אֶלָּא מַעֲשֵׂר שֵׁנִי בִּלְבַד מִתְוַדֶּה. שֶׁעִקַּר הַוִּדּוּי בַּמַּעֲשֵׂר הוּא. וְכֵן אִם לֹא הָיָה לוֹ אֶלָּא בִּכּוּרִים בִּלְבַד מִתְוַדֶּה שֶׁנֶּאֱמַר (דברים כו יג) \"בִּעַרְתִּי הַקֹּדֶשׁ\". הַקֹּדֶשׁ הָרִאשׁוֹן שֶׁהוּא הַבִּכּוּרִים. אֲבָל מִי שֶׁאֵין לוֹ אֶלָּא תְּרוּמָה בִּפְנֵי עַצְמָהּ אֵינוֹ מִתְוַדֶּה שֶׁאֵין הַתְּרוּמָה טְעוּנָה וִדּוּי אֶלָּא בִּכְלַל שְׁאָר הַמַּתָּנוֹת:","(דברים כו יג) \"לֹא עָבַרְתִּי מִמִּצְוֹתֶיךָ\" שֶׁלֹּא הִפְרִישׁ מִמִּין עַל שֶׁאֵינוֹ מִינוֹ. וְלֹא מִן הַתָּלוּשׁ עַל הַמְחֻבָּר. וְלֹא מִן הַמְחֻבָּר עַל הַתָּלוּשׁ. וְלֹא מִן הֶחָדָשׁ עַל הַיָּשָׁן. וְלֹא מִן הַיָּשָׁן עַל הֶחָדָשׁ. וְלֹא שָׁכַחְתִּי שֶׁלֹּא שָׁכַח מִלְּבָרְכוֹ וּמִלְּהַזְכִּיר שְׁמוֹ עָלָיו. לֹא אָכַלְתִּי בְאֹנִי מִמֶּנּוּ הָא אִם אֲכָלוֹ בַּאֲנִינוֹ אֵינוֹ מִתְוַדֶּה. וְלֹא בִעַרְתִּי מִמֶּנּוּ בְּטָמֵא הָא אִם הִפְרִישׁוֹ בְּטֻמְאָה אֵינוֹ מִתְוַדֶּה. וְלֹא נָתַתִּי מִמֶּנּוּ לְמֵת שֶׁלֹּא לָקַח מִמֶּנּוּ אָרוֹן וְתַכְרִיכִין וְלֹא נְתָנוֹ לְאוֹנְנִים אֲחֵרִים. שָׁמַעְתִּי בְּקוֹל ה' אֱלֹהָי שֶׁהֱבִיאוֹ לְבֵית הַבְּחִירָה. עָשִׂיתִי כְּכָל אֲשֶׁר צִוִּיתָנִי שֶׁשָּׂמַח וְשִׂמֵּחַ בּוֹ שֶׁנֶּאֱמַר (דברים כו יא) \"וְשָׂמַחְתָּ בְכָל הַטּוֹב\":","(דברים כו טו) \"הַשְׁקִיפָה מִמְּעוֹן קָדְשְׁךָ מִן הַשָּׁמַיִם\" עַד (דברים כו טו) \"כַּאֲשֶׁר נִשְׁבַּעְתָּ לַאֲבֹתֵינוּ אֶרֶץ זָבַת חָלָב וּדְבָשׁ\" זוֹ בַּקָּשָׁה שֶׁיִּתֵּן טַעַם בַּפֵּרוֹת:","יִשְׂרָאֵל וּמַמְזֵרִים מִתְוַדִּים. אֲבָל לֹא גֵּרִים וַעֲבָדִים מְשֻׁחְרָרִים מִפְּנֵי שֶׁאֵין לָהֶם חֵלֶק בָּאָרֶץ וַהֲרֵי הוּא אוֹמֵר (דברים כו טו) \"וְאֶת הָאֲדָמָה אֲשֶׁר נָתַתָּ לָנוּ\". כֹּהֲנִים וּלְוִיִּים מִתְוַדִּים שֶׁאַף עַל פִּי שֶׁלֹּא נָטְלוּ חֵלֶק בָּאָרֶץ יֵשׁ לָהֶם עָרֵי מִגְרָשׁ: סְלִיקוּ לְהוּ הִלְכוֹת מַעֲשֵׂר שֵׁנִי וְנֶטַע רְבָעִי בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Service on the Day of Atonement 4":["סֵדֶר כָּל הַמַּעֲשִׂים שֶׁבְּיוֹם זֶה כָּךְ הוּא. כַּחֲצוֹת הַלַּיְלָה מְפִיסִין לִתְרוּמַת הַדֶּשֶׁן. וּמְסַדְּרִין אֶת הַמַּעֲרָכָה וּמְדַשְּׁנִין אֶת הַמִּזְבֵּחַ כְּדֶרֶךְ שֶׁעוֹשִׂין בְּכָל יוֹם עַל הַסֵּדֶר שֶׁבֵּאַרְנוּ עַד שֶׁיַּגִּיעוּ לִשְׁחִיטַת הַתָּמִיד. כְּשֶׁיַּגִּיעוּ לִשְׁחֹט אֶת הַתָּמִיד פּוֹרְסִין סָדִין שֶׁל בּוּץ בֵּין כֹּהֵן גָּדוֹל וּבֵין הָעָם. וְלָמָּה שֶׁל בּוּץ כְּדֵי שֶׁיַּכִּיר שֶׁעֲבוֹדַת הַיּוֹם בְּבִגְדֵי בּוּץ. וּפוֹשֵׁט בִּגְדֵי חֹל וְטוֹבֵל וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וְשׁוֹחֵט בְּתָמִיד רֹב שְׁנַיִם וּמַנִּיחַ אַחֵר לִגְמֹר הַשְּׁחִיטָה. וּמְקַבֵּל הַדָּם וְזוֹרְקוֹ עַל הַמִּזְבֵּחַ כְּמִצְוָתוֹ. וְאַחַר כָּךְ נִכְנָס לַהֵיכָל וּמַקְטִיר קְטֹרֶת שֶׁל שַׁחַר וּמֵיטִיב אֶת הַנֵּרוֹת. וּמַקְטִיר אֵיבְרֵי הַתָּמִיד וְהַחֲבִיתִין וְהַנְּסָכִים כְּכָל סֵדֶר הַתָּמִיד שֶׁל כָּל יוֹם שֶׁבֵּאַרְנוּ. וְאַחַר הַתָּמִיד מַקְרִיב הַפָּר וְשִׁבְעַת הַכְּבָשִׂים שֶׁל מוּסַף הַיּוֹם. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי זָהָב. וְטוֹבֵל וְלוֹבֵשׁ בִּגְדֵי לָבָן וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וּבָא לוֹ אֵצֶל פָּרוֹ. וּפָרוֹ הָיָה עוֹמֵד בֵּין הָאוּלָם וְלַמִּזְבֵּחַ רֹאשׁוֹ לַדָּרוֹם וּפָנָיו לַמַּעֲרָב וְהַכֹּהֵן עוֹמֵד בַּמִּזְרָח וּפָנָיו לַמַּעֲרָב. וְסוֹמֵךְ שְׁתֵּי יָדָיו עַל רֹאשׁ הַפָּר וּמִתְוַדֶּה. וְכָךְ הָיָה אוֹמֵר אָנָּא הַשֵּׁם חָטָאתִי עָוִיתִי פָּשַׁעְתִּי לְפָנֶיךָ אֲנִי וּבֵיתִי. אָנָּא הַשֵּׁם כַּפֵּר נָא לַחֲטָאִים וְלַעֲוֹנוֹת וְלַפְּשָׁעִים שֶׁחָטָאתִי וְשֶׁעָוִיתִי וְשֶׁפָּשַׁעְתִּי לְפָנֶיךָ אֲנִי וּבֵיתִי כַּכָּתוּב בְּתוֹרַת משֶׁה עַבְדֶּךָ לֵאמֹר (ויקרא טז ל) \"כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם לְטַהֵר אֶתְכֶם מִכּל חַטֹּאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ\". וְאַחַר כָּךְ מַגְרִיל עַל שְׁנֵי הַשְּׂעִירִים. וְקוֹשֵׁר לָשׁוֹן שֶׁל זְהוֹרִית בְּרֹאשׁ הַמִּשְׁתַּלֵּחַ וּמַעֲמִידוֹ כְּנֶגֶד בֵּית שִׁלּוּחוֹ וְלַנִּשְׁחָט כְּנֶגֶד בֵּית שְׁחִיטָתוֹ. וּבָא לוֹ אֵצֶל פָּרוֹ שְׁנִיָּה וְסוֹמֵךְ שְׁתֵּי יָדָיו עַל רֹאשׁוֹ וּמִתְוַדֶּה וִדּוּי שֵׁנִי. וְכָךְ הוּא אוֹמֵר אָנָּא הַשֵּׁם חָטָאתִי עָוִיתִי פָּשַׁעְתִּי לְפָנֶיךָ אֲנִי וּבֵיתִי וּבְנֵי אַהֲרֹן עַם קְדוֹשֶׁיךָ. אָנָּא הַשֵּׁם כַּפֵּר נָא לַחֲטָאִים וְלַעֲוֹנוֹת וְלַפְּשָׁעִים שֶׁחָטָאתִי וְשֶׁעָוִיתִי וְשֶׁפָּשַׁעְתִּי לְפָנֶיךָ אֲנִי וּבֵיתִי וּבְנֵי אַהֲרֹן עַם קְדוֹשֶׁיךָ כַּכָּתוּב בְּתוֹרַת משֶׁה עַבְדֶּךָ כִּי בַיּוֹם הַזֶּה וְגוֹ'. וְאַחַר כָּךְ שׁוֹחֵט אֶת הַפָּר וּמְקַבֵּל אֶת דָּמוֹ וְנוֹתְנוֹ לְמִי שֶׁהוּא מְנַדְנְדוֹ שֶׁלֹּא יִקָּרֵשׁ (וּמַנִּיחָהּ) עַל הָרֹבֶד הָרְבִיעִי שֶׁל הֵיכָל מִבַּחוּץ. וְנוֹטֵל אֶת הַמַּחְתָּה וְחוֹתֶה בָּהּ אֵשׁ מֵעַל הַמִּזְבֵּחַ מִן הַסָּמוּךְ לַמַּעֲרָב. שֶׁנֶּאֱמַר (ויקרא טז יב) \"מֵעַל הַמִּזְבֵּחַ מִלִּפְנֵי ה'\". וְיוֹרֵד וּמַנִּיחָהּ עַל הָרֹבֶד שֶׁבָּעֲזָרָה. וּמוֹצִיאִין לוֹ אֶת הַכַּף וּכְלִי מָלֵא קְטֹרֶת דַּקָּה מִן הַדַּקָּה. וְחוֹפֵן מִמֶּנָּה מְלֹא חָפְנָיו לֹא מְחוּקוֹת וְלֹא גְּדוּשׁוֹת אֶלָּא טְפוּפוֹת הַגָּדוֹל לְפִי גָּדְלוֹ וְהַקָּטָן לְפִי קָטְנוֹ וְנוֹתֵן לְתוֹךְ הַכַּף. כְּבָר בֵּאַרְנוּ שֶׁהוֹלָכָה בִּשְׂמֹאל פּוֹסֶלֶת בְּדַם הַקָּדָשִׁים וּשְׁאָר הָעֲבוֹדוֹת. וּלְפִיכָךְ הָיָה מִן הַדִּין שֶׁיּוֹלִיךְ הַמַּחְתָּה בִּשְׂמֹאלוֹ וְכַף הַקְּטֹרֶת בִּימִינוֹ. אֲבָל מִפְּנֵי כֹּבֶד הַמַּחְתָּה וְעוֹד שֶׁהִיא חַמָּה. אֵינוֹ יָכוֹל לְסָבְלָהּ בִּשְׂמֹאלוֹ עַד הָאָרוֹן. לְפִיכָךְ נוֹטֵל הַמַּחְתָּה בִּימִינוֹ וְכַף הַקְּטֹרֶת בִּשְׂמֹאלוֹ. וּמְהַלֵּךְ בַּהֵיכָל עַד שֶׁהוּא מַגִּיעַ לְקֹדֶשׁ הַקָּדָשִׁים. מָצָא הַפָּרֹכֶת פְּרוּפָה נִכְנַס לְקֹדֶשׁ הַקָּדָשִׁים עַד שֶׁהוּא מַגִּיעַ לָאָרוֹן. הִגִּיעַ לָאָרוֹן נוֹתֵן הַמַּחְתָּה בֵּין שְׁנֵי הַבַּדִּים וּבְבַיִת שֵׁנִי שֶׁלֹּא הָיָה אָרוֹן הָיָה מַנִּיחָהּ עַל אֶבֶן הַשְּׁתִיָּה. וְאוֹחֵז שְׂפַת הַכַּף בְּרָאשֵׁי אֶצְבְּעוֹתָיו אוֹ בְּשִׁנָּיו. וּמְעָרֶה הַקְּטֹרֶת בְּגוּדָלוֹ לְתוֹךְ חָפְנָיו עַד שֶׁמַּחְזִירָהּ לִמְלֹא חָפְנָיו כְּשֶׁהָיְתָה. וְזוֹ הִיא עֲבוֹדָה קָשָׁה שֶׁבַּמִּקְדָּשׁ. וְצוֹבֵר אֶת הַקְּטֹרֶת עַל גַּבֵּי הַגֶּחָלִים בְּיָדוֹ לְפָנִים בַּמַּחְתָּה. כְּדֵי שֶׁתִּהְיֶה הַקְּטֹרֶת קְרוֹבָה לָאָרוֹן וּרְחוֹקָה מִפָּנָיו שֶׁלֹּא יִכָּוֶה. וּמַמְתִּין שָׁם עַד שֶׁיִּתְמַלֵּא הַבַּיִת עָשָׁן וְיֵצֵא. וְהוּא מְהַלֵּךְ אֲחוֹרַנִּית מְעַט מְעַט פָּנָיו לַקֹּדֶשׁ וַאֲחוֹרָיו לַהֵיכָל עַד שֶׁיֵּצֵא מִן הַפָּרֹכֶת. וּמִתְפַּלֵּל שָׁם בַּהֵיכָל אַחַר שֶׁיֵּצֵא תְּפִלָּה קְצָרָה שֶׁלֹּא לְהַבְעִית אֶת הָעָם שֶׁמָּא יֹאמְרוּ מֵת בַּהֵיכָל. וְכָךְ הָיָה מִתְפַּלֵּל. יְהִי רָצוֹן מִלְּפָנֶיךָ ה' אֱלֹהֵינוּ שֶׁאִם תִּהְיֶה שָׁנָה זוֹ שְׁחוּנָה תִּהְיֶה גְּשׁוּמָה. וְלֹא יָסוּר שֵׁבֶט מִבֵּית יְהוּדָה. וְלֹא יִהְיוּ עַמְּךָ בֵּית יִשְׂרָאֵל צְרִיכִין לְפַרְנָסָה [א.] וְאַל תִּכָּנֵס לְפָנֶיךָ תְּפִלַּת עוֹבְרֵי דְּרָכִים:","בִּשְׁעַת הַקְטָרַת הַקְּטֹרֶת בְּקֹדֶשׁ הַקָּדָשִׁים. כָּל הָעָם פּוֹרְשִׁים מִן הַהֵיכָל בִּלְבַד וְאֵינָן פּוֹרְשִׁים מִבֵּין הָאוּלָם וְלַמִּזְבֵּחַ. שֶׁאֵין פּוֹרְשִׁים מִבֵּין הָאוּלָם וְלַמִּזְבֵּחַ אֶלָּא בִּשְׁעַת הַקְטָרָה בַּהֵיכָל בְּכָל יוֹם וּבִשְׁעַת מַתַּן דָּמִים בַּהֵיכָל כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּמִידִין. וְאַחַר כָּךְ נוֹטֵל דַּם הַפָּר מִזֶּה שֶׁהוּא מְנַדְנְדוֹ. וְנִכְנָס בּוֹ לְקֹדֶשׁ הַקָּדָשִׁים וּמַזֶּה מִמֶּנּוּ שָׁם שְׁמוֹנֶה הַזָּיוֹת בֵּין בַּדֵּי הָאָרוֹן. וְיוֹצֵא וּמַנִּיחוֹ בַּהֵיכָל עַל כַּן הַזָּהָב שֶׁהָיָה שָׁם. וְאַחַר כָּךְ יוֹצֵא מִן הַהֵיכָל וְשׁוֹחֵט אֶת הַשָּׂעִיר וּמְקַבֵּל אֶת דָּמוֹ וְנִכְנָס בּוֹ לְקֹדֶשׁ הַקָּדָשִׁים. וּמַזֶּה מִמֶּנּוּ שָׁם שְׁמוֹנֶה הַזָּיוֹת בֵּין בַּדֵּי הָאָרוֹן. וְיוֹצֵא וּמַנִּיחוֹ עַל כַּן הַזָּהָב שֵׁנִי שֶׁבַּהֵיכָל. וְאַחַר כָּךְ נוֹטֵל דַּם הַפָּר מֵעַל הַכַּן וּמַזֶּה מִמֶּנּוּ עַל הַפָּרֹכֶת כְּנֶגֶד הָאָרוֹן שְׁמוֹנֶה הַזָּיוֹת וּמַנִּיחַ דַּם הַפָּר וְנוֹטֵל דַּם הַשָּׂעִיר וּמַזֶּה מִמֶּנּוּ עַל הַפָּרֹכֶת כְּנֶגֶד הָאָרוֹן שְׁמוֹנֶה הַזָּיוֹת. וְאַחַר כָּךְ מְעָרֶה דַּם הַפָּר לְתוֹךְ דַּם הַשָּׂעִיר וּמַחֲזִיר הַכּל לַמִּזְרָק שֶׁהָיָה בּוֹ דַּם הַפָּר כְּדֵי שֶׁיִּתְעָרְבוּ יָפֶה יָפֶה. וְעוֹמֵד לְפָנִים מִמִּזְבַּח הַזָּהָב בֵּין הַמִּזְבֵּחַ וְהַמְּנוֹרָה. וּמַתְחִיל לְהַזּוֹת מִדַּם הַתַּעֲרֹבֶת עַל קַרְנוֹת מִזְבַּח הַזָּהָב. וְהוּא מְסַבֵּב וְהוֹלֵךְ וּמַזֶּה עַל הַקְּרָנוֹת מִבַּחוּץ. וּמַתְחִיל מִקֶּרֶן מִזְרָחִית צְפוֹנִית. לִצְפוֹנִית מַעֲרָבִית. לְמַעֲרָבִית דְּרוֹמִית. לִדְרוֹמִית מִזְרָחִית. וְעַל כֻּלָּן הוּא נוֹתֵן מִלְּמַטָּן לְמַעְלָן. חוּץ מִן הָאַחֲרוֹנָה שֶׁהָיְתָה לְפָנָיו שֶׁהוּא נוֹתֵן מִלְּמַעְלָן לְמַטָּן. כְּדֵי שֶׁלֹּא יִתְלַכְלְכוּ כֵּלָיו. וְחוֹתֶה הַגֶּחָלִים וְהָאֵפֶר שֶׁבְּמִזְבַּח הַזָּהָב הֵילָךְ וְהֵילָךְ עַד שֶׁמְּגַלֶּה זְהָבוֹ. וּמַזֶּה מִדַּם הַתַּעֲרֹבֶת עַל טָהֳרוֹ שֶׁל מִזְבֵּחַ שֶׁבַע פְּעָמִים בְּצַד הַדָּרוֹם בְּמָקוֹם שֶׁשָּׁלְמוּ מַתְּנוֹת קַרְנוֹתָיו. וְיוֹצֵא וְשׁוֹפֵךְ שְׁיָרֵי הַדָּם עַל יְסוֹד מַעֲרָבִי שֶׁל מִזְבֵּחַ הַחִיצוֹן. וְאַחַר כָּךְ בָּא אֵצֶל שָׂעִיר הַמִּשְׁתַּלֵּחַ וְסוֹמֵךְ שְׁתֵּי יָדָיו עַל רֹאשׁוֹ וּמִתְוַדֶּה. וְכָךְ הוּא אוֹמֵר אָנָּא הַשֵּׁם חָטְאוּ עָווּ וּפָשְׁעוּ לְפָנֶיךָ עַמְּךָ בֵּית יִשְׂרָאֵל. אָנָּא הַשֵּׁם כַּפֵּר נָא לַחֲטָאִים וְלַעֲוֹנוֹת וְלַפְּשָׁעִים שֶׁחָטְאוּ וְשֶׁעָווּ וְשֶׁפָּשְׁעוּ לְפָנֶיךָ עַמְּךָ בֵּית יִשְׂרָאֵל כַּכָּתוּב בְּתוֹרַת משֶׁה עַבְדֶּךָ (ויקרא טז ל) \"כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם\" וְגוֹ'. וְאַחַר כָּךְ מְשַׁלֵּחַ אֶת הַשָּׂעִיר לַמִּדְבָּר. וּמוֹצִיא אֵימוּרֵי פַּר וְשָׂעִיר שֶׁהִכְנִיס דָּמָן לְפָנִים וְנוֹתְנָן בִּכְלִי. וּמְשַׁלֵּחַ הַשְּׁאָר לְבֵית הַדֶּשֶׁן לִשְׂרֵפָה. וְיוֹצֵא לְעֶזְרַת הַנָּשִׁים וְקוֹרֵא שָׁם אַחַר שֶׁיַּגִּיעַ הַשָּׂעִיר לַמִּדְבָּר. וְאַחַר כָּךְ מְקַדֵּשׁ וּפוֹשֵׁט בִּגְדֵי לָבָן וְטוֹבֵל וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ יָדָיו וְרַגְלָיו. וְעוֹשֶׂה הַשָּׂעִיר הַנַּעֲשֶׂה בַּחוּץ שֶׁהוּא מִכְּלַל קָרְבְּנוֹת מוּסַף הַיּוֹם. וּמַקְרִיב אֵילוֹ וְאֵיל הָעָם שֶׁנֶּאֱמַר (ויקרא טז כד) \"וְיָצָא וְעָשָׂה אֶת עלָתוֹ וְאֶת עלַת הָעָם\". וּמַקְטִיר הָאֵימוּרִין שֶׁל פַּר וְשָׂעִיר הַנִּשְׂרָפִין. וּמַקְרִיב תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי זָהָב וְטוֹבֵל וְלוֹבֵשׁ בִּגְדֵי לָבָן וּמְקַדֵּשׁ וְנִכְנָס לְקֹדֶשׁ הַקָּדָשִׁים וּמוֹצִיא אֶת הַכַּף וְאֶת הַמַּחְתָּה. וְאַחַר כָּךְ מְקַדֵּשׁ וּפוֹשֵׁט בִּגְדֵי לָבָן וְטוֹבֵל וְלוֹבֵשׁ בִּגְדֵי זָהָב וּמְקַדֵּשׁ וּמַקְטִיר קְטֹרֶת שֶׁל בֵּין הָעַרְבַּיִם וּמֵיטִיב אֶת הַנֵּרוֹת שֶׁל בֵּין הָעַרְבַּיִם כִּשְׁאָר הַיָּמִים. וְאַחַר כָּךְ מְקַדֵּשׁ יָדָיו וְרַגְלָיו וּפוֹשֵׁט בִּגְדֵי זָהָב וְלוֹבֵשׁ בִּגְדֵי עַצְמוֹ וְיוֹצֵא לְבֵיתוֹ וְכָל הָעָם מְלַוִּין אוֹתוֹ עַד בֵּיתוֹ. וְיוֹם טוֹב הָיָה עוֹשֶׂה עַל שֶׁיָּצָא בְּשָׁלוֹם מִן הַקֹּדֶשׁ:"],"Mishneh Torah, Shofar, Sukkah and Lulav 7":["(ויקרא כג מ) \"כַּפּוֹת תְּמָרִים\" הָאֲמוּרוֹת בַּתּוֹרָה הֵן חֲרָיוֹת שֶׁל דֶּקֶל כְּשֶׁיִּצְמְחוּ קֹדֶם שֶׁיִּתְפָּרְדוּ הֶעָלִין שֶׁלָּהֶן לְכָאן וּלְכָאן אֶלָּא כְּשֶׁיִּהְיֶה כְּמוֹ שַׁרְבִיט. וְהוּא הַנִּקְרָא לוּלָב:","(ויקרא כג מ) \"פְּרִי עֵץ הָדָר\" הָאָמוּר בַּתּוֹרָה הוּא אֶתְרוֹג. (ויקרא כג מ) \"וַעֲנַף עֵץ עָבוֹת\" הָאָמוּר בַּתּוֹרָה הוּא הַהֲדַס שֶׁעָלָיו חוֹפִין אֶת עֵצוֹ. כְּגוֹן שֶׁיִּהְיוּ שְׁלֹשָׁה עָלִין אוֹ יֶתֶר עַל כֵּן בְּגִבְעוֹל אֶחָד. אֲבָל אִם הָיוּ שְׁנֵי הֶעָלִין בְּשָׁוֶה זֶה כְּנֶגֶד זֶה וְהֶעָלֶה הַשְּׁלִישִׁי לְמַעְלָה מֵהֶן אֵין זֶה עָבוֹת אֲבָל נִקְרָא הֲדַס שׁוֹטֶה:","(ויקרא כג מ) \"עַרְבֵי נַחַל\" הָאֲמוּרוֹת בַּתּוֹרָה אֵינָן כָּל דָּבָר הַגָּדֵל עַל הַנַּחַל אֶלָּא מִין יָדוּעַ הוּא הַנִּקְרָא עַרְבֵי נַחַל. עָלֶה שֶׁלּוֹ מָשׁוּךְ כְּנַחַל וּפִיו חָלָק וְקָנֶה שֶׁלּוֹ אָדֹם וְזֶה הוּא הַנִּקְרָא עֲרָבָה. וְרֹב מִין זֶה גָּדֵל עַל הַנְּחָלִים לְכָךְ נֶאֱמַר עַרְבֵי נָחַל. וַאֲפִלּוּ הָיָה גָּדֵל בַּמִּדְבָּר אוֹ בֶּהָרִים כָּשֵׁר:","וְיֵשׁ מִין אַחֵר דּוֹמֶה לַעֲרָבָה אֶלָּא שֶׁעָלֶה שֶׁלּוֹ עָגל וּפִיו דּוֹמֶה לְמַסָּר וְקָנֶה שֶׁלּוֹ אֵינוֹ אָדֹם וְזֶהוּ הַנִּקְרָא צַפְצָפָה וְהִיא פְּסוּלָה. וְיֵשׁ שָׁם מִין עֲרָבָה שֶׁאֵין פִּי הֶעָלֶה שֶׁלָּהּ חָלָק וְאֵינוֹ כְּמַסָּר אֶלָּא יֵשׁ בּוֹ תְּלָמִים קְטַנִּים עַד מְאֹד כְּמוֹ פִּי מַגָּל קָטָן וְזֶה כָּשֵׁר. וְכָל הַדְּבָרִים הָאֵלּוּ מִפִּי הַשְּׁמוּעָה מִמּשֶׁה רַבֵּנוּ נִתְפָּרְשׁוּ:","אַרְבָּעָה מִינִין אֵלּוּ מִצְוָה אַחַת הֵן וּמְעַכְּבִין זֶה אֶת זֶה וְכֻלָּן נִקְרָאִים מִצְוַת לוּלָב. וְאֵין פּוֹחֲתִין מֵהֶן וְאֵין מוֹסִיפִין עֲלֵיהֶן. וְאִם לֹא נִמְצָא אֶחָד מֵהֶן אֵין מְבִיאִים תַּחְתָּיו מִין אַחֵר הַדּוֹמֶה לוֹ:","מִצְוָה מִן הַמֻּבְחָר לֶאֱגֹד לוּלָב וַהֲדַס וַעֲרָבָה וְלַעֲשׂוֹת שְׁלָשְׁתָּן אֲגֻדָּה אַחַת. וּכְשֶׁהוּא נוֹטְלָם לָצֵאת בָּהֶן מְבָרֵךְ תְּחִלָּה עַל נְטִילַת לוּלָב הוֹאִיל וְכֻלָּן סְמוּכִין לוֹ וְאַחַר כָּךְ נוֹטֵל הָאֲגֻדָּה הַזֹּאת בִּימִינוֹ וְאֶתְרוֹג בִּשְׂמֹאלוֹ וְנוֹטְלָן דֶּרֶךְ גְּדִילָתָן שֶׁיִּהְיוּ עִקְּרֵיהֶן לְמַטָּה לָאָרֶץ וְרָאשֵׁיהֶן לְמַעְלָה לַאֲוִיר. וְאִם לֹא אֲגָדָן וּנְטָלָן אֶחָד אֶחָד יָצָא וְהוּא שֶׁיִּהְיוּ אַרְבַּעְתָּן מְצוּיִין אֶצְלוֹ. אֲבָל אִם לֹא הָיָה לוֹ אֶלָּא מִין אֶחָד אוֹ שֶׁחָסֵר מִין אֶחָד לֹא יִטּל עַד שֶׁיִּמְצָא הַשְּׁאָר:","כַּמָּה נוֹטֵל מֵהֶן. לוּלָב אֶחָד וְאֶתְרוֹג אֶחָד וּשְׁנֵי בַּדֵּי עֲרָבָה וּשְׁלֹשָׁה בַּדֵּי הֲדַס. וְאִם רָצָה לְהוֹסִיף בַּהֲדַס כְּדֵי שֶׁתִּהְיֶה אֲגֻדָּה גְּדוֹלָה מוֹסִיף. וְנוֹיֵי מִצְוָה הוּא. אֲבָל שְׁאָר הַמִּינִין אֵין מוֹסִיפִין עַל מִנְיָנָם וְאֵין גּוֹרְעִין מֵהֶן. וְאִם הוֹסִיף אוֹ גָּרַע (פָּסוּל):","כַּמָּה שִׁעוּר אֹרֶךְ כָּל מִין מֵהֶם. לוּלָב אֵין פָּחוֹת מֵאַרְבָּעָה טְפָחִים וְאִם הָיָה אָרֹךְ כָּל שֶׁהוּא כָּשֵׁר. וּמְדִידָתוֹ מִשִּׁדְרָתוֹ בִּלְבַד לֹא מֵרֹאשׁ הֶעָלִים. וַהֲדַס וַעֲרָבָה אֵין פָּחוֹת מִשְּׁלֹשָׁה טְפָחִים. וְאִם הָיוּ אֲרֻכִּין כָּל שֶׁהֵן כְּשֵׁרִים. וַאֲפִלּוּ אֵין בְּכָל בַּד וּבַד אֶלָּא שְׁלֹשָׁה עָלִין לַחִין כְּשֵׁרִים וְהוּא שֶׁיִּהְיוּ בְּרֹאשׁ הַבַּד. וְאִם אָגַד הַלּוּלָב צָרִיךְ שֶׁיִּהְיֶה שְׁדֵרוֹ שֶׁל לוּלָב יוֹצֵא מִן הַהֲדַס וַעֲרָבָה טֶפַח אוֹ יוֹתֵר. וְשִׁעוּר אֶתְרוֹג אֵין פָּחוֹת מִכְּבֵיצָה וְאִם הָיָה גָּדוֹל כָּל שֶׁהוּא כָּשֵׁר:","מִשֶּׁיַּגְבִּיהַ אַרְבָּעָה מִינִין אֵלּוּ בֵּין שֶׁהִגְבִּיהָן כְּאַחַת בֵּין בָּזֶה אַחַר זֶה בֵּין בְּיָמִין בֵּין בִּשְׂמֹאל יָצָא. וְהוּא שֶׁיַּגְבִּיהָן דֶּרֶךְ גְּדִילָתָן. אֲבָל שֶׁלֹּא דֶּרֶךְ גְּדִילָתָן לֹא יָצָא. וּמִצְוָה כְּהִלְכָתָהּ שֶׁיַּגְבִּיהַּ אֲגֻדָּה שֶׁל שְׁלֹשָׁה מִינִין בְּיָמִין וְאֶתְרוֹג בִּשְׂמֹאל וְיוֹלִיךְ וְיָבִיא וְיַעֲלֶה וְיוֹרִיד וִינַעֲנֵעַ הַלּוּלָב שְׁלֹשָׁה פְּעָמִים בְּכָל רוּחַ וְרוּחַ:","כֵּיצַד. מוֹלִיךְ וּמְנַעְנֵעַ רֹאשׁ הַלּוּלָב שָׁלֹשׁ פְּעָמִים וּמֵבִיא וּמְנַעְנֵעַ רֹאשׁ הַלּוּלָב שָׁלֹשׁ פְּעָמִים וְכֵן בַּעֲלִיָּה וִירִידָה. וְהֵיכָן מוֹלִיךְ וּמֵבִיא. בִּשְׁעַת קְרִיאַת הַהַלֵּל בְּ (תהילים קיח א) (תהילים קיח כט) \"הוֹדוּ לַה' כִּי טוֹב\" תְּחִלָּה וָסוֹף וּבְ(תהילים קיח כה) \"אָנָּא ה' הוֹשִׁיעָה נָּא\". וְכָל הַיּוֹם כָּשֵׁר לִנְטִילַת לוּלָב וְאֵינוֹ נוֹטֵל בַּלַּיְלָה:","עָשָׂה לַאֲגֻדָּה זוֹ גִּימוֹן שֶׁל כֶּסֶף וְשֶׁל זָהָב אוֹ שֶׁכָּרַךְ עָלֶיהָ סָדִין וּנְטָלָהּ יָצָא. לְקִיחָה עַל יְדֵי דָּבָר אַחֵר שְׁמָהּ לְקִיחָה. וְהוּא שֶׁיִּהְיֶה דֶּרֶךְ כָּבוֹד וְדֶרֶךְ הִדּוּר שֶׁכָּל שֶׁהוּא לְנָאוֹתוֹ אֵינוֹ חוֹצֵץ. אֲבָל אִם נָתַן אֶת הַמִּינִין הָאֵלּוּ בְּעָצִיץ אוֹ בִּקְדֵרָה וּנְטָלָהּ לֹא יָצָא יְדֵי חוֹבָתוֹ:","אָגַד אֶת הַלּוּלָב עִם הַהֲדַס וְהָעֲרָבָה וְהִבְדִּיל בֵּין הַלּוּלָב וּבֵין הַהֲדַס בְּמַטְלָת וְכַיּוֹצֵא בָּהּ הֲרֵי זֶה חוֹצֵץ. הִבְדִּיל בֵּינֵיהֶן בַּעֲלֵי הֲדַס אֵינוֹ חוֹצֵץ. שֶׁמִּין בְּמִינוֹ אֵינוֹ חוֹצֵץ. וְיֵשׁ לוֹ לֶאֱגֹד אֶת הַלּוּלָב בְּחוּט אוֹ בִּמְשִׁיחָה וּבְכָל מִין שֶׁיִּרְצֶה הוֹאִיל וְאֵין אֲגִידָתוֹ מְעַכֵּב:","מִצְוַת לוּלָב לְהִנָּטֵל בְּיוֹם רִאשׁוֹן שֶׁל חַג בִּלְבַד בְּכָל מָקוֹם וּבְכָל זְמַן וַאֲפִלּוּ בְּשַׁבָּת שֶׁנֶּאֱמַר (ויקרא כג מ) \"וּלְקַחְתֶּם לָכֶם בַּיּוֹם הָרִאשׁוֹן\". וּבַמִּקְדָּשׁ לְבַדּוֹ נוֹטְלִין אוֹתוֹ בְּכָל יוֹם וָיוֹם מִשִּׁבְעַת יְמֵי הֶחָג שֶׁנֶּאֱמַר (ויקרא כג מ) \"וּשְׂמַחְתֶּם לִפְנֵי ה' אֱלֹהֵיכֶם\" וְגוֹ'. חָל יוֹם הַשַּׁבָּת לִהְיוֹת בְּתוֹךְ יְמֵי הֶחָג אֵינוֹ נִטָּל בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יוֹלִיכֶנּוּ בְּיָדוֹ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים כְּמוֹ שֶׁגָּזְרוּ בְּשׁוֹפָר:","וְלָמָּה לֹא גָּזְרוּ גְּזֵרָה זוֹ בְּיוֹם טוֹב הָרִאשׁוֹן מִפְּנֵי שֶׁהוּא מִצְוָה מִן הַתּוֹרָה וַאֲפִלּוּ בִּגְבוּלִין. נִמְצָא שֶׁאֵין דִּינוֹ וְדִין שְׁאָר הַיָּמִים שָׁוֶה שֶׁבִּשְׁאָר יְמֵי הֶחָג אֵין אָדָם חַיָּב לִטּל לוּלָב אֶלָּא בַּמִּקְדָּשׁ:","מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ הִתְקִינוּ שֶׁיִּהְיֶה לוּלָב נִטָּל בְּכָל מָקוֹם כָּל שִׁבְעַת יְמֵי הֶחָג זֵכֶר לַמִּקְדָּשׁ. וְכָל יוֹם וָיוֹם מְבָרֵךְ עָלָיו אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל נְטִילַת לוּלָב מִפְּנֵי שֶׁהִיא מִצְוָה מִדִּבְרֵי סוֹפְרִים. וְתַקָּנָה זוֹ עִם כָּל הַתַּקָּנוֹת שֶׁהִתְקִין רַבָּן יוֹחָנָן בֵּן זַכַּאי מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ כְּשֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ יַחְזְרוּ הַדְּבָרִים לְיָשְׁנָן:","בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם הָיָה לוּלָב נִטָּל בַּיּוֹם הָרִאשׁוֹן שֶׁחָל לִהְיוֹת בְּשַׁבָּת. וְכֵן בִּשְׁאָר הַמְּקוֹמוֹת שֶׁיָּדְעוּ בְּוַדַּאי שֶׁיּוֹם זֶה הוּא יוֹם הֶחָג בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל הַמְּקוֹמוֹת הָרְחוֹקִים שֶׁלֹּא הָיוּ יוֹדְעִים בִּקְבִיעוּת רֹאשׁ חֹדֶשׁ לֹא הָיוּ נוֹטְלִין הַלּוּלָב מִסָּפֵק:","וּמִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ אָסְרוּ חֲכָמִים לִטּל אֶת הַלּוּלָב בְּשַׁבָּת בַּיּוֹם הָרִאשׁוֹן וַאֲפִלּוּ בְּנֵי אֶרֶץ יִשְׂרָאֵל שֶׁקִּדְּשׁוּ אֶת הַחֹדֶשׁ. מִפְּנֵי בְּנֵי הַגְּבוּלִין הָרְחוֹקִים שֶׁאֵינָן יוֹדְעִין בִּקְבִיעַת הַחֹדֶשׁ. כְּדֵי שֶׁיִּהְיוּ הַכּל שָׁוִין בְּדָבָר זֶה וְלֹא יִהְיוּ אֵלּוּ נוֹטְלִין בְּשַׁבָּת וְאֵלּוּ אֵין נוֹטְלִין. הוֹאִיל וְחִיּוּב יוֹם רִאשׁוֹן בְּכָל מָקוֹם אֶחָד הוּא וְאֵין שָׁם מִקְדָּשׁ לְהִתָּלוֹת בּוֹ:","וּבַזְּמַן הַזֶּה שֶׁהַכּל עוֹשִׂין עַל פִּי הַחֶשְׁבּוֹן נִשְׁאָר הַדָּבָר כְּמוֹת שֶׁהָיָה שֶׁלֹּא יִנָּטֵל לוּלָב בְּשַׁבָּת כְּלָל לֹא בִּגְבוּלִין וְלֹא בְּאֶרֶץ יִשְׂרָאֵל וַאֲפִלּוּ בְּיוֹם רִאשׁוֹן. וְאַף עַל פִּי שֶׁהַכּל יוֹדְעִים בִּקְבִיעַת הַחֹדֶשׁ. וּכְבָר בֵּאַרְנוּ שֶׁעִקַּר הָאִסּוּר בִּנְטִילַת הַלּוּלָב בְּשַׁבָּת גְּזֵרָה שֶׁמָּא יַעֲבִירֶנּוּ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים:","כָּל שֶׁחַיָּב בְּשׁוֹפָר וּבְסֻכָּה חַיָּב בִּנְטִילַת הַלּוּלָב. וְכָל הַפָּטוּר מִשּׁוֹפָר וְסֻכָּה פָּטוּר מִנְּטִילַת לוּלָב. קָטָן הַיּוֹדֵעַ לְנַעֲנֵעַ חַיָּב בְּלוּלָב מִדִּבְרֵי סוֹפְרִים כְּדֵי לְחַנְּכוֹ בְּמִצְוֹת:","הֲלָכָה לְמשֶׁה מִסִּינַי שֶּׁמְּבִיאִין בַּמִּקְדָּשׁ עֲרָבָה אַחֶרֶת חוּץ מֵעֲרָבָה שֶׁבַּלּוּלָב. וְאֵין אָדָם יוֹצֵא יְדֵי חוֹבָתוֹ בַּעֲרָבָה שֶׁבַּלּוּלָב. וְשִׁעוּרָהּ אֲפִלּוּ עָלֶה אֶחָד בְּבַד אֶחָד:","כֵּיצַד הָיְתָה מִצְוָתָהּ. בְּכָל יוֹם וָיוֹם מִשִּׁבְעַת הַיָּמִים הָיוּ מְבִיאִין מֻרְבִּיּוֹת שֶׁל עֲרָבָה וְזוֹקְפִין אוֹתָן עַל צִדְדֵי הַמִּזְבֵּחַ וְרָאשֵׁיהֶן כְּפוּפִין עַל גַּבֵּי הַמִּזְבֵּחַ. וּבְעֵת שֶׁהָיוּ מְבִיאִין אוֹתָהּ וְסוֹדְרִין אוֹתָהּ תּוֹקְעִין וּמְרִיעִין וְתוֹקְעִין. חָל יוֹם שַׁבָּת לִהְיוֹת בְּתוֹךְ הֶחָג אֵין זוֹקְפִין עֲרָבָה אֶלָּא אִם כֵּן חָל יוֹם שְׁבִיעִי לִהְיוֹת בְּשַׁבָּת זוֹקְפִין אוֹתָהּ בְּשַׁבָּת כְּדֵי לְפַרְסְמָהּ שֶׁהִיא מִצְוָה:","כֵּיצַד הָיוּ עוֹשִׂין. מְבִיאִין אוֹתָהּ מֵעֶרֶב שַׁבָּת לַמִּקְדָּשׁ וּמַנִּיחִין אוֹתָהּ בְּגִגִּיּוֹת שֶׁל זָהָב כְּדֵי שֶׁלֹּא יִכְמְשׁוּ הֶעָלִין. וּלְמָחָר זוֹקְפִין אוֹתָהּ עַל גַּבֵּי הַמִּזְבֵּחַ וּבָאִין הָעָם וְלוֹקְחִין מִמֶּנָּה וְנוֹטְלִין אוֹתָהּ כְּדֶרֶךְ שֶׁעוֹשִׂין בְּכָל יוֹם. וַעֲרָבָה זוֹ הוֹאִיל וְאֵינָהּ בְּפֵרוּשׁ בַּתּוֹרָה אֵין נוֹטְלִין אוֹתָהּ כָּל שִׁבְעַת יְמֵי הֶחָג זֵכֶר לַמִּקְדָּשׁ אֶלָּא בַּיּוֹם הַשְּׁבִיעִי בִּלְבַד הוּא שֶׁנּוֹטְלִין אוֹתָהּ בַּזְּמַן הַזֶּה. כֵּיצַד עוֹשֶׂה. לוֹקֵחַ בַּד אֶחָד אוֹ בַּדִּין הַרְבֵּה חוּץ מֵעֲרָבָה שֶׁבַּלּוּלָב וְחוֹבֵט בָּהּ עַל הַקַּרְקַע אוֹ עַל הַכְּלִי פַּעֲמַיִם אוֹ שָׁלֹשׁ בְּלֹא בְּרָכָה שֶׁדָּבָר זֶה מִנְהַג נְבִיאִים הוּא:","בְּכָל יוֹם וָיוֹם הָיוּ מַקִּיפִין אֶת הַמִּזְבֵּחַ בְּלוּלְבֵיהֶן בִּידֵיהֶן פַּעַם אַחַת וְאוֹמְרִין (תהילים קיח כה) \"אָנָּא ה' הוֹשִׁיעָה נָּא\". (תהילים קיח כה) \"אָנָּא ה' הַצְלִיחָה נָּא\". וּבַיּוֹם הַשְּׁבִיעִי מַקִּיפִין אֶת הַמִּזְבֵּחַ שֶׁבַע פְּעָמִים. וּכְבָר נָהֲגוּ יִשְׂרָאֵל בְּכָל הַמְּקוֹמוֹת לְהַנִּיחַ תֵּבָה בְּאֶמְצַע בֵּית הַכְּנֶסֶת וּמַקִּיפִין אוֹתָהּ בְּכָל יוֹם כְּדֶרֶךְ שֶׁהָיוּ מַקִּיפִין אֶת הַמִּזְבֵּחַ זֵכֶר לַמִּקְדָּשׁ:","כָּךְ הָיָה הַמִּנְהָג בִּירוּשָׁלַיִם. יוֹצֵא אָדָם מִבֵּיתוֹ שַׁחֲרִית וְלוּלָבוֹ בְּיָדוֹ. וְנִכְנָס לְבַיִת הַכְּנֶסֶת וְהוּא בְּיָדוֹ. מִתְפַּלֵּל וְהוּא בְּיָדוֹ. וְיוֹצֵא לְבַקֵּר חוֹלִים וּלְנַחֵם אֲבֵלִים וְהוּא בְּיָדוֹ. וּכְשֶׁיִּכָּנֵס לַמִּדְרָשׁ מְשַׁלְּחוֹ לְבֵיתוֹ בְּיַד בְּנוֹ אוֹ בְּיַד עַבְדּוֹ:","מְקַבֶּלֶת אִשָּׁה הַלּוּלָב מִיַּד בְּנָהּ אוֹ מִיַּד בַּעְלָהּ וּמַחְזִירָתוֹ לַמַּיִם בְּשַׁבָּת בִּזְמַן שֶׁהָיוּ נוֹטְלִין לוּלָב בְּשַׁבָּת. וּבְיוֹם טוֹב מוֹסִיפִין עַל הַמַּיִם וּבַמּוֹעֵד מַחְלִיפִין הַמַּיִם:","הֲדַס שֶׁבַּלּוּלָב אָסוּר לְהָרִיחַ בּוֹ מִפְּנֵי שֶׁאֵינוֹ רָאוּי אֶלָּא לְרֵיחַ וְהוֹאִיל וְהֻקְצָה לְמִצְוָה אָסוּר לְהָרִיחַ בּוֹ. אֲבָל אֶתְרוֹג מֻתָּר לְהָרִיחַ בּוֹ שֶׁהֲרֵי הֻקְצָה לְמִצְוָה מֵאֲכִילָה:","וְאָסוּר לֶאֱכל אֶתְרוֹג כָּל יוֹם הַשְּׁבִיעִי מִפְּנֵי שֶׁהֻקְצָה לְמִקְצָת הַיּוֹם הֻקְצָה לְכֻלּוֹ. וּבַשְּׁמִינִי מֻתָּר בַּאֲכִילָה. וּבַזְּמַן הַזֶּה שֶׁאָנוּ עוֹשִׂין שְׁנֵי יָמִים אַף עַל פִּי שֶׁאֵין נוֹטְלִין לוּלָב בַּשְּׁמִינִי הָאֶתְרוֹג אָסוּר בַּשְּׁמִינִי כְּדֶרֶךְ שֶׁהָיָה אָסוּר בַּשְּׁמִינִי בִּזְמַן שֶׁהָיוּ עוֹשִׂין שְׁנֵי יָמִים מִפְּנֵי הַסָּפֵק שֶׁהוּא סְפֵק שְׁבִיעִי. הִפְרִישׁ שִׁבְעָה אֶתְרוֹגִין לְשִׁבְעַת יָמִים כָּל אַחַת וְאַחַת יוֹצֵא בָּהּ לְיוֹמָהּ וְאוֹכְלָהּ לְמָחָר:"],"Mishneh Torah, Substitution 2":["הַתְמוּרָה הוּא שֶׁיֹּאמַר בַּעַל הַקָּרְבָּן עַל בֶּהֱמַת חֻלִּין שֶׁיֵּשׁ לוֹ הֲרֵי זוֹ תַּחַת זוֹ. אוֹ הֲרֵי זוֹ חֲלִיפַת זוֹ. וְאֵין צָרִיךְ לוֹמַר אִם אָמַר הֲרֵי זוֹ תַּחַת חַטָּאת זוֹ אוֹ תַּחַת עוֹלָה זוֹ שֶׁהִיא תְּמוּרָה. וְכֵן אִם אָמַר הֲרֵי זוֹ תַּחַת חַטָּאת שֶׁיֵּשׁ לִי בְּתוֹךְ הַבַּיִת אוֹ תַּחַת עוֹלָה שֶׁיֵּשׁ לִי בְּמָקוֹם פְּלוֹנִי הֲרֵי זוֹ תְּמוּרָה וְהוּא שֶׁיֵּשׁ לוֹ. אֲבָל אִם אָמַר עַל בֶּהֱמַת חֻלִּין הֲרֵי זוֹ תַּחַת עוֹלָה אוֹ הֲרֵי זוֹ תַּחַת חַטָּאת לֹא אָמַר כְּלוּם. וְכֵן אִם אָמַר הֲרֵי זוֹ מְחֻלֶּלֶת עַל זוֹ אֵינָהּ תְּמוּרָה:","הָיוּ לְפָנָיו שְׁתֵּי בְּהֵמוֹת אַחַת חֻלִּין וְאַחַת הֶקְדֵּשׁ שֶׁנָּפַל בָּהּ מוּם. הִנִּיחַ יָדוֹ עַל בֶּהֱמַת חֻלִּין וְאָמַר הֲרֵי זוֹ תַּחַת זוֹ הֲרֵי זוֹ תְּמוּרָה וְלוֹקֶה. הִנִּיחַ יָדוֹ עַל בֶּהֱמַת הֶקְדֵּשׁ וְאָמַר הֲרֵי זוֹ תַּחַת זוֹ הֲרֵי זֶה חִלְּלָהּ עַל בֶּהֱמַת הַחֻלִּין וְאֵין זוֹ תְּמוּרָה אֶלָּא כְּפוֹדֶה בַּעֲלַת מוּם בְּזוֹ הַבְּהֵמָה:","הָיוּ לְפָנָיו שָׁלֹשׁ בְּהֵמוֹת קָדְשֵׁי מִזְבֵּחַ וְאַחַת מֵהֶן בַּעֲלַת מוּם שֶׁהֲרֵי הִיא עוֹמֶדֶת לְפִדְיוֹן וְשָׁלֹשׁ בְּהֵמוֹת תְּמִימוֹת חֻלִּין וְאָמַר הֲרֵי אֵלּוּ תַּחַת אֵלּוּ. הֲרֵי שְׁתַּיִם מִן הַחֻלִּין תַּחַת שְׁתַּיִם הַתְּמִימוֹת תְּמוּרָתָן תְּמוּרָה וְלוֹקֶה עֲלֵיהֶם שְׁתַּיִם. וְהַבְּהֵמָה הַשְּׁלִישִׁית הִיא תַּחַת בַּעֲלַת מוּם שֶׁנִּתְחַלְּלָה עָלֶיהָ וּלְחַלְּלָהּ נִתְכַּוֵּן וְלֹא לְהָמִיר בָּהּ. שֶׁכֵּיוָן שֶׁיֵּשׁ לְפָנָיו דֶּרֶךְ אִסּוּר וְהִיא הַתְּמוּרָה וְדֶרֶךְ הֶתֵּר וְהוּא הַחִלּוּל חֲזָקָה הִיא שֶׁאֵין אָדָם מַנִּיחַ הַהֶתֵּר וְעוֹשֶׂה הָאִסּוּר וּלְפִיכָךְ אֵינוֹ לוֹקֶה שָׁלֹשׁ מַלְקִיּוֹת. וְכֵן אִם אָמַר עֶשֶׂר בְּהֵמוֹת אֵלּוּ תַּחַת עֶשֶׂר בְּהֵמוֹת אֵלּוּ וְאַחַת מֵהֶן בַּעֲלַת מוּם אֵינוֹ לוֹקֶה אֶלָּא תֵּשַׁע מַלְקִיּוֹת שֶׁהַבְּהֵמָה הָעֲשִׂירִית לְחַלְּלָהּ נִתְכַּוֵּן וְלֹא לְהָמִיר בָּהּ. שֶׁאַף עַל פִּי שֶׁהֻחְזַק זֶה בְּמַלְקִיּוֹת הַרְבֵּה הוֹאִיל וְיֵשׁ שָׁם דֶּרֶךְ הֶתֵּר אֵינוֹ מַנִּיחַ דְּבַר הַהֶתֵּר וְעוֹשֶׂה הָאִסּוּר. שְׁתֵּי בְּהֵמוֹת שֶׁל הֶקְדֵּשׁ וְאַחַת מֵהֶן בַּעֲלַת מוּם וּשְׁתֵּי בְּהֵמוֹת שֶׁל חֻלִּין וְאַחַת מֵהֶן בַּעֲלַת מוּם וְאָמַר הֲרֵי אֵלּוּ תַּחַת אֵלּוּ הֲרֵי הַתְּמִימָה תְּמוּרַת הַתְּמִימָה וְלוֹקֶה אַחַת וּבַעֲלַת הַמּוּם מְחֻלֶּלֶת עַל בַּעֲלַת הַמּוּם שֶׁאֵינוֹ מֵנִיחַ הַהֶתֵּר וְעוֹשֶׂה הָאִסּוּר:","הָאוֹמֵר הֲרֵי זוֹ תְּמוּרַת עוֹלָה וּשְׁלָמִים דְּבָרָיו קַיָּמִים וְתִמָּכֵר וְיָבִיא בַּחֲצִי דָּמֶיהָ תְּמוּרַת עוֹלָה וּבַחֲצִי דָּמֶיהָ תְּמוּרַת שְׁלָמִים. אָמַר הֲרֵי זוֹ תְּמוּרַת עוֹלָה וּתְמוּרַת שְׁלָמִים אִם נִתְכַּוֵּן לְכָךְ מִתְּחִלָּה דְּבָרָיו קַיָּמִים וְאִם לֹא נִתְכַּוֵּן בַּתְּחִלָּה אֶלָּא לִתְמוּרַת עוֹלָה וְחָזַר וְאָמַר תְּמוּרַת שְׁלָמִים אַף עַל פִּי שֶׁחָזַר בְּתוֹךְ כְּדֵי דִּבּוּר אֵין תּוֹפְשִׂין אֶלָּא לָשׁוֹן רִאשׁוֹן וַהֲרֵי הִיא תְּמוּרַת עוֹלָה בִּלְבַד:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 9":["אֵין עוֹשִׂין סֵפֶר תּוֹרָה לֹא אָרְכּוֹ יוֹתֵר עַל הֶקֵּפוֹ וְלֹא הֶקֵּפוֹ יָתֵר עַל אָרְכּוֹ. וְכַמָּה הוּא אָרְכּוֹ. בִּגְוִיל שִׁשָּׁה טְפָחִים שֶׁהֵם אַרְבַּע וְעֶשְׂרִים אֶצְבָּעוֹת בְּרֹחַב הַגּוּדָל שֶׁל יָד. וּבִקְלָף אוֹ פָּחוֹת אוֹ יוֹתֵר וְהוּא שֶׁיְּהֵא אָרְכּוֹ כְּהֶקֵּפוֹ. וְכֵן אִם עָשָׂה בַּגְּוִיל פָּחוֹת מִשִּׁשָׁה טְפָחִים וּמִעֵט אֶת הַכְּתָב אוֹ יִתֵּר עַל שִׁשָּׁה וְהִרְחִיב בַּכְּתָב עַד שֶׁיִּהְיֶה אָרְכּוֹ כְּהֶקֵּפוֹ הֲרֵי זֶה כַּמִּצְוָה:","שִׁעוּר הַגִּלָּיוֹן מִלְּמַטָּה אַרְבַּע אֶצְבָּעוֹת וּלְמַעְלָה שָׁלֹשׁ אֶצְבָּעוֹת וּבֵין דַּף לְדַף שְׁתֵּי אֶצְבָּעוֹת. לְפִיכָךְ צָרִיךְ שֶׁיַּנִּיחַ בִּתְחִלַּת כָּל יְרִיעָה וּבְסוֹפָהּ רֹחַב אֶצְבַּע אַחַת וּכְדֵי תְּפִירָה. שֶׁנִּמְצָא כְּשֶׁיִּתְפֹּר הַיְרִיעָה יִהְיֶה בֵּין כָּל דַּף וְדַף בְּכָל הַסֵּפֶר כֻּלּוֹ שְׁתֵּי אֶצְבָּעוֹת. וְיַנִּיחַ מִן הָעוֹר בִּתְחִלַּת הַסֵּפֶר וּבְסוֹפוֹ כְּדֵי לִגְלל עַל הָעַמּוּד. וְכָל הַשִּׁעוּרִין הָאֵלּוּ לְמִצְוָה וְאִם חִסֵּר אוֹ הוֹתִיר לֹא פָּסַל:","כֵּיצַד יִתְכַּוֵּן אָדָם עַד שֶׁיַּעֲשֶׂה הַסֵּפֶר שֶׁיִּהְיֶה אָרְכּוֹ כְּהֶקֵּפוֹ. מַתְחִיל וּמְרַבֵּעַ הָעוֹרוֹת בְּשָׁוֶה וְעוֹשֶׂה רֹחַב כָּל עוֹר מֵהֶן שִׁשָּׁה טְפָחִים, קֶצֶב אֶחָד לְכָל אֶחָד. וְאַחַר כָּךְ גּוֹלֵל הָעוֹרוֹת בְּשָׁוֶה וְעוֹשֶׂה מֵהֶן כֶּרֶךְ אֶחָד מְהֻדָּק יָפֶה יָפֶה וּמוֹסִיף בְּעוֹרוֹת וּמְהַדֵּק עַד שֶׁיֵּעָשֶׂה הֶקֵּף הַכֶּרֶךְ שִׁשָּׁה טְפָחִים שֶׁהוּא רֹחַב הָעוֹר. וּמוֹדֵד בְּחוּט שֶׁל שָׁנִי שֶׁיַּקִּיפוֹ עַל הַכֶּרֶךְ:","וְאַחַר כָּךְ יַעֲשֶׂה קָנֶה שָׁוֶה יִהְיֶה אָרְכָּהּ אַרְבָּעִים אוֹ חֲמִשִּׁים אֶצְבָּעוֹת וִיחַלֵּק אֶצְבַּע מֵהֶן בַּקָּנֶה לִשְׁנַיִם וְלִשְׁלֹשָׁה וּלְאַרְבָּעָה חֲלָקִים כְּדֵי שֶׁיֵּדַע בּוֹ שִׁעוּר חֲצִי אֶצְבַּע וּרְבִיעַ אֶצְבַּע וְכַיּוֹצֵא בְּזֶה הַחֵלֶק. וְיִמְדֹּד כָּל עוֹר בְּקָנֶה זוֹ עַד שֶׁיֵּדַע כַּמָּה אֶצְבָּעוֹת יֵשׁ בְּכָל עוֹר עַד שֶׁיֵּדַע כַּמָּה אֶצְבָּעוֹת בְּאֹרֶךְ כָּל הַכֶּרֶךְ:","וְאַחַר כָּךְ לוֹקֵחַ עוֹרוֹת אֲחֵרוֹת שְׁנַיִם אוֹ שְׁלֹשָׁה לִבְדֹּק בָּהֶן שִׁעוּר הַכְּתָב וְכוֹתֵב בָּהֶן דַּף אֶחָד. וְדָבָר יָדוּעַ שֶׁאֹרֶךְ הַדַּף שְׁבַע עֶשְׂרֵה אֶצְבָּעוֹת. לְפִי שֶׁהוּא מַנִּיחַ גִּלָּיוֹן לְמַעְלָה שָׁלֹשׁ וּלְמַטָּה אַרְבַּע. אֲבָל רֹחַב הַדַּף הוּא לְפִי הַכְּתָב אִם דַּקָּה אִם עָבָה. וְכֵן מִנְיַן הַשִּׁיטוֹת שֶׁבַּדַּף יָבוֹאוּ לְפִי הַכְּתָב לְפִי שֶׁבֵּין שִׁיטָה וְשִׁיטָה כִּמְלֹא שִׁיטָה:","וְאַחַר שֶׁכָּתַב הַדַּף שֶׁבּוֹדֵק בּוֹ לְפִי מַה שֶּׁיִּרְצֶה יָמֹד רֹחַב הַדַּף בְּאֶצְבְּעוֹת הַקָּנֶה וְיוֹסִיף עַל רֹחַב הַדַּף שְׁתֵּי אֶצְבָּעוֹת שֶׁבֵּין דַּף וְדַף וְיַחֲשֹׁב כַּמָּה דַּפִּין יָבֹאוּ בַּכֶּרֶךְ שֶׁגָּלַל מֵאוֹתוֹ הַכְּתָב שֶׁבָּדַק בּוֹ וְיֵדַע חֶשְׁבּוֹן הַדַּפִּין וְיִרְאֶה כַּמָּה נִכְתַּב בְּדַף זֶה שֶׁבָּדַק בּוֹ מִן הַתּוֹרָה כֻּלָּהּ. וּמְשַׁעֵר לְפִי הַסֵּפֶר שֶׁהוּא כּוֹתֵב מִמֶּנּוּ וּמְחַשֵּׁב אִם עָלְתָה לוֹ כָּל הַתּוֹרָה לְפִי מִנְיַן הַדַּפִּין מִזֶּה הַכְּתָב שֶׁכּוֹתֵב בּוֹ בְּכֶרֶךְ מוּטָב. וְאִם הוֹצִיא הַחֶשְׁבּוֹן שֶׁהַדַּפִּין יוֹתֵר מִן הַתּוֹרָה יַרְחִיב בַּכְּתָב עַד שֶׁיִּתְמַעֵט מִנְיַן הַדַּפִּין וְיִבְדֹק בְּדַף אַחֵר. וְאִם הוֹצִיא הַחֶשְׁבּוֹן שֶׁהַתּוֹרָה יָתֵר מִן הַדַּפִּין יְמַעֵט הַכְּתָב עַד שֶׁיַּרְבֶּה בְּמִנְיַן הַדַּפִּין וְיִבְדֹק בְּדַף אַחַר דַּף עַד שֶׁיָּבוֹא הַחֶשְׁבּוֹן אֶחָד. מֵאַחַר שֶׁיָּדַע רֹחַב הַדַּף וְשִׁעוּר הַכְּתָב מַתְחִיל בְּאוֹתוֹ הַכֶּרֶךְ:","וּמְחַלֵּק כָּל עוֹר וְעוֹר דַּפִּין דַּפִּין בְּשִׂרְטוּט כְּפִי רֹחַב הַדַּף שֶׁבָּדַק בּוֹ וְעָלָה בַּחֶשְׁבּוֹן. וּכְשֶׁיִּשָּׁאֵר בָּעוֹר שָׁלֹשׁ אֶצְבָּעוֹת אוֹ אַרְבַּע יוֹתֵר עַל הַדַּף הָאַחֲרוֹנָה שֶׁבַּיְרִיעָה יַנִּיחַ מִמֶּנּוּ רֹחַב אֶצְבַּע וּכְדֵי תְּפִירָה וְיָקֹץ הַשְּׁאָר וְאַל יָחוּשׁ, שֶׁבָּאַחֲרוֹנָה יִתְוַסֵּף עוֹרוֹת אֲחֵרוֹת עַל הַכֶּרֶךְ שֶׁגָּלַל כְּנֶגֶד כָּל הַתּוֹסָפוֹת שֶׁקּוֹצֵץ מִכָּל עוֹר וְעוֹר וְאֵינוֹ צָרִיךְ לְחַשֵּׁב דָּבָר זֶה, שֶׁהַכְּתָב מוֹשְׁכוֹ לְפִי מִנְיַן הַדַּפִּין:","וְכֵן הָרוֹצֶה לַעֲשׂוֹת רֹחַב הַסֵּפֶר יוֹתֵר מִשִּׁשָּׁה אוֹ פָּחוֹת מִשִּׁשָּׁה עַל הַדֶּרֶךְ הַזֶּה הוּא מְחַשֵּׁב וְיֵצֵא אָרְכּוֹ כְּהֶקֵּפוֹ בְּלֹא פָּחוֹת וְלֹא יוֹתֵר. וְהוּא שֶׁלֹּא יִטְעֶה בַּחֶשְׁבּוֹן:","רֹחַב הַגּוּדָל הָאָמוּר בְּכָל הַשִּׁעוּרִין הָאֵלּוּ וּבִשְׁאָר שִׁעוּרֵי תּוֹרָה כֻּלָּהּ הוּא אֶצְבַּע הַבֵּינוֹנִי. וּכְבָר דִּקְדַּקְנוּ בְּשִׁעוּרוֹ וּמְצָאנוּהוּ רָחָב שֶׁבַע שְׂעוֹרוֹת בֵּינוֹנִיּוֹת זוֹ בְּצַד זוֹ בְּדֹחַק וְהֵן כְּאֹרֶךְ שְׁתֵּי שְׂעוֹרוֹת בְּרֶוַח. וְכָל טֶפַח הָאָמוּר בְּכָל מָקוֹם הוּא אַרְבַּע אֶצְבָּעוֹת מִזּוֹ. וְכָל אַמָּה שִׁשָּׁה טְפָחִים:","סֵפֶר תּוֹרָה שֶׁכָּתַבְתִּי אֲנִי רֹחַב כָּל דַּף וְדַף מִדַּפָּיו אַרְבַּע אֶצְבָּעוֹת. וְשִׁירַת הַיָּם וְשִׁירַת הַאֲזִינוּ רֹחַב כָּל דַּף מִשְּׁתֵּיהֶן שֵׁשׁ אֶצְבָּעוֹת. וּמִנְיַן הַשִּׁיטִין שֶׁבְּכָל דַּף וְדַף אַחַת וַחֲמִשִּׁים. וּמִנְיַן הַדַּפִּין שֶׁל כָּל הַסֵּפֶר מָאתַיִם וְשִׁשָּׁה וְעֶשְׂרִים דַּף. וְאֹרֶךְ כָּל הַסֵּפֶר אֶלֶף וּשְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וְשֵׁשׁ אֶצְבָּעוֹת בְּקֵרוּב:","אֵלּוּ הַשֵּׁשׁ אֶצְבָּעוֹת הַיְתֵרוֹת בְּחֶשְׁבּוֹן לַגִּלָּיוֹן שֶׁבִּתְחִלַּת הַסֵּפֶר וְסוֹפוֹ. וְהָעוֹרוֹת שֶׁכָּתַבְנוּ בָּהֶם עוֹרוֹת אֵילִים. וּבִזְמַן שֶׁתִּרְצֶה לִכְתֹּב עַל פִּי הַמִּדּוֹת הָאֵלּוּ אוֹ קָרוֹב לָהֶם מְעַט הֵן חָסֵר דַּף אֶחָד אוֹ שְׁנַיִם אוֹ שְׁלֹשָׁה אוֹ יָתֵר דַּף אוֹ שְׁנַיִם אוֹ שָׁלֹשׁ לֹא תִּיגַע וְלֹא תְּהֵא צָרִיךְ לְחֶשְׁבּוֹן אֶלָּא מִיָּד יָבוֹא לְךָ אָרְכּוֹ כְּהֶקֵּפוֹ:","אֵין עוֹשִׂין בִּירִיעָה פָּחוֹת מִשְּׁלֹשָׁה דַּפִּין וְלֹא יָתֵר עַל שְׁמוֹנָה דַּפִּין. נִזְדַּמְּנָה לוֹ יְרִיעָה בַּת תִּשְׁעָה דַּפִּין חוֹלֵק אוֹתָהּ אַרְבָּעָה לְכָאן וַחֲמִשָּׁה לְכָאן. בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְחִלַּת הַסֵּפֶר אוֹ בְּאֶמְצַע אֲבָל בְּסוֹף הַסֵּפֶר אֲפִלּוּ פָּסוּק אֶחָד בְּדַף אֶחָד עוֹשִׂים אוֹתוֹ דַּף לְבַדּוֹ וְתוֹפְרִין אוֹתוֹ עִם שְׁאָר הַיְרִיעוֹת:","וּכְשֶׁתּוֹפְרִין הַיְרִיעוֹת אֵין תּוֹפְרִין אוֹתָן אֶלָּא בְּגִידִים שֶׁל בְּהֵמָה אוֹ חַיָּה טְהוֹרָה וַאֲפִלּוּ מִנְּבֵלוֹת וּטְרֵפוֹת שֶׁלָּהֶם כְּדֶרֶךְ שֶׁתּוֹפְרִין אֶת הַתְּפִלִּין. וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי. לְפִיכָךְ אִם תְּפָרָן שֶׁלֹּא בְּגִידִין אוֹ בְּגִידֵי בְּהֵמָה טְמֵאָה פָּסוּל עַד שֶׁיַּתִּירָהּ וְיַחֲזֹר וְיִתְפֹּר כַּהֲלָכָה:","כְּשֶׁתּוֹפְרִין כָּל הַיְרִיעוֹת אֵין תּוֹפְרִין כָּל הַיְרִיעָה כֻּלָּהּ מִתְּחִלָּתָהּ וְעַד סוֹפָהּ אֶלָּא מַנִּיחַ מְעַט מִלְּמַעְלָה וּמְעַט מִלְּמַטָּה בְּלֹא תְּפִירָה כְּדֵי שֶׁלֹּא תִּקָּרַע הַיְרִיעָה בְּאֶמְצָעָהּ כְּשֶׁיִּגְלל אוֹתָהּ. וְעוֹשֶׂה לוֹ שְׁנֵי עַמּוּדִים שֶׁל עֵץ אֶחָד בִּתְחִלָּתוֹ וְאֶחָד בְּסוֹפוֹ. וְתוֹפֵר הָעוֹר שֶׁשִּׁיֵּר בִּתְחִלָּתוֹ וּבַסּוֹף עַל הָעַמּוּדִים בְּגִידִים כְּדֵי שֶׁיְּהֵא נִגְלָל עֲלֵיהֶם. וְיַרְחִיק בֵּין הָעַמּוּדִים וְהַכְּתָב שֶׁבַּדַּף:","סֵפֶר תּוֹרָה שֶׁנִּקְרְעָה בּוֹ יְרִיעָה בְּתוֹךְ שְׁתֵּי שִׁיטוֹת יִתְפֹּר. בְּתוֹךְ שָׁלֹשׁ לֹא יִתְפֹּר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּיָשָׁן שֶׁאֵין עֲפָצוֹ נִכָּר אֲבָל אִם נִכָּר הַגְּוִיל שֶׁהוּא עָפוּץ תּוֹפֵר וַאֲפִלּוּ קֶרַע הַבָּא בְּתוֹךְ שָׁלֹשׁ. וְכֵן בֵּין כָּל דַּף וְדַף וּבֵין תֵּבָה לְתֵבָה יִתְפֹּר. וְכָל הַקְּרָעִים אֵין תּוֹפְרִין אוֹתָן אֶלָּא בְּגִידִין שֶׁתּוֹפְרִין בָּהֶן הַיְרִיעוֹת זוֹ לָזוֹ. וּבְכָל הַקְּרָעִים יִזָּהֵר שֶׁלֹּא תֶּחְסַר אוֹת אַחַת אוֹ תִּשְׁתַּנֶּה צוּרָתָהּ:"],"Mishneh Torah, Testimony 2":["מַה בֵּין חֲקִירוֹת וּדְרִישׁוֹת לִבְדִיקוֹת. בַּחֲקִירוֹת וּדְרִישׁוֹת אִם כִּוֵּן הָאֶחָד אֶת עֵדוּתוֹ וְהַשֵּׁנִי אוֹמֵר אֵינִי יוֹדֵעַ עֵדוּתָן בְּטֵלָה. אֲבָל בִּבְדִיקוֹת אֲפִלּוּ שְׁנֵיהֶן אוֹמְרִין אֵין אָנוּ יוֹדְעִין עֵדוּתָן קַיֶּמֶת. וּבִזְמַן שֶׁהֵן מַכְחִישִׁין זֶה אֶת זֶה אֲפִלּוּ בִּבְדִיקוֹת עֵדוּתָן בְּטֵלָה. כֵּיצַד. הֵעִידוּ שֶׁהָרַג זֶה אֶת זֶה וְאָמַר הָאֶחָד כְּשֶׁנֶּחְקַר בְּשָׁבוּעַ פְּלוֹנִי. בְּשָׁנָה פְּלוֹנִית. בְּחֹדֶשׁ פְּלוֹנִי. בְּכָךְ וְכָךְ בְּחֹדֶשׁ. בִּרְבִיעִי בְּשַׁבָּת. בְּשֵׁשׁ שָׁעוֹת בַּיּוֹם. בְּמָקוֹם פְּלוֹנִי הֲרָגוֹ. וְכֵן כְּשֶׁדָּרְשׁוּ בַּמֶּה הֲרָגוֹ אָמַר הֲרָגוֹ בְּסַיִף. וְכֵן הָעֵד הַשֵּׁנִי כִּוֵּן עֵדוּתוֹ בַּכּל חוּץ מִן הַשָּׁעוֹת שֶׁאָמַר אֵינִי יוֹדֵעַ בְּכַמָּה שָׁעוֹת הָיָה בַּיּוֹם. אוֹ שֶׁכִּוֵּן אֶת הַשָּׁעוֹת וְאָמַר אֵינִי יוֹדֵעַ בַּמֶּה הֲרָגוֹ וְלֹא הֵבַנְתִּי בַּכְּלִי שֶׁהָיָה בְּיָדוֹ. הֲרֵי עֵדוּתָן בְּטֵלָה. אֲבָל אִם כִּוְּנוּ הַכּל וְאָמְרוּ לָהֶן הַדַּיָּנִים כֵּלָיו הָיוּ שְׁחוֹרִים אוֹ לְבָנִים וְאָמְרוּ אֵין אָנוּ יוֹדְעִים וְלֹא שַׂמְנוּ לִבֵּנוּ לִדְבָרִים אֵלּוּ שֶׁאֵין בָּהֶן מַמָּשׁ הֲרֵי עֵדוּתָן קַיֶּמֶת:","אָמַר אֶחָד כֵּלִים שְׁחוֹרִים הָיָה לָבוּשׁ וְהַשֵּׁנִי אָמַר לֹא כֵן אֶלָּא לְבָנִים הָיָה לָבוּשׁ הֲרֵי עֵדוּתָן בְּטֵלָה. וּכְאִלּוּ אָמַר אֶחָד בִּרְבִיעִי בְּשַׁבָּת וְהַשֵּׁנִי בַּחֲמִישִׁי שֶׁאֵין כָּאן עֵדוּת. אוֹ שֶׁאָמַר הָאֶחָד בְּסַיִף הֲרָגוֹ וְהַשֵּׁנִי אָמַר בְּרֹמַח שֶׁאֵין כָּאן עֵדוּת. שֶׁנֶּאֱמַר (דברים יג טו) \"נָכוֹן הַדָּבָר\" וְכֵיוָן שֶׁהִכְחִישׁוּ זֶה אֶת זֶה בְּאֵי זֶה מִכָּל הַדְּבָרִים אֵין זֶה נָכוֹן:","הָיוּ הָעֵדִים מְרֻבִּים שְׁנַיִם מֵהֶן כִּוְּנוּ עֵדוּתָן בַּחֲקִירוֹת וּבִדְרִישׁוֹת וְהַשְּׁלִישִׁי אוֹמֵר אֵינִי יוֹדֵעַ תִּתְקַיֵּם הָעֵדוּת בִּשְׁנַיִם וְיֵהָרֵג. אֲבָל אִם הִכְחִישׁ אֶת שְׁנֵיהֶן אֲפִלּוּ בִּבְדִיקוֹת עֵדוּתָן בְּטֵלָה:","עֵד אֶחָד אוֹמֵר בִּרְבִיעִי בְּשַׁבָּת בִּשְׁנַיִם לַחֹדֶשׁ וְהַשֵּׁנִי אוֹמֵר בִּרְבִיעִי בְּשַׁבָּת בִּשְׁלֹשָׁה לַחֹדֶשׁ עֵדוּתָן קַיֶּמֶת. שֶׁזֶּה יוֹדֵעַ בְּעִבּוּרוֹ שֶׁל חֹדֶשׁ וְזֶה אֵינוֹ יוֹדֵעַ. בַּמֶּה דְּבָרִים אֲמוּרִים עַד חֲצוֹת הַחֹדֶשׁ. אֲבָל אַחַר חֲצוֹת הַחֹדֶשׁ כְּגוֹן שֶׁאָמַר הָאֶחָד בְּשִׁשָּׁה עָשָׂר בַּחֹדֶשׁ וְהַשֵּׁנִי אוֹמֵר בְּשִׁבְעָה עָשָׂר בַּחֹדֶשׁ אַף עַל פִּי שֶׁכִּוְּנוּ שְׁנֵיהֶם יוֹם אֶחָד מִימֵי הַשַּׁבָּת עֵדוּתָן בְּטֵלָה. שֶׁאֵין חֲצִי הַחֹדֶשׁ בָּא וּכְבָר יָדְעוּ הַכּל אֵימָתַי הָיָה רֹאשׁ הַחֹדֶשׁ:","אָמַר הָאֶחָד בִּשְׁלֹשָׁה וְהַשֵּׁנִי אוֹמֵר בַּחֲמִשָּׁה עֵדוּתָן בְּטֵלָה. אָמַר עֵד אֶחָד בִּשְׁתֵּי שָׁעוֹת בַּיּוֹם וְהַשֵּׁנִי אוֹמֵר בְּשָׁלֹשׁ שָׁעוֹת הֲרֵי עֵדוּתָן קַיֶּמֶת שֶׁדֶּרֶךְ הָעָם לִטְעוֹת בְּשָׁעָה אַחַת. אֲבָל אִם אָמַר הָאֶחָד בְּשָׁלֹשׁ שָׁעוֹת וְהַשֵּׁנִי אוֹמֵר בְּחָמֵשׁ עֵדוּתָן בְּטֵלָה. אָמַר עֵד אֶחָד קֹדֶם הָנֵץ הַחַמָּה וְאֶחָד אוֹמֵר בְּהָנֵץ הַחַמָּה עֵדוּתָן בְּטֵלָה אַף עַל פִּי שֶׁהִיא שָׁעָה אַחַת שֶׁהַדָּבָר נִכָּר לַכּל. וְכֵן אִם נֶחְלְקוּ בִּשְׁקִיעָתָהּ:"],"Mishneh Torah, The Chosen Temple 2":["הַמִּזְבֵחַ מְקוֹמוֹ מְכֻוָּן בְּיוֹתֵר. וְאֵין מְשַׁנִּין אוֹתוֹ מִמְּקוֹמוֹ לְעוֹלָם. שֶׁנֶּאֱמַר (דברי הימים א כב א) \"זֶה מִזְבַּח לְעוֹלָה לְיִשְׂרָאֵל\". וּבַמִּקְדָּשׁ נֶעֱקַד יִצְחָק אָבִינוּ שֶׁנֶּאֱמַר (בראשית כב ב) \"וְלֶךְ לְךָ אֶל אֶרֶץ הַמֹּרִיָּה\". וְנֶאֱמַר בְּדִבְרֵי הַיָּמִים (דברי הימים ב ג א) \"וַיָּחֶל שְׁלֹמֹה לִבְנוֹת אֶת בֵּית ה' בִּירוּשָׁלַיִם בְּהַר הַמּוֹרִיָּה אֲשֶׁר נִרְאָה לְדָוִיד אָבִיהוּ אֲשֶׁר הֵכִין בִּמְקוֹם דָּוִיד בְּגֹרֶן אָרְנָן הַיְבוּסִי\":","וּמָסֹרֶת בְּיַד הַכּל שֶׁהַמָּקוֹם שֶׁבָּנָה בּוֹ דָּוִד וּשְׁלֹמֹה הַמִּזְבֵּחַ בְּגֹרֶן אֲרַוְנָה הוּא הַמָּקוֹם שֶׁבָּנָה בּוֹ אַבְרָהָם הַמִּזְבֵּחַ וְעָקַד עָלָיו יִצְחָק. וְהוּא הַמָּקוֹם שֶׁבָּנָה בּוֹ נֹחַ כְּשֶׁיָּצָא מִן הַתֵּבָה. וְהוּא הַמִּזְבֵּחַ שֶׁהִקְרִיב עָלָיו קַיִן וְהֶבֶל. וּבוֹ הִקְרִיב אָדָם הָרִאשׁוֹן קָרְבָּן כְּשֶׁנִּבְרָא וּמִשָּׁם נִבְרָא. אָמְרוּ חֲכָמִים אָדָם מִמְּקוֹם כַּפָּרָתוֹ נִבְרָא:","מִדּוֹת הַמִּזְבֵּחַ מְכֻוָּנוֹת הַרְבֵּה וְצוּרָתוֹ יְדוּעָה אִישׁ מֵאִישׁ. וּמִזְבֵּחַ שֶׁבָּנוּ בְּנֵי הַגּוֹלָה כְּעֵין מִזְבֵּחַ שֶׁעָתִיד לְהִבָּנוֹת עָשׂוּהוּ וְאֵין לְהוֹסִיף עַל מִדָּתוֹ וְלֹא לִגְרֹעַ מִמֶּנָּה:","וּשְׁלֹשָׁה נְבִיאִים עָלוּ עִמָּהֶם מִן הַגּוֹלָה. אֶחָד הֵעִיד לָהֶן עַל מְקוֹם הַמִּזְבֵּחַ. וְאֶחָד הֵעִיד לָהֶן עַל מִדּוֹתָיו. וְאֶחָד הֵעִיד לָהֶן שֶׁמַּקְרִיבִין עַל הַמִּזְבֵּחַ הַזֶּה כָּל הַקָּרְבָּנוֹת אַף עַל פִּי שֶׁאֵין שָׁם בַּיִת:","מִזְבֵּחַ שֶׁעָשָׂה משֶׁה וְשֶׁעָשָׂה שְׁלֹמֹה וְשֶׁעָשׂוּ בְּנֵי הַגּוֹלָה וְשֶׁעָתִיד לְהֵעָשׂוֹת כֻּלָּן עֶשֶׂר אַמּוֹת גֹּבַהּ כָּל אֶחָד מֵהֶן. וְזֶה הַכָּתוּב בַּתּוֹרָה (שמות כז א) \"וְשָׁלֹשׁ אַמּוֹת קוֹמָתוֹ\" מְקוֹם הַמַּעֲרָכָה בִּלְבַד. וּמִזְבֵּחַ שֶׁעָשׂוּ בְּנֵי הַגּוֹלָה וְכֵן הֶעָתִיד לְהִבָּנוֹת מִדַּת אָרְכּוֹ וְרָחְבּוֹ ל\"ב אַמּוֹת עַל ל\"ב אַמּוֹת:","עֶשֶׂר אַמּוֹת שֶׁל גֹּבַהּ הַמִּזְבֵּחַ מֵהֶן בְּאַמָּה בַּת חֲמִשָּׁה טְפָחִים וּמֵהֶן בְּאַמָּה בַּת שִׁשָּׁה טְפָחִים. וּשְׁאָר כָּל אַמּוֹת הַבִּנְיָן בְּאַמָּה בַּת שִׁשָּׁה טְפָחִים. וְגֹבַהּ כָּל הַמִּזְבֵּחַ נ\"ח טְפָחִים:","וְכָךְ הָיְתָה מִדָּתוֹ וְצוּרָתוֹ. עָלָה חֲמִשָּׁה טְפָחִים וְכָנַס חֲמִשָּׁה טְפָחִים זֶהוּ יְסוֹד. נִמְצָא רֹחַב שְׁלֹשִׁים אַמָּה וּשְׁנֵי טְפָחִים עַל רֹחַב שְׁלֹשִׁים אַמָּה וּשְׁנֵי טְפָחִים. עָלָה שְׁלֹשִׁים טְפָחִים וְכָנַס חֲמִשָּׁה טְפָחִים זֶהוּ סוֹבֵב [עָלָה י\"ח טְפָחִים זֶהוּ מְקוֹם הַמַּעֲרָכָה] נִמְצָא רָחְבּוֹ שְׁמוֹנֶה וְעֶשְׂרִים אַמָּה וְאַרְבָּעָה טְפָחִים עַל שְׁמוֹנֶה וְעֶשְׂרִים אַמָּה וְאַרְבָּעָה טְפָחִים [עָלָה י\"ח טְפָחִים וְכוֹנֵס לְקֶרֶן זָוִית שֶׁל הַי\"ח בִּנְיָן חָלוּל מְרֻבָּע לְכָל אַרְבַּע קְרָנוֹת] וּמְקוֹם הַקְּרָנוֹת אַמָּה מִזֶּה וְאַמָּה מִזֶּה סָבִיב. וְכֵן מְקוֹם רַגְלֵי הַכֹּהֲנִים אַמָּה סָבִיב. נִמְצָא מְקוֹם הַמַּעֲרָכָה רָחְבּוֹ עֶשְׂרִים וְאַרְבַּע אַמּוֹת וְאַרְבָּעָה טְפָחִים עַל עֶשְׂרִים וְאַרְבַּע אַמּוֹת וְאַרְבָּעָה טְפָחִים:","גֹּבַהּ כָּל קֶרֶן וְקֶרֶן חֲמִשָּׁה טְפָחִים. וְרִבּוּעַ כָּל קֶרֶן אַמָּה עַל אַמָּה. וְאַרְבַּע הַקְּרָנוֹת חֲלוּלוֹת הָיוּ מִתּוֹכָן. וְגֹבַהּ מְקוֹם הַמַּעֲרָכָה י\"ח טְפָחִים. נִמְצָא חֲצִי גֹּבַהּ הַמִּזְבֵּחַ כ\"ט טְפָחִים מִסּוֹף הַסּוֹבֵב וּלְמַטָּה:","וְחוּט שֶׁל סִקְרָה הָיָה חוֹגֵר בְּאֶמְצַע הַמִּזְבֵּחַ [כְּשִׁשָּׁה טְפָחִים מִסּוֹף הַסּוֹבֵב וּלְמַטָּה] לְהַבְדִּיל בֵּין דָּמִים הָעֶלְיוֹנִים לְדָמִים הַתַּחְתּוֹנִים. וְנִמְצָא גָּבְהוֹ מִן הָאָרֶץ עַד מְקוֹם הַמַּעֲרָכָה תֵּשַׁע אַמּוֹת פָּחוֹת טֶפַח:","יְסוֹד הַמִּזְבֵּחַ לֹא הָיָה מַקִּיף מֵאַרְבַּע רוּחוֹתָיו כְּמוֹ הַסּוֹבֵב. אֶלָּא הָיָה הַיְסוֹד מָשׁוּךְ כְּנֶגֶד כָּל רוּחַ צָפוֹן וּמַעֲרָבִי וְאוֹכֵל בַּדָּרוֹם אַמָּה אַחַת וּבַמִּזְרָח אַמָּה אַחַת. וְקֶרֶן דְּרוֹמִית מִזְרָחִית לֹא הָיָה לָהּ יְסוֹד:","וּבְקֶרֶן מַעֲרָבִית דְּרוֹמִית הָיוּ שְׁנֵי נְקָבִים כְּמִין שֵׁנִי חֳטָמִין דַּקִּין. וְהֵן הַנִּקְרָאִין שִׁיתִין שֶׁהַדָּמִים יוֹרְדִין בָּהֶן וּמִתְעָרְבִין בְּאוֹתָהּ הַקֶּרֶן בָּאַמָּה וְיוֹצְאִין לַנַּחַל קִדְרוֹן:","וּלְמַטָּה בָּרִצְפָּה בְּאוֹתוֹ הַקֶּרֶן הָיָה מְקוֹם אַמָּה עַל אַמָּה וְטַבְלָא שֶׁל שַׁיִשׁ וְטַבַּעַת קְבוּעָה בָּהּ שֶׁבּוֹ יוֹרְדִין לַשִּׁיתִין וּמְנַקִּין אוֹתוֹ:","וְכֶבֶשׁ הָיָה בָּנוּי לִדְרוֹמוֹ שֶׁל מִזְבֵּחַ. אָרְכּוֹ שְׁלֹשִׁים וּשְׁתַּיִם אַמָּה עַל רֹחַב ט\"ז אַמָּה וְהָיָה אוֹכֵל בָּאָרֶץ שְׁלֹשִׁים אַמָּה מִצַּד הַמִּזְבֵּחַ. וּפוֹרֵחַ מִמֶּנָּה אַמָּה עַל הַיְסוֹד וְאַמָּה עַל הַסּוֹבֵב. וַאֲוִיר מְעַט הָיָה מַפְסִיק בֵּין הַכֶּבֶשׁ לַמִּזְבֵּחַ כְּדֵי לִתֵּן הָאֵיבָרִים לַמִּזְבֵּחַ בִּזְרִיקָה. וְגֹבַהּ הַכֶּבֶשׁ תֵּשַׁע אַמּוֹת פָּחוֹת שְׁתוּת עַד כְּנֶגֶד הַמַּעֲרָכָה:","וּשְׁנֵי כְּבָשִׁים קְטַנִּים יוֹצְאִים מִמֶּנּוּ שֶׁבָּהֶם פּוֹנִים לַיְסוֹד וְלַסּוֹבֵב וּמֻבְדָּלִין מִן הַמִּזְבֵּחַ כִּמְלֹא נִימָא. וְחַלּוֹן הָיְתָה בְּמַעֲרָבוֹ שֶׁל כֶּבֶשׁ אַמָּה עַל אַמָּה וּרְבוּבָה הָיְתָה נִקְרֵאת. שֶׁבָּהּ נוֹתְנִין פְּסוּלֵי חַטַּאת הָעוֹף עַד שֶׁתַּעֲבֹר צוּרָתָהּ וְתֵצֵא לְבֵית הַשְּׂרֵפָה:","וּשְׁנֵי שֻׁלְחָנוֹת הָיוּ בְּמַעֲרַב הַכֶּבֶשׁ אֶחָד שֶׁל שַׁיִשׁ שֶׁנּוֹתְנִין עָלָיו אֶת הָאֵיבָרִים וְאֶחָד שֶׁל כֶּסֶף שֶׁנּוֹתְנִין עָלָיו כְּלֵי הַשָּׁרֵת:","כְּשֶׁבּוֹנִין הַמִּזְבֵּחַ בּוֹנִין אוֹתוֹ כֻּלּוֹ אָטוּם כְּמִין עַמּוּד וְאֵין עוֹשִׂין בּוֹ חָלָל כְּלָל. אֶלָּא מֵבִיא אֲבָנִים שְׁלֵמוֹת גְּדוֹלוֹת וּקְטַנּוֹת וּמֵבִיא סִיד וְזֶפֶת וְקוּנְיָא וּמְמַחֶה וְשׁוֹפַךְ לְתוֹךְ מַלְבֵּן גָּדוֹל כְּמִדָּתוֹ וּבוֹנֶה וְעוֹלֶה. וְנוֹתֵן בְּתוֹךְ הַבִּנְיָן גּוּף שֶׁל עֵץ אוֹ אֶבֶן בְּקֶרֶן דְּרוֹמִית מִזְרָחִית כְּמִדַּת הַיְסוֹד. וְכֵן נוֹתֵן בְּתוֹךְ כָּל קֶרֶן וְקֶרֶן עַד שֶׁיַּשְׁלִים הַבִּנְיָן וְיָסִיר הַגּוּפִים שֶׁבְּתוֹךְ הַבִּנְיָן כְּדֵי שֶׁתִּשָּׁאֵר קֶרֶן דְּרוֹמִית מִזְרָחִית בְּלֹא יְסוֹד וְיִשָּׁאֲרוּ הַקְּרָנוֹת חֲלוּלִין:","אַרְבַּע קְרָנוֹת שֶׁל מִזְבֵּחַ וִיסוֹדוֹ וְרִבּוּעוֹ מְעַכְּבִין. וְכָל מִזְבֵּחַ שֶׁאֵין לוֹ קֶרֶן יְסוֹד וְכֶבֶשׁ וְרִבּוּעַ הֲרֵי הוּא פָּסוּל שֶׁאַרְבַּעְתָּן מְעַכְּבִין. אֲבָל מִדַּת אָרְכּוֹ וּמִדַּת רָחְבּוֹ וּמִדַּת קוֹמָתוֹ אֵינָן מְעַכְּבִין. וְהוּא שֶׁלֹּא יִפְחֹת מֵאַמָּה עַל אַמָּה בְּרוּם שָׁלֹשׁ אַמּוֹת כְּשִׁעוּר מְקוֹם הַמַּעֲרָכָה שֶׁל מִזְבַּח מִדְבָּר:","מִזְבֵּחַ שֶׁנִּפְגַּם מִבִּנְיָנוֹ אִם נִפְגַּם מִבִּנְיָנוֹ טֶפַח פָּסוּל פָּחוֹת מִטֶּפַח כָּשֵׁר וְהוּא שֶׁלֹּא יִהְיֶה בַּנִּשְׁאָר אֶבֶן פְּגוּמָה:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 1":["מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה לְמַנּוֹת שׁוֹפְטִים וְשׁוֹטְרִים בְּכָל מְדִינָה וּמְדִינָה וּבְכָל פֶּלֶךְ וּפֶלֶךְ שֶׁנֶּאֱמַר (דברים טז יח) \"שֹׁפְטִים וְשֹׁטְרִים תִּתֶּן לְךָ בְּכָל שְׁעָרֶיךָ\". שׁוֹפְטִים אֵלּוּ הַדַּיָּנִים הַקְּבוּעִין בְּבֵית דִּין וּבַעֲלֵי דִּינִין בָּאִים לִפְנֵיהֶם. שׁוֹטְרִים אֵלּוּ בַּעֲלֵי מַקֵּל וּרְצוּעָה וְהֵם עוֹמְדִים לִפְנֵי הַדַּיָּנִין הַמְסַבְּבִין בַּשְּׁוָקִים וּבָרְחוֹבוֹת וְעַל הַחֲנֻיּוֹת לְתַקֵּן הַשְּׁעָרִים וְהַמִּדּוֹת וּלְהַכּוֹת כָּל מְעַוֵּת וְכָל מַעֲשֵׂיהֶם עַל פִּי הַדַּיָּנִים וְכָל שֶׁיִּרְאוּ בּוֹ עִוּוּת דָּבָר מְבִיאִין אוֹתוֹ לְבֵית דִּין וְדָנִין אוֹתוֹ כְּפִי רִשְׁעוֹ:","אֵין אָנוּ חַיָּבִין לְהַעֲמִיד בָּתֵּי דִּינִים בְּכָל פֶּלֶךְ וּפֶלֶךְ וּבְכָל עִיר וָעִיר אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד. אֲבָל בְּחוּצָה לָאָרֶץ אֵינָן חַיָּבִין לְהַעֲמִיד בֵּית דִּין בְּכָל פֶּלֶךְ וּפֶלֶךְ שֶׁנֶּאֱמַר (דברים טז יח) \"תִּתֶּן לְךָ בְּכָל שְׁעָרֶיךָ אֲשֶׁר ה' אֱלֹהֶיךָ נֹתֵן לְךָ לִשְׁבָטֶיךָ\":","כַּמָּה בָּתֵּי דִּינִין קְבוּעִין יִהְיוּ בְּיִשְׂרָאֵל וְכַמָּה יִהְיֶה מִנְיָנָן. קוֹבְעִין בַּתְּחִלָּה בֵּית דִּין הַגָּדוֹל בַּמִּקְדָּשׁ. וְהוּא הַנִּקְרָא סַנְהֶדְרִי גְּדוֹלָה. וּמִנְיָנָם שִׁבְעִים וְאֶחָד. שֶׁנֶּאֱמַר (במדבר יא טז) \"אֶסְפָה לִּי שִׁבְעִים אִישׁ מִזִּקְנֵי יִשְׂרָאֵל\" וּמשֶׁה עַל גַּבֵּיהֶן שֶׁנֶּאֱמַר (במדבר יא טז) \"וְהִתְיַצְּבוּ שָׁם עִמָּךְ\" הֲרֵי שִׁבְעִים וְאֶחָד. הַגָּדוֹל בְּחָכְמָה שֶׁבְּכֻלָּן מוֹשִׁיבִין אוֹתוֹ רֹאשׁ עֲלֵיהֶן וְהוּא רֹאשׁ הַיְשִׁיבָה וְהוּא שֶׁקּוֹרִין אוֹתוֹ הַחֲכָמִים נָשִׂיא בְּכָל מָקוֹם וְהוּא הָעוֹמֵד תַּחַת משֶׁה רַבֵּנוּ. וּמוֹשִׁיבִין הַגָּדוֹל שֶׁבַּשִּׁבְעִים מִשְׁנֶה לָרֹאשׁ וְיוֹשֵׁב מִימִינוֹ וְהוּא הַנִּקְרָא אַב בֵּית דִּין וּשְׁאָר הַשִּׁבְעִים יוֹשְׁבִין לְפָנָיו כְּפִי שְׁנֵיהֶם וּכְפִי מַעֲלָתָם. כָּל הַגָּדוֹל מֵחֲבֵרוֹ בְּחָכְמָה יִהְיֶה קָרוֹב לַנָּשִׂיא מִשְּׂמֹאלוֹ יוֹתֵר מֵחֲבֵרוֹ. וְהֵם יוֹשְׁבִין בִּכְמוֹ חֲצִי גֹּרֶן בְּעִגּוּל כְּדֵי שֶׁיִּהְיֶה הַנָּשִׂיא עִם אַב בֵּית דִּין רוֹאִין כֻּלָּן. וְעוֹד מַעֲמִידִין שְׁנֵי בָּתֵּי דִּינִין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה עֶשְׂרִים וּשְׁלֹשָׁה אֶחָד עַל פֶּתַח הָעֲזָרָה וְאֶחָד עַל פֶּתַח הַר הַבַּיִת. וּמַעֲמִידִין בְּכָל עִיר וָעִיר מִיִּשְׂרָאֵל שֶׁיֵּשׁ בָּהּ מֵאָה וְעֶשְׂרִים אוֹ יוֹתֵר סַנְהֶדְרִי קְטַנָּה וְיוֹשֶׁבֶת בְּשַׁעַר הָעִיר שֶׁנֶּאֱמַר (עמוס ה טו) \"וְהַצִּיגוּ בַשַּׁעַר מִשְׁפָּט\". וְכַמָּה יִהְיֶה מִנְיָנָם עֶשְׂרִים וּשְׁלֹשָׁה דַּיָּנִים וְהַגָּדוֹל בְּחָכְמָה שֶׁבְּכֻלָּן רֹאשׁ עֲלֵיהֶן וְהַשְּׁאָר יוֹשְׁבִין בְּעִגּוּל כְּמוֹ חֲצִי גֹּרֶן כְּדֵי שֶׁיְּהֵא הָרֹאשׁ רוֹאֶה אֶת כֻּלָּן:","עִיר שֶׁאֵין בָּהּ מֵאָה וְעֶשְׂרִים מַעֲמִידִין בָּהּ שְׁלֹשָׁה דַּיָּנִים שֶׁאֵין בֵּית דִּין פָּחוֹת מִשְּׁלֹשָׁה כְּדֵי שֶׁיְּהֵא בָּהֶן רֹב וּמִעוּט אִם הָיְתָה בֵּינֵיהֶן מַחְלֹקֶת בְּדִין מִן הַדִּינִין:","כָּל עִיר שֶׁאֵין בָּהּ שְׁנֵי חֲכָמִים גְּדוֹלִים אֶחָד רָאוּי לְלַמֵּד וּלְהוֹרוֹת בְּכָל הַתּוֹרָה כֻּלָּהּ וְאֶחָד יוֹדֵעַ לִשְׁמֹעַ וְיוֹדֵעַ לִשְׁאל וּלְהָשִׁיב אֵין מוֹשִׁיבִין בָּהּ סַנְהֶדְרִין אַף עַל פִּי שֶׁיֵּשׁ בָּהּ אֲלָפִים מִיִּשְׂרָאֵל:","סַנְהֶדְרִין שֶׁיֵּשׁ בָּהּ שְׁנַיִם אֵלּוּ אֶחָד רָאוּי לִשְׁמֹעַ וְאֶחָד רָאוּי לְדַבֵּר הֲרֵי זוֹ סַנְהֶדְרִין. הָיוּ בָּהּ שְׁלֹשָׁה הֲרֵי זוֹ בֵּינוֹנִית. הָיוּ בָּהּ אַרְבָּעָה יוֹדְעִים לְדַבֵּר הֲרֵי זוֹ סַנְהֶדְרִי חֲכָמָה:","כָּל סַנְהֶדְרִי קְטַנָּה מוֹשִׁיבִין לִפְנֵיהֶן שָׁלֹשׁ שׁוּרוֹת שֶׁל תַּלְמִידֵי חֲכָמִים בְּכָל שׁוּרָה וְשׁוּרָה עֶשְׂרִים וּשְׁלֹשָׁה אִישׁ. שׁוּרָה רִאשׁוֹנָה קְרוֹבָה לַסַּנְהֶדְרִין. וְשׁוּרָה שְׁנִיָּה לְמַטָּה הֵימֶנָּה. וּשְׁלִישִׁית לְמַטָּה הֵימֶנָּה. וְכָל שׁוּרָה וְשׁוּרָה יוֹשְׁבִין בָּהּ לְפִי מַעֲלָתָן בְּחָכְמָה:","אִם נֶחְלְקוּ הַסַּנְהֶדְרִין וְהֻצְרְכוּ לִסְמֹךְ אֶחָד לְהוֹסִיף עַל מִנְיָנָן סוֹמְכִין מִן הָרִאשׁוֹנָה גָּדוֹל שֶׁבָּהּ וְהָרִאשׁוֹן שֶׁבְּשׁוּרָה שְׁנִיָּה בָּא וְיוֹשֵׁב בְּסוֹף שׁוּרָה הָרִאשׁוֹנָה כְּדֵי לְמַלְּאוֹת חֶסְרוֹנָהּ וְהָרִאשׁוֹן שֶׁבַּשְּׁלִישִׁית בָּא וְיוֹשֵׁב בְּסוֹף שׁוּרָה שְׁנִיָּה. וּבוֹרְרִין לָהֶן אֶחָד מִשְּׁאָר הַקָּהָל וּמוֹשִׁיבִין אוֹתוֹ בְּסוֹף שׁוּרָה שְׁלִישִׁית. וְכֵן אִם צָרְכוּ לִסְמֹךְ שֵׁנִי אוֹ שְׁלִישִׁי עַל הַסֵּדֶר הַזֶּה הֵם עוֹשִׂים:","כָּל מָקוֹם שֶׁיֵּשׁ בּוֹ סַנְהֶדְרִין יִהְיוּ שָׁם שְׁנֵי סוֹפְרֵי דַּיָּנִים עוֹמְדִין לִפְנֵיהֶם אֶחָד מִן הַיָּמִין וְאֶחָד מִן הַשְּׂמֹאל. אֶחָד כּוֹתֵב דִּבְרֵי הַמְחַיְּבִין וְאֶחָד כּוֹתֵב דִּבְרֵי הַמְזַכִּים:","וְלָמָּה אֵין [מַעֲמִידִין] סַנְהֶדְרִין אֶלָּא בְּעִיר שֶׁיֵּשׁ בָּהּ מֵאָה וְעֶשְׂרִים. כְּדֵי שֶׁיִּהְיֶה מֵהֶן סַנְהֶדְרִין שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה וְשָׁלֹשׁ שׁוּרוֹת שֶׁל עֶשְׂרִים וּשְׁלֹשָׁה וַעֲשָׂרָה בַּטְלָנִין שֶׁל בֵּית הַכְּנֶסֶת. וּשְׁנֵי סוֹפְרִים וּשְׁנֵי חַזָּנִים וּשְׁנֵי בַּעֲלֵי דִּינִין. וּשְׁנֵי עֵדִים וּשְׁנֵי זוֹמְמִין. וּשְׁנֵי זוֹמְמֵי זוֹמְמִין. וּשְׁנֵי גַּבָּאֵי צְדָקָה וְעוֹד אֶחָד כְּדֵי שֶׁיִּהְיוּ שְׁלֹשָׁה לְחַלֵּק צְדָקָה. וְרוֹפֵא אֻמָּן. וְלַבְלָר. וּמְלַמֵּד תִּינוֹקוֹת. הֲרֵי מֵאָה וְעֶשְׂרִים:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 20":["אֵין בֵּית דִּין עוֹנְשִׁין בְּאֹמֶד הַדַּעַת אֶלָּא עַל פִּי עֵדִים בִּרְאָיָה בְּרוּרָה. אֲפִלּוּ רָאוּהוּ הָעֵדִים רוֹדֵף אַחַר חֲבֵרוֹ וְהִתְרוּ בּוֹ וְהֶעֱלִימוּ עֵינֵיהֶם אוֹ שֶׁנִּכְנְסוּ אַחֲרָיו לְחֻרְבָּה וְנִכְנְסוּ אַחֲרָיו וּמְצָאוּהוּ הָרוּג וּמְפַרְפֵּר וְהַסַּיִף מְנַטֵּף דָּם בְּיַד הַהוֹרֵג הוֹאִיל וְלֹא רָאוּהוּ בְּעֵת שֶׁהִכָּהוּ אֵין בֵּית דִּין הוֹרְגִין בְּעֵדוּת זוֹ וְעַל זֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (שמות כג ז) \"וְנָקִי וְצַדִּיק אַל תַּהֲרֹג\". וְכֵן אִם הֵעִידוּ עָלָיו שְׁנַיִם שֶׁעָבַד עֲבוֹדָה זָרָה זֶה רָאָהוּ שֶׁעָבַד אֶת הַחַמָּה וְהִתְרָה בּוֹ וְזֶה רָאָהוּ שֶׁעָבַד אֶת הַלְּבָנָה וְהִתְרָה בּוֹ אֵין מִצְטָרְפִין. שֶׁנֶּאֱמַר וְנָקִי וְצַדִּיק אַל תַּהֲרֹג הוֹאִיל וְיֵשׁ שָׁם צַד לְנַקּוֹתוֹ וְלִהְיוֹתוֹ צַדִּיק אַל תַּהַרְגוּהוּ:","כָּל מִי שֶׁעָשָׂה דָּבָר שֶׁחַיָּבִין עָלָיו מִיתַת בֵּית דִּין בְּאֹנֶס אֵין בֵּית דִּין מְמִיתִין אוֹתוֹ וְאַף עַל פִּי שֶׁהָיָה מְצֻוֶּה שֶׁיֵּהָרֵג וְאַל יַעֲבֹר אַף עַל פִּי שֶׁחִלֵּל אֶת הַשֵּׁם וְהוּא אָנוּס אֵינוֹ נֶהֱרָג שֶׁנֶּאֱמַר (דברים כב כו) \"וְלַנַּעֲרָה לֹא תַעֲשֶׂה דָבָר\" זוֹ אַזְהָרָה לְבֵית דִּין שֶׁלֹּא יַעַנְשׁוּ אֶת הָאָנוּס:","אִישׁ שֶׁאֲנָסוּהוּ עַד שֶׁבָּא עַל הָעֶרְוָה חַיָּב מִיתַת בֵּית דִּין שֶׁאֵין קִשּׁוּי אֶלָּא לְדַעַת. אֲבָל הָאִשָּׁה הַנִּבְעֶלֶת בְּאֹנֶס אֲפִלּוּ אָמְרָה אַחַר שֶׁנֶּאֶנְסָה הָנִיחוּ לוֹ הֲרֵי הִיא פְּטוּרָה מִפְּנֵי שֶׁיִּצְרָהּ נִתְגַּבֵּר עָלֶיהָ:","אָסוּר לְבֵית דִּין לָחוּס עַל הַהוֹרֵג שֶׁלֹּא יֹאמְרוּ כְּבָר נֶהֱרַג זֶה וּמַה תּוֹעֶלֶת יֵשׁ בַּהֲרִיגַת הָאַחֵר וְנִמְצְאוּ מִתְרַשְּׁלִין בַּהֲרִיגָתוֹ. שֶׁנֶּאֱמַר (דברים יט יג) \"וְלֹא תָחוֹס עֵינְךָ עָלָיו וּבִעַרְתָּ דַם הַנָּקִי\". וְכֵן אָסוּר לְבֵית דִּין לָחוּס עַל מִי שֶׁנִּתְחַיֵּב קְנָס שֶׁלֹּא יֹאמְרוּ עָנִי הוּא זֶה שֶׁלֹּא בְּכַוָּנָה עָשָׂה אֶלָּא מַגְבִּין מִמֶּנּוּ כָּל שֶׁיֵּשׁ לוֹ בְּלֹא חֲנִינָה שֶׁנֶּאֱמַר וְלֹא תָחוֹס עֵינְךָ. וְכֵן בְּדִינֵי מָמוֹנוֹת אֵין מְרַחֲמִין עַל הַדַּל. שֶׁלֹּא תֹּאמַר עָנִי הוּא זֶה וּבַעַל דִּינוֹ עָשִׁיר הוֹאִיל וַאֲנִי וְהֶעָשִׁיר חַיָּבִין לְפַרְנְסוֹ אֲזַכֶּנּוּ בַּדִּין וְנִמְצָא מִתְפַּרְנֵס בְּכָבוֹד. עַל זֶה הִזְהִירָה תּוֹרָה (שמות כג ג) \"וְדָל לֹא תֶהְדַּר בְּרִיבוֹ\". וְנֶאֱמַר (ויקרא יט טו) \"לֹא תִשָּׂא פְנֵי דָל\". אָסוּר לְהַדֵּר פְּנֵי גָּדוֹל. כֵּיצַד. הֲרֵי שֶׁבָּאוּ לְפָנֶיךָ שְׁנַיִם לְדִין אֶחָד חָכָם גָּדוֹל וְאֶחָד הֶדְיוֹט לֹא תַּקְדִּים לִשְׁאל בִּשְׁלוֹמוֹ שֶׁל גָּדוֹל וְלֹא תַּסְבִּיר לוֹ פָּנִים וְלֹא תְּכַבְּדֶנּוּ. כְּדֵי שֶׁלֹּא יִסְתַּתְּמוּ טַעֲנוֹתָיו שֶׁל אַחֵר. אֶלָּא אֵינוֹ נִפְנֶה לְאֶחָד מֵהֶן עַד שֶׁיִּגָּמֵר הַדִּין שֶׁנֶּאֱמַר (ויקרא יט טו) \"לֹא תֶהְדַּר פְּנֵי גָדוֹל\". אָמְרוּ חֲכָמִים אַל תֹּאמַר עָשִׁיר הוּא זֶה בֶּן גְּדוֹלִים הוּא זֶה הֵיאַךְ אֲבַיְּשֶׁנּוּ וְאֶרְאֶה בְּבוּשָׁתוֹ. לְכָךְ נֶאֱמַר לֹא תֶהְדַּר פְּנֵי גָדוֹל:","בָּאוּ לְפָנֶיךָ שְׁנַיִם אֶחָד כָּשֵׁר וְאֶחָד רָשָׁע אַל תֹּאמַר הוֹאִיל וְרָשָׁע הוּא וְחֶזְקָתוֹ מְשַׁקֵּר וְחֶזְקַת זֶה שֶׁאֵינוֹ מְשַׁנֶּה בִּדְבָרוֹ אַטֶּה הַדִּין עַל הָרָשָׁע. עַל זֶה נֶאֱמַר (שמות כג ו) \"לֹא תַטֶּה מִשְׁפַּט אֶבְיֹנְךָ בְּרִיבוֹ\" אַף עַל פִּי שֶׁהוּא אֶבְיוֹן בְּמִצְוֹת לֹא תַּטֶּה דִּינוֹ:","(ויקרא יט טו) \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט\" זֶה הַמְעַוֵּת אֶת הַדִּין וּמְזַכֶּה אֶת הַחַיָּב וּמְחַיֵּב אֶת הַזַּכַּאי. וְכֵן הַמְעַנֶּה אֶת הַדִּין וּמַאֲרִיךְ בִּדְבָרִים בְּרוּרִים כְּדֵי לְצַעֵר אֶחָד מִבַּעֲלֵי דִּינִים הֲרֵי זֶה בִּכְלַל עָוֶל:","הַגַּס לִבּוֹ בְּהוֹרָאָה וְקוֹפֵץ וְחוֹתֵךְ אֶת הַדִּין קֹדֶם שֶׁיַּחְקְרֵהוּ בֵּינוֹ לְבֵין עַצְמוֹ עַד שֶׁיְּהֵא לוֹ בָּרוּר כַּשֶּׁמֶשׁ הֲרֵי זֶה שׁוֹטֶה רָשָׁע וְגַס רוּחַ. כָּךְ צִוּוּ חֲכָמִים (גמרא סנהדרין ז ב) \"הֱווּ מְתוּנִין בַּדִּין\". וְכֵן אִיּוֹב הוּא אוֹמֵר (איוב כט טז) \"וְרִב לֹא יָדַעְתִּי אֶחְקְרֵהוּ\":","כָּל דַּיָּן שֶׁבָּא לְפָנָיו דִּין וְהִתְחִיל לְדַמּוֹתוֹ בְּדִין פָּסוּק שֶׁכְּבָר יָדַע אוֹתוֹ וְיֵשׁ בַּמְּדִינָה גָּדוֹל מִמֶּנּוּ בְּחָכְמָה וְאֵינוֹ הוֹלֵךְ וְנִמְלָךְ בּוֹ הֲרֵי זֶה בִּכְלַל הָרְשָׁעִים שֶׁלִּבָּם גַּס בְּהוֹרָאָה. וְאָמְרוּ חֲכָמִים רָעָה עַל רָעָה תָּבוֹא לוֹ שֶׁכָּל הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן מִגַּסּוּת הָרוּחַ הֵן הַמְּבִיאוֹת לִידֵי עִוּוּת הַדִּין. (משלי ז כו) \"כִּי רַבִּים חֲלָלִים הִפִּילָה\" זֶה תַּלְמִיד שֶׁלֹּא הִגִּיעַ לְהוֹרָאָה וּמוֹרֶה. (משלי ז כו) \"וַעֲצֻמִים כָּל הֲרֻגֶיהָ\" זֶה שֶׁהִגִּיעַ לְהוֹרָאָה וְאֵינוֹ מוֹרֶה. וְהוּא שֶׁיִּהְיֶה הַדּוֹר צָרִיךְ לוֹ. אֲבָל אִם יָדַע שֶׁיֵּשׁ לְשָׁם רָאוּי לְהוֹרָאָה וּמָנַע עַצְמוֹ מִן הַהוֹרָאָה הֲרֵי זֶה מְשֻׁבָּח. וְכָל הַמּוֹנֵעַ עַצְמוֹ מִן הַדִּין מוֹנֵעַ מִמֶּנּוּ אֵיבָה וְגֵזֶל וּשְׁבוּעַת שָׁוְא וְהַגַּס לִבּוֹ בְּהוֹרָאָה שׁוֹטֶה רָשָׁע וְגַס רוּחַ:","תַּלְמִיד אַל יוֹרֶה הֲלָכָה לִפְנֵי רַבּוֹ אֶלָּא אִם כֵּן הָיָה רָחוֹק מִמֶּנּוּ שָׁלֹשׁ פַּרְסָאוֹת כְּנֶגֶד מַחֲנֵה יִשְׂרָאֵל:","אַל תֹּאמַר שֶׁכָּל אֵלּוּ הַדְּבָרִים בְּדִין שֶׁיֵּשׁ בּוֹ הוֹצָאַת מָמוֹן הַרְבֵּה מִזֶּה וּנְתִינָתוֹ לָזֶה. לְעוֹלָם יְהִי דִּין אֶלֶף מָנֶה וְדִין פְּרוּטָה אַחַת שָׁוִין בְּעֵינֶיךָ לְכָל דָּבָר:","אֵין הַדַּיָּנִין יוֹשְׁבִין לָדִין בְּדִין פָּחוֹת מִשְּׁוֵה פְּרוּטָה. וְאִם הֻזְקְקוּ לִשְׁוֵה פְּרוּטָה גּוֹמְרִין אֶת דִּינוֹ אֲפִלּוּ לְפָחוֹת מִשְּׁוֵה פְּרוּטָה:","כָּל הַמַּטֶּה מִשְׁפָּט אֶחָד מִיִּשְׂרָאֵל עוֹבֵר בְּלָאו אֶחָד שֶׁנֶּאֱמַר (ויקרא יט טו) \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט\". וְאִם הָיָה גֵּר עוֹבֵר בִּשְׁנֵי לָאוִין שֶׁנֶּאֱמַר (דברים כד יז) \"לֹא תַטֶּה מִשְׁפַּט גֵּר\". וְאִם הָיָה יָתוֹם עוֹבֵר בִּשְׁלֹשָׁה לָאוִין שֶׁנֶּאֱמַר (דברים כד יז) \"מִשְׁפַּט גֵּר יָתוֹם\":"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 8":["בֵּית דִּין שֶׁנֶּחְלְקוּ מִקְצָתָם אוֹמְרִים זַכַּאי וּמִקְצָתָם אוֹמְרִים חַיָּב הוֹלְכִין אַחַר הָרֹב. וְזוֹ מִצְוַת עֲשֵׂה שֶׁל תּוֹרָה שֶׁנֶּאֱמַר (שמות כג ב) \"אַחֲרֵי רַבִּים לְהַטֹּת\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּדִינֵי מָמוֹנוֹת וּבִשְׁאָר דִּינֵי אָסוּר וּמֻתָּר וְטָמֵא וְטָהוֹר וְכַיּוֹצֵא בָּהֶן. אֲבָל בְּדִינֵי נְפָשׁוֹת אִם נֶחְלְקוּ בָּזֶה הַחוֹטֵא אִם יֵהָרֵג אוֹ לֹא יֵהָרֵג. אִם הָיוּ הָרֹב מְזַכִּים זַכַּאי וְאִם הָיוּ הָרֹב מְחַיְּבִין אֵינוֹ נֶהֱרָג עַד שֶׁיִּהְיוּ הַמְחַיְּבִין יֶתֶר עַל הַמְזַכִּים שְׁנַיִם. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁעַל זֶה הִזְהִירָה תּוֹרָה וְאָמְרָה (שמות כג ב) \"לֹא תִהְיֶה אַחֲרֵי רַבִּים לְרָעֹת\". כְּלוֹמַר אִם הָרֹב נוֹטִים לְרָעָה לַהֲרֹג לֹא תִּהְיֶה אַחֲרֵיהֶם עַד שֶׁיִּטּוּ הַטָּיָה גְּדוֹלָה וְיוֹסִיפוּ הַמְחַיְּבִין שְׁנַיִם. שֶׁנֶּאֱמַר (שמות כג ב) \"לִנְטֹת אַחֲרֵי רַבִּים לְהַטֹּת\" הַטָּיָתְךָ לְטוֹבָה עַל פִּי אֶחָד לְרָעָה עַל פִּי שְׁנַיִם. וְכָל אֵלּוּ הַדְּבָרִים קַבָּלָה הֵם:","בֵּית דִּין שֶׁל שְׁלֹשָׁה שֶׁנֶּחְלְקוּ שְׁנַיִם אוֹמְרִים זַכַּאי וְאֶחָד אוֹמֵר חַיָּב הֲרֵי זֶה זַכַּאי. שְׁנַיִם אוֹמְרִים חַיָּב וְאֶחָד אוֹמֵר זַכַּאי הֲרֵי זֶה חַיָּב. אֶחָד אוֹמֵר זַכַּאי וְאֶחָד אוֹמֵר חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ. אוֹ שֶׁאָמְרוּ שְׁנַיִם זַכַּאי אוֹ חַיָּב וְהַשְּׁלִישִׁי אוֹמֵר אֵינִי יוֹדֵעַ יוֹסִיפוּ הַדַּיָּנִים שְׁנַיִם. נִמְצְאוּ חֲמִשָּׁה נוֹשְׂאִים וְנוֹתְנִים בַּדָּבָר. אָמְרוּ שְׁלֹשָׁה מֵהֶם זַכַּאי וּשְׁנַיִם אוֹמְרִים חַיָּב הֲרֵי זֶה זַכַּאי. אָמְרוּ שְׁלֹשָׁה חַיָּב וּשְׁנַיִם זַכַּאי הֲרֵי זֶה חַיָּב. אָמְרוּ שְׁנַיִם מֵהֶם זַכַּאי וּשְׁנַיִם מֵהֶם חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ מוֹסִיפִין שְׁנַיִם. אֲבָל אִם אָמְרוּ אַרְבָּעָה זַכַּאי אוֹ חַיָּב וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ. אוֹ שֶׁאָמְרוּ שְׁלֹשָׁה זַכַּאי וְאֶחָד חַיָּב וְאָמַר אֶחָד אֵינִי יוֹדֵעַ בֵּין שֶׁהָיָה זֶה שֶׁאָמַר אֵינִי יוֹדֵעַ הוּא שֶׁאָמַר אֵינִי יוֹדֵעַ בַּתְּחִלָּה בֵּין שֶׁאָמַר אַחֵר הוֹלְכִים אַחַר הָרֹב. הָיוּ מֶחֱצָה לְמֶחֱצָה וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ הֲרֵי אֵלּוּ מוֹסִיפִין שְׁנַיִם אֲחֵרִים. וְכֵן אִם נִסְתַּפֵּק הַדָּבָר מוֹסִיפִין וְהוֹלְכִין עַד שִׁבְעִים וְאֶחָד. הִגִּיעוּ לְשִׁבְעִים וְאֶחָד וְאָמְרוּ שְׁלֹשִׁים וַחֲמִשָּׁה חַיָּב וּשְׁלֹשִׁים וַחֲמִשָּׁה זַכַּאי וְאֶחָד אוֹמֵר אֵינִי יוֹדֵעַ נוֹשְׂאִים וְנוֹתְנִים עִמּוֹ עַד שֶׁיַּחֲזֹר לְדִבְרֵי הַצַּד הָאֶחָד וְנִמְצְאוּ שְׁלֹשִׁים וְשִׁשָּׁה מְזַכִּים אוֹ מְחַיְּבִין. וְאִם לֹא חָזַר לֹא הוּא וְלֹא אֶחָד מֵהֶן הֲרֵי הַדָּבָר סָפֵק וּמַעֲמִידִין אֶת הַמָּמוֹן בְּחֶזְקַת בְּעָלָיו:","כָּל מִי שֶׁאָמַר אֵינִי יוֹדֵעַ אֵינוֹ צָרִיךְ לָתֵת טַעַם לִדְבָרָיו וּלְהוֹדִיעַ מֵאֵי זֶה טַעַם בָּא לוֹ הַסָּפֵק. כְּדֶרֶךְ שֶׁמַּרְאֶה הַמְזַכֶּה מֵאֵי זֶה טַעַם מְזַכֶּה וְהַמְחַיֵּב מֵאֵי זֶה טַעַם מְחַיֵּב:"],"Mishneh Torah, Things Forbidden on the Altar 2":["כָּל הַמּוּמִין הַפּוֹסְלִין בָּאָדָם וּבַבְּהֵמָה חֲמִשִּׁים וּכְבָר נִמְנוּ:","וְיֵשׁ מוּמִין אֲחֵרִים מְיֻחָדִין בַּבְּהֵמָה וְאֵינָן רְאוּיִין לִהְיוֹת בְּאָדָם. וּשְׁלֹשָׁה וְעֶשְׂרִים הֵם וְאֵלּוּ הֵן. אִם הָיָה גַּלְגַּל עֵינָהּ עָגל כְּשֶׁל אָדָם. עֵינָהּ אַחַת גְּדוֹלָה כְּשֶׁל עֵגֶל וְהַשְּׁנִיָּה קְטַנָּה כְּשֶׁל אַוָּז. אֲבָל אִם הָיְתָה אֹזֶן גְּדוֹלָה וְאֹזֶן קְטַנָּה אֲפִלּוּ קְטַנָּה עַד כְּפוֹל כָּשֵׁר. אִם יֵשׁ בְּלֹבֶן עֵינָהּ יַבֶּלֶת שֶׁיֵּשׁ בָּהּ שֵׂעָר. אִם נִקַּב הָעוֹר שֶׁבֵּין שְׁנֵי חֳטָמֶיהָ בַּמָּקוֹם הַנִּרְאֶה. פִּיהָ דּוֹמֶה לְשֶׁל חֲזִיר פָּרוּס אַף עַל פִּי שֶׁאֵינוֹ מְחֻדָּד כְּשִׁפּוּד:","חִטֶּיהָ הַחִיצוֹנוֹת שֶׁנִּקְּבוּ אוֹ שֶׁנִּפְגְּמוּ אַף עַל פִּי שֶׁנִּשְׁאַר מִקְצָתָן אוֹ שֶׁנִּגְמְמוּ אִם נֶעֶקְרוּ חִטֶּיהָ הַפְּנִימִיּוֹת שֶׁהֲרֵי בְּעֵת שֶׁפּוֹתַחַת פִּיהָ וְצוֹוַחַת הֵן נִרְאִין חֲסֵרִין:","אִם נִטְּלוּ קַרְנֶיהָ וְזִכְרוּתָן עִמָּהֶן וְלֹא נִשְׁאַר מֵהֶן כְּלוּם. אֲבָל נְקֵבָה שֶׁיֵּשׁ לָהּ קַרְנַיִם כְּשֵׁרָה. אִם נִפְגַּם הָעוֹר שֶׁחוֹפֶה אֶת גִּיד הַבְּהֵמָה. אִם נִפְגְּמָה הָעֶרְוָה שֶׁל נְקֵבָה. אִם נִפְגַּם הַזָּנָב מִן הָעֶצֶם אֲבָל לֹא מִן הַפֶּרֶק. אִם הָיְתָה רֹאשׁ הַזָּנָב מְפֻצָּל לִשְׁנַיִם בִּשְׁנֵי עֲצָמִים. אִם הָיָה בֵּין חֻלְיָא לְחֻלְיָא מְלֹא אֶצְבַּע בָּשָׂר. אִם הָיָה הַזָּנָב קָצָר. וְעַד כַּמָּה. בִּגְדִי חֻלְיָא אַחַת מוּם שְׁתַּיִם כָּשֵׁר. וּבְטָלֶה אֹרֶךְ שְׁתֵּי חֻלְיוֹת מוּם. הָיְתָה שָׁלֹשׁ כָּשֵׁר. זְנַב הַגְּדִי שֶׁהָיָה רַךְ וּמְדֻלְדָּל דּוֹמֶה לְשֶׁל חֲזִיר. אִם נִשְׁבַּר עֶצֶם מִן הַזָּנָב. אֲבָל אִם נִשְׁבַּר עֶצֶם מִצַּלְעוֹתָיו כָּשֵׁר מִפְּנֵי שֶׁאֵינוֹ בְּגָלוּי:","בַּעֲלַת חָמֵשׁ רַגְלַיִם אוֹ אֵין לָהּ אֶלָּא שָׁלֹשׁ רַגְלַיִם. אִם הָיְתָה אַחַת מֵרַגְלָיו וְיָדָיו פַּרְסָתָהּ עֲגֻלָּה כְּשֶׁל חֲמוֹר אַף עַל פִּי שֶׁהִיא סְדוּקָה וּפְרוּסָה. אִם הָיְתָה יָדוֹ אוֹ רַגְלוֹ קְלוּטָה כְּשֶׁל חֲמוֹר וְזֶהוּ (ויקרא כב-כג) \"קָלוּט\" הָאָמוּר בַּתּוֹרָה. אִם נִגְמְמוּ טְלָפֶיהָ וְזִכְרוּתָן עִמָּהֶן אַף עַל פִּי שֶׁנִּשְׁאַר מִזִּכְרוּתָן מְעַט קָרוֹב לַבָּשָׂר:","כָּל מוּם מִשְּׁלֹשָׁה וְשִׁבְעִים מוּם הַמְּנוּיִין בַּבְּהֵמָה פּוֹסְלִין אוֹתָהּ מִן הַקָּרְבָּן. וְאִם נָפַל אֶחָד מֵהֶם בִּתְמִימָה שֶׁהִיא קֹדֶשׁ תִּפָּדֶה וְתֵצֵא לְחֻלִּין. חוּץ מִזָּקֵן וְחוֹלֶה וּמְזֹהָם שֶׁאַף עַל פִּי שֶׁאֵינוֹ כָּשֵׁר לְקָרְבָּן אֵינוֹ נִפְדֶּה. אֶלָּא יִהְיֶה קַיָּם וְרוֹעֶה עַד שֶׁיִּוָּלֵד בּוֹ מוּם אַחֵר קָבוּעַ מִשְּׁאָר הַמּוּמִין וְיִפָּדֶה. וְכֵן בֶּהֱמַת קָדָשִׁים שֶׁנּוֹלַד בָּהּ מוּם עוֹבֵר אֵינָהּ קְרֵבָה וְלֹא נִפְדֵּית:","אַרְבָּעָה מוּמִין עוֹבְרִים יֵשׁ בָּאָדָם וּבַבְּהֵמָה וְאֵלּוּ הֵן. גָּרָב לַח. חֲזָזִית שֶׁאֵינָהּ מִצְרִית. מַיִם שֶׁיּוֹרְדִין בָּעַיִן וְאֵינָן קְבוּעִין. סַנְוִירִין שֶׁאֵינָן קְבוּעִין:","יֵשׁ שָׁם אַרְבָּעָה חֳלָיִים אֲחֵרִים אִם נִמְצָא אֶחָד מֵהֶם בִּבְהֵמָה אֵין מַקְרִיבִין אוֹתָהּ. לְפִי שֶׁאֵינָהּ מִן הַמֻּבְחָר וְהַכָּתוּב אוֹמֵר (דברים יב-יא) \"מִבְחַר נְדָרֶיךָ\". וְאֵלּוּ הֵן. מִי שֶׁבְּלֹבֶן עֵינוֹ יַבֶּלֶת שֶׁאֵין בּוֹ שֵׂעָר. אִם נִגְמְמוּ קַרְנָיו אַף עַל פִּי שֶׁנִּשְׁאַר מִזִּכְרוּתָן מְעַט סָמוּךְ לַבָּשָׂר. אִם נִפְגְּמוּ חִטָּיו הַפְּנִימִיּוֹת. אִם הָיָה אֶחָד מֵאֵלּוּ בְּקָדָשִׁים לֹא קְרֵבִין וְלֹא נִפְדִּין. אֶלָּא יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם. וְאִם הִקְרִיבָן יֵרָאֶה לִי שֶׁהֻרְצוּ:","וְכֵן בֶּהֱמַת קָדָשִׁים שֶׁנֶּעֶבְדָה בָּהּ עֲבֵרָה אוֹ שֶׁהֵמִיתָה אֶת הָאָדָם בְּעֵד אֶחָד אוֹ עַל פִּי הַבְּעָלִים לֹא קְרֵבָה וְלֹא נִפְדֵּית עַד שֶׁיִּוָּלֵד לָהּ מוּם קָבוּעַ:","בְּהֵמָה שֶׁנּוֹלַד בָּהּ אַחַת מִן הַטְּרֵפִיּוֹת הָאוֹסְרוֹת אוֹתָהּ בַּאֲכִילָה אֲסוּרָה לְגַבֵּי הַמִּזְבֵּחַ הֲרֵי הוּא אוֹמֵר (מלאכי א-ח) \"הַקְרִיבֵהוּ נָא לְפֶחָתֶךָ הֲיִרְצְךָ אוֹ הֲיִשָּׂא פָנֶיךָ\". וְאַף עַל פִּי שֶׁאֵינָהּ רְאוּיָה לְקָרְבָּן אֵין פּוֹדִין אוֹתָהּ שֶׁאֵין פּוֹדִין אֶת הַקָּדָשִׁים לְהַאֲכִילָן לַכְּלָבִים. אֶלָּא יִרְעוּ עַד שֶׁיָּמוּתוּ וְיִקָּבְרוּ:","נִשְׁחֲטָה וְנִמְצֵאת טְרֵפָה הֲרֵי זוֹ תֵּצֵא לְבֵית הַשְּׂרֵפָה. וְכֵן אִם נִמְצָא אֶחָד מֵאֵיבָרֶיהָ הַפְּנִימִיִּין חָסֵר אַף עַל פִּי שֶׁאֵינָהּ טְרֵפָה כְּגוֹן שֶׁנִּמְצֵאת בְּכֻלְיָא אַחַת אוֹ שֶׁנִּטַּל הַטְּחוֹל הֲרֵי זוֹ אֲסוּרָה לַמִּזְבֵּחַ וְתִשָּׂרֵף. לֹא מִפְּנֵי שֶׁהִיא בַּעֲלַת מוּם שֶׁאֵין חִסָּרוֹן שֶׁבִּפְנִים מוּם אֶלָּא מִפְּנֵי שֶׁאֵין מַקְרִיבִין חָסֵר כְּלָל שֶׁנֶּאֱמַר (במדבר כח-יט) (במדבר כ״ח:ל״א) (במדבר כט-ח) \"תְּמִימִם יִהְיוּ לָכֶם\". וְכָל הַיָּתֵר כְּחָסֵר לְפִיכָךְ אִם נִמְצָא שָׁם שָׁלֹשׁ כֻּלְיוֹת אוֹ שְׁנֵי טְחוֹלִים פְּסוּלָה:","אֵי זוֹ הִיא סַנְוִירִין קְבוּעִים כָּל שֶׁשָּׁהָה שְׁמוֹנִים יוֹם וְלֹא רָאָה. וּבוֹדְקִין אוֹתוֹ שָׁלֹשׁ פְּעָמִים בְּיוֹם שִׁבְעָה וְעֶשְׂרִים מֵעֵת שֶׁהִרְגִּישׁוּ בּוֹ וּבְיוֹם אַרְבָּעָה וַחֲמִשִּׁים וּבְיוֹם שְׁמוֹנִים. אִם רָאָה מוֹנִים לוֹ שְׁמוֹנִים מֵעֵת שֶׁפָּסְקָה הָרְאִיָּה:","וּבַמֶּה יִוָּדַע שֶׁהַמַּיִם קְבוּעִין. כְּשֶׁאָכְלָה עֲשָׂבִים לַחִים מֵרֹאשׁ אֲדָר עַד חֲצִי נִיסָן וְאָכְלָה אַחֲרֵי כֵן עֲשָׂבִים יְבֵשִׁים אֱלוּל וַחֲצִי תִּשְׁרֵי וְלֹא נִתְרַפְּאָה הֲרֵי אֵלּוּ מַיִם קְבוּעִים:","וְכַמָּה תֹּאכַל מֵעֲשָׂבִים אֵלּוּ הַלַּחִים בַּזְּמַן הַלַּח וְהַיְבֵשִׁים בַּזְּמַן הַיָּבֵשׁ. כִּגְרוֹגֶרֶת אוֹ יוֹתֵר קֹדֶם סְעֻדָּה רִאשׁוֹנָה שֶׁל כָּל יָמִים בִּשְׁלֹשָׁה חֳדָשִׁים אֵלּוּ. וְצָרִיךְ שֶׁתֹּאכַל אוֹתָן בְּכָל יוֹם אַחַר שְׁתִיָּה. וְתִהְיֶה מֻתֶּרֶת בַּשָּׂדֶה בְּעֵת אֲכִילָה. וְלֹא תִּהְיֶה לְבַדָּהּ אֶלָּא הִיא וּבְהֵמָה אַחֶרֶת לְצַוֵּות עִמָּהּ. אִם נַעֲשָׂה לָהּ כָּל אֵלּוּ וְלֹא נִתְרַפֵּאת הֲרֵי אֵלּוּ קְבוּעִין וַדַּאי. וְאִם חָסֵר אֶחָד מִכָּל אֵלּוּ הֲרֵי זֶה סָפֵק וְאֵינָהּ קְרֵבָה וְלֹא נִפְדֵּית:","כֵּיצַד. אָכְלָה הַלַּח כְּמִשְׁפָּטוֹ בַּאֲדָר כֻּלּוֹ וַחֲצִי נִיסָן וְאָכְלָה אַחֲרָיו הַיָּבֵשׁ כְּמִשְׁפָּטוֹ בַּחֲצִי נִיסָן וְאִיָּר שֶׁנִּמְצָא שֶׁאָכְלָה בִּשְׁלֹשָׁה חֳדָשִׁים עַל הַסֵּדֶר. אוֹ שֶׁאָכְלָה כִּגְרוֹגֶרֶת אַחַר אֲכִילָה אוֹ קֹדֶם שְׁתִיָּה אוֹ שֶׁהָיְתָה קְשׁוּרָה אוֹ שֶׁהָיְתָה לְבַדָּהּ אוֹ שֶׁהָיְתָה בַּגִּנָּה הַסְּמוּכָה לָעִיר וְלֹא נִתְרַפֵּאת מִכָּל אֵלּוּ סָפֵק קְבוּעִין אוֹ עוֹבְרִים. לְפִיכָךְ אִם הֵטִיל בָּהּ מוּם אַחֵר אֵינוֹ לוֹקֶה. אֲכָלָהּ כְּמִשְׁפָּטָהּ בִּזְמַנֵּי הָאֲכִילָה וְלֹא נִתְרַפְּאָה הֲרֵי הִיא בַּעֲלַת מוּם קָבוּעַ:","יֵשׁ בַּדָּבָר סָפֵק אִם לְמַפְרֵעַ הִיא בַּעֲלַת מוּם קָבוּעַ מֵעֵת שֶׁבָּאוּ לָהּ הַמּוּמִים אוֹ מֵעֵת שֶׁנִּתְיָאֲשׁוּ מֵרְפוּאָתָהּ. לְפִיכָךְ הַפּוֹדֶה אוֹתָהּ קֹדֶם שֶׁנִּתְיָאֲשׁוּ מֵרְפוּאָתָהּ וְנֶהֱנֶה בְּאוֹתוֹ הַפִּדְיוֹן אַחַר שֶׁנִּתְיָאֲשׁוּ מֵרְפוּאָתָהּ הֲרֵי זֶה סָפֵק מוֹעֵל וְאֵינוֹ מֵבִיא קָרְבַּן מְעִילָה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:"],"Mishneh Torah, Those Who Defile Bed or Seat 3":["בּוֹעֵל נִדָּה כְּנִדָּה שֶׁהוּא אָב מֵאֲבוֹת הַטֻּמְאָה שֶׁל תּוֹרָה מְטַמֵּא כֵּלִים בְּמַגָּע וּמְטַמֵּא אָדָם בְּמַשָּׂא וּבְמַגָּע וּמְטַמֵּא בְּהֶסֵּט וּמְטַמֵּא מִשְׁכָּב וּמֶרְכָּב כְּנִדָּה:","אֵין מִשְׁכַּב בּוֹעֵל נִדָּה וּמֶרְכָּבוֹ כְּמִשְׁכַּב נִדָּה וּמֶרְכָּבָהּ שֶׁהַמִּשְׁכָּב אוֹ הַמֶּרְכָּב שֶׁדָּרְסָה עָלָיו נִדָּה אָב מֵאֲבוֹת הַטֻּמְאָה וּמִשְׁכַּב בּוֹעֵל נִדָּה וּמֶרְכָּבוֹ וְלַד טֻמְאָה כְּכֵלִים שֶׁנּוֹגֵעַ בָּהֶן שֶׁאֵינָן מְטַמְּאִין אָדָם וְלֹא כֵּלִים אֶלָּא אֳכָלִין וּמַשְׁקִין בִּלְבַד. וְלָמָּה נִגְרְעָה טֻמְאַת מִשְׁכָּבוֹ מִטֻּמְאַת מִשְׁכָּבָהּ מִפְּנֵי שֶׁנֶּאֱמַר בְּבוֹעֵל נִדָּה (ויקרא טו כד) \"וּתְהִי נִדָּתָהּ עָלָיו וְטָמֵא שִׁבְעַת יָמִים\" וְנֶאֱמַר בּוֹ (ויקרא טו כד) \"כָּל הַמִּשְׁכָּב אֲשֶׁר יִשְׁכַּב עָלָיו יִטְמָא\" מֵאַחַר שֶׁנֶּאֱמַר וּתְהִי נִדָּתָהּ עָלָיו אֵינִי יוֹדֵעַ שֶׁהוּא מְטַמֵּא מִשְׁכָּב וְלָמָּה נֶאֱמַר. מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁהַכָּתוּב נִתְּקוֹ מִטֻּמְאָה חֲמוּרָה מִלְּטַמֵּא אָדָם וְכֵלִים וּתְלָאוֹ בְּטֻמְאָה קַלָּה שֶׁיִּהְיֶה מִשְׁכָּבוֹ וָלָד וְלֹא יְטַמֵּא אָדָם וְכֵלִים אֶלָּא אֳכָלִין וּמַשְׁקִין בִּלְבַד כִּשְׁאָר וַלְדוֹת הַטֻּמְאוֹת:","אֶחָד הַבָּא עַל הַנִּדָּה אוֹ עַל שׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם אוֹ עַל הַיּוֹלֶדֶת [בֵּין כְּדַרְכָּן בֵּין שֶׁלֹּא כְּדַרְכָּן] אֶחָד הַמְעָרֶה וְאֶחָד הַגּוֹמֵר בֵּין גָּדוֹל שֶׁבָּא עַל הַקְּטַנָּה בֵּין קָטָן שֶׁבָּא עַל הַגְּדוֹלָה מִתְטַמֵּא מִשּׁוּם בּוֹעֵל נִדָּה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַבּוֹעֵל בֶּן תֵּשַׁע שָׁנִים וְיוֹם אֶחָד וְהַנִּבְעֶלֶת הָיְתָה בַּת שָׁלֹשׁ שָׁנִים וְיוֹם אֶחָד. אֲבָל פָּחוֹת מִכָּאן אֵינוֹ מִתְטַמֵּא מִשּׁוּם בּוֹעֵל נִדָּה אֶלָּא מִשּׁוּם נוֹגֵעַ בְּנִדָּה בִּלְבַד שֶׁהוּא וָלָד וְאֵינוֹ אָב. וְכֵן בּוֹעֵל הַזָּב הֲרֵי הוּא כְּנוֹגֵעַ בּוֹ וְאֶחָד הַנּוֹגֵעַ בְּזָב אוֹ הַנִּבְעֶלֶת מִן הַזָּב:","הַנִּדָּה וְהַזָּבָה וְשׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם וְהַיּוֹלֶדֶת אַף עַל פִּי שֶׁלֹּא רָאֲתָה דָּם כֻּלָּם מְטַמְּאוֹת לְמַפְרֵעַ מֵעֵת לְעֵת אוֹ מִפְּקִידָה לִפְקִידָה וְזֶהוּ הַנִּקְרָא מֵעֵת לְעֵת שֶׁבְּנִדָּה. כֵּיצַד. אִשָּׁה שֶׁהָיְתָה טְהוֹרָה וְאֵין לָהּ וֶסֶת וּבָדְקָה עַצְמָהּ בְּשַׁחֲרִית וּמָצְאָה טְהוֹרָה וּבַחֲצִי הַיּוֹם בָּדְקָה עָצְמָה וּמָצְאָה דָּם הֲרֵי כָּל הַטָּהֳרוֹת שֶׁעָשְׂתָה מִשְּׁעַת פְּקִידָה רִאשׁוֹנָה עַד שְׁעַת פְּקִידָה שְׁנִיָּה טְמֵאוֹת לְמַפְרֵעַ. וְכֵן אִם בָּדְקָה הַיּוֹם וּמָצְאָה טְהוֹרָה וּלְאַחַר שְׁנַיִם אוֹ שְׁלֹשָׁה יָמִים בָּדְקָה וּמָצְאָה דָּם כָּל הַטָּהֳרוֹת שֶׁעָשְׂתָה מֵעֵת שֶׁבָּדְקָה וּמָצְאָה דָּם עַד כ\"ד שָׁעוֹת טְמֵאוֹת לְמַפְרֵעַ. וְעֵד שֶׁלְּאַחַר הַתַּשְׁמִישׁ הֲרֵי הוּא כִּפְקִידָה וְשֶׁלִּפְנֵי הַתַּשְׁמִישׁ אֵינוֹ כִּפְקִידָה מִפְּנֵי שֶׁאֵינָהּ בּוֹדֶקֶת בּוֹ יָפֶה:","אִשָּׁה שֶׁיֵּשׁ לָהּ וֶסֶת וְרָאֲתָה דָּם בִּשְׁעַת וֶסְתָּהּ דַּיָּהּ שְׁעָתָהּ וְאֵינָהּ טְמֵאָה לְמַפְרֵעַ. הִגִּיעַ שְׁעַת וֶסְתָּהּ וְלֹא בָּדְקָה עַצְמָהּ וּלְאַחַר יָמִים בָּדְקָה עַצְמָהּ וּמָצְאָה דָּם הֲרֵי זוֹ טְמֵאָה לְמַפְרֵעַ וַהֲרֵי הִיא בְּחֶזְקַת נִדָּה מִשְּׁעַת וֶסְתָּהּ. וְזוֹ הִיא טֻמְאַת וֶסְתּוֹת הָאֲמוּרָה בְּכָל מָקוֹם. וְאִם מָצְאָה עַצְמָהּ טְהוֹרָה כְּשֶׁבָּדְקָה אַחַר הַוֶּסֶת הֲרֵי זוֹ טְהוֹרָה:","כָּל אִשָּׁה שֶׁיֵּשׁ לָהּ וֶסֶת תַּרְגִּישׁ בְּעַצְמָהּ. מְפַהֶקֶת. אוֹ מִתְעַטֶּשֶׁת. אוֹ חוֹשֶׁשֶׁת פִּי כְּרֵסָהּ וְשִׁפּוּלֵי מֵעֶיהָ. אוֹ אֲחָזָהּ צַמְרוּרִית. אוֹ רֹאשָׁהּ כָּבֵד עָלֶיהָ אוֹ אֵיבָרֶיהָ כְּבֵדִין וְכַיּוֹצֵא בְּאֵלּוּ. וְיֵשׁ אִשָּׁה שֶׁדַּרְכָּהּ לִרְאוֹת בְּעֵת שֶׁיַּתְחִיל בָּהּ מִקְרֶה אֶחָד מֵאֵלּוּ מִיָּד בִּתְחִלָּתוֹ וְיֵשׁ אִשָּׁה שֶׁתַּמְתִּין בְּמִקְרֶה זֶה שָׁעָה אוֹ שְׁתַּיִם וְאַחַר כָּךְ תִּרְאֶה הַדָּם בְּסוֹף הַוֶּסֶת. הָיְתָה לְמוּדָה לִהְיוֹת רוֹאָה בִּתְחִלַּת הַוֶּסֶת כָּל הַטָּהֳרוֹת שֶׁעָשְׂתָה בְּתוֹךְ הַוֶּסֶת טְמֵאוֹת. הָיְתָה לְמוּדָה לִהְיוֹת רוֹאָה בְּסוֹף הַוֶּסֶת כָּל הַטָּהֳרוֹת שֶׁעָשְׂתָה בְּתוֹךְ הַוֶּסֶת טְהוֹרוֹת. וְאֵינָהּ חוֹשֶׁשֶׁת אֶלָּא מִשָּׁעָה שֶׁדַּרְכָּהּ לִרְאוֹת עַד עֵת שֶׁמָּצְאָה דָּם:","הָרוֹאָה כֶּתֶם טְמֵאָה לְמַפְרֵעַ עַד עֵת הַפְּקִידָה. וְכֵן הַבֶּגֶד שֶׁנִּמְצָא עָלָיו הַכֶּתֶם טָמֵא לְמַפְרֵעַ. וְעַד כַּמָּה. עַד שֶׁתֹּאמַר בָּדַקְתִּי הֶחָלוּק הַזֶּה וְלֹא הָיָה עָלָיו כֶּתֶם. אֲפִלּוּ כִּבְּסַתּוּ וְלֹא בְּדָקַתּוּ טָמֵא מִקֹּדֶם הַכִּבּוּס לְמַפְרֵעַ עַד שְׁעַת בְּדִיקָה. וַאֲפִלּוּ נִמְצָא הַכֶּתֶם לַח הֲרֵי זֶה מְטַמֵּא לְמַפְרֵעַ עַד שְׁעַת הַבְּדִיקָה שֶׁאֲנִי אוֹמֵר מִיָּמִים הָיָה שָׁם וְעַתָּה נָפְלוּ עָלָיו מַיִם וְנַעֲשָׂה לַח:","וְכָל הַנָּשִׁים שֶׁדַּיָּן שְׁעָתָן כִּתְמָן כִּרְאִיָּתָן וְאֵינוֹ מְטַמֵּא אוֹתָן לְמַפְרֵעַ. כָּל אֵלּוּ הַנָּשִׁים הַטְּמֵאוֹת לְמַפְרֵעַ בֵּין רָאֲתָה דָּם בֵּין מָצָאתָה כֶּתֶם מְטַמְּאוֹת מִשְׁכָּב וּמֶרְכָּב לְמַפְרֵעַ לְטַמֵּא אָדָם וּבְגָדִים. וְכֵן רֻקָּן וּמֵימֵי רַגְלֵיהֶן טְמֵאִין לְמַפְרֵעַ. וַאֲפִלּוּ כְּלִי חֶרֶשׂ הַמֻּקָּף צָמִיד פָּתִיל מְטַמְּאוֹת אוֹתָן לְמַפְרֵעַ. אֲבָל אֵינָן מְטַמְּאוֹת אֶת הַבּוֹעֵל לְמַפְרֵעַ מִשּׁוּם בּוֹעֵל נִדָּה אֶלָּא מִשּׁוּם נוֹגֵעַ בִּלְבַד. אֲבָל הָרוֹאָה כֶּתֶם הַבּוֹעֵל אוֹתָהּ מֵאַחַר שֶׁנִּמְצֵאת הַכֶּתֶם טָמֵא מִשּׁוּם בּוֹעֵל נִדָּה:","מְעֻבֶּרֶת שֶׁהוֹצִיא הָעֻבָּר אֶת יָדוֹ וְהֶחֱזִירָהּ אִמּוֹ טְמֵאָה לֵדָהּ. וְטֻמְאַת יוֹלֶדֶת (י\"ד) וְטֻמְאַת מֵעֵת לְעֵת אוֹ מִפְּקִידָה לִפְקִידָה לְמַפְרֵעַ כְּמוֹ שֶׁבֵּאַרְנוּ וְטֻמְאַת וְסָתוֹת וְטֻמְאַת כְּתָמִים הַכּל מִדִּבְרֵי סוֹפְרִים וְטֻמְאָתָן מִסָּפֵק לְפִיכָךְ אֵין שׂוֹרְפִין עֲלֵיהֶן תְּרוּמָה וְקָדָשִׁים אֶלָּא תּוֹלִין. וְכֵן חֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ שֶׁנִּטְמְאוּ בְּאֵלּוּ תּוֹלִין. אֲבָל הַנַּעֲשִׂים עַל טָהֳרַת הַתְּרוּמָה וְחֻלִּין הַטְּבוּלִין לְחַלָּה אֵין מִתְטַמְּאִין בְּכָל אֵלּוּ הַטֻּמְאוֹת שֶׁהֵן מִדִּבְרֵיהֶן. נִמְצֵאתָ אוֹמֵר שֶׁכָּל אַחַת מֵאֵלּוּ הַנָּשִׁים וּמִשְׁכָּבָן וּמֶרְכָּבָן וְרֻקָּן וּמֵימֵי רַגְלֵיהֶן וּבוֹעֵל רוֹאָה כֶּתֶם מֵאַחַר שֶׁנִּמְצָא הַכֶּתֶם וּבוֹעֵל יוֹלֶדֶת מֵאַחַר שֶׁיָּצָא הָאֵיבָר וְחָזַר כֻּלָּן אֲבוֹת טֻמְאוֹת מִדִּבְרֵי סוֹפְרִים:"],"Mishneh Torah, Tithes 14":["הַלוֹקֵחַ מִן הַסִּיטוֹן וִחָזַר וְלָקַח מִמֶּנּוּ פַּעַם שְׁנִיָּה לֹא יְעַשֵּׂר מִזֶּה עַל זֶה אַף עַל פִּי שֶׁהוּא מִין אֶחָד אֲפִלּוּ מִקֻּפָּה אַחַת. אַף עַל פִּי שֶׁמַּכִּיר אֶת הֶחָבִית שֶׁהִיא הִיא. מִפְּנֵי שֶׁהַסִּיטוֹן לוֹקֵחַ מֵאֲנָשִׁים הַרְבֵּה וּמוֹכֵר. וְשֶׁמָּא לָקַח זֶה שֶׁמָּכַר תְּחִלָּה מֵעַם הָאָרֶץ שֶׁפֵּרוֹתָיו דְּמַאי וְזֶה שֶׁלָּקַח בַּסּוֹף מֵחָבֵר שֶׁפֵּרוֹתָיו מְתֻקָּנִין. וּכְבָר בֵּאַרְנוּ שֶׁאֵין מְעַשְּׂרִין מִן הַחַיָּב עַל הַפָּטוּר וְלֹא מִן הַפָּטוּר עַל הַחַיָּב. וְאִם אָמַר הַסִּיטוֹן מִשֶּׁל אֶחָד הֵן נֶאֱמָן:","הָיָה מוֹכֵר כְּשׁוּת אוֹ יָרָק וְהֵן מְבִיאִין וְצוֹבְרִין לְפָנָיו הַלּוֹקֵחַ מִמֶּנּוּ מְעַשֵּׂר מִכָּל כְּשׁוּת וּכְשׁוּת וּמִכָּל אֲגֻדָּה וַאֲגֻדָּה וּמִכָּל תְּמָרָה וּתְמָרָה:","הַלּוֹקֵחַ מִבַּעַל הַבַּיִת וְחָזַר וְלָקַח מִמֶּנּוּ שְׁנִיָּה. מְעַשֵּׂר מִזֶּה עַל זֶה. אֲפִלּוּ מִשְּׁתֵּי קֻפּוֹת אֲפִלּוּ מִשְּׁתֵּי עֲיָרוֹת. שֶׁחֶזְקָתוֹ שֶׁאֵינוֹ מוֹכֵר אֶלָּא מִשֶּׁלּוֹ:","בַּעַל הַבַּיִת שֶׁהָיָה מוֹכֵר יָרָק בַּשּׁוּק בִּזְמַן שֶׁמְּבִיאִין לוֹ מִגִּנּוֹתָיו מְעַשֵּׂר מֵאֶחָד עַל הַכּל. וּבִזְמַן שֶׁמְּבִיאִין לוֹ מִגִּנּוֹת אֲחֵרוֹת אִם לָקַח מִמֶּנּוּ וְחָזַר וְלָקַח מִמֶּנּוּ פַּעַם שְׁנִיָּה לֹא יְעַשֵּׂר מִזֶּה עַל זֶה:","הַלּוֹקֵחַ פַּת מִן הַנַּחְתּוֹם לֹא יְעַשֵּׂר מִן הַחַמָּה עַל הַצּוֹנֶנֶת שֶׁאֲנִי אוֹמֵר חִטִּים שֶׁל אֶמֶשׁ הָיוּ מִשֶּׁל אֶחָד וְשֶׁל הַיּוֹם מִשֶּׁל אַחֵר:","הַלּוֹקֵחַ מִן הַפַּלְטֵר אַף עַל פִּי שֶׁהֵן דְּפוּסִין הַרְבֵּה מְעַשֵּׂר מֵאֶחָד עַל הַכּל. שֶׁהַנַּחְתּוֹם שֶׁמּוֹכֵר לַמַּנְפּוֹל עוֹשֶׂה עִסָּתוֹ דְּפוּסִין הַרְבֵּה. אֲבָל הַלּוֹקֵחַ מִן הַמַּנְפּוֹל מְעַשֵּׂר מִכָּל דְּפוּס וּדְפוּס. שֶׁהַמַּנְפּוֹל לוֹקֵחַ מִשְּׁנֵי נַחְתּוֹמִין:","תִּשְׁעָה מַנְפּוֹלִין שֶׁלָּקְחוּ מֵעֲשָׂרָה נַחְתּוֹמִין הוֹאִיל וְאֶחָד מֵהֶן לָקַח מִשְּׁנַיִם כָּל הַלּוֹקֵחַ מֵאֶחָד מִן הַתִּשְׁעָה מְעַשֵּׂר מִכָּל דְּפוּס וּדְפוּס:","הַלּוֹקֵחַ מִן הֶעָנִי וְכֵן הֶעָנִי שֶׁנָּתְנוּ לוֹ פְּרוּסוֹת פַּת אוֹ פִּלְחֵי דְּבֵלָה מְעַשֵּׂר מִכָּל אַחַת וְאַחַת. וּבִתְמָרִים וּבִגְרוֹגָרוֹת בּוֹלֵל הַכּל וּמְעַשֵּׂר. אֵימָתַי בִּזְמַן שֶׁהַמַּתָּנָה מְרֻבָּה. אֲבָל בְּמֻעֶטֶת מְעַשֵּׂר מִכָּל מַתָּנָה וּמַתָּנָה:","שָׁחַק אֶת הַפַּת וַעֲשָׂאָהּ פֵּרוּרִין וְאֶת הַגְּרוֹגָרוֹת וַעֲשָׂאָן דְּבֵלָה מְעַשֵּׂר מֵאֶחָד עַל הַכּל:","פּוֹעֲלִים אוֹ אוֹרְחִים שֶׁהָיוּ מְסֻבִּין וְאוֹכְלִין וְהוֹתִירוּ פְּרוּסוֹת מְעַשֵּׂר מִכָּל אַחַת וְאַחַת: סְלִיקוּ לְהוּ הִלְכוֹת מַעשֵׂר בְּסִיַעְתָּא דִּשְׁמַיָּא"],"Mishneh Torah, Torah Study 4":["אֵין מְלַמְּדִין תּוֹרָה אֶלָּא לְתַלְמִיד הָגוּן נָאֶה בְּמַעֲשָׂיו. אוֹ לְתָם. אֲבָל אִם הָיָה הוֹלֵךְ בְּדֶרֶךְ לֹא טוֹבָה מַחְזִירִין אוֹתוֹ לַמּוּטָב וּמַנְהִיגִין אוֹתוֹ בְּדֶרֶךְ יְשָׁרָה וּבוֹדְקִין אוֹתוֹ וְאַחַר כָּךְ מַכְנִיסִין אוֹתוֹ לְבֵית הַמִּדְרָשׁ וּמְלַמְּדִין אוֹתוֹ. אָמְרוּ חֲכָמִים כָּל הַשּׁוֹנֶה לְתַלְמִיד שֶׁאֵינוֹ הָגוּן כְּאִלּוּ זָרַק אֶבֶן לְמַרְקוּלִיס שֶׁנֶּאֱמַר (משלי כו ח) \"כִּצְרוֹר אֶבֶן בְּמַרְגֵּמָה כֵּן נוֹתֵן לִכְסִיל כָּבוֹד\". וְאֵין כָּבוֹד אֶלָּא תּוֹרָה שֶׁנֶּאֱמַר (משלי ג לה) \"כָּבוֹד חֲכָמִים יִנְחָלוּ\". וְכֵן הָרַב שֶׁאֵינוֹ הוֹלֵךְ בְּדֶרֶךְ טוֹבָה אַף עַל פִּי שֶׁחָכָם גָּדוֹל הוּא וְכָל הָעָם צְרִיכִין לוֹ אֵין מִתְלַמְּדִין מִמֶּנּוּ עַד שׁוּבוֹ לַמּוּטָב. שֶׁנֶּאֱמַר (מלאכי ב ז) \"כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ כִּי מַלְאַךְ ה' צְבָאוֹת הוּא\". אָמְרוּ חֲכָמִים אִם הָרַב דּוֹמֶה לְמַלְאַךְ ה' צְבָאוֹת תּוֹרָה יְבַקְּשׁוּ מִפִּיהוּ אִם לָאו אַל יְבַקְּשׁוּ תּוֹרָה מִפִּיהוּ:","כֵּיצַד מְלַמְּדִים. הָרַב יוֹשֵׁב בָּרֹאשׁ וְהַתַּלְמִידִים מֻקָּפִים לְפָנָיו כַּעֲטָרָה כְּדֵי שֶׁיְּהוּ כֻּלָּם רוֹאִים הָרַב וְשׁוֹמְעִים דְּבָרָיו. וְלֹא יֵשֵׁב הָרַב עַל הַכִּסֵּא וְתַלְמִידָיו עַל הַקַּרְקַע אֶלָּא אוֹ הַכּל עַל הָאָרֶץ אוֹ הַכּל עַל הַכִּסְאוֹת. וּבָרִאשׁוֹנָה הָיָה הָרַב יוֹשֵׁב וְהַתַּלְמִידִים עוֹמְדִים וּמִקֹּדֶם חֻרְבַּן בַּיִת שֵׁנִי נָהֲגוּ הַכּל לְלַמֵּד לַתַּלְמִידִים וְהֵם יוֹשְׁבִים:","אִם הָיָה מְלַמֵּד מִפִּיו לַתַּלְמִידִים מְלַמֵּד. וְאִם הָיָה מְלַמֵּד עַל פִּי מְתַרְגֵּם [הַמְתַרְגֵּם] עוֹמֵד בֵּינוֹ וּבֵין הַתַּלְמִידִים וְהָרַב אוֹמֵר לַמְתַרְגֵּם וְהַמְתַרְגֵּם מַשְׁמִיעַ לְכָל הַתַּלְמִידִים. וּכְשֶׁהֵם שׁוֹאֲלִין לַמְתַרְגֵּם הוּא שׁוֹאֵל לָרַב וְהָרַב מֵשִׁיב לַמְתַרְגֵּם וְהַמְתַרְגֵּם מֵשִׁיב לַשּׁוֹאֵל. וְלֹא יַגְבִּיהַּ הָרַב קוֹלוֹ יוֹתֵר מִקּוֹל הַמְתַרְגֵּם. וְלֹא יַגְבִּיהַּ הַמְתַרְגֵּם קוֹלוֹ בְּעֵת שֶׁשּׁוֹאֵל אֶת הָרַב יוֹתֵר מִקּוֹל הָרַב. אֵין הַמְתַרְגֵּם רַשַּׁאי לֹא לִפְחֹת וְלֹא לְהוֹסִיף וְלֹא לְשַׁנּוֹת אֶלָּא אִם כֵּן הָיָה הַמְתֻרְגְּמָן אָבִיו שֶׁל חָכָם אוֹ רַבּוֹ. אוֹמֵר הָרַב לַמְתֻרְגְּמָן כָּךְ אָמַר לִי רַבִּי אוֹ כָּךְ אָמַר לִי אַבָּא מָרִי. וּכְשֶׁאוֹמֵר הַמְתֻרְגְּמָן הַדְּבָרִים לָעָם אוֹמֵר בְּשֵׁם הֶחָכָם וּמַזְכִּיר שְׁמוֹ שֶׁל אֲבִי הָרַב אוֹ שֶׁל רַבּוֹ וְאוֹמֵר כָּךְ אָמַר רַבָּנָא פְּלוֹנִי אַף עַל פִּי שֶׁלֹּא הִזְכִּיר הָרַב שְׁמוֹ שֶׁל חָכָם. שֶׁאָסוּר לִקְרוֹת לְרַבּוֹ אוֹ לְאָבִיו בִּשְׁמוֹ:","הָרַב שֶׁלִּמֵּד וְלֹא הֵבִינוּ הַתַּלְמִידִים לֹא יִכְעֹס עֲלֵיהֶם וְיִרְגַּז אֶלָּא חוֹזֵר וְשׁוֹנֶה הַדָּבָר אֲפִלּוּ כַּמָּה פְּעָמִים עַד שֶׁיָּבִינוּ עֹמֶק הַהֲלָכָה. וְכֵן לֹא יֹאמַר הַתַּלְמִיד הֵבַנְתִּי וְהוּא לֹא הֵבִין אֶלָּא חוֹזֵר וְשׁוֹאֵל אֲפִלּוּ כַּמָּה פְּעָמִים. וְאִם כָּעַס עָלָיו רַבּוֹ וְרָגַז יֹאמַר לוֹ רַבִּי תּוֹרָה הִיא וְלִלְמֹד אֲנִי צָרִיךְ וְדַעְתִּי קְצָרָה:","לֹא יִהְיֶה הַתַּלְמִיד בּוֹשׁ מֵחֲבֵרָיו שֶׁלָּמְדוּ מִפַּעַם רִאשׁוֹנָה אוֹ שְׁנִיָּה וְהוּא לֹא לָמַד אֶלָּא אַחַר כַּמָּה פְּעָמִים. שֶׁאִם נִתְבַּיֵּשׁ מִדָּבָר זֶה נִמְצָא נִכְנָס וְיוֹצֵא לְבֵית הַמִּדְרָשׁ וְהוּא אֵינוֹ לָמֵד כְּלוּם. לְפִיכָךְ אָמְרוּ חֲכָמִים הָרִאשׁוֹנִים אֵין הַבַּיְשָׁן לָמֵד וְלֹא הַקַּפְּדָן מְלַמֵּד. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁלֹּא הֵבִינוּ הַתַּלְמִידִים הַדָּבָר מִפְּנֵי עָמְקוֹ אוֹ מִפְּנֵי דַּעְתָּן שֶׁהִיא קְצָרָה. אֲבָל אִם נִכָּר לָרַב שֶׁהֵם מִתְרַשְּׁלִין בְּדִבְרֵי תּוֹרָה וּמִתְרַפִּין עֲלֵיהֶן וּלְפִיכָךְ לֹא הֵבִינוּ חַיָּב לִרְגֹז עֲלֵיהֶן וּלְהַכְלִימָן בִּדְבָרִים כְּדֵי לְחַדְּדָם. וּכְעִנְיָן זֶה אָמְרוּ חֲכָמִים זְרֹק מָרָה בַּתַּלְמִידִים. לְפִיכָךְ אֵין רָאוּי לָרַב לִנְהֹג קַלּוּת רֹאשׁ לִפְנֵי הַתַּלְמִידִים וְלֹא לִשְׂחֹק בִּפְנֵיהֶם וְלֹא לֶאֱכל וְלִשְׁתּוֹת עִמָּהֶם כְּדֵי שֶׁתְּהֵא אֵימָתוֹ עֲלֵיהֶן וְיִלְמְדוּ מִמֶּנּוּ בִּמְהֵרָה:","אֵין שׁוֹאֲלִין אֶת הָרַב כְּשֶׁיִּכָּנֵס לַמִּדְרָשׁ עַד שֶׁתִּתְיַשֵּׁב דַּעְתּוֹ עָלָיו. וְאֵין הַתַּלְמִיד שׁוֹאֵל כְּשֶׁיִּכָּנֵס עַד שֶׁיִּתְיַשֵּׁב וְיָנוּחַ. וְאֵין שׁוֹאֲלִין שְׁנַיִם כְּאֶחָד. וְאֵין שׁוֹאֲלִין אֶת הָרַב מֵעִנְיָן אַחֵר אֶלָּא מֵאוֹתוֹ הָעִנְיָן שֶׁהֵן עֲסוּקִין בּוֹ כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ. וְיֵשׁ לָרַב לְהַטְעוֹת אֶת הַתַּלְמִידִים בִּשְׁאֵלוֹתָיו וּבַמַּעֲשִׂים שֶׁעוֹשֶׂה בִּפְנֵיהֶם כְּדֵי לְחַדְּדָן. וּכְדֵי שֶׁיֵּדַע אִם זוֹכְרִים הֵם מַה שֶּׁלִּמְּדָם אוֹ אֵינָם זוֹכְרִים. וְאֵין צָרִיךְ לוֹמַר שֶׁיֵּשׁ לוֹ רְשׁוּת לִשְׁאל אוֹתָם בְּעִנְיָן אַחֵר שֶׁאֵין עוֹסְקִין בּוֹ כְּדֵי לְזָרְזָם:","אֵין שׁוֹאֲלִין מְעֻמָּד וְאֵין מְשִׁיבִין מְעֻמָּד וְלֹא מִגָּבוֹהַּ וְלֹא מֵרָחוֹק וְלֹא מֵאֲחוֹרֵי הַזְּקֵנִים. וְאֵין שׁוֹאֲלִין הָרַב אֶלָּא בְּעִנְיָן שֶׁהֵן קוֹרִין בּוֹ. וְאֵין שׁוֹאֲלִין אֶלָּא מִיִּרְאָה. וְלֹא יִשְׁאַל בָּעִנְיָן יוֹתֵר מִשָּׁלֹשׁ הֲלָכוֹת:","שְׁנַיִם שֶׁשָּׁאֲלוּ. שָׁאַל אֶחָד כָּעִנְיָן וְשָׁאַל אֶחָד שֶׁלֹּא כָּעִנְיָן נִזְקָקִין לָעִנְיָן. מַעֲשֶׂה וְשֶׁאֵינוֹ מַעֲשֶׂה נִזְקָקִין לַמַּעֲשֶׂה. הֲלָכָה וּמִדְרָשׁ נִזְקָקִין לַהֲלָכָה. מִדְרָשׁ וְאַגָּדָה נִזְקָקִין לַמִּדְרָשׁ. אַגָּדָה וְקַל וָחֹמֶר נִזְקָקִין לַקַּל וָחֹמֶר. קַל וָחֹמֶר וּגְזֵרָה שָׁוָה נִזְקָקִין לַקַּל וָחֹמֶר. הָיוּ הַשּׁוֹאֲלִין שְׁנַיִם אֶחָד חָכָם וְאֶחָד תַּלְמִיד נִזְקָקִין לֶחָכָם. תַּלְמִיד וְעַם הָאָרֶץ נִזְקָקִין לַתַּלְמִיד. שְׁנֵיהֶם חֲכָמִים שְׁנֵיהֶם תַּלְמִידִים שְׁנֵיהֶם עַמֵּי הָאָרֶץ שָׁאֲלוּ שְׁנֵיהֶם בִּשְׁתֵּי הֲלָכוֹת אוֹ בִּשְׁתֵּי תְּשׁוּבוֹת אוֹ בִּשְׁתֵּי שְׁאֵלוֹת שְׁנֵי מַעֲשִׂים. הָרְשׁוּת בְּיַד הַמְתַרְגֵּם מֵעַתָּה:","אֵין יְשֵׁנִים בְּבֵית הַמִּדְרָשׁ וְכָל הַמִּתְנַמְנֵם בְּבֵית הַמִּדְרָשׁ חָכְמָתוֹ נַעֲשֵׂית קְרָעִים קְרָעִים. וְכֵן אָמַר שְׁלֹמֹה בְּחָכְמָתוֹ (משלי כג כא) \"וּקְרָעִים תַּלְבִּישׁ נוּמָה\". וְאֵין מְשִׂיחִין בְּבֵית הַמִּדְרָשׁ אֶלָּא בְּדִבְרֵי תּוֹרָה בִּלְבַד. אֲפִלּוּ מִי שֶׁנִּתְעַטֵּשׁ אֵין אוֹמְרִים לוֹ רְפוּאָה בְּבֵית הַמִּדְרָשׁ וְאֵין צָרִיךְ לוֹמַר שְׁאָר הַדְּבָרִים. וּקְדֻשַּׁת בֵּית הַמִּדְרָשׁ חֲמוּרָה מִקְּדֻשַּׁת בָּתֵּי כְּנֵסִיּוֹת:"],"Mishneh Torah, Transmission of the Oral Law 17":["אַף עַל פִּי שֶׁאֵלּוּ הָאַחַד עָשָׂר קִבְּלוּ מֵרַבֵּנוּ הַקָּדוֹשׁ וְעָמְדוּ בְּמִדְרָשׁוֹ, רִבִּי יוֹחָנָן קָטָן הָיָה וְאַחַר כָּךְ הָיָה תַּלְמִיד לְרִבִּי יַנַּאי וְקִבַּל מִמֶּנּוּ תּוֹרָה. וְכֵן רָב קִבַּל מֵרִבִּי יַנַּאי; וּשְׁמוּאֵל קִבַּל מֵרִבִּי חֲנַנְיָה בֶּן חָמָא."],"Mishneh Torah, Transmission of the Oral Law 28":["וְחִבְּרוּ חַכְמֵי מִשְׁנָה חִבּוּרִין אֲחֵרִים, לְפָרַשׁ דִּבְרֵי הַתּוֹרָה: רִבִּי הוֹשַׁעְיָה תַּלְמִידוֹ שֶׁלְּרַבֵּנוּ הַקָּדוֹשׁ, חִבַּר בֵּאוּר סֵפֶר בְּרֵאשִׁית. וְרִבִּי יִשְׁמָעֵאל פֵּרַשׁ מֵאֵלֶּה שְׁמוֹת עַד סוֹף הַתּוֹרָה, וְהוּא הַנִּקְרָא מְכִלְּתָא; וְכֵן רִבִּי עֲקִיבָה חִבַּר מְכִלְּתָא. וַחֲכָמִים אֲחֵרִים אַחֲרֵיהֶם חִבְּרוּ מִדְרָשׁוֹת. וְהַכֹּל חֻבַּר קֹדֶם הַתַּלְמוּד הַבַּבְלִי."],"Mishneh Torah, Transmission of the Oral Law 39":["וְעוֹד חִבְּרוּ הֲלָכוֹת פְּסוּקוֹת, בְּעִנְיַן הָאָסוּר וְהַמֻּתָּר וְהַחַיָּב וְהַפָּטוּר, בִּדְבָרִים שֶׁהַשָּׁעָה צְרִיכָה לָהֶם, כְּדֵי שֶׁיִּהְיוּ קְרוֹבִין לְמַדַּע מִי שְׁאֵינוּ יָכוֹל לֵירַד לְעָמְקוֹ שֶׁלַּתַּלְמוּד. וְזוֹ הִיא מְלֶאכֶת ה' שֶׁעָשׂוּ בָּהּ כָּל גְּאוֹנֵי יִשְׂרָאֵל, מִיּוֹם שֶׁחֻבַּר הַתַּלְמוּד וְעַד זְמָן זֶה, שְׁהוּא שָׁנָה שְׁמִינִית אַחַר מֵאָה וְאֶלֶף לְחָרְבָּן."],"Mishneh Torah, Transmission of the Oral Law 9":["חֲמִשָּׁה תַּלְמִידִים הָיוּ לוֹ לְרַבַּן יוֹחָנָן בֶּן זַכַּאי, וְהֶם גְּדוֹלֵי הַחֲכָמִים שֶׁקִּבְּלוּ מִמֶּנּוּ; וְאֵלּוּ הֶם – רִבִּי אֱלִיעֶזֶר הַגָּדוֹל, וְרִבִּי יְהוֹשׁוּעַ, וְרִבִּי יוֹסֵי הַכּוֹהֵן, וְרִבִּי שִׁמְעוֹן בֶּן נְתַנְאֵל, וְרִבִּי אֶלְעָזָר בֶּן עֲרָךְ. וְרִבִּי עֲקִיבָה בֶּן יוֹסֵף קִבַּל מֵרִבִּי אֱלִיעֶזֶר הַגָּדוֹל, וְיוֹסֵף אָבִיו גֵּר צֶדֶק הָיָה. וְרִבִּי יִשְׁמָעֵאל וְרִבִּי מֵאִיר בֶּן גֵּר הַצֶּדֶק קִבְּלוּ מֵרִבִּי עֲקִיבָה, וְגַם קִבַּל רִבִּי מֵאִיר וַחֲבֵרָיו מֵרִבִּי יִשְׁמָעֵאל."],"Mishneh Torah, Vessels 12":["כְּלֵי עֵץ וּכְלֵי עוֹר וּכְלֵי עֶצֶם שֶׁנִּשְׁבְּרוּ טִהֲרוּ מִטֻּמְאָתָן. חָזַר וְעָשָׂה כְּלִי מִשִּׁבְרֵיהֶם אוֹ שֶׁקִּבֵּץ אֶת שִׁבְרֵיהֶן וְעָשָׂה מֵהֶן כֵּלִים אֲחֵרִים הֲרֵי אֵלּוּ כִּשְׁאָר הַכֵּלִים הַטְּהוֹרִים שֶׁלֹּא נִטְמְאוּ מִקֹּדֶם שֶׁהֵן מְקַבְּלִין טֻמְאָה מִכָּאן וּלְהַבָּא. וְכֵן כְּלֵי מַתָּכוֹת שֶׁנִּשְׁבְּרוּ אַחַר שֶׁנִּטְמְאוּ טִהֲרוּ. הִתִּיכָן וְחָזַר וְעָשָׂה מֵהֶן כֵּלִים אֲחֵרִים חָזְרוּ לַטֻּמְאָה הַיְשָׁנָה. וְאֵין לִכְלֵי מַתָּכוֹת טָהֳרָה גְּמוּרָה עַד שֶׁיַּטְבִּילֵם בְּמִקְוֶה כְּשֶׁהֵם שְׁלֵמִים אוֹ יִשָּׁאֲרוּ שְׁבוּרִים:","וַחֲזָרַת כְּלֵי מַתָּכוֹת לְטֻמְאָתָן הַיְשָׁנָה מִדִּבְרֵי סוֹפְרִים וּמִפְּנֵי מָה גָּזְרוּ עַל כְּלֵי מַתָּכוֹת שֶׁיַּחְזְרוּ לְטֻמְאָתָן הַיְשָׁנָה גְּזֵרָה שֶׁמָּא יְטַמֵּא לוֹ כְּלִי וְיַתִּיכֶנּוּ וְיַעֲשֶׂה מִמֶּנּוּ כְּלִי אַחֵר בּוֹ בְּיוֹם אִם יֹאמַר שֶׁהוּא טָהוֹר כְּדִין תּוֹרָה יָבוֹא לוֹמַר הַשְּׁבִירָה מְטַהֶרֶת וְהַטְּבִילָה מְטַהֶרֶת כְּשֵׁם שֶׁאִם נִשְׁבַּר וְהִתִּיכוֹ וְעָשָׂה מִמֶּנּוּ כְּלִי כְּשֶׁהָיָה הֲרֵי הוּא טָהוֹר בּוֹ בַּיּוֹם כָּךְ אִם הִטְבִּילוֹ אַף עַל פִּי שֶׁהוּא כְּשֶׁהָיָה הֲרֵי הוּא טָהוֹר בּוֹ בַּיּוֹם וְיָבוֹאוּ לוֹמַר שֶׁאֵין הַכֵּלִים צְרִיכִין הַעֲרֵב שֶׁמֶשׁ מִפְּנֵי זֶה הַחֲשָׁשׁ גָּזְרוּ טֻמְאָה עֲלֵיהֶם:","אֶחָד כְּלִי שֶׁנִּטְמָא בְּמֵת אוֹ בִּשְׁאָר הַטֻּמְאוֹת אִם הִתִּיכוֹ חָזַר לְטֻמְאָתוֹ הַיְשָׁנָה עַד שֶׁיַּטְבִּיל. נִטְמָא בְּמֵת וְהִזָּה עָלָיו בַּשְּׁלִישִׁי וְאַחַר כָּךְ הִתִּיכוֹ וַעֲשָׂאָהוּ כְּלִי אַחֵר וְהִזָּה עָלָיו בַּשְּׁבִיעִי וְהִטְבִּילוֹ הֲרֵי זֶה טָמֵא וְאֵין הַזָּיָה שֶׁקֹּדֶם הִתּוּךְ מִצְטָרֶפֶת לְהַזָּאָה שֶׁאַחַר הִתּוּךְ וְאֵין לוֹ טָהֳרָה עַד שֶׁיַּזֶּה עָלָיו שְׁלִישִׁי וּשְׁבִיעִי וְיַטְבִּיל כְּשֶׁהוּא כְּלִי קֹדֶם שְׁבִירָה אוֹ יַזֶּה עָלָיו שְׁלִישִׁי וּשְׁבִיעִי וְיַטְבִּיל אַחַר שֶׁיַּתִּיכֶנּוּ:","בַּרְזֶל טָמֵא שֶׁבְּלָלוֹ עִם בַּרְזֶל טָהוֹר אִם רֹב מִן הַטָּמֵא טָמֵא וְאִם רֹב מִן הַטָּהוֹר טָהוֹר. מֶחֱצָה לְמֶחֱצָה טָמֵא. וְכֵן טִיט שֶׁבְּלָלוֹ בִּגְלָלִים וְשָׂרַף הַכּל בְּכִבְשָׁן וַעֲשָׂאָהוּ כְּלִי אִם רֹב מִן הַטִּיט הֲרֵי זֶה מְקַבֵּל טֻמְאָה מִפְּנֵי שֶׁהוּא כְּלִי חֶרֶס וְאִם רֹב מִן הַגְּלָלִים אֵינוֹ מְקַבֵּל טֻמְאָה:","כְּלֵי מַתָּכוֹת הַטְּהוֹרִין שֶׁאֲנָכָן בַּאֲנָךְ טָמֵא טְמֵאִים. אֲבָל הָעוֹשֶׂה כֵּלִים מִן הָאֲנָךְ הַטָּמֵא הֲרֵי הֵן טְהוֹרִין:","קוֹרְדוֹם שֶׁעֲשָׂאָהוּ מִן הַבַּרְזֶל הַטָּהוֹר וְעָשָׂה עֻשְׁפּוֹ מִן הַטָּמֵא הֲרֵי זֶה טָמֵא. עָשָׂה עֻשְׁפּוֹ מִן הַטָּהוֹר וְהַקּוֹרְדוֹם מִן הַטָּמֵא הֲרֵי זֶה טָהוֹר. שֶׁהַכּל הוֹלֵךְ אַחַר עוֹשֵׂה הַמְּלָאכָה:","קוֹרְדוֹם טָהוֹר שֶׁחֲסָמוֹ בְּבַרְזֶל טָמֵא טָהוֹר:","קִיתוֹן שֶׁעֲשָׂאָהוּ מִן הַטָּמֵא וְשׁוּלָיו מִן הַטָּהוֹר טָהוֹר. עֲשָׂאָהוּ מִן הַטָּהוֹר וְשׁוּלָיו מִן הַטָּמֵא טָמֵא. שֶׁהַכּל הוֹלֵךְ אַחַר הַמְקַבֵּל הָעוֹשֵׂה מְלָאכָה:","כְּלִי מַתָּכוֹת שֶׁנִּטְמָא בְּטֻמְאָה שֶׁהִיא מִדִּבְרֵי סוֹפְרִים כְּגוֹן שֶׁנִּטְמָא בַּעֲבוֹדָה זָרָה וְכַיּוֹצֵא בָּהּ וְנִשְׁבַּר וְהִתִּיכוֹ וְחָזַר וְעָשָׂה מִמֶּנּוּ כְּלִי אַחֵר הֲרֵי זֶה סָפֵק אִם חָזַר לְטֻמְאָתוֹ הַיְשָׁנָה אוֹ לֹא חָזַר:","כְּלֵי זְכוּכִית שֶׁנִּטְמְאוּ וְנִשְׁבְּרוּ טָהֲרוּ כְּכָל הַכֵּלִים וַאֲפִלּוּ הִתִּיכָן וְעָשָׂה מֵהֶן כֵּלִים אֲחֵרִים אֵינָם חוֹזְרִים לַטֻּמְאָה הַיְשָׁנָה לְפִי שֶׁעִקַּר טֻמְאָתָהּ מִדִּבְרֵי סוֹפְרִים כְּמוֹ שֶׁבֵּאַרְנוּ לֹא גָּזְרוּ עֲלֵיהֶן בְּטֻמְאָה יְשָׁנָה. וְכֵן כְּלֵי זְכוּכִית שֶׁנִּשְׁבְּרוּ אַף עַל פִּי שֶׁשִּׁבְרֵיהֶן כֵּלִים וּרְאוּיִין לְתַשְׁמִישׁ הוֹאִיל וְהֵם שִׁבְרֵי כֵּלִים אֵינָן מְקַבְּלִין טֻמְאָה לְפִי שֶׁאֵינָן דּוֹמִין לִכְלֵי חֶרֶס. כֵּיצַד. קְעָרָה שֶׁל זְכוּכִית שֶׁנִּשְׁבְּרָה וְהִתְקִין שׁוּלַיִם לְתַשְׁמִישׁ אֵין הַשּׁוּלַיִם מְקַבְּלִין טֻמְאָה אַף עַל פִּי שֶׁהֵן בַּקְּעָרָה. וְאִם קִרְסֵם אֶת מְקוֹם הַשֶּׁבֶר וְשָׁפוֹ בְּשׁוּפִין הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה:","צְלוֹחִית קְטַנָּה הַנִּטֶּלֶת בְּיָד אַחַת שֶׁנִּטַּל פִּיהָ מְקַבֶּלֶת טֻמְאָה מִפְּנֵי שֶׁאֵין מַכְנִיסִין הַיָּד לְתוֹכָהּ אֶלָּא יוֹצֵק מִמֶּנָּה. אֲבָל גְּדוֹלָה הַנִּטֶּלֶת בִּשְׁתֵּי יָדַיִם שֶׁנִּטַּל פִּיהָ טְהוֹרָה מִפְּנֵי שֶׁהִיא חוֹבֶלֶת בַּיָּד בְּשָׁעָה שֶׁמַּכְנִיס יָדוֹ לְתוֹכָהּ. וְכֵן צְלוֹחִית שֶׁל פַּלְיָטוֹן אַף עַל פִּי שֶׁהִיא קְטַנָּה אִם נִטֶּלֶת פִּיהָ טְהוֹרָה מִפְּנֵי שֶׁחוֹבֶלֶת בְּאֶצְבָּעוֹ בְּשָׁעָה שֶׁמּוֹצִיא הַבּשֶֹׁם מִתּוֹכָהּ:","לָגִינִים הַגְּדוֹלִין שֶׁנִּטַּל פִּיהֶן עֲדַיִן הֵן כֵּלִים מִפְּנֵי שֶׁמַּתְקִינָם הוּא לְכִבְשָׁנִים:","כּוֹס שֶׁנִּפְגַּם רֻבּוֹ טָהוֹר. נִפְגַּם בּוֹ שְׁלִישׁ הֶקֵּפוֹ בְּרֹב גָּבְהוֹ טָהוֹר. נִקַּב וּסְתָמוֹ בֵּין בְּבַעַץ בֵּין בְּזֶפֶת טָהוֹר. וְהַכּוֹס וְהַצְּלוֹחִית שֶׁנִּקְּבוּ בֵּין מִלְּמַעְלָה בֵּין מִלְּמַטָּה טְהוֹרִין:","הַתַּמְחוּי וְהַקְּעָרָה שֶׁנִּקְּבוּ מִלְּמַעְלָה טְמֵאִין מִלְּמַטָּה טְהוֹרִין. נִסְדְּקוּ אִם יְכוֹלִין לְקַבֵּל אֶת הַחַמִּין כְּצוֹנְנִין טְמֵאִין וְאִם לָאו טְהוֹרִין:","הַכּוֹסוֹת הַחֲתוּכִין אַף עַל פִּי שֶׁשִּׂפְתוֹתֵיהֶם סוֹרְכִין אֶת הַפֶּה מְקַבְּלִים טֻמְאָה:","הָאֲפַרְכֵּס שֶׁל זְכוּכִית טָהוֹר שֶׁהֲרֵי הוּא כְּמוֹ מַחַץ שֶׁאֵינוֹ מְקַבֵּל:","זְכוּכִית שֶׁעוֹשִׂין אוֹתָהּ לְמַרְאָה טְהוֹרָה אַף עַל פִּי שֶׁהִיא מְקַבֶּלֶת לְפִי שֶׁלֹּא נַעֲשֵׂית לְקַבָּלָה. הַתַּרְוָד שֶׁל זְכוּכִית שֶׁהוּא מְקַבֵּל אַף עַל פִּי שֶׁכְּשֶׁמַּנִּיחוֹ עַל הַשֻּׁלְחָן נֶהְפָּךְ עַל צִדּוֹ וְאֵינוֹ מְקַבֵּל הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","תַּמְחוּי שֶׁל זְכוּכִית שֶׁעֲשָׂאוֹ מַרְאָה מְקַבֵּל טֻמְאָה. וְאִם מִתְּחִלָּה עֲשָׂאוּהוּ לְמַרְאָה כְּדֵי שֶׁיִּהְיוּ דְּבָרִים שֶׁמַּנִּיחִין בּוֹ נִרְאִין מֵאֲחוֹרָיו הֲרֵי זֶה טָהוֹר. וְכָל כְּלֵי זְכוּכִית אֵין מְקַבְּלִין טֻמְאָה עַד שֶׁתִּגָּמֵר מְלַאכְתָּן כְּכָל הַכֵּלִים:"],"Mishneh Torah, Vessels 23":["הַמַּפָּץ הוּא הַמַּחְצֶלֶת שֶׁאוֹרְגִין אוֹתָהּ מִן הַחֲבָלִים וּמִן הַסּוּף וּמִן הַגֹּמֶא וְכַיּוֹצֵא בָּהֶן. וְאֵין הַמַּפָּץ בִּכְלַל כֵּלִים הָאֲמוּרִין בַּתּוֹרָה וְאַף עַל פִּי כֵן מִתְטַמֵּא הוּא בְּמִדְרָס דִּין תּוֹרָה שֶׁהֲרֵי רִבָּה הַכָּתוּב (ויקרא טו ד) \"כָּל הַמִּשְׁכָּב\" וְזֶה רָאוּי לְמִשְׁכָּב וְעָשׂוּי לוֹ. וְכֵן מִתְטַמֵּא בְּמֵת וּבִשְׁאָר טֻמְאוֹת מִדִּבְרֵיהֶן כְּכָל פְּשׁוּטֵי כְּלֵי עֵץ כְּמוֹ שֶׁבֵּאַרְנוּ. וְזֶה כְּלָל גָּדוֹל שֶׁכָּל הַמִּתְטַמֵּא בְּמִדְרָס מִתְטַמֵּא בִּשְׁאָר טֻמְאוֹת:","כְּבָר בֵּאַרְנוּ שֶׁהַבֶּגֶד מִתְטַמֵּא בְּשָׁלֹשׁ עַל שָׁלֹשׁ כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁאָר טֻמְאוֹת. וּבִשְׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים לְמִדְרָס:","הַשַּׂק שִׁעוּרוֹ אַרְבָּעָה טְפָחִים עַל אַרְבָּעָה טְפָחִים. הָעוֹר חֲמִשָּׁה עַל חֲמִשָּׁה. הַמַּפָּץ שִׁשָּׁה עַל שִׁשָּׁה בֵּין לְמִדְרָס בֵּין לִשְׁאָר הַטֻּמְאוֹת. וּפָחוֹת מִן הַשִּׁעוּרִין הָאֵלּוּ טְהוֹרִין מִכְּלוּם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקֶרַע אֶחָד מֵהֶן שֶׁנִּקְרַע בְּלֹא כַּוָּנָה. אֲבָל הַקּוֹצֵץ בְּכַוָּנָה וְקִצֵּץ אֲפִלּוּ טֶפַח עַל טֶפַח לְמוֹשָׁב אוֹ שְׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים לְמִשְׁכָּב הֲרֵי זֶה מִתְטַמֵּא בְּמִדְרָס. בֵּין שֶׁהָיָה הַטֶּפַח עַל טֶפַח שֶׁקִּצֵּץ אוֹ הַשְּׁלֹשָׁה בֶּגֶד אוֹ שַׂק אוֹ עוֹר אוֹ מַפָּץ. וְכֵן הַמְקַצֵּעַ מֵאֶחָד מֵהֶן לַאֲחִיזָה כְּדֵי שֶׁיֹּאחַז בּוֹ בְּיָדוֹ כְּדֶרֶךְ שֶׁעוֹשִׂין קוֹצְצֵי תְּאֵנִים שֶׁלֹּא יִזּוֹקוּ אֶצְבְּעוֹתֵיהֶן הֲרֵי זֶה טָמֵא בְּכָל שֶׁהוּא. וְהוּא שֶׁלֹּא יִהְיֶה פָּחוֹת מִשָּׁלֹשׁ עַל שָׁלֹשׁ שֶׁכָּל פָּחוֹת מִשָּׁלֹשׁ אֶצְבָּעוֹת טָהוֹר מִכְּלוּם:","הַמְחַבֵּר שְׁנֵי טְפָחִים מִן הַבֶּגֶד וּמִן הַשַּׂק טֶפַח שְׁלֹשָׁה מִן הַשַּׂק וְאֶחָד מִן הָעוֹר אַרְבָּעָה מִן הָעוֹר וְאֶחָד מִן הַמַּפָּץ הֲרֵי זֶה טָהוֹר מִן הַמִּדְרָס. אֲבָל אִם חִבֵּר חֲמִשָּׁה טְפָחִים מִן הַמַּפָּץ וְאֶחָד מִן הָעוֹר אַרְבָּעָה מִן הָעוֹר וְאֶחָד מִן הַשַּׂק שְׁלֹשָׁה מִן הַשַּׂק וְאֶחָד מִן הַבֶּגֶד הֲרֵי זֶה טְמֵא מִדְרָס זֶה הַכְּלָל כָּל שֶׁהִשְׁלִים שִׁעוּרוֹ בְּחָמוּר מִמֶּנּוּ טָמֵא מִן הַקַּל טָהוֹר:","בְּלוֹיֵי נָפָה וּכְבָרָה שֶׁהִתְקִינָן לִישִׁיבָה טְהוֹרִין וְאֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיְּקַצְּצֵם וְאַחַר כָּךְ יִהְיוּ כְּמַפָּץ:","חָלוּק שֶׁל קָטָן אֵינוֹ מִתְטַמֵּא בְּמִדְרָס עַד שֶׁיִּהְיֶה בּוֹ כְּשִׁעוּר שְׁלֹשָׁה טְפָחִים עַל שְׁלֹשָׁה טְפָחִים וְנִמְדָּד כָּפוּל כִּבְרִיָּתוֹ. וְאֵלּוּ נִמְדָּדִין כְּפוּלִין בְּגָדִים שֶׁמַּלְבִּישִׁין אוֹתָן עַל הָרַגְלַיִם וְעַל הַשּׁוֹקַיִם וְאֶת הָרֹאשׁ וְהַמִּכְנָסַיִם וְהַכּוֹבַע וְהַכִּיס שֶׁל פֻּנְדָּא וּמַטְלִית שֶׁתְּלָאָהּ עַל הַשָּׂפָה אִם פְּשׁוּטָה נִמְדֶּדֶת פְּשׁוּטָה וְאִם כְּפוּלָה נִמְדֶּדֶת כְּפוּלָה:","הַבֶּגֶד שֶׁאָרַג שְׁלֹשָׁה עַל שְׁלֹשָׁה נִטְמָא בְּמִדְרָס וְאַחַר כָּךְ הִשְׁלִים אֶת כָּל הַבֶּגֶד כֻּלּוֹ מִדְרָס. נָטַל חוּט אֶחָד מִתְּחִלָּתוֹ טָהַר מִן הַמִּדְרָס אֲבָל טָמֵא מַגַּע מִדְרָס וַהֲרֵי הוּא רִאשׁוֹן כִּכְלִי שֶׁנָּגַע בְּמִדְרָס. נָטַל חוּט אֶחָד מִתְּחִלָּתוֹ וְאַחַר כָּךְ הִשְׁלִים אֶת כָּל הַבֶּגֶד כָּל הַבֶּגֶד טָמֵא מַגַּע מִדְרָס. וְכֵן בֶּגֶד שֶׁנֶּאֱרַג בּוֹ שָׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת וְנִטְמָא בְּמֵת וְאַחַר כָּךְ הִשְׁלִים עָלָיו אֶת כָּל הַבֶּגֶד הַבֶּגֶד כֻּלּוֹ טְמֵא מֵת. נָטַל חוּט אֶחָד מִתְּחִלָּתוֹ טָהַר מִטְּמֵא מֵת. אֲבָל טְמֵא מַגָּע טְמֵא מֵת. נָטַל חוּט אֶחָד מִתְּחִלָּתוֹ וְאַחַר כָּךְ הִשְׁלִים אֶת כָּל הַבֶּגֶד הַכּל טָהוֹר. וְלָמָּה יִהְיֶה הַכּל טָהוֹר מִפְּנֵי שֶׁאָמְרוּ שָׁלֹשׁ עַל שָׁלֹשׁ שֶׁנִּתְמַעֲטָה טְהוֹרָה מִכְּלוּם אֲבָל שְׁלֹשָׁה עַל שְׁלֹשָׁה שֶׁנִּתְמַעֲטָה אַף עַל פִּי שֶׁטָּהֲרָה מִן הַמִּדְרָס הֲרֵי הִיא טְמֵאָה בְּכָל הַטֻּמְאוֹת:","מַטְלִית שֶׁהִיא מִדְרָס וּטְלָאָהּ עַל הַקֻּפָּה אוֹ עַל הָעוֹר נַעֲשָׂה הַכּל רִאשׁוֹן לְטֻמְאָה. הִפְרִישׁ אֶת הַמַּטְלִית הֲרֵי הַקֻּפָּה אוֹ הָעוֹר רִאשׁוֹן מִפְּנֵי שֶׁנָּגְעוּ בַּמִּדְרָס וְהַמַּטְלִית טְהוֹרָה שֶׁכֵּיוָן שֶׁטְּלָאָהּ וְהִפְרִישָׁהּ בָּטְלָה. טְלָאָהּ עַל הַבֶּגֶד אוֹ עַל הַשַּׂק נַעֲשָׂה הַכּל מִדְרָס וַהֲרֵי הַכּל אַב טֻמְאָה. הִפְרִישָׁהּ הֲרֵי הַבֶּגֶד אוֹ הַשַּׂק רִאשׁוֹן שֶׁהֲרֵי נָגַע בַּמִּדְרָס וְהַמַּטְלִית אַב טֻמְאָה כְּשֶׁהָיְתָה שֶׁאֵינָהּ בְּטֵלָה עַל הָאָרִיג. תָּפַר הַמַּטְלִית עַל הַבֶּגֶד כְּשֶׁטְּלָאָהּ מֵרוּחַ אַחַת אוֹ מִשְּׁתֵי רוּחוֹת כְּמִין גַּאם אֵינוֹ חִבּוּר וְלֹא נַעֲשָׂה הַכּל אָב אֶלָּא מַגַּע מִדְרָס בִּלְבַד. תְּפָרָהּ מִשְּׁתֵי רוּחוֹת זוֹ בְּצַד זוֹ הֲרֵי הִיא חִבּוּר וְנַעֲשָׂה הַכּל אָב:","שְׁלֹשָׁה עַל שְׁלֹשָׁה שֶׁנִּטְמָא בְּמִדְרָס וְאַחַר כָּךְ נֶחְלַק טָהַר מִן הַמִּדְרָס וְאֵין בִּקְרָעִים אֵלּוּ טֻמְאָה כְּלָל וְהִנָּם כְּשִׁבְרֵי כְּלִי שֶׁנִּטְמָא. אֲבָל בֶּגֶד שֶׁנִּטְמָא בְּמִדְרָס וְקָרַע מִמֶּנּוּ שָׁלֹשׁ אֶצְבָּעוֹת עַל שָׁלֹשׁ אֶצְבָּעוֹת אוֹתוֹ הַקֶּרַע טָהַר מִן הַמִּדְרָס אֲבָל טְמֵא מַגַּע מִדְרָס שֶׁבְּעֵת פְּרִישָׁתוֹ מִן הַבֶּגֶד הַגָּדוֹל נִטְמָא בְּמַגָּע:","סָדִין שֶׁנִּטְמָא בְּמִדְרָס וְאַחַר כָּךְ עֲשָׂאָהוּ פָּרֹכֶת טָהַר מִן הַמִּדְרָס. וּמֵאֵימָתַי הוּא טָהֳרָתוֹ מִן הַמִּדְרָס מִשֶּׁיִּקְשֹׁר בּוֹ הַלּוּלָאוֹת שֶׁהוּא נִתְלֶה בָּהֶן כִּשְׁאָר הַפָּרוֹכוֹת:","טַלִּית שֶׁהִיא מִדְרָס וְהִטְבִּילָהּ וְקֹדֶם שֶׁיַּעֲרִיב שִׁמְשָׁהּ הִתְחִיל לִקְרֹעַ מִמֶּנָּה קֶרַע כֵּיוָן שֶׁנִּקְרַע בָּהּ רֻבָּהּ שׁוּב אֵינָהּ חִבּוּר וְטָהֲרָה כֻּלָּהּ אַף עַל פִּי שֶׁעֲדַיִן נִשְׁתַּיֵּר בָּהּ כְּדֵי מַעֲפֹרֶת שֶׁלֹּא נִקְרַע שֶׁהֲרֵי הוּא קוֹרֵעַ וְהוֹלֵךְ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּטְבוּלַת יוֹם שֶׁכֵּיוָן שֶׁלֹּא חָס עָלֶיהָ לְהַטְבִּילָהּ כָּךְ לֹא יָחוּס לִקְרֹעַ אֶת כֻּלָּהּ וּלְפִיכָךְ טָהֲרָה כֻּלָּהּ:"],"Mishneh Torah, Vessels 9":["כָּל כְּלֵי מַתָּכוֹת שֶׁיֵּשׁ לָהֶן שֵׁם בִּפְנֵי עַצְמָן מְקַבְּלִין טֻמְאָה חוּץ מִן הַדֶּלֶת וְהַנֶּגֶר וְהַמַּנְעוּל וְהַפּוֹתָת שֶׁתַּחַת הַצִּיר וְהַצִּיר וְהַקּוֹרָה וְהַצִּנּוֹר מִפְּנֵי שֶׁאֵלּוּ עֲשׂוּיִין לְקַרְקַע אוֹ לְשַׁמֵּשׁ אֶת הָעֵץ אֵינָן מְקַבְּלִין טֻמְאָה וַאֲפִלּוּ קֹדֶם שֶׁיִּקָּבְעוּ. וְכָל כְּלִי מַתָּכוֹת שֶׁיֵּשׁ לוֹ שֵׁם לְוַוי אֵינוֹ מִתְטַמֵּא בִּפְנֵי עַצְמוֹ מִפְּנֵי שֶׁהוּא כְּמִקְצָת כְּלִי. כֵּיצַד. עַקְרָב שֶׁל פְּרוּמְבְּיָא טָמֵא וּלְחָיַיִם שֶׁלָּהּ שֶׁעַל לְחָיֵי הַבְּהֵמָה מִכָּאן וּמִכָּאן טְהוֹרִין. וְאֵין מְקַבְּלִין טֻמְאָה בִּפְנֵי עַצְמָן מִפְּנֵי שֶׁאֵין לָהֶם שֵׁם בִּפְנֵי עַצְמָן. וּבִשְׁעַת חִבּוּרָן הַכּל מְקַבֵּל טֻמְאָה:","טַסִּין שֶׁל בַּרְזֶל שֶׁמַּנִּיחִין עַל לְחָיֵי הָאָדָם בִּשְׁעַת מִלְחָמָה אֵינָן מְקַבְּלִין טֻמְאָה מִפְּנֵי שֶׁאֵין לָהֶם שֵׁם בִּפְנֵי עַצְמָן. וְאִם יֵשׁ בָּהֶן בֵּית קִבּוּל מַיִם מִתְטַמְּאִין כְּכָל כְּלִי קִבּוּל:","נֶזֶם הֶעָשׂוּי כִּקְדֵרָה מִלְּמַטָּה וְכַעֲדָשָׁה מִלְּמַעְלָה וְנִפְסַק הַקְּדֵרָה שֶׁלּוֹ מְקַבֶּלֶת טֻמְאָה בִּפְנֵי עַצְמָהּ שֶׁהֲרֵי יֵשׁ לָהּ בֵּית קִבּוּל וְהָעֲדָשָׁה מְקַבֶּלֶת טֻמְאָה בִּפְנֵי עַצְמָהּ מִפְּנֵי שֶׁיֵּשׁ לָהּ שֵׁם בִּפְנֵי עַצְמָהּ. וְהַצְּנִירָה שֶׁלָּהּ שֶׁהִיא נִכְנֶסֶת בָּאֹזֶן אוֹ בָּאַף אֵינָהּ מְקַבֶּלֶת טֻמְאָה בִּפְנֵי עַצְמָהּ. הָיָה הַנֶּזֶם עָשׂוּי כְּמִין אֶשְׁכּוֹל וְנִפְרַק טָהוֹר מִפְּנֵי שֶׁאֵין בּוֹ בֵּית קִבּוּל וְאֵין לְכָל גַּרְגִּיר מִמֶּנּוּ שֵׁם בִּפְנֵי עַצְמוֹ וַהֲרֵי אֵינוֹ רָאוּי לְתַכְשִׁיט מִשֶּׁנִּפְרַק:","טַבַּעַת אַחַת שֶׁמַּנִּיחִין הַבָּנוֹת בְּרֶגֶל אַחַת הִיא הַנִּקְרֵאת בִּירִית וְאֵינָהּ מְקַבֶּלֶת טֻמְאָה מִפְּנֵי שֶׁאֵין עָלֶיהָ צוּרַת כְּלִי תַּכְשִׁיט אֶלָּא כְּמוֹ טַבַּעַת הַכֵּלִים אוֹ טַבַּעַת שֶׁקּוֹשֵׁר בָּהּ בֵּין כְּתֵפָיו. אֲבָל שְׁתֵּי טַבָּעוֹת שֶׁמְּשִׂימוֹת הַבָּנוֹת בְּרַגְלֵיהֶן וְשַׁלְשֶׁלֶת מֻטֶּלֶת בֵּינֵיהֶן מִזּוֹ לְזוֹ מְקַבְּלִין טֻמְאָה מִפְּנֵי שֶׁהֵן תַּכְשִׁיטֵי הַבָּנוֹת וְהֵן הַנִּקְרָאִין כְּבָלִים:","קַטְלָא שֶׁל חֻלְיוֹת שֶׁל מַתֶּכֶת וְהֵם בְּחוּט שֶׁל צֶמֶר אוֹ שֶׁל פִּשְׁתָּן וְנִפְסַק הַחוּט. הַחֻלְיוֹת מְקַבְּלוֹת טֻמְאָה שֶׁכָּל אֶחָד וְאֶחָד כְּלִי בִּפְנֵי עַצְמוֹ. הָיָה הַחוּט שֶׁלָּהּ שֶׁל מַתֶּכֶת וְהַחֻלְיוֹת שֶׁל אֲבָנִים טוֹבוֹת וְשֶׁל מַרְגָּלִיּוֹת אוֹ שֶׁל זְכוּכִית וְנִשְׁבְּרוּ הַחֻלְיוֹת וְהַחוּט קַיָּם הֲרֵי זֶה מִתְטַמֵּא בִּפְנֵי עַצְמוֹ. שְׁיָרֵי קַטְלָא כִּמְלֹא צַוַּאר קְטַנָּה:","כָּל הַכִּסּוּיִין שֶׁל מַתֶּכֶת טְהוֹרִין וְאֵין מְקַבְּלִין טֻמְאָה מִפְּנֵי שֶׁאֵין לָהֶם שֵׁם בִּפְנֵי עַצְמָן. חוּץ מִכִּסּוּי הַמֵּחַם וּמִכִּסּוּי טֶנִי שֶׁל רוֹפְאִין מִפְּנֵי שֶׁמַּנִּיחִין בּוֹ אֶת הָאִסְפְּלָנִית נַעֲשֶׂה כְּלִי קִבּוּל:","כִּסּוּי שֶׁל מַתֶּכֶת שֶׁשָּׁפוֹ וְלִטְּשׁוֹ וְעָשָׂהוּ מַרְאָה הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","כָּל הַמִּשְׁקוֹלוֹת שֶׁל מַתָּכוֹת מְקַבְּלוֹת טֻמְאָה וְהֵן הַנִּקְרָאִין אוֹנְקִיאוֹת. קְנֵה מֹאזְנַיִם שֶׁל עֵץ שֶׁהָיוּ אוֹנְקִיּוֹת שֶׁל בַּרְזֶל תְּלוּיוֹת בּוֹ מְקַבֶּלֶת טֻמְאָה מִפְּנֵי הָאוֹנְקִיּוֹת הַתְּלוּיוֹת בּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמֹאזְנַיִם שֶׁל מוֹכְרֵי פִּשְׁתָּן וּמוֹכְרֵי צֶמֶר. אֲבָל שֶׁל בַּעֲלֵי בָּתִּים אֵינוֹ מְקַבֵּל טֻמְאָה עַד שֶׁיִּהְיוּ הָאוֹנְקִיּוֹת קְבוּעוֹת בּוֹ:","מִשְׁקָלוֹת שֶׁנִּשְׁתַּבְּרוּ אַף עַל פִּי שֶׁהֶחְזִירָן וְשׁוֹקֵל בָּהֶן אֵינָן מְקַבְּלִין טֻמְאָה. יִחֵד מֵהֶן חֲצָאֵי לִיטְרִין שְׁלִישֵׁי לִיטְרִין רְבִיעֵי לִיטְרִין הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה:","סֶלַע שֶׁנִּפְסְלָה וְהִתְקִינָהּ לִהְיוֹת שׁוֹקֵל בָּהּ מְקַבֶּלֶת טֻמְאָה:","אֻנְקְלִי שֶׁל כַּתָּפִים טְהוֹרָה וְשֶׁל רוֹכְלִים מִתְטַמְּאָה. אֻנְקְלִי שֶׁל נַקְלִיטֵי הַמִּטָּה טְהוֹרָה וְשֶׁל דַּרְגִּישׁ מִתְטַמְּאָה. אֻנְקְלִי שֶׁל כַּוֶּרֶת הַצַּיָּדִים שֶׁצָּדִין בָּהֶן הַדָּגִים טָהוֹר וְשֶׁל שִׁדָּה מִתְטַמְּאָה. אֻנְקְלִי שֶׁל מְנוֹרוֹת הָעֵץ טָהוֹר וְשֶׁל שֻׁלְחָן מִתְטַמְּאָה. זֶה הַכְּלָל כָּל כְּלִי שֶׁמְּקַבֵּל טֻמְאָה בִּפְנֵי עַצְמוֹ מִן הַתּוֹרָה הֲרֵי הָאֻנְקְלִי שֶׁל מַתֶּכֶת שֶׁלּוֹ וְשַׁלְשֶׁלֶת שֶׁלּוֹ מְקַבֶּלֶת טֻמְאָה. וּכְלִי שֶׁאֵינוֹ מְקַבֵּל טֻמְאָה כְּגוֹן פְּשׁוּטֵי כְּלֵי עֵץ וּכְלֵי עֵץ הַבָּאִים בְּמִדָּה וְכַיּוֹצֵא בָּהֶן אֻנְקְלִי שֶׁל מַתֶּכֶת וְהַשַּׁלְשֶׁלֶת שֶׁלּוֹ אֵינָן מְקַבְּלִין טֻמְאָה וְכָל אַחַת וְאַחַת בִּפְנֵי עַצְמָהּ טְהוֹרָה שֶׁאֵין הָאֻנְקְלִי אוֹ הַשַּׁלְשֶׁלֶת כְּלִי בִּפְנֵי עַצְמוֹ אֶלָּא הֲרֵי הֵן כְּמִקְצָת כְּלִי. וַאֲפִלּוּ אֻנְקְלִי שֶׁבַּכְּתָלִים שֶׁתּוֹלִין בָּהּ הַכֵּלִים וְהַבְּגָדִים וְכַיּוֹצֵא בָּהֶן טְהוֹרָה:","שַׁלְשֶׁלֶת שֶׁיֵּשׁ בָּהּ בֵּית נְעִילָה מִתְטַמְּאָה וְהָעֲשׂוּיָה לִכְפִיתָה טְהוֹרָה:","שַׁלְשֶׁלֶת שֶׁל סִיטוֹנוֹת מִתְטַמְּאָה מִפְּנֵי שֶׁהֵן נוֹעֲלִין בָּהּ אֶת הַחֲנֻיּוֹת. וְשֶׁל בַּעֲלֵי בָּתִּים טְהוֹרָה שֶׁאֵינָהּ עֲשׂוּיָה אֶלָּא לְנוֹי:","שַׁלְשֶׁלֶת שֶׁל מוֹשְׁחֵי קַרְקַע וִיתֵדוֹתֵיהֶן שֶׁתּוֹקְעִין בַּקַּרְקַע בְּשָׁעָה שֶׁמּוֹשְׁחִין מְקַבְּלִין טֻמְאָה. וְשֶׁל מְקוֹשְׁשֵׁי עֵצִים טְהוֹרָה לְפִי שֶׁהִיא מְשַׁמֶּשֶׁת אֶת הָעֵץ:","שַׁלְשֶׁלֶת דְּלִי גָּדוֹל אַרְבָּעָה טְפָחִים מִמֶּנָּה סָמוּךְ לַדְּלִי מִתְטַמְּאָה עִם הַדְּלִי מִפְּנֵי שֶׁהִיא צֹרֶךְ הַדְּלִי וְהַשְּׁאָר טָהוֹר לְפִי שֶׁאֵין לוֹ שֵׁם בִּפְנֵי עַצְמוֹ. וְשַׁלְשֶׁלֶת דְּלִי קָטָן עֲשָׂרָה טְפָחִים:","הַכַּדּוּר שֶׁל מַתֶּכֶת וְהַסַּדָּן. וְהַקַּנְטָר שֶׁל בַּנַּאי. וְהַדַּקָּר שֶׁל חָרָשׁ. וַחֲמוֹר שֶׁל נַפָּח. וְהַמְטֻלְטֶּלֶת. וְהַמִּשְׁקוֹלוֹת שֶׁל בַּנָּאִים. וְהַכִּירַיִם שֶׁל בַּרְזֶל שֶׁחוֹבְטִין בָּהֶם הַזֵּיתִים. וְהָאֲפַרְכֵּס שֶׁל מַתֶּכֶת. וְהָאוֹלָר שֶׁכּוֹרְתִין בּוֹ הַסּוֹפְרִים רֹאשׁ הַקֻּלְמוֹס שֶׁל קָנֶה. וְהַקֻּלְמוֹס שֶׁל מַתֶּכֶת. וְהַכַּן. וְהַכַּנָא שֶׁמְּשַׂרְטְטִין בּוֹ הַסּוֹפְרִים. כָּל אֵלּוּ מְקַבְּלִין טֻמְאָה שֶׁכָּל אֶחָד מֵהֶן יֵשׁ לוֹ שֵׁם בִּפְנֵי עַצְמוֹ:"],"Mishneh Torah, Virgin Maiden 2":["חֲמִשִׁים כֶּסֶף שֶׁל קְנָס הֵם דְּמֵי הֲנָאַת שְׁכִיבָה בִּלְבַד. וְחַיָּב הַמְפַתֶּה לִתֵּן בּשֶׁת וּפְגָם יוֹתֵר עַל הַקְּנָס הַקָּצוּב בַּתּוֹרָה. יֶתֶר עָלָיו הָאוֹנֵס שֶׁהוּא נוֹתֵן אֶת הַצַּעַר. שֶׁהַנִּבְעֶלֶת בִּרְצוֹנָהּ אֵין לָהּ צַעַר וַאֲנוּסָה יֵשׁ לָהּ צַעַר. וְכֵן הוּא אוֹמֵר בַּאֲנוּסָה (דברים כב כט) \"תַּחַת אֲשֶׁר עִנָּהּ\":","נִמְצָא הַמְפַתֶּה מְשַׁלֵּם שְׁלֹשָׁה דְּבָרִים קְנָס וּבֹשֶׁת וּפְגָם. וְהָאוֹנֵס אַרְבָּעָה קְנָס וּבֹשֶׁת וְצַעַר וּפְגָם:","קְנָס שָׁוֶה בַּכּל. אֶחָד הַבָּא עַל בַּת כֹּהֵן גָּדוֹל וְאֶחָד הַבָּא עַל בַּת גֵּר אוֹ מַמְזֵר קְנָסָהּ חֲמִשִּׁים כֶּסֶף. אֲבָל הַבּשֶׁת וְהַפְּגָם וְהַצַּעַר אֵינָן שָׁוִין לַכּל וּצְרִיכִין שׁוּמָא:","כֵּיצַד שָׁמִין הַבּשֶׁת. הַכּל לְפִי הַמְבַיֵּשׁ וְהַמִּתְבַּיֵּשׁ. שֶׁאֵינוֹ דּוֹמֶה מְבַיֵּשׁ נַעֲרָה חֲשׁוּבָה וּמִמִּשְׁפָּחָה מְיֻחָסָה לִמְבַיֵּשׁ קְטַנָּה עֲנִיָּה בְּזוּיָה. וְאֵינוֹ דּוֹמֶה מִתְבַּיֵּשׁ מֵאָדָם חָשׁוּב וְגָדוֹל לְמִתְבַּיֵּשׁ מֵאֶחָד מֵהַנְּבָלִים וְקַל מִן הַקַּלִּים:","וּלְפִי זֶה רוֹאִין הַדַּיָּנִין מַעֲלָתוֹ וּמַעֲלָתָהּ וְשָׁמִין כַּמָּה מָמוֹן רָאוּי לְאָבִיהָ וּלְמִשְׁפַּחְתָּהּ לִתֵּן וְלֹא יֶאֱרַע לָהֶן דָּבָר זֶה מֵאָדָם זֶה וְכָמוֹהוּ חַיָּב לְשַׁלֵּם:","פְּגָם לְפִי יָפְיָהּ. רוֹאִין אוֹתָהּ כְּאִלּוּ הִיא שִׁפְחָה נִמְכֶּרֶת בַּשּׁוּק כַּמָּה הִיא שָׁוָה בְּעוּלָה וְכַמָּה הָיְתָה שָׁוָה בְּתוּלָה. שֶׁאָדָם רוֹצֶה לִקְנוֹת שִׁפְחָה בְּתוּלָה לִתְּנָהּ לְעַבְדּוֹ שֶׁהוּא רוֹצֶה בַּהֲנָיָתוֹ וְטוֹבָתוֹ. וְרוֹאִין כַּמָּה פָּחֲתָה וִישַׁלֵּם צַעַר לְפִי קַטְנוּתָהּ וּבִנְיַן גּוּפָהּ. וּלְפִי שָׁנָיו וְגוּפוֹ אוֹמְדִין כַּמָּה הָאָב רוֹצֶה לִתֵּן וְלֹא תִּצְטַעֵר זוֹ מִזֶּה וְיִתֵּן:","הַמְפַתֶּה נוֹתֵן בּשֶׁת וּפְגָם מִיָּד וְאֵינוֹ נוֹתֵן הַקְּנָס אֶלָּא אִם כֵּן לֹא נְשָׂאָהּ שֶׁנֶּאֱמַר (שמות כב טז) \"וְאִם מָאֵן יְמָאֵן אָבִיהָ לְתִתָּהּ לוֹ כֶּסֶף יִשְׁקל\". אֲבָל הָאוֹנֵס נוֹתֵן אַרְבָּעָה דְּבָרִים מִיָּד וְכוֹנֵס. לְפִיכָךְ כְּשֶׁתִּרְצֶה לְהִתְגָּרֵשׁ אוֹ תִּתְאַלְמֵן אֵין לָהּ כְּלוּם:","בָּאוּ עָלֶיהָ שְׁנַיִם אֶחָד כְּדַרְכָּהּ וְאֶחָד שֶׁלֹּא כְּדַרְכָּהּ זֶה שֶׁבָּא עָלֶיהָ שֶׁלֹּא כְּדַרְכָּהּ אִם הוּא רִאשׁוֹן חַיָּב בְּבשֶׁת וּפְגָם וְאִם הוּא אַחֲרוֹן חַיָּב בְּבשֶׁת בִּלְבַד שֶׁכְּבָר נִפְגְּמָה. וְזֶה שֶׁבָּא עָלֶיהָ כְּדַרְכָּהּ בֵּין רִאשׁוֹן בֵּין אַחֲרוֹן חַיָּב בִּקְנָס וּבִשְׁאָר הַדְּבָרִים. אֲבָל אֵין בּשֶׁת וּפְגָם שֶׁל בַּת שֶׁלֹּא נִבְעֲלָה כְּלָל כְּבשֶׁת וּפְגָם זוֹ שֶׁנִּבְעֲלָה שֶׁלֹּא כְּדַרְכָּהּ:","כְּבָר הוֹדַעְנוּ הַבָּנוֹת שֶׁאֵין לָהֶן קְנָס וְעֶשֶׂר הֵן. הַבּוֹגֶרֶת. וְהַמְמָאֶנֶת. וְהַמְגֹרֶשֶׁת. וְהָאַיְלוֹנִית. וְהַשּׁוֹטָה. וְהַחֵרֶשֶׁת. וְהַגִּיֹּרֶת. וְהַשְּׁבוּיָה. וְהַמְשֻׁחְרֶרֶת. וְהַיּוֹצֵא עָלֶיהָ שֵׁם רַע. וּשְׁאָר הַבָּנוֹת יֵשׁ לָהֶן קְנָס:","כָּל בַּת שֶׁיֵּשׁ לָהּ קְנָס יֵשׁ לָהּ בּשֶׁת וּפְגָם. וְאִם הָיְתָה אֲנוּסָה יֵשׁ לָהּ צַעַר. וְכָל בַּת שֶׁאֵין לָהּ קְנָס כָּךְ אֵין לָהּ לֹא בּשֶׁת וְלֹא פְּגָם אִם נִתְפַּתְּתָה וְכֵן אִם נֶאֶנְסָה חוּץ מִבּוֹגֶרֶת וּמְמָאֶנֶת וְשׁוֹטָה וְחֵרֶשֶׁת:","כֵּיצַד. הָאוֹנֵס אֶת הַבּוֹגֶרֶת וְאֶת הַמְמָאֶנֶת אַף עַל פִּי שֶׁאֵין לָהֶן קְנָס יֵשׁ לָהֶן בּשֶׁת וּפְגָם וְצַעַר. וְהָאוֹנֵס שׁוֹטָה אוֹ חֵרֶשֶׁת מְשַׁלֵּם צַעַר בִּלְבַד. אֲבָל הַמְפַתֶּה אֶת כֻּלָּן פָּטוּר מִכְּלוּם:","אֵין אָדָם מְשַׁלֵּם קְנָס בְּכָל מָקוֹם בְּהוֹדָאַת פִּיו אֶלָּא עַל פִּי עֵדִים. לְפִיכָךְ הָאוֹמֵר אָנַסְתִּי אוֹ פִּתִּיתִי בִּתּוֹ שֶׁל פְּלוֹנִי אֵינוֹ מְשַׁלֵּם קְנָס אֲבָל מְשַׁלֵּם בּשֶׁת וּפְגָם בְּהוֹדָאַת פִּיו. וְכֵן בַּת שֶׁתָּבְעָה אִישׁ בַּדִּין וְאָמְרָה לוֹ אָנַסְתָּ אוֹ פִּתִּיתָ אוֹתִי וְהוּא אוֹמֵר לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁאִלּוּ הוֹדָה הָיָה מְשַׁלֵּם לָהּ בּשֶׁת וּפְגָם וְצַעַר עַל פִּי עַצְמוֹ:","אָמְרָה לוֹ אָנַסְתָּ אוֹתִי וְהוּא אוֹמֵר לֹא כִּי אֶלָּא פִּתִּיתִי הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַתּוֹרָה עַל דְּמֵי הַצַּעַר וּמְשַׁלֵּם בּשֶׁת וּפְגָם שֶׁהֲרֵי הוֹדָה בְּמִקְצָת הַטַּעֲנָה כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:","שְׁלֹשָׁה דְּבָרִים שֶׁל מְפַתֶּה וְאַרְבָּעָה שֶׁל אוֹנֵס הֲרֵי הֵן שֶׁל אָב שֶׁכָּל שֶׁבַח נְעוּרִים לוֹ. וְאִם אֵין לָהּ אָב הֲרֵי הֵן שֶׁל עַצְמָהּ:","מְפֻתָּה אוֹ אֲנוּסָה שֶׁלֹּא תָּבְעָה עַד שֶׁבָּגְרָה אוֹ עַד שֶׁנִּשֵּׂאת אוֹ עַד שֶׁמֵּת הָאָב הָאַרְבָּעָה דְּבָרִים אוֹ הַשְּׁלֹשָׁה שֶׁלָּהּ. עָמְדָה בַּדִּין וְתָבְעָה אוֹתוֹ וְאַחַר כָּךְ בָּגְרָה אוֹ שֶׁנִּשֵּׂאת הֲרֵי הֵן שֶׁל אָב. וְאִם מֵת הָאָב אַחַר עֲמִידָתָהּ בַּדִּין הֲרֵי הֵן שֶׁל אַחִין שֶׁהֵן יוֹרְשֵׁי הָאָב. שֶׁמֵּעֵת שֶׁעָמְדָה בְּדִין זָכָה בָּהֶן הָאָב:","הַבַּת שֶׁנִּתְאָרְסָה וְנִתְגָּרְשָׁה קְנָסָהּ לְבַדּוֹ לְעַצְמָהּ. נֶאֶנְסָה אוֹ נִתְפַּתְּתָה וְאַחַר כָּךְ נִתְקַדְּשָׁה לְאַחֵר קְנָסָהּ וּשְׁאָר הַדְּבָרִים לְאָבִיהָ. שֶׁאֵין הָאֵרוּסִין מוֹצִיאִין מֵרְשׁוּת אָב:","אֲנִי אוֹמֵר שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא יט כט) \"אַל תְּחַלֵּל אֶת בִּתְּךָ לְהַזְנוֹתָהּ\". שֶׁלֹּא יֹאמַר הָאָב הוֹאִיל וְלֹא חִיְּבָה תּוֹרָה מְפַתֶּה וְאוֹנֵס אֶלָּא שֶׁיִּתֵּן מָמוֹן לָאָב הֲרֵינִי שׂוֹכֵר בִּתִּי הַבְּתוּלָה לָזֶה לָבוֹא עָלֶיהָ בְּכָל מָמוֹן שֶׁאֶרְצֶה אוֹ אָנִיחַ זֶה לָבוֹא עָלֶיהָ בְּחִנָּם שֶׁיֵּשׁ לוֹ לָאָדָם לִמְחל מָמוֹנוֹ לְכָל מִי שֶׁיִּרְצֶה לְכָךְ נֶאֱמַר אַל תְּחַלֵּל אֶת בִּתְּךָ. שֶׁזֶּה שֶׁחִיְּבָה תּוֹרָה לָאוֹנֵס וְלַמְפַתֶּה מָמוֹן וְלֹא מַלְקוֹת בְּשֶׁאֵרַע הַדָּבָר מִקְרֶה שֶׁלֹּא מִדַּעַת אָבִיהָ וְלֹא הֵכִינָה עַצְמָהּ לְכָךְ שֶׁדָּבָר זֶה אֵינוֹ הוֹוֶה תָּמִיד וְאֵינוֹ מָצוּי. אֲבָל אִם הֵנִיחַ בִּתּוֹ הַבְּתוּלָה מוּכֶנֶת לְכָל מִי שֶׁיָּבוֹא עָלֶיהָ גּוֹרֵם שֶׁתִּמָּלֵא הָאָרֶץ זִמָּה וְנִמְצָא הָאָב נוֹשֵׂא בִּתּוֹ וְהָאָח נוֹשֵׂא אֲחוֹתוֹ שֶׁאִם תִּתְעַבֵּר וְתֵלֵד לֹא יִוָּדַע בֶּן מִי הוּא. וְהַמֵּכִין בִּתּוֹ לְכָךְ הֲרֵי הִיא קְדֵשָׁה וְלוֹקֶה הַבּוֹעֵל וְהַנִּבְעֶלֶת מִשּׁוּם (דברים כג יח) \"לֹא תִהְיֶה קְדֵשָׁה\". וְאֵין קוֹנְסִין אוֹתוֹ שֶׁלֹּא חִיְּבָה תּוֹרָה קְנָס אֶלָּא לְאוֹנֵס וּמְפַתֶּה אֲבָל זוֹ שֶׁהֵכִינָה עַצְמָהּ לְכָךְ בֵּין מִדַּעְתָּהּ בֵּין מִדַּעַת אָבִיהָ הֲרֵי זוֹ קְדֵשָׁה. וְאִסּוּר קְדֵשָׁה אֶחָד הוּא בֵּין בִּבְתוּלָה בֵּין בִּבְעוּלָה לְפִיכָךְ אָמְרוּ חֲכָמִים שֶׁהַיּוֹצֵא עָלֶיהָ שֵׁם רַע בְּיַלְדוּתָהּ אֵין לָהּ קְנָס כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁהֲרֵי זוֹ בְּחֶזְקַת שֶׁהִפְקִירָה עַצְמָהּ לְדָבָר זֶה בִּרְצוֹנָהּ:"],"Mishneh Torah, Vows 7":["שְׁנַּיִם שֶׁנֶּאֶסְרָה הֲנָאַת כָּל אֶחָד מֵהֶן עַל חֲבֵרוֹ בֵּין בְּנֵדֶר בֵּין בִּשְׁבוּעָה הֲרֵי אֵלּוּ מֻתָּרִין לְהַחְזִיר אֲבֵדָה זֶה לָזֶה מִפְּנֵי שֶׁהוּא מִצְוָה. וּבְמָקוֹם שֶׁדַּרְכָּן שֶׁנּוֹטֵל שָׂכָר הַמַּחֲזִיר אֶת הָאֲבֵדָה יִפּל הַשָּׂכָר לַהֶקְדֵּשׁ. שֶׁאִם יִטּל שָׂכָר נִמְצָא נֶהֱנֶה וְאִם לֹא יִטּוֹל נִמְצָא מְהַנֶּה:","וּמֻתָּרִין בִּדְבָרִים שֶׁהֵם בְּשֻׁתָּפוּת כָּל יִשְׂרָאֵל. כְּגוֹן הַר הַבַּיִת (וְהַלְּשָׁכוֹת) וְהָעֲזָרוֹת וְהַבְּאֵר שֶׁבְּאֶמְצַע הַדֶּרֶךְ. וַאֲסוּרִין בִּדְבָרִים שֶׁהֵם בְּשֻׁתָּפוּת כָּל אַנְשֵׁי הָעִיר כְּגוֹן הָרְחָבָה שֶׁבָּעִיר וְהַמֶּרְחָץ וּבֵית הַכְּנֶסֶת וְהַתֵּבָה וְהַסְּפָרִים:","וְכֵיצַד יַעֲשׂוּ כְּדֵי שֶׁיִּהְיוּ מֻתָּרִין בִּדְבָרִים אֵלּוּ. כָּל אֶחָד וְאֶחָד מִשְּׁנֵיהֶם כּוֹתֵב חֶלְקוֹ לַנָּשִׂיא אוֹ לְאֶחָד מִשְּׁאָר הָעָם וּמְזַכֶּה לוֹ בְּחֶלְקוֹ עַל יְדֵי אַחֵר. וְנִמְצָא כָּל אֶחָד מֵהֶם כְּשֶׁיִּכָּנֵס לַמֶּרְחָץ שֶׁהוּא לְכָל אַנְשֵׁי הָעִיר אוֹ לְבֵית הַכְּנֶסֶת אֵינוֹ נִכְנָס לִרְשׁוּת חֲבֵרוֹ אֶלָּא לִרְשׁוּת אֲחֵרִים שֶׁהֲרֵי כָּל אֶחָד מֵהֶם נִסְתַּלֵּק מֵחֶלְקוֹ שֶׁבְּמָקוֹם זֶה וּנְתָנוֹ בְּמַתָּנָה:","הָיוּ שְׁנֵיהֶם שֻׁתָּפִין בְּחָצֵר. אִם יֵשׁ בָּהּ דִּין חֲלוּקָה הֲרֵי אֵלּוּ אֲסוּרִין לְהִכָּנֵס לָהּ עַד שֶׁיַּחֲלֹקוּ וְיִכָּנֵס כָּל אֶחָד לְחֶלְקוֹ. וְאִם אֵין בָּהּ דִּין חֲלוּקָה כָּל אֶחָד וְאֶחָד נִכְנָס לְבֵיתוֹ וְהוּא אוֹמֵר בְּתוֹךְ שֶׁלִּי אֲנִי נִכְנָס. וּבֵין כָּךְ וּבֵין כָּךְ שְׁנֵיהֶם אֲסוּרִים לְהַעֲמִיד רֵחַיִם וְתַנּוּר וּלְגַדֵּל תַּרְנְגוֹלִין בְּחָצֵר זוֹ:","שְׁנַיִם שֶׁהָיוּ שֻׁתָּפִין בְּחָצֵר וְנָדַר אֶחָד מֵהֶן שֶׁלֹּא יְהַנֶּה בּוֹ הַשֵּׁנִי כּוֹפִין אֶת הַנּוֹדֵר לִמְכֹּר חֶלְקוֹ. נָדַר שֶׁלֹּא יֵהָנֶה הוּא בַּשֵּׁנִי הֲרֵי זֶה מֻתָּר לְהִכָּנֵס לְבֵיתוֹ מִפְּנֵי שֶׁבִּרְשׁוּתוֹ הוּא נִכְנָס. אֲבָל אֵינוֹ יָכוֹל לְהִשְׁתַּמֵּשׁ בַּחָצֵר כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיָה אֶחָד מִן הַשּׁוּק אָסוּר בַּהֲנָאַת אֶחָד מִשְּׁנֵיהֶם. הֲרֵי זֶה מֻתָּר לְהִכָּנֵס לֶחָצֵר. מִפְּנֵי שֶׁהוּא אוֹמֵר לוֹ לְתוֹךְ שֶׁל חֲבֵרְךָ אֲנִי נִכְנָס אֵינִי נִכְנָס לְתוֹךְ שֶׁלְּךָ:","מִי שֶׁאָסַר הֲנָיַת אֻמָּה מִן הָאֻמּוֹת עַל עַצְמוֹ. הֲרֵי זֶה מֻתָּר לִקַּח מֵהֶן בְּיוֹתֵר וְלִמְכֹּר לָהֶן בְּפָחוֹת. אָסַר הֲנָיָתוֹ עֲלֵיהֶם אִם שׁוֹמְעִין לוֹ שֶׁיִּקַּח מֵהֶן בְּפָחוֹת וְיִמְכֹּר בְּיוֹתֵר מֻתָּר. וְאֵין גּוֹזְרִין כָּאן שֶׁלֹּא יִמְכֹּר גְּזֵרָה שֶׁמָּא יִקַּח. שֶׁהֲרֵי לֹא נָדַר מֵאִישׁ אֶחָד כְּדֵי שֶׁנִּגְזֹר עָלָיו [אֶלָּא] מֵאֻמָּה כֻּלָּהּ. שֶׁאִם אִי אֶפְשָׁר לוֹ לִשָּׂא וְלִתֵּן עִם זֶה יִשָּׂא וְיִתֵּן עִם אַחֵר. לְפִיכָךְ אִם אָסַר הֲנָיָתָן עָלָיו הֲרֵי זֶה מַשְׁאִילָן וּמַלְוֶה אוֹתָן. אֲבָל לֹא יִשְׁאַל מֵהֶם וְלֹא יִלְוֶה מֵהֶן:","אָסַר הֲנָיָתוֹ עֲלֵיהֶן וַהֲנָיָתָן עָלָיו לֹא יִשָּׂא וְיִתֵּן עִמָּהֶם. וְכֵן לֹא יִשְּׂאוּ הֵן וְיִתְּנוּ עִמּוֹ וְלֹא יַשְׁאִיל לָהֶן וְלֹא יִלְוֶה מֵהֶם וְלֹא יַלְוֶה אוֹתָן:","אָסַר עַל עַצְמוֹ הֲנָיַת בְּנֵי הָעִיר אָסוּר לְהִשָּׁאֵל עַל נִדְרוֹ לְחָכָם מִבְּנֵי אוֹתָהּ הָעִיר (הַהִיא). וְאִם נִשְׁאַל וְהִתִּיר לוֹ הֲרֵי נִדְרוֹ מֻתָּר כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁאָסַר הֲנָיַת הַבְּרִיּוֹת עָלָיו הֲרֵי זֶה מֻתָּר לֵהָנוֹת בְּלֶקֶט שִׁכְחָה וּפֵאָה וּמַעֲשַׂר עָנִי הַמִּתְחַלֵּק בָּגֳרָנוֹת אֲבָל לֹא בְּתוֹךְ הַבַּיִת:","מִי שֶׁאָסַר הֲנָיָתוֹ עַל הַכֹּהֲנִים וְעַל הַלְוִיִּם הֲרֵי אֵלּוּ בָּאִין וְנוֹטְלִין מַתְּנוֹתֵיהֶם עַל כָּרְחוֹ. וְאִם אָמַר כֹּהֲנִים אֵלּוּ וּלְוִיִּם אֵלּוּ הֲרֵי אֵלּוּ אֲסוּרִין. וְיִתֵּן תְּרוּמוֹתָיו וּמַעַשְׂרוֹתָיו לְכֹהֲנִים וּלְוִיִּם אֲחֵרִים. וְהוּא הַדִּין בְּמַתְּנוֹת עֲנִיִּים עִם הָעֲנִיִּים:","מִי שֶׁהָיְתָה הֲנָיָתוֹ אֲסוּרָה עַל חֲבֵרוֹ וְאֵין לַחֲבֵרוֹ מַה יֹּאכַל. הוֹלֵךְ אֵצֶל הַחֶנְוָנִי וְאוֹמֵר אִישׁ פְּלוֹנִי אָסוּר בַּהֲנָיָתִי וְאֵינִי יוֹדֵעַ מָה אֶעֱשֶׂה. אִם הָלַךְ הַחֶנְוָנִי וְנָתַן לוֹ וּבָא וְנָטַל מִזֶּה הֲרֵי זֶה מֻתָּר:","הָיָה בֵּיתוֹ לִבְנוֹת גְּדֵרוֹ לִגְדֹּר שָׂדֵהוּ לִקְצֹר וְהָלַךְ אֵצֶל פּוֹעֲלִים וְאָמַר אִישׁ פְּלוֹנִי אָסוּר בַּהֲנָיָתִי וְאֵינִי יוֹדֵעַ מָה אֶעֱשֶׂה. וְהָלְכוּ הֵן וְעָשׂוּ עִמּוֹ וּבָאוּ לָזֶה וְנָתַן לָהֶן שְׂכָרָן הֲרֵי זֶה מֻתָּר. שֶּׁנִּמְצָא זֶה שֶׁפָּרַע לוֹ חוֹבוֹ. וּכְבָר בֵּאַרְנוּ שֶׁזֶּה מֻתָּר לִפְרֹעַ לוֹ חוֹבוֹ:","הָיוּ מְהַלְּכִין בַּדֶּרֶךְ וְאֵין לוֹ מַה יֹּאכַל. נוֹתֵן לְאַחֵר מִשּׁוּם מַתָּנָה וְהַלָּה מֻתָּר בָּהּ. וְאִם אֵין עִמָּהֶם אַחֵר מַנִּיחַ עַל הַסֶּלַע וְאוֹמֵר הֲרֵי הֵן מֻפְקָרִין לְכָל מִי שֶׁיַּחְפֹּץ וְהַלָּה נוֹטֵל וְאוֹכֵל:","נָתַן לְאֶחָד מַתָּנָה וְאָמַר לוֹ הֲרֵי סְעֻדָּה זוֹ נְתוּנָה לְךָ מַתָּנָה וְיָבוֹא פְּלוֹנִי שֶׁהוּא אָסוּר בַּהֲנָיָתִי וְיֹאכַל עִמָּנוּ הֲרֵי זֶה אָסוּר. וְלֹא עוֹד אֶלָּא [אֲפִלּוּ] אִם נָתַן לוֹ סְתָם וְחָזַר וְאָמַר לוֹ רְצוֹנְךָ שֶׁיָּבוֹא פְּלוֹנִי וְיֹאכַל עִמָּנוּ. אִם הוֹכִיחַ סוֹפוֹ עַל תְּחִלָּתוֹ שֶׁלֹּא נָתַן לוֹ אֶלָּא עַל מְנָת שֶׁיָּבוֹא פְּלוֹנִי וְיֹאכַל אָסוּר. כְּגוֹן שֶׁהָיְתָה סְעֻדָּה גְּדוֹלָה וְהוּא רוֹצֶה שֶׁיָּבוֹא אָבִיו אוֹ רַבּוֹ וְכַיּוֹצֵא בָּהֶן לֶאֱכל מִסְּעוּדָתוֹ. שֶׁהֲרֵי סְעוּדָתוֹ מוֹכַחַת עָלָיו שֶׁלֹּא גָּמַר לְהַקְנוֹת לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל מַתָּנָה שֶׁאִם הִקְדִּישָׁהּ לֹא תִּהְיֶה מֻקְדֶּשֶׁת אֵינָהּ מַתָּנָה. וְכָל הַנּוֹתֵן לָזֶה מַתָּנָה עַל מְנָת לְהַקְנוֹתָהּ לְאַחֵר הֲרֵי זֶה הָאַחֵר קָנָה בְּעֵת שֶׁיַּקְנֶה לוֹ הָרִאשׁוֹן. וְאִם לֹא הִקְנָה לוֹ הָרִאשׁוֹן לְאוֹתוֹ אַחֵר לֹא קָנָה לֹא הָרִאשׁוֹן וְלֹא הַשֵּׁנִי:","מִי שֶׁנֶּאֶסְרָה הֲנָיָתוֹ עַל בַּעַל בִּתּוֹ וְהוּא רוֹצֶה לָתֵת לְבִתּוֹ מָעוֹת כְּדֵי שֶׁתִּהְיֶה נֶהֱנֵית בָּהֶן וּמוֹצִיאָה אוֹתָן בַּחֲפָצֶיהָ. הֲרֵי זֶה נוֹתֵן לָהּ וְאוֹמֵר לָהּ הֲרֵי הַמָּעוֹת הָאֵלּוּ נְתוּנִין לָךְ בְּמַתָּנָה וּבִלְבַד שֶׁלֹּא יְהֵא לְבַעֲלִיךְ רְשׁוּת בָּהֶן אֶלָּא יִהְיוּ לְמַה שֶּׁאַתְּ נוֹתֶנֶת לְפִיךְ אוֹ לְמַה שֶּׁתִּלְבְּשִׁי וְכַיּוֹצֵא בָּזֶה. וַאֲפִלּוּ אָמַר לָהּ עַל מְנָת שֶׁאֵין לְבַעֲלִיךְ רְשׁוּת בָּהֶן אֶלָּא מַה שֶּׁתִּרְצִי עֲשִׂי בָּהֶן לֹא קָנָה הַבַּעַל וּמַה שֶּׁתִּרְצֶה תַּעֲשֶׂה בָּהֶן. אֲבָל אִם נָתַן לָהּ מַתָּנָה וְאָמַר לָהּ עַל מְנָת שֶׁאֵין לְבַעֲלִיךְ רְשׁוּת בָּהֶן וְלֹא פֵּרֵשׁ שֶׁתִּהְיֶה הַמַּתָּנָה הַזֹּאת לְכָךְ וּלְכָךְ אוֹ לְמַה שֶּׁתִּרְצֶה תַּעֲשֶׂה בָּהֶן הֲרֵי קָנָה אוֹתָהּ הַבַּעַל לֶאֱכל פֵּרוֹתֶיהָ. וְדָבָר זֶה אָסוּר שֶׁהֲרֵי הוּא אָסוּר בַּהֲנָיַת חוֹתְנוֹ:"]} as Record<string, string[]>;
